INSERT INTO "course_content" VALUES (377, 5, '{"english": "This is for Sarah. She is my classmate.", "chinese": "这是给萨拉的。她是我的同学。"}', 79, '2026-02-05 03:55:19', '2026-02-05 03:55:19');
