INSERT INTO "course_content" VALUES (379, 6, '{"english": "Revision  A robot show", "chinese": "复习单元 一场机器人展览"}', 1, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (380, 6, '{"english": "Listen and read aloud.", "chinese": "听一听，大声读。"}', 2, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (381, 6, '{"english": "Let''s meet at the robot show.", "chinese": "我们在机器人展览上集合吧。"}', 3, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (382, 6, '{"english": "OK.", "chinese": "好的。"}', 4, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (383, 6, '{"english": "This is my bottle. This is my cap. I''m ready!", "chinese": "这是我的水瓶。这是我的帽子。我准备好了！"}', 5, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (384, 6, '{"english": "Great! Let''s go, Sarah.", "chinese": "太好了！我们走吧，萨拉。"}', 6, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (385, 6, '{"english": "Hi, Sarah!", "chinese": "你好，萨拉！"}', 7, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (386, 6, '{"english": "Hello!", "chinese": "你好！"}', 8, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (387, 6, '{"english": "Who''s he?", "chinese": "他是谁？"}', 9, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (388, 6, '{"english": "He''s my classmate, Binbin.", "chinese": "他是我的同学，斌斌。"}', 10, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (389, 6, '{"english": "Good morning! I''m Congcong.", "chinese": "早上好！我是聪聪。"}', 11, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (390, 6, '{"english": "Good morning, Congcong.", "chinese": "早上好，聪聪。"}', 12, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (391, 6, '{"english": "Let''s play. You say. I do.", "chinese": "我们一起玩吧。你们来说。我来做。"}', 13, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (392, 6, '{"english": "Cool!", "chinese": "酷！"}', 14, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (393, 6, '{"english": "Let''s try.", "chinese": "我们试一试吧。"}', 15, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (394, 6, '{"english": "Listen and tick.", "chinese": "听一听，勾一勾。"}', 16, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (395, 6, '{"english": "—Congcong, show me a cap, please.", "chinese": "——聪聪，请向我展示一顶帽子。"}', 17, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (396, 6, '{"english": "—Open my bag, please.", "chinese": "——请打开我的书包。"}', 18, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (397, 6, '{"english": "—Congcong, read this book, please.", "chinese": "——聪聪，请读这本书。"}', 19, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (398, 6, '{"english": "Listen and do.", "chinese": "听一听，做一做。"}', 20, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (399, 6, '{"english": "This is my book. Show me your book, please.", "chinese": "这是我的书。请向我展示你的书。"}', 21, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (400, 6, '{"english": "This is my bag. Show me your bag, please.", "chinese": "这是我的书包。请向我展示你的书包。"}', 22, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (401, 6, '{"english": "This is my bottle. Show me your bottle, please.", "chinese": "这是我的水瓶。请向我展示你的水瓶。"}', 23, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
