INSERT INTO "course_content" VALUES (410, 6, '{"english": "brother", "chinese": "哥；弟"}', 32, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (411, 6, '{"english": "sister", "chinese": "姐；妹"}', 33, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
INSERT INTO "course_content" VALUES (412, 6, '{"english": "mum", "chinese": "妈妈"}', 34, '2026-02-05 03:55:20', '2026-02-05 03:55:20');
