INSERT INTO "course_content" VALUES (878, 15, '{"english": "Yes, I can. Can you swim?", "chinese": "是的，我会。你会游泳吗？"}', 40, '2026-02-05 03:55:42', '2026-02-05 03:55:42');
INSERT INTO "course_content" VALUES (879, 15, '{"english": "No, I can''t.", "chinese": "不，我不会。"}', 41, '2026-02-05 03:55:42', '2026-02-05 03:55:42');
