INSERT INTO "course_content" VALUES (884, 15, '{"english": "Can you run?", "chinese": "你能跑吗？"}', 46, '2026-02-05 03:55:42', '2026-02-05 03:55:42');
INSERT INTO "course_content" VALUES (885, 15, '{"english": "No, I can''t. But I can fly.", "chinese": "不，我不能。但我能飞。"}', 47, '2026-02-05 03:55:42', '2026-02-05 03:55:42');
