INSERT INTO "course_content" VALUES (895, 15, '{"english": "I''m big. I can run fast.", "chinese": "我很大。我能跑得很快。"}', 57, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (896, 15, '{"english": "I''m small. I can swim well.", "chinese": "我个子小。我游泳游得很好。"}', 58, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (897, 15, '{"english": "My bird is small. It can fly. It can sing.", "chinese": "我的鸟很小。它能飞。它会唱歌。"}', 59, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
