INSERT INTO "course_content" VALUES (899, 15, '{"english": "Can you swim?", "chinese": "你会游泳吗？"}', 61, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (900, 15, '{"english": "No, I can''t. Can you swim?", "chinese": "不，我不会。你会游泳吗？"}', 62, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (901, 15, '{"english": "Yes, I can.", "chinese": "是的，我会。"}', 63, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
