INSERT INTO "course_content" VALUES (903, 15, '{"english": "We are special!", "chinese": "我们很特别！"}', 65, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (904, 15, '{"english": "My bird is small. It can fly. It can sing.", "chinese": "我的鸟很小。它能飞。它会唱歌。"}', 66, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
