INSERT INTO "course_content" VALUES (909, 15, '{"english": "But I can run very fast!", "chinese": "但我跑得很快！"}', 71, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
INSERT INTO "course_content" VALUES (910, 15, '{"english": "I''m small. I can''t talk. I can''t read.", "chinese": "我个子小。我不会说话。我不识字。"}', 72, '2026-02-05 03:55:43', '2026-02-05 03:55:43');
