INSERT INTO "course_content" VALUES (1066, 21, '{"english": "How can we make numbers and letters fun?", "chinese": "我们如何让数字和字母变有趣？"}', 2, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1067, 21, '{"english": "Listen and chant.", "chinese": "听一听，唱一唱。"}', 3, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1068, 21, '{"english": "1, and 2, 3 and 4,  5, 5, 5!", "chinese": "1 和 2，3 和 4， 5，5，5！"}', 4, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1069, 21, '{"english": "6, and 7, 8 and 9,  10, 10, 10!", "chinese": "6 和 7，8 和 9， 10，10，10！"}', 5, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1070, 21, '{"english": "Listen and sing.", "chinese": "听一听，唱一唱。"}', 6, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1071, 21, '{"english": "Let''s count!   1, 2, 3, 4, 5.", "chinese": "一起数数！  1，2，3，4，5."}', 7, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1072, 21, '{"english": "I can count up to 5.", "chinese": "我可以数到 5。"}', 8, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
