INSERT INTO "course_content" VALUES (1074, 21, '{"english": "Let''s count up to 10 again.", "chinese": "让我们再数到 10。"}', 10, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1075, 21, '{"english": "I see a lot of fruit.", "chinese": "我看到了很多水果。"}', 11, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1076, 21, '{"english": "Apples, oranges and bananas too.  Books, bags, pencils, pens.", "chinese": "还有苹果，橘子和香蕉。 书，书包，铅笔，钢笔。"}', 12, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1077, 21, '{"english": "I see 1 to 10.", "chinese": "我看到了 1 到 10。"}', 13, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1078, 21, '{"english": "1, 2, 3, 4, 5.", "chinese": "1，2，3，4，5."}', 14, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1079, 21, '{"english": "I can count up to 5.", "chinese": "我可以数到 5。"}', 15, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1080, 21, '{"english": "6, 7, 8, 9, 10.", "chinese": "6，7，8，9，10。"}', 16, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1081, 21, '{"english": "Let''s count up to 10 again.", "chinese": "让我们再数到 10。"}', 17, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
