INSERT INTO "course_content" VALUES (1083, 21, '{"english": "Apples, oranges and bananas too.  Books, bags, pencils, pens.", "chinese": "还有苹果，橘子和香蕉。 书，书包，铅笔，钢笔。"}', 19, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
INSERT INTO "course_content" VALUES (1084, 21, '{"english": "I see 1 to 10.", "chinese": "我看到了 1 到 10。"}', 20, '2026-02-05 03:55:53', '2026-02-05 03:55:53');
