INSERT INTO "course_content" VALUES (1399, 26, '{"english": "OK!", "chinese": "好！"}', 6, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1400, 26, '{"english": "I see ''A''.", "chinese": "我看到了“A”。"}', 7, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1401, 26, '{"english": "Here it is!", "chinese": "就是这个！"}', 8, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1402, 26, '{"english": "One, two, three, four, five, six, seven, eight, nine, ten!", "chinese": "一、二、三、四、五、六、七、八、九、十！"}', 9, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1403, 26, '{"english": "Look at me. One, ...", "chinese": "看我。一,⋯⋯"}', 10, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1404, 26, '{"english": "Let''s draw some pictures.", "chinese": "我们一起画画吧。"}', 11, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1405, 26, '{"english": "OK!", "chinese": "好！"}', 12, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1406, 26, '{"english": "Look at my car. It''s yellow.", "chinese": "看我的小汽车。它是黄色的"}', 13, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1407, 26, '{"english": "It''s nice. My boat is green.", "chinese": "它很好看。我的小船是绿色的。"}', 14, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1408, 26, '{"english": "Oh no! Look at the room.", "chinese": "哦不！看看房间。"}', 15, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1409, 26, '{"english": "I can clean the floor.", "chinese": "我可以扫地。"}', 16, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1410, 26, '{"english": "I''m tired.", "chinese": "我很疲劳。"}', 17, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1411, 26, '{"english": "Me too. But I''m happy.", "chinese": "我也是。但是我很高兴。"}', 18, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1412, 26, '{"english": "I''m hungry now!", "chinese": "我现在很饿！"}', 19, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1413, 26, '{"english": "Aha! Now let''s eat.", "chinese": "啊哈！现在我们一起吃吧。"}', 20, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1414, 26, '{"english": "Look and colour.", "chinese": "看一看并涂色。"}', 21, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1415, 26, '{"english": "Look and match.", "chinese": "看一看并连线。"}', 22, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1416, 26, '{"english": "Listen and choose.", "chinese": "听一听，选一选。"}', 23, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1417, 26, '{"english": "1. I have a blue and yellow ball.", "chinese": "1. 我有一个蓝黄相间的球。"}', 24, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1418, 26, '{"english": "2. John is very sad.", "chinese": "2. 约翰非常难过。"}', 25, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1419, 26, '{"english": "3. I have three rabbits.", "chinese": "3. 我有三只兔子。"}', 26, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1420, 26, '{"english": "Look, tick or cross and say.", "chinese": "看一看，打勾或画叉并说一说。"}', 27, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1421, 26, '{"english": "A white apple? No. I like red apples.", "chinese": "一个白色的苹果？不。我喜欢红色的苹果。"}', 28, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
INSERT INTO "course_content" VALUES (1422, 26, '{"english": "Look, cross the odd out and say.", "chinese": "看一看，将不一样的画叉并说一说。"}', 29, '2026-02-05 03:56:03', '2026-02-05 03:56:03');
