INSERT INTO "course_content" VALUES (1443, 26, '{"english": "Happy, angry, sad, tired, two. I put away two.", "chinese": "高兴的，生气的，难过的，疲劳的，二。我收起了二。"}', 50, '2026-02-05 03:56:04', '2026-02-05 03:56:04');
