INSERT INTO "course_content" VALUES (1469, 27, '{"english": "Let''s count!   1, 2, 3, 4, 5.", "chinese": "一起数数！  1，2，3，4，5."}', 4, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1470, 27, '{"english": "I can count up to 5.", "chinese": "我可以数到 5。"}', 5, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1471, 27, '{"english": "6, 7, 8, 9, 10.", "chinese": "6，7，8，9，10。"}', 6, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1472, 27, '{"english": "Let''s count up to 10 again.", "chinese": "让我们再数到 10。"}', 7, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1473, 27, '{"english": "I see a lot of fruit.", "chinese": "我看到了很多水果。"}', 8, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1474, 27, '{"english": "Apples, oranges and bananas too.  Books, bags, pencils, pens.", "chinese": "还有苹果，橘子和香蕉。 书，书包，铅笔，钢笔。"}', 9, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1475, 27, '{"english": "I see 1 to 10.", "chinese": "我看到了 1 到 10。"}', 10, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1476, 27, '{"english": "1, 2, 3, 4, 5.", "chinese": "1，2，3，4，5."}', 11, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1477, 27, '{"english": "I can count up to 5.", "chinese": "我可以数到 5。"}', 12, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1478, 27, '{"english": "6, 7, 8, 9, 10.", "chinese": "6，7，8，9，10。"}', 13, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1479, 27, '{"english": "Let''s count up to 10 again.", "chinese": "让我们再数到 10。"}', 14, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1480, 27, '{"english": "I see a lot of fruit.", "chinese": "我看到了很多水果。"}', 15, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1481, 27, '{"english": "Apples, oranges and bananas too.  Books, bags, pencils, pens.", "chinese": "还有苹果，橘子和香蕉。 书，书包，铅笔，钢笔。"}', 16, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1482, 27, '{"english": "I see 1 to 10.", "chinese": "我看到了 1 到 10。"}', 17, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1483, 27, '{"english": "Unit 2", "chinese": "第 2 单元"}', 18, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1484, 27, '{"english": "Roses are red!   Roses are red.", "chinese": "玫瑰是红色的！  玫瑰是红色的。"}', 19, '2026-02-05 03:56:05', '2026-02-05 03:56:05');
INSERT INTO "course_content" VALUES (1485, 27, '{"english": "Yes! Yes!  Trees are green.", "chinese": "是的！是的！ 树是绿色的。"}', 20, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1486, 27, '{"english": "My apple is red.  Your apple is green.", "chinese": "我的苹果是红色的。 你的苹果是绿色的。"}', 21, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1487, 27, '{"english": "The sun is yellow.  Yes! Yes!  The sea is blue.", "chinese": "太阳是黄色的。 是的！是的！ 大海是蓝色的。"}', 22, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1488, 27, '{"english": "My flower is yellow.  Your flower is blue.", "chinese": "我的花是黄色的。 你的花是蓝色的。"}', 23, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1489, 27, '{"english": "Roses are red.  Yes! Yes!  Trees are green.", "chinese": "玫瑰是红色的。 是的！是的！ 树是绿色的。"}', 24, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1490, 27, '{"english": "My apple is red.  Your apple is green.", "chinese": "我的苹果是红色的。 你的苹果是绿色的。"}', 25, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1491, 27, '{"english": "The sun is yellow.  Yes! Yes!  The sea is blue.", "chinese": "太阳是黄色的。 是的！是的！ 大海是蓝色的。"}', 26, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1492, 27, '{"english": "My flower is yellow.  Your flower is blue.", "chinese": "我的花是黄色的。 你的花是蓝色的。"}', 27, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1493, 27, '{"english": "Unit 3", "chinese": "第 3 单元"}', 28, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1494, 27, '{"english": "I can help!   I am big.", "chinese": "我可以帮忙！  我长大了。"}', 29, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1495, 27, '{"english": "And I can feed the dog.", "chinese": "而且我可以喂狗。"}', 30, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1496, 27, '{"english": "I can help.  Now I can help a lot.", "chinese": "我可以帮忙。 现在我可以帮很多忙。"}', 31, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1497, 27, '{"english": "My mum and dad are so happy.", "chinese": "我的妈妈和爸爸很高兴。"}', 32, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1498, 27, '{"english": "I can help them every day.", "chinese": "我可以每天帮助他们。"}', 33, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1499, 27, '{"english": "I clean the table and floor before I play!", "chinese": "我玩之前先擦桌子和扫地！"}', 34, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1500, 27, '{"english": "I am big.  And I can feed the dog.", "chinese": "我长大了。 而且我可以喂狗。"}', 35, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1501, 27, '{"english": "I can help.  Now I can help a lot.", "chinese": "我可以帮忙。 现在我可以帮很多忙。"}', 36, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1502, 27, '{"english": "My mum and dad are so happy.", "chinese": "我的妈妈和爸爸很高兴。"}', 37, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1503, 27, '{"english": "I can help them every day.", "chinese": "我可以每天帮助他们。"}', 38, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
INSERT INTO "course_content" VALUES (1504, 27, '{"english": "I clean the table and floor before I play!", "chinese": "我玩之前先擦桌子和扫地！"}', 39, '2026-02-05 03:56:06', '2026-02-05 03:56:06');
