INSERT INTO "course_content" VALUES (1735, 33, '{"english": "Can you bounce the yellow ball?", "chinese": "你能拍黄色的球吗？"}', 12, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1736, 33, '{"english": "Can you bounce the yellow ball?", "chinese": "你能拍黄色的球吗？"}', 13, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1737, 33, '{"english": "The yellow ball?", "chinese": "黄色的球？"}', 14, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1738, 33, '{"english": "The yellow ball!", "chinese": "黄色的球！"}', 15, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1739, 33, '{"english": "I can bounce the yellow ball.", "chinese": "我能拍黄色的球。"}', 16, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1740, 33, '{"english": "Yes, I can!", "chinese": "是的，我能。"}', 17, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1741, 33, '{"english": "Can you run or do sit-ups?", "chinese": "你能跑步或做仰卧起坐吗？"}', 18, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
