INSERT INTO "course_content" VALUES (1753, 33, '{"english": "Li Dong: Yes, I can.", "chinese": "李东：是的，我会。"}', 30, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1754, 33, '{"english": "Mr Yu: Can you jump rope?", "chinese": "余老师：你会跳绳吗？"}', 31, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1755, 33, '{"english": "Chen Jie: Yes, I can.", "chinese": "陈杰：是的，我会。"}', 32, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1756, 33, '{"english": "Mr Yu: Can you do sit-ups?", "chinese": "余老师：你会做仰卧起坐吗？"}', 33, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
