INSERT INTO "course_content" VALUES (1759, 33, '{"english": "Can you do sit-ups?", "chinese": "你能做仰卧起坐吗？"}', 36, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
INSERT INTO "course_content" VALUES (1760, 33, '{"english": "No. But I can try.", "chinese": "不能。但我想试试。"}', 37, '2026-02-05 03:56:17', '2026-02-05 03:56:17');
