INSERT INTO "course_content" VALUES (2050, 37, '{"english": "Please don''t jump or shout.", "chinese": "请不要蹦跳或大喊大叫。"}', 36, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2051, 37, '{"english": "You''re in the playground.", "chinese": "你在操场上。"}', 37, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2052, 37, '{"english": "You have some fun.", "chinese": "你玩得很开心。"}', 38, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2053, 37, '{"english": "Please jump and run about!", "chinese": "请跳跃并四处奔跑！"}', 39, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2054, 37, '{"english": "Unit 3", "chinese": "第三单元"}', 40, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2055, 37, '{"english": "Can you bounce the yellow ball?", "chinese": "你能拍黄色的球吗？"}', 41, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2056, 37, '{"english": "Can you bounce the yellow ball?  The yellow ball?", "chinese": "你能拍黄色的球吗？ 黄色的球？"}', 42, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2057, 37, '{"english": "The yellow ball!  I can bounce the yellow ball.  Yes, I can!", "chinese": "黄色的球！ 我能拍黄色的球。 是的，我能。"}', 43, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2058, 37, '{"english": "Can you run or do sit-ups?  Do sit-ups?  Do sit-ups!", "chinese": "你能跑步或做仰卧起坐吗？ 做仰卧起坐？ 做仰卧起坐！"}', 44, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2059, 37, '{"english": "I can run but can''t do sit-ups.  No, I can''t!", "chinese": "我能跑，但不能做仰卧起坐。 不，我不能。"}', 45, '2026-02-05 03:56:27', '2026-02-05 03:56:27');
INSERT INTO "course_content" VALUES (2060, 38, '{"english": "Listening scripts for ''Listen, point and repeat. ''", "chinese": "词汇学习板块听力文本"}', 1, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2061, 38, '{"english": "Unit 1", "chinese": "第一单元"}', 2, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2062, 38, '{"english": "I have a coat.", "chinese": "我有一件外套。"}', 3, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2063, 38, '{"english": "I have a sweater.", "chinese": "我有一件毛衣。"}', 4, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2064, 38, '{"english": "I have a T-shirt and a skirt.", "chinese": "我有一件T恤和一条裙子。"}', 5, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2065, 38, '{"english": "Unit 2", "chinese": "第二单元"}', 6, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2066, 38, '{"english": "Let''s play. I push.", "chinese": "我们来玩吧。我推。"}', 7, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2067, 38, '{"english": "I climb.", "chinese": "我爬。"}', 8, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2068, 38, '{"english": "We jump.", "chinese": "我们跳。"}', 9, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2069, 38, '{"english": "We shout.", "chinese": "我们喊。"}', 10, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2070, 38, '{"english": "Unit 3", "chinese": "第三单元"}', 11, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2071, 38, '{"english": "Can you bounce a ball?", "chinese": "你能拍球吗？"}', 12, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2072, 38, '{"english": "Yes, I can.", "chinese": "是的，我能。"}', 13, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2073, 38, '{"english": "Can you jump rope?", "chinese": "你会跳绳吗？"}', 14, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2074, 38, '{"english": "Yes, I can.", "chinese": "是的，我会。"}', 15, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2075, 38, '{"english": "Can you do sit-ups?", "chinese": "你能做仰卧起坐吗？"}', 16, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
INSERT INTO "course_content" VALUES (2076, 38, '{"english": "No. But I can try.", "chinese": "不能。但我想试试。"}', 17, '2026-02-05 03:56:28', '2026-02-05 03:56:28');
