INSERT INTO "course_content" VALUES (2094, 40, '{"english": "Useful expressions", "chinese": "常用表达法"}', 1, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2095, 40, '{"english": "Unit 1", "chinese": "第一单元"}', 2, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2096, 40, '{"english": "It''s cold. I put on my coat.", "chinese": "天冷。我穿上外套。"}', 3, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2097, 40, '{"english": "It''s hot. I take off my coat.", "chinese": "天热。我脱下外套。"}', 4, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2098, 40, '{"english": "Unit 2", "chinese": "第二单元"}', 5, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2099, 40, '{"english": "Don''t climb, John.", "chinese": "约翰, 别爬。"}', 6, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2100, 40, '{"english": "Don''t push, Sam.", "chinese": "萨姆, 别推。"}', 7, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2101, 40, '{"english": "Unit 3", "chinese": "第三单元"}', 8, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2102, 40, '{"english": "Can you do sit-ups?", "chinese": "你能做仰卧起坐吗?"}', 9, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2103, 40, '{"english": "No. But I can try.", "chinese": "不能。但我想试试。"}', 10, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2104, 40, '{"english": "How many, Mum?", "chinese": "妈妈, 我做了多少个?"}', 11, '2026-02-05 03:56:30', '2026-02-05 03:56:30');
INSERT INTO "course_content" VALUES (2105, 41, '{"english": "Unit One Welcome back to school!", "chinese": "第一单元 欢迎回到学校！"}', 1, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2106, 41, '{"english": "Welcome!", "chinese": "欢迎！"}', 2, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2107, 41, '{"english": "Welcome!", "chinese": "欢迎！"}', 3, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2108, 41, '{"english": "Wu Binbin, this is Amy.", "chinese": "吴斌斌，这是艾米。"}', 4, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2109, 41, '{"english": "Hi! Nice to meet you.", "chinese": "你好！很高兴见到你。"}', 5, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2110, 41, '{"english": "Where are you from?", "chinese": "你是哪里人？"}', 6, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2111, 41, '{"english": "I''m from the UK.", "chinese": "我是英国人。"}', 7, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2112, 41, '{"english": "Welcome back!", "chinese": "欢迎回校！"}', 8, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2113, 41, '{"english": "Nice to see you again.", "chinese": "很高兴再次见到你们。"}', 9, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2114, 41, '{"english": "Nice to see you, too.", "chinese": "也很高兴见到您。"}', 10, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2115, 41, '{"english": "USA", "chinese": "美国"}', 11, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2116, 41, '{"english": "China", "chinese": "中国"}', 12, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2117, 41, '{"english": "Let''s chant", "chinese": "我们来说唱"}', 13, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2118, 41, '{"english": "We are friends. We like to play.", "chinese": "我们是朋友。我们喜欢玩耍。"}', 14, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2119, 41, '{"english": "We are friends. We like to play.", "chinese": "我们是朋友。我们喜欢玩耍。"}', 15, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2120, 41, '{"english": "A boy from Canada, A girl from the UK,", "chinese": "一个来自加拿大的男孩，一个来自英国的女孩，"}', 16, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2121, 41, '{"english": "Friends from China and the USA.", "chinese": "一群来自中国和美国的朋友。"}', 17, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2122, 41, '{"english": "Listen, repeat and chant.", "chinese": "听一听，跟读并说唱。"}', 18, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2123, 41, '{"english": "cat", "chinese": "猫"}', 19, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2124, 41, '{"english": "bag", "chinese": "包"}', 20, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2125, 41, '{"english": "dad", "chinese": "爸爸"}', 21, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2126, 41, '{"english": "hand", "chinese": "手"}', 22, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2127, 41, '{"english": "I am a boy and you are a girl.", "chinese": "我是男孩，你是女孩。"}', 23, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2128, 41, '{"english": "I am a boy and you are a girl.", "chinese": "我是男孩，你是女孩。"}', 24, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2129, 41, '{"english": "I am a boy and you are a girl.", "chinese": "我是男孩，你是女孩。"}', 25, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2130, 41, '{"english": "Do you want to be my friend?", "chinese": "你想和我做朋友吗？"}', 26, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2131, 41, '{"english": "I am a girl and you are a boy.", "chinese": "我是女孩，你是男孩。"}', 27, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2132, 41, '{"english": "I am a girl and you are a boy.", "chinese": "我是女孩，你是男孩。"}', 28, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2133, 41, '{"english": "I am a girl and you are a boy.", "chinese": "我是女孩，你是男孩。"}', 29, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2134, 41, '{"english": "Yes,I want to be your friend.", "chinese": "是的，我想成为你的朋友。"}', 30, '2026-02-05 03:56:33', '2026-02-05 03:56:33');
INSERT INTO "course_content" VALUES (2135, 42, '{"english": "Unit Two My family", "chinese": "第二单元 我的家庭"}', 1, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2136, 42, '{"english": "Who''s that man?", "chinese": "那位男士是谁？"}', 2, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2137, 42, '{"english": "He''s Sarah''s grandpa.", "chinese": "他是萨拉的爷爷。"}', 3, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2138, 42, '{"english": "Who''s that woman?", "chinese": "那位女士是谁呀？"}', 4, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2139, 42, '{"english": "She''s my mother.", "chinese": "她是我妈妈。"}', 5, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2140, 42, '{"english": "Who''s that man?", "chinese": "那位男士是谁呀？"}', 6, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2141, 42, '{"english": "Sarah''s grandfather.", "chinese": "萨拉的祖父。"}', 7, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2142, 42, '{"english": "Who''s that woman?", "chinese": "那位女士是谁呀？"}', 8, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2143, 42, '{"english": "She''s my mother.", "chinese": "她是我妈妈。"}', 9, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2144, 42, '{"english": "father (dad) man", "chinese": "爸爸"}', 10, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2145, 42, '{"english": "woman mother (mum)", "chinese": "妈妈"}', 11, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2146, 42, '{"english": "Let''s chant.", "chinese": "我们来说唱"}', 12, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2147, 42, '{"english": "The man is the father - tall, tall, tall!", "chinese": "这个男人是爸爸。——高，高，高!"}', 13, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2148, 42, '{"english": "The woman is the mother - not so tall.", "chinese": "这个女人是妈妈——不是特别高。"}', 14, '2026-02-05 03:56:35', '2026-02-05 03:56:35');
INSERT INTO "course_content" VALUES (2149, 42, '{"english": "That''s the son - small, small, small.", "chinese": "那是他们的儿子——小，小，小。"}', 15, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2150, 42, '{"english": "They are a falmily, one and all.", "chinese": "他们所有人组成了一个家庭。"}', 16, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2151, 42, '{"english": "Listen, repeat and chant.", "chinese": "听一听，跟读并说唱。"}', 17, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2152, 42, '{"english": "ten", "chinese": "十"}', 18, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2153, 42, '{"english": "pen", "chinese": "钢笔"}', 19, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2154, 42, '{"english": "leg", "chinese": "腿"}', 20, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2155, 42, '{"english": "red", "chinese": "红色"}', 21, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2156, 42, '{"english": "Sister, brother:", "chinese": "姐妹，兄弟："}', 22, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2157, 42, '{"english": "All my family Help each other.", "chinese": "我所有的家人都互帮互助。"}', 23, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2158, 42, '{"english": "Let''s sing", "chinese": "我们来唱一唱"}', 24, '2026-02-05 03:56:36', '2026-02-05 03:56:36');
INSERT INTO "course_content" VALUES (2159, 42, '{"english": "I love my family", "chinese": "我爱我家"}', 25, '2026-02-05 03:56:37', '2026-02-05 03:56:37');
