INSERT INTO "course_content" VALUES (2168, 43, '{"english": "Unit Three At the zoo", "chinese": "第三单元 在动物园"}', 1, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2169, 43, '{"english": "Look at me!", "chinese": "看看我！"}', 2, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2170, 43, '{"english": "Ah! So cute!", "chinese": "啊！真可爱！"}', 3, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2171, 43, '{"english": "Look at the elephant.", "chinese": "看看那只大象。"}', 4, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2172, 43, '{"english": "It has a long nose.", "chinese": "它有长鼻子。"}', 5, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2173, 43, '{"english": "Look at that monkey. It''s so fat!", "chinese": "看看那只猴子。它好胖啊！"}', 6, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2174, 43, '{"english": "Look at the giraffe.", "chinese": "看看那只长颈鹿。"}', 7, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2175, 43, '{"english": "It''s so tall!", "chinese": "它好高啊！"}', 8, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2176, 43, '{"english": "fat", "chinese": "胖的"}', 9, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2177, 43, '{"english": "tall", "chinese": "高的"}', 10, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2178, 43, '{"english": "short", "chinese": "矮的"}', 11, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2179, 43, '{"english": "Let''s do", "chinese": "我们来做一做"}', 12, '2026-02-05 03:56:39', '2026-02-05 03:56:39');
INSERT INTO "course_content" VALUES (2180, 43, '{"english": "Be fat. Be fat. Be fat, fat, fat!", "chinese": "变胖。变胖。变胖，胖，胖！"}', 13, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2181, 43, '{"english": "Be thin. Be thin. Be thin, thin, thin!", "chinese": "变瘦。变瘦。变瘦，瘦，瘦！"}', 14, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2182, 43, '{"english": "Be tall. Be tall. Be tall, tall, tall!", "chinese": "变高。变高。变高，高，高！"}', 15, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2183, 43, '{"english": "Be short. Be short. Be short, short, short!", "chinese": "变矮。变矮。变矮，矮，矮！"}', 16, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2184, 43, '{"english": "Listen, repeat and chant.", "chinese": "听一听，跟读并说唱。"}', 17, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
