INSERT INTO "course_content" VALUES (2188, 43, '{"english": "milk", "chinese": "牛奶"}', 21, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2189, 43, '{"english": "Monkey is short. Giraffe is tall.", "chinese": "猴子长得矮。长劲鹿长得高。"}', 22, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2190, 43, '{"english": "See them play with the ball.", "chinese": "看他们在玩球！"}', 23, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2191, 43, '{"english": "Cat is fast. Rat is fat.", "chinese": "猫跑得快。老鼠长得肥。"}', 24, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2192, 43, '{"english": "See them run. Fun! Fun! Fun!", "chinese": "看它们在跑。好玩！好玩！好玩！"}', 25, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2193, 43, '{"english": "Monkey is short. Giraffe is tall.", "chinese": "猴子长得矮。长劲鹿长得高。"}', 26, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2194, 43, '{"english": "See them play with the ball.", "chinese": "看他们在玩球！"}', 27, '2026-02-05 03:56:40', '2026-02-05 03:56:40');
INSERT INTO "course_content" VALUES (2195, 44, '{"english": "Unit Four Where is my car?", "chinese": "第四单元 我的小汽车在哪儿？"}', 1, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2196, 44, '{"english": "Where is Zip?", "chinese": "兹普在哪儿？"}', 2, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2197, 44, '{"english": "Where is my car?", "chinese": "我的小汽车在哪儿？"}', 3, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2198, 44, '{"english": "Is it in the desk?", "chinese": "在桌子里吗？"}', 4, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2199, 44, '{"english": "No.", "chinese": "不在。"}', 5, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2200, 44, '{"english": "Where is my map?", "chinese": "我的帽子在哪儿？"}', 6, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2201, 44, '{"english": "Is it on the desk?", "chinese": "在桌子上吗？"}', 7, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2202, 44, '{"english": "Good guess!", "chinese": "猜得好！"}', 8, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
INSERT INTO "course_content" VALUES (2203, 44, '{"english": "It''s under your book!", "chinese": "在你书下面！"}', 9, '2026-02-05 03:56:41', '2026-02-05 03:56:41');
