INSERT INTO "course_content" VALUES (2223, 44, '{"english": "Oh, it''s on your chair!", "chinese": "喔！在你的椅子上！"}', 29, '2026-02-05 03:56:42', '2026-02-05 03:56:42');
INSERT INTO "course_content" VALUES (2224, 44, '{"english": "Where is the toy boat?", "chinese": "玩具汽车在哪里？"}', 30, '2026-02-05 03:56:42', '2026-02-05 03:56:42');
