INSERT INTO "course_content" VALUES (2241, 45, '{"english": "Let''s chant.", "chinese": "我们来说唱"}', 14, '2026-02-05 03:56:43', '2026-02-05 03:56:43');
INSERT INTO "course_content" VALUES (2242, 45, '{"english": "Do you like oranges? No, but I should.", "chinese": "你喜欢橘子吗？不喜欢，但我本应该喜欢吃。"}', 15, '2026-02-05 03:56:43', '2026-02-05 03:56:43');
