INSERT INTO "course_content" VALUES (2248, 46, '{"english": "How many birds do you see?", "chinese": "你看见了多少只鸟？"}', 2, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2249, 46, '{"english": "I see 13!", "chinese": "我看见了十三只！"}', 3, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2250, 46, '{"english": "How many crayons do you have?", "chinese": "你有多少支蜡笔？"}', 4, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2251, 46, '{"english": "I have 16.", "chinese": "我有十六支。"}', 5, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2252, 46, '{"english": "No! The black one is a bird! Oh!", "chinese": "不！黑色的那个是只鸟！哦！"}', 6, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2253, 46, '{"english": "Let''s learn", "chinese": "我们来学一学"}', 7, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
