INSERT INTO "course_content" VALUES (2256, 46, '{"english": "eleven", "chinese": "十一"}', 10, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2257, 46, '{"english": "twelve", "chinese": "十二"}', 11, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2258, 46, '{"english": "thirteen", "chinese": "十三"}', 12, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2259, 46, '{"english": "fourteen", "chinese": "十四"}', 13, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2260, 46, '{"english": "fifteen", "chinese": "十五"}', 14, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2261, 46, '{"english": "Let''s chant", "chinese": "我们来说唱"}', 15, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2262, 46, '{"english": "Hello, my friend. Please tell me.", "chinese": "你好，我的朋友。请告诉我。"}', 16, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2263, 46, '{"english": "How many cars do you see?", "chinese": "你看到了多少辆车？"}', 17, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2264, 46, '{"english": "One, two, three ... I see eleven.", "chinese": "一，二，三……我看到十一。"}', 18, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2265, 46, '{"english": "One, two, three ... I see eleven.", "chinese": "一，二，三……我看到十一。"}', 19, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2266, 46, '{"english": "Hello, my friend. Please tell me.", "chinese": "你好，我的朋友。请告诉我。"}', 20, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2267, 46, '{"english": "How many balls do you see?", "chinese": "你看到多少个球？"}', 21, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2268, 46, '{"english": "One, two, three, four, five", "chinese": "一，二，三，四，五"}', 22, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2269, 46, '{"english": "One, two, three, four, five.", "chinese": "一，二，三，四，五。"}', 23, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2270, 46, '{"english": "Where is short e?", "chinese": "短e在哪里？"}', 24, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2271, 46, '{"english": "Here I am. Here I am.", "chinese": "我来了。我来了。"}', 25, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2272, 46, '{"english": "I''m in a red pen.", "chinese": "我在一支红色的钢笔里。"}', 26, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2273, 46, '{"english": "I''m in a red pen.", "chinese": "我在一支红色的钢笔里。"}', 27, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2274, 46, '{"english": "Here I am. Here I am.", "chinese": "我来了。我来了。"}', 28, '2026-02-05 03:56:44', '2026-02-05 03:56:44');
INSERT INTO "course_content" VALUES (2275, 47, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:56:46', '2026-02-05 03:56:46');
