INSERT INTO "course_content" VALUES (2284, 47, '{"english": "I see a ''c''.", "chinese": "我看到一个“c”。"}', 10, '2026-02-05 03:56:46', '2026-02-05 03:56:46');
INSERT INTO "course_content" VALUES (2285, 47, '{"english": "Where is it?", "chinese": "它在哪里？"}', 11, '2026-02-05 03:56:46', '2026-02-05 03:56:46');
