INSERT INTO "course_content" VALUES (2288, 47, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 14, '2026-02-05 03:56:46', '2026-02-05 03:56:46');
INSERT INTO "course_content" VALUES (2289, 47, '{"english": "What''s in the classroom?", "chinese": "教室里有什么？"}', 15, '2026-02-05 03:56:46', '2026-02-05 03:56:46');
