INSERT INTO "course_content" VALUES (2313, 47, '{"english": "I like my name and I can make a cake.", "chinese": "我喜欢我的名字，我喜欢做蛋糕。"}', 39, '2026-02-05 03:56:47', '2026-02-05 03:56:47');
