INSERT INTO "course_content" VALUES (2327, 47, '{"english": "1. -Let''s clean the classroom, Mike.  -OK.", "chinese": "1. —我们来打扫教室吧，迈克。 —好的。"}', 53, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
