INSERT INTO "course_content" VALUES (2329, 47, '{"english": "2.This is my classroom. The walls are green.", "chinese": "2. 这是我的教室。墙是绿色的。"}', 55, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
