INSERT INTO "course_content" VALUES (2331, 47, '{"english": "3. -Where''s the fan?  -It''s near the window.", "chinese": "3. —风扇在哪里？ —在窗户旁边。"}', 57, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
