INSERT INTO "course_content" VALUES (2336, 47, '{"english": "A door, three chairs,  two desks, a blackboard,", "chinese": "一扇门，三把椅子， 两张课桌，一块黑板，"}', 62, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
INSERT INTO "course_content" VALUES (2337, 47, '{"english": "a computer, a teacher''s desk and a window.", "chinese": "一台电脑，一张讲台和一扇窗户。"}', 63, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
INSERT INTO "course_content" VALUES (2338, 47, '{"english": "Let''s sing", "chinese": "让我们唱歌吧"}', 64, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
