INSERT INTO "course_content" VALUES (2342, 47, '{"english": "What''s in your new classroom? There''s a board and a fan.", "chinese": "你的新教室里有什么？有一块黑板和一个风扇。"}', 68, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
INSERT INTO "course_content" VALUES (2343, 47, '{"english": "Can I use the computer? Of course, you can.", "chinese": "我可以用这个电脑吗？当然，你可以。"}', 69, '2026-02-05 03:56:48', '2026-02-05 03:56:48');
INSERT INTO "course_content" VALUES (2344, 48, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2345, 48, '{"english": "Hi, Chen Jie. I have a new schoolbag.", "chinese": "嗨，陈杰。我有一个新书包。"}', 2, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2346, 48, '{"english": "Really?", "chinese": "真的吗？"}', 3, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2347, 48, '{"english": "Look! It''s black and white.", "chinese": "看！它是黑白相间的。"}', 4, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2348, 48, '{"english": "Wow! It''s a panda!", "chinese": "哇！它是一只熊猫！"}', 5, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2349, 48, '{"english": "What''s in your schoolbag?", "chinese": "你的书包里有什么？"}', 6, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2350, 48, '{"english": "An English book, a maths book, three storybooks and ...", "chinese": "一本英语书、一本数学书、三本故事书和⋯⋯"}', 7, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2351, 48, '{"english": "It''s a fat panda!", "chinese": "它是一只胖胖的熊猫！"}', 8, '2026-02-05 03:56:49', '2026-02-05 03:56:49');
INSERT INTO "course_content" VALUES (2352, 48, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 9, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2353, 48, '{"english": "What''s in your hand?", "chinese": "你手里拿的是什么？"}', 10, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2354, 48, '{"english": "Guess.", "chinese": "猜猜看。"}', 11, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
