INSERT INTO "course_content" VALUES (2356, 48, '{"english": "No.", "chinese": "不是。"}', 13, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2357, 48, '{"english": "A ruler?", "chinese": "一把尺子？"}', 14, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2358, 48, '{"english": "No. It''s an eraser.", "chinese": "不。是一块橡皮擦。"}', 15, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2359, 48, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 16, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2360, 48, '{"english": "What''s in your schoolbag?", "chinese": "你的书包里有什么？"}', 17, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2361, 48, '{"english": "An English book, a Chinese book,", "chinese": "一本英语书、一本语文书、"}', 18, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2362, 48, '{"english": "a maths book and three storybooks.", "chinese": "一本数学书和三本故事书。"}', 19, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
