INSERT INTO "course_content" VALUES (2364, 48, '{"english": "maths book", "chinese": "数学书"}', 21, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2365, 48, '{"english": "English book", "chinese": "英语书"}', 22, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2366, 48, '{"english": "Chinese book", "chinese": "语文书"}', 23, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2367, 48, '{"english": "storybook", "chinese": "故事书"}', 24, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2368, 48, '{"english": "Let''s do", "chinese": "让我们做一做"}', 25, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
INSERT INTO "course_content" VALUES (2369, 48, '{"english": "Put your Chinese book in your desk.", "chinese": "把你的语文书放在你的桌子里面。"}', 26, '2026-02-05 03:56:50', '2026-02-05 03:56:50');
