INSERT INTO "course_content" VALUES (2472, 49, '{"english": "He has long hair and brown shoes. Who is he?  -His name is Tim.", "chinese": "他长着一头长发，穿着棕色的鞋子。他是谁？ —他的名字是蒂姆。"}', 59, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2473, 49, '{"english": "2. -Look at her. She has orange shoes.", "chinese": "2. —看她。她穿着橙色的鞋子。"}', 60, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2474, 49, '{"english": "Who is she?  -Her name is Ann.", "chinese": "她是谁？ —她的名字是安。"}', 61, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2475, 49, '{"english": "3. -What''s his name?  -His name is Mike. He''s very friendly.", "chinese": "3. —他叫什么名字？ —他叫迈克。他非常友好。"}', 62, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2476, 49, '{"english": "4. -My friend Bob is tall and strong.", "chinese": "4. —我的朋友鲍勃又高又强壮。"}', 63, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2477, 49, '{"english": "-Really?  -Yes, there he is. He has glasses.", "chinese": "—真的吗？ —是的，他来了。他戴着眼镜。"}', 64, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2478, 49, '{"english": "Look and match.", "chinese": "看一看，连一连。"}', 65, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
