INSERT INTO "course_content" VALUES (2488, 49, '{"english": "Friends", "chinese": "朋友"}', 75, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2489, 49, '{"english": "If your friend is tall and quiet, clap your hands.", "chinese": "如果你的朋友又高又安静，拍拍你的手。"}', 76, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
INSERT INTO "course_content" VALUES (2490, 49, '{"english": "If your friend is tall and quiet, clap your hands.", "chinese": "如果你的朋友又高又安静，拍拍你的手。"}', 77, '2026-02-05 03:56:55', '2026-02-05 03:56:55');
