INSERT INTO "course_content" VALUES (2505, 50, '{"english": "Recycle 1", "chinese": "复习 1"}', 1, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2506, 50, '{"english": "Read aloud.", "chinese": "大声朗读。"}', 2, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2507, 50, '{"english": "Let me help you.", "chinese": "让我来帮你。"}', 3, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2508, 50, '{"english": "Thanks.", "chinese": "谢谢。"}', 4, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2509, 50, '{"english": "Wow! Your bag is so heavy. What''s in it?", "chinese": "哇！你的书包太重了。里面有什么？"}', 5, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2510, 50, '{"english": "An English book, a maths book,", "chinese": "一本英语书、一本数学书、"}', 6, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2511, 50, '{"english": "a notebook and ten storybooks.", "chinese": "一本笔记本和十本故事书。"}', 7, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2512, 50, '{"english": "Ten?", "chinese": "十本？"}', 8, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2513, 50, '{"english": "Yes. They''re my friend''s storybooks.", "chinese": "是的。它们是我朋友的故事书。"}', 9, '2026-02-05 03:56:56', '2026-02-05 03:56:56');
INSERT INTO "course_content" VALUES (2514, 50, '{"english": "Who''s your friend?", "chinese": "你的朋友是谁？"}', 10, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2515, 50, '{"english": "Can you guess? She''s friendly and she speaks English well.", "chinese": "你能猜猜吗？她很友好，她英语讲得很好。"}', 11, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2516, 50, '{"english": "I know. It''s Amy!", "chinese": "我知道。是艾米！"}', 12, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2517, 50, '{"english": "No. She''s tall. She has short hair and big eyes.", "chinese": "不。她很高。她留着短发，有一双大眼睛。"}', 13, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2518, 50, '{"english": "I don''t know. What''s her name?", "chinese": "我不知道。她叫什么名字？"}', 14, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2519, 50, '{"english": "Sandy White, our English teacher.", "chinese": "桑迪·怀特，我们的英语老师。"}', 15, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2520, 50, '{"english": "Ah!", "chinese": "啊！"}', 16, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2521, 50, '{"english": "Can you act it out?", "chinese": "你能表演出来吗？"}', 17, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2522, 50, '{"english": "Connect and say.", "chinese": "连一连，说一说。"}', 18, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
