INSERT INTO "course_content" VALUES (2549, 50, '{"english": "1. Kate likes to make rice cakes.", "chinese": "1. 凯特喜欢做米糕。"}', 45, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2550, 50, '{"english": "2. Five mice ride a nice bike.", "chinese": "2. 五只老鼠喜欢骑一辆漂亮的自行车。"}', 46, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2551, 50, '{"english": "3. Mr Jones phones me at home.", "chinese": "3. 琼斯先生在家给我打电话。"}', 47, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2552, 50, '{"english": "Look and find.", "chinese": "看一看，找一找。"}', 48, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2553, 50, '{"english": "I have a good friend. He''s quiet.", "chinese": "我有一个好朋友。他很安静。"}', 49, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2554, 50, '{"english": "He''s tall. He has glasses. Who is he?", "chinese": "他个子高。他戴眼镜。他是谁？"}', 50, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
