INSERT INTO "course_content" VALUES (2571, 50, '{"english": "John, let''s clean the classroom now.", "chinese": "约翰，我们现在来打扫教室吧。"}', 67, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2572, 50, '{"english": "OK. Let me clean the board.", "chinese": "好的。让我来擦黑板。"}', 68, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2573, 50, '{"english": "Let me clean the desks and chairs!", "chinese": "让我来擦桌子和椅子！"}', 69, '2026-02-05 03:56:57', '2026-02-05 03:56:57');
INSERT INTO "course_content" VALUES (2574, 50, '{"english": "Mike, who''s he?", "chinese": "迈克，他是谁？"}', 70, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2575, 50, '{"english": "He''s very tall and he has brown hair.", "chinese": "他很高并且有棕色的头发。"}', 71, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2576, 50, '{"english": "He''s my friend. He''s a new student.", "chinese": "他是我的朋友。他是个新学生。"}', 72, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2577, 50, '{"english": "What''s his name?", "chinese": "他叫什么名字？"}', 73, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2578, 50, '{"english": "His name is Ted.", "chinese": "他的名字是泰德。"}', 74, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2579, 50, '{"english": "Look at the pictures and finish the dialogues.", "chinese": "看图片，完成对话。"}', 75, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2580, 50, '{"english": "Play a game.", "chinese": "玩一个游戏。"}', 76, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2581, 50, '{"english": "What''s in your classroom?", "chinese": "你的教室里有什么？"}', 77, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2582, 50, '{"english": "Who''s your maths teacher?", "chinese": "你的数学老师是谁？"}', 78, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2583, 50, '{"english": "How many storybooks do you have?", "chinese": "你有多少本故事书？"}', 79, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2584, 50, '{"english": "What''s in your pencil box?", "chinese": "你的铅笔盒里有什么？"}', 80, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2585, 50, '{"english": "Do you like maths?", "chinese": "你喜欢数学吗？"}', 81, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2586, 50, '{"english": "What colour is your schoolbag?", "chinese": "你的书包是什么颜色的？"}', 82, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2587, 50, '{"english": "What''s in your schoolbag?", "chinese": "你的书包里有什么？"}', 83, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2588, 50, '{"english": "Who''s your best friend?", "chinese": "谁是你最好的朋友？"}', 84, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2589, 50, '{"english": "What colour is your English book?", "chinese": "你的英语书是什么颜色的？"}', 85, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2590, 50, '{"english": "Who''s the winner?", "chinese": "谁赢啦？"}', 86, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2591, 50, '{"english": "Unit Four", "chinese": "第四单元"}', 87, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2592, 50, '{"english": "Mum, where are my crayons?", "chinese": "妈妈，我的蜡笔在哪里？"}', 88, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2593, 50, '{"english": "Are they in the study?", "chinese": "它们在书房里吗？"}', 89, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2594, 50, '{"english": "Where''s the cat, Dad?", "chinese": "猫在哪儿，爸爸？"}', 90, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2595, 50, '{"english": "Is she in the kitchen?", "chinese": "她在厨房里吗？"}', 91, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2596, 50, '{"english": "My home", "chinese": "我的家"}', 92, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2597, 50, '{"english": "Oh, no!", "chinese": "哦，不！"}', 93, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2598, 50, '{"english": "Zip, your living room is nice.", "chinese": "兹普，你的客厅很漂亮。"}', 94, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2599, 50, '{"english": "Zip is in the bathroom. I''m her sister.", "chinese": "兹普在浴室里。我是她的姐姐。"}', 95, '2026-02-05 03:56:58', '2026-02-05 03:56:58');
INSERT INTO "course_content" VALUES (2600, 51, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2601, 51, '{"english": "I have a cat. She''s cute.", "chinese": "我有一只猫。她很可爱。"}', 2, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2602, 51, '{"english": "Where is she?", "chinese": "她在哪里？"}', 3, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2603, 51, '{"english": "Mmm. Is she in the living room?", "chinese": "嗯。她在客厅里吗？"}', 4, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2604, 51, '{"english": "No, she isn''t.", "chinese": "不，她不在。"}', 5, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2605, 51, '{"english": "Is she in the study?", "chinese": "她在书房吗？"}', 6, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2606, 51, '{"english": "No, she isn''t.", "chinese": "不，她不在。"}', 7, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2607, 51, '{"english": "Look! She''s in the kitchen.", "chinese": "看！她在厨房里。"}', 8, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2608, 51, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 9, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2609, 51, '{"english": "Where''s my pen?", "chinese": "我的钢笔在哪里？"}', 10, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2610, 51, '{"english": "Is it in your desk?", "chinese": "它在你的书桌里吗？"}', 11, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2611, 51, '{"english": "No, it isn''t.", "chinese": "不，它不在。"}', 12, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2612, 51, '{"english": "Is it in your hand?", "chinese": "它在你的手里吗？"}', 13, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2613, 51, '{"english": "Yes, it is!", "chinese": "是的，它在！"}', 14, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2614, 51, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 15, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2615, 51, '{"english": "Where''s Amy?  Is she in the study?", "chinese": "艾米在哪里？ 她在书房里吗？"}', 16, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2616, 51, '{"english": "Yes, she is.", "chinese": "是的，她在。"}', 17, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2617, 51, '{"english": "bedroom", "chinese": "卧室"}', 18, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2618, 51, '{"english": "living room", "chinese": "客厅"}', 19, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2619, 51, '{"english": "study", "chinese": "书房"}', 20, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2620, 51, '{"english": "kitchen", "chinese": "厨房"}', 21, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2621, 51, '{"english": "bathroom", "chinese": "浴室"}', 22, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2622, 51, '{"english": "Let''s do", "chinese": "让我们做一做"}', 23, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2623, 51, '{"english": "Go to the living room.  Watch TV.   Go to the study.", "chinese": "去客厅。 看电视。  去书房。"}', 24, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2624, 51, '{"english": "Read a book.   Go to the kitchen.  Have a snack.", "chinese": "看书。  去厨房。 吃零食。"}', 25, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2625, 51, '{"english": "Go to the bedroom.  Have a nap.   Go to the bathroom.", "chinese": "去卧室。 小睡一会。  去浴室。"}', 26, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2626, 51, '{"english": "Take a shower.  Go to the living room.", "chinese": "洗淋浴。 去客厅。"}', 27, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2627, 51, '{"english": "Watch TV.   Go to the study.  Read a book.", "chinese": "看电视。  去书房。 看书。"}', 28, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2628, 51, '{"english": "Go to the kitchen.  Have a snack.   Go to the bedroom.", "chinese": "去厨房。 吃零食。  去卧室。"}', 29, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2629, 51, '{"english": "Have a nap.   Go to the bathroom.  Take a shower.", "chinese": "小睡一会。  去浴室。 洗淋浴。"}', 30, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2630, 51, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 31, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2631, 51, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 32, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2632, 51, '{"english": "Excuse me ...", "chinese": "打扰一下⋯⋯"}', 33, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2633, 51, '{"english": "use", "chinese": "使用"}', 34, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2634, 51, '{"english": "cute", "chinese": "可爱的"}', 35, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2635, 51, '{"english": "excuse", "chinese": "原谅"}', 36, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2636, 51, '{"english": "One cute cat uses two two balls.", "chinese": "一只可爱的猫咪用两个球。"}', 37, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2637, 51, '{"english": "Two cute cats use three three balls.", "chinese": "两只可爱的猫咪用三个球。"}', 38, '2026-02-05 03:57:00', '2026-02-05 03:57:00');
INSERT INTO "course_content" VALUES (2638, 51, '{"english": "Three cute cats use four four balls.", "chinese": "三只可爱的猫咪用四个球。"}', 39, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2639, 51, '{"english": "Four cute cats use five five balls.", "chinese": "四只可爱的猫咪用五个球。"}', 40, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2640, 51, '{"english": "Five cute cats use six six balls.", "chinese": "五只可爱的猫咪用六个球。"}', 41, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2641, 51, '{"english": "One two three, four five six.  Five cute cats playing tricks.", "chinese": "一、二、三、四、五、六。 五只可爱的猫咪在耍花招。"}', 42, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2642, 51, '{"english": "One cute cat uses two two balls.", "chinese": "一只可爱的猫咪用两个球。"}', 43, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2643, 51, '{"english": "Two cute cats use three three balls.  Three cute cats use four four balls.", "chinese": "两只可爱的猫咪用三个球。 三只可爱的猫咪用四个球。"}', 44, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2644, 51, '{"english": "Four cute cats use five five balls.  Five cute cats use six six balls.", "chinese": "四只可爱的猫咪用五个球。 五只可爱的猫咪用六个球。"}', 45, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2645, 51, '{"english": "One two three, four five six.  Five cute cats playing tricks.", "chinese": "一、二、三、四、五、六。 五只可爱的猫咪在耍花招。"}', 46, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2646, 51, '{"english": "Listen, circle and say.", "chinese": "听一听，圈一圈，说一说。"}', 47, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2647, 51, '{"english": "cute, cut, use, fun, tube  excuse, bus, mum, mule", "chinese": "可爱的，切，使用，有趣的，管子 原谅，公交车，妈妈，骡子"}', 48, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2648, 51, '{"english": "Listen, circle and write.", "chinese": "听一听，圈一圈，写一写。"}', 49, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2649, 51, '{"english": "duck", "chinese": "鸭子"}', 50, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2650, 51, '{"english": "cute", "chinese": "可爱的"}', 51, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2651, 51, '{"english": "up", "chinese": "向上"}', 52, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2652, 51, '{"english": "use", "chinese": "使用"}', 53, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2653, 51, '{"english": "1. -Where are my glasses?  -They''re on the fridge.  -Oh, yes. I see them.", "chinese": "1. —我的眼镜在哪里？ —它们在冰箱上面。 —噢，是的。我看见了。"}', 54, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2654, 51, '{"english": "2. -Are the keys in the kitchen?", "chinese": "2. —钥匙在厨房吗？"}', 55, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2655, 51, '{"english": "-No, they aren''t. They''re in the living room.", "chinese": "—不，它们不在。它们在客厅。"}', 56, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2656, 51, '{"english": "3. -Where are my books?  -Are they in the study?  -Yes, they are. Thanks.", "chinese": "3. —我的书在哪里？ —它们在书房吗？ —是的，它们在。谢谢。"}', 57, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2657, 51, '{"english": "4. -Where''s Mike? Is he in the study?", "chinese": "4. —迈克在哪里？他在书房吗？"}', 58, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2658, 51, '{"english": "-No, he isn''t. He''s in the bedroom.  -OK. Thanks.", "chinese": "—不，他不在。他在卧室。 —好的。谢谢。"}', 59, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2659, 51, '{"english": "Look and tick (√).", "chinese": "看一看，勾一勾。"}', 60, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2660, 51, '{"english": "FOR RENT", "chinese": "供出租"}', 61, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2661, 51, '{"english": "2 bedrooms (beds)  1 living room (sofa, table and TV)", "chinese": "两间卧室（床） 一间客厅（沙发、桌子、电视）"}', 62, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2662, 51, '{"english": "1 kitchen (fridge)  2 bathrooms", "chinese": "一间厨房（冰箱） 两间卫生间"}', 63, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2663, 51, '{"english": "FOR RENT", "chinese": "供出租"}', 64, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2664, 51, '{"english": "1 bedroom (bed)  1 living room (sofa and TV)", "chinese": "一间卧室（床） 一间客厅（沙发、电视）"}', 65, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2665, 51, '{"english": "1 kitchen (fridge)  1 bathroom", "chinese": "一间厨房（冰箱） 一间卫生间"}', 66, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2666, 51, '{"english": "Let''s sing", "chinese": "让我们唱歌吧"}', 67, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2667, 51, '{"english": "My home", "chinese": "我的家"}', 68, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2668, 51, '{"english": "Where, oh, where has the TV gone?", "chinese": "哦，电视去哪了？"}', 69, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2669, 51, '{"english": "Where, oh, where can it be?", "chinese": "在哪里？在哪里？"}', 70, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2670, 51, '{"english": "Where, oh, where has the TV gone?", "chinese": "哦，电视去哪了？"}', 71, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2671, 51, '{"english": "It''s in the bedroom with me.", "chinese": "它和我在卧室里。"}', 72, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2672, 51, '{"english": "Where, oh, where has the telephone gone?  Where, oh, where can it be?", "chinese": "哦，电话去哪了？ 在哪里？在哪里？"}', 73, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2673, 51, '{"english": "Where, oh, where has the sofa gone?  It''s in the bedroom with me.", "chinese": "哦，沙发去哪了？ 它和我在卧室里。"}', 74, '2026-02-05 03:57:01', '2026-02-05 03:57:01');
INSERT INTO "course_content" VALUES (2674, 52, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2675, 52, '{"english": "Mum, I''m hungry. What''s for dinner?", "chinese": "妈妈，我饿了。晚餐吃什么？"}', 2, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2676, 52, '{"english": "What would you like?", "chinese": "你想吃什么？"}', 3, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2677, 52, '{"english": "I''d like some soup and bread, please.", "chinese": "我想要汤和面包。"}', 4, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2678, 52, '{"english": "What would you like for dinner?", "chinese": "晚餐你想吃什么？"}', 5, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2679, 52, '{"english": "Some fish and vegetables, please.", "chinese": "鱼和蔬菜。"}', 6, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2680, 52, '{"english": "Dinner''s ready!", "chinese": "晚餐准备好了！"}', 7, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2681, 52, '{"english": "Thanks!", "chinese": "谢谢！"}', 8, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2682, 52, '{"english": "Let''s survey", "chinese": "让我们调查一下"}', 9, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2683, 52, '{"english": "What would you like for dinner?", "chinese": "晚餐你想吃什么？"}', 10, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2684, 52, '{"english": "I''d like some rice and vegetables.", "chinese": "我想要些米饭和蔬菜。"}', 11, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2685, 52, '{"english": "name", "chinese": "名字"}', 12, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2686, 52, '{"english": "Mike", "chinese": "迈克"}', 13, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2687, 52, '{"english": "fish", "chinese": "鱼"}', 14, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2688, 52, '{"english": "vegetables", "chinese": "蔬菜"}', 15, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2689, 52, '{"english": "rice", "chinese": "大米"}', 16, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2690, 52, '{"english": "bread", "chinese": "面包"}', 17, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2691, 52, '{"english": "juice", "chinese": "果汁"}', 18, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2692, 52, '{"english": "soup", "chinese": "汤"}', 19, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2693, 52, '{"english": "others", "chinese": "其他"}', 20, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2694, 52, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 21, '2026-02-05 03:57:02', '2026-02-05 03:57:02');
INSERT INTO "course_content" VALUES (2695, 52, '{"english": "What would you like?", "chinese": "你想吃什么？"}', 22, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2696, 52, '{"english": "I''d like some vegetables, please.", "chinese": "我想要一些蔬菜。"}', 23, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2697, 52, '{"english": "OK. Five yuan, please.", "chinese": "好的。请给五元。"}', 24, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2698, 52, '{"english": "MENU", "chinese": "菜单"}', 25, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2699, 52, '{"english": "beef", "chinese": "牛肉"}', 26, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2700, 52, '{"english": "chicken", "chinese": "鸡肉"}', 27, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2701, 52, '{"english": "noodles", "chinese": "面条"}', 28, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2702, 52, '{"english": "soup", "chinese": "汤"}', 29, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2703, 52, '{"english": "vegetables", "chinese": "蔬菜"}', 30, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2704, 52, '{"english": "rice", "chinese": "米饭"}', 31, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2705, 52, '{"english": "fish", "chinese": "鱼"}', 32, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2706, 52, '{"english": "juice", "chinese": "果汁"}', 33, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2707, 52, '{"english": "milk", "chinese": "牛奶"}', 34, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2708, 52, '{"english": "bread", "chinese": "面包"}', 35, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2709, 52, '{"english": "Look, choose and write.", "chinese": "看一看，选一选，写一写。"}', 36, '2026-02-05 03:57:03', '2026-02-05 03:57:03');
INSERT INTO "course_content" VALUES (2710, 52, '{"english": "In my soup,", "chinese": "在汤里面，"}', 37, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2711, 52, '{"english": "I''d like some ______, ______ and some ______.", "chinese": "我想要一些______，______和一些______。"}', 38, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2712, 52, '{"english": "rice", "chinese": "米饭"}', 39, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2713, 52, '{"english": "vegetables", "chinese": "蔬菜"}', 40, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2714, 52, '{"english": "fish", "chinese": "鱼"}', 41, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2715, 52, '{"english": "beef", "chinese": "牛肉"}', 42, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2716, 52, '{"english": "noodles", "chinese": "面条"}', 43, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2717, 52, '{"english": "juice", "chinese": "果汁"}', 44, '2026-02-05 03:57:04', '2026-02-05 03:57:04');
INSERT INTO "course_content" VALUES (2718, 53, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2719, 53, '{"english": "How many people are there in your family, Chen Jie?", "chinese": "你家有几口人，陈杰？"}', 2, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2720, 53, '{"english": "Three. My parents and me.", "chinese": "三口人。我的父母和我。"}', 3, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2721, 53, '{"english": "My family has six people.", "chinese": "我家有六口人。"}', 4, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2722, 53, '{"english": "Six?", "chinese": "六口人？"}', 5, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2723, 53, '{"english": "Yes.", "chinese": "是的。"}', 6, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2724, 53, '{"english": "My dad, my mum, my sister, my baby brother and me.", "chinese": "我的爸爸、我的妈妈、我的姐姐、我的弟弟和我。"}', 7, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2725, 53, '{"english": "But that''s only five.", "chinese": "但这只有五口人。"}', 8, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2726, 53, '{"english": "And my little puppy!", "chinese": "还有我的小狗！"}', 9, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2727, 53, '{"english": "Let''s count", "chinese": "让我们数一数"}', 10, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2728, 53, '{"english": "How many apples are there on the tree?", "chinese": "树上有多少个苹果？"}', 11, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2729, 53, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 12, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2730, 53, '{"english": "Hi. Meet my family!", "chinese": "嗨。见见我的家人！"}', 13, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2731, 53, '{"english": "parents", "chinese": "父母"}', 14, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2732, 53, '{"english": "cousin", "chinese": "堂妹"}', 15, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2733, 53, '{"english": "uncle", "chinese": "叔叔"}', 16, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2734, 53, '{"english": "aunt", "chinese": "婶婶"}', 17, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2735, 53, '{"english": "baby brother", "chinese": "婴儿小弟弟"}', 18, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2736, 53, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 19, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2737, 53, '{"english": "This is my uncle. He''s tall and strong.", "chinese": "这是我叔叔。他又高又壮。"}', 20, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2738, 53, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 21, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2739, 53, '{"english": "Read, listen and circle.", "chinese": "读一读，听一听，圈一圈。"}', 22, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2740, 53, '{"english": "1. he, men, rice", "chinese": "1. 他，男人（复数），米饭"}', 23, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2741, 53, '{"english": "2. had, make, nose", "chinese": "2. 有（have 的过去式），制作，鼻子"}', 24, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2742, 53, '{"english": "3. use, cat, mum", "chinese": "3. 使用，猫，妈妈"}', 25, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2743, 53, '{"english": "Listen and chant.", "chinese": "听一听，唱一唱。"}', 26, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2744, 53, '{"english": "We like the cat! It''s cute. It''s cute.", "chinese": "我们喜欢这只猫！它很可爱。它很可爱。"}', 27, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2745, 53, '{"english": "He''s got a cake and a cup of milk.", "chinese": "它有一块蛋糕和一杯牛奶。"}', 28, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2746, 53, '{"english": "He is tall and strong.", "chinese": "他又高又强壮。"}', 29, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2747, 53, '{"english": "My uncle is a cook. My aunt is a nurse.", "chinese": "我叔叔是位厨师。我的婶婶是位护士。"}', 30, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2748, 53, '{"english": "I am a student. I have no job.", "chinese": "我是学生。我没有工作。"}', 31, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2749, 53, '{"english": "Is this John''s mother?", "chinese": "这是约翰的妈妈吗？"}', 32, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2750, 53, '{"english": "Is this John''s aunt?", "chinese": "这是约翰的婶婶吗？"}', 33, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2751, 53, '{"english": "Is this his father?", "chinese": "这是他的爸爸吗？"}', 34, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2752, 53, '{"english": "Is this his uncle?", "chinese": "这是他的叔叔吗？"}', 35, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2753, 53, '{"english": "Look and write.", "chinese": "看一看，写一写。"}', 36, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2754, 53, '{"english": "What is his / her job?", "chinese": "他/她的工作是什么？"}', 37, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2755, 53, '{"english": "He is a driver.", "chinese": "他是一名司机。"}', 38, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2756, 53, '{"english": "doctor", "chinese": "医生"}', 39, '2026-02-05 03:57:05', '2026-02-05 03:57:05');
INSERT INTO "course_content" VALUES (2757, 54, '{"english": "Recycle 2", "chinese": "复习 2"}', 1, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2758, 54, '{"english": "Read aloud.", "chinese": "大声朗读。"}', 2, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2759, 54, '{"english": "This is our living room.", "chinese": "这是我们的客厅。"}', 3, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2760, 54, '{"english": "Wow! It''s beautiful!", "chinese": "哇！好漂亮！"}', 4, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2761, 54, '{"english": "Come and meet my family. They''re in the kitchen.", "chinese": "来见见我的家人。他们在厨房里。"}', 5, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2762, 54, '{"english": "Welcome!", "chinese": "欢迎！"}', 6, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2763, 54, '{"english": "Merry Christmas!", "chinese": "圣诞快乐！"}', 7, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2764, 54, '{"english": "Merry Christmas!", "chinese": "圣诞快乐！"}', 8, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2765, 54, '{"english": "Is that your father?", "chinese": "那是你爸爸吗？"}', 9, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2766, 54, '{"english": "Yes. He''s Father Christmas now.", "chinese": "是的。他现在是圣诞老人。"}', 10, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2767, 54, '{"english": "This is my mother. She''s a nurse.", "chinese": "这是我的妈妈。她是位护士。"}', 11, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2768, 54, '{"english": "Nice to meet you.", "chinese": "很高兴认识你。"}', 12, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2769, 54, '{"english": "Nice to meet you, too.", "chinese": "我也很高兴认识你们。"}', 13, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2770, 54, '{"english": "What would you like?", "chinese": "你想要吃什么？"}', 14, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2771, 54, '{"english": "I''d like some turkey, please.", "chinese": "我想要吃一些火鸡。"}', 15, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2772, 54, '{"english": "Would you like some juice?", "chinese": "你想喝点果汁吗？"}', 16, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2773, 54, '{"english": "Yes, please.", "chinese": "是的，请给我些。"}', 17, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2774, 54, '{"english": "Help yourself!", "chinese": "随便吃吧！"}', 18, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2775, 54, '{"english": "Merry Christmas!", "chinese": "圣诞快乐！"}', 19, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2776, 54, '{"english": "Can you act it out?", "chinese": "你能表演出来吗？"}', 20, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2777, 54, '{"english": "Listen and number the rooms.", "chinese": "听一听，给房间编号。"}', 21, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2778, 54, '{"english": "-Where are we?  -Hmm,that''s a red sofa.", "chinese": "—我们在哪里？ —嗯，有一张红色沙发。"}', 22, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2779, 54, '{"english": "We are in the living room.  -Is this the little boy''s room?", "chinese": "我们在客厅里。 —这是小男孩的房间吗？"}', 23, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2780, 54, '{"english": "-Hmm,no. We are in the kitchen.  -And now?", "chinese": "—嗯，不。我们在厨房。 —现在呢？"}', 24, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2781, 54, '{"english": "-That''s a desk. We are in the study.  -And now?", "chinese": "—那有一张桌子。我们在书房。 —现在呢？"}', 25, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2782, 54, '{"english": "-Oh no. It''s mother and father''s room. Quiet!  -Aha!", "chinese": "—哦，不。是爸爸妈妈的房间。安静！ —哈哈！"}', 26, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2783, 54, '{"english": "I see him on the green bed.  -He''s so cute.", "chinese": "我看见他躺在绿色的床上。 —他太可爱了。"}', 27, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2784, 54, '{"english": "Let''s put his gift under the window.  -OK.", "chinese": "让我们把他的礼物放在窗户下面。 —好的。"}', 28, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2785, 54, '{"english": "Look, listen and write.", "chinese": "看一看，听一听，写一写。"}', 29, '2026-02-05 03:57:06', '2026-02-05 03:57:06');
INSERT INTO "course_content" VALUES (2786, 54, '{"english": "Can I use your sleigh, Santa?", "chinese": "圣诞老人，我能用你的雪橇吗？"}', 30, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2787, 54, '{"english": "My bus is late and my bike is at home.", "chinese": "我的公共汽车晚点了，我的自行车在家。"}', 31, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2788, 54, '{"english": "Yes, little girl.", "chinese": "可以，小女孩。"}', 32, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2789, 54, '{"english": "Give them some cake and they can take you home.", "chinese": "给它们一些蛋糕，它们可以带你回家。"}', 33, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2790, 54, '{"english": "Thank you so much. What do you want, Santa?", "chinese": "非常感谢。你想要什么，圣诞老人？"}', 34, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2791, 54, '{"english": "Just give me a smile. It''s free to be nice.", "chinese": "给我一个微笑。善良是免费的。"}', 35, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
INSERT INTO "course_content" VALUES (2792, 54, '{"english": "Look, ask and answer.", "chinese": "看一看，问一问，答一答。"}', 36, '2026-02-05 03:57:07', '2026-02-05 03:57:07');
