INSERT INTO "course_content" VALUES (2910, 57, '{"english": "It''s near the window.", "chinese": "就在窗户旁边。"}', 6, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2911, 57, '{"english": "Let''s clean the classroom!", "chinese": "我们打扫教室吧！"}', 7, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2912, 57, '{"english": "Let me clean the windows.", "chinese": "我来擦窗户。"}', 8, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2913, 57, '{"english": "Unit 2", "chinese": "第 2 单元"}', 9, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2914, 57, '{"english": "What''s in your schoolbag?", "chinese": "你书包里有什么？"}', 10, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2915, 57, '{"english": "An English book, a maths book, three storybooks and ...", "chinese": "一本英语书，一本数学书，三本故事书和⋯⋯"}', 11, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2916, 57, '{"english": "What colour is it?", "chinese": "什么颜色的？"}', 12, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2917, 57, '{"english": "It''s blue and white.", "chinese": "是蓝白色的。"}', 13, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2918, 57, '{"english": "Unit 3", "chinese": "第 3 单元"}', 14, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2919, 57, '{"english": "What''s his name?", "chinese": "他叫什么名字？"}', 15, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2920, 57, '{"english": "His name is Zhang Peng.", "chinese": "他叫张鹏。"}', 16, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2921, 57, '{"english": "He''s tall and strong.", "chinese": "他又高又壮。"}', 17, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2922, 57, '{"english": "Who''s he?", "chinese": "他是谁？"}', 18, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2923, 57, '{"english": "He has glasses and his shoes are blue.", "chinese": "他戴眼镜，穿蓝色鞋子。"}', 19, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2924, 57, '{"english": "Unit 4", "chinese": "第 4 单元"}', 20, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2925, 57, '{"english": "Is she in the living room?", "chinese": "她在客厅里吗？"}', 21, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2926, 57, '{"english": "No, she isn''t.", "chinese": "不，她不在。"}', 22, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2927, 57, '{"english": "Where are the keys?", "chinese": "钥匙在哪儿？"}', 23, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2928, 57, '{"english": "Are they on the table?", "chinese": "它们在桌子上吗？"}', 24, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2929, 57, '{"english": "No, they aren''t. They''re in the door.", "chinese": "不，不在。它们在门上。"}', 25, '2026-02-05 03:57:12', '2026-02-05 03:57:12');
INSERT INTO "course_content" VALUES (2930, 58, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2931, 58, '{"english": "Excuse me. Where''s the teachers'' office?", "chinese": "打扰一下。教师办公室在哪里？"}', 2, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2932, 58, '{"english": "It''s on the second floor.", "chinese": "它在二楼。"}', 3, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2933, 58, '{"english": "OK. Thanks.", "chinese": "好的。谢谢。"}', 4, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2934, 58, '{"english": "Hi. Is this the teachers'' office?", "chinese": "嗨。这是教师办公室吗？"}', 5, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2935, 58, '{"english": "No, it isn''t. The teachers'' office is next to the library.", "chinese": "不，不是。教师办公室挨着图书馆。"}', 6, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2936, 58, '{"english": "Hi, Miss White! Here''s my homework.", "chinese": "你好，怀特老师！这是我的作业。"}', 7, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2937, 58, '{"english": "Thank you, Mike.", "chinese": "谢谢，迈克。"}', 8, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2938, 58, '{"english": "Bye, Miss White.", "chinese": "再见，怀特老师。"}', 9, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2939, 58, '{"english": "Look, ask and answer", "chinese": "看一看，问一问，答一答"}', 10, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2940, 58, '{"english": "Where''s the library?", "chinese": "图书馆在哪里？"}', 11, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2941, 58, '{"english": "It''s on the second floor.", "chinese": "它在二楼。"}', 12, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2942, 58, '{"english": "Is it next to Classroom 3?", "chinese": "它在三班旁边吗？"}', 13, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2943, 58, '{"english": "Yes, it is.", "chinese": "是的。"}', 14, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2944, 58, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 15, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2945, 58, '{"english": "Where''s the library?", "chinese": "图书馆在哪里？"}', 16, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2946, 58, '{"english": "It''s on the first floor.", "chinese": "它在一楼。"}', 17, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2947, 58, '{"english": "teachers'' office", "chinese": "教师办公室"}', 18, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2948, 58, '{"english": "library", "chinese": "图书馆"}', 19, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2949, 58, '{"english": "first floor", "chinese": "一楼"}', 20, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2950, 58, '{"english": "second floor", "chinese": "二楼"}', 21, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2951, 58, '{"english": "Let''s do", "chinese": "让我们做一做"}', 22, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2952, 58, '{"english": "Go to the library.", "chinese": "去图书馆，"}', 23, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2953, 58, '{"english": "Read a book.", "chinese": "读本书吧。"}', 24, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2954, 58, '{"english": "Shhh . .. Be quiet!", "chinese": "嘘⋯⋯ 安静！"}', 25, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2955, 58, '{"english": "Go to the teachers'' office.", "chinese": "去教室办公室。"}', 26, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2956, 58, '{"english": "Say hello.", "chinese": "问声好。"}', 27, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2957, 58, '{"english": "Hi, Miss White.", "chinese": "你好，怀特老师。"}', 28, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2958, 58, '{"english": "Go to the playground.", "chinese": "去操场。"}', 29, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2959, 58, '{"english": "Play football.", "chinese": "踢足球。"}', 30, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2960, 58, '{"english": "Yeah! We win!", "chinese": "耶！我们赢了！"}', 31, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2961, 58, '{"english": "Go to the garden.", "chinese": "去花园。"}', 32, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2962, 58, '{"english": "Water the flowers.", "chinese": "浇花。"}', 33, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2963, 58, '{"english": "Wow! Beautiful!", "chinese": "哇！好漂亮！"}', 34, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2964, 58, '{"english": "Go to the library. Read a book. Shhh ... Be quiet!", "chinese": "去图书馆 读本书吧。嘘⋯⋯ 安静！"}', 35, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2965, 58, '{"english": "Go to the teachers'' office. Say hello. Hi, Miss White.", "chinese": "去教室办公室 问声好。你好，怀特老师。"}', 36, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2966, 58, '{"english": "Go to the playground. Play football. Yeah! We win!", "chinese": "去操场 踢足球。耶！我们赢了！"}', 37, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2967, 58, '{"english": "Go to the garden. Water the flowers. Wow! Beautiful!", "chinese": "去花园 浇花。哇！好漂亮！"}', 38, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2968, 58, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 39, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2969, 58, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 40, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2970, 58, '{"english": "water", "chinese": "水"}', 41, '2026-02-05 03:57:14', '2026-02-05 03:57:14');
INSERT INTO "course_content" VALUES (2971, 58, '{"english": "tiger", "chinese": "老虎"}', 42, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
