INSERT INTO "course_content" VALUES (2973, 58, '{"english": "computer", "chinese": "计算机"}', 44, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2974, 58, '{"english": "dinner", "chinese": "正餐"}', 45, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2975, 58, '{"english": "Sister, sister, can you see?", "chinese": "姐姐，姐姐，你能看见吗？"}', 46, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2976, 58, '{"english": "A hungry tiger on the TV.", "chinese": "一只饥饿的老虎在电视上。"}', 47, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2977, 58, '{"english": "Tiger, tiger, can you see?", "chinese": "老虎，老虎，你能看见吗？"}', 48, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2978, 58, '{"english": "Dinner for you, dinner for me.", "chinese": "你的晚餐，我的晚餐。"}', 49, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2979, 58, '{"english": "Sister, sister, can you see?", "chinese": "姐姐，姐姐，你能看见吗？"}', 50, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2980, 58, '{"english": "A hungry tiger on the TV.", "chinese": "一只饥饿的老虎在电视上。"}', 51, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2981, 58, '{"english": "Tiger, tiger, can you see?", "chinese": "老虎，老虎，你能看见吗？"}', 52, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2982, 58, '{"english": "Dinner for you, dinner for me.", "chinese": "你的晚餐，我的晚餐。"}', 53, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2983, 58, '{"english": "Read, underline and say.", "chinese": "读一读，画下划线，说一说。"}', 54, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2984, 58, '{"english": "1. sister, ruler, under, number", "chinese": "1. 姐妹, 尺子, 在⋯⋯下面, 数字"}', 55, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2985, 58, '{"english": "2. computer, eraser, dinner, winter", "chinese": "2. 计算机，橡皮，正餐，冬天"}', 56, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2986, 58, '{"english": "3. under, after, water, river", "chinese": "3. 在⋯⋯下面，在⋯⋯之后，水，河流"}', 57, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2987, 58, '{"english": "Look, listen and write.", "chinese": "看一看，听一听，写一写。"}', 58, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2988, 58, '{"english": "my sister''s dinner.", "chinese": "我妹妹的晚餐。"}', 59, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2989, 58, '{"english": "No water near the computer.", "chinese": "电脑附近不要放水。"}', 60, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2990, 58, '{"english": "—No, it isn''t. The teachers'' office is next to the art room.", "chinese": "——不，不是。教师办公室紧挨着美术教室。"}', 61, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2991, 58, '{"english": "—Hi. Is this the teachers'' office?", "chinese": "——你好。这是教师办公室吗？"}', 62, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2992, 58, '{"english": "—No, it isn''t. The teachers'' office is next to the art room.", "chinese": "——不，不是。教师办公室紧挨着美术教室。"}', 63, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2993, 58, '{"english": "4. —Do you have a music room?", "chinese": "4. ——你们有音乐教室吗？"}', 64, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (2994, 58, '{"english": "—No, we don''t.", "chinese": "——我们没有。"}', 65, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
