INSERT INTO "course_content" VALUES (3012, 58, '{"english": "This is the way I go to school, go to school, go to school.", "chinese": "这就是我上学的方式,去上学啊，去上学啊。"}', 83, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
INSERT INTO "course_content" VALUES (3013, 58, '{"english": "This is the way I go to school, where I like to learn all day.", "chinese": "这就是我上学的方式，我喜欢在那里整日学习。"}', 84, '2026-02-05 03:57:15', '2026-02-05 03:57:15');
