INSERT INTO "course_content" VALUES (3201, 61, '{"english": "We have a show in the library today.", "chinese": "今天我们在图书馆里有一场表演。"}', 3, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3202, 61, '{"english": "What time?", "chinese": "什么时间？"}', 4, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3203, 61, '{"english": "At 4 o''clock.", "chinese": "四点。"}', 5, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
