INSERT INTO "course_content" VALUES (3205, 61, '{"english": "It''s 3:40. Time to go!", "chinese": "三点四十了。该出发了！"}', 7, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3206, 61, '{"english": "It''s cold outside.", "chinese": "外面很冷。"}', 8, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3207, 61, '{"english": "Yes, it''s windy too. Do you have a jacket?", "chinese": "是的，风也很大。你有夹克衫吗？"}', 9, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
