INSERT INTO "course_content" VALUES (3216, 61, '{"english": "1. —What time is it now?", "chinese": "1. ——现在几点了？"}', 18, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3217, 61, '{"english": "—It''s three o''clock.", "chinese": "——现在三点钟。"}', 19, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3218, 61, '{"english": "Time for art class.  —What time is it now?", "chinese": "该上美术课了。 ——现在几点了？"}', 20, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3219, 61, '{"english": "—It''s three o''clock. Time for art class.", "chinese": "——现在三点钟。该上美术课了。"}', 21, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3220, 61, '{"english": "2. Look at that bird outside the window.", "chinese": "2. 看窗外的那只鸟。"}', 22, '2026-02-05 03:57:26', '2026-02-05 03:57:26');
INSERT INTO "course_content" VALUES (3221, 61, '{"english": "It''s so cute.", "chinese": "它太可爱了。"}', 23, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3222, 61, '{"english": "Look at that bird outside the window. It''s so cute.", "chinese": "看窗外的那只鸟。它太可爱了。"}', 24, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3223, 61, '{"english": "3. Time for PE. Let''s play basketball.", "chinese": "3. 该上体育课了。我们一起打篮球吧。"}', 25, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3224, 61, '{"english": "Where is my ball? Time for PE.", "chinese": "我的球在哪里？该上体育课了。"}', 26, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3225, 61, '{"english": "Let''s play basketball. Where is my ball?", "chinese": "我们一起打篮球吧。我的球在哪里？"}', 27, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3226, 61, '{"english": "4. —Ah, the water is hot.", "chinese": "4. ——啊，这水好烫。"}', 28, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3227, 61, '{"english": "—Be careful!", "chinese": "——当心点！"}', 29, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3228, 61, '{"english": "—Ah, the water is hot.", "chinese": "——啊，这水好烫。"}', 30, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3229, 61, '{"english": "—Be careful!", "chinese": "——当心点！"}', 31, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3230, 61, '{"english": "Look, ask and answer.", "chinese": "看一看，问一问，答一答。"}', 32, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3231, 61, '{"english": "Is this the library?", "chinese": "这是图书馆吗？"}', 33, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3232, 61, '{"english": "What''s the weather like?", "chinese": "天气怎么样？"}', 34, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3233, 61, '{"english": "Where is the computer room?", "chinese": "计算机房在哪里？"}', 35, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3234, 61, '{"english": "Listen, tick (√) and say.", "chinese": "听一听，打勾，说一说。"}', 36, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3235, 61, '{"english": "Good afternoon. This is the weather report. Today it''s snowy in Beijing.", "chinese": "下午好。这里是天气预报。今天北京下雪了。"}', 37, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3236, 61, '{"english": "In Shanghai, it''s cloudy. It''s windy in Harbin and Lhasa.", "chinese": "上海多云。哈尔滨和拉萨有风。"}', 38, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3237, 61, '{"english": "In Sanya, it''s sunny. And in Hong Kong it''s rainy.", "chinese": "三亚阳光明媚。香港下雨。"}', 39, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3238, 61, '{"english": "Well, that''s the weather report for today. Thank you.", "chinese": "这是今天的天气预报。非常感谢。"}', 40, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3239, 61, '{"english": "Goodbye. Good afternoon. This is the weather report.", "chinese": "再见。下午好。这里是天气预报。"}', 41, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3240, 61, '{"english": "Today it''s snowy in Beijing. In Shanghai, it''s cloudy.", "chinese": "今天北京下雪了。上海多云。"}', 42, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3241, 61, '{"english": "It''s windy in Harbin and Lhasa.", "chinese": "哈尔滨和拉萨有风。"}', 43, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3242, 61, '{"english": "In Sanya, it''s sunny. And in Hong Kong it''s rainy.", "chinese": "三亚阳光明媚。香港下雨。"}', 44, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3243, 61, '{"english": "Well, that''s the weather report for today. Thank you. Goodbye.", "chinese": "这是今天的天气预报。非常感谢。再见。"}', 45, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3244, 61, '{"english": "What''s the weather like in Beijing?", "chinese": "北京的天气怎么样？"}', 46, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3245, 61, '{"english": "It''s ...", "chinese": "天气是⋯⋯"}', 47, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3246, 61, '{"english": "Read and write.", "chinese": "读一读，写一写。"}', 48, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3247, 61, '{"english": "1. ''It''s time for PE,'' says the ______.", "chinese": "1. “—该上体育课了，”______说。"}', 49, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3248, 61, '{"english": "''Let''s get a ______.''", "chinese": "“让我们来______。”"}', 50, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3249, 61, '{"english": "2. ''My mother''s a ______,'' says the boy.", "chinese": "2. “我的母亲是一个 ______，”男孩说。"}', 51, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3250, 61, '{"english": "''She drives a red ______.''", "chinese": "“她开一辆红色的 ______。”"}', 52, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3251, 61, '{"english": "Circle the big letters.", "chinese": "圈出大写字母。"}', 53, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3252, 61, '{"english": "Read and circle.", "chinese": "读一读，圈一圈。"}', 54, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3253, 61, '{"english": "It is 6 o''clock. It is sunny outside.", "chinese": "现在 6 点。外面天气晴朗。"}', 55, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3254, 61, '{"english": "I get up and have breakfast.", "chinese": "我起床吃早饭。"}', 56, '2026-02-05 03:57:27', '2026-02-05 03:57:27');
INSERT INTO "course_content" VALUES (3255, 61, '{"english": "It is 7:30.", "chinese": "现在是 7:30。"}', 57, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3256, 61, '{"english": "I go to school. It is cloudy now.", "chinese": "我去上学。现在是多云。"}', 58, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3257, 61, '{"english": "It is 9 o''clock. I go to Chinese class.", "chinese": "现在是 9 点钟。我去上语文课。"}', 59, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3258, 61, '{"english": "It is cloudy and cold outside.", "chinese": "外面多云且冷。"}', 60, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3259, 61, '{"english": "It is 10 o''clock. I go to the library.", "chinese": "现在是 10 点钟。我去图书馆。"}', 61, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3260, 61, '{"english": "It is on the second floor.", "chinese": "它在二楼。"}', 62, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3261, 61, '{"english": "It is rainy outside. I have no umbrella!", "chinese": "外面下着雨。我没有伞！"}', 63, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3262, 61, '{"english": "It is 12 o''clock. I have lunch.", "chinese": "现在是 12 点。我吃午饭了。"}', 64, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3263, 61, '{"english": "It is still raining! But it is warm inside.", "chinese": "还在下雨！但是室内很暖和。"}', 65, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3264, 61, '{"english": "It is 3:15. I have PE class.", "chinese": "现在是 3:15。我在上体育课。"}', 66, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3265, 61, '{"english": "It is sunny again. We can go outside!", "chinese": "天又放晴了。我们可以出去了！"}', 67, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3266, 61, '{"english": "Unit Four", "chinese": "第四单元"}', 68, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3267, 61, '{"english": "How many horses do you have?", "chinese": "你有多少匹马？"}', 69, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3268, 61, '{"english": "Seventeen.", "chinese": "17 匹。"}', 70, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3269, 61, '{"english": "What are these? Are these potatoes?", "chinese": "这些是什么？这些是土豆吗？"}', 71, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3270, 61, '{"english": "Let me try one ... They''re carrots.", "chinese": "让我尝一个⋯⋯它们是胡萝卜。"}', 72, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3271, 61, '{"english": "At the farm", "chinese": "在农场"}', 73, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3272, 61, '{"english": "What are those?", "chinese": "那些是什么？"}', 74, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3273, 61, '{"english": "They''re sheep. Let me count ...", "chinese": "它们是绵羊。让我数一数⋯⋯"}', 75, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3274, 61, '{"english": "Oh, I feel sleepy.", "chinese": "哦，我困了。"}', 76, '2026-02-05 03:57:28', '2026-02-05 03:57:28');
INSERT INTO "course_content" VALUES (3275, 62, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3276, 62, '{"english": "Look at these! Are these carrots?", "chinese": "看看这些！这些是胡萝卜吗？"}', 2, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3277, 62, '{"english": "Yes, they are.", "chinese": "是的。"}', 3, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3278, 62, '{"english": "Wow! They''re so big!", "chinese": "哇！它们那么大！"}', 4, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3279, 62, '{"english": "What are these?", "chinese": "这些是什么？"}', 5, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3280, 62, '{"english": "They''re tomatoes.", "chinese": "它们是西红柿。"}', 6, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3281, 62, '{"english": "But they''re yellow!", "chinese": "但它们是黄色的！"}', 7, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3282, 62, '{"english": "Try some! They''re good.", "chinese": "尝一些吧！它们很好吃的。"}', 8, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3283, 62, '{"english": "Thanks. Yum.", "chinese": "谢谢。真好吃。"}', 9, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3284, 62, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 10, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3285, 62, '{"english": "What are these?", "chinese": "这些是什么？"}', 11, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3286, 62, '{"english": "Are they tomatoes?", "chinese": "它们是西红柿吗？"}', 12, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3287, 62, '{"english": "No.", "chinese": "不是。"}', 13, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3288, 62, '{"english": "Are they apples?", "chinese": "它们是苹果吗？"}', 14, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3289, 62, '{"english": "Yes!", "chinese": "是的！"}', 15, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3290, 62, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 16, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3291, 62, '{"english": "Look at the green beans. They''re so long!", "chinese": "看看这些豆角。它们好长！"}', 17, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3292, 62, '{"english": "Yes, and the potatoes are big.", "chinese": "是的，土豆也很大。"}', 18, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3293, 62, '{"english": "tomatoes", "chinese": "西红柿"}', 19, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3294, 62, '{"english": "green beans", "chinese": "豆角；四季豆"}', 20, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3295, 62, '{"english": "potatoes", "chinese": "马铃薯；土豆"}', 21, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3296, 62, '{"english": "carrots", "chinese": "胡萝卜"}', 22, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3297, 62, '{"english": "Let''s chant", "chinese": "让我们唱一唱"}', 23, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3298, 62, '{"english": "I like tomatoes.  I like potatoes.", "chinese": "我喜欢西红柿。 我喜欢土豆。"}', 24, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3299, 62, '{"english": "Carrots I will try.  I love to eat green beans.", "chinese": "我会尝试一下胡萝卜。 我喜欢吃豆角。"}', 25, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3300, 62, '{"english": "But onions make me cry.  I like tomatoes.", "chinese": "但是洋葱会使我哭泣。 我喜欢西红柿。"}', 26, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3301, 62, '{"english": "I like potatoes.  Carrots I will try.", "chinese": "我喜欢土豆。 我会尝试一下胡萝卜。"}', 27, '2026-02-05 03:57:30', '2026-02-05 03:57:30');
INSERT INTO "course_content" VALUES (3302, 62, '{"english": "I love to eat green beans.  But onions make me cry.", "chinese": "我喜欢吃豆角。 但是洋葱会使我哭泣。"}', 28, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3303, 62, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 29, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3304, 62, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 30, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3305, 62, '{"english": "horse", "chinese": "马"}', 31, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3306, 62, '{"english": "fork", "chinese": "叉子"}', 32, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3307, 62, '{"english": "homework", "chinese": "家庭作业"}', 33, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3308, 62, '{"english": "world map", "chinese": "世界地图"}', 34, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3309, 62, '{"english": "Let''s chant.  I like to read the story.", "chinese": "让我们一起唱吧。 我喜欢读这个故事。"}', 35, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3310, 62, '{"english": "The story about the horse.", "chinese": "关于马的故事。"}', 36, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3311, 62, '{"english": "The horse likes to work.  He works hard of course.", "chinese": "这匹马喜欢工作。 当然，他工作很努力。"}', 37, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3312, 62, '{"english": "I like to read the story.  The story about the horse.", "chinese": "我喜欢读这个故事。 关于马的故事。"}', 38, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3313, 62, '{"english": "The horse likes to work.  He works hard of course.", "chinese": "这匹马喜欢工作。 当然，他工作很努力。"}', 39, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3314, 62, '{"english": "Read, listen and number.", "chinese": "读一读，听一听，并编号。"}', 40, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3315, 62, '{"english": "1. fork  2. world  3. born", "chinese": "1. 叉子 2. 世界 3. 出生"}', 41, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3316, 62, '{"english": "4. for  5. work  6. horse", "chinese": "4. 为 5. 工作 6. 马"}', 42, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3317, 62, '{"english": "Look, listen and write.", "chinese": "看一看，听一听，写一写。"}', 43, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3318, 62, '{"english": "I''d like four forks.", "chinese": "我想要四把叉子。"}', 44, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3319, 62, '{"english": "This is her homework.", "chinese": "这是她的家庭作业。"}', 45, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3320, 62, '{"english": "I like horses.", "chinese": "我喜欢马。"}', 46, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3321, 62, '{"english": "Welcome to my farm, children.", "chinese": "欢迎来到我的农场，孩子们。"}', 47, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3322, 62, '{"english": "Let''s look at the animals and vegetables.", "chinese": "让我们看看动物和蔬菜。"}', 48, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3323, 62, '{"english": "1. —Are those hens?", "chinese": "1. ——那些是母鸡吗？"}', 49, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3324, 62, '{"english": "—Yes, they are. I have twenty hens here.", "chinese": "——是的。我这里有二十只母鸡。"}', 50, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3325, 62, '{"english": "2. —What are these?", "chinese": "2. ——这些是什么？"}', 51, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3326, 62, '{"english": "—They''re my potatoes.", "chinese": "——它们是我的土豆。"}', 52, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3327, 62, '{"english": "3. —Are those horses over there?", "chinese": "3. ——那边的那些是马吗？"}', 53, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3328, 62, '{"english": "—No. They are baby cows.", "chinese": "——不，它们是小奶牛。"}', 54, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3329, 62, '{"english": "4. —What are those?", "chinese": "4. ——那些是什么？"}', 55, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3330, 62, '{"english": "Are they apples? —No. They are tomatoes.", "chinese": "它们是苹果吗？ ——不，它们是西红柿。"}', 56, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3331, 62, '{"english": "Look and match.", "chinese": "看一看，连一连。"}', 57, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3332, 62, '{"english": "Sheep, cows and horses.  Tomatoes, carrots and green beans.", "chinese": "绵羊、奶牛和马。 西红柿、胡萝卜和豆角。"}', 58, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3333, 62, '{"english": "Cows, sheep and hens.  Green beans, tomatoes and carrots.", "chinese": "奶牛、绵羊和母鸡。 豆角、西红柿和胡萝卜。"}', 59, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3334, 62, '{"english": "Let''s sing", "chinese": "让我们唱一唱"}', 60, '2026-02-05 03:57:31', '2026-02-05 03:57:31');
INSERT INTO "course_content" VALUES (3335, 62, '{"english": "Mary has a little lamb", "chinese": "玛丽有一只小羊羔"}', 61, '2026-02-05 03:57:32', '2026-02-05 03:57:32');
INSERT INTO "course_content" VALUES (3336, 62, '{"english": "Mary has a little lamb, little lamb, little lamb.", "chinese": "玛丽有一只小羊羔，小羊羔，小羊羔。"}', 62, '2026-02-05 04:00:06', '2026-02-05 04:00:06');
INSERT INTO "course_content" VALUES (3337, 62, '{"english": "Mary has a little lamb.", "chinese": "玛丽有一只小羊羔。"}', 63, '2026-02-05 04:00:06', '2026-02-05 04:00:06');
INSERT INTO "course_content" VALUES (3338, 62, '{"english": "Its fleece is white as snow.", "chinese": "它的羊毛洁白如雪。"}', 64, '2026-02-05 04:00:06', '2026-02-05 04:00:06');
INSERT INTO "course_content" VALUES (3339, 62, '{"english": "Everywhere that Mary goes, Mary goes, Mary goes,   Everywhere that Mary goes, the lamb is sure to go.", "chinese": "无论玛丽去哪里，去哪里，去哪里，  无论玛丽去哪里，羊羔都会去。"}', 65, '2026-02-05 04:00:06', '2026-02-05 04:00:06');
INSERT INTO "course_content" VALUES (3340, 125, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3341, 125, '{"english": "OK. It''s four o''clock. It''s time to go home!", "chinese": "好了。四点了。该回家了！"}', 2, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3342, 125, '{"english": "Amy, are these yours?", "chinese": "埃米，这些是你的吗？"}', 3, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3343, 125, '{"english": "No, they aren''t. My shoes are green. They''re Chen Jie''s.", "chinese": "不，不是我的。我的鞋子是绿色的。它们是陈杰的。"}', 4, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3344, 125, '{"english": "What about this hat? Is this John''s?", "chinese": "这顶帽子呢？这是约翰的吗？"}', 5, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3345, 125, '{"english": "No, it isn''t. It''s Mike''s.", "chinese": "不是。它是迈克的。"}', 6, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3346, 125, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 7, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3347, 125, '{"english": "Are these yours, Mike?", "chinese": "这些是你的吗，迈克？"}', 8, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3348, 125, '{"english": "Yes, they are.", "chinese": "是的，它们是。"}', 9, '2026-02-05 04:00:07', '2026-02-05 04:00:07');
INSERT INTO "course_content" VALUES (3349, 125, '{"english": "Is this John''s?", "chinese": "这是约翰的吗？"}', 10, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3350, 125, '{"english": "No, it isn''t. It''s Wu Binbin''s.", "chinese": "不，它不是。它是吴斌斌的。"}', 11, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3351, 125, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 12, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3352, 125, '{"english": "I like that green skirt.", "chinese": "我喜欢那条绿色的裙子。"}', 13, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3353, 125, '{"english": "Me too. And I like those pants.", "chinese": "我也喜欢。我还喜欢那条裤子。"}', 14, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3354, 125, '{"english": "clothes", "chinese": "衣服；服装"}', 15, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3355, 125, '{"english": "hat", "chinese": "（常指带檐的）帽子"}', 16, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3356, 125, '{"english": "skirt", "chinese": "女裙"}', 17, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3357, 125, '{"english": "pants", "chinese": "裤子"}', 18, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3358, 125, '{"english": "dress", "chinese": "连衣裙"}', 19, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3359, 125, '{"english": "Let''s do", "chinese": "让我们做一做"}', 20, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3360, 125, '{"english": "Put on your shirt.", "chinese": "穿上你的衬衫。"}', 21, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3361, 125, '{"english": "Hang up your dress.", "chinese": "挂起你的连衣裙。"}', 22, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3362, 125, '{"english": "Take off your hat.", "chinese": "摘下你的帽子。"}', 23, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3363, 125, '{"english": "Wash your skirt.", "chinese": "洗洗你的短裙。"}', 24, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3364, 125, '{"english": "Put away your pants.", "chinese": "收好你的裤子。"}', 25, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3365, 125, '{"english": "Put on your shirt.  Hang up your dress.", "chinese": "穿上你的衬衫。 挂起你的连衣裙。"}', 26, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3366, 125, '{"english": "Take off your hat.  Wash your skirt.  Put away your pants.", "chinese": "摘下你的帽子。 洗洗你的短裙。 收好你的裤子。"}', 27, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3367, 125, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 28, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3368, 125, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 29, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3369, 125, '{"english": "apple", "chinese": "苹果"}', 30, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3370, 125, '{"english": "people", "chinese": "人们"}', 31, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3371, 125, '{"english": "table", "chinese": "桌子"}', 32, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3372, 125, '{"english": "Oh, it''s time to pack my clothes.", "chinese": "哦，该收拾我的衣服了。"}', 33, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3373, 125, '{"english": "This is my red T-shirt.  These are my blue pants.", "chinese": "这是我的红色 T 恤衫。 这是我的蓝色裤子。"}', 34, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3374, 125, '{"english": "And those are my shoes.  Wait! Is this my hat?", "chinese": "那些是我的鞋子。 等等！这是我的帽子吗？"}', 35, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3375, 125, '{"english": "No, this is Amy''s.  Amy! Is this yours?", "chinese": "不，这是艾米的。 艾米！这是你的吗？"}', 36, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3376, 125, '{"english": "1. Are these Sarah''s blue pants?    A. Yes. B. No.", "chinese": "1. 这是萨拉的蓝色裤子吗？ A. 是。 B. 不是。"}', 37, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3377, 125, '{"english": "2. This is Amy''s red T-shirt.     A. Yes. B. No.", "chinese": "2. 这是埃米的红色 T 恤衫。     A. 是。 B. 不是。"}', 38, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3378, 125, '{"english": "3. Whose shoes are these?   A. Amy''s. B. Sarah''s.", "chinese": "3. 这双鞋是谁的？    A. 埃米的。 B. 萨拉的。"}', 39, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3379, 125, '{"english": "4. Whose hat is this?     A. Amy''s. B. Sarah''s.", "chinese": "4. 这顶帽子是谁的？   A. 埃米的。B. 萨拉的。"}', 40, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3380, 125, '{"english": "Look and write.", "chinese": "看一看，写一写。"}', 41, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3381, 125, '{"english": "These are John''s shoes.", "chinese": "这是约翰的鞋。"}', 42, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3382, 125, '{"english": "This is Chen Jie''s dress.", "chinese": "这是陈杰的连衣裙。"}', 43, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3383, 125, '{"english": "Draw your pants and write a sentence.", "chinese": "画出你的裤子并写一句话。"}', 44, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3384, 125, '{"english": "Let''s check", "chinese": "让我们来测一测"}', 45, '2026-02-05 04:00:08', '2026-02-05 04:00:08');
INSERT INTO "course_content" VALUES (3385, 126, '{"english": "A. Let''s talk", "chinese": "A. 让我们说一说"}', 1, '2026-02-05 04:00:09', '2026-02-05 04:00:09');
INSERT INTO "course_content" VALUES (3386, 126, '{"english": "Can I help you?", "chinese": "我能为您做点什么？"}', 2, '2026-02-05 04:00:09', '2026-02-05 04:00:09');
INSERT INTO "course_content" VALUES (3387, 126, '{"english": "Yes. These shoes are nice.", "chinese": "是的。这双鞋不错。"}', 3, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3388, 126, '{"english": "Can I try them on? Size 6, please.", "chinese": "我可以试一下吗？请给我拿 6 号的。"}', 4, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3389, 126, '{"english": "Of course. Here you are.", "chinese": "当然。给你。"}', 5, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3390, 126, '{"english": "John, are they OK?", "chinese": "约翰，合适吗？"}', 6, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3391, 126, '{"english": "No. They''re too small.", "chinese": "不行。它们太小了。"}', 7, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3392, 126, '{"english": "Hmm. OK. Let''s try size 7.", "chinese": "嗯，好的。让我们试试 7 号。"}', 8, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3393, 126, '{"english": "They''re just right!", "chinese": "它们正合适！"}', 9, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3394, 126, '{"english": "Good!", "chinese": "不错！"}', 10, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3395, 126, '{"english": "Let''s play", "chinese": "让我们玩一玩"}', 11, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3396, 126, '{"english": "Can I help you?", "chinese": "我能为您做点什么？"}', 12, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3397, 126, '{"english": "Yes. Can I try these on?", "chinese": "是的。我可以试试这些吗？"}', 13, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3398, 126, '{"english": "OK. Here you are.", "chinese": "好的。给你。"}', 14, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3399, 126, '{"english": "Oh, they''re too big!", "chinese": "哦，它们太大了！"}', 15, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3400, 126, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 16, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3401, 126, '{"english": "Can I help you?", "chinese": "我能为您做点什么？"}', 17, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3402, 126, '{"english": "The gloves are nice. Can I try them on?", "chinese": "这手套不错。我可以试一下吗？"}', 18, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3403, 126, '{"english": "Sure.", "chinese": "当然。"}', 19, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3404, 126, '{"english": "gloves", "chinese": "（分手指的）手套"}', 20, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3405, 126, '{"english": "sunglasses", "chinese": "太阳镜"}', 21, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3406, 126, '{"english": "umbrella", "chinese": "伞；雨伞"}', 22, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3407, 126, '{"english": "scarf", "chinese": "围巾；披巾"}', 23, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3408, 126, '{"english": "Complete and say", "chinese": "补充下面的内容，并说一说"}', 24, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3409, 126, '{"english": "It''s hot, so I put on my T-shirt.", "chinese": "天气很热，所以我穿上 T 恤衫。"}', 25, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3410, 126, '{"english": "T-shirt", "chinese": "T 恤衫"}', 26, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3411, 126, '{"english": "socks", "chinese": "短袜"}', 27, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3412, 126, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 28, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3413, 126, '{"english": "Read aloud.", "chinese": "大声朗读。"}', 29, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3414, 126, '{"english": "computer", "chinese": "电脑"}', 30, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3415, 126, '{"english": "dinner", "chinese": "（中午或晚上吃的）正餐"}', 31, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3416, 126, '{"english": "girl", "chinese": "女孩"}', 32, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3417, 126, '{"english": "wall", "chinese": "墙"}', 33, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3418, 126, '{"english": "homework", "chinese": "家庭作业"}', 34, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3419, 126, '{"english": "nurse", "chinese": "护士"}', 35, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3420, 126, '{"english": "card", "chinese": "卡片"}', 36, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3421, 126, '{"english": "What?", "chinese": "什么？"}', 37, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3422, 126, '{"english": "Who?", "chinese": "谁？"}', 38, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3423, 126, '{"english": "How much?", "chinese": "多少钱？"}', 39, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3424, 126, '{"english": "a pretty dress", "chinese": "一条漂亮的连衣裙"}', 40, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
