INSERT INTO "course_content" VALUES (3430, 126, '{"english": "￥50", "chinese": "50 元"}', 46, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3431, 126, '{"english": "￥40", "chinese": "40 元"}', 47, '2026-02-05 04:00:10', '2026-02-05 04:00:10');
INSERT INTO "course_content" VALUES (3432, 126, '{"english": "￥5", "chinese": "5 元"}', 48, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
