INSERT INTO "course_content" VALUES (3434, 126, '{"english": "Read and write", "chinese": "读一读，写一写"}', 50, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3435, 126, '{"english": "Read and answer.", "chinese": "读一读，答一答。"}', 51, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3436, 126, '{"english": "SALE!", "chinese": "打折促销！"}', 52, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3437, 126, '{"english": "Today all sunglasses and gloves are five yuan!", "chinese": "今天所有的太阳镜和手套都是五元！"}', 53, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3438, 126, '{"english": "They are very cheap.", "chinese": "它们很便宜。"}', 54, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3439, 126, '{"english": "We have many nice scarves, too — red, yellow, brown and more!", "chinese": "我们也有许多漂亮的围巾——红的、黄的、棕色的，还有更多！"}', 55, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3440, 126, '{"english": "Umbrellas are cheap, too.", "chinese": "雨伞也很便宜。"}', 56, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3441, 126, '{"english": "We have many pretty colours for you.", "chinese": "我们有很多种漂亮的颜色供你选择。"}', 57, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3442, 126, '{"english": "Come and see us today!", "chinese": "今天过来看看吧！"}', 58, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3443, 126, '{"english": "1. How much is the red scarf?  It''s ______ yuan.", "chinese": "1. 这条红围巾多少钱？ 它是______元。"}', 59, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3444, 126, '{"english": "2. How much are the brown gloves?  They''re ______ yuan.", "chinese": "2. 棕色手套多少钱？ 它们______元。"}', 60, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3445, 126, '{"english": "3. Is the umbrella too expensive? ______", "chinese": "3. 这把伞太贵了吗？ ______"}', 61, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3446, 126, '{"english": "4. Are the sunglasses cheap?  ______", "chinese": "4. 太阳镜便宜吗？ ______"}', 62, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3447, 126, '{"english": "Look and write.", "chinese": "看一看，写一写。"}', 63, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3448, 126, '{"english": "￥500", "chinese": "500 元"}', 64, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3449, 126, '{"english": "They are very expensive.", "chinese": "它们很贵。"}', 65, '2026-02-05 04:00:11', '2026-02-05 04:00:11');
INSERT INTO "course_content" VALUES (3450, 127, '{"english": "Recycle 2", "chinese": "复习 2"}', 1, '2026-02-05 04:00:12', '2026-02-05 04:00:12');
INSERT INTO "course_content" VALUES (3451, 127, '{"english": "Read aloud.", "chinese": "大声朗读。"}', 2, '2026-02-05 04:00:12', '2026-02-05 04:00:12');
INSERT INTO "course_content" VALUES (3452, 127, '{"english": "Tomorrow will be warm and sunny.", "chinese": "明天天气将温暖晴朗。"}', 3, '2026-02-05 04:00:12', '2026-02-05 04:00:12');
INSERT INTO "course_content" VALUES (3453, 127, '{"english": "Let''s have a picnic tomorrow.", "chinese": "我们明天去野餐吧。"}', 4, '2026-02-05 04:00:12', '2026-02-05 04:00:12');
INSERT INTO "course_content" VALUES (3454, 127, '{"english": "Yeah!", "chinese": "好啊！"}', 5, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3455, 127, '{"english": "Can I help you?", "chinese": "我能为您做点什么吗？"}', 6, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3456, 127, '{"english": "Yes, five tomatoes and two carrots, please.", "chinese": "是的，请给我五个西红柿和两根胡萝卜。"}', 7, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3457, 127, '{"english": "Three bananas and two apples, please. How much is that?", "chinese": "请给我三根香蕉和两个苹果。那要多少钱？"}', 8, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3458, 127, '{"english": "That''s 42 yuan in total.", "chinese": "一共是 42 元。"}', 9, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3459, 127, '{"english": "That''s expensive!", "chinese": "太贵了！"}', 10, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3460, 127, '{"english": "That jacket is cool! Whose is it?", "chinese": "那件夹克很酷！它是谁的？"}', 11, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3461, 127, '{"english": "It''s Sarah''s. I like it, too.", "chinese": "是萨拉的。我也喜欢它。"}', 12, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3462, 127, '{"english": "Are those cows? They look hungry.", "chinese": "那些是奶牛吗？它们看起来很饿。"}', 13, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3463, 127, '{"english": "Whose tomatoes are those?", "chinese": "那些西红柿是谁的？"}', 14, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3464, 127, '{"english": "Moo.", "chinese": "哞。"}', 15, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3465, 127, '{"english": "They''re Sarah''s! Quick!", "chinese": "它们是萨拉的！快点！"}', 16, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3466, 127, '{"english": "FINISH THE STORY!", "chinese": "故事结束！"}', 17, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3467, 127, '{"english": "Can you act it out?", "chinese": "你能演一演吗？"}', 18, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3468, 127, '{"english": "Listen and tick (√).", "chinese": "听一听，勾一勾。"}', 19, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3469, 127, '{"english": "Conversation 1:", "chinese": "对话 1："}', 20, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3470, 127, '{"english": "—Welcome. How can I help you?", "chinese": "——欢迎。我能帮你什么忙吗？"}', 21, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3471, 127, '{"english": "—Hi, I''d like to buy some gloves. Where are they?", "chinese": "——嗨，我想买一些手套。它们在哪里？"}', 22, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3472, 127, '{"english": "—They''re on the second floor. This way, please.", "chinese": "——它们在二楼。请这边走。"}', 23, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3473, 127, '{"english": "—What colours do you have?", "chinese": "——你们有什么颜色的？"}', 24, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3474, 127, '{"english": "—We have blue gloves.", "chinese": "——我们有蓝色的手套。"}', 25, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3475, 127, '{"english": "—Do you have red gloves?", "chinese": "——你有红手套吗？"}', 26, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3476, 127, '{"english": "—No, sir.", "chinese": "——没有，先生。"}', 27, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3477, 127, '{"english": "—Welcome. How can I help you?", "chinese": "——欢迎。我能帮你什么忙吗？"}', 28, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3478, 127, '{"english": "—Hi, I''d like to buy some gloves. Where are they?", "chinese": "——嗨，我想买一些手套。它们在哪里？"}', 29, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3479, 127, '{"english": "—They''re on the second floor. This way, please.", "chinese": "——它们在二楼。请这边走。"}', 30, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3480, 127, '{"english": "—What colours do you have?", "chinese": "———你们有什么颜色的？"}', 31, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3481, 127, '{"english": "—We have blue gloves.", "chinese": "——我们有蓝色的手套。"}', 32, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3482, 127, '{"english": "—Do you have red gloves?", "chinese": "——你有红手套吗？"}', 33, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3483, 127, '{"english": "—No, sir.", "chinese": "——没有，先生。"}', 34, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3484, 127, '{"english": "Conversation 2:", "chinese": "对话 2："}', 35, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3485, 127, '{"english": "—Hi, can I try on some hats, please?", "chinese": "——嗨，我能试一些帽子吗？"}', 36, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3486, 127, '{"english": "—Of course. How about these?", "chinese": "——当然。这些怎么样？"}', 37, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3487, 127, '{"english": "—All those hats?", "chinese": "——那些是帽子吗？"}', 38, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3488, 127, '{"english": "—Yes, they are. They''re summer hats.", "chinese": "——是的。它们是夏天的帽子。"}', 39, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3489, 127, '{"english": "—It''s cold and snowy outside now. I need a warm hat.", "chinese": "——现在外面又冷又下雪。我需要一顶暖和的帽子。"}', 40, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3490, 127, '{"english": "—How about this?", "chinese": "——这个怎么样？"}', 41, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3491, 127, '{"english": "—Great. I like red. How much is it?", "chinese": "——太棒了。我喜欢红色。多少钱？"}', 42, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3492, 127, '{"english": "—Ten yuan.", "chinese": "——十元。"}', 43, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3493, 127, '{"english": "—That''s cheap. Here you are. Ten yuan.", "chinese": "——那很便宜。给你十元。"}', 44, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3494, 127, '{"english": "—Hi, can I try on some hats, please?", "chinese": "——嗨，我能试一些帽子吗？"}', 45, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3495, 127, '{"english": "—Of course. How about these?", "chinese": "——当然。这些怎么样？"}', 46, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3496, 127, '{"english": "—All those hats?", "chinese": "——那些是帽子吗？"}', 47, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3497, 127, '{"english": "—Yes, they are. They''re summer hats.", "chinese": "——是的。它们是夏天的帽子。"}', 48, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3498, 127, '{"english": "—It''s cold and snowy outside now. I need a warm hat.", "chinese": "——现在外面又冷又下雪。我需要一顶暖和的帽子。"}', 49, '2026-02-05 04:00:13', '2026-02-05 04:00:13');
INSERT INTO "course_content" VALUES (3499, 127, '{"english": "—How about this?", "chinese": "——这个怎么样？"}', 50, '2026-02-05 04:00:14', '2026-02-05 04:00:14');
INSERT INTO "course_content" VALUES (3500, 127, '{"english": "—Great. I like red. How much is it?", "chinese": "——太棒了。我喜欢红色。多少钱？"}', 51, '2026-02-05 04:00:14', '2026-02-05 04:00:14');
INSERT INTO "course_content" VALUES (3501, 127, '{"english": "—Ten yuan.", "chinese": "——十元。"}', 52, '2026-02-05 04:00:14', '2026-02-05 04:00:14');
INSERT INTO "course_content" VALUES (3502, 127, '{"english": "—That''s cheap. Here you are. Ten yuan.", "chinese": "——那很便宜。给你十元。"}', 53, '2026-02-05 04:00:14', '2026-02-05 04:00:14');
