INSERT INTO "course_content" VALUES (3647, 130, '{"english": "Useful expressions", "chinese": "常用表达法"}', 1, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3648, 130, '{"english": "Unit 1", "chinese": "第一单元"}', 2, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3649, 130, '{"english": "Where''s the teachers'' office?", "chinese": "教师办公室在哪里？"}', 3, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3650, 130, '{"english": "It''s on the second floor.", "chinese": "它在二楼。"}', 4, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3651, 130, '{"english": "Is this the teachers'' office?", "chinese": "这是教师办公室吗？"}', 5, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3652, 130, '{"english": "No, it isn''t.", "chinese": "不，不是。"}', 6, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3653, 130, '{"english": "The teachers'' office is next to the library.", "chinese": "教师办公室在图书馆旁边。"}', 7, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3654, 130, '{"english": "Is that the computer room?", "chinese": "那是计算机房吗？"}', 8, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3655, 130, '{"english": "Do you have a library?", "chinese": "你们（学校）有图书馆吗？"}', 9, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3656, 130, '{"english": "Yes, we do.", "chinese": "是的，有。"}', 10, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3657, 130, '{"english": "Unit 2", "chinese": "第二单元"}', 11, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3658, 130, '{"english": "What time is it?", "chinese": "几点了？"}', 12, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3659, 130, '{"english": "It''s 6 o''clock. It''s time for dinner.", "chinese": "六点了。该吃晚饭了。"}', 13, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3660, 130, '{"english": "Time to go home, kids.", "chinese": "该回家了，孩子们。"}', 14, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3661, 130, '{"english": "It''s time to get up.", "chinese": "该起床了。"}', 15, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3662, 130, '{"english": "Unit 3", "chinese": "第三单元"}', 16, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3663, 130, '{"english": "Can I go outside now?", "chinese": "现在我能出去吗？"}', 17, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3664, 130, '{"english": "It''s cold outside.", "chinese": "外面冷。"}', 18, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3665, 130, '{"english": "Yes, you can. / No, you can''t.", "chinese": "可以。/ 不行。"}', 19, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3666, 130, '{"english": "What''s the weather like in New York?", "chinese": "纽约天气怎么样？"}', 20, '2026-02-05 04:00:20', '2026-02-05 04:00:20');
INSERT INTO "course_content" VALUES (3667, 130, '{"english": "It''s rainy.", "chinese": "是下雨天。"}', 21, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3668, 130, '{"english": "Is it cold?", "chinese": "天冷吗？"}', 22, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3669, 130, '{"english": "No, it isn''t.", "chinese": "不，不冷。"}', 23, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3670, 130, '{"english": "It''s 26 degrees.", "chinese": "是 26 度。"}', 24, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3671, 130, '{"english": "Unit 4", "chinese": "第四单元"}', 25, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3672, 130, '{"english": "Are these carrots?", "chinese": "这些是胡萝卜吗？"}', 26, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3673, 130, '{"english": "Yes, they are.", "chinese": "是的。"}', 27, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3674, 130, '{"english": "What are these?", "chinese": "这些是什么？"}', 28, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3675, 130, '{"english": "They''re tomatoes.", "chinese": "它们是西红柿。"}', 29, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3676, 130, '{"english": "What are those?", "chinese": "那些是什么？"}', 30, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3677, 130, '{"english": "They''re horses.", "chinese": "它们是马。"}', 31, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3678, 130, '{"english": "Are they hens?", "chinese": "它们是母鸡吗？"}', 32, '2026-02-05 04:00:21', '2026-02-05 04:00:21');
INSERT INTO "course_content" VALUES (3679, 131, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3680, 131, '{"english": "Wu Binbin and Oliver see Mr Li.", "chinese": "吴斌斌和奥利弗看见了李老师。"}', 2, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3681, 131, '{"english": "Look at the pictures below. Listen and tick.", "chinese": "看下列图片。听一听并打勾。"}', 3, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3682, 131, '{"english": "-Look! That''s Mr Li, our maths teacher.", "chinese": "—看，那是李老师，我们的数学老师。"}', 4, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3683, 131, '{"english": "-He''s so strong.  -Yes, he''s a good basketball player.", "chinese": "—他很强壮。 —是的，他是个优秀的篮球运动员。"}', 5, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3684, 131, '{"english": "-Cool! Is he strict?  -Yes, sometimes.  Who is Mr Li?", "chinese": "—酷！他严格吗？ —是的，有时候很严格。 谁是李老师？"}', 6, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3685, 131, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3686, 131, '{"english": "Do you know Mr Young?", "chinese": "你认识杨老师吗？"}', 8, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3687, 131, '{"english": "No, I don''t. Who is he?", "chinese": "不，我不认识。他是谁？"}', 9, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3688, 131, '{"english": "He''s our music teacher.", "chinese": "他是我们的音乐老师。"}', 10, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3689, 131, '{"english": "Is he young?", "chinese": "他年轻吗？"}', 11, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3690, 131, '{"english": "No, he isn''t. He''s old.", "chinese": "不，他不年轻。他比较年长。"}', 12, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3691, 131, '{"english": "Is he funny?", "chinese": "他有趣吗？"}', 13, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3692, 131, '{"english": "Yes, he is.", "chinese": "是的，他很有趣。"}', 14, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3693, 131, '{"english": "Great! I like funny teachers.", "chinese": "太棒了！我喜欢有趣的老师。"}', 15, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3694, 131, '{"english": "Talk about your teachers.", "chinese": "谈谈你的老师。"}', 16, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3695, 131, '{"english": "Miss White", "chinese": "怀特老师"}', 17, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3696, 131, '{"english": "English teacher", "chinese": "英语老师"}', 18, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3697, 131, '{"english": "tall", "chinese": "高的"}', 19, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3698, 131, '{"english": "friendly", "chinese": "友好的"}', 20, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3699, 131, '{"english": "quiet", "chinese": "安静的"}', 21, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3700, 131, '{"english": "funny", "chinese": "有趣的"}', 22, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3701, 131, '{"english": "young", "chinese": "年轻的"}', 23, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3702, 131, '{"english": "old", "chinese": "老的"}', 24, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3703, 131, '{"english": "Who''s your English teacher?", "chinese": "你的英语老师是谁？"}', 25, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3704, 131, '{"english": "Miss White.", "chinese": "怀特老师。"}', 26, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3705, 131, '{"english": "Is she kind?", "chinese": "她和蔼吗？"}', 27, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3706, 131, '{"english": "Yes, she is.", "chinese": "是的，她很和蔼。"}', 28, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3707, 131, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 29, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3708, 131, '{"english": "Who''s your art teacher?", "chinese": "你的美术老师是谁？"}', 30, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3709, 131, '{"english": "Mr Jones.", "chinese": "琼斯老师。"}', 31, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3710, 131, '{"english": "Is he young?", "chinese": "他年轻吗？"}', 32, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3711, 131, '{"english": "Yes, he is.", "chinese": "是的，他很年轻。"}', 33, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3712, 131, '{"english": "Mr Young  music teacher", "chinese": "杨老师 音乐老师"}', 34, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3713, 131, '{"english": "old", "chinese": "老的；年纪大的"}', 35, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3714, 131, '{"english": "Mr Jones  art teacher", "chinese": "琼斯老师 美术老师"}', 36, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3715, 131, '{"english": "young", "chinese": "年轻的"}', 37, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3716, 131, '{"english": "Miss Green  science teacher", "chinese": "格林老师 科学老师"}', 38, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3717, 131, '{"english": "funny", "chinese": "有趣的"}', 39, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3718, 131, '{"english": "Miss White English teacher", "chinese": "怀特老师 英语老师"}', 40, '2026-02-05 04:00:23', '2026-02-05 04:00:23');
INSERT INTO "course_content" VALUES (3719, 131, '{"english": "kind", "chinese": "和蔼的"}', 41, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3720, 131, '{"english": "Mr Li  maths teacher", "chinese": "李老师 数学老师"}', 42, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3721, 131, '{"english": "strict", "chinese": "严厉的"}', 43, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3722, 131, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 44, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3723, 131, '{"english": "Mrs Smith", "chinese": "史密斯老师"}', 45, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3724, 131, '{"english": "Who''s Mrs Smith?", "chinese": "史密斯老师是谁？"}', 46, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3725, 131, '{"english": "She''s the head teacher. She''s tall. She''s strict.", "chinese": "她是班主任。她很高。她很严厉。"}', 47, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3726, 131, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 48, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3727, 131, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 49, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3728, 131, '{"english": "No candy for the baby.", "chinese": "宝宝没糖吃。"}', 50, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3729, 131, '{"english": "No candy for the baby.  I am sorry, little baby.", "chinese": "宝宝没糖吃。 对不起，小宝宝。"}', 51, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3730, 131, '{"english": "But no candy for the baby.  No candy for the baby.", "chinese": "但是宝宝没糖吃。 宝宝没糖吃。"}', 52, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3731, 131, '{"english": "No candy for the baby.  I am sorry, little baby.", "chinese": "宝宝没糖吃。 对不起，小宝宝。"}', 53, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3732, 131, '{"english": "But no candy for the baby.   Now it''s your turn.", "chinese": "但是宝宝没糖吃。  现在轮到你了。"}', 54, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3733, 131, '{"english": "baby", "chinese": "婴儿"}', 55, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3734, 131, '{"english": "happy", "chinese": "高兴的"}', 56, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3735, 131, '{"english": "windy", "chinese": "有风的"}', 57, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3736, 131, '{"english": "sunny", "chinese": "晴朗的"}', 58, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3737, 131, '{"english": "sorry", "chinese": "对不起"}', 59, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3738, 131, '{"english": "Listen, number and say.", "chinese": "听录音，排序并说一说。"}', 60, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3739, 131, '{"english": "1. many  2. windy  3. candy  4. happy", "chinese": "1. 很多 2. 有风的 3. 糖果 4. 高兴的"}', 61, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3740, 131, '{"english": "5. sorry  6. sunny  7. baby  8. party  9. family", "chinese": "5. 对不起 6. 晴朗的 7. 婴儿 8. 派对 9. 家庭"}', 62, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3741, 131, '{"english": "Listen, write and say.", "chinese": "听一听，写一写，说一说。"}', 63, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3742, 131, '{"english": "The baby is happy.", "chinese": "这个婴儿很开心。"}', 64, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3743, 131, '{"english": "I like candy.", "chinese": "我喜欢吃糖果。"}', 65, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3744, 131, '{"english": "I am sorry.", "chinese": "我很抱歉。"}', 66, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3745, 131, '{"english": "Choose one sentence from above and write.", "chinese": "从上面选一个句子写下来。"}', 67, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3746, 131, '{"english": "What is Mr Grey like?", "chinese": "格雷老师是个什么样的人？"}', 68, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3747, 131, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 69, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3748, 131, '{"english": "Think and match.", "chinese": "想一想，连一连。"}', 70, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3749, 131, '{"english": "Choose and write.", "chinese": "选一选，写一写。"}', 71, '2026-02-05 04:00:24', '2026-02-05 04:00:24');
INSERT INTO "course_content" VALUES (3750, 131, '{"english": "I am helpful!", "chinese": "我乐于助人！"}', 72, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3751, 131, '{"english": "He is funny.", "chinese": "他很有趣。"}', 73, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3752, 131, '{"english": "She is kind.", "chinese": "她很友善。"}', 74, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3753, 131, '{"english": "It is small.", "chinese": "它很小。"}', 75, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3754, 131, '{"english": "They are old.", "chinese": "他们很老。"}', 76, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3755, 131, '{"english": "We are strong!", "chinese": "我们很强壮！"}', 77, '2026-02-05 04:00:25', '2026-02-05 04:00:25');
INSERT INTO "course_content" VALUES (3756, 132, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3757, 132, '{"english": "Listen and fill in the blank.", "chinese": "听一听，填一填。"}', 2, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3758, 132, '{"english": "-Good morning, John. What day is it today?", "chinese": "—早上好，约翰。今天是星期几？"}', 3, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3759, 132, '{"english": "-Wednesday.  -Oh, yes! What do you have on Wednesdays?", "chinese": "—星期三。 —哦，是的！你星期三有什么课？"}', 4, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3760, 132, '{"english": "-I have art. I really like it.", "chinese": "—我有美术课。我很喜欢美术课。"}', 5, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3761, 132, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 6, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3762, 132, '{"english": "Grandpa! Look at my picture.", "chinese": "爷爷！看我的照片。"}', 7, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3763, 132, '{"english": "Great! What do you have on Thursdays?", "chinese": "真棒！星期四你有什么课？"}', 8, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3764, 132, '{"english": "I have maths, English and music.", "chinese": "我有数学、英语和音乐课。"}', 9, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3765, 132, '{"english": "Oh, I love music! Who''s your music teacher?", "chinese": "哦，我喜欢音乐！谁是你的音乐老师？"}', 10, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3766, 132, '{"english": "Mr Young.", "chinese": "杨老师。"}', 11, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3767, 132, '{"english": "Is he strict?", "chinese": "他严格吗？"}', 12, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3768, 132, '{"english": "No. He''s funny. What do you do on Thursdays, Grandpa?", "chinese": "不。他很有趣。爷爷，你星期四做什么？"}', 13, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3769, 132, '{"english": "Oh, I have a cooking class with your grandma!", "chinese": "哦，我和你奶奶有一节烹饪课！"}', 14, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3770, 132, '{"english": "Haha!", "chinese": "哈哈！"}', 15, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3771, 132, '{"english": "What do we have on Wednesdays and Thursdays?", "chinese": "我们星期三和星期四有什么课？"}', 16, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
INSERT INTO "course_content" VALUES (3772, 132, '{"english": "What do we have on Wednesdays?", "chinese": "我们星期三有什么课？"}', 17, '2026-02-05 04:00:26', '2026-02-05 04:00:26');
