INSERT INTO "course_content" VALUES (3808, 132, '{"english": "Is it Monday?", "chinese": "是星期一吗？"}', 53, '2026-02-05 04:00:27', '2026-02-05 04:00:27');
INSERT INTO "course_content" VALUES (3809, 132, '{"english": "No.", "chinese": "不是。"}', 54, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
