INSERT INTO "course_content" VALUES (3820, 132, '{"english": "I like to read.  I like to eat.", "chinese": "我喜欢读书。 我喜欢吃东西。"}', 65, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3821, 132, '{"english": "I like to drink tea.  I like to repeat.", "chinese": "我喜欢喝茶。 我喜欢跟读。"}', 66, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3822, 132, '{"english": "I like to read.  I like to eat.", "chinese": "我喜欢读书。 我喜欢吃东西。"}', 67, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3823, 132, '{"english": "I like to drink tea.  I like to repeat.   Now it''s your turn.", "chinese": "我喜欢喝茶。 我喜欢跟读。  现在轮到你了。"}', 68, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3824, 132, '{"english": "Listen, repeat and circle.", "chinese": "听一听，跟读并圈出来。"}', 69, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3825, 132, '{"english": "1. read", "chinese": "1. 阅读"}', 70, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3826, 132, '{"english": "2. see", "chinese": "2. 看见"}', 71, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3827, 132, '{"english": "3. repeat", "chinese": "3. 重复"}', 72, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3828, 132, '{"english": "Listen, write and say.", "chinese": "听一听，写一写，说一说。"}', 73, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3829, 132, '{"english": "I like to read by the sea.", "chinese": "我喜欢在海边看书。"}', 74, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3830, 132, '{"english": "Have some beef and tea.", "chinese": "吃些牛肉喝些茶。"}', 75, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3831, 132, '{"english": "Feed the baby.", "chinese": "喂孩子。"}', 76, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3832, 132, '{"english": "Choose one sentence from above and write.", "chinese": "从上面选一个句子并写下来。"}', 77, '2026-02-05 04:00:28', '2026-02-05 04:00:28');
INSERT INTO "course_content" VALUES (3833, 132, '{"english": "1. Do you read books on the weekend?", "chinese": "1. 你周末看书吗？"}', 78, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3834, 132, '{"english": "Yes. / No.", "chinese": "看。/不看。"}', 79, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3835, 132, '{"english": "2. Do you watch TV on the weekend?", "chinese": "2. 你周末看电视吗？"}', 80, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3836, 132, '{"english": "Yes. / No.", "chinese": "看。/不看。"}', 81, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3837, 132, '{"english": "3. Do you wash your clothes on the weekend?", "chinese": "3. 你周末洗衣服吗？"}', 82, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3838, 132, '{"english": "Yes. / No.", "chinese": "洗。/不洗。"}', 83, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3839, 132, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 84, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3840, 132, '{"english": "Mon + day = Monday", "chinese": "星期一"}', 85, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3841, 132, '{"english": "bed + room = bedroom", "chinese": "卧室"}', 86, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3842, 132, '{"english": "Complete the words.", "chinese": "补全单词。"}', 87, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3843, 132, '{"english": "Saturday", "chinese": "星期六"}', 88, '2026-02-05 04:00:29', '2026-02-05 04:00:29');
INSERT INTO "course_content" VALUES (3844, 133, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3845, 133, '{"english": "Sarah is hungry. What would she like to eat?", "chinese": "萨拉饿了。她想要吃什么？"}', 2, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3846, 133, '{"english": "Listen and fill in the blanks.", "chinese": "听录音并填空。"}', 3, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3847, 133, '{"english": "-Mum, I''m hungry.  -What would you like to eat?", "chinese": "—妈妈，我饿了。 —你想吃什么？"}', 4, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3848, 133, '{"english": "-I''d like some bread and chicken, please.", "chinese": "—我想要一些面包和鸡肉。"}', 5, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3849, 133, '{"english": "-Here you are, dear. Have some chicken sandwiches.  -Thanks, Mum.", "chinese": "—给你，亲爱的。吃些鸡肉三明治。 —谢谢，妈妈。"}', 6, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3850, 133, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3851, 133, '{"english": "I''m hungry.", "chinese": "我饿了。"}', 8, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3852, 133, '{"english": "What would you like to eat?", "chinese": "你想吃什么？"}', 9, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3853, 133, '{"english": "A sandwich, please.", "chinese": "请给我一个三明治。"}', 10, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3854, 133, '{"english": "OK.", "chinese": "好的。"}', 11, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3855, 133, '{"english": "What would you like to drink?", "chinese": "你想喝什么？"}', 12, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3856, 133, '{"english": "I''d like some water. I''m thirsty!", "chinese": "我想要一些水。我渴了！"}', 13, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3857, 133, '{"english": "Here you are.", "chinese": "给你。"}', 14, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3858, 133, '{"english": "Thanks.", "chinese": "谢谢。"}', 15, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3859, 133, '{"english": "Ask and answer.", "chinese": "问一问，答一答。"}', 16, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3860, 133, '{"english": "What would you like to eat?", "chinese": "你想吃什么？"}', 17, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
INSERT INTO "course_content" VALUES (3861, 133, '{"english": "What would you like to drink?", "chinese": "你想喝什么？"}', 18, '2026-02-05 04:00:30', '2026-02-05 04:00:30');
