INSERT INTO "course_content" VALUES (3892, 133, '{"english": "It is winter.  I look out of my window.", "chinese": "现在是冬天。 我向窗外望去。"}', 49, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
INSERT INTO "course_content" VALUES (3893, 133, '{"english": "I can see white snow.", "chinese": "我能看见白色的雪。"}', 50, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
INSERT INTO "course_content" VALUES (3894, 133, '{"english": "Down comes the snow, slow, slow, slow.", "chinese": "雪落下来，慢慢地、慢慢地、慢慢地。"}', 51, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
INSERT INTO "course_content" VALUES (3895, 133, '{"english": "It is spring.  I look out of my window.", "chinese": "现在是春天。 我向窗外望去。"}', 52, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
INSERT INTO "course_content" VALUES (3896, 133, '{"english": "I can see something yellow.  Up comes a flower, slow, slow, slow.", "chinese": "我能看见黄色的东西。 一朵花开了，慢慢地、慢慢地、慢慢地。"}', 53, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
INSERT INTO "course_content" VALUES (3897, 133, '{"english": "Listen, circle and say.", "chinese": "听一听，圈一圈，说一说。"}', 54, '2026-02-05 04:00:31', '2026-02-05 04:00:31');
