INSERT INTO "course_content" VALUES (3958, 134, '{"english": "Two. We have PE on Monday afternoons and Wednesday mornings.", "chinese": "两节。我们周一下午和周三上午有体育课。"}', 40, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
