INSERT INTO "course_content" VALUES (3960, 134, '{"english": "Look at the schedule above. Tick or cross.", "chinese": "看看上面的时间表。打勾或打叉。"}', 42, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3961, 134, '{"english": "1. Students have science, maths and art on Wednesdays.", "chinese": "1. 学生们星期三有科学课、数学课和美术课。"}', 43, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3962, 134, '{"english": "2. David and Jean have two reading classes on Fridays.", "chinese": "2. 戴维和珍星期五有两节阅读课。"}', 44, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3963, 134, '{"english": "3. They don''t have maths on Mondays.", "chinese": "3. 他们星期一没有数学课。"}', 45, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3964, 134, '{"english": "4. Jean and Dean have music classes on Tuesdays,", "chinese": "4. 珍和迪恩在周二、"}', 46, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3965, 134, '{"english": "Thursdays and Fridays.", "chinese": "周四和周五有音乐课。"}', 47, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3966, 134, '{"english": "Today is Monday. It is time for lunch.", "chinese": "今天是星期一。午饭时间到了。"}', 48, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3967, 134, '{"english": "Chen Jie is in the lunch room. Look at the menu.", "chinese": "陈洁在餐厅。看看菜单。"}', 49, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3968, 134, '{"english": "Then read the dialogue and fill in the blanks.", "chinese": "然后读对话并填空。"}', 50, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
