INSERT INTO "course_content" VALUES (3980, 134, '{"english": "orange juice", "chinese": "橙汁"}', 62, '2026-02-05 04:00:34', '2026-02-05 04:00:34');
INSERT INTO "course_content" VALUES (3981, 134, '{"english": "Wednesday", "chinese": "星期三"}', 63, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3982, 134, '{"english": "carrots", "chinese": "胡萝卜"}', 64, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3983, 134, '{"english": "fish", "chinese": "鱼"}', 65, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3984, 134, '{"english": "oranges", "chinese": "橙子"}', 66, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3985, 134, '{"english": "rice", "chinese": "米饭"}', 67, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3986, 134, '{"english": "tea", "chinese": "茶"}', 68, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3987, 134, '{"english": "Thursday", "chinese": "星期四"}', 69, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3988, 134, '{"english": "eggs", "chinese": "鸡蛋"}', 70, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3989, 134, '{"english": "cake", "chinese": "蛋糕"}', 71, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3990, 134, '{"english": "grapes", "chinese": "葡萄"}', 72, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3991, 134, '{"english": "bread", "chinese": "面包"}', 73, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3992, 134, '{"english": "apple juice", "chinese": "苹果汁"}', 74, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3993, 134, '{"english": "Friday", "chinese": "星期五"}', 75, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3994, 134, '{"english": "green beans", "chinese": "青豆"}', 76, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3995, 134, '{"english": "tomatoes", "chinese": "西红柿"}', 77, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3996, 134, '{"english": "noodles", "chinese": "面条"}', 78, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3997, 134, '{"english": "ice cream", "chinese": "冰淇淋"}', 79, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3998, 134, '{"english": "water", "chinese": "水"}', 80, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (3999, 134, '{"english": "Hi. Welcome! What would you like to eat?", "chinese": "你好。欢迎光临！你想吃什么？"}', 81, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4000, 134, '{"english": "A sandwich, please. It''s my ______ food. Thanks.", "chinese": "请给我一个三明治。它是我______的食物。谢谢。"}', 82, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4001, 134, '{"english": "What would you like to ______?", "chinese": "你想要______？"}', 83, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4002, 134, '{"english": "Tea, please.", "chinese": "请给我茶。"}', 84, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4003, 134, '{"english": "Oh, we don''t have tea today. We have tea on ______ and we have ______ today.", "chinese": "哦，我们今天没有茶。我们在______有茶，我们今天有______。"}', 85, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4004, 134, '{"english": "That''s fine. I''ll have milk.", "chinese": "那好吧。我要牛奶。"}', 86, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4005, 134, '{"english": "Role-play with your partner. Draw your food on the plate.", "chinese": "与你的搭档进行角色扮演。把你的食物画在盘子上。"}', 87, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4006, 134, '{"english": "What would you like to eat?", "chinese": "你想吃什么？"}', 88, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4007, 134, '{"english": "A hamburger, please.", "chinese": "请给我一个汉堡包。"}', 89, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4008, 134, '{"english": "Read Chen Jie''s diary. Write the letters in the boxes.", "chinese": "读一读陈洁的日记。把字母写在盒子里。"}', 90, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4009, 134, '{"english": "A. School", "chinese": "A. 学校"}', 91, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4010, 134, '{"english": "B. Class", "chinese": "B. 课程"}', 92, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4011, 134, '{"english": "C. Food", "chinese": "C. 食物"}', 93, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4012, 134, '{"english": "D. Friends and teachers", "chinese": "D. 朋友们和老师们"}', 94, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4013, 134, '{"english": "Monday", "chinese": "星期一"}', 95, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4014, 134, '{"english": "It is sunny today. I am at Willow Primary School.", "chinese": "今天天气晴朗。我在杨柳小学。"}', 96, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4015, 134, '{"english": "It is so pretty. There are many yellow flowers.", "chinese": "它太漂亮了。那里有许多黄色的花。"}', 97, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4016, 134, '{"english": "David is my new friend. He is clever and hard-working.", "chinese": "大卫是我的新朋友。他聪明又勤奋。"}', 98, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4017, 134, '{"english": "He is funny, too. His favourite class is English.", "chinese": "他也很有趣。他最喜欢的课是英语。"}', 99, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4018, 134, '{"english": "The teacher, Ms Brown, is very helpful.", "chinese": "布朗老师很乐于助人。"}', 100, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4019, 134, '{"english": "Teachers and students often eat lunch at school.", "chinese": "老师们和学生们经常在学校吃午饭。"}', 101, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4020, 134, '{"english": "Some of them have beef and drink tea.", "chinese": "有些人吃牛肉喝茶。"}', 102, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4021, 134, '{"english": "Some love green beans and ice cream. The food is delicious!", "chinese": "有些人喜欢绿豆和冰淇淋。这些食物很好吃！"}', 103, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4022, 134, '{"english": "After lunch, we have a reading class with Mr Reed.", "chinese": "午饭后，我们和里德老师一起上阅读课。"}', 104, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4023, 134, '{"english": "What a friendly school!", "chinese": "多么友爱的学校啊！"}', 105, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4024, 134, '{"english": "Find ''friends'' for the words in the diary.", "chinese": "为日记中的单词找“朋友”。"}', 106, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4025, 134, '{"english": "sunny：", "chinese": "晴朗的："}', 107, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4026, 134, '{"english": "pretty", "chinese": "漂亮的"}', 108, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4027, 134, '{"english": "beef:", "chinese": "牛肉："}', 109, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4028, 134, '{"english": "yellow:", "chinese": "黄色的："}', 110, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4029, 134, '{"english": "eat:", "chinese": "吃："}', 111, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4030, 134, '{"english": "flower:", "chinese": "花："}', 112, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4031, 134, '{"english": "Rearrange the words. Write down the sentences.", "chinese": "重新排列单词。把句子写下来。"}', 113, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4032, 134, '{"english": "1. you, watch TV, often, on the weekend", "chinese": "1. 你，看电视，经常，在周末"}', 114, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4033, 134, '{"english": "2. often, on Saturdays, do homework", "chinese": "2. 经常，在星期六，做家庭作业"}', 115, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4034, 134, '{"english": "3. read books, often, on Sundays", "chinese": "3. 读书，经常，在星期日"}', 116, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4035, 134, '{"english": "Unit Four", "chinese": "第 4 单元"}', 117, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4036, 134, '{"english": "We''ll have an English party next Tuesday.", "chinese": "下星期二我们将举行英语联欢会。"}', 118, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4037, 134, '{"english": "Great!", "chinese": "太棒啦！"}', 119, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4038, 134, '{"english": "What can you do for the party?", "chinese": "你能为联欢会做些什么？"}', 120, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4039, 134, '{"english": "I can play the pipa.", "chinese": "我会弹琵琶。"}', 121, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4040, 134, '{"english": "Wonderful!", "chinese": "好极了！"}', 122, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4041, 134, '{"english": "I can dance!", "chinese": "我会跳舞！"}', 123, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4042, 134, '{"english": "I can sing! La la la ...", "chinese": "我会唱歌！啦啦啦⋯⋯"}', 124, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4043, 134, '{"english": "What can you do?", "chinese": "你能做什么？"}', 125, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4044, 134, '{"english": "Hi, Mr Li.", "chinese": "您好，李老师。"}', 126, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4045, 134, '{"english": "Hi. Can you play ping-pong?", "chinese": "你好。你会打乒乓球吗？"}', 127, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4046, 134, '{"english": "A little.", "chinese": "会一点点。"}', 128, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4047, 134, '{"english": "Let''s play together!", "chinese": "我们一起打吧！"}', 129, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4048, 134, '{"english": "Sorry. I have an English class at 3 o''clock.", "chinese": "抱歉。我三点要上英语课。"}', 130, '2026-02-05 04:00:35', '2026-02-05 04:00:35');
INSERT INTO "course_content" VALUES (4049, 135, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4050, 135, '{"english": "What can Mike do? Listen and tick.", "chinese": "迈克能做什么？听一听并打勾。"}', 2, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4051, 135, '{"english": "-Hi, Mike. We''ll have an English party next Tuesday.  -Great!", "chinese": "—嗨，迈克。我们下周二有一个英语派对。 —太好了！"}', 3, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4052, 135, '{"english": "I like parties.  -What can you do for the party?", "chinese": "我喜欢派对。 —你能为派对做些什么？"}', 4, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4053, 135, '{"english": "-I can draw pictures.", "chinese": "—我会画画。"}', 5, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4054, 135, '{"english": "-It''s time for English class. Get ready!", "chinese": "—该上英语课了。准备好！"}', 6, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4055, 135, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4056, 135, '{"english": "We''ll have an English party next Tuesday!", "chinese": "下星期二我们将举行英语联欢会！"}', 8, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4057, 135, '{"english": "What can you do for the party, children?", "chinese": "孩子们，你们能为联欢会做什么？"}', 9, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4058, 135, '{"english": "I can sing English songs.", "chinese": "我可以唱英文歌。"}', 10, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4059, 135, '{"english": "Wonderful! How about you, John?", "chinese": "太好啦！你呢，约翰？"}', 11, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4060, 135, '{"english": "I can do some kung fu!", "chinese": "我会一些功夫!"}', 12, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4061, 135, '{"english": "Thank you, John.", "chinese": "谢谢你，约翰。"}', 13, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4062, 135, '{"english": "What can you do?", "chinese": "你能做什么？"}', 14, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4063, 135, '{"english": "What can you do, Wu Binbin?", "chinese": "你能做什么，吴斌斌？"}', 15, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4064, 135, '{"english": "I can draw pictures.", "chinese": "我可以画画。"}', 16, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4065, 135, '{"english": "sing  dance  draw pictures", "chinese": "唱歌 跳舞 画画"}', 17, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4066, 135, '{"english": "clean the classroom  do some kung fu", "chinese": "打扫教室 练功夫"}', 18, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4067, 135, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 19, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4068, 135, '{"english": "What can you do?", "chinese": "你能做什么？"}', 20, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4069, 135, '{"english": "I can draw cartoons.", "chinese": "我会画漫画。"}', 21, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
INSERT INTO "course_content" VALUES (4070, 135, '{"english": "dance", "chinese": "跳舞"}', 22, '2026-02-05 04:00:37', '2026-02-05 04:00:37');
