INSERT INTO "course_content" VALUES (4184, 137, '{"english": "What is in the park?", "chinese": "公园里有什么？"}', 2, '2026-02-05 04:00:42', '2026-02-05 04:00:42');
INSERT INTO "course_content" VALUES (4185, 137, '{"english": "Listen and tick the word you hear.", "chinese": "听录音，勾出你听到的单词。"}', 3, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4186, 137, '{"english": "-Look at the map of the park.", "chinese": "—看看公园的地图。"}', 4, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4187, 137, '{"english": "-Is there a forest in the park?", "chinese": "—公园里有森林吗？"}', 5, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4188, 137, '{"english": "-Yes, there is. Here!  -Cool! I love trees.", "chinese": "—有的。在这里！ —酷！我喜欢树。"}', 6, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4189, 137, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4190, 137, '{"english": "Children, let''s go to the forest!", "chinese": "孩子们，我们去森林吧！"}', 8, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4191, 137, '{"english": "Yeah!", "chinese": "好耶！"}', 9, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4192, 137, '{"english": "Is there a river in the forest, Miss White?", "chinese": "怀特小姐，森林里有河吗？"}', 10, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4193, 137, '{"english": "No, there isn''t.", "chinese": "不，森林里没有河。"}', 11, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4194, 137, '{"english": "Is there a lake, Miss White?", "chinese": "怀特小姐，那里有湖吗？"}', 12, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4195, 137, '{"english": "Yes, there is and there are some small boats.", "chinese": "是的，有湖并且湖里有一些小船。"}', 13, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4196, 137, '{"english": "Cool! Let''s go boating.", "chinese": "酷！我们去划船吧。"}', 14, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4197, 137, '{"english": "Talk about the park with your partner.", "chinese": "和你的搭档谈谈公园。"}', 15, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4198, 137, '{"english": "Is there a lake in the park?", "chinese": "公园里有湖吗？"}', 16, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4199, 137, '{"english": "Yes, there is.", "chinese": "是的，公园里有湖。"}', 17, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4200, 137, '{"english": "Is there a forest?", "chinese": "那里有森林吗？"}', 18, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4201, 137, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 19, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4202, 137, '{"english": "Is there a river in the park?", "chinese": "公园里有一条河吗？"}', 20, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4203, 137, '{"english": "Yes, there is.", "chinese": "是的，公园里有一条河。"}', 21, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4204, 137, '{"english": "forest", "chinese": "森林；林区"}', 22, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4205, 137, '{"english": "hill", "chinese": "山丘；小山"}', 23, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4206, 137, '{"english": "mountain", "chinese": "高山；山岳"}', 24, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4207, 137, '{"english": "river", "chinese": "河；江"}', 25, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4208, 137, '{"english": "lake", "chinese": "湖；湖泊"}', 26, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4209, 137, '{"english": "Draw and ask", "chinese": "画一画，问一问"}', 27, '2026-02-05 04:00:43', '2026-02-05 04:00:43');
INSERT INTO "course_content" VALUES (4210, 137, '{"english": "Draw a nature park.", "chinese": "画一个自然公园。"}', 28, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4211, 137, '{"english": "Then talk about it with your partner.", "chinese": "然后和你的搭档谈谈。"}', 29, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4212, 137, '{"english": "Is there a river in front of the mountain?", "chinese": "山前有条河吗？"}', 30, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4213, 137, '{"english": "Write and say", "chinese": "写一写，说一说"}', 31, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4214, 137, '{"english": "Write four sentences about the picture above.", "chinese": "写四个关于上面图片的句子。"}', 32, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4215, 137, '{"english": "There is a village in the nature park.", "chinese": "自然公园里有一个村庄。"}', 33, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4216, 137, '{"english": "Read and write", "chinese": "读一读，写一写"}', 34, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4217, 137, '{"english": "Robin draws", "chinese": "罗宾画画"}', 35, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4218, 137, '{"english": "Robin is at Mr Jones'' house. There is a nature park near the house. In the park there is a high mountain. In front of the mountain there is a small village. There is a lake near the village. There are many ducks on the lake.", "chinese": "罗宾在琼斯老师的家里。房子附近有一个自然公园。公园里有一座高山。在山的前面有一个小村庄。村庄附近有一个湖。湖里有许多鸭子。"}', 36, '2026-02-05 04:00:44', '2026-02-05 04:00:44');
INSERT INTO "course_content" VALUES (4219, 138, '{"english": "Recycle 2", "chinese": "复习 2"}', 1, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4220, 138, '{"english": "Having fun in a park", "chinese": "在公园里玩得开心"}', 2, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4221, 138, '{"english": "The children will go to a nature park this weekend.", "chinese": "这个周末孩子们将去自然公园。"}', 3, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4222, 138, '{"english": "Robin wants to go, too.", "chinese": "罗宾也想去。"}', 4, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4223, 138, '{"english": "He calls Miss White. Listen and tick or cross.", "chinese": "他给怀特小姐打了电话。听录音，打勾或打叉。"}', 5, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4224, 138, '{"english": "-Hello.  -Hello. Can I speak to Miss White, please?", "chinese": "—你好。 —你好。请问怀特小姐在吗？"}', 6, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4225, 138, '{"english": "-This is Miss White speaking.  -Hello, Miss White.", "chinese": "—我是怀特小姐。 —你好，怀特小姐。"}', 7, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4226, 138, '{"english": "This is Robin.  -Oh, hi!", "chinese": "我是罗宾。 —哦，嗨！"}', 8, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4227, 138, '{"english": "-Can I go to the nature park with the children, Miss White?", "chinese": "—怀特小姐，我能和孩子们一起去自然公园吗？"}', 9, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4228, 138, '{"english": "-Let me think. First I have some questions for you.", "chinese": "—让我想想。首先我有一些问题要问你。"}', 10, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4229, 138, '{"english": "-No problem.  -We''ll have a party in the park.", "chinese": "—没问题。 —我们将在公园里举办一个派对。"}', 11, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4230, 138, '{"english": "What can you do?  -Cool! I love parties.", "chinese": "你能做什么？ —太棒了！我喜欢派对。"}', 12, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4231, 138, '{"english": "I can do lots of things. I can sing.", "chinese": "我可以做很多事情。我会唱歌。"}', 13, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4232, 138, '{"english": "I can dance. I can even do kung fu.  -OK.", "chinese": "我会跳舞。我甚至会功夫。 —好啊。"}', 14, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4233, 138, '{"english": "The children will go swimming after the party.", "chinese": "派对结束后孩子们将去游泳。"}', 15, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4234, 138, '{"english": "Will you go with them?  -No, no, no.", "chinese": "你打算和他们一起去吗？ —不，不，不。"}', 16, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4235, 138, '{"english": "I can''t swim.  -We''ll cook there. Can you cook?", "chinese": "我不会游泳。 —我们将在那里做饭。你会做饭吗？"}', 17, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4236, 138, '{"english": "-Of course I can. I''m a good cook.", "chinese": "—我当然可以。我是个好厨师。"}', 18, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4237, 138, '{"english": "I often make beef noodles and vegetable salad.", "chinese": "我经常做牛肉面和蔬菜沙拉。"}', 19, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4238, 138, '{"english": "-Great! I''ll see you at eight in the morning at the school then.", "chinese": "—太好了！那我们早上八点在学校见。"}', 20, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4239, 138, '{"english": "-Thank you, Miss White.", "chinese": "—谢谢你，怀特小姐。"}', 21, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4240, 138, '{"english": "Listen again and answer the questions.", "chinese": "再听一遍，回答问题。"}', 22, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4241, 138, '{"english": "1. Can Robin cook noodles?", "chinese": "1. 罗宾会煮面吗？"}', 23, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4242, 138, '{"english": "2. Can he swim?", "chinese": "2. 他会游泳吗？"}', 24, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4243, 138, '{"english": "3. Can he go to the park?   -Hello.   -Hello.", "chinese": "3. 他会去公园吗？  —你好。  —你好。"}', 25, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4244, 138, '{"english": "Can I speak to Miss White, please?", "chinese": "请问怀特小姐在吗？"}', 26, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4245, 138, '{"english": "-This is Miss White speaking.  -Hello, Miss White.", "chinese": "—我是怀特小姐。 —你好，怀特小姐。"}', 27, '2026-02-05 04:00:45', '2026-02-05 04:00:45');
INSERT INTO "course_content" VALUES (4246, 138, '{"english": "This is Robin.  -Oh, hi!", "chinese": "我是罗宾。 —哦，嗨！"}', 28, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4247, 138, '{"english": "-Can I go to the nature park with the children, Miss White?", "chinese": "—怀特小姐，我能和孩子们一起去自然公园吗？"}', 29, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4248, 138, '{"english": "-Let me think. First I have some questions for you.", "chinese": "—让我想想。首先我有一些问题要问你。"}', 30, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4249, 138, '{"english": "-No problem.  -We''ll have a party in the park.", "chinese": "—没问题。 —我们将在公园里举办一个派对。"}', 31, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4250, 138, '{"english": "What can you do?  -Cool! I love parties.", "chinese": "你能做什么？ —太棒了！我喜欢派对。"}', 32, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4251, 138, '{"english": "I can do lots of things. I can sing.", "chinese": "我可以做很多事情。我会唱歌。"}', 33, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4252, 138, '{"english": "I can dance. I can even do kung fu.  -OK.", "chinese": "我会跳舞。我甚至会功夫。 —好啊。"}', 34, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4253, 138, '{"english": "The children will go swimming after the party.", "chinese": "派对结束后孩子们将去游泳。"}', 35, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4254, 138, '{"english": "Will you go with them?  -No, no, no.", "chinese": "你打算和他们一起去吗？ —不，不，不。"}', 36, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4255, 138, '{"english": "I can''t swim.  -We''ll cook there. Can you cook?", "chinese": "我不会游泳。 —我们将在那里做饭。你会做饭吗？"}', 37, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4256, 138, '{"english": "-Of course I can. I''m a good cook.", "chinese": "—我当然可以。我是个好厨师。"}', 38, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4257, 138, '{"english": "I often make beef noodles and vegetable salad.", "chinese": "我经常做牛肉面和蔬菜沙拉。"}', 39, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4258, 138, '{"english": "-Great! I''ll see you at eight in the morning at the school then.", "chinese": "—太好了！那我们早上八点在学校见。"}', 40, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4259, 138, '{"english": "-Thank you, Miss White.", "chinese": "—谢谢你，怀特小姐。"}', 41, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4260, 138, '{"english": "What else can Robin do? Write two sentences.", "chinese": "罗宾还能做什么？写两句话。"}', 42, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4261, 138, '{"english": "Role-play.", "chinese": "角色扮演。"}', 43, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4262, 138, '{"english": "Can you cook, Robin?", "chinese": "罗宾，你会做饭吗？"}', 44, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4263, 138, '{"english": "Yes, I can.", "chinese": "是的，我可以。"}', 45, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4264, 138, '{"english": "The children are in the park.", "chinese": "孩子们在公园里。"}', 46, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4265, 138, '{"english": "They are looking at the map. Some things are missing.", "chinese": "他们正在看地图。有些东西不见了。"}', 47, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4266, 138, '{"english": "Read the dialogue and draw the missing things.", "chinese": "阅读对话并画出遗漏的东西。"}', 48, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4267, 138, '{"english": "Are there any lakes in the forest?", "chinese": "森林里有湖吗？"}', 49, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4268, 138, '{"english": "Yes, there are two.", "chinese": "是的，有两个。"}', 50, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4269, 138, '{"english": "Is there a restaurant in the forest?", "chinese": "森林里有餐厅吗？"}', 51, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4270, 138, '{"english": "No, there isn''t,", "chinese": "不，没有，"}', 52, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4271, 138, '{"english": "but there is one in front of the hill.", "chinese": "但是在山丘前有一个。"}', 53, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4272, 138, '{"english": "Are there any villages in the nature park?", "chinese": "自然公园里有村庄吗？"}', 54, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4273, 138, '{"english": "Let me think. Yes, there is one on the mountain.", "chinese": "让我想想。是的，山上有一个。"}', 55, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4274, 138, '{"english": "Is there a robot in the park?", "chinese": "公园里有机器人吗？"}', 56, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4275, 138, '{"english": "Yes, there is one between Zhang Peng and Sarah!", "chinese": "是的，张鹏和萨拉之间有一个！"}', 57, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4276, 138, '{"english": "It''s me!", "chinese": "就是我！"}', 58, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4277, 138, '{"english": "Talk about the map with your partner.", "chinese": "和你的搭档讨论一下这张地图。"}', 59, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4278, 138, '{"english": "What''s in the nature park?", "chinese": "自然公园里有什么？"}', 60, '2026-02-05 04:00:46', '2026-02-05 04:00:46');
INSERT INTO "course_content" VALUES (4279, 139, '{"english": "Songs in each unit", "chinese": "单元歌曲表"}', 1, '2026-02-05 04:00:47', '2026-02-05 04:00:47');
INSERT INTO "course_content" VALUES (4280, 139, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:00:47', '2026-02-05 04:00:47');
