INSERT INTO "course_content" VALUES (4413, 142, '{"english": "Useful expressions", "chinese": "常用表达法"}', 1, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4414, 142, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4415, 142, '{"english": "Is he young?", "chinese": "他年轻吗？"}', 3, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4416, 142, '{"english": "No, he isn''t.", "chinese": "不，他不年轻。"}', 4, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4417, 142, '{"english": "What''s she like?", "chinese": "她什么样？"}', 5, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4418, 142, '{"english": "She''s kind.", "chinese": "她很和蔼。"}', 6, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4419, 142, '{"english": "Unit 2", "chinese": "第 2 单元"}', 7, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4420, 142, '{"english": "What do you have on Thursdays?", "chinese": "星期四你有什么课？"}', 8, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4421, 142, '{"english": "I have maths, English and music.", "chinese": "我有数学、英语和音乐课。"}', 9, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4422, 142, '{"english": "Do you often read books in this park?", "chinese": "你经常在这个公园里看书吗？"}', 10, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4423, 142, '{"english": "No, I don''t.", "chinese": "不，我不经常在这里看书。"}', 11, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4424, 142, '{"english": "Unit 3", "chinese": "第 3 单元"}', 12, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4425, 142, '{"english": "What would you like to eat?", "chinese": "你想吃什么？"}', 13, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4426, 142, '{"english": "A sandwich, please.", "chinese": "请给我一个三明治。"}', 14, '2026-02-05 04:00:53', '2026-02-05 04:00:53');
INSERT INTO "course_content" VALUES (4427, 143, '{"english": "Unit 5", "chinese": "第 5 单元"}', 1, '2026-02-05 04:00:54', '2026-02-05 04:00:54');
INSERT INTO "course_content" VALUES (4428, 143, '{"english": "There is a big bed.", "chinese": "（这里）有张大床。"}', 2, '2026-02-05 04:00:54', '2026-02-05 04:00:54');
INSERT INTO "course_content" VALUES (4429, 143, '{"english": "There are so many pictures here.", "chinese": "这里有这么多幅画。"}', 3, '2026-02-05 04:00:54', '2026-02-05 04:00:54');
INSERT INTO "course_content" VALUES (4430, 143, '{"english": "Unit 6", "chinese": "第 6 单元"}', 4, '2026-02-05 04:00:54', '2026-02-05 04:00:54');
INSERT INTO "course_content" VALUES (4431, 143, '{"english": "Is there a river in the forest, Miss White?", "chinese": "怀特小姐，森林里有河吗？"}', 5, '2026-02-05 04:00:54', '2026-02-05 04:00:54');
INSERT INTO "course_content" VALUES (4432, 143, '{"english": "No, there isn''t.", "chinese": "不，森林里没有河。"}', 6, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4433, 143, '{"english": "Are there any tall buildings in the nature park?", "chinese": "自然公园里有高楼吗？"}', 7, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4434, 143, '{"english": "No, there aren''t.", "chinese": "不，自然公园里没有高楼。"}', 8, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4435, 143, '{"english": "Proverbs", "chinese": "谚语"}', 9, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4436, 143, '{"english": "Unit 1", "chinese": "第 1 单元"}', 10, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4437, 143, '{"english": "You can''t judge a book by its cover.", "chinese": "不能以貌取人。"}', 11, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4438, 143, '{"english": "Unit 2", "chinese": "第 2 单元"}', 12, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4439, 143, '{"english": "For the hard-working,", "chinese": "勤奋的人，"}', 13, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4440, 143, '{"english": "a week has seven days; for the lazy, seven tomorrows.", "chinese": "一个星期有七天；懒惰的人，一个星期有七个明天。"}', 14, '2026-02-05 04:00:55', '2026-02-05 04:00:55');
INSERT INTO "course_content" VALUES (4441, 144, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4442, 144, '{"english": "Where are Zhang Peng and Pedro? Listen and tick.", "chinese": "张鹏和佩德罗在哪里？听一听，勾一勾。"}', 2, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4443, 144, '{"english": "Pedro is a new student from Spain.", "chinese": "佩德罗是来自西班牙的新学生。"}', 3, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4444, 144, '{"english": "—Pedro, this is our new classroom. Do you like our school?", "chinese": "——佩德罗，这是我们的新教室。你喜欢我们学校吗？"}', 4, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4445, 144, '{"english": "—Yes. But I am tired.", "chinese": "——喜欢。但是我累了。"}', 5, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4446, 144, '{"english": "In Spain, I always sleep a little in the afternoon.", "chinese": "在西班牙，我下午总是睡一会儿。"}', 6, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4447, 144, '{"english": "—Really? When do you sleep?", "chinese": "——真的吗？你什么时候睡觉？"}', 7, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4448, 144, '{"english": "—At about 2 o''clock.", "chinese": "——大约 2 点钟。"}', 8, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4449, 144, '{"english": "—Oh, that''s now. But we have a math class at 2 o''clock.", "chinese": "——哦，那就是现在。但是我们 2 点钟有数学课。"}', 9, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4450, 144, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 10, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4451, 144, '{"english": "When do you finish class in the morning?", "chinese": "你们上午的课到几点结束？"}', 11, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4452, 144, '{"english": "We finish class at 1 o''clock.", "chinese": "我们在 1 点钟结束上午的课。"}', 12, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4453, 144, '{"english": "Then we eat lunch at home.", "chinese": "然后我们在家里吃午饭。"}', 13, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4454, 144, '{"english": "Wow! When do you go back to school after lunch?", "chinese": "哇！你吃完午饭后什么时候回学校？"}', 14, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4455, 144, '{"english": "At 2:30. Classes start at 3 o''clock.", "chinese": "2 点半。3 点钟开始上课。"}', 15, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4456, 144, '{"english": "When do you usually eat dinner in Spain?", "chinese": "在西班牙你通常什么时候吃晚饭？"}', 16, '2026-02-05 04:00:59', '2026-02-05 04:00:59');
INSERT INTO "course_content" VALUES (4457, 144, '{"english": "Usually at 9:30 or 10 o''clock.", "chinese": "通常在 9 点半或 10 点钟。"}', 17, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4458, 144, '{"english": "Wow! That''s too late!", "chinese": "哇！那太晚了！"}', 18, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4459, 144, '{"english": "Role-play", "chinese": "角色扮演"}', 19, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4460, 144, '{"english": "When do you get up?", "chinese": "你什么时候起床？"}', 20, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4461, 144, '{"english": "I get up at 5 o''clock.", "chinese": "我 5 点钟起床。"}', 21, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4462, 144, '{"english": "When do you go to bed?", "chinese": "你什么时候睡觉？"}', 22, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4463, 144, '{"english": "At 6 o''clock in the morning. I work at night.", "chinese": "早上 6 点钟。我晚上工作。"}', 23, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4464, 144, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 24, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4465, 144, '{"english": "When do you do morning exercises?", "chinese": "你什么时候做早操？"}', 25, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4466, 144, '{"english": "At 7 o''clock.", "chinese": "7 点钟。"}', 26, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4467, 144, '{"english": "do morning exercises", "chinese": "做早操"}', 27, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4468, 144, '{"english": "eat breakfast", "chinese": "吃早饭"}', 28, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4469, 144, '{"english": "have ... class", "chinese": "上⋯⋯课"}', 29, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4470, 144, '{"english": "play sports", "chinese": "进行体育运动"}', 30, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4471, 144, '{"english": "eat dinner", "chinese": "吃晚饭"}', 31, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4472, 144, '{"english": "Ask and write", "chinese": "问一问，写一写"}', 32, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4473, 144, '{"english": "Ask about your partner''s timetable.", "chinese": "询问你搭档的时间表。"}', 33, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4474, 144, '{"english": "When do you get up?", "chinese": "你什么时候起床？"}', 34, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4475, 144, '{"english": "I get up at 6:00 a.m.", "chinese": "我早上 6 点钟起床。"}', 35, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4476, 144, '{"english": "get up", "chinese": "起床"}', 36, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4477, 144, '{"english": "eat breakfast", "chinese": "吃早饭"}', 37, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4478, 144, '{"english": "eat lunch", "chinese": "吃午饭"}', 38, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4479, 144, '{"english": "eat dinner", "chinese": "吃晚饭"}', 39, '2026-02-05 04:01:00', '2026-02-05 04:01:00');
INSERT INTO "course_content" VALUES (4480, 144, '{"english": "do morning exercises", "chinese": "做早操"}', 40, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4481, 144, '{"english": "have ... class", "chinese": "上⋯⋯课"}', 41, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4482, 144, '{"english": "play sports", "chinese": "进行体育运动"}', 42, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4483, 144, '{"english": "go to bed", "chinese": "去睡觉"}', 43, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4484, 144, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 44, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4485, 144, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 45, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4486, 144, '{"english": "clean", "chinese": "打扫"}', 46, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4487, 144, '{"english": "clock", "chinese": "时钟"}', 47, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4488, 144, '{"english": "class", "chinese": "班级"}', 48, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4489, 144, '{"english": "clever", "chinese": "聪明的"}', 49, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4490, 144, '{"english": "plate", "chinese": "盘子"}', 50, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4491, 144, '{"english": "eggplant", "chinese": "茄子"}', 51, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4492, 144, '{"english": "please", "chinese": "请"}', 52, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4493, 144, '{"english": "play", "chinese": "玩"}', 53, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4494, 144, '{"english": "Let''s chant.  Please clean your plate.  Please clean your plate.", "chinese": "让我们唱一唱。 请清理你的盘子。 请清理你的盘子。"}', 54, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4495, 144, '{"english": "No more eggplant.  No more peas.  So clean your plate.", "chinese": "没有更多茄子了。 没有更多豌豆了。 所以请清理你的盘子。"}', 55, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4496, 144, '{"english": "Please, please, please.  Please clean your plate.", "chinese": "拜托，拜托，拜托。 请清理你的盘子。"}', 56, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4497, 144, '{"english": "Please clean your plate.  No more eggplant.", "chinese": "请清理你的盘子。 没有更多茄子了。"}', 57, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4498, 144, '{"english": "No more peas.  So clean your plate.  Please, please, please.", "chinese": "没有更多豌豆了。 所以请清理你的盘子。 拜托，拜托，拜托。"}', 58, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
INSERT INTO "course_content" VALUES (4499, 144, '{"english": "Bingo!", "chinese": "答对了！"}', 59, '2026-02-05 04:01:01', '2026-02-05 04:01:01');
