INSERT INTO "course_content" VALUES (4517, 144, '{"english": "clean", "chinese": "干净的"}', 77, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4518, 144, '{"english": "Choose, write and say.", "chinese": "选一选，写一写，说一说。"}', 78, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4519, 144, '{"english": "1. Clean the plate/classroom/room, please.", "chinese": "1. 请打扫盘子/教室/房间。"}', 79, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4520, 144, '{"english": "2. Put two eggplants/clocks/plates in the playground.", "chinese": "2. 在操场上放两个茄子/时钟/盘子。"}', 80, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4521, 144, '{"english": "kung fu", "chinese": "功夫"}', 81, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
