INSERT INTO "course_content" VALUES (4528, 144, '{"english": "play", "chinese": "打；演奏"}', 88, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4529, 144, '{"english": "have", "chinese": "吃"}', 89, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4530, 144, '{"english": "do", "chinese": "做"}', 90, '2026-02-05 04:01:02', '2026-02-05 04:01:02');
INSERT INTO "course_content" VALUES (4531, 145, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4532, 145, '{"english": "What is the weather like today? Listen and write.", "chinese": "今天的天气怎么样？听一听，写一写。"}', 2, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4533, 145, '{"english": "—It''s a windy day.", "chinese": "——今天有风。"}', 3, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4534, 145, '{"english": "—Yes. It''s cold, too.", "chinese": "——是的。天气也很冷。"}', 4, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4535, 145, '{"english": "—What''s your favourite season, Chen Jie?", "chinese": "——陈杰，你最喜欢的季节是什么？"}', 5, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4536, 145, '{"english": "—Spring. It is beautiful here in Beijing.", "chinese": "——春天。北京的春天很美。"}', 6, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4537, 145, '{"english": "rainy and cold  windy and cold  sunny and warm", "chinese": "下雨且寒冷的 刮风且寒冷的 晴朗温暖的"}', 7, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4538, 145, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 8, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4539, 145, '{"english": "Do you like the music, children?", "chinese": "你们喜欢这段音乐吗，同学们？"}', 9, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4540, 145, '{"english": "Yes. It''s very beautiful. What is it?", "chinese": "是的。它很美妙。这是什么音乐？"}', 10, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4541, 145, '{"english": "The Four Seasons. Today we''ll draw the seasons.", "chinese": "《四季》。今天我们将画一画四季。"}', 11, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4542, 145, '{"english": "Which season do you like best, Mike?", "chinese": "你最喜欢哪个季节，迈克？"}', 12, '2026-02-05 04:01:05', '2026-02-05 04:01:05');
INSERT INTO "course_content" VALUES (4543, 145, '{"english": "Winter. I like snow.", "chinese": "冬天。我喜欢雪。"}', 13, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4544, 145, '{"english": "I like snow, too.", "chinese": "我也喜欢雪。"}', 14, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4545, 145, '{"english": "Which season do you like best, Wu Binbin?", "chinese": "你最喜欢哪个季节，吴斌斌？"}', 15, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4546, 145, '{"english": "Spring. It''s pretty.", "chinese": "春天。它很美。"}', 16, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4547, 145, '{"english": "Yes, it is.", "chinese": "是的，它很美。"}', 17, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4548, 145, '{"english": "Which season do you like best? Ask and answer.", "chinese": "你最喜欢哪个季节？问一问，答一答。"}', 18, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4549, 145, '{"english": "Which season do you like best?", "chinese": "你最喜欢哪个季节？"}', 19, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4550, 145, '{"english": "Winter.", "chinese": "冬天。"}', 20, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4551, 145, '{"english": "spring", "chinese": "春天"}', 21, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4552, 145, '{"english": "summer", "chinese": "夏天"}', 22, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4553, 145, '{"english": "autumn", "chinese": "秋天"}', 23, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4554, 145, '{"english": "winter", "chinese": "冬天"}', 24, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4555, 145, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 25, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4556, 145, '{"english": "Which season do you like best?", "chinese": "你最喜欢哪个季节？"}', 26, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4557, 145, '{"english": "Summer. I can go swimming every day!", "chinese": "夏天。我可以每天去游泳！"}', 27, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4558, 145, '{"english": "spring", "chinese": "春天"}', 28, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4559, 145, '{"english": "summer", "chinese": "夏天"}', 29, '2026-02-05 04:01:06', '2026-02-05 04:01:06');
INSERT INTO "course_content" VALUES (4560, 145, '{"english": "autumn", "chinese": "秋天"}', 30, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4561, 145, '{"english": "winter", "chinese": "冬天"}', 31, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4562, 145, '{"english": "Read and match", "chinese": "读一读，连一连"}', 32, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4563, 145, '{"english": "Spring is green with flowers and songs.", "chinese": "春天是绿色的，有鲜花和歌曲。"}', 33, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4564, 145, '{"english": "Summer is hot and the days are long.", "chinese": "夏天很热，白天很长。"}', 34, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4565, 145, '{"english": "Autumn is golden and farmers are busy.", "chinese": "秋天是金色的，农民们都很忙。"}', 35, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4566, 145, '{"english": "Winter is white and the year is gone.", "chinese": "冬天是白色的，一年过去了。"}', 36, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4567, 145, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 37, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4568, 145, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 38, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4569, 145, '{"english": "brown", "chinese": "棕色；棕色的"}', 39, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4570, 145, '{"english": "library", "chinese": "图书馆"}', 40, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4571, 145, '{"english": "brother", "chinese": "兄弟"}', 41, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4572, 145, '{"english": "umbrella", "chinese": "雨伞"}', 42, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4573, 145, '{"english": "green", "chinese": "绿色；绿色的"}', 43, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4574, 145, '{"english": "grapes", "chinese": "葡萄"}', 44, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4575, 145, '{"english": "grandpa", "chinese": "爷爷；外公"}', 45, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4576, 145, '{"english": "grow", "chinese": "生长"}', 46, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4577, 145, '{"english": "Let''s chant.  Green grapes grow.  Green grapes grow.", "chinese": "让我们唱一唱。 绿葡萄在生长。 绿葡萄在生长。"}', 47, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4578, 145, '{"english": "Grandpa and my brother watch green grapes grow.   Brown bread bakes.", "chinese": "爷爷和哥哥看着绿葡萄在生长。  黑面包在烤。"}', 48, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4579, 145, '{"english": "Brown bread bakes.  Grandma and my brother watch brown bread bake.", "chinese": "黑面包在烤。 奶奶和哥哥看着黑面包在烤。"}', 49, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4580, 145, '{"english": "Green grapes grow.  Green grapes grow.", "chinese": "绿葡萄在生长。 绿葡萄在生长。"}', 50, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4581, 145, '{"english": "Grandpa and my brother watch green grapes grow.   Brown bread bakes.", "chinese": "爷爷和哥哥看着绿葡萄在生长。  黑面包在烤。"}', 51, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4582, 145, '{"english": "Brown bread bakes.  Grandma and my brother watch brown bread bake.", "chinese": "黑面包在烤。 奶奶和哥哥看着黑面包在烤。"}', 52, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4583, 145, '{"english": "Read and group.", "chinese": "读一读并归类。"}', 53, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4584, 145, '{"english": "green, brother, brown grass, grow, grapes, grandma, library, breakfast, great", "chinese": "绿色，兄弟，棕色，草，生长，葡萄，奶奶，图书馆，早餐，很棒"}', 54, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4585, 145, '{"english": "Choose, write and say.", "chinese": "选一选，写一写，说一说。"}', 55, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4586, 145, '{"english": "1. Grandpa grows green grapes.", "chinese": "1. 爷爷种绿葡萄。"}', 56, '2026-02-05 04:01:07', '2026-02-05 04:01:07');
INSERT INTO "course_content" VALUES (4587, 145, '{"english": "Boy: When is your birthday?", "chinese": "男生：你的生日是什么时候？"}', 57, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4588, 145, '{"english": "Girl: It''s in summer.", "chinese": "女生：在夏天。"}', 58, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4589, 145, '{"english": "Boy: Do you like summer?", "chinese": "男生：你喜欢夏天吗？"}', 59, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4590, 145, '{"english": "Girl: No, I don''t. It''s too hot.", "chinese": "女生：不，我不喜欢。太热了。"}', 60, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4591, 145, '{"english": "Boy: Which season do you like best?", "chinese": "男生：你最喜欢哪个季节？"}', 61, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4592, 145, '{"english": "Girl: Autumn. The colours are beautiful. I can pick fresh apples.", "chinese": "女生：秋天。颜色很美。我可以摘新鲜的苹果。"}', 62, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4593, 145, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 63, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4594, 145, '{"english": "Fill in the question words.", "chinese": "填写疑问词。"}', 64, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4595, 145, '{"english": "Where is ''do''?", "chinese": "“do”在哪里？"}', 65, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4596, 145, '{"english": "Why do you like spring best?", "chinese": "你为什么最喜欢春天？"}', 66, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4597, 145, '{"english": "Because the weather is nice.", "chinese": "因为天气很好。"}', 67, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4598, 145, '{"english": "______ season do you like best?", "chinese": "你最喜欢哪个季节？"}', 68, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4599, 145, '{"english": "I like spring best.", "chinese": "我最喜欢春天。"}', 69, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4600, 145, '{"english": "______ do you go to school?", "chinese": "你什么时候去上学？"}', 70, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4601, 145, '{"english": "I go to school at 8 o''clock.", "chinese": "我 8 点钟去上学。"}', 71, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4602, 145, '{"english": "______ do you often do on the weekend?", "chinese": "你在周末经常做什么？"}', 72, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4603, 145, '{"english": "I often go shopping.", "chinese": "我经常去购物。"}', 73, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4604, 145, '{"english": "______ is your photo?", "chinese": "你的照片在哪里？"}', 74, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4605, 145, '{"english": "It''s on the wall.", "chinese": "它在墙上。"}', 75, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4606, 145, '{"english": "what  when  where  which  why", "chinese": "什么 什么时候；何时 什么地方；何地 哪一个 为什么"}', 76, '2026-02-05 04:01:08', '2026-02-05 04:01:08');
INSERT INTO "course_content" VALUES (4607, 146, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4608, 146, '{"english": "Who will go to the sports meet next week?", "chinese": "谁将参加下个星期的运动会？"}', 2, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4609, 146, '{"english": "Listen and tick.", "chinese": "听一听，勾一勾。"}', 3, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4610, 146, '{"english": "—What''s that, Zhang Peng?", "chinese": "——那是什么，张鹏？"}', 4, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4611, 146, '{"english": "—It''s an invitation for my mum and dad.", "chinese": "——这是给我爸妈的请柬。"}', 5, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4612, 146, '{"english": "—What for?", "chinese": "——为了什么？"}', 6, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4613, 146, '{"english": "—For the sports meet next week. I will run.", "chinese": "——参加下周的运动会。我要跑步。"}', 7, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4614, 146, '{"english": "—I see. Good luck.", "chinese": "——知道了。祝你好运。"}', 8, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4615, 146, '{"english": "-Thank you.", "chinese": "——谢谢你。"}', 9, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4616, 146, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 10, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4617, 146, '{"english": "We have a few fun things in spring.", "chinese": "我们在春天会有一些有趣的事情。"}', 11, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4618, 146, '{"english": "After the sports meet, we have an English party.", "chinese": "运动会后，我们有一个英语聚会。"}', 12, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4619, 146, '{"english": "When is the party?", "chinese": "聚会是什么时候？"}', 13, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4620, 146, '{"english": "It''s in April. We have a school trip, too.", "chinese": "在四月。我们还有一次学校旅行。"}', 14, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4621, 146, '{"english": "When is that?", "chinese": "那是什么时候？"}', 15, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4622, 146, '{"english": "It''s in May.", "chinese": "在五月。"}', 16, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4623, 146, '{"english": "Cool!", "chinese": "酷！"}', 17, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4624, 146, '{"english": "April  sports meet  English party", "chinese": "四月 运动会 英语聚会"}', 18, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4625, 146, '{"english": "May  school trip", "chinese": "五月 学校旅行"}', 19, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4626, 146, '{"english": "Write and talk.", "chinese": "写一写，说一说。"}', 20, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4627, 146, '{"english": "When is the singing contest?", "chinese": "歌唱比赛什么时候举行？"}', 21, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4628, 146, '{"english": "It''s usually in May.", "chinese": "通常在五月。"}', 22, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4629, 146, '{"english": "school trip  sports meet  Chinese/maths/... test  singing contest", "chinese": "学校旅行 运动会 语文/数学/⋯⋯考试 歌唱比赛"}', 23, '2026-02-05 04:01:11', '2026-02-05 04:01:11');
INSERT INTO "course_content" VALUES (4630, 146, '{"english": "April", "chinese": "四月"}', 24, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
