INSERT INTO "course_content" VALUES (4632, 146, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 26, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4633, 146, '{"english": "When is Tree Planting Day?", "chinese": "植树节是什么时候？"}', 27, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4634, 146, '{"english": "It''s in March.", "chinese": "它在三月。"}', 28, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
