INSERT INTO "course_content" VALUES (4644, 146, '{"english": "June (Jun.)  Children''s Day  Father''s Day", "chinese": "六月 儿童节 父亲节"}', 38, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4645, 146, '{"english": "Read and say", "chinese": "读一读，说一说"}', 39, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4646, 146, '{"english": "Tick or cross.", "chinese": "判断正误。"}', 40, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4647, 146, '{"english": "Correct the names of the months when necessary.", "chinese": "必要时更正月份名称。"}', 41, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4648, 146, '{"english": "When is Mother''s Day?", "chinese": "母亲节是什么时候？"}', 42, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4649, 146, '{"english": "It''s in ...", "chinese": "它在⋯⋯"}', 43, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4650, 146, '{"english": "Let''s spell", "chinese": "让我们拼一拼"}', 44, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4651, 146, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 45, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4652, 146, '{"english": "China", "chinese": "中国"}', 46, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
