INSERT INTO "course_content" VALUES (4654, 146, '{"english": "lunch", "chinese": "午饭"}', 48, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4655, 146, '{"english": "teacher", "chinese": "老师"}', 49, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4656, 146, '{"english": "sheep", "chinese": "绵羊"}', 50, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4657, 146, '{"english": "fish", "chinese": "鱼肉"}', 51, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4658, 146, '{"english": "shirt", "chinese": "衬衫"}', 52, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4659, 146, '{"english": "shorts", "chinese": "短裤"}', 53, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4660, 146, '{"english": "Let''s chant.", "chinese": "让我们唱一唱。"}', 54, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4661, 146, '{"english": "Teacher, teacher.", "chinese": "老师，老师。"}', 55, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4662, 146, '{"english": "What''s for lunch today?", "chinese": "今天午饭吃什么？"}', 56, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4663, 146, '{"english": "Chicken or fish?", "chinese": "鸡肉还是鱼？"}', 57, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4664, 146, '{"english": "Chicken or fish?", "chinese": "鸡肉还是鱼？"}', 58, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4665, 146, '{"english": "I love chicken.", "chinese": "我喜欢鸡肉。"}', 59, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4666, 146, '{"english": "Hooray!", "chinese": "万岁！"}', 60, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4667, 146, '{"english": "Teacher, teacher.", "chinese": "老师，老师。"}', 61, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4668, 146, '{"english": "What''s for lunch today?", "chinese": "今天午饭吃什么？"}', 62, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4669, 146, '{"english": "Chicken or fish?", "chinese": "鸡肉还是鱼？"}', 63, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4670, 146, '{"english": "Chicken or fish?", "chinese": "鸡肉还是鱼？"}', 64, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4671, 146, '{"english": "I love chicken.", "chinese": "我喜欢鸡肉。"}', 65, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4672, 146, '{"english": "Hooray!", "chinese": "万岁！"}', 66, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4673, 146, '{"english": "Listen, number and say.", "chinese": "听一听，标序号，说一说。"}', 67, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4674, 146, '{"english": "1. an English teacher  2. fish for lunch", "chinese": "1. 英语老师 2. 午餐吃鱼"}', 68, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4675, 146, '{"english": "3. a short sheep  4. a shirt and shorts  5. Chinese children", "chinese": "3. 矮小的羊 4. 衬衫和短裤 5. 中国的儿童"}', 69, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4676, 146, '{"english": "Choose, write and say.", "chinese": "选一选，写一写，说一说。"}', 70, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4677, 146, '{"english": "1. The teacher is nice.", "chinese": "1. 老师很好。"}', 71, '2026-02-05 04:01:12', '2026-02-05 04:01:12');
INSERT INTO "course_content" VALUES (4678, 146, '{"english": "1. What will the students do in May?", "chinese": "1. 学生们在五月会做什么？"}', 72, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4679, 146, '{"english": "2. What will they do in December?", "chinese": "2. 学生们在十二月会做什么？"}', 73, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4680, 146, '{"english": "1. We have lots of fun things this spring.", "chinese": "1. 今年春天我们有很多有趣的事情。"}', 74, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4681, 146, '{"english": "In March, there is the school trip. We''ll go to the Great Wall.", "chinese": "三月，有学校旅行。我们将去长城。"}', 75, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4682, 146, '{"english": "In April, we''ll have a singing contest. In May, we''ll visit a farm.", "chinese": "四月，我们将举办一场歌唱比赛。五月，我们将参观一个农场。"}', 76, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4683, 146, '{"english": "2. Look at the calendar. In September, there is Teachers'' Day.", "chinese": "2. 看日历。九月有教师节。"}', 77, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4684, 146, '{"english": "In October, we''ll go to the zoo.", "chinese": "十月，我们将去动物园。"}', 78, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4685, 146, '{"english": "In November, there is Thanksgiving Day. We''ll eat a big dinner.", "chinese": "十一月有感恩节。我们将吃一顿丰盛的晚餐。"}', 79, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4686, 146, '{"english": "In December, there is Christmas. We''ll have a party.", "chinese": "十二月有圣诞节。我们将开聚会。"}', 80, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4687, 146, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 81, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4688, 146, '{"english": "Fill in the blanks.", "chinese": "填空。"}', 82, '2026-02-05 04:01:13', '2026-02-05 04:01:13');
INSERT INTO "course_content" VALUES (4689, 147, '{"english": "Recycle 1", "chinese": "复习 1"}', 1, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4690, 147, '{"english": "Sarah''s weekend", "chinese": "萨拉的周末"}', 2, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4691, 147, '{"english": "It is Saturday morning. Sarah is calling her friends.", "chinese": "现在是星期六的早上。萨拉正在给她的朋友打电话。"}', 3, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4692, 147, '{"english": "Listen and write the names.", "chinese": "听一听并写出名字。"}', 4, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4693, 147, '{"english": "1. —Hello.", "chinese": "1. ——你好。"}', 5, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4694, 147, '{"english": "—Hi, Mike. This is Sarah.", "chinese": "——嗨，迈克。我是萨拉。"}', 6, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4695, 147, '{"english": "—Hi, Sarah.", "chinese": "——嗨，萨拉。"}', 7, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4696, 147, '{"english": "—I will play ping-pong tomorrow morning. Would you like to come?", "chinese": "——我明天早上去打乒乓球。你愿意来吗？"}', 8, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4697, 147, '{"english": "—Sorry, I will pick apples with my grandpa.", "chinese": "——对不起，我要和爷爷一起摘苹果。"}', 9, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4698, 147, '{"english": "—No problem.", "chinese": "——没问题。"}', 10, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4699, 147, '{"english": "2. —Hi, Wu Binbin. This is Sarah.", "chinese": "2. ——嗨，吴斌斌。我是萨拉。"}', 11, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4700, 147, '{"english": "—Hi.", "chinese": "——嗨。"}', 12, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4701, 147, '{"english": "—I will play ping-pong tomorrow. Will you come?", "chinese": "——我明天要去打乒乓球。你会来吗？"}', 13, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4702, 147, '{"english": "—Sorry, I will go swimming.", "chinese": "——对不起，我要去游泳。"}', 14, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4703, 147, '{"english": "—That''s OK. See you Monday.", "chinese": "——没关系。星期一见。"}', 15, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4704, 147, '{"english": "—See you.", "chinese": "——再见。"}', 16, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4705, 147, '{"english": "3. —Hello.", "chinese": "3. ——你好。"}', 17, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4706, 147, '{"english": "—Hi, Amy. This is Sarah.", "chinese": "——嗨，埃米。我是萨拉。"}', 18, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4707, 147, '{"english": "I will play ping-pong tomorrow morning. Can you come?", "chinese": "我明天早上要去打乒乓球。你能来吗？"}', 19, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4708, 147, '{"english": "—Sure. I am free.", "chinese": "——当然。我有空。"}', 20, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4709, 147, '{"english": "—Cool!", "chinese": "——酷！"}', 21, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4710, 147, '{"english": "Call your friends and plan your weekend.", "chinese": "打电话给你的朋友，计划你们的周末。"}', 22, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4711, 147, '{"english": "go shopping", "chinese": "购物"}', 23, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4712, 147, '{"english": "play basketball", "chinese": "打篮球"}', 24, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4713, 147, '{"english": "go swimming", "chinese": "去游泳"}', 25, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4714, 147, '{"english": "go on a picnic", "chinese": "去野餐"}', 26, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4715, 147, '{"english": "pick apples", "chinese": "摘苹果"}', 27, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4716, 147, '{"english": "Hello.", "chinese": "你好。"}', 28, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4717, 147, '{"english": "Hi, Oliver. This is Wu Binbin.", "chinese": "嗨，奥利弗。我是吴斌斌。"}', 29, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4718, 147, '{"english": "Are you free this ...?", "chinese": "你有空吗？"}', 30, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4719, 147, '{"english": "It is Sunday morning. Sarah''s father is home after work.", "chinese": "今天是星期天早上。萨拉的爸爸下班后在家。"}', 31, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4720, 147, '{"english": "Sarah is still asleep, but Robin is up.", "chinese": "萨拉还在睡觉，但罗宾醒了。"}', 32, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4721, 147, '{"english": "Read and complete the dialogue.", "chinese": "阅读并完成对话。"}', 33, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4722, 147, '{"english": "Do you work at night?", "chinese": "你晚上工作吗？"}', 34, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4723, 147, '{"english": "Yes, I''m a doctor. I often work at night.", "chinese": "是的，我是一名医生。我经常在晚上工作。"}', 35, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4724, 147, '{"english": "When do you go to bed, then?", "chinese": "那么你什么时候睡觉？"}', 36, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4725, 147, '{"english": "Wow! When do you eat lunch?", "chinese": "哇！你什么时候吃午饭？"}', 37, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4726, 147, '{"english": "At 5:00 p.m.", "chinese": "下午 5 点钟。"}', 38, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4727, 147, '{"english": "When do you go to work?", "chinese": "你什么时候上班？"}', 39, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4728, 147, '{"english": "Oh! You must be very tired.", "chinese": "哦！你一定很累。"}', 40, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4729, 147, '{"english": "Breakfast is ready. Please enjoy it!", "chinese": "早餐准备好了。请享用！"}', 41, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4730, 147, '{"english": "Thanks.", "chinese": "谢谢。"}', 42, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4731, 147, '{"english": "6: 00 p.m. go to work", "chinese": "下午 6 点钟上班"}', 43, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4732, 147, '{"english": "8: 00 a.m. eat breakfast  9: 00 a.m. go to bed", "chinese": "上午 8 点钟吃早饭 上午 9 点钟睡觉"}', 44, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4733, 147, '{"english": "2: 00 p.m. eat lunch  5: 00 p.m. eat dinner", "chinese": "下午 2 点钟吃午饭 下午 5 点钟吃晚饭"}', 45, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4734, 147, '{"english": "Find out your parents'' timetables and role-play with your partner.", "chinese": "找出你父母的时间表，并与你的搭档进行角色扮演。"}', 46, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4735, 147, '{"english": "When do you get up, Mum?", "chinese": "妈妈，你什么时候起床？"}', 47, '2026-02-05 04:01:15', '2026-02-05 04:01:15');
INSERT INTO "course_content" VALUES (4736, 147, '{"english": "I usually get up at 6: 00 a.m.", "chinese": "我通常早上 6 点钟起床。"}', 48, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4737, 147, '{"english": "When do you cook breakfast?", "chinese": "你什么时候做早饭？"}', 49, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4738, 147, '{"english": "get up  cook breakfast  go to work", "chinese": "起床 做早饭 上班"}', 50, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4739, 147, '{"english": "go home  cook dinner  go to bed", "chinese": "回家 做晚饭 睡觉"}', 51, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4740, 147, '{"english": "Sarah will visit Sydney in April. She asks Stella,", "chinese": "莎拉将在四月参观悉尼。她问她"}', 52, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4741, 147, '{"english": "a friend there, about the weather. Here is Stella''s reply.", "chinese": "在那里的一个朋友斯特拉关于天气的情况。这是斯特拉的回复。"}', 53, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4742, 147, '{"english": "Hi, Sarah!", "chinese": "嗨，萨拉！"}', 54, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4743, 147, '{"english": "It is autumn in April here in Sydney.", "chinese": "在悉尼这里四月是秋天。"}', 55, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4744, 147, '{"english": "Autumn is my favourite season!", "chinese": "秋天是我最喜欢的季节！"}', 56, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4745, 147, '{"english": "It is warm in the day and cool at night.", "chinese": "白天很温暖，晚上很凉爽。"}', 57, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4746, 147, '{"english": "Many people visit us in autumn because they like the weather.", "chinese": "许多人在秋天来我们这里参观，因为他们喜欢这样的天气。"}', 58, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4747, 147, '{"english": "When you come, you can visit the Sydney Opera House.", "chinese": "当你来的时候，你可以参观悉尼歌剧院。"}', 59, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4748, 147, '{"english": "It is the most famous building in Australia.", "chinese": "它是澳大利亚最著名的建筑。"}', 60, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4749, 147, '{"english": "What is the weather like in April in your city?", "chinese": "在你的城市四月的天气是什么样的？"}', 61, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4750, 147, '{"english": "What do you often do?", "chinese": "你经常做什么？"}', 62, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4751, 147, '{"english": "All the best, Stella", "chinese": "祝你一切安好， 斯特拉"}', 63, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4752, 147, '{"english": "Read and answer.", "chinese": "读一读，答一答。"}', 64, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4753, 147, '{"english": "1. Is it spring in Sydney in April?", "chinese": "1. 悉尼四月是春天吗？"}', 65, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4754, 147, '{"english": "2. What''s the weather like in April in Sydney?", "chinese": "2. 悉尼四月的天气怎么样？"}', 66, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4755, 147, '{"english": "Now can you answer the email for Sarah, please?", "chinese": "现在请你帮萨拉回邮件，好吗？"}', 67, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4756, 147, '{"english": "Hi, Stella!", "chinese": "嗨，斯特拉！"}', 68, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4757, 147, '{"english": "Thanks for your email. It is spring here in China.", "chinese": "谢谢你的电子邮件。中国现在是春天。"}', 69, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4758, 147, '{"english": "Please visit me someday and I am sure you will have a good time!", "chinese": "请有一天来看我，我保证你会玩得很开心！"}', 70, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4759, 147, '{"english": "Best wishes, Sarah", "chinese": "祝你一切顺利， 萨拉"}', 71, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4760, 147, '{"english": "What''s the weather like in spring?", "chinese": "春天的天气怎么样？"}', 72, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4761, 147, '{"english": "What do you usually do then?", "chinese": "那你通常做什么？"}', 73, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4762, 147, '{"english": "Sarah often reads to Sam.", "chinese": "萨拉经常读书给山姆听。"}', 74, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4763, 147, '{"english": "This is a poem that Sarah will read today.", "chinese": "这是萨拉今天要读的一首诗。"}', 75, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4764, 147, '{"english": "Bed in Summer  by Robert Louis Stevenson", "chinese": "《夏日无眠》 罗伯特·路易斯·史蒂文森著"}', 76, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4765, 147, '{"english": "In winter I get up at night", "chinese": "冬日我大清早起床，"}', 77, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4766, 147, '{"english": "And dress by yellow candlelight.", "chinese": "借着黄色的烛光穿裳。"}', 78, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4767, 147, '{"english": "In summer, quite the other way.", "chinese": "夏日完全相反，"}', 79, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4768, 147, '{"english": "I have to go to bed by day.", "chinese": "我必须在日间上床。"}', 80, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4769, 147, '{"english": "I have to go to bed and see", "chinese": "我必上床且看"}', 81, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4770, 147, '{"english": "The birds still hopping on the tree,", "chinese": "鸟儿还在树梢跃荡，"}', 82, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4771, 147, '{"english": "Or hear the grown-up people''s feet  Still going past me in the street.", "chinese": "抑或聆听成年人的脚声 仍旧在街道走过我的身旁。"}', 83, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4772, 147, '{"english": "And does it not seem hard to you,", "chinese": "它对你来说难道不为难吗？"}', 84, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4773, 147, '{"english": "When all the sky is clear and blue,", "chinese": "在明亮而蔚蓝的天空当前，"}', 85, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4774, 147, '{"english": "And I should like so much to play,", "chinese": "而我如此喜欢玩要，"}', 86, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4775, 147, '{"english": "To have to go to bed by day?", "chinese": "却必须在白天就上床？"}', 87, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4776, 147, '{"english": "Find ''friends'' in the poem for the words below.", "chinese": "在诗中为下面的单词找到“朋友”。"}', 88, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4777, 147, '{"english": "clean", "chinese": "清洁"}', 89, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4778, 147, '{"english": "please", "chinese": "请"}', 90, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4779, 147, '{"english": "green", "chinese": "绿色；绿色的"}', 91, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4780, 147, '{"english": "cheap", "chinese": "便宜的"}', 92, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4781, 147, '{"english": "sheep", "chinese": "羊"}', 93, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4782, 147, '{"english": "Can you write more words?", "chinese": "你能写出更多的单词吗？"}', 94, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4783, 147, '{"english": "Unit Four", "chinese": "第四单元"}', 95, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4784, 147, '{"english": "When is Mother''s day?", "chinese": "母亲节是什么时候？"}', 96, '2026-02-05 04:01:16', '2026-02-05 04:01:16');
INSERT INTO "course_content" VALUES (4785, 147, '{"english": "It''s on the second Sunday in May.", "chinese": "它是在五月的第二个星期天。"}', 97, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4786, 147, '{"english": "Happy birthday, Mum!", "chinese": "生日快乐，妈妈！"}', 98, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4787, 147, '{"english": "Thank you.", "chinese": "谢谢你。"}', 99, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4788, 147, '{"english": "When is the art show?", "chinese": "艺术节是哪天？"}', 100, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4789, 147, '{"english": "When is Mid-Autumn Festival this year?", "chinese": "今年的中秋节是哪天？"}', 101, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4790, 147, '{"english": "September 27th.", "chinese": "9 月 27 日。"}', 102, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4791, 147, '{"english": "What do you usually do on Mid-Autumn Festival?", "chinese": "中秋节你通常做什么？"}', 103, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4792, 147, '{"english": "We eat mooncakes.", "chinese": "我们吃月饼。"}', 104, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4793, 147, '{"english": "My family will also eat a birthday cake.", "chinese": "我的家人也会吃生日蛋糕。"}', 105, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4794, 147, '{"english": "A birthday cake for Mid-Autumn Festival?!", "chinese": "为中秋节准备生日蛋糕吗？！"}', 106, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4795, 147, '{"english": "My cousin''s birthday is on Mid-Autumn Festival this year!", "chinese": "我表弟的生日是在今年的中秋节！"}', 107, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4796, 147, '{"english": "Cool!", "chinese": "酷！"}', 108, '2026-02-05 04:01:17', '2026-02-05 04:01:17');
INSERT INTO "course_content" VALUES (4797, 148, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4798, 148, '{"english": "Which month are they talking about? Listen and tick.", "chinese": "他们在谈论哪个月份？听一听，勾一勾。"}', 2, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4799, 148, '{"english": "—When is the football match, Zhang Peng?", "chinese": "——张鹏，足球赛是哪天？"}', 3, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4800, 148, '{"english": "—It''s on April 30th.", "chinese": "——它在 4 月 30 日。"}', 4, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4801, 148, '{"english": "—Good luck.", "chinese": "——祝好运。"}', 5, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4802, 148, '{"english": "—Thank you.", "chinese": "——谢谢。"}', 6, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4803, 148, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4804, 148, '{"english": "There are some other special days in May.", "chinese": "五月还有一些特殊的日子。"}', 8, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4805, 148, '{"english": "What are they?", "chinese": "它们是什么？"}', 9, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4806, 148, '{"english": "The school art show and the reading festival.", "chinese": "学校艺术节和读书节。"}', 10, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4807, 148, '{"english": "When is the art show?", "chinese": "艺术节是哪天？"}', 11, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4808, 148, '{"english": "It''s on May 1st.", "chinese": "它在 5 月 1 日。"}', 12, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
INSERT INTO "course_content" VALUES (4809, 148, '{"english": "It''s Labour Day. When is the reading festival?", "chinese": "这天是劳动节。读书节是哪天？"}', 13, '2026-02-05 04:01:19', '2026-02-05 04:01:19');
