INSERT INTO "course_content" VALUES (4851, 148, '{"english": "Read, listen and chant.", "chinese": "读一读，听一听，唱一唱。"}', 55, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4852, 148, '{"english": "three", "chinese": "三"}', 56, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4853, 148, '{"english": "thin", "chinese": "瘦的"}', 57, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4854, 148, '{"english": "thirteen", "chinese": "十三"}', 58, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4855, 148, '{"english": "maths", "chinese": "数学"}', 59, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4856, 148, '{"english": "this", "chinese": "这；这个"}', 60, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4857, 148, '{"english": "that", "chinese": "那；那个"}', 61, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4858, 148, '{"english": "mother", "chinese": "母亲"}', 62, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4859, 148, '{"english": "brother", "chinese": "兄弟"}', 63, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4860, 148, '{"english": "Let''s chant.  My birthday is in three more days.", "chinese": "让我们唱一唱。 我的生日还有三天。"}', 64, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4861, 148, '{"english": "Three more days,", "chinese": "还有三天，"}', 65, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4862, 148, '{"english": "three more days.  My birthday is in three more days.", "chinese": "还有三天。 我的生日还有三天。"}', 66, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4863, 148, '{"english": "I will be thirteen.   My brother has a birthday, too.", "chinese": "我将十三岁了。  我的弟弟也过生日。"}', 67, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4864, 148, '{"english": "A birthday, too,", "chinese": "也过生日，"}', 68, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4865, 148, '{"english": "a birthday, too.  He has a birthday on the third of the month.  What about you?  My birthday is in three more days.", "chinese": "也过生日。 他在这个月的第三天过生日。 你呢？ 我的生日还有三天。"}', 69, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4866, 148, '{"english": "Three more days,", "chinese": "还有三天，"}', 70, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4867, 148, '{"english": "three more days.  My birthday is in three more days.  I will be thirteen.   My brother has a birthday, too.", "chinese": "还有三天。 我的生日还有三天。 我将十三岁了。  我的弟弟也过生日。"}', 71, '2026-02-05 04:01:20', '2026-02-05 04:01:20');
INSERT INTO "course_content" VALUES (4868, 148, '{"english": "A birthday, too,", "chinese": "也过生日，"}', 72, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4869, 148, '{"english": "a birthday, too.  He has a birthday on the third of the month.  What about you?", "chinese": "也过生日。 他在这个月的第三天过生日。你呢？"}', 73, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4870, 148, '{"english": "Listen, circle and say.", "chinese": "听一听，圈一圈，说一说。"}', 74, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4871, 148, '{"english": "1. maths", "chinese": "1. 数学"}', 75, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4872, 148, '{"english": "2. father", "chinese": "2. 爸爸"}', 76, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4873, 148, '{"english": "3. brother", "chinese": "3. 兄弟"}', 77, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4874, 148, '{"english": "4. birthday", "chinese": "4. 生日"}', 78, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4875, 148, '{"english": "5. there", "chinese": "5. 那里"}', 79, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4876, 148, '{"english": "6. third", "chinese": "6. 第三"}', 80, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4877, 148, '{"english": "Choose, write and say.", "chinese": "选一选，写一写，说一说。"}', 81, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4878, 148, '{"english": "Thursday/Monday is his eleventh/third/fourth birthday.", "chinese": "星期四/星期一是他的十一/三/四岁生日。"}', 82, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4879, 148, '{"english": "That is her brother/grandfather/father.", "chinese": "那是她的兄弟/（外）祖父/父亲。"}', 83, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4880, 148, '{"english": "His mother/brother is a maths/Chinese teacher.", "chinese": "他的母亲/兄弟是一名数学/语文教师。"}', 84, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4881, 148, '{"english": "1. Thursday is his eleventh birthday.", "chinese": "1. 星期四是他的十一岁生日。"}', 85, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4882, 148, '{"english": "—Great. See you then.", "chinese": "——太好了。那时候见。"}', 86, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4883, 148, '{"english": "3. -When is your birthday?", "chinese": "3. —你的生日是哪天？"}', 87, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4884, 148, '{"english": "-My birthday is on October 2nd.  -That''s next Sunday.  -Yes.", "chinese": "—我的生日是在 10 月 2 日。 —那就是下个星期天。 —是的。"}', 88, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4885, 148, '{"english": "4. -It''s my birthday soon.  -When is it?", "chinese": "4. —我的生日快到了。 —哪天？"}', 89, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4886, 148, '{"english": "-It''s on December 13th.  -It''s this Friday.  -Yes.", "chinese": "—是在 12 月 13 日。 —是这个星期五。 —是的。"}', 90, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4887, 148, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 91, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4888, 148, '{"english": "Fill in the table.", "chinese": "填表。"}', 92, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4889, 148, '{"english": "Finish the sentences.", "chinese": "完成句子。"}', 93, '2026-02-05 04:01:21', '2026-02-05 04:01:21');
INSERT INTO "course_content" VALUES (4890, 149, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4891, 149, '{"english": "Listen and tick. Which is John''s picture?", "chinese": "听一听，勾一勾。哪幅是约翰的画？"}', 2, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4892, 149, '{"english": "-The school art show is great.  -Yes. I like this picture.", "chinese": "—学校的艺术展真好。 —是的。我喜欢这幅画。"}', 3, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4893, 149, '{"english": "The trees are beautiful.  -Whose picture is it?", "chinese": "树很漂亮。 —它是谁的画？"}', 4, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4894, 149, '{"english": "-It''s John''s.  -What about the one over there?", "chinese": "—是约翰的。 —那边的那幅呢？"}', 5, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4895, 149, '{"english": "I like the blue colour.  -That''s mine.", "chinese": "我喜欢蓝色。 —那是我的。"}', 6, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4896, 149, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4897, 149, '{"english": "The yellow picture is mine. Are these all ours?", "chinese": "那幅黄颜色的画是我的。这些都是我们的画吗？"}', 8, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4898, 149, '{"english": "Yes, they are.", "chinese": "是的，它们是的。"}', 9, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4899, 149, '{"english": "Wow! That picture of Beijing is beautiful. Whose is it?", "chinese": "哇！那幅画北京的画真漂亮。它是谁的？"}', 10, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4900, 149, '{"english": "It''s Zhang Peng''s.", "chinese": "是张鹏的。"}', 11, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4901, 149, '{"english": "Look! There is a picture of Shanghai, too.", "chinese": "看！这也有一幅画上海的画。"}', 12, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4902, 149, '{"english": "It''s Binbin''s.", "chinese": "是斌斌的。"}', 13, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4903, 149, '{"english": "Oh, yes! It''s his.", "chinese": "哦，是的！是他的。"}', 14, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4904, 149, '{"english": "Ask and find out.", "chinese": "问一问，找一找。"}', 15, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4905, 149, '{"english": "Whose storybooks are these?", "chinese": "这些是谁的故事书？"}', 16, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4906, 149, '{"english": "They are mine.", "chinese": "它们是我的。"}', 17, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4907, 149, '{"english": "Whose book is this?", "chinese": "这是谁的书？"}', 18, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4908, 149, '{"english": "It''s Mike''s. It''s his.", "chinese": "是迈克的。是他的。"}', 19, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4909, 149, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 20, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4910, 149, '{"english": "Look! That''s my dog!", "chinese": "看！那是我的狗！"}', 21, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4911, 149, '{"english": "Yes! It''s your dog. The dog is yours.", "chinese": "是的！它是你的狗。这条狗是你的。"}', 22, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4912, 149, '{"english": "his dog — his", "chinese": "他的狗——他的（狗）"}', 23, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4913, 149, '{"english": "her dog — hers", "chinese": "她的狗——她的（狗）"}', 24, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4914, 149, '{"english": "their dog — theirs", "chinese": "他们的狗——他们的（狗）"}', 25, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4915, 149, '{"english": "It''s our dog. The dog is ours.", "chinese": "它是我们的狗。这条狗是我们的。"}', 26, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4916, 149, '{"english": "Zoom''s dog", "chinese": "佐姆的狗"}', 27, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4917, 149, '{"english": "my dog — mine", "chinese": "我的狗——我的（狗）"}', 28, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4918, 149, '{"english": "Look, say and complete", "chinese": "看一看，说一说，并完成表格"}', 29, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4919, 149, '{"english": "Whose book is that?", "chinese": "那是谁的书？"}', 30, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4920, 149, '{"english": "It''s Amy''s book.", "chinese": "这是埃米的书。"}', 31, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4921, 149, '{"english": "Ah! The book is hers.", "chinese": "啊！这本书是她的。"}', 32, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4922, 149, '{"english": "It''s her book.", "chinese": "这是她的书。"}', 33, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4923, 149, '{"english": "The book is hers.", "chinese": "这本书是她的。"}', 34, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
