INSERT INTO "course_content" VALUES (4934, 149, '{"english": "Let''s chant.  I think I can sing.", "chinese": "让我们一起唱。 我认为我会唱歌。"}', 45, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4935, 149, '{"english": "I think I can sing.  I think I can sing a song.", "chinese": "我认为我会唱歌。 我认为我能唱首歌。"}', 46, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4936, 149, '{"english": "I think I can sing.  I think I can sing.", "chinese": "我认为我会唱歌。 我认为我会唱歌。"}', 47, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4937, 149, '{"english": "A song that is not too long.  I think I can sing.", "chinese": "一首不太长的歌。 我认为我会唱歌。"}', 48, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4938, 149, '{"english": "I think I can sing.  I think I can sing a song.", "chinese": "我认为我会唱歌。 我认为我能唱首歌。"}', 49, '2026-02-05 04:01:24', '2026-02-05 04:01:24');
INSERT INTO "course_content" VALUES (4939, 149, '{"english": "I think I can sing.  I think I can sing.", "chinese": "我认为我会唱歌。 我认为我会唱歌。"}', 50, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4940, 149, '{"english": "A song that is not too long.", "chinese": "一首不太长的歌。"}', 51, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
