INSERT INTO "course_content" VALUES (4950, 149, '{"english": "thank", "chinese": "谢谢"}', 61, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4951, 149, '{"english": "morning", "chinese": "早上"}', 62, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
