INSERT INTO "course_content" VALUES (4954, 149, '{"english": "Look, listen and write.", "chinese": "看一看，听一听，写一写。"}', 65, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4955, 149, '{"english": "Zoom is eating.", "chinese": "佐姆正在吃东西。"}', 66, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4956, 149, '{"english": "John is jumping.", "chinese": "约翰正在跳。"}', 67, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4957, 149, '{"english": "Zip is drinking.", "chinese": "兹普正在喝水。"}', 68, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4958, 149, '{"english": "Sarah is singing.", "chinese": "萨拉正在唱歌。"}', 69, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4959, 149, '{"english": "—Where is Amy now?", "chinese": "——艾米现在在哪儿？"}', 70, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4960, 149, '{"english": "—She is shopping for us.", "chinese": "——她正在为我们购物。"}', 71, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4961, 149, '{"english": "—I see. What a good girl!", "chinese": "——明白了。真是个好女孩啊！"}', 72, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4962, 149, '{"english": "—Yes, she is.", "chinese": "——是的，她是。"}', 73, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4963, 149, '{"english": "2. —Look at the cat.", "chinese": "2. ——看这只猫。"}', 74, '2026-02-05 04:01:25', '2026-02-05 04:01:25');
INSERT INTO "course_content" VALUES (4964, 150, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4965, 150, '{"english": "Listen and tick.", "chinese": "听一听，勾一勾。"}', 2, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4966, 150, '{"english": "—Wow, there are so many animals in the zoo.", "chinese": "——哇，动物园里有这么多动物。"}', 3, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4967, 150, '{"english": "—Yes, I love them. Look! The birds are flying.", "chinese": "——是呀，我喜欢它们。看！鸟儿在飞翔。"}', 4, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4968, 150, '{"english": "—And there is a yellow tiger, too.", "chinese": "——还有一只黄色的老虎。"}', 5, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4969, 150, '{"english": "—Yes, it is running very fast.", "chinese": "——是的，它正在快速地跑着。"}', 6, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4970, 150, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 7, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4971, 150, '{"english": "Look at the pandas.", "chinese": "看那些熊猫。"}', 8, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4972, 150, '{"english": "What are they doing?", "chinese": "它们在做什么？"}', 9, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4973, 150, '{"english": "Haha. They''re eating lunch! They''re so cute.", "chinese": "哈哈。它们正在吃午饭！它们真可爱。"}', 10, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4974, 150, '{"english": "Oh, yes! They like bamboo.", "chinese": "哦，是的！它们喜欢竹子。"}', 11, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4975, 150, '{"english": "What''s the little monkey doing?", "chinese": "那只小猴子在做什么？"}', 12, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4976, 150, '{"english": "It''s playing with its mother!", "chinese": "它在和它的妈妈玩！"}', 13, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4977, 150, '{"english": "Do you see any elephants?", "chinese": "你看到大象了吗？"}', 14, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4978, 150, '{"english": "Yes! Look there! The elephant is drinking water.", "chinese": "是的！看那里！大象在喝水。"}', 15, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4979, 150, '{"english": "Choose and tell.", "chinese": "选一选，说一说。"}', 16, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4980, 150, '{"english": "We''re having an English class.", "chinese": "我们正在上英语课。"}', 17, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4981, 150, '{"english": "I''m eating dinner.", "chinese": "我正在吃晚饭。"}', 18, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4982, 150, '{"english": "I am  He/She is  We are  You are  They are", "chinese": "我是 他/她是 我们是 你（们）是 他们是"}', 19, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4983, 150, '{"english": "have ... class  clean ...", "chinese": "上⋯⋯课 打扫⋯⋯"}', 20, '2026-02-05 04:01:28', '2026-02-05 04:01:28');
INSERT INTO "course_content" VALUES (4984, 150, '{"english": "room  eat dinner  read a book  watch TV", "chinese": "房间 吃晚饭 看书 看电视"}', 21, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4985, 150, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 22, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4986, 150, '{"english": "It''s 7:30 p.m.What''s Chen Jie doing?", "chinese": "晚上 7:30 了。陈杰在做什么？"}', 23, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4987, 150, '{"english": "She''s listening to music. It''s 9 o''clock.", "chinese": "她在听音乐。9 点钟了。"}', 24, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4988, 150, '{"english": "What are the students doing?", "chinese": "学生们在做什么？"}', 25, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4989, 150, '{"english": "doing morning exercises", "chinese": "（正在）做早操"}', 26, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4990, 150, '{"english": "having ... class", "chinese": "（正在）上⋯⋯课"}', 27, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4991, 150, '{"english": "eating lunch", "chinese": "（正在）吃午饭"}', 28, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4992, 150, '{"english": "reading a book", "chinese": "（正在）看书"}', 29, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4993, 150, '{"english": "listening to music", "chinese": "（正在）听音乐"}', 30, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4994, 150, '{"english": "Look and say", "chinese": "看一看，说一说"}', 31, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4995, 150, '{"english": "Mike is listening to music.", "chinese": "迈克正在听音乐。"}', 32, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4996, 150, '{"english": "Talk quietly.", "chinese": "小声讲话。"}', 33, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4997, 150, '{"english": "1. He is talking in the library.", "chinese": "1. 他正在图书馆里讲话。"}', 34, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4998, 150, '{"english": "2. We are playing a game.", "chinese": "2. 我们正在玩游戏。"}', 35, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (4999, 150, '{"english": "3. She is colouring at her desk.", "chinese": "3. 她正在书桌前涂色。"}', 36, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5000, 150, '{"english": "4. They are writing in class.", "chinese": "4. 他们正在课堂上写作。"}', 37, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5001, 150, '{"english": "5. They are walking on a bridge.", "chinese": "5. 他们正在桥上散步。"}', 38, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5002, 150, '{"english": "A. Keep to the right.", "chinese": "A. 请靠右。"}', 39, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5003, 150, '{"english": "B. Talk quietly.", "chinese": "B. 小声讲话。"}', 40, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5004, 150, '{"english": "C. Take turns.", "chinese": "C. 按顺序。"}', 41, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5005, 150, '{"english": "D. Keep your desk clean.", "chinese": "D. 保持你的桌子干净。"}', 42, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5006, 150, '{"english": "E. Work quietly.", "chinese": "E. 安静地工作。"}', 43, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5007, 150, '{"english": "Read and write", "chinese": "读一读，写一写"}', 44, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5008, 150, '{"english": "The world robot exhibition", "chinese": "世界机器人展"}', 45, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5009, 150, '{"english": "Ni hao, Ni zai gan shen me ne?", "chinese": "你好，你在干什么呢？"}', 46, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5010, 150, '{"english": "Sorry. What are you saying?", "chinese": "抱歉。你在说什么？"}', 47, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5011, 150, '{"english": "I''m speaking Chinese.", "chinese": "我在讲中文。"}', 48, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5012, 150, '{"english": "Oh, hello. What are you doing?", "chinese": "哦，你好。你在做什么？"}', 49, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5013, 150, '{"english": "I''m drawing a picture. Have a look.", "chinese": "我正在画一幅画。看一看。"}', 50, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5014, 150, '{"english": "It''s lovely.", "chinese": "它很可爱。"}', 51, '2026-02-05 04:01:29', '2026-02-05 04:01:29');
INSERT INTO "course_content" VALUES (5015, 150, '{"english": "Are you cooking?", "chinese": "你在做饭吗？"}', 52, '2026-02-05 04:01:30', '2026-02-05 04:01:30');
INSERT INTO "course_content" VALUES (5016, 150, '{"english": "Yes. I''m cooking rice. Asako is making sushi.", "chinese": "是的。我在烧米饭。朝子正在做寿司。"}', 53, '2026-02-05 04:01:30', '2026-02-05 04:01:30');
INSERT INTO "course_content" VALUES (5017, 150, '{"english": "Can we play music with you?", "chinese": "我们能和你一起演奏音乐吗？"}', 54, '2026-02-05 04:01:30', '2026-02-05 04:01:30');
INSERT INTO "course_content" VALUES (5018, 151, '{"english": "Recycle 2", "chinese": "复习 2"}', 1, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5019, 151, '{"english": "Mike''s summer camp", "chinese": "迈克的夏令营"}', 2, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5020, 151, '{"english": "Mike is at summer camp.", "chinese": "迈克在夏令营。"}', 3, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5021, 151, '{"english": "What will he do? Listen and match.", "chinese": "他将会做什么？听一听，连一连。"}', 4, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5022, 151, '{"english": "Dialogue 1", "chinese": "对话 1"}', 5, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5023, 151, '{"english": "—Hi, Mum.", "chinese": "——嗨，妈妈。"}', 6, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5024, 151, '{"english": "—Hi. How is your summer camp?", "chinese": "——嗨。你的夏令营怎么样？"}', 7, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5025, 151, '{"english": "—Fine. Today, we''ll have an art class.", "chinese": "——很好。今天我们将要上美术课。"}', 8, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5026, 151, '{"english": "—Good.", "chinese": "——不错。"}', 9, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5027, 151, '{"english": "—On August 1st, we''ll have a sports day.", "chinese": "——在 8 月 1 日，我们会开运动会。"}', 10, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5028, 151, '{"english": "Dialogue 2", "chinese": "对话 2"}', 11, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5029, 151, '{"english": "—What are you doing now?", "chinese": "——你们现在在做什么？"}', 12, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5030, 151, '{"english": "—We''re listening to music. We''ll have lunch.", "chinese": "——我们正在听音乐。我们要吃午饭了。"}', 13, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5031, 151, '{"english": "—I see. What''s for lunch?", "chinese": "——明白了。午饭吃什么？"}', 14, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5032, 151, '{"english": "—Potatoes and rice.", "chinese": "——土豆和米饭。"}', 15, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5033, 151, '{"english": "Dialogue 3", "chinese": "对话 3"}', 16, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5034, 151, '{"english": "—What else will you do at camp?", "chinese": "——你们在夏令营还将会做什么？"}', 17, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5035, 151, '{"english": "—On the 6th, we''ll have a trip to the forest.", "chinese": "——在 6 日，我们将去森林旅行。"}', 18, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5036, 151, '{"english": "—That sounds fun.", "chinese": "——那听起来很有趣。"}', 19, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5037, 151, '{"english": "—And on the 11th, we''ll have a party.", "chinese": "——然后在 11 日，我们将举办聚会。"}', 20, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5038, 151, '{"english": "—Great!", "chinese": "——真好！"}', 21, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5039, 151, '{"english": "Dialogue 4", "chinese": "对话 4"}', 22, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5040, 151, '{"english": "—OK, Mike. Be a good boy! Keep your room clean.", "chinese": "——好的，迈克。做个乖孩子！保持你的房间整洁。"}', 23, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5041, 151, '{"english": "—I will.", "chinese": "——我会的。"}', 24, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5042, 151, '{"english": "—See you at home on August 12th.", "chinese": "——8 月 12 日在家里见。"}', 25, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5043, 151, '{"english": "—OK. Bye-bye. I love you, Mum.", "chinese": "——好的。再见。我爱你，妈妈。"}', 26, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5044, 151, '{"english": "—Love you, too.", "chinese": "——我也爱你。"}', 27, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5045, 151, '{"english": "Listen to dialogue 2 and tick the right picture.", "chinese": "听一听对话 2 ，勾选出正确的图片。"}', 28, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5046, 151, '{"english": "What are the children doing?", "chinese": "孩子们正在做什么？"}', 29, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5047, 151, '{"english": "—What are you doing now?", "chinese": "——你们现在在做什么？"}', 30, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5048, 151, '{"english": "—We''re listening to music. We''ll have lunch.", "chinese": "——我们正在听音乐。我们要吃午饭了。"}', 31, '2026-02-05 04:01:32', '2026-02-05 04:01:32');
INSERT INTO "course_content" VALUES (5049, 151, '{"english": "—I see. What''s for lunch?", "chinese": "——明白了。午饭吃什么？"}', 32, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5050, 151, '{"english": "—Potatoes and rice.", "chinese": "——土豆和米饭。"}', 33, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5051, 151, '{"english": "Listen to dialogue 1 and 4. Choose the right answers.", "chinese": "听一听对话 1 和对话 4。选择正确答案。"}', 34, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5052, 151, '{"english": "Dialogue 1", "chinese": "对话 1"}', 35, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5053, 151, '{"english": "—Hi, Mum.", "chinese": "——嗨，妈妈。"}', 36, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5054, 151, '{"english": "—Hi. How is your summer camp?", "chinese": "——嗨。你的夏令营怎么样？"}', 37, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5055, 151, '{"english": "—Fine. Today, we''ll have an art class.", "chinese": "——很好。今天，我们将要上美术课。"}', 38, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5056, 151, '{"english": "—Good.", "chinese": "——不错。"}', 39, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5057, 151, '{"english": "—On August 1st, we''ll have a sports day.", "chinese": "——在 8 月 1 日，我们会开运动会。"}', 40, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5058, 151, '{"english": "Dialogue 4  —OK, Mike. Be a good boy! Keep your room clean.", "chinese": "对话 4 ——好的，迈克。做个乖孩子！保持你的房间整洁。"}', 41, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5059, 151, '{"english": "—I will.  —See you at home on August twelfth.", "chinese": "——我会的。 ——8 月 12 日在家里见。"}', 42, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5060, 151, '{"english": "—OK. Bye-bye. I love you, Mum.  —Love you, too.", "chinese": "——好的。再见。我爱你，妈妈。 ——我也爱你。"}', 43, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5061, 151, '{"english": "Read the chant and write the months in the correct column.", "chinese": "读儿歌并在正确的栏中写上月份。"}', 44, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5062, 151, '{"english": "Thirty days has September,April,June and November;  February has twenty-eight alone.", "chinese": "九月、四月、六月、十一月都有三十天； 只有二月是二十八天。"}', 45, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5063, 151, '{"english": "All the rest have thirty-one", "chinese": "其他剩下的都是三十一天"}', 46, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5064, 151, '{"english": "Except in leap year. That''s the time  When February''s days are twenty-nine.", "chinese": "除了闰年。那个时候 二月有二十九天。"}', 47, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5065, 151, '{"english": "A game: Animals and dates", "chinese": "游戏：动物和日期"}', 48, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5066, 151, '{"english": "Pandas, pandas and pandas. Tell me when Children''s Day comes.", "chinese": "熊猫，熊猫，熊猫。告诉我儿童节什么时候来。"}', 49, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
INSERT INTO "course_content" VALUES (5067, 151, '{"english": "It''s on June 1st.", "chinese": "它在 6 月 1 日。"}', 50, '2026-02-05 04:01:33', '2026-02-05 04:01:33');
