INSERT INTO "course_content" VALUES (5071, 152, '{"english": "I like to do things on the weekend.", "chinese": "我喜欢在周末做一些事情。"}', 4, '2026-02-05 04:01:34', '2026-02-05 04:01:34');
INSERT INTO "course_content" VALUES (5072, 152, '{"english": "I clean my room and go shopping at the mall.", "chinese": "我打扫我的房间，去商场购物。"}', 5, '2026-02-05 04:01:34', '2026-02-05 04:01:34');
INSERT INTO "course_content" VALUES (5073, 152, '{"english": "I have a music class and do exercises.", "chinese": "我上音乐课，做锻炼。"}', 6, '2026-02-05 04:01:34', '2026-02-05 04:01:34');
INSERT INTO "course_content" VALUES (5074, 152, '{"english": "I play football and play basketball.", "chinese": "我踢足球和打篮球。"}', 7, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
INSERT INTO "course_content" VALUES (5075, 152, '{"english": "I like to do things on the weekend.", "chinese": "我喜欢在周末做一些事情。"}', 8, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
INSERT INTO "course_content" VALUES (5076, 152, '{"english": "I clean my room and go shopping at the mall.", "chinese": "我打扫我的房间，去商场购物。"}', 9, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
