INSERT INTO "course_content" VALUES (5081, 152, '{"english": "Summer, winter,  Spring and fall,  What''s your favourite season?", "chinese": "夏天、冬天， 春天和秋天， 你最喜欢的季节是什么？"}', 14, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
