INSERT INTO "course_content" VALUES (5086, 152, '{"english": "Apples, peaches, pears and plums,  Tell me when your birthday comes.", "chinese": "苹果、桃子、梨子和李子， 告诉我你们的生日什么时候来临。"}', 19, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
