INSERT INTO "course_content" VALUES (5094, 152, '{"english": "My birthday is in January.  My birthday is in January.", "chinese": "我的生日是在 1 月。 我的生日是在 1 月。"}', 27, '2026-02-05 04:01:35', '2026-02-05 04:01:35');
