INSERT INTO "course_content" VALUES (5288, 155, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5289, 155, '{"english": "When do you finish class in the morning?", "chinese": "你们上午的课到几点结束？"}', 3, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5290, 155, '{"english": "We finish class at 1 o''clock.", "chinese": "我们一点钟结束上午的课。"}', 4, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5291, 155, '{"english": "What do you do on the weekend?", "chinese": "你周末做什么？"}', 5, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5292, 155, '{"english": "I often watch TV and play ping-pong with my father.", "chinese": "我经常看电视，也常和我爸爸一起打乒乓球。"}', 6, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5293, 155, '{"english": "Unit 2", "chinese": "第 2 单元"}', 7, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5294, 155, '{"english": "Which season do you like best, Miss White?", "chinese": "怀特小姐，你最喜欢哪个季节？"}', 8, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5295, 155, '{"english": "Summer.", "chinese": "夏天。"}', 9, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5296, 155, '{"english": "Why?", "chinese": "为什么？"}', 10, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5297, 155, '{"english": "Because I like summer vacation!", "chinese": "因为我喜欢暑假！"}', 11, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5298, 155, '{"english": "Unit 3", "chinese": "第 3 单元"}', 12, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5299, 155, '{"english": "When is the party?", "chinese": "聚会什么时候举行？"}', 13, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5300, 155, '{"english": "It''s in April.", "chinese": "在 4 月。"}', 14, '2026-02-05 04:01:46', '2026-02-05 04:01:46');
INSERT INTO "course_content" VALUES (5301, 156, '{"english": "Are these all ours?", "chinese": "这些都是我们的画吗？"}', 1, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5302, 156, '{"english": "Whose is it?", "chinese": "这是谁的？"}', 2, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5303, 156, '{"english": "It''s Zhang Peng''s.", "chinese": "是张鹏的。"}', 3, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5304, 156, '{"english": "Is he drinking water?", "chinese": "他在喝水吗？"}', 4, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5305, 156, '{"english": "No, he isn''t. He''s eating.", "chinese": "不是。他在吃东西。"}', 5, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5306, 156, '{"english": "Unit 6", "chinese": "第 6 单元"}', 6, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5307, 156, '{"english": "What are they doing?", "chinese": "它们在干什么？"}', 7, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5308, 156, '{"english": "They''re eating lunch!", "chinese": "它们正在吃午饭！"}', 8, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5309, 156, '{"english": "What''s the little monkey doing?", "chinese": "那只小猴子在干什么？"}', 9, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5310, 156, '{"english": "It''s playing with its mother!", "chinese": "它在和妈妈玩耍！"}', 10, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5311, 156, '{"english": "Shh. Talk quietly.", "chinese": "嘘，小声讲话。"}', 11, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5312, 156, '{"english": "Keep your desk clean.", "chinese": "保持桌面整洁。"}', 12, '2026-02-05 04:01:48', '2026-02-05 04:01:48');
INSERT INTO "course_content" VALUES (5313, 157, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5314, 157, '{"english": "Wu Binbin and Robin are looking at some robots.", "chinese": "吴斌斌和罗宾正在参观一些机器人。"}', 2, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5315, 157, '{"english": "Listen and tick.", "chinese": "听录音并打勾。"}', 3, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5316, 157, '{"english": "-These robots are so cool! I love this museum!  -Me too.", "chinese": "—这些机器人太酷了！我喜欢这个博物馆！ —我也喜欢。"}', 4, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5317, 157, '{"english": "Don''t forget to buy some gifts for Grandpa.  -I know.", "chinese": "别忘了给爷爷买些礼物。 —我知道。"}', 5, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5318, 157, '{"english": "But I really need to go to the bathroom. Where is it?  -It''s on the second floor.  -OK. Thanks.", "chinese": "但我真的需要去洗手间。它在哪里？ —在二楼。 —好的。谢谢。"}', 6, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5319, 157, '{"english": "1. Where are they?", "chinese": "1.他们在哪里？"}', 7, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5320, 157, '{"english": "2. Is Grandpa there?", "chinese": "2.爷爷在吗？"}', 8, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5321, 157, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 9, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5322, 157, '{"english": "Robin, where is the museum shop?", "chinese": "罗宾，博物馆的商店在哪儿？"}', 10, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5323, 157, '{"english": "I want to buy a postcard.", "chinese": "我想买张明信片。"}', 11, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5324, 157, '{"english": "It''s near the door.", "chinese": "在门附近。"}', 12, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5325, 157, '{"english": "Thanks. Where is the post office?", "chinese": "谢谢。邮局在哪里？"}', 13, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5326, 157, '{"english": "I want to send it today.", "chinese": "我想今天就寄出去。"}', 14, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5327, 157, '{"english": "I don''t know. I''ll ask. Excuse me, sir.", "chinese": "我不知道。我问一下。打扰一下，先生。"}', 15, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5328, 157, '{"english": "Wow! A talking robot! What a great museum!", "chinese": "哇！一个会说话的机器人！多么伟大的博物馆啊！"}', 16, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5329, 157, '{"english": "Where is the post office?", "chinese": "邮局在哪里？"}', 17, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5330, 157, '{"english": "It''s next to the museum.", "chinese": "在博物馆的旁边。"}', 18, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5331, 157, '{"english": "Thanks.", "chinese": "谢谢。"}', 19, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5332, 157, '{"english": "Where is the museum shop/post office?", "chinese": "博物馆商店/邮局在哪里？"}', 20, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5333, 157, '{"english": "park", "chinese": "公园"}', 21, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5334, 157, '{"english": "library", "chinese": "图书馆"}', 22, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5335, 157, '{"english": "zoo", "chinese": "动物园"}', 23, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
INSERT INTO "course_content" VALUES (5336, 157, '{"english": "post office", "chinese": "邮局"}', 24, '2026-02-05 04:01:51', '2026-02-05 04:01:51');
