INSERT INTO "course_content" VALUES (5339, 157, '{"english": "Talk about the places in your city.", "chinese": "谈谈关于你所在的城市里的地方。"}', 27, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5340, 157, '{"english": "Talk about the places in your town.", "chinese": "谈谈关于你所在的城镇的地方。"}', 28, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5341, 157, '{"english": "Talk about the places in your village.", "chinese": "谈谈关于你所在的村庄里的地方。"}', 29, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5342, 157, '{"english": "Is there a ...?", "chinese": "那有⋯⋯吗？"}', 30, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5343, 157, '{"english": "Where is it?", "chinese": "它在哪里？"}', 31, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5344, 157, '{"english": "It''s near/next to/behind ...", "chinese": "它在⋯⋯附近/旁边/后面"}', 32, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5345, 157, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 33, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5346, 157, '{"english": "Where is the cinema?", "chinese": "电影院在哪里？"}', 34, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5347, 157, '{"english": "It''s next to the bookstore.", "chinese": "它在书店旁边。"}', 35, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5348, 157, '{"english": "science museum", "chinese": "科学博物馆"}', 36, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5349, 157, '{"english": "post office", "chinese": "邮局"}', 37, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
