INSERT INTO "course_content" VALUES (5354, 157, '{"english": "pet hospital", "chinese": "宠物医院"}', 42, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5355, 157, '{"english": "park", "chinese": "公园"}', 43, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5356, 157, '{"english": "There is a pet hospital in my city.", "chinese": "我的城市有一家宠物医院。"}', 44, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5357, 157, '{"english": "Where is it?", "chinese": "它在哪里？"}', 45, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5358, 157, '{"english": "It''s near the park.", "chinese": "在公园附近。"}', 46, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5359, 157, '{"english": "Wu Binbin''s grandpa gave Robin a new feature.", "chinese": "吴斌斌的爷爷给罗宾装了一个新功能。"}', 47, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5360, 157, '{"english": "He now has BDS.", "chinese": "他现在有了北斗导航系统。"}', 48, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5361, 157, '{"english": "He can help the boys find the Italian restaurant.", "chinese": "他可以帮助男孩们找到意大利餐厅。"}', 49, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5362, 157, '{"english": "We''re in front of the cinema.", "chinese": "我们现在在电影院前面。"}', 50, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5363, 157, '{"english": "Let''s go straight and turn left at the bookstore. Follow me, please!", "chinese": "让我们直走然后在书店左拐。请跟我来！"}', 51, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5364, 157, '{"english": "Is it far?", "chinese": "那儿远吗？"}', 52, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5365, 157, '{"english": "No. Now we are behind the hospital.", "chinese": "不。现在我们在医院后面。"}', 53, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5366, 157, '{"english": "Let''s turn right and then turn right again.", "chinese": "让我们右转后再右转一次。"}', 54, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5367, 157, '{"english": "There is the restaurant!", "chinese": "那边有个餐厅！"}', 55, '2026-02-05 04:01:52', '2026-02-05 04:01:52');
INSERT INTO "course_content" VALUES (5368, 157, '{"english": "My BDS works!", "chinese": "我的 BDS 很有用！"}', 56, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5369, 157, '{"english": "Yes! I''ll tell Grandpa.", "chinese": "对！我会告诉爷爷的。"}', 57, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5370, 157, '{"english": "But let''s eat first. I''m so hungry!", "chinese": "但是我们先吃饭吧。我太饿了！"}', 58, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5371, 157, '{"english": "Read the text and answer the questions.", "chinese": "阅读课文并回答问题。"}', 59, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5372, 157, '{"english": "1. What is Robin''s new feature?", "chinese": "1. 罗宾的新功能是什么？"}', 60, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5373, 157, '{"english": "He can find food.  He can find the way.", "chinese": "他能找到食物。 他能找到路。"}', 61, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5374, 157, '{"english": "2. How many places did they pass by?", "chinese": "2. 他们经过多少地方？"}', 62, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5375, 157, '{"english": "Underline them in the text.", "chinese": "在课文中给它们划下划线。"}', 63, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5376, 157, '{"english": "3. Which word under the fourth picture means ''奏效，起作用''?", "chinese": "3. 在第四张图片下面的哪一个单词的意思是“奏效，起作用”？"}', 64, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5377, 157, '{"english": "Fill in the blanks. Then retell the story.", "chinese": "填空。然后复述故事。"}', 65, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5378, 157, '{"english": "Wu Binbin and his friends want to eat some pizza in an Italian restaurant.", "chinese": "吴斌斌和他的朋友们想在一家意大利餐馆吃披萨。"}', 66, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5379, 157, '{"english": "They ______ and ______.", "chinese": "他们______然后______。"}', 67, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5380, 157, '{"english": "They ______ and then turn right again.", "chinese": "他们______然后再右转。"}', 68, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5381, 157, '{"english": "Tips for pronunciation", "chinese": "发音小贴士"}', 69, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5382, 157, '{"english": "Listen, look and say.", "chinese": "听一听，看一看，说一说。"}', 70, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5383, 157, '{"english": "Robin has BDS.", "chinese": "罗宾有北斗导航系统。"}', 71, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5384, 157, '{"english": "Follow me, please!", "chinese": "请跟我来！"}', 72, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5385, 157, '{"english": "Is it far?", "chinese": "那儿远吗？"}', 73, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5386, 157, '{"english": "Where is the restaurant?", "chinese": "餐厅在哪里？"}', 74, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5387, 157, '{"english": "Let''s check", "chinese": "让我们检查一下"}', 75, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5388, 157, '{"english": "Listen and tick the places you hear.", "chinese": "听录音，勾出你听到的地方。"}', 76, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5389, 157, '{"english": "Write the words under the pictures.", "chinese": "并把单词写在图片下面。"}', 77, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5390, 157, '{"english": "Today, I want to go to the museum.", "chinese": "今天，我想去博物馆。"}', 78, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5391, 157, '{"english": "From my school, I go straight and turn left at the post office.", "chinese": "从学校出发，我一直向前直走，在邮局左转。"}', 79, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5392, 157, '{"english": "I can see the bookstore there. From there, I go straight ahead.", "chinese": "我可以在那里看到书店。从那里开始，我一直往前走。"}', 80, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5393, 157, '{"english": "Then, at the cinema, I turn right.", "chinese": "然后，在电影院处右拐。"}', 81, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5394, 157, '{"english": "Finally, I''m at the museum. It''s not far.", "chinese": "最后，我到了博物馆。它不是很远。"}', 82, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5395, 157, '{"english": "Listen again and answer.", "chinese": "再听一遍并回答问题。"}', 83, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5396, 157, '{"english": "1. Where does the boy want to go?", "chinese": "1. 这个男孩想去哪里？"}', 84, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5397, 157, '{"english": "2. How can he get there from the post office?", "chinese": "2. 他怎么从邮局到那里？"}', 85, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5398, 157, '{"english": "Today, I want to go to the museum.", "chinese": "今天，我想去博物馆。"}', 86, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5399, 157, '{"english": "From my school, I go straight and turn left at the post office.", "chinese": "从学校出发，我一直向前直走，在邮局左转。"}', 87, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5400, 157, '{"english": "I can see the bookstore there. From there, I go straight ahead.", "chinese": "我可以在那里看到书店。从那里开始，我一直往前走。"}', 88, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5401, 157, '{"english": "Then, at the cinema, I turn right.", "chinese": "然后，在电影院处右拐。"}', 89, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5402, 157, '{"english": "Finally, I''m at the museum. It''s not far.", "chinese": "最后，我到了博物馆。它不是很远。"}', 90, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5403, 157, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 91, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5404, 157, '{"english": "Try to write more words.", "chinese": "试着写出更多单词。"}', 92, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5405, 157, '{"english": "Can you make sentences with these words?", "chinese": "你能用这些词造句吗？"}', 93, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5406, 157, '{"english": "next to", "chinese": "紧邻"}', 94, '2026-02-05 04:01:53', '2026-02-05 04:01:53');
INSERT INTO "course_content" VALUES (5407, 157, '{"english": "near", "chinese": "靠近"}', 95, '2026-02-05 04:01:54', '2026-02-05 04:01:54');
INSERT INTO "course_content" VALUES (5408, 157, '{"english": "beside", "chinese": "在⋯⋯旁边"}', 96, '2026-02-05 04:01:54', '2026-02-05 04:01:54');
INSERT INTO "course_content" VALUES (5409, 158, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5410, 158, '{"english": "Amy meets Mike at school this morning.", "chinese": "今天早上艾米在学校遇见了迈克。"}', 2, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5411, 158, '{"english": "Listen and tick or cross.", "chinese": "听录音，判断正误。"}', 3, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5412, 158, '{"english": "-Morning, Mike.  -Morning. Hey, don''t forget!", "chinese": "—早上好，迈克。 —早晨好。嘿，别忘了"}', 4, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5413, 158, '{"english": "Mrs Smith will take us to the nature park next Wednesday.", "chinese": "史密斯老师下周三会带我们去自然公园。"}', 5, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5414, 158, '{"english": "-Oh, yes. How do we get to the nature park?", "chinese": "—哦，对哦。那我们怎么去自然公园？"}', 6, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5415, 158, '{"english": "-By bus.  -Look! There''s Mrs Smith now!", "chinese": "—乘公共汽车。 —看！那是史密斯老师！"}', 7, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5416, 158, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 8, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5417, 158, '{"english": "Good morning, Mrs Smith!", "chinese": "早上好，史密斯老师！"}', 9, '2026-02-05 04:01:56', '2026-02-05 04:01:56');
INSERT INTO "course_content" VALUES (5418, 158, '{"english": "Hi, children. You''re early. How do you come to school?", "chinese": "嗨，孩子们。你们来得真早。你们怎么来学校的？"}', 10, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5419, 158, '{"english": "Usually, I come on foot. Sometimes I come by bus.", "chinese": "通常，我是步行来的。有时我坐公共汽车来。"}', 11, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5420, 158, '{"english": "I often come by bike.", "chinese": "我经常骑自行车来。"}', 12, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5421, 158, '{"english": "How do you come to school, Mrs Smith? By car?", "chinese": "你怎么来学校的，史密斯老师？坐小汽车？"}', 13, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5422, 158, '{"english": "Sometimes, but I usually walk.", "chinese": "有时坐小汽车，但我通常走路。"}', 14, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5423, 158, '{"english": "That''s good exercise.", "chinese": "那是很好的锻炼方式。"}', 15, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5424, 158, '{"english": "How do Mike, Amy and Mrs Smith come to school?", "chinese": "迈克、艾米和史密斯老师是怎么来学校的？"}', 16, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5425, 158, '{"english": "What about your classmates and teachers? Do a survey.", "chinese": "关于你的同学和老师呢？做个调查."}', 17, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5426, 158, '{"english": "How do you come to school?", "chinese": "你怎么来学校的？"}', 18, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5427, 158, '{"english": "I usually/often/sometimes ...", "chinese": "我通常/经常/有时⋯⋯"}', 19, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5428, 158, '{"english": "usually", "chinese": "通常"}', 20, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5429, 158, '{"english": "often", "chinese": "经常"}', 21, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5430, 158, '{"english": "sometimes", "chinese": "有时"}', 22, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5431, 158, '{"english": "Three students usually come to school by bike.", "chinese": "三个学生通常骑自行车来学校。"}', 23, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5432, 158, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 24, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5433, 158, '{"english": "Let''s go to the nature park.", "chinese": "让我们去自然公园吧。"}', 25, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5434, 158, '{"english": "Hooray!", "chinese": "好哇！"}', 26, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5435, 158, '{"english": "How do we get there?", "chinese": "我们怎样去那儿呢？"}', 27, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5436, 158, '{"english": "By bus.", "chinese": "乘公共汽车。"}', 28, '2026-02-05 04:01:57', '2026-02-05 04:01:57');
INSERT INTO "course_content" VALUES (5437, 158, '{"english": "on foot", "chinese": "步行"}', 29, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5438, 158, '{"english": "by bus", "chinese": "乘公共汽车"}', 30, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5439, 158, '{"english": "by taxi", "chinese": "乘出租车"}', 31, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5440, 158, '{"english": "by plane", "chinese": "乘飞机"}', 32, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5441, 158, '{"english": "by ship", "chinese": "乘船"}', 33, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5442, 158, '{"english": "by subway", "chinese": "乘地铁"}', 34, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5443, 158, '{"english": "by train", "chinese": "乘火车"}', 35, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5444, 158, '{"english": "Write and say", "chinese": "写一写，说一说"}', 36, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5445, 158, '{"english": "From", "chinese": "从⋯⋯来"}', 37, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5446, 158, '{"english": "How?", "chinese": "怎么样？"}', 38, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5447, 158, '{"english": "To", "chinese": "去到"}', 39, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5448, 158, '{"english": "China", "chinese": "中国"}', 40, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5449, 158, '{"english": "USA", "chinese": "美国"}', 41, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5450, 158, '{"english": "your school", "chinese": "你的学校"}', 42, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5451, 158, '{"english": "your home", "chinese": "你的家"}', 43, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5452, 158, '{"english": "How do you get to the USA from China?", "chinese": "你怎么从中国去美国？"}', 44, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5453, 158, '{"english": "By plane.", "chinese": "乘飞机去。"}', 45, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5454, 158, '{"english": "because the ferry didn''t work.", "chinese": "因为渡船不工作。"}', 46, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5455, 158, '{"english": "Grandpa, let me read this for you.", "chinese": "爷爷，我来给你读这个。"}', 47, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5456, 158, '{"english": "Thanks, Robin.", "chinese": "谢谢，罗宾。"}', 48, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5457, 158, '{"english": "I don''t go to school. I learn at home.", "chinese": "我不上学。我在家学习。"}', 49, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5458, 158, '{"english": "Read the text and answer the questions.", "chinese": "阅读课文并回答问题。"}', 50, '2026-02-05 04:01:58', '2026-02-05 04:01:58');
INSERT INTO "course_content" VALUES (5459, 158, '{"english": "1. How many ways to go to school can you find in the text?", "chinese": "1. 你能在课文中找到多少上学的方法？"}', 51, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5460, 158, '{"english": "Underline them.", "chinese": "在它们下面划线。"}', 52, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5461, 158, '{"english": "2. Does everyone in the text go to school?", "chinese": "2. 课文里的每个人都上学吗？"}', 53, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5462, 158, '{"english": "Choose some suggestions for the kids on page 18.", "chinese": "在第 18 页，为孩子们选择一些建议。"}', 54, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5463, 158, '{"english": "Pay attention!", "chinese": "注意！"}', 55, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5464, 158, '{"english": "You must", "chinese": "你必须"}', 56, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5465, 158, '{"english": "On foot  You must stop at a red light.", "chinese": "步行 你必须在红灯时停下。"}', 57, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5466, 158, '{"english": "By sled  You must drive slowly.", "chinese": "乘雪橇 你必须慢行。"}', 58, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5467, 158, '{"english": "By subway  You must mind the gap.", "chinese": "乘地铁 你必须注意空隙。"}', 59, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5468, 158, '{"english": "Don''t", "chinese": "不要"}', 60, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5469, 158, '{"english": "On foot  Don''t go at a red light.", "chinese": "步行 不要闯红灯。"}', 61, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5470, 158, '{"english": "By sled  Don''t let the dogs run too fast.", "chinese": "坐雪橇 别让狗跑得太快。"}', 62, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5471, 158, '{"english": "By subway  Don''t run on the subway.", "chinese": "乘地铁 不要在地铁上跑。"}', 63, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5472, 158, '{"english": "What suggestions will you give to your friends?", "chinese": "你会给你的朋友什么建议？"}', 64, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5473, 158, '{"english": "Make a poster.", "chinese": "制作一张海报。"}', 65, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5474, 158, '{"english": "Tips for pronunciation", "chinese": "发音小贴士"}', 66, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5475, 158, '{"english": "Listen, look and say.", "chinese": "听一听，看一看，说一说。"}', 67, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5476, 158, '{"english": "come and have a look", "chinese": "过来并看看"}', 68, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5477, 158, '{"english": "pictures of", "chinese": "⋯⋯的图片"}', 69, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5478, 158, '{"english": "stop at a red light", "chinese": "红灯停"}', 70, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5479, 158, '{"english": "Look at the text on page 18.", "chinese": "看第 18 页的课文。"}', 71, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5480, 158, '{"english": "Find and say more like these.", "chinese": "找到并说出更多这样的话。"}', 72, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5481, 158, '{"english": "Let''s check", "chinese": "让我们测一测"}', 73, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5482, 158, '{"english": "Listen and number.", "chinese": "听录音，并排序。"}', 74, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5483, 158, '{"english": "1. -Excuese me, how can I get to the park?", "chinese": "1. —不好意思，我怎么去公园？"}', 75, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5484, 158, '{"english": "-Take the number 25 bus.  -Can I go on foot?", "chinese": "—坐25路公共汽车。 —我能步行去吗？"}', 76, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5485, 158, '{"english": "-No, it''s too far. Go by bus.", "chinese": "—不，太远了。坐公共汽车去。"}', 77, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5486, 158, '{"english": "2. -My father works near my home. It''s great.", "chinese": "2. —我父亲在我家附近工作。太棒了！"}', 78, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5487, 158, '{"english": "-My father works in the city.  -How does he go to work?  -Usually, by train.", "chinese": "—我父亲在城里工作。 —他怎么去上班？ —通常是坐火车。"}', 79, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5488, 158, '{"english": "3. -Hey, Amy. School is over.", "chinese": "3. —嘿，艾米。放学了。"}', 80, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5489, 158, '{"english": "How do you go home?  -I usually go on foot.", "chinese": "你怎么回家？ —我通常步行回家。"}', 81, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5490, 158, '{"english": "And you? By bus?  -No, I go on foot, too.", "chinese": "你呢？乘公共汽车吗？ —不，我也步行回家。"}', 82, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5491, 158, '{"english": "4. -Don''t cross the street now.  -Why? There are no cars coming.", "chinese": "4. —现在不要过马路。 —为什么？没有车来。"}', 83, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5492, 158, '{"english": "-It''s a red light. Cars are very fast. It''s dangerous.  -OK.", "chinese": "—现在是红灯。汽车速度很快。这很危险。 —好吧。"}', 84, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5493, 158, '{"english": "Listen again and answer the questions.", "chinese": "再听一遍，并回答问题。"}', 85, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5494, 158, '{"english": "1. -Excuese me, how can I get to the park?", "chinese": "1. —不好意思，我怎么去公园？"}', 86, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5495, 158, '{"english": "-Take the number 25 bus.  -Can I go on foot?", "chinese": "—坐 25 路公共汽车。 —我能步行去吗？"}', 87, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5496, 158, '{"english": "-No, it''s too far. Go by bus.", "chinese": "—不，太远了。坐公共汽车去。"}', 88, '2026-02-05 04:01:59', '2026-02-05 04:01:59');
INSERT INTO "course_content" VALUES (5497, 158, '{"english": "How does Wu Binbin go to the park?", "chinese": "吴斌斌怎么去学校？"}', 89, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5498, 158, '{"english": "2. -My father works near my home.", "chinese": "2. —我父亲在我家附近工作。"}', 90, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5499, 158, '{"english": "It''s great.  -My father works in the city.", "chinese": "太棒了！ —我父亲在城里工作。"}', 91, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5500, 158, '{"english": "-How does he go to work?  -Usually, by train.", "chinese": "—他怎么去上班？ —通常是坐火车。"}', 92, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5501, 158, '{"english": "How does the girl''s father go to work?", "chinese": "这个女孩的父亲怎么去上班？"}', 93, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5502, 158, '{"english": "3. -Hey, Amy. School is over. How do you go home?", "chinese": "3. —嘿，艾米。放学了。你怎么回家？"}', 94, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5503, 158, '{"english": "-I usually go on foot. And you?", "chinese": "—我通常步行回家。你呢？"}', 95, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5504, 158, '{"english": "By bus?  -No, I go on foot, too.", "chinese": "乘公共汽车吗？ —不，我也步行回家。"}', 96, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5505, 158, '{"english": "How does Amy go home?", "chinese": "艾米怎么回家？"}', 97, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5506, 158, '{"english": "4. -Don''t cross the street now.  -Why?", "chinese": "4. —现在不要过马路。 —为什么？"}', 98, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5507, 158, '{"english": "There are no cars coming.  -It''s a red light.", "chinese": "没有车来。 —现在是红灯。"}', 99, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5508, 158, '{"english": "Cars are very fast. It''s dangerous.  -OK.   What will the woman do?", "chinese": "汽车速度很快。这很危险。 —好吧。  这个女人将要做什么？"}', 100, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5509, 158, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 101, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5510, 158, '{"english": "Come or go? Where is Mike? Tick or cross.", "chinese": "来还是走？迈克在哪里？听音判断对错。"}', 102, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5511, 158, '{"english": "Go to the cinema.", "chinese": "去看电影。"}', 103, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5512, 158, '{"english": "At the cinema.", "chinese": "在电影院。"}', 104, '2026-02-05 04:02:00', '2026-02-05 04:02:00');
INSERT INTO "course_content" VALUES (5513, 158, '{"english": "Not at the cinema.", "chinese": "不在电影院。"}', 105, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5514, 158, '{"english": "Come to the park and play with us.", "chinese": "来公园和我们一起玩。"}', 106, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5515, 158, '{"english": "In the park.", "chinese": "在公园里。"}', 107, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5516, 158, '{"english": "Not in the park.", "chinese": "不在公园里。"}', 108, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5517, 158, '{"english": "How does Mrs Zhao come to school?", "chinese": "赵老师是怎么来学校的？"}', 109, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5518, 158, '{"english": "At school.", "chinese": "在学校。"}', 110, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5519, 158, '{"english": "Not at school.", "chinese": "不是在学校。"}', 111, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5520, 158, '{"english": "How can I go to the museum?", "chinese": "我怎么去博物馆？"}', 112, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5521, 158, '{"english": "At the museum.", "chinese": "在博物馆。"}', 113, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5522, 158, '{"english": "Not at the museum.", "chinese": "不在博物馆。"}', 114, '2026-02-05 04:02:01', '2026-02-05 04:02:01');
INSERT INTO "course_content" VALUES (5523, 159, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5524, 159, '{"english": "It''s Saturday morning.", "chinese": "今天是星期六早上。"}', 2, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5525, 159, '{"english": "Sarah is on the phone with Mike. Listen and circle.", "chinese": "萨拉正在和迈克通电话。听录音，圈一圈。"}', 3, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5526, 159, '{"english": "-Hi, Sarah.  -Good morning, Mike. Today is so warm.", "chinese": "—嗨，萨拉。 —早上好，迈克。今天真暖和。"}', 4, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5527, 159, '{"english": "Let''s go swimming.  -Sorry, I can''t. I have to do my homework now.", "chinese": "我们去游泳吧。 —对不起，我不能去游泳。我现在得做作业。"}', 5, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5528, 159, '{"english": "-OK. What about this afternoon?  -No, I can''t. I''m going fishing.", "chinese": "—好吧。今天下午怎么样？ —不，我不能去游泳。我要去钓鱼。"}', 6, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5529, 159, '{"english": "1. Can Mike go swimming today?", "chinese": "1. 迈克今天能去游泳吗？"}', 7, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5530, 159, '{"english": "2. Why or why not?", "chinese": "2. 为什么？"}', 8, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5531, 159, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 9, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5532, 159, '{"english": "What are you going to do tomorrow?", "chinese": "你明天打算干什么呀？"}', 10, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5533, 159, '{"english": "I''m going to have an art lesson.", "chinese": "我要上艺术课。"}', 11, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5534, 159, '{"english": "What are you going to do in your lesson?", "chinese": "你们课上打算做什么？"}', 12, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5535, 159, '{"english": "We''re going to draw some pictures in Renmin Park.", "chinese": "我们打算去人民公园画画。"}', 13, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5536, 159, '{"english": "Sounds great! I''m going to see a film tomorrow.", "chinese": "听起来不错！我明天要去看电影。"}', 14, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5537, 159, '{"english": "Have a good time!", "chinese": "玩得愉快！"}', 15, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5538, 159, '{"english": "You too. I have to do my homework now. Bye.", "chinese": "你也是。我现在必须做作业了。再见。"}', 16, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5539, 159, '{"english": "OK. Bye.", "chinese": "好的。再见。"}', 17, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5540, 159, '{"english": "What are Mike and Sarah going to do tomorrow?", "chinese": "迈克和萨拉明天打算做什么?"}', 18, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5541, 159, '{"english": "Talk about your plan and your friends'' plans for the weekend.", "chinese": "谈谈你和你朋友的周末计划。"}', 19, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5542, 159, '{"english": "What is ... going to do?", "chinese": "⋯⋯打算干什么？"}', 20, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5543, 159, '{"english": "What are ... going to do?", "chinese": "⋯⋯打算干什么？"}', 21, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5544, 159, '{"english": "He/She is going to ...", "chinese": "他/她将⋯⋯"}', 22, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5545, 159, '{"english": "They are going to ...", "chinese": "他们将要⋯⋯"}', 23, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5546, 159, '{"english": "go ice-skating", "chinese": "去溜冰"}', 24, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5547, 159, '{"english": "wash clothes", "chinese": "洗衣服"}', 25, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5548, 159, '{"english": "draw pictures", "chinese": "画画"}', 26, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5549, 159, '{"english": "make a snowman", "chinese": "堆雪人"}', 27, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5550, 159, '{"english": "go for a picnic", "chinese": "去野餐"}', 28, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5551, 159, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 29, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5552, 159, '{"english": "What are you going to do today?", "chinese": "你今天打算做什么？"}', 30, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5553, 159, '{"english": "I''m going to see a film.", "chinese": "我要去看电影。"}', 31, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5554, 159, '{"english": "visit my grandparents", "chinese": "去看望我的祖父母"}', 32, '2026-02-05 04:02:03', '2026-02-05 04:02:03');
INSERT INTO "course_content" VALUES (5555, 159, '{"english": "see a film", "chinese": "看电影"}', 33, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5556, 159, '{"english": "take a trip", "chinese": "去旅行"}', 34, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5557, 159, '{"english": "go to the supermarket", "chinese": "去超市"}', 35, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5558, 159, '{"english": "this morning", "chinese": "今天早上"}', 36, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5559, 159, '{"english": "this afternoon", "chinese": "今天下午"}', 37, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5560, 159, '{"english": "this evening", "chinese": "今天傍晚"}', 38, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5561, 159, '{"english": "tonight", "chinese": "今晚"}', 39, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5562, 159, '{"english": "tomorrow", "chinese": "明天"}', 40, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5563, 159, '{"english": "next week", "chinese": "下个星期"}', 41, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5564, 159, '{"english": "Make a plan", "chinese": "制定计划"}', 42, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5565, 159, '{"english": "It is Saturday morning now.", "chinese": "现在是星期六早上。"}', 43, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5566, 159, '{"english": "Make a plan and share it with your partner.", "chinese": "制定一个计划并与你的搭档分享。"}', 44, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5567, 159, '{"english": "When?", "chinese": "什么时候？"}', 45, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5568, 159, '{"english": "What are you going to do?", "chinese": "你打算去做什么？"}', 46, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5569, 159, '{"english": "this morning", "chinese": "今天早上"}', 47, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5570, 159, '{"english": "this afternoon", "chinese": "今天下午"}', 48, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5571, 159, '{"english": "this evening", "chinese": "今天傍晚"}', 49, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5572, 159, '{"english": "tonight", "chinese": "今晚"}', 50, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5573, 159, '{"english": "tomorrow", "chinese": "明天"}', 51, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5574, 159, '{"english": "What are you going to do this morning?", "chinese": "今天早上你打算做什么？"}', 52, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5575, 159, '{"english": "I''m going to visit my grandparents.", "chinese": "我要去看望我的祖父母。"}', 53, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5576, 159, '{"english": "My aunt is going to make mooncakes.", "chinese": "我姑姑将要做月饼。"}', 54, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5577, 159, '{"english": "My grandma will tell us a story about Chang''e.", "chinese": "我奶奶将会给我们讲嫦娥的故事。"}', 55, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5578, 159, '{"english": "Robin and I are going to read a poem. This is our poem:", "chinese": "罗宾和我要读一首诗。这是我们的诗："}', 56, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5579, 159, '{"english": "F is for family. We will all be together tonight.", "chinese": "F 代表家庭。今晚我们都会聚在一起。"}', 57, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5580, 159, '{"english": "A is for autumn. It is the autumn season.", "chinese": "A 代表秋天。这是秋天的季节。"}', 58, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5581, 159, '{"english": "M is for moon.", "chinese": "M 代表月亮。"}', 59, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5582, 159, '{"english": "We eat mooncakes and tell stories about the moon.", "chinese": "我们吃月饼，讲有关月亮的故事。"}', 60, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5583, 159, '{"english": "I is for ''I''. I am so happy today.", "chinese": "I 代表“我”。我今天很高兴。"}', 61, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5584, 159, '{"english": "L is for love. We love Mid-Autumn Festival.", "chinese": "L 代表爱。我们喜欢中秋节。"}', 62, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5585, 159, '{"english": "Y is for you.", "chinese": "Y 代表你。"}', 63, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5586, 159, '{"english": "You can be together with your family too!", "chinese": "你也可以和你的家人在一起！"}', 64, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5587, 159, '{"english": "Read the text and fill in the table.", "chinese": "读课文并填表。"}', 65, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5588, 159, '{"english": "Who", "chinese": "谁"}', 66, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5589, 159, '{"english": "Be going to / Will", "chinese": "将要"}', 67, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5590, 159, '{"english": "Wu Binbin''s family", "chinese": "吴斌斌的家庭"}', 68, '2026-02-05 04:02:04', '2026-02-05 04:02:04');
INSERT INTO "course_content" VALUES (5591, 159, '{"english": "His family will get together.", "chinese": "他的家人们会聚在一起。"}', 69, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5592, 159, '{"english": "Wu Binbin''s aunt", "chinese": "吴斌斌的阿姨"}', 70, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5593, 159, '{"english": "Wu Binbin''s grandma", "chinese": "吴斌斌的奶奶"}', 71, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5594, 159, '{"english": "Wu Binbin and Robin", "chinese": "吴斌斌和罗宾"}', 72, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5595, 159, '{"english": "Discuss with your partner. What are you going to do for Mid-Autumn Festival?", "chinese": "与你的搭档讨论。中秋节你们打算做什么？"}', 73, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5596, 159, '{"english": "Write down your plan here.", "chinese": "在这里写下你们的计划。"}', 74, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5597, 159, '{"english": "For Mid-Autumn Festival, I''m going to ______.", "chinese": "为了中秋节，我将要______。"}', 75, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5598, 159, '{"english": "My partner is going to ______.", "chinese": "我的搭档将要______。"}', 76, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5599, 159, '{"english": "Tips for pronunciation", "chinese": "发音小贴士"}', 77, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5600, 159, '{"english": "Listen, clap and repeat.", "chinese": "听一听，拍一拍，读一读。"}', 78, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5601, 159, '{"english": "lesson", "chinese": "课"}', 79, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5602, 159, '{"english": "dinner", "chinese": "晚餐"}', 80, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5603, 159, '{"english": "tonight", "chinese": "今晚"}', 81, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5604, 159, '{"english": "tomorrow", "chinese": "明天"}', 82, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5605, 159, '{"english": "Look at the text on page 28.", "chinese": "请看第 28 页的课文。"}', 83, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5606, 159, '{"english": "Find and say more words like these.", "chinese": "找到并说出更多这样的词。"}', 84, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5607, 159, '{"english": "Let''s check", "chinese": "让我们检查一下"}', 85, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5608, 159, '{"english": "Listen and tick.", "chinese": "听录音，并打勾。"}', 86, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5609, 159, '{"english": "1. -Hi, John. What are you going to do tomorrow?", "chinese": "1. —嗨，约翰。你明天打算做什么？"}', 87, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5610, 159, '{"english": "-Not much. I''m just going to do my homework and buy a postcard tomorrow morning.", "chinese": "—不多。我明天早上要做作业然后买张明信片。"}', 88, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5611, 159, '{"english": "And you?  -I''m going to see a film tomorrow afternoon.", "chinese": "你呢？ —明天下午我要去看电影。"}', 89, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5612, 159, '{"english": "-Great! Can I go, too?", "chinese": "—太好了！我也能去吗？"}', 90, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5613, 159, '{"english": "Question: What is John going to do tomorrow morning?", "chinese": "问题：约翰明天早上要做什么？"}', 91, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5614, 159, '{"english": "2. -Amy, did you see my new comic book?", "chinese": "2. —艾米，你看到我的新漫画书了吗？"}', 92, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5615, 159, '{"english": "I''m going to read it this evening.  -Oh!", "chinese": "我今晚要读它。 —哦！"}', 93, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5616, 159, '{"english": "It looks good! Can I read it after you?", "chinese": "看起来不错！我能跟你一起读吗？"}', 94, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5617, 159, '{"english": "-Yes. I can give it to you tomorrow.  -OK. Thanks.", "chinese": "—可以。我可以明天给你。 —好啊。谢谢。"}', 95, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5618, 159, '{"english": "Question: What is the boy going to do this evening?", "chinese": "问题：这个男孩今晚要做什么？"}', 96, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5619, 159, '{"english": "3. -I''m going to the bookstore to buy a new dictionary.", "chinese": "3.—我打算去书店买一本新的字典。"}', 97, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5620, 159, '{"english": "-Oh! When are you going?  -This afternoon.", "chinese": "—哦！你什么时候去？ —今天下午。"}', 98, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5621, 159, '{"english": "The bookstore isn''t open this evening.  Question: Where is the boy going?", "chinese": "书店今天傍晚不营业。 问题：那男孩要去哪里？"}', 99, '2026-02-05 04:02:05', '2026-02-05 04:02:05');
INSERT INTO "course_content" VALUES (5622, 159, '{"english": "4. -I''m going to buy some milk and a newspaper.", "chinese": "4. —我打算买些牛奶和报纸。"}', 100, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5623, 159, '{"english": "-Where are you going to buy them?", "chinese": "—你打算在哪里买？"}', 101, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5624, 159, '{"english": "-I''m going to buy them at the small shop near the post office.", "chinese": "—我打算在邮局附近的小店买。"}', 102, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5625, 159, '{"english": "-Really? I''m going to buy a postcard there.", "chinese": "—真的吗？我打算在那里买张明信片。"}', 103, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5626, 159, '{"english": "Can I go with you?  -Sure! Let''s go together!", "chinese": "我能和你一起去吗？ —当然！我们一起去吧！"}', 104, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5627, 159, '{"english": "Question: What is the woman going to buy?", "chinese": "问题：这个女人要买什么？"}', 105, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5628, 159, '{"english": "Listen again and fill in the blanks.", "chinese": "再听一遍，并填空。"}', 106, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5629, 159, '{"english": "1. -Hi, John. What are you going to do tomorrow?", "chinese": "1. —嗨，约翰。你明天打算做什么？"}', 107, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5630, 159, '{"english": "-Not much. I''m just going to do my homework and buy a postcard tomorrow morning.", "chinese": "—不多。我明天早上要做作业然后买张明信片。"}', 108, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5631, 159, '{"english": "And you?  -I''m going to see a film tomrrow afternoon.", "chinese": "你呢？ —明天下午我要去看电影。"}', 109, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5632, 159, '{"english": "-Great! Can I go, too?", "chinese": "—太好了！我也能去吗？"}', 110, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5633, 159, '{"english": "2. -Amy, did you see my new comic book?", "chinese": "2. —艾米，你看到我的新漫画书了吗？"}', 111, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5634, 159, '{"english": "I''m going to read it this evening.  -Oh!", "chinese": "我今晚要读它。 —哦！"}', 112, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5635, 159, '{"english": "It looks good! Can I read it after you?", "chinese": "看起来不错！我能跟你一起读吗？"}', 113, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5636, 159, '{"english": "-Yes. I can give it to you tomorrow. -OK.Thanks.", "chinese": "—可以。我可以明天给你。—好啊。谢谢。"}', 114, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5637, 159, '{"english": "3. -I''m going to the bookstore to buy a new dictionary.", "chinese": "3.—我打算去书店买一本新的字典。"}', 115, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5638, 159, '{"english": "-Oh! When are you going?", "chinese": "—哦！你什么时候去？"}', 116, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5639, 159, '{"english": "-This afternoon. The bookstore isn''t open this evening.", "chinese": "—今天下午。书店今天傍晚不营业。"}', 117, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5640, 159, '{"english": "4. -I''m going to buy some milk and a newspaper.", "chinese": "4. —我打算买些牛奶和报纸。"}', 118, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5641, 159, '{"english": "-Where are you going to buy them?", "chinese": "—你打算在哪里买？"}', 119, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5642, 159, '{"english": "-I''m going to buy them at the small shop near the post office.", "chinese": "—我打算在邮局附近的小店买。"}', 120, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5643, 159, '{"english": "-Really? I''m going to buy a postcard there.", "chinese": "—真的吗？我打算在那里买张明信片。"}', 121, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5644, 159, '{"english": "Can I go with you?  -Sure! Let''s go together!", "chinese": "我能和你一起去吗？ —当然！我们一起去吧！"}', 122, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5645, 159, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 123, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5646, 159, '{"english": "How many sentences can you make?", "chinese": "你能造出几个句子？"}', 124, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5647, 159, '{"english": "going to/going", "chinese": "去"}', 125, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5648, 159, '{"english": "do", "chinese": "助动词"}', 126, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5649, 159, '{"english": "What, Where, When", "chinese": "什么，什么地方，什么时候"}', 127, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5650, 159, '{"english": "am, is, are", "chinese": "是"}', 128, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5651, 159, '{"english": "I, you  we, they  he/she", "chinese": "我，你 我们，他们 他/她"}', 129, '2026-02-05 04:02:06', '2026-02-05 04:02:06');
INSERT INTO "course_content" VALUES (5652, 160, '{"english": "Recycle 1", "chinese": "复习 1"}', 1, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5653, 160, '{"english": "Visiting Grandma and Grandpa", "chinese": "看望奶奶和爷爷"}', 2, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5654, 160, '{"english": "Wu Binbin is going to visit his grandparents.", "chinese": "吴斌斌打算去看望他的祖父母。"}', 3, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5655, 160, '{"english": "Listen and circle.", "chinese": "听一听，圈一圈。"}', 4, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5656, 160, '{"english": "-Robin, how do we get to my grandparents'' new house from here?", "chinese": "—罗宾，我们怎么从这里到我祖父母的新家？"}', 5, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5657, 160, '{"english": "Can you use your BDS?  -Sure. First go straight. Then turn left.", "chinese": "你能用你的 BDS 吗？—当然可以。先直走。然后左转。"}', 6, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5658, 160, '{"english": "At the traffic lights, turn left and walk one hundred metres.", "chinese": "在红绿灯处向左转后走一百米。"}', 7, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5659, 160, '{"english": "Then, finally, we can see the house.  -Good. What time are we leaving?", "chinese": "然后，我们终于可以看到房子了。 —好的。我们什么时候出发？"}', 8, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5660, 160, '{"english": "-Nine o''clock.", "chinese": "—九点钟。"}', 9, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5661, 160, '{"english": "Look at these pictures and fill in the blanks.", "chinese": "看这些图片并填空。"}', 10, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5662, 160, '{"english": "Listen again and answer.", "chinese": "再听一遍，并回答问题。"}', 11, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5663, 160, '{"english": "1. Are they going by bus or on foot?", "chinese": "1. 他们是坐公共汽车去还是步行去？"}', 12, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5664, 160, '{"english": "2. When are they going?", "chinese": "2. 他们什么时候去？"}', 13, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5665, 160, '{"english": "Binbin and Robin see a little boy crying on the street.", "chinese": "斌斌和罗宾看到一个小男孩在街上哭。"}', 14, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5666, 160, '{"english": "Look at the pictures and guess what they are saying.", "chinese": "看看照片并猜猜他们在说什么。"}', 15, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5667, 160, '{"english": "These may help you:", "chinese": "这些可以帮助您："}', 16, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5668, 160, '{"english": "Stop! Don''t go at ...!", "chinese": "停！不要去⋯⋯！"}', 17, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5669, 160, '{"english": "Let''s go to ...", "chinese": "让我们去⋯⋯"}', 18, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5670, 160, '{"english": "Go ... Turn ...", "chinese": "去⋯⋯转⋯⋯"}', 19, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5671, 160, '{"english": "Now listen and tick or cross.", "chinese": "听录音，并打勾或叉。"}', 20, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5672, 160, '{"english": "1. -Hey! Stop! Don''t cross at a red light.", "chinese": "1.—嘿！停！红灯时不要过马路。"}', 21, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5673, 160, '{"english": "-Sorry.  -You must be more careful.  -OK.", "chinese": "—我很抱歉。 —你必须更加小心。 —好的。"}', 22, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5674, 160, '{"english": "I can''t find my mum.  -Oh, let me help you!", "chinese": "我找不到我妈妈了。 —哦，让我来帮你吧！"}', 23, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5675, 160, '{"english": "2. -Are you hungry?  -Yes, I am.", "chinese": "2.—你饿了吗？ —是的，我饿了。"}', 24, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5676, 160, '{"english": "-There is a restaurant over there.", "chinese": "—那边有一家餐馆。"}', 25, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5677, 160, '{"english": "Let''s go and buy some food.  -Good idea.", "chinese": "我们去买些食物吧。 —好主意。"}', 26, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5678, 160, '{"english": "3. -Thank you for the food. I feel better now.", "chinese": "3.—谢谢你的食物。我现在感觉好多了。"}', 27, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5679, 160, '{"english": "-Let''s go to the police station. They can help you.", "chinese": "—我们去警察局吧。他们可以帮助你。"}', 28, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5680, 160, '{"english": "-Where is it?  -We go straight and then turn right at the crossing.", "chinese": "—它在哪里？ —我们直走然后在十字路口右转。"}', 29, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5681, 160, '{"english": "After that, we''ll go straight again.", "chinese": "之后，我们再直走。"}', 30, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5682, 160, '{"english": "The police station is next to the supermarket.", "chinese": "警察局就在超市旁边。"}', 31, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5683, 160, '{"english": "The little boy is waiting for his mother.", "chinese": "这个小男孩在等他的妈妈。"}', 32, '2026-02-05 04:02:08', '2026-02-05 04:02:08');
INSERT INTO "course_content" VALUES (5684, 160, '{"english": "Robin is singing a song to him.", "chinese": "罗宾正在给他唱一首歌。"}', 33, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5685, 160, '{"english": "Listen and read the song aloud.", "chinese": "听一听并大声朗读这首歌。"}', 34, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5686, 160, '{"english": "Hush, little boy, don''t say a word.", "chinese": "安静，小男孩，一句话也别说。"}', 35, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5687, 160, '{"english": "Papa''s going to buy you a little bird.", "chinese": "爸爸打算给你买只小鸟。"}', 36, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5688, 160, '{"english": "And if that bird doesn''t sing,  Papa''s going to buy you a big, big ring.", "chinese": "如果那只鸟不唱歌， 爸爸打算给你买一个大大的戒指。"}', 37, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5689, 160, '{"english": "And if that ring is lost in class,", "chinese": "如果戒指在教室里丢了，"}', 38, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5690, 160, '{"english": "Papa''s going to buy you a looking glass.", "chinese": "爸爸打算给你买个镜子。"}', 39, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5691, 160, '{"english": "And if that looking glass falls down,", "chinese": "如果镜子掉下来，"}', 40, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5692, 160, '{"english": "Well, you''ll still be the sweetest boy in town.", "chinese": "你还是镇里最可爱的男孩。"}', 41, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5693, 160, '{"english": "In the song, what is Papa going to do?", "chinese": "在这首歌里，爸爸要做什么？"}', 42, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5694, 160, '{"english": "Read and circle.", "chinese": "阅读并圈出答案。"}', 43, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5695, 160, '{"english": "1. Who is the song for?", "chinese": "1. 这首歌是给谁的？"}', 44, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5696, 160, '{"english": "A. For a sad kid.  B. For a happy kid.", "chinese": "A. 给一个悲伤的小孩。 B. 给一个开心的小孩。"}', 45, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5697, 160, '{"english": "2. What is the meaning of ''hush''?", "chinese": "2. “安静”是什么意思？"}', 46, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5698, 160, '{"english": "A. Be nice.  B. Be quiet.", "chinese": "A. 很棒。 B. 安静。"}', 47, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5699, 160, '{"english": "The little boy''s mother is on the phone.", "chinese": "这个小男孩的妈妈在打电话。"}', 48, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5700, 160, '{"english": "Look at the map and fill in the blanks.", "chinese": "看地图并填空。"}', 49, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5701, 160, '{"english": "Ma''am, your son is here.", "chinese": "夫人，你的儿子在我们这里。"}', 50, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5702, 160, '{"english": "Come to the police station, please.", "chinese": "请到警察局来。"}', 51, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5703, 160, '{"english": "Thank you. Thank you! How can I ______?", "chinese": "谢谢您。谢谢您！我该怎么______？"}', 52, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5704, 160, '{"english": "Where are you now?", "chinese": "你现在在哪里？"}', 53, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5705, 160, '{"english": "I''m in front of the ______.", "chinese": "我在______前面。"}', 54, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5706, 160, '{"english": "Is it far? Should I go by bus?", "chinese": "远吗？我应该坐公共汽车去吗？"}', 55, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5707, 160, '{"english": "No, you can come on foot.", "chinese": "不用，你可以步行来。"}', 56, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5708, 160, '{"english": "______ ______ at the hospital. Then ______ ______.", "chinese": "在医院______ ______。然后______ ______。"}', 57, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5709, 160, '{"english": "The police station is ______ ______ the supermarket.", "chinese": "警察局在超市的______。"}', 58, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5710, 160, '{"english": "Read, answer and do.", "chinese": "阅读，回答并做一做。"}', 59, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5711, 160, '{"english": "1. How can the boy''s mother go to the police station?", "chinese": "1. 孩子的母亲怎么去警察局？"}', 60, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5712, 160, '{"english": "2. Circle the words for transportation(交通方式).", "chinese": "2. 圈出关于交通方式的单词。"}', 61, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5713, 160, '{"english": "What other kinds do you know? Write them down.", "chinese": "还有其他你知道的交通方式吗？写下它们。"}', 62, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5714, 160, '{"english": "Listen and read aloud.", "chinese": "听录音，并大声朗读。"}', 63, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5715, 160, '{"english": "Are you Mrs Zhang?", "chinese": "你是张夫人吗？"}', 64, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5716, 160, '{"english": "Yes, I am.", "chinese": "是的，我是张夫人。"}', 65, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5717, 160, '{"english": "Thank you so much!", "chinese": "非常感谢！"}', 66, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5718, 160, '{"english": "Unit Four", "chinese": "第四单元"}', 67, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5719, 160, '{"english": "Tea''s ready!", "chinese": "茶点准备好了！"}', 68, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5720, 160, '{"english": "You like tea a lot!", "chinese": "你非常喜欢喝茶啊！"}', 69, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5721, 160, '{"english": "Yes. What do you like?", "chinese": "对。你喜欢什么？"}', 70, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5722, 160, '{"english": "Cake, for sure!", "chinese": "当然是蛋糕了！"}', 71, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5723, 160, '{"english": "Sorry, I don''t have any cake.", "chinese": "对不起，我没有蛋糕。"}', 72, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5724, 160, '{"english": "I have a pen pal", "chinese": "我有一个笔友"}', 73, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5725, 160, '{"english": "Oliver, this is my pen pal Peter.", "chinese": "奥利弗，这是我的笔友彼得。"}', 74, '2026-02-05 04:02:09', '2026-02-05 04:02:09');
INSERT INTO "course_content" VALUES (5726, 160, '{"english": "He''s from New Zealand.", "chinese": "他来自新西兰。"}', 75, '2026-02-05 04:02:10', '2026-02-05 04:02:10');
INSERT INTO "course_content" VALUES (5727, 160, '{"english": "What are his hobbies?", "chinese": "他的爱好是什么？"}', 76, '2026-02-05 04:02:10', '2026-02-05 04:02:10');
INSERT INTO "course_content" VALUES (5728, 160, '{"english": "He likes doing kung fu and swimming.", "chinese": "他喜欢练功夫和游泳。"}', 77, '2026-02-05 04:02:10', '2026-02-05 04:02:10');
INSERT INTO "course_content" VALUES (5729, 160, '{"english": "Does he live on the South Island?", "chinese": "他住在南岛吗？"}', 78, '2026-02-05 04:02:10', '2026-02-05 04:02:10');
INSERT INTO "course_content" VALUES (5730, 160, '{"english": "Yes, he does. He lives on a farm. Look!", "chinese": "是的。他住在农场里。看！"}', 79, '2026-02-05 04:02:10', '2026-02-05 04:02:10');
INSERT INTO "course_content" VALUES (5731, 161, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:11', '2026-02-05 04:02:11');
INSERT INTO "course_content" VALUES (5732, 161, '{"english": "Zhang Peng is talking with Oliver about his pen pal.", "chinese": "张鹏正在和奥利弗谈论他的笔友。"}', 2, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5733, 161, '{"english": "Listen and then write T (true) or F (false).", "chinese": "听录音，判断对（T）错（F）。"}', 3, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5734, 161, '{"english": "-Look! I have a new pen pal.", "chinese": "—看！我有一个新笔友。"}', 4, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5735, 161, '{"english": "He''s from New Zealand.  -That''s good. What''s his name?", "chinese": "他来自新西兰。 —那很好。他叫什么名字？"}', 5, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5736, 161, '{"english": "-His name is Peter. He likes playing basketball.", "chinese": "—他叫彼得。他喜欢打篮球。"}', 6, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5737, 161, '{"english": "-Oh! Is he very tall?  -Yes, he is.", "chinese": "—哦！他很高吗？ —是的，他很高。"}', 7, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5738, 161, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 8, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5739, 161, '{"english": "What are Peter''s hobbies?", "chinese": "彼得的爱好是什么？"}', 9, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5740, 161, '{"english": "He likes reading stories.", "chinese": "他喜欢读故事。"}', 10, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5741, 161, '{"english": "He lives on a farm, so sometimes he reads to the cows!", "chinese": "他住在农场，所以有时他会读给奶牛听！"}', 11, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5742, 161, '{"english": "That''s interesting.", "chinese": "那很有趣呀。"}', 12, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5743, 161, '{"english": "He likes doing kung fu and swimming.", "chinese": "他喜欢练功夫和游泳。"}', 13, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5744, 161, '{"english": "Really? Me too!", "chinese": "真的吗？我也是！"}', 14, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5745, 161, '{"english": "He also likes singing.", "chinese": "他也喜欢唱歌。"}', 15, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5746, 161, '{"english": "Oh, you like singing, too.", "chinese": "哦，你也喜欢唱歌。"}', 16, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5747, 161, '{"english": "Yes. I''m going to teach him the Chinese song ''Jasmine Flower''!", "chinese": "是的。我打算教他唱中文歌曲“茉莉花”！"}', 17, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5748, 161, '{"english": "Good idea!", "chinese": "好主意！"}', 18, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5749, 161, '{"english": "What are Peter''s hobbies?", "chinese": "彼得的爱好是什么？"}', 19, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5750, 161, '{"english": "Who is your best friend?", "chinese": "谁是你最好的朋友？"}', 20, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5751, 161, '{"english": "Talk about his or her hobbies.", "chinese": "谈谈他或她的爱好。"}', 21, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5752, 161, '{"english": "My best friend is Xu Wei.", "chinese": "我最好的朋友是徐伟。"}', 22, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5753, 161, '{"english": "What are his hobbies?", "chinese": "他的爱好是什么？"}', 23, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5754, 161, '{"english": "He likes flying kites and singing English songs.", "chinese": "他喜欢放风筝和唱英文歌。"}', 24, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5755, 161, '{"english": "playing sports", "chinese": "运动"}', 25, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5756, 161, '{"english": "watching TV", "chinese": "看电视"}', 26, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5757, 161, '{"english": "climbing mountains", "chinese": "爬山"}', 27, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5758, 161, '{"english": "playing the pipa", "chinese": "弹奏琵琶"}', 28, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5759, 161, '{"english": "listening to music", "chinese": "听音乐"}', 29, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5760, 161, '{"english": "drawing cartoons", "chinese": "画漫画"}', 30, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5761, 161, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 31, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5762, 161, '{"english": "Hey, Zhang Peng, what are your hobbies?", "chinese": "你好，张鹏，你的爱好是什么？"}', 32, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5763, 161, '{"english": "I like reading stories.", "chinese": "我喜欢读故事。"}', 33, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5764, 161, '{"english": "I also like singing and doing kung fu.", "chinese": "我也喜欢唱歌和练功夫。"}', 34, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5765, 161, '{"english": "dancing", "chinese": "跳舞"}', 35, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5766, 161, '{"english": "singing", "chinese": "歌唱"}', 36, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5767, 161, '{"english": "reading stories", "chinese": "读故事"}', 37, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5768, 161, '{"english": "playing football", "chinese": "踢足球"}', 38, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5769, 161, '{"english": "doing kung fu", "chinese": "练功夫"}', 39, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5770, 161, '{"english": "Do a survey", "chinese": "做个调查"}', 40, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5771, 161, '{"english": "Interview your classmates and then give a report.", "chinese": "采访你的同学，然后做报告。"}', 41, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5772, 161, '{"english": "dancing", "chinese": "跳舞"}', 42, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5773, 161, '{"english": "singing", "chinese": "歌唱"}', 43, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5774, 161, '{"english": "reading stories", "chinese": "读故事"}', 44, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5775, 161, '{"english": "playing football", "chinese": "踢足球"}', 45, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5776, 161, '{"english": "doing kung fu", "chinese": "练功夫"}', 46, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5777, 161, '{"english": "Sue", "chinese": "苏"}', 47, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5778, 161, '{"english": "Martin", "chinese": "马丁"}', 48, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5779, 161, '{"english": "What are your hobbies?", "chinese": "你的爱好是什么？"}', 49, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5780, 161, '{"english": "I like singing and dancing.", "chinese": "我喜欢唱歌和跳舞。"}', 50, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5781, 161, '{"english": "Two students like dancing. One student likes singing.", "chinese": "两个学生喜欢跳舞。一个学生喜欢唱歌。"}', 51, '2026-02-05 04:02:12', '2026-02-05 04:02:12');
INSERT INTO "course_content" VALUES (5782, 161, '{"english": "Your partner''s hobbies", "chinese": "你搭档的爱好"}', 52, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5783, 161, '{"english": "NOTICE BOARD", "chinese": "公告板"}', 53, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5784, 161, '{"english": "Shall we dance?  There is a dancing class on Sunday at 1 p.m.", "chinese": "我们跳舞好吗？ 星期日下午 1 点有一节舞蹈课。"}', 54, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5785, 161, '{"english": "I like dancing, and I need a partner.", "chinese": "我喜欢跳舞，然后我需要一个舞伴。"}', 55, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5786, 161, '{"english": "Call Amy: 134xxxxxxxx", "chinese": "打电话给艾米：134xxxxxxxx"}', 56, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5787, 161, '{"english": "Goal! Goal! Goal!  What do you do on Sundays?", "chinese": "目标！目标！目标！ 星期天你干什么？"}', 57, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5788, 161, '{"english": "Join our football club! See you on the playground!  john@pep.com.cn", "chinese": "加入我们的足球俱乐部吧！操场见！ john@pep.com.cn"}', 58, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5789, 161, '{"english": "Let''s read together!", "chinese": "让我们一起读书！"}', 59, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5790, 161, '{"english": "What is your hobby? Do you like reading?", "chinese": "你的爱好是什么？你喜欢读书吗？"}', 60, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5791, 161, '{"english": "I have great books. We can share!", "chinese": "我有很棒的书。我们可以分享！"}', 61, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5792, 161, '{"english": "Call Mike: 136-210-0639", "chinese": "打电话给迈克：1362100639"}', 62, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5793, 161, '{"english": "Science Club, YOUR club!  Do you want to learn about robots?", "chinese": "科学俱乐部，你的俱乐部！ 你想学习机器人吗？"}', 63, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5794, 161, '{"english": "Come to the science room! Meet Robin.", "chinese": "到科学教室来！见罗宾。"}', 64, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5795, 161, '{"english": "He teaches students to make robots. robin@pep.com.cn", "chinese": "他教学生制造机器人。 robin@pep.com.cn"}', 65, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5796, 161, '{"english": "Read, answer and write.", "chinese": "读一读，答一答，写一写。"}', 66, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5797, 161, '{"english": "1. Do the four people in the text want pen pals?", "chinese": "1. 课文中的四个人想要笔友吗？"}', 67, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5798, 161, '{"english": "2. How many hobbies can you find in the text?", "chinese": "2. 你能在课文中能找到多少爱好？"}', 68, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5799, 161, '{"english": "Write them down.", "chinese": "把它们写下来。"}', 69, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5800, 161, '{"english": "Finish this ad for a cooking club.", "chinese": "完成这个烹饪俱乐部的广告。"}', 70, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5801, 161, '{"english": "Let''s cook!", "chinese": "我们做饭吧！"}', 71, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5802, 161, '{"english": "Do you like food? Do you want to cook?", "chinese": "你喜欢食物吗？你想做饭吗？"}', 72, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5803, 161, '{"english": "Join us!  Different people in our club teach different things.", "chinese": "加入我们！ 不同的人在我们的俱乐部教不同的东西。"}', 73, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5804, 161, '{"english": "Mandy ______ (talk/talks) about chocolates.", "chinese": "曼迪谈论巧克力。"}', 74, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5805, 161, '{"english": "Wang Tong ______ (cook/cooks) rice and noodles.", "chinese": "王彤做米饭和面条。"}', 75, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5806, 161, '{"english": "Cao Jia ______ (make/makes) salad.  Who ______ (do/does)the dishes?", "chinese": "曹佳做沙拉。 谁洗碗？"}', 76, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5807, 161, '{"english": "Don''t worry. We all do them together.", "chinese": "别担心。我们一起洗碗。"}', 77, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5808, 161, '{"english": "We meet every Wednesday afternoon at 4 o''clock in the dining hall. See you there!", "chinese": "我们每周三下午 4 点在餐厅见面。那里见！"}', 78, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5809, 161, '{"english": "Tips for pronunciation", "chinese": "发音小贴士"}', 79, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5810, 161, '{"english": "Listen and repeat.", "chinese": "听录音，并跟读。"}', 80, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5811, 161, '{"english": "1. We can share.", "chinese": "1. 我们可以分享。"}', 81, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5812, 161, '{"english": "2. I like dancing.", "chinese": "2. 我喜欢跳舞。"}', 82, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5813, 161, '{"english": "3. He lives on a farm.", "chinese": "3. 他住在农场里。"}', 83, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5814, 161, '{"english": "4. What are Peter''s hobbies?", "chinese": "4. 彼得的爱好是什么？"}', 84, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5815, 161, '{"english": "Let''s check", "chinese": "让我们来测一测"}', 85, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5816, 161, '{"english": "Listen and tick.", "chinese": "听录音，并打勾。"}', 86, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5817, 161, '{"english": "1. -Who is that?  -That''s Andy.", "chinese": "1. —那是谁？ —那是安迪。"}', 87, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5818, 161, '{"english": "-Does he like playing basketball?  -No, he likes playing football.", "chinese": "—他喜欢打篮球吗？ —不，他喜欢踢足球。"}', 88, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5819, 161, '{"english": "2. -Does Mike go to school by bike?", "chinese": "2. —迈克骑自行车上学吗？"}', 89, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5820, 161, '{"english": "-Yes, he does.", "chinese": "—是的。"}', 90, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5821, 161, '{"english": "3. -Does Amy read the newspaper every day?", "chinese": "3. —艾米每天都看报纸吗？"}', 91, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5822, 161, '{"english": "-No, she doesn''t. But she loves to read stories.", "chinese": "—不，她不是。但她喜欢读故事。"}', 92, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5823, 161, '{"english": "4. -Does your mother like watching TV at night, John?", "chinese": "4. —约翰，你妈妈喜欢晚上看电视吗？"}', 93, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5824, 161, '{"english": "-No, she likes watching TV in the morning.", "chinese": "—不，她喜欢早上看电视。"}', 94, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5825, 161, '{"english": "Listen again and fill in the blanks.", "chinese": "再听一遍，并填空。"}', 95, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5826, 161, '{"english": "1. -Who is that?  -That''s Andy.", "chinese": "1. —那是谁？ —那是安迪。"}', 96, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5827, 161, '{"english": "-Does he like playing basketball?  -No, he likes playing football.", "chinese": "—他喜欢打篮球吗？ —不，他喜欢踢足球。"}', 97, '2026-02-05 04:02:13', '2026-02-05 04:02:13');
INSERT INTO "course_content" VALUES (5828, 161, '{"english": "2. -Does Mike go to school by bike?", "chinese": "2. —迈克骑自行车上学吗？"}', 98, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5829, 161, '{"english": "-Yes, he does.", "chinese": "—是的。"}', 99, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5830, 161, '{"english": "3. -Does Amy read the newspaper every day?", "chinese": "3. —艾米每天都看报纸吗？"}', 100, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5831, 161, '{"english": "-No, she doesn''t. But she loves to read stories.", "chinese": "—不，她不是。但她喜欢读故事。"}', 101, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5832, 161, '{"english": "4. -Does your mother like watching TV at night,John?", "chinese": "4. —约翰，你妈妈喜欢晚上看电视吗？"}', 102, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5833, 161, '{"english": "-No, she likes watching TV in the morning.", "chinese": "—不，她喜欢早上看电视。"}', 103, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5834, 161, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 104, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5835, 161, '{"english": "Underline the verbs and fill in the blanks.", "chinese": "在动词下面划线并填空。"}', 105, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5836, 161, '{"english": "Jane has a cat. The cat loves to sleep.", "chinese": "简有一只猫。猫喜欢睡觉。"}', 106, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5837, 161, '{"english": "Every afternoon Jane studies Chinese and does her homework.", "chinese": "每天下午简学习中文并做家庭作业。"}', 107, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5838, 161, '{"english": "After that, Jane teaches her sister to draw. The cat just sleeps.", "chinese": "之后，简教她妹妹画画。猫只是睡觉。"}', 108, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5839, 161, '{"english": "loves → love", "chinese": "爱"}', 109, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5840, 161, '{"english": "has → have", "chinese": "有"}', 110, '2026-02-05 04:02:14', '2026-02-05 04:02:14');
INSERT INTO "course_content" VALUES (5841, 162, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5842, 162, '{"english": "Today is Parents'' Day. Who will come? Listen and circle.", "chinese": "今天是家长日。谁会来？听一听并圈一圈。"}', 2, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5843, 162, '{"english": "-Sarah, today is Parents'' Day.", "chinese": "—萨拉，今天是家长日。"}', 3, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5844, 162, '{"english": "-Yes, my mother is coming, but my father is too busy.", "chinese": "—是的，我妈妈要来，但我爸爸太忙了。"}', 4, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5845, 162, '{"english": "-I see. What does your father do?  -He''s a doctor.", "chinese": "—我知道了。你父亲是做什么的？ —他是个医生。"}', 5, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5846, 162, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 6, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5847, 162, '{"english": "Is your father here today?", "chinese": "你爸爸今天在吗？"}', 7, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5848, 162, '{"english": "No. He''s in Australia.", "chinese": "不。他在澳大利亚。"}', 8, '2026-02-05 04:02:16', '2026-02-05 04:02:16');
INSERT INTO "course_content" VALUES (5849, 162, '{"english": "What does he do?", "chinese": "他是做什么工作的？"}', 9, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5850, 162, '{"english": "He''s a businessman. He often goes to other countries.", "chinese": "他是个商人。他经常去其他国家。"}', 10, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5851, 162, '{"english": "And what does your mother do?", "chinese": "那你妈妈是做什么工作的？"}', 11, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5852, 162, '{"english": "She''s a head teacher.", "chinese": "她是一名校长。"}', 12, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5853, 162, '{"english": "That''s nice.", "chinese": "那很棒。"}', 13, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5854, 162, '{"english": "Yeah. She''ll be here today!", "chinese": "是啊。她今天会来！"}', 14, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5855, 162, '{"english": "Do you want to be a head teacher, too?", "chinese": "你也想当一名校长吗？"}', 15, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5856, 162, '{"english": "No, I want to be a businessman.", "chinese": "不，我想成为一名商人。"}', 16, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5857, 162, '{"english": "What does Oliver''s father/mother do?", "chinese": "奥利弗的父亲/母亲是做什么工作的？"}', 17, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5858, 162, '{"english": "What does your father/mother do?", "chinese": "你爸爸/妈妈是做什么的？"}', 18, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5859, 162, '{"english": "taxi driver", "chinese": "出租车司机"}', 19, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5860, 162, '{"english": "cleaner", "chinese": "保洁员"}', 20, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5861, 162, '{"english": "writer", "chinese": "作家"}', 21, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5862, 162, '{"english": "singer", "chinese": "歌手"}', 22, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5863, 162, '{"english": "dancer", "chinese": "舞者"}', 23, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5864, 162, '{"english": "football player", "chinese": "足球运动员"}', 24, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5865, 162, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 25, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5866, 162, '{"english": "Career Day", "chinese": "职业日"}', 26, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5867, 162, '{"english": "factory worker", "chinese": "工厂工人"}', 27, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5868, 162, '{"english": "postman", "chinese": "邮递员"}', 28, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5869, 162, '{"english": "businessman", "chinese": "商人"}', 29, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5870, 162, '{"english": "police officer", "chinese": "警官"}', 30, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5871, 162, '{"english": "Is your father a postman?", "chinese": "你父亲是邮递员吗？"}', 31, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5872, 162, '{"english": "No, he isn''t.", "chinese": "不，他不是。"}', 32, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5873, 162, '{"english": "What does he do?", "chinese": "他是做什么工作的？"}', 33, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5874, 162, '{"english": "He''s a businessman.", "chinese": "他是个商人。"}', 34, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5875, 162, '{"english": "Listen, match and say", "chinese": "听一听，连一连，说一说"}', 35, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5876, 162, '{"english": "1. -What does your mother do, Jiao Jie?  -My mother is a businesswoman.", "chinese": "1. —你妈妈是做什么的，焦洁？ —我妈妈是个商人。"}', 36, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5877, 162, '{"english": "2. -Hi, Ge Nan. Today is Career Day.", "chinese": "2. —嗨，葛楠。今天是职业日。"}', 37, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5878, 162, '{"english": "What do you want to do?", "chinese": "你想做什么？"}', 38, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5879, 162, '{"english": "-I want to be a police officer, just like my father.  -Cool!", "chinese": "—我想成为一名警察，就像我父亲一样。 —酷！"}', 39, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5880, 162, '{"english": "3. -Hi, Zhou Jia. Is your mother coming today?", "chinese": "3. —你好，周佳。你妈妈今天来吗？"}', 40, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5881, 162, '{"english": "-No, she''s too busy.  -What does she do?  -She''s a factory worker.", "chinese": "—不，她太忙了。 —她是做什么的？ —她是一名工厂工人。"}', 41, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5882, 162, '{"english": "4. -My father is a doctor.", "chinese": "4. —我父亲是一名医生。"}', 42, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5883, 162, '{"english": "What about you, Liu Qian?  -My father is a postman.", "chinese": "你呢，刘谦？ —我父亲是邮递员。"}', 43, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5884, 162, '{"english": "What does Jiao Jie''s mother do?", "chinese": "焦洁的妈妈是做什么的？"}', 44, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5885, 162, '{"english": "She''s a businesswoman.", "chinese": "她是个商人。"}', 45, '2026-02-05 04:02:17', '2026-02-05 04:02:17');
INSERT INTO "course_content" VALUES (5886, 162, '{"english": "sea", "chinese": "海"}', 46, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5887, 162, '{"english": "plane", "chinese": "飞机"}', 47, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5888, 162, '{"english": "Can you think of any other jobs?", "chinese": "你能想到其他工作吗？"}', 48, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5889, 162, '{"english": "Where do those people work?", "chinese": "那些人在哪里工作？"}', 49, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5890, 162, '{"english": "Read and write", "chinese": "读一读，写一写"}', 50, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5891, 162, '{"english": "List five jobs. Compare with your partner.", "chinese": "列出五项工作。和你的搭档对比一下。"}', 51, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5892, 162, '{"english": "How many different jobs are there in both lists?", "chinese": "两份列表中有多少不同的工作？"}', 52, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5893, 162, '{"english": "Hu Bin likes sports. He is good at football, ping-pong and basketball.", "chinese": "胡斌喜欢运动。他擅长踢足球、打乒乓球和打篮球。"}', 53, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5894, 162, '{"english": "He often goes running after school.", "chinese": "他经常放学后跑步。"}', 54, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5895, 162, '{"english": "He wants to work in a gym.", "chinese": "他想在健身房工作。"}', 55, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5896, 162, '{"english": "Tip: If you like sports, you can be a coach,", "chinese": "小贴士：如果你喜欢运动，你可以做教练，"}', 56, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5897, 162, '{"english": "a sports reporter, or a PE teacher.", "chinese": "体育记者，或者体育老师。"}', 57, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5898, 162, '{"english": "Sarah likes using computers, and she can type very quickly.", "chinese": "萨拉喜欢使用电脑，她打字很快。"}', 58, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5899, 162, '{"english": "She wants to work in an office.", "chinese": "她想在办公室工作。"}', 59, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5900, 162, '{"english": "Tip: If you can type quickly, you can be a secretary.", "chinese": "小贴士：如果你打字很快，你可以当秘书。"}', 60, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5901, 162, '{"english": "Robin wants to be a scientist like Wu Binbin''s grandfather.", "chinese": "罗宾想成为像吴斌斌爷爷那样的科学家。"}', 61, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5902, 162, '{"english": "He studies very hard, and he wants to work in a university.", "chinese": "他学习很努力，并且他想在大学里工作。"}', 62, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5903, 162, '{"english": "Tip: If you like science, you can be a scientist.", "chinese": "小贴士：如果你喜欢科学，你可以成为一名科学家。"}', 63, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5904, 162, '{"english": "Choose a title for the text.", "chinese": "为文本选择标题。"}', 64, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5905, 162, '{"english": "People and their jobs", "chinese": "人和他们的工作"}', 65, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5906, 162, '{"english": "Hobbies and jobs", "chinese": "爱好和工作"}', 66, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5907, 162, '{"english": "Fill in the table.", "chinese": "填表。"}', 67, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5908, 162, '{"english": "What does he/she like?", "chinese": "他/她喜欢什么？"}', 68, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5909, 162, '{"english": "What does he/she want to be?", "chinese": "他/她想成为什么样的人？"}', 69, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5910, 162, '{"english": "Where is he/she going to work?", "chinese": "他/她要去哪里工作？"}', 70, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5911, 162, '{"english": "Hu Bin", "chinese": "胡斌"}', 71, '2026-02-05 04:02:18', '2026-02-05 04:02:18');
INSERT INTO "course_content" VALUES (5912, 163, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5913, 163, '{"english": "It''s cold outside.", "chinese": "外面很冷。"}', 2, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5914, 163, '{"english": "Sam is talking with Sarah. Listen and circle.", "chinese": "山姆正在和萨拉说话。听一听,圈一圈。"}', 3, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5915, 163, '{"english": "-Phew! It''s so cold in January.  -Yes, but we can stay inside and watch films.", "chinese": "—呸，一月份真冷。 —是的，但是我们可以呆在里面看电影。"}', 4, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5916, 163, '{"english": "-Great! I like cartoons.  -Yes, me too. They make me feel happy.", "chinese": "—太好了！我喜欢卡通片。 —是的，我也是。它们让我感到快乐。"}', 5, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5917, 163, '{"english": "1. Where are they?", "chinese": "1.他们在哪里？"}', 6, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5918, 163, '{"english": "2. What will they do?", "chinese": "2.他们将会怎么做？"}', 7, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5919, 163, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 8, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5920, 163, '{"english": "What''s this cartoon about?", "chinese": "这部卡通片是关于什么的？"}', 9, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5921, 163, '{"english": "It''s about a cat. The cat is a police officer.", "chinese": "这是关于一只猫的。这只猫是个警察。"}', 10, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5922, 163, '{"english": "Cool!", "chinese": "真棒！"}', 11, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5923, 163, '{"english": "He chases the mice. They''re afraid of him.", "chinese": "他追赶老鼠。他们怕他。"}', 12, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5924, 163, '{"english": "Why?", "chinese": "为什么？"}', 13, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5925, 163, '{"english": "Because the mice are bad. They hurt people.", "chinese": "因为老鼠很坏。他们伤害人。"}', 14, '2026-02-05 04:02:20', '2026-02-05 04:02:20');
INSERT INTO "course_content" VALUES (5926, 163, '{"english": "The cat is angry with them.", "chinese": "猫对他们很生气。"}', 15, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5927, 163, '{"english": "Maybe our cat is chasing a mouse now!", "chinese": "也许我们的猫正在追赶一只老鼠！"}', 16, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5928, 163, '{"english": "Why is the cat angry with the mice?", "chinese": "猫为什么生老鼠的气？"}', 17, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5929, 163, '{"english": "Read and tell your partner.", "chinese": "读一读并告诉你的搭档。"}', 18, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5930, 163, '{"english": "Your friends need some help.", "chinese": "你的朋友需要帮助。"}', 19, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5931, 163, '{"english": "Call them and give your suggestions.", "chinese": "打电话给他们，提出你的建议。"}', 20, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5932, 163, '{"english": "Don''t be angry. You should take a deep breath.", "chinese": "别生气。你应该深呼吸。"}', 21, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5933, 163, '{"english": "I''m angry.", "chinese": "我很生气。"}', 22, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5934, 163, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 23, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5935, 163, '{"english": "You should see a doctor.", "chinese": "你应该去看医生。"}', 24, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5936, 163, '{"english": "You should do more exercise.", "chinese": "你应该多做运动。"}', 25, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5937, 163, '{"english": "You should wear warm clothes.", "chinese": "你应该穿暖和的衣服。"}', 26, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5938, 163, '{"english": "You should take a deep breath and count to ten.", "chinese": "你应该深呼吸，然后数到十。"}', 27, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5939, 163, '{"english": "take a deep breath take a deep breath", "chinese": "深呼吸深呼吸"}', 28, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5940, 163, '{"english": "count to ten count to ten", "chinese": "数到十数到十"}', 29, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5941, 163, '{"english": "Play card games", "chinese": "玩纸牌游戏"}', 30, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5942, 163, '{"english": "What suggestions can you give?", "chinese": "你有什么建议？"}', 31, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5943, 163, '{"english": "What should I do?", "chinese": "我该怎么办？"}', 32, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5944, 163, '{"english": "You should wear warm clothes.", "chinese": "你应该穿暖和的衣服。"}', 33, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5945, 163, '{"english": "cold", "chinese": "冷的"}', 34, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5946, 163, '{"english": "ill", "chinese": "生病的"}', 35, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5947, 163, '{"english": "angry", "chinese": "愤怒的"}', 36, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5948, 163, '{"english": "worried", "chinese": "担心的"}', 37, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5949, 163, '{"english": "Read and write", "chinese": "读一读，写一写"}', 38, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5950, 163, '{"english": "Draw faces for each word.", "chinese": "为每个单词一张脸。"}', 39, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5951, 163, '{"english": "afraid", "chinese": "害怕的"}', 40, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5952, 163, '{"english": "happy", "chinese": "幸福的"}', 41, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5953, 163, '{"english": "angry", "chinese": "愤怒的"}', 42, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5954, 163, '{"english": "sad", "chinese": "悲哀的"}', 43, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5955, 163, '{"english": "Robin and the Ant", "chinese": "罗宾与蚂蚁"}', 44, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5956, 163, '{"english": "It is a sunny morning.", "chinese": "这是个晴朗的早晨。"}', 45, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5957, 163, '{"english": "Robin is going to sit on the grass when he hears, ''Wait!''", "chinese": "罗宾正要坐在草地上时听到，“等等！”"}', 46, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5958, 163, '{"english": "It is a little ant. He is afraid. ''Please don''t sit on me.", "chinese": "它是一只小蚂蚁。他很害怕。“请不要坐在我身上。"}', 47, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5959, 163, '{"english": "One day I can help you.''", "chinese": "总有一天我会帮助你的。”"}', 48, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5960, 163, '{"english": "''Don''t worry, little ant. I won''t sit on you,'' says Robin.", "chinese": "“别担心，小蚂蚁。我不会坐在你身上。”罗宾说。"}', 49, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5961, 163, '{"english": "The next day, it is raining. Robin is in the park.", "chinese": "第二天，下雨了。罗宾在公园里。"}', 50, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5962, 163, '{"english": "He is stuck in the mud. He is worried.", "chinese": "他陷在了泥里。他很担心。"}', 51, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5963, 163, '{"english": "Then he hears, ''Let us help you!''", "chinese": "然后他听到，“让我们来帮助你！”"}', 52, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5964, 163, '{"english": "It is the ant and all of his friends.", "chinese": "是蚂蚁和它所有的朋友。"}', 53, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5965, 163, '{"english": "They are strong. They pull Robin out of the mud.", "chinese": "他们很强壮。他们把罗宾从泥里拉了出来。"}', 54, '2026-02-05 04:02:21', '2026-02-05 04:02:21');
INSERT INTO "course_content" VALUES (5966, 163, '{"english": "Everyone is happy!", "chinese": "每个人都很开心！"}', 55, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5967, 163, '{"english": "What does the story tell us?", "chinese": "这个故事告诉我们什么？"}', 56, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5968, 163, '{"english": "A. We should always be nice to each other.", "chinese": "A. 我们应该永远友好相处。"}', 57, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5969, 163, '{"english": "B. We shouldn''t hurt ants.", "chinese": "B. 我们不应该伤害蚂蚁。"}', 58, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5970, 163, '{"english": "Number the pictures.", "chinese": "给图片编号。"}', 59, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5971, 163, '{"english": "Fill in the blanks and retell the story.", "chinese": "填空并复述故事。"}', 60, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5972, 163, '{"english": "The ant is ______.", "chinese": "蚂蚁是______。"}', 61, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5973, 163, '{"english": "Robin is stuck and ______.", "chinese": "罗宾被卡住了并且______。"}', 62, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5974, 163, '{"english": "The ants are strong. They ______.", "chinese": "蚂蚁很强壮。他们______。"}', 63, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5975, 163, '{"english": "Now everyone ______.", "chinese": "现在所有人______。"}', 64, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5976, 163, '{"english": "Tips for pronunciation", "chinese": "发音小贴士"}', 65, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5977, 163, '{"english": "Listen and repeat.", "chinese": "听录音，并跟读。"}', 66, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5978, 163, '{"english": "next day", "chinese": "接下来的一天"}', 67, '2026-02-05 04:02:22', '2026-02-05 04:02:22');
INSERT INTO "course_content" VALUES (5979, 163, '{"english": "can''t go", "chinese": "不能去"}', 68, '2026-02-05 04:02:23', '2026-02-05 04:02:23');
INSERT INTO "course_content" VALUES (5980, 164, '{"english": "Recycle 2", "chinese": "复习 2"}', 1, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5981, 164, '{"english": "Visiting an old friend", "chinese": "拜访老朋友"}', 2, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5982, 164, '{"english": "Peter''s family are going to visit Ken''s family in another town.", "chinese": "彼得一家打算去另一个城镇看望肯的家人。"}', 3, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5983, 164, '{"english": "Peter''s father is talking about them.", "chinese": "彼得的父亲正在谈论他们。"}', 4, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5984, 164, '{"english": "Listen and fill in the blanks.", "chinese": "听录音并填空。"}', 5, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5985, 164, '{"english": "My friend Kevin is a farmer. He has two boys and one girl.", "chinese": "我的朋友凯文是个农民。他有两个男孩和一个女孩。"}', 6, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5986, 164, '{"english": "His little boy is called Ken. He''s eleven years old.", "chinese": "他的小儿子叫肯。他 11 岁。"}', 7, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5987, 164, '{"english": "He likes singing. Ken''s mother is a worker in a milk factory.", "chinese": "他喜欢唱歌。肯的母亲是一家牛奶厂的工人。"}', 8, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5988, 164, '{"english": "She likes reading. Ken''s brother is a fisherman.", "chinese": "她喜欢读书。肯的哥哥是个渔夫。"}', 9, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5989, 164, '{"english": "He likes fishing. His sister is a police officer.", "chinese": "他喜欢钓鱼。他姐姐是一名警察。"}', 10, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5990, 164, '{"english": "She likes doing Kongfu. She''s really cool.", "chinese": "她喜欢功夫。她真的很酷。"}', 11, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5991, 164, '{"english": "Ken''s aunt teaches football. She likes watching football matches too.", "chinese": "肯的阿姨教足球。她也喜欢看足球比赛。"}', 12, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5992, 164, '{"english": "His uncle is a postman. He likes going hiking every week.", "chinese": "他的叔叔是邮递员。他喜欢每周去徒步旅行。"}', 13, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5993, 164, '{"english": "Listen again. Write down the hobbies for the people.", "chinese": "再听一遍。写下人们的爱好。"}', 14, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5994, 164, '{"english": "Peter''s family are on the bus.", "chinese": "彼得的家人在公共汽车上。"}', 15, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5995, 164, '{"english": "What are they doing on the bus?", "chinese": "他们在公共汽车上干什么？"}', 16, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5996, 164, '{"english": "Stop running! Sit down!", "chinese": "别跑了！坐下！"}', 17, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5997, 164, '{"english": "aunt", "chinese": "阿姨"}', 18, '2026-02-05 04:02:24', '2026-02-05 04:02:24');
INSERT INTO "course_content" VALUES (5998, 164, '{"english": "sister", "chinese": "姐妹"}', 19, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (5999, 164, '{"english": "cousin", "chinese": "表弟"}', 20, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6000, 164, '{"english": "mother", "chinese": "母亲"}', 21, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6001, 164, '{"english": "brother", "chinese": "兄弟"}', 22, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6002, 164, '{"english": "father", "chinese": "父亲"}', 23, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6003, 164, '{"english": "uncle", "chinese": "叔叔"}', 24, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6004, 164, '{"english": "Peter", "chinese": "彼得"}', 25, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6005, 164, '{"english": "Peter''s father is talking. He''s happy.", "chinese": "彼得的父亲在交谈，他很高兴。"}', 26, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6006, 164, '{"english": "happy", "chinese": "幸福的"}', 27, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6007, 164, '{"english": "sad", "chinese": "难过的"}', 28, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6008, 164, '{"english": "worried", "chinese": "担心的"}', 29, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6009, 164, '{"english": "angry", "chinese": "愤怒的"}', 30, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6010, 164, '{"english": "talking", "chinese": "说话"}', 31, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6011, 164, '{"english": "reading a book", "chinese": "读书"}', 32, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6012, 164, '{"english": "playing video games", "chinese": "玩电子游戏"}', 33, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6013, 164, '{"english": "doing word puzzles", "chinese": "做字谜"}', 34, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6014, 164, '{"english": "singing", "chinese": "歌唱"}', 35, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6015, 164, '{"english": "running", "chinese": "跑步"}', 36, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6016, 164, '{"english": "This is Peter''s puzzle. Do you know the answers?", "chinese": "这是彼得的难题。你知道答案吗？"}', 37, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6017, 164, '{"english": "DOWN", "chinese": "纵向"}', 38, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6018, 164, '{"english": "ACROSS", "chinese": "横向"}', 39, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6019, 164, '{"english": "1. You are afraid and not happy because something bad might happen.", "chinese": "1. 你害怕也不高兴，因为可能会有不好的事情发生。"}', 40, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6020, 164, '{"english": "2. You go there to see the doctor.", "chinese": "2. 你去那里看医生。"}', 41, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6021, 164, '{"english": "3. You are not feeling well.", "chinese": "3. 你感觉不舒服。"}', 42, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6022, 164, '{"english": "4. They catch bad men.", "chinese": "4. 他们抓坏人。"}', 43, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6023, 164, '{"english": "At Ken''s house, his father tells a story.", "chinese": "在肯的家里，他父亲讲了一个故事。"}', 44, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6024, 164, '{"english": "One day, a rich old businessman in a small town meets a factory worker,", "chinese": "有一天，一个富有的老商人在一个小镇遇见了一个工厂工人、"}', 45, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6025, 164, '{"english": "a coach and a fisherman.", "chinese": "一个教练和一个渔夫。"}', 46, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6026, 164, '{"english": "He gives them three seeds and says,", "chinese": "他给了他们三颗种子并说，"}', 47, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6027, 164, '{"english": "''Bring me the flowers in three months.", "chinese": "“三个月后带花来见我。"}', 48, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6028, 164, '{"english": "The man with the most beautiful flower can have my money!''", "chinese": "拥有最漂亮的花的人可以得到我的钱！”"}', 49, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6029, 164, '{"english": "After three months, the factory worker brings a big red flower.", "chinese": "三个月后，工厂工人带来了一朵大红花。"}', 50, '2026-02-05 04:02:25', '2026-02-05 04:02:25');
INSERT INTO "course_content" VALUES (6030, 165, '{"english": "Songs in each unit", "chinese": "单元歌曲表"}', 1, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6031, 165, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6032, 165, '{"english": "Where is the hospital?", "chinese": "医院在哪里？"}', 3, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6033, 165, '{"english": "Where is the hospital?  Is it near the park?", "chinese": "医院在哪？ 它在公园附近吗？"}', 4, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6034, 165, '{"english": "Where is the cinema?  Is it near the mall?", "chinese": "电影院在哪里？ 它在商场附近吗？"}', 5, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6035, 165, '{"english": "Come to the bookstore.  It''s next to the light.", "chinese": "到书店来。 就在灯旁边。"}', 6, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6036, 165, '{"english": "Come with me!  Come with me!  Come with me tonight.", "chinese": "跟我来！ 跟我来！ 今晚跟我来。"}', 7, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6037, 165, '{"english": "Where is the hospital?  Is it near the park?", "chinese": "医院在哪？ 它在公园附近吗？"}', 8, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6038, 165, '{"english": "Where is the cinema?  Is it near the mall?", "chinese": "电影院在哪里？ 它在商场附近吗？"}', 9, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6039, 165, '{"english": "Come to the bookstore.  It''s next to the light.", "chinese": "到书店来。 就在灯旁边。"}', 10, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6040, 165, '{"english": "Come with me!  Come with me!  Come with me tonight.", "chinese": "跟我来！ 跟我来！ 今晚跟我来。"}', 11, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6041, 165, '{"english": "Unit 2", "chinese": "第 2 单元"}', 12, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6042, 165, '{"english": "How do you get there?", "chinese": "你怎么到达那里？"}', 13, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6043, 165, '{"english": "You go by subway,  And I''ll go by taxi.", "chinese": "你乘地铁， 我乘出租车。"}', 14, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6044, 165, '{"english": "And I''ll be at school before you.", "chinese": "我会在你之前到学校。"}', 15, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6045, 165, '{"english": "You go by airplane,  And I''ll go by a big ship.", "chinese": "你乘飞机， 我乘大船，"}', 16, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6046, 165, '{"english": "And I''ll be in Scotland before you.", "chinese": "我会在你之前到达苏格兰。"}', 17, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6047, 165, '{"english": "You go by subway,  And I''ll go by taxi.  And I''ll be at school before you.", "chinese": "你乘地铁， 我乘出租车。 我会在你之前到学校。"}', 18, '2026-02-05 04:02:27', '2026-02-05 04:02:27');
INSERT INTO "course_content" VALUES (6048, 165, '{"english": "You go by airplane,  And I''ll go by a big ship.", "chinese": "你乘飞机， 我乘大船，"}', 19, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6049, 165, '{"english": "And I''ll be in Scotland before you.", "chinese": "我会在你之前到达苏格兰。"}', 20, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6050, 165, '{"english": "Unit 3", "chinese": "第 3 单元"}', 21, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6051, 165, '{"english": "What are you going to do?", "chinese": "你打算做什么？"}', 22, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6052, 165, '{"english": "I''m going to walk on the moon! Hooray! Hooray!", "chinese": "我要在月球上行走！万岁！万岁！"}', 23, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6053, 165, '{"english": "I''m going to walk on the moon! Hooray! Hooray!", "chinese": "我要在月球上行走！万岁！万岁！"}', 24, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6054, 165, '{"english": "When I grow up, I''ll walk on the moon.", "chinese": "当我长大了，我会在月球上行走。"}', 25, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6055, 165, '{"english": "When I grow up, I''ll walk on the moon.", "chinese": "当我长大了，我会在月球上行走。"}', 26, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6056, 165, '{"english": "What are you going to do?", "chinese": "你打算做什么？"}', 27, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6057, 165, '{"english": "I''m going to be a soldier!", "chinese": "我要当兵了！"}', 28, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6058, 165, '{"english": "Hooray! Hooray!  I''m going to be a soldier! Hooray!", "chinese": "万岁！万岁！ 我要当兵了！万岁！"}', 29, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6059, 165, '{"english": "Hooray!  When I grow up, I''ll be a soldier.", "chinese": "万岁！ 当我长大了，我要当兵当。"}', 30, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6060, 165, '{"english": "When I grow up, I''ll be a soldier.  What are you going to do?", "chinese": "我长大了，我要当兵。 你打算做什么？"}', 31, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
