INSERT INTO "course_content" VALUES (6062, 165, '{"english": "Hush, little boy", "chinese": "安静，小男孩"}', 33, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6063, 165, '{"english": "Hush, little boy, don''t say a word.", "chinese": "安静，小男孩。一句话也别说。"}', 34, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6064, 165, '{"english": "Papa''s going to buy you a little bird.", "chinese": "爸爸要给你买只小鸟。"}', 35, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6065, 165, '{"english": "And if that bird doesn''t sing,  Papa''s going to buy you a big, big ring.", "chinese": "如果那只鸟不唱歌， 爸爸会给你买一个大大的戒指。"}', 36, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6066, 165, '{"english": "And if that ring is lost in class,", "chinese": "如果戒指在课堂上丢了，"}', 37, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6067, 165, '{"english": "Papa''s going to buy you a looking glass.", "chinese": "爸爸会给你买个镜子。"}', 38, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6068, 165, '{"english": "And if that looking glass falls down,", "chinese": "如果镜子掉了，"}', 39, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
INSERT INTO "course_content" VALUES (6069, 165, '{"english": "Well, you''ll still be the sweetest boy in town.", "chinese": "你还是城里最可爱的男孩。"}', 40, '2026-02-05 04:02:28', '2026-02-05 04:02:28');
