INSERT INTO "course_content" VALUES (6253, 168, '{"english": "Useful expressions", "chinese": "常用表达法"}', 1, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6254, 168, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6255, 168, '{"english": "Where is the museum shop?", "chinese": "博物馆的商店在哪儿？"}', 3, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6256, 168, '{"english": "It''s near the door.", "chinese": "在大门附近。"}', 4, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6257, 168, '{"english": "How can we get there?", "chinese": "我们怎么到那儿？"}', 5, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6258, 168, '{"english": "Turn left at the bookstore.", "chinese": "到书店左转。"}', 6, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6259, 168, '{"english": "Unit 2", "chinese": "第 2 单元"}', 7, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6260, 168, '{"english": "How do you come to school?", "chinese": "你怎么来学校的？"}', 8, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6261, 168, '{"english": "Usually, I come on foot.", "chinese": "通常我走路来。"}', 9, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6262, 168, '{"english": "In the USA people on bikes must wear one.", "chinese": "在美国骑自行车的人必须戴（头盔）。"}', 10, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6263, 168, '{"english": "Don''t go at the red light!", "chinese": "别闯红灯！"}', 11, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6264, 168, '{"english": "I must pay attention to the traffic lights!", "chinese": "我必须注意交通信号灯！"}', 12, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6265, 168, '{"english": "Unit 3", "chinese": "第 3 单元"}', 13, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6266, 168, '{"english": "What are you going to do tomorrow?", "chinese": "你明天打算做什么？"}', 14, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6267, 168, '{"english": "I''m going to have an art lesson.", "chinese": "我要上美术课。"}', 15, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6268, 168, '{"english": "We''re going to draw some pictures in Renmin Park.", "chinese": "我们要到人民公园去画画。"}', 16, '2026-02-05 04:02:42', '2026-02-05 04:02:42');
INSERT INTO "course_content" VALUES (6269, 169, '{"english": "Unit 5", "chinese": "第 5 单元"}', 1, '2026-02-05 04:02:44', '2026-02-05 04:02:44');
INSERT INTO "course_content" VALUES (6270, 169, '{"english": "What does he do?", "chinese": "他是做什么的？"}', 2, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6271, 169, '{"english": "He''s a businessman.", "chinese": "他是商人。"}', 3, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6272, 169, '{"english": "Where does he work?", "chinese": "他在哪儿工作？"}', 4, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6273, 169, '{"english": "He works at sea.", "chinese": "他在海上工作。"}', 5, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6274, 169, '{"english": "How does he go to work?", "chinese": "他怎么上班？"}', 6, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6275, 169, '{"english": "He goes to work by bike.", "chinese": "他骑自行车上班。"}', 7, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6276, 169, '{"english": "Unit 6", "chinese": "第 6 单元"}', 8, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6277, 169, '{"english": "They''re afraid of him.", "chinese": "它们害怕它。"}', 9, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6278, 169, '{"english": "The cat is angry with them.", "chinese": "这只猫很生它们的气。"}', 10, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6279, 169, '{"english": "What''s wrong?", "chinese": "怎么了？"}', 11, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6280, 169, '{"english": "Your father is ill.", "chinese": "你爸爸病了。"}', 12, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6281, 169, '{"english": "He should see a doctor this morning.", "chinese": "他今天早上应该去看病。"}', 13, '2026-02-05 04:02:45', '2026-02-05 04:02:45');
INSERT INTO "course_content" VALUES (6282, 170, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6283, 170, '{"english": "The children are in the museum. Listen and circle.", "chinese": "同学们在博物馆里。听一听，圈一圈。"}', 2, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6284, 170, '{"english": "—Look at the dinosaur. It''s so big.", "chinese": "——看这只恐龙。它真大。"}', 3, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6285, 170, '{"english": "—Yes. That one eats vegetables.", "chinese": "——是的。那只吃蔬菜的。"}', 4, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6286, 170, '{"english": "—Cool.", "chinese": "——酷。"}', 5, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6287, 170, '{"english": "—This one eats meat. It''s taller.", "chinese": "——这只吃肉的。它更高。"}', 6, '2026-02-05 04:02:49', '2026-02-05 04:02:49');
INSERT INTO "course_content" VALUES (6288, 170, '{"english": "—You are right.", "chinese": "——你说得对。"}', 7, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6289, 170, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 8, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6290, 170, '{"english": "Look! That''s the tallest dinosaur in this hall.", "chinese": "看！那是这个厅里最高的恐龙。"}', 9, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6291, 170, '{"english": "Yes, it is. How tall is it?", "chinese": "是的，它是。它有多高？"}', 10, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6292, 170, '{"english": "Maybe 4 metres.", "chinese": "也许有 4 米。"}', 11, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6293, 170, '{"english": "Wow! It''s taller than both of us together.", "chinese": "哇！它比我们俩加起来还高。"}', 12, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6294, 170, '{"english": "Look! There are more dinosaurs over there!", "chinese": "看！那里还有更多的恐龙！"}', 13, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6295, 170, '{"english": "They''re all so big and tall.", "chinese": "它们都又大又高。"}', 14, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6296, 170, '{"english": "Hey, this dinosaur isn''t tall! I''m taller than this one.", "chinese": "嘿，这个恐龙不高！我比这只高。"}', 15, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6297, 170, '{"english": "Oh, yes. How tall are you?", "chinese": "哦，对的。你有多高？"}', 16, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6298, 170, '{"english": "I''m 1.65 metres.", "chinese": "我身高 1.65 米。"}', 17, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6299, 170, '{"english": "How tall is Zhang Peng?", "chinese": "张鹏有多高？"}', 18, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6300, 170, '{"english": "Who is taller, Zhang Peng or the small dinosaur?", "chinese": "谁更高，张鹏还是小恐龙？"}', 19, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6301, 170, '{"english": "How tall are you?", "chinese": "你有多高？"}', 20, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6302, 170, '{"english": "I''m _______ metres.", "chinese": "我 _______ 米。"}', 21, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6303, 170, '{"english": "Who is taller than you?", "chinese": "谁比你高？"}', 22, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6304, 170, '{"english": "How old are you?", "chinese": "你多大？"}', 23, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6305, 170, '{"english": "I''m ______.", "chinese": "我______。"}', 24, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6306, 170, '{"english": "Who is older than you?", "chinese": "谁比你年长？"}', 25, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6307, 170, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 26, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6308, 170, '{"english": "How tall are you?", "chinese": "你有多高？"}', 27, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6309, 170, '{"english": "I''m 1.61 metres.", "chinese": "我身高 1.61 米。"}', 28, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6310, 170, '{"english": "Oh! I''m taller.", "chinese": "哦！我更高。"}', 29, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6311, 170, '{"english": "You''re older than me, too.", "chinese": "你年龄也比我大。"}', 30, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6312, 170, '{"english": "younger", "chinese": "（young 的比较级）更年轻的"}', 31, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6313, 170, '{"english": "older", "chinese": "（old 的比较级）更年长的"}', 32, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6314, 170, '{"english": "taller", "chinese": "（tall 的比较级）更高的"}', 33, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6315, 170, '{"english": "shorter", "chinese": "（short 的比较级）更矮的"}', 34, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6316, 170, '{"english": "shorter", "chinese": "（short 的比较级）更短的"}', 35, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6317, 170, '{"english": "longer", "chinese": "（long 的比较级）更长的"}', 36, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6318, 170, '{"english": "Do a survey and report", "chinese": "做个调查并报告"}', 37, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6319, 170, '{"english": "How old are you?", "chinese": "你多大了？"}', 38, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6320, 170, '{"english": "I''m 12 years old.", "chinese": "我 12 岁。"}', 39, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6321, 170, '{"english": "How tall are you?", "chinese": "你有多高？"}', 40, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6322, 170, '{"english": "I''m 1.64 metres.", "chinese": "我身高 1.64 米。"}', 41, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6323, 170, '{"english": "Wu Binbin is taller than John, but Zhang Peng is taller than Wu Binbin.", "chinese": "吴斌斌比约翰高，但张鹏比吴斌斌高。"}', 42, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6324, 170, '{"english": "Name", "chinese": "姓名"}', 43, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6325, 170, '{"english": "Age", "chinese": "年龄"}', 44, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6326, 170, '{"english": "Height", "chinese": "身高"}', 45, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6327, 170, '{"english": "Wu Binbin has a story to tell Robin.", "chinese": "吴斌斌要给罗宾讲个故事。"}', 46, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6328, 170, '{"english": "(Title)", "chinese": "（标题）"}', 47, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6329, 170, '{"english": "Little Duck is watching the sun go down.", "chinese": "小鸭子正看着太阳下山。"}', 48, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6330, 170, '{"english": "It is getting lower and lower, but his shadow is getting longer and longer.", "chinese": "太阳越来越低，但它的影子却越来越长。"}', 49, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6331, 170, '{"english": "''Why is that?'' Little Duck asks his friend Old Tree.", "chinese": "“为什么会那样？”小鸭子问它的朋友老树。"}', 50, '2026-02-05 04:02:50', '2026-02-05 04:02:50');
INSERT INTO "course_content" VALUES (6332, 170, '{"english": "''You are older and smarter than me.", "chinese": "“你比我年长，也比我聪明。"}', 51, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6333, 170, '{"english": "Tell me — why is my shadow longer when the sun gets lower?''", "chinese": "告诉我为什么太阳越来越低的时候，我的影子会越来越长？”"}', 52, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6334, 170, '{"english": "Old Tree says, ''That''s easy, Little Duck.", "chinese": "老树说：“很简单，小鸭子。"}', 53, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6335, 170, '{"english": "The sun goes down every day, and we grow older every day.", "chinese": "太阳每天下山，我们每天变老。"}', 54, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6336, 170, '{"english": "Your shadow grows longer because you are growing taller.", "chinese": "你的影子变长了是因为你越来越高了。"}', 55, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6337, 170, '{"english": "You are becoming a big beautiful bird!''", "chinese": "你正在变成一只美丽的大鸟儿！”"}', 56, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6338, 170, '{"english": "Can you answer Little Duck''s question, Robin?", "chinese": "你能回答小鸭子的问题吗，罗宾？"}', 57, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6339, 170, '{"english": "Read and circle", "chinese": "读一读，圈一圈"}', 58, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6340, 170, '{"english": "1. Choose a title for the story.", "chinese": "1. 为故事选择一个标题。"}', 59, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6341, 170, '{"english": "A. Little Duck''s shadow", "chinese": "A. 小鸭子的影子"}', 60, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6342, 170, '{"english": "B. Old Tree''s shadow", "chinese": "B. 老树的影子"}', 61, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6343, 170, '{"english": "2. Who is younger?", "chinese": "2. 谁更年轻？"}', 62, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6344, 170, '{"english": "A. The tree.", "chinese": "A. 树。"}', 63, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6345, 170, '{"english": "B. The duck.", "chinese": "B. 鸭子。"}', 64, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6346, 170, '{"english": "3. When is the duck''s shadow longer?", "chinese": "3. 鸭子的影子什么时候更长？"}', 65, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6347, 170, '{"english": "A. In the morning.", "chinese": "A. 在早上。"}', 66, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6348, 170, '{"english": "B. In the afternoon.", "chinese": "B. 在下午。"}', 67, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6349, 170, '{"english": "Read the story again and finish the dialogue.", "chinese": "再读一遍故事，完成对话。"}', 68, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6350, 170, '{"english": "Old Tree, the sun gets _______, but my shadow gets _______.", "chinese": "老树，太阳变得 _______，但我的影子变得 _______。"}', 69, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6351, 170, '{"english": "Why?", "chinese": "为什么？"}', 70, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6352, 170, '{"english": "That''s easy.", "chinese": "这很简单。"}', 71, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6353, 170, '{"english": "Your shadow gets longer because you are getting _______ and growing _______ everyday.", "chinese": "你的影子变长，因为你每天都变得 _______并且每天 _______ 成长。"}', 72, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6354, 170, '{"english": "So what will happen to me?", "chinese": "那我会怎么样？"}', 73, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6355, 170, '{"english": "Well, ...", "chinese": "嗯，⋯⋯"}', 74, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6356, 170, '{"english": "Think and discuss.", "chinese": "想一想并讨论。"}', 75, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6357, 170, '{"english": "1. Do you agree with Old Tree? Why?", "chinese": "1. 你同意老树的观点吗？为什么？"}', 76, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6358, 170, '{"english": "2. Can you answer Little Duck''s question?", "chinese": "2. 你能回答小鸭子的问题吗？"}', 77, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6359, 170, '{"english": "What''s your answer?", "chinese": "你的答案是什么？"}', 78, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6360, 170, '{"english": "3. Please circle the words with ''-er''.", "chinese": "3. 请圈出带“-er”的单词。"}', 79, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6361, 170, '{"english": "Then talk about the changes in your friends.", "chinese": "然后谈谈你朋友们的变化。"}', 80, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6362, 170, '{"english": "Let''s check", "chinese": "让我们查一查"}', 81, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6363, 170, '{"english": "Listen and tick.", "chinese": "听一听，勾一勾。"}', 82, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6364, 170, '{"english": "1. —John and Sarah have a birthday next week.", "chinese": "1. ——约翰和萨拉下周过生日。"}', 83, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6365, 170, '{"english": "—Really? On the same day?", "chinese": "——真的吗？在同一天？"}', 84, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6366, 170, '{"english": "—No. Sarah is two days younger.", "chinese": "——不。萨拉小两天。"}', 85, '2026-02-05 04:02:51', '2026-02-05 04:02:51');
INSERT INTO "course_content" VALUES (6367, 170, '{"english": "Question: Who''s older?", "chinese": "问题：谁更年长？"}', 86, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6368, 170, '{"english": "2. —Zhang Peng, do you exercise?", "chinese": "2. ——张鹏，你锻炼吗？"}', 87, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6369, 170, '{"english": "—Yes.I exercise every day, but I''m heavier than before.", "chinese": "——是的。我每天锻炼，但我比以前更重了。"}', 88, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6370, 170, '{"english": "—That''s strange. Do you eat too much candy?", "chinese": "——那真奇怪。你吃了太多糖果吗？"}', 89, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6371, 170, '{"english": "Question: Is Zhang Peng heavier or thinner now?", "chinese": "问题：现在张鹏更重还是更瘦？"}', 90, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6372, 170, '{"english": "3. —My hair is long. It covers my ears.", "chinese": "3. ——我的头发很长。它盖过我的耳朵了。"}', 91, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6373, 170, '{"english": "—Yes. It''s quite long for a boy.", "chinese": "——是的。这对男生来说太长了。"}', 92, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6374, 170, '{"english": "Isn''t your hair usually shorter?", "chinese": "你的头发通常不是更短吗？"}', 93, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6375, 170, '{"english": "Question: Is Mike''s hair longer or shorter now?", "chinese": "问题：现在迈克的头发更长还是更短？"}', 94, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6376, 170, '{"english": "4. —I like elephants. They''re funny.", "chinese": "4. ——我喜欢大象。它们很有趣。"}', 95, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6377, 170, '{"english": "—Yes, and they''re very big and fast.", "chinese": "——是的，而且它们又大又快。"}', 96, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6378, 170, '{"english": "—How tall are they?", "chinese": "——它们有多高？"}', 97, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6379, 170, '{"english": "—They''re about three metres tall.", "chinese": "——它们大约三米高。"}', 98, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6380, 170, '{"english": "—Wow! That''s taller than a bus.", "chinese": "——哇！那比公共汽车还高。"}', 99, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6381, 170, '{"english": "Question: Which is taller, a bus or an elephant?", "chinese": "问题：公共汽车和大象哪个更高？"}', 100, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6382, 170, '{"english": "Listen again and write the answers to the questions.", "chinese": "再听一遍，写出问题的答案。"}', 101, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6383, 170, '{"english": "1. —John and Sarah have a birthday next week.", "chinese": "1. ——约翰和萨拉下周过生日。"}', 102, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6384, 170, '{"english": "—Really? On the same day?", "chinese": "——真的吗？在同一天？"}', 103, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6385, 170, '{"english": "—No. Sarah is two days younger.", "chinese": "——不。萨拉小两天。"}', 104, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6386, 170, '{"english": "Question: Who''s older?", "chinese": "问题：谁更年长？"}', 105, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6387, 170, '{"english": "2. —Zhang Peng, do you exercise?", "chinese": "2. ——张鹏，你锻炼吗？"}', 106, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6388, 170, '{"english": "—Yes. I exercise every day, but I''m heavier than before.", "chinese": "——是的。我每天锻炼，但我比以前更重了。"}', 107, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6389, 170, '{"english": "—That''s strange. Do you eat too much candy?", "chinese": "——那真奇怪。你吃了太多糖果吗？"}', 108, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6390, 170, '{"english": "Question: Is Zhang Peng heavier or thinner now?", "chinese": "问题：现在张鹏更重还是更瘦？"}', 109, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6391, 170, '{"english": "3. —My hair is long. It covers my ears.", "chinese": "3. ——我的头发很长。它盖过我的耳朵了。"}', 110, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6392, 170, '{"english": "—Yes. It''s quite long for a boy. Isn''t your hair usually shorter?", "chinese": "——是的。这对男生来说太长了。你的头发通常不是更短吗？"}', 111, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6393, 170, '{"english": "Question: Is Mike''s hair longer or shorter now?", "chinese": "问题：现在迈克的头发更长还是更短？"}', 112, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6394, 170, '{"english": "4. —I like elephants. They''re funny.", "chinese": "4. ——我喜欢大象。它们很有趣。"}', 113, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6395, 170, '{"english": "—Yes, and they''re very big and fast.", "chinese": "——是的，而且它们又大又快。"}', 114, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6396, 170, '{"english": "—How tall are they?", "chinese": "——它们有多高？"}', 115, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6397, 170, '{"english": "—They''re about three metres tall.", "chinese": "——它们大约三米高。"}', 116, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6398, 170, '{"english": "—Wow! That''s taller than a bus.", "chinese": "——哇！那比公共汽车还高。"}', 117, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6399, 170, '{"english": "Question: Which is taller, a bus or an elephant?", "chinese": "问题：公共汽车和大象哪个更高？"}', 118, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6400, 170, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 119, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6401, 170, '{"english": "Read and write.", "chinese": "读一读，写一写。"}', 120, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6402, 170, '{"english": "tall — taller", "chinese": "高的—更高的"}', 121, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6403, 170, '{"english": "thin — thinner", "chinese": "瘦的—更瘦的"}', 122, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6404, 170, '{"english": "heavy — heavier", "chinese": "重的—更重的"}', 123, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6405, 170, '{"english": "long", "chinese": "长的"}', 124, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6406, 170, '{"english": "strong", "chinese": "强壮的"}', 125, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6407, 170, '{"english": "big", "chinese": "大的"}', 126, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6408, 170, '{"english": "sad", "chinese": "悲伤的"}', 127, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6409, 170, '{"english": "hot", "chinese": "热的"}', 128, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6410, 170, '{"english": "angry", "chinese": "愤怒的"}', 129, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6411, 170, '{"english": "sunny", "chinese": "晴朗的"}', 130, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6412, 170, '{"english": "funny", "chinese": "有趣的"}', 131, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6413, 170, '{"english": "happy", "chinese": "幸福的"}', 132, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6414, 170, '{"english": "windy", "chinese": "刮风的"}', 133, '2026-02-05 04:02:52', '2026-02-05 04:02:52');
INSERT INTO "course_content" VALUES (6415, 171, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6416, 171, '{"english": "Sarah and Mike are talking about this weekend.", "chinese": "萨拉和迈克正在谈论这个周末。"}', 2, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6417, 171, '{"english": "Listen and circle.", "chinese": "听一听，圈一圈。"}', 3, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6418, 171, '{"english": "—Tomorrow is Monday. We will have class again soon.", "chinese": "——明天是星期一。 我们很快又要上课了。"}', 4, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6419, 171, '{"english": "—Yes, we will.", "chinese": "——是的。"}', 5, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6420, 171, '{"english": "—How was your weekend, Mike?", "chinese": "——迈克，你周末过得怎么样？"}', 6, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6421, 171, '{"english": "—It was OK. I cleaned my room and I watched TV.", "chinese": "——还可以。我打扫了我的房间，看了电视。"}', 7, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6422, 171, '{"english": "I''m going to call my grandparents now. They''re in London.  —OK. Bye.", "chinese": "我现在要给我的爷爷奶奶打电话。他们在伦敦。 ——好的。再见。"}', 8, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6423, 171, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 9, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6424, 171, '{"english": "Hi, Grandpa. How are you? How was your weekend?", "chinese": "嗨，爷爷。您好吗？您周末过得怎么样？"}', 10, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6425, 171, '{"english": "I''m fine, Mike. It was good, thank you.", "chinese": "我很好，迈克。 我周末过得不错，谢谢你。"}', 11, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6426, 171, '{"english": "What did you do?", "chinese": "你做了什么？"}', 12, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6427, 171, '{"english": "Well, I stayed at home with your grandma.", "chinese": "嗯，我和你奶奶待在家里。"}', 13, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6428, 171, '{"english": "We drank tea in the afternoon and watched TV.", "chinese": "我们喝了下午茶，还看了电视。"}', 14, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6429, 171, '{"english": "I watched TV, too. I watched some children''s shows on TV.", "chinese": "我也看电视了。我在电视上看了一些儿童节目。"}', 15, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6430, 171, '{"english": "That''s nice. Did you do anything else?", "chinese": "很好。你还做了其他什么事吗？"}', 16, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6431, 171, '{"english": "Yes, I cleaned my room and washed my clothes.", "chinese": "是的，我打扫了房间，还洗了衣服。"}', 17, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6432, 171, '{"english": "You are a good boy!", "chinese": "你是个好孩子！"}', 18, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6433, 171, '{"english": "What did Mike''s grandpa do last weekend?", "chinese": "上周末迈克的爷爷做了什么？"}', 19, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6434, 171, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 20, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6435, 171, '{"english": "What did you do last weekend?", "chinese": "上周末你做了什么？"}', 21, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6436, 171, '{"english": "What are you going to do next weekend?", "chinese": "下周末你打算做什么？"}', 22, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6437, 171, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 23, '2026-02-05 04:02:54', '2026-02-05 04:02:54');
INSERT INTO "course_content" VALUES (6438, 171, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 24, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6439, 171, '{"english": "It was fine, thanks.", "chinese": "很好，谢谢。"}', 25, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6440, 171, '{"english": "What did you do?", "chinese": "你做了什么？"}', 26, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6441, 171, '{"english": "I stayed at home and watched TV.", "chinese": "我待在家里看电视。"}', 27, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6442, 171, '{"english": "cleaned my room", "chinese": "打扫我的房间"}', 28, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6443, 171, '{"english": "washed my clothes", "chinese": "洗我的衣服"}', 29, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6444, 171, '{"english": "stayed at home", "chinese": "待在家里"}', 30, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6445, 171, '{"english": "watched TV", "chinese": "看电视"}', 31, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6446, 171, '{"english": "Do a survey and report", "chinese": "做个调查并报告"}', 32, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6447, 171, '{"english": "Ask six students.", "chinese": "问六个学生。"}', 33, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6448, 171, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 34, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6449, 171, '{"english": "It was OK.", "chinese": "还可以。"}', 35, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6450, 171, '{"english": "What did you do?", "chinese": "你做了什么？"}', 36, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6451, 171, '{"english": "I washed my clothes.", "chinese": "我洗了我的衣服。"}', 37, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6452, 171, '{"english": "What did you do?", "chinese": "你做了什么？"}', 38, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6453, 171, '{"english": "Tick", "chinese": "打勾"}', 39, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6454, 171, '{"english": "washed my clothes", "chinese": "洗我的衣服"}', 40, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6455, 171, '{"english": "stayed at home", "chinese": "待在家里"}', 41, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6456, 171, '{"english": "watched TV", "chinese": "看电视"}', 42, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6457, 171, '{"english": "cleaned my room", "chinese": "打扫我的房间"}', 43, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6458, 171, '{"english": "did something else", "chinese": "做了些其他的事"}', 44, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6459, 171, '{"english": "Now tell the class.", "chinese": "现在告诉全班同学。"}', 45, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6460, 171, '{"english": "Last weekend, two students washed their clothes ...", "chinese": "上周末，两个学生洗了衣服⋯⋯"}', 46, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6461, 171, '{"english": "slept, had a cold", "chinese": "睡觉，感冒"}', 47, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6462, 171, '{"english": "went boating", "chinese": "去划船"}', 48, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6463, 171, '{"english": "read a book", "chinese": "看书"}', 49, '2026-02-05 04:02:55', '2026-02-05 04:02:55');
INSERT INTO "course_content" VALUES (6464, 171, '{"english": "saw a film", "chinese": "看电影"}', 50, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6465, 171, '{"english": "washed her clothes", "chinese": "洗她的衣服"}', 51, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6466, 171, '{"english": "Read and write", "chinese": "读一读，写一写"}', 52, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6467, 171, '{"english": "This is Mrs Broom. She works in a hotel.", "chinese": "这是布鲁姆女士。她在一家旅馆工作。"}', 53, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6468, 171, '{"english": "She is a housekeeper. What do you think she did yesterday?", "chinese": "她是一名管家。你认为她昨天做了什么？"}', 54, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6469, 171, '{"english": "made the beds  cooked the food  cleaned the rooms", "chinese": "铺床 做饭 打扫房间"}', 55, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6470, 171, '{"english": "Wu Binbin and his family stayed at the Holiday Hotel.", "chinese": "吴斌斌和他的家人住在假日酒店。"}', 56, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6471, 171, '{"english": "It was not a happy time.", "chinese": "那并不是一段快乐的时光。"}', 57, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6472, 171, '{"english": "Dear Customer,  Thank you for staying in our hotel. How was your stay?", "chinese": "亲爱的住户： 感谢您入住我们的酒店。您住得怎么样？"}', 58, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6473, 171, '{"english": "Please circle:  Good/Average/Bad", "chinese": "请圈出： 好/一般/不好"}', 59, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6474, 171, '{"english": "Comments", "chinese": "评论"}', 60, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6475, 171, '{"english": "Dear Sir,", "chinese": "尊敬的先生："}', 61, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6476, 171, '{"english": "Our weekend at your hotel was bad.", "chinese": "我们的周末在你们的旅馆过得很糟糕。"}', 62, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6477, 171, '{"english": "Our room was big but everything was very old.", "chinese": "我们的房间很大，但是所有东西都很旧。"}', 63, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6478, 171, '{"english": "Our friend Robin cleaned our room and fixed a broken chair.", "chinese": "我们的朋友罗宾打扫了房间，并把一把坏掉的椅子修好了。"}', 64, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6479, 171, '{"english": "My mother wanted to read a book but the lamp was too small.", "chinese": "我妈妈想看书，但是台灯太小了。"}', 65, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6480, 171, '{"english": "My dad got some hamburgers from the hotel kitchen,", "chinese": "我爸爸从酒店厨房拿了一些汉堡，"}', 66, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6481, 171, '{"english": "but they were cold and tasted bad.", "chinese": "但它们又凉又难吃。"}', 67, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6482, 171, '{"english": "I wanted to watch TV but the TV didn''t work.", "chinese": "我想看电视，但电视机坏了。"}', 68, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6483, 171, '{"english": "The people in Room 301 listened to loud music.", "chinese": "301 房间的客人在听很嘈杂的音乐。"}', 69, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6484, 171, '{"english": "I didn''t sleep all night.", "chinese": "我整晚都没睡。"}', 70, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6485, 171, '{"english": "I''m sorry, but we didn''t enjoy our stay very much.", "chinese": "我很抱歉，但是我们非常不享受住在这里。"}', 71, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6486, 171, '{"english": "Wu Binbin and family", "chinese": "吴斌斌和家人"}', 72, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6487, 171, '{"english": "Read the letter again quickly. Find the sentences that describe Pictures 1-3.", "chinese": "快速把信再读一遍。找出描述图 1—3 的句子。"}', 73, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6488, 171, '{"english": "Circle all the verbs in the text and complete the table.", "chinese": "圈出课文中的所有的动词并完成表格。"}', 74, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6489, 171, '{"english": "Past", "chinese": "过去式"}', 75, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6490, 171, '{"english": "Present", "chinese": "现在式"}', 76, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6491, 171, '{"english": "was", "chinese": "是"}', 77, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6492, 171, '{"english": "is", "chinese": "是"}', 78, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6493, 171, '{"english": "Read and finish the letter.", "chinese": "阅读并完成这封信。"}', 79, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6494, 171, '{"english": "Dear Manager,", "chinese": "尊敬的经理："}', 80, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6495, 171, '{"english": "Last weekend, the Wu family were not happy with their room.", "chinese": "上周末，吴先生一家对他们的房间不满意。"}', 81, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6496, 171, '{"english": "The people in Room 301 _______ all night.", "chinese": "301 房间的人整晚都在 _______。"}', 82, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6497, 171, '{"english": "It was very noisy. The father _______ from the kitchen but _______.", "chinese": "非常吵。父亲从厨房 _______ 但是 _______。"}', 83, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6498, 171, '{"english": "Also, the mother _______ but the lamp _______.", "chinese": "还有，母亲 _______ 但是灯 _______ 。"}', 84, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6499, 171, '{"english": "The TV didn''t work either.", "chinese": "电视也坏了。"}', 85, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6500, 171, '{"english": "It wasn''t a good stay.", "chinese": "住得很不舒服。"}', 86, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6501, 171, '{"english": "Maybe we can write an email and say sorry to them.", "chinese": "也许我们可以写封电子邮件跟他们说抱歉。"}', 87, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6502, 171, '{"english": "Mrs Broom", "chinese": "布鲁姆女士"}', 88, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6503, 171, '{"english": "Let''s check", "chinese": "让我们查一查"}', 89, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6504, 171, '{"english": "Listen and number.", "chinese": "听一听并排序。"}', 90, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6505, 171, '{"english": "1. —Hey, how was your weekend, Amy?", "chinese": "1. ——嘿，艾米，你周末过得怎么样？"}', 91, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6506, 171, '{"english": "—It was OK.", "chinese": "——还可以。"}', 92, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6507, 171, '{"english": "—What did you do?", "chinese": "——你做了什么？"}', 93, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6508, 171, '{"english": "—I cleaned my room and I watched TV.", "chinese": "——我打扫了房间，还看了电视。"}', 94, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6509, 171, '{"english": "2. —I had a great weekend.", "chinese": "2. ——我过了一个很棒的周末。"}', 95, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6510, 171, '{"english": "—Really? What did you do, Zhang Peng?", "chinese": "——真的吗？张鹏，你做了什么？"}', 96, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6511, 171, '{"english": "—I went boating and slept on Saturday.", "chinese": "——星期六我划船和睡觉了。"}', 97, '2026-02-05 04:02:56', '2026-02-05 04:02:56');
INSERT INTO "course_content" VALUES (6512, 171, '{"english": "—What about Sunday?", "chinese": "——星期天呢？"}', 98, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6513, 171, '{"english": "—I read storybooks.", "chinese": "——我读故事书了。"}', 99, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6514, 171, '{"english": "3. —What did you do last weekend, John?", "chinese": "3. ——约翰，你上周末做了什么？"}', 100, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6515, 171, '{"english": "—Nothing. I had a cold.", "chinese": "——什么都没做。我感冒了。"}', 101, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6516, 171, '{"english": "—Oh. Are you OK now?", "chinese": "——哦。你现在好了吗？"}', 102, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6517, 171, '{"english": "—Yes, I''m fine. Thanks, Chen Jie.", "chinese": "——是的，我好了。谢谢，陈洁。"}', 103, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6518, 171, '{"english": "4. —What did you do yesterday?", "chinese": "4. ——你昨天做了什么？"}', 104, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6519, 171, '{"english": "—I saw a new action film.", "chinese": "——我看了一部新的动作片。"}', 105, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6520, 171, '{"english": "—Did you like it?", "chinese": "——你喜欢它吗？"}', 106, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6521, 171, '{"english": "—Yes, I did.", "chinese": "——是的，我喜欢。"}', 107, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6522, 171, '{"english": "—What will you do today, Mike?", "chinese": "——迈克，你今天要做什么？"}', 108, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6523, 171, '{"english": "—Oh, I will play football.", "chinese": "——哦，我要去踢足球。"}', 109, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6524, 171, '{"english": "—OK. Have fun!", "chinese": "——好的。玩得愉快！"}', 110, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6525, 171, '{"english": "Listen again and number the phrases.", "chinese": "再听一遍，给词组排序。"}', 111, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6526, 171, '{"english": "1. -Hey, how was your weekend, Amy?  -It was OK.", "chinese": "1. —嘿，艾米，你周末过得怎么样？ —还可以。"}', 112, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6527, 171, '{"english": "-What did you do?  -I cleaned my room and I watched TV.", "chinese": "—你做了什么？ —我打扫了房间，还看了电视。"}', 113, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6528, 171, '{"english": "2. -I had a great weekend.  -Really? What did you do, Zhang Peng?", "chinese": "2. —我过了一个很棒的周末。 —真的吗？张鹏，你做了什么？"}', 114, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6529, 171, '{"english": "-I went boating and slept on Saturday.  -What about Sunday?  -I read storybooks.", "chinese": "—星期六我去划了船，睡觉。 —星期天呢？ —我读了故事书。"}', 115, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6530, 171, '{"english": "3. -What did you do last weekend, John?", "chinese": "3. —约翰，你上周末做了什么？"}', 116, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6531, 171, '{"english": "-Nothing. I had a cold.  -Oh. Are you OK now?", "chinese": "—什么都没做。我感冒了。 —哦。你现在好了吗？"}', 117, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6532, 171, '{"english": "-Yes, I''m fine. Thanks, Chen Jie.", "chinese": "—是的，我好了。谢谢，陈洁。"}', 118, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6533, 171, '{"english": "4. -What did you do yesterday?", "chinese": "4. —你昨天做了什么？"}', 119, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6534, 171, '{"english": "-I saw a new action film.  -Did you like it?", "chinese": "—我看了一部新的动作片。 —你喜欢它吗？"}', 120, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6535, 171, '{"english": "-Yes, I did.  -What will you do today, Mike?", "chinese": "—是的，我喜欢。 —迈克，你今天要做什么？"}', 121, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6536, 171, '{"english": "-Oh, I will play football.  -OK. Have fun!", "chinese": "—哦，我要去踢足球。 —好的。玩得愉快！"}', 122, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6537, 171, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 123, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6538, 171, '{"english": "Read and complete the sentences.", "chinese": "读一读并完成下列句子。"}', 124, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6539, 171, '{"english": "talk → talked", "chinese": "谈话"}', 125, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6540, 171, '{"english": "stay → stayed", "chinese": "暂住；逗留"}', 126, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6541, 171, '{"english": "live → lived", "chinese": "住"}', 127, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6542, 171, '{"english": "want → wanted", "chinese": "想要"}', 128, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6543, 171, '{"english": "plan → planned", "chinese": "计划"}', 129, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6544, 171, '{"english": "cry → cried", "chinese": "哭；喊"}', 130, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6545, 171, '{"english": "I (cook) _______ dinner last Monday.", "chinese": "我上星期一 _______ （烹饪）晚饭。"}', 131, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6546, 171, '{"english": "I (play) _______ football last weekend.", "chinese": "我上周末 _______ （踢）足球。"}', 132, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6547, 171, '{"english": "I (like) _______ the food yesterday.", "chinese": "我 _______ （喜欢）昨天的食物。"}', 133, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6548, 171, '{"english": "I (visit) _______ my grandparents last weekend.", "chinese": "上周末我去 _______ （看望）我的祖父母。"}', 134, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6549, 171, '{"english": "I (stop) _______ to look at the flower.", "chinese": "我 _______ （停下来）看花。"}', 135, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6550, 171, '{"english": "I (study) _______ English last night.", "chinese": "我昨晚 _______ （学习）英语。"}', 136, '2026-02-05 04:02:57', '2026-02-05 04:02:57');
INSERT INTO "course_content" VALUES (6551, 172, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:02:58', '2026-02-05 04:02:58');
INSERT INTO "course_content" VALUES (6552, 172, '{"english": "John answered a phone call from Amy.", "chinese": "约翰接听了艾米的电话。"}', 2, '2026-02-05 04:02:58', '2026-02-05 04:02:58');
INSERT INTO "course_content" VALUES (6553, 172, '{"english": "Listen and tick or cross.", "chinese": "听一听，判断正误。"}', 3, '2026-02-05 04:02:58', '2026-02-05 04:02:58');
INSERT INTO "course_content" VALUES (6554, 172, '{"english": "—John, where are you? It''s time for our first class!", "chinese": "——约翰，你在哪里？我们该上第一节课了！"}', 4, '2026-02-05 04:02:58', '2026-02-05 04:02:58');
INSERT INTO "course_content" VALUES (6555, 172, '{"english": "—Sorry, I''m at the hospital now.", "chinese": "——对不起，我现在在医院。"}', 5, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6556, 172, '{"english": "—What happened?", "chinese": "——怎么了？"}', 6, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6557, 172, '{"english": "—I hurt my foot. Please tell Mr Hu I''m sorry I can''t come.", "chinese": "——我的脚受伤了。请告诉胡老师，很抱歉我不能来。"}', 7, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6558, 172, '{"english": "—OK. Bye.", "chinese": "——好的。再见。"}', 8, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6559, 172, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 9, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6560, 172, '{"english": "What happened?", "chinese": "怎么了？"}', 10, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6561, 172, '{"english": "I fell off my bike last Saturday and hurt my foot.", "chinese": "上星期六我从自行车上摔下来，伤了脚。"}', 11, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6562, 172, '{"english": "That''s too bad! Are you all right?", "chinese": "那太糟糕了！你还好吗？"}', 12, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6563, 172, '{"english": "I''m OK now.", "chinese": "我现在没事了。"}', 13, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6564, 172, '{"english": "Come and look at my photos from the Labour Day holiday.", "chinese": "来看看我在劳动节假期拍的照片吧。"}', 14, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6565, 172, '{"english": "Where did you go?", "chinese": "你去了哪里？"}', 15, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6566, 172, '{"english": "Mt. Tianshan, Xinjiang. I rode a horse.", "chinese": "新疆的天山。我骑了马。"}', 16, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6567, 172, '{"english": "Look, it''s very small!", "chinese": "看，它非常小！"}', 17, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6568, 172, '{"english": "Oh, yes. It looks like a mule!", "chinese": "哦，是的。它看起来像骡子！"}', 18, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6569, 172, '{"english": "Did you go to Turpan?", "chinese": "你们去吐鲁番了吗？"}', 19, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6570, 172, '{"english": "Yes, we did. We saw lots of grapes there, but we couldn''t eat them.", "chinese": "是的，我们去了。在那里我们看到了很多葡萄，但我们不能吃。"}', 20, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6571, 172, '{"english": "They won''t be ready till August.", "chinese": "它们到八月才熟。"}', 21, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6572, 172, '{"english": "Where did John go over his holiday?", "chinese": "约翰假期去哪里了？"}', 22, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6573, 172, '{"english": "What did he do?", "chinese": "他做了什么？"}', 23, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6574, 172, '{"english": "Where did you go over your holiday?", "chinese": "你假期去了哪里？"}', 24, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6575, 172, '{"english": "What did you do?", "chinese": "你做了什么？"}', 25, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6576, 172, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 26, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6577, 172, '{"english": "Where did you go last Saturday?", "chinese": "上星期六你去哪儿了？"}', 27, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6578, 172, '{"english": "I went to a forest park.", "chinese": "我去森林公园了。"}', 28, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6579, 172, '{"english": "What did you do there?", "chinese": "你在那里做了什么？"}', 29, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6580, 172, '{"english": "I rode a bike.", "chinese": "我骑自行车了。"}', 30, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6581, 172, '{"english": "rode a horse", "chinese": "骑马"}', 31, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6582, 172, '{"english": "rode a bike", "chinese": "骑自行车"}', 32, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6583, 172, '{"english": "went camping", "chinese": "去野营"}', 33, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6584, 172, '{"english": "hurt my foot", "chinese": "伤了我的脚"}', 34, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6585, 172, '{"english": "went fishing", "chinese": "去钓鱼"}', 35, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6586, 172, '{"english": "Listen, answer and write", "chinese": "听一听，答一答，写一写"}', 36, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6587, 172, '{"english": "What did they do yesterday?", "chinese": "他们昨天做了什么？"}', 37, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6588, 172, '{"english": "I went camping yesterday and hurt my foot.", "chinese": "我昨天去野营了，伤了我的脚。"}', 38, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6589, 172, '{"english": "Yesterday was my twelfth birthday.", "chinese": "昨天是我的十二岁生日。"}', 39, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6590, 172, '{"english": "I got a new bike and  I rode it for the whole day.", "chinese": "我得到了一辆新自行车，我骑了它一整天。"}', 40, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6591, 172, '{"english": "Mr Guo is my father''s friend.", "chinese": "郭先生是我爸爸的朋友。"}', 41, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6592, 172, '{"english": "Yesterday my father and Mr Guo went fishing and rode horses.", "chinese": "昨天我爸爸和郭先生去钓鱼骑马了。"}', 42, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6593, 172, '{"english": "Discuss with your partner.", "chinese": "和你的同伴讨论。"}', 43, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6594, 172, '{"english": "How did Wu Binbin meet Max? What will happen next?", "chinese": "吴斌斌是如何遇见麦克斯的？接下来会发生什么？"}', 44, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6595, 172, '{"english": "What''s your name? How about ''Max''?", "chinese": "你叫什么名字？叫“麦克斯”如何？"}', 45, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6596, 172, '{"english": "Hello, Max!", "chinese": "你好，麦克斯！"}', 46, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6597, 172, '{"english": "Saturday, April 23rd", "chinese": "星期六，4 月 23 日"}', 47, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6598, 172, '{"english": "Today was a sunny day.", "chinese": "今天是一个晴朗的日子。"}', 48, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6599, 172, '{"english": "In the morning, we rode a bike for three people.", "chinese": "早上，我们骑了三人自行车。"}', 49, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6600, 172, '{"english": "Max sat in a basket on the front of the bike.", "chinese": "麦克斯坐在自行车前的篮筐里。"}', 50, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6601, 172, '{"english": "That was fun! We took pictures of the beautiful countryside.", "chinese": "那太有趣了！我们拍了美丽乡村的照片。"}', 51, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6602, 172, '{"english": "We bought some gifts and ate some delicious food.", "chinese": "我们买了一些礼物，吃了一些美味的食物。"}', 52, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6603, 172, '{"english": "In the afternoon, Mum ate some bad fruit and didn''t feel well.", "chinese": "下午，妈妈吃了一些坏水果，感到不舒服。"}', 53, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6604, 172, '{"english": "So we stayed in the hotel.", "chinese": "所以我们待在旅馆里。"}', 54, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6605, 172, '{"english": "Dad and I wanted to make her happy.", "chinese": "我和爸爸想要让她开心。"}', 55, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6606, 172, '{"english": "We dressed up and made a funny play.", "chinese": "我们装扮起来，表演了一个有趣的节目。"}', 56, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6607, 172, '{"english": "Robin played the part of a dog. He was so cute.", "chinese": "罗宾扮演了一只狗的角色。他太可爱了。"}', 57, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6608, 172, '{"english": "Max liked him so much. He jumped on him and licked him.", "chinese": "麦克斯很喜欢他。它跳到罗宾身上舔他。"}', 58, '2026-02-05 04:02:59', '2026-02-05 04:02:59');
INSERT INTO "course_content" VALUES (6609, 172, '{"english": "Of course, Robin didn''t like it. We laughed and laughed.", "chinese": "当然，罗宾不喜欢。我们笑了又笑。"}', 59, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6610, 172, '{"english": "It was a bad day but also a good day!", "chinese": "这是糟糕的一天，但也是美好的一天！"}', 60, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6611, 172, '{"english": "Number the pictures.", "chinese": "给图片编号。"}', 61, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6612, 172, '{"english": "What happened to Wu Binbin''s family?", "chinese": "吴斌斌的家人发生了什么？"}', 62, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6613, 172, '{"english": "Bad:", "chinese": "令人不快的："}', 63, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6614, 172, '{"english": "Good:", "chinese": "好的："}', 64, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6615, 172, '{"english": "Now write about your bad but good day.", "chinese": "现在写下你糟糕而又美好的一天。"}', 65, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6616, 172, '{"english": "Today was a bad but good day for me.", "chinese": "今天对我来说是糟糕而又美好的一天。"}', 66, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6617, 172, '{"english": "First, it was a bad day.", "chinese": "首先，这是糟糕的一天。"}', 67, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6618, 172, '{"english": "But what did I do then?", "chinese": "但我后来做了什么？"}', 68, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6619, 172, '{"english": "So it was also a good day.", "chinese": "所以这也是美好的一天。"}', 69, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6620, 172, '{"english": "As the saying goes, ''Bad luck often brings good luck.''", "chinese": "俗话说：“塞翁失马焉知非福。”"}', 70, '2026-02-05 04:03:00', '2026-02-05 04:03:00');
INSERT INTO "course_content" VALUES (6621, 172, '{"english": "Let''s check", "chinese": "让我们查一查"}', 71, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6622, 172, '{"english": "Listen and write T(true) or F(false).", "chinese": "听一听，判断正（T）误（F）。"}', 72, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6623, 172, '{"english": "1. —Where did you go last weekend, Mike?", "chinese": "1. ——迈克，上周末你去哪儿了？"}', 73, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6624, 172, '{"english": "—I went to Hailar.", "chinese": "——我去了海拉尔。"}', 74, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6625, 172, '{"english": "—What did you do?", "chinese": "——你做了什么？"}', 75, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6626, 172, '{"english": "—I rode a horse. It was very exciting!", "chinese": "——我骑马了。非常刺激。"}', 76, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6627, 172, '{"english": "2. —What did you do last weekend. Sarah?", "chinese": "2. ——萨拉，上周末你做了什么？"}', 77, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6628, 172, '{"english": "—I visited a museum.", "chinese": "——我参观了博物馆。"}', 78, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6629, 172, '{"english": "—Did you have fun?", "chinese": "——你玩得开心吗？"}', 79, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6630, 172, '{"english": "—Yes. It was great!", "chinese": "——是的。博物馆太棒了！"}', 80, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6631, 172, '{"english": "3. —Hey,you came early today, Amy.", "chinese": "3. ——嘿，艾米，你今天来得很早。"}', 81, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6632, 172, '{"english": "—Yes. I didn''t walk to school today.", "chinese": "——对。我今天没走路来上学。"}', 82, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6633, 172, '{"english": "—How did you get here?", "chinese": "——你怎么来的？"}', 83, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6634, 172, '{"english": "—I came by car.", "chinese": "——我是坐小汽车来的。"}', 84, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6635, 172, '{"english": "I hurt my foot yesterday, so my father brought me.", "chinese": "昨天我的脚受伤了，所以我爸爸把我送来了。"}', 85, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6636, 172, '{"english": "4. —Where did you go over your winter holiday,Zhang Peng?", "chinese": "4. ——张鹏，你寒假去了哪里？"}', 86, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6637, 172, '{"english": "—I went to Harbin.", "chinese": "——我去了哈尔滨。"}', 87, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6638, 172, '{"english": "—Who did you go with?", "chinese": "——你和谁一起去的？"}', 88, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6639, 172, '{"english": "—I went with my uncle.", "chinese": "——我和叔叔一起去的。"}', 89, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6640, 172, '{"english": "—What did you do there?", "chinese": "——你们在那里做了什么？"}', 90, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6641, 172, '{"english": "—We took many photos.", "chinese": "——我们拍了很多照片。"}', 91, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6642, 172, '{"english": "Listen again and answer the questions.", "chinese": "再听一遍，回答问题。"}', 92, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6643, 172, '{"english": "1. What did Mike do last weekend?", "chinese": "1. 迈克上周末做了什么？"}', 93, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6644, 172, '{"english": "2. Why did Sarah think her weekend was great?", "chinese": "2. 为什么萨拉觉得她的周末很棒？"}', 94, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6645, 172, '{"english": "3. Why did Amy go to school by car today?", "chinese": "3. 艾米今天为什么乘车上学？"}', 95, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6646, 172, '{"english": "4. What did Zhang Peng do in Harbin?", "chinese": "4. 张鹏在哈尔滨做了什么？"}', 96, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6647, 172, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 97, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6648, 172, '{"english": "Look at the pictures.", "chinese": "看这些图片。"}', 98, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6649, 172, '{"english": "Choose words to fill in the blanks.", "chinese": "选择单词填空。"}', 99, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6650, 172, '{"english": "am/is → was  are → were", "chinese": "是是"}', 100, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6651, 172, '{"english": "eat → ate  drink → drank  run → ran", "chinese": "吃 喝 跑"}', 101, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6652, 172, '{"english": "There _______ lots of dinosaurs many years ago.", "chinese": "很多年前 _______ 很多恐龙。"}', 102, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6653, 172, '{"english": "Some of them _______ plants.", "chinese": "其中一些 _______ 植物。"}', 103, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6654, 172, '{"english": "Some of them _______ faster,", "chinese": "它们中的一些 _______ 速度更快，"}', 104, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6655, 172, '{"english": "so they could eat other smaller dinosaurs.", "chinese": "所以它们可以吃其他较小的恐龙。"}', 105, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6656, 172, '{"english": "But we can only see dinosaurs in museums now.", "chinese": "但我们现在只能在博物馆里看到恐龙。"}', 106, '2026-02-05 04:03:01', '2026-02-05 04:03:01');
INSERT INTO "course_content" VALUES (6657, 173, '{"english": "A. Let''s try", "chinese": "A. 让我们试一试"}', 1, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6658, 173, '{"english": "Today, there is a guest visiting the school.", "chinese": "今天，有一位客人要来参观学校。"}', 2, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6659, 173, '{"english": "Listen and tick or cross.", "chinese": "听录音，判断正误。"}', 3, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6660, 173, '{"english": "—Children, please welcome Wu Binbin''s grandfather to the class.", "chinese": "——同学们，请欢迎吴斌斌的爷爷来班级。"}', 4, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6661, 173, '{"english": "—Welcome!", "chinese": "——欢迎！"}', 5, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6662, 173, '{"english": "—Wow! The school is very different from my old school.", "chinese": "——哇！这所学校和我以前的学校很不一样。"}', 6, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6663, 173, '{"english": "There were no computers at all before.", "chinese": "以前根本没有电脑。"}', 7, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6664, 173, '{"english": "—Really? How did you learn?", "chinese": "——真的吗？那你们怎么学习？"}', 8, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6665, 173, '{"english": "—We listened to the teachers and read lots of books.", "chinese": "——我们听老师讲课，读很多书。"}', 9, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6666, 173, '{"english": "Let''s talk", "chinese": "让我们说一说"}', 10, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6667, 173, '{"english": "Wow, a library!", "chinese": "哇，图书馆！"}', 11, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6668, 173, '{"english": "There was no library in my old school.", "chinese": "我以前的学校里没有图书馆。"}', 12, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6669, 173, '{"english": "Tell us about your school, please.", "chinese": "请给我们讲讲您的学校吧。"}', 13, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6670, 173, '{"english": "There was only one small building on a hill.", "chinese": "那时只有一座在山上的小建筑。"}', 14, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6671, 173, '{"english": "Could you see stars at night?", "chinese": "您夜晚能看见星星吗？"}', 15, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6672, 173, '{"english": "Yes, I liked the stars.", "chinese": "是的，我喜欢星星。"}', 16, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6673, 173, '{"english": "Me too. One day I''m going to visit the moon.", "chinese": "我也是。有一天我要去参观月球。"}', 17, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6674, 173, '{"english": "The Americans took about five days to get there in 1969.", "chinese": "1969 年，美国人花了大约五天的时间到达了那里。"}', 18, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6675, 173, '{"english": "How do you know that?", "chinese": "你怎么知道的？"}', 19, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6676, 173, '{"english": "Easy, I looked it up on the Internet.", "chinese": "简单，我在网上查阅的。"}', 20, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6677, 173, '{"english": "Ah! There were no computers or Internet in my time.", "chinese": "啊！我那时候没有电脑也没有网络。"}', 21, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6678, 173, '{"english": "What was Grandpa''s school like?", "chinese": "爷爷的学校什么样？"}', 22, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6679, 173, '{"english": "What was your school like five years ago?", "chinese": "五年前你的学校什么样？"}', 23, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6680, 173, '{"english": "What is it like now? Draw and talk.", "chinese": "现在什么样？画一画，说一说。"}', 24, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6681, 173, '{"english": "5 years ago", "chinese": "5 年前"}', 25, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6682, 173, '{"english": "Now", "chinese": "现在"}', 26, '2026-02-05 04:03:03', '2026-02-05 04:03:03');
INSERT INTO "course_content" VALUES (6683, 173, '{"english": "There was ... There were ...", "chinese": "有⋯⋯ 有⋯⋯"}', 27, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6684, 173, '{"english": "There is ... There are ...", "chinese": "有⋯⋯ 有⋯⋯"}', 28, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6685, 173, '{"english": "Let''s learn", "chinese": "让我们学一学"}', 29, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6686, 173, '{"english": "There was no gym in my school thirty years ago.", "chinese": "三十年前，我的学校里没有体育馆。"}', 30, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6687, 173, '{"english": "Now there''s a new one in our school.", "chinese": "现在我们学校有一个新的。"}', 31, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6688, 173, '{"english": "dining hall", "chinese": "饭厅"}', 32, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6689, 173, '{"english": "gym", "chinese": "体育馆"}', 33, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6690, 173, '{"english": "grass", "chinese": "草坪"}', 34, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6691, 173, '{"english": "years ago, months ago, last year, last month", "chinese": "年前，月前，去年，上月"}', 35, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6692, 173, '{"english": "Find the mistakes", "chinese": "找出错误"}', 36, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6693, 173, '{"english": "In the Tang dynasty ...", "chinese": "在唐代⋯⋯"}', 37, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6694, 173, '{"english": "At that time, there were no gyms.", "chinese": "当时，那里没有健身房。"}', 38, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6695, 173, '{"english": "People didn''t go by bus. People couldn''t use the Internet.", "chinese": "人们没有公共汽车出行。人们不能使用网络。"}', 39, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6696, 173, '{"english": "Read and write", "chinese": "读一读，写一写"}', 40, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6697, 173, '{"english": "Tell your partner.", "chinese": "告诉你的搭档。"}', 41, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6698, 173, '{"english": "1. What animal can run very fast?", "chinese": "1. 什么动物可以跑得很快？"}', 42, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6699, 173, '{"english": "2. What makes you feel worried?", "chinese": "2. 什么让你感到担心？"}', 43, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6700, 173, '{"english": "What a dream!", "chinese": "多么有趣的一场梦啊！"}', 44, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6701, 173, '{"english": "Wu Binbin had a race with his father and Max.", "chinese": "吴斌斌和他的爸爸还有麦克斯进行了一场赛跑。"}', 45, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6702, 173, '{"english": "There were many people there.", "chinese": "那里有很多人。"}', 46, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6703, 173, '{"english": "His father ran very fast, but Wu Binbin could not.", "chinese": "他的爸爸跑得非常快，但吴斌斌不能。"}', 47, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6704, 173, '{"english": "There was nothing he could do. He was so worried.", "chinese": "他没什么可以做的事情。他是如此担心。"}', 48, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6705, 173, '{"english": "''I could run fast at school,'' he thought.", "chinese": "“我在学校可以跑得很快，”他想。"}', 49, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6706, 173, '{"english": "''Why am I so slow now?''", "chinese": "“为什么我现在跑得这么慢？”"}', 50, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6707, 173, '{"english": "Then Robin said, ''Drink this! '' and gave Wu Binbin some water.", "chinese": "然后罗宾说：“喝下这个！” 并给了吴斌斌一些水。"}', 51, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6708, 173, '{"english": "Wu Binbin drank it and suddenly he felt good.", "chinese": "吴斌斌喝了它，突然他感觉很好。"}', 52, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6709, 173, '{"english": "He could run fast again.", "chinese": "他又可以跑得很快了。"}', 53, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6710, 173, '{"english": "There was a second race.", "chinese": "第二场比赛来了。"}', 54, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6711, 173, '{"english": "There were many animals in that race.", "chinese": "在那场比赛里有很多动物。"}', 55, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6712, 173, '{"english": "Wu Binbin ran like a cheetah. He could win the race!", "chinese": "吴斌斌跑得像只猎豹一样。他可以赢得比赛！"}', 56, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6713, 173, '{"english": "But suddenly he tripped and fell. Then he woke up.", "chinese": "但是他突然绊了一下摔倒了。然后他醒了。"}', 57, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6714, 173, '{"english": "He was in bed. It was all a dream!", "chinese": "他在床上。这完全是一场梦！"}', 58, '2026-02-05 04:03:04', '2026-02-05 04:03:04');
INSERT INTO "course_content" VALUES (6715, 173, '{"english": "Number the pictures.", "chinese": "给图片编号。"}', 59, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6716, 173, '{"english": "Wu Binbin is telling his mother about the dream.", "chinese": "吴斌斌正在给他妈妈讲梦。"}', 60, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6717, 173, '{"english": "Listen and fill in the blanks.", "chinese": "听录音，填空。"}', 61, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6718, 173, '{"english": "Mum, I had an interesting dream last night.", "chinese": "妈妈，我昨晚做了一个有趣的梦。"}', 62, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6719, 173, '{"english": "What did you dream about?", "chinese": "你梦到了什么？"}', 63, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6720, 173, '{"english": "I had a race with Dad and Max, but I couldn''t run fast.", "chinese": "我和爸爸还有麦克斯进行赛跑了，但我跑不快。"}', 64, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6721, 173, '{"english": "What happened then?", "chinese": "然后发生了什么？"}', 65, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6722, 173, '{"english": "Robin gave me some water.", "chinese": "罗宾给了我一些水。"}', 66, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6723, 173, '{"english": "I drank it and then could run very fast.", "chinese": "我喝了它，然后就可以跑得非常快了。"}', 67, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6724, 173, '{"english": "Suddenly I tripped and fell. Then I woke up.", "chinese": "突然我绊了一下摔倒了。然后我醒了。"}', 68, '2026-02-05 04:03:05', '2026-02-05 04:03:05');
INSERT INTO "course_content" VALUES (6725, 173, '{"english": "What a dream!", "chinese": "多么有趣的一场梦啊！"}', 69, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6726, 173, '{"english": "Did you have an interesting dream?", "chinese": "你做过有趣的梦吗？"}', 70, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6727, 173, '{"english": "Tell your dream to your partner. Then write several sentences about it.", "chinese": "把你的梦告诉你的搭档。然后写几个关于它的句子。"}', 71, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6728, 173, '{"english": "I had a dream last night.", "chinese": "我昨晚做了一个梦。"}', 72, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6729, 173, '{"english": "In my dream, I ...", "chinese": "在我的梦里，我⋯⋯"}', 73, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6730, 173, '{"english": "What a dream!", "chinese": "多么有趣的一场梦啊！"}', 74, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6731, 173, '{"english": "Let''s check", "chinese": "让我们查一查"}', 75, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6732, 173, '{"english": "Listen and number.", "chinese": "听一听并排序。"}', 76, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6733, 173, '{"english": "Many years ago, I went to this school.", "chinese": "很多年前，我上过这所学校。"}', 77, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6734, 173, '{"english": "I went to school by bike. I loved cycling.", "chinese": "我骑自行车上学。我喜欢骑自行车。"}', 78, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6735, 173, '{"english": "Nowadays, many students go by bus or car.", "chinese": "现在，许多学生乘公共汽车或汽车。"}', 79, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6736, 173, '{"english": "We didn''t have computer games then or computers.", "chinese": "那时候我们没有电脑游戏或电脑。"}', 80, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6737, 173, '{"english": "So we often play badminton in the summer and went ice-skating in the winter.", "chinese": "所以我们经常在夏天打羽毛球，在冬天滑冰。"}', 81, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6738, 173, '{"english": "We had a great time.", "chinese": "我们玩得很开心。"}', 82, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6739, 173, '{"english": "After school, I often went to the park and read under a tree. It was so beautiful there.", "chinese": "放学后，我经常去公园，在树下看书。那里太美了。"}', 83, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6740, 173, '{"english": "Cross out the words you didn''t hear.", "chinese": "划掉你没听到的单词。"}', 84, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6741, 173, '{"english": "gym, cycling, dining hall, ice-skating, grass, badminton", "chinese": "体育馆，骑自行车，饭厅，滑冰，草坪，羽毛球运动"}', 85, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6742, 173, '{"english": "Let''s wrap it up", "chinese": "让我们总结一下"}', 86, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6743, 173, '{"english": "Changes are all around us. Talk about the changes below.", "chinese": "变化无处不在。谈谈下面的变化。"}', 87, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6744, 173, '{"english": "It was an egg.  Now ...", "chinese": "它以前是一个鸡蛋。 现在⋯⋯"}', 88, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6745, 173, '{"english": "It was raining.  Now ...", "chinese": "刚才下雨了。 现在⋯⋯"}', 89, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6746, 173, '{"english": "In summer, the tree was green. Now ...", "chinese": "夏天，树是绿色的。现在⋯⋯"}', 90, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6747, 173, '{"english": "Chen Jie was short.", "chinese": "陈洁以前个子矮。"}', 91, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6748, 173, '{"english": "Now she is 1.5 metres tall.", "chinese": "现在她身高 1.5 米。"}', 92, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6749, 173, '{"english": "There was a building before. Now ...", "chinese": "以前这有一座大楼。现在⋯⋯"}', 93, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6750, 173, '{"english": "The cat was on the chair. Now ...", "chinese": "猫刚刚在椅子上。现在⋯⋯"}', 94, '2026-02-05 04:03:06', '2026-02-05 04:03:06');
INSERT INTO "course_content" VALUES (6751, 174, '{"english": "Recycle", "chinese": "复习"}', 1, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
