INSERT INTO "course_content" VALUES (6753, 174, '{"english": "Mike visited a farm.", "chinese": "迈克参观了一个农场。"}', 3, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6754, 174, '{"english": "What can you see on the farm?", "chinese": "你在农场能看到什么？"}', 4, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
