INSERT INTO "course_content" VALUES (6759, 174, '{"english": "umbrella", "chinese": "雨伞"}', 9, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6760, 174, '{"english": "apples", "chinese": "苹果"}', 10, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6761, 174, '{"english": "horses", "chinese": "马"}', 11, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6762, 174, '{"english": "tomatoes", "chinese": "西红柿"}', 12, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6763, 174, '{"english": "What else can you see?", "chinese": "你还能看到什么？"}', 13, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6764, 174, '{"english": "Can you name the groups of words?", "chinese": "你能给这几组词取名吗？"}', 14, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6765, 174, '{"english": "Fruit", "chinese": "水果"}', 15, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
