INSERT INTO "course_content" VALUES (6768, 174, '{"english": "egg", "chinese": "鸡蛋"}', 18, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6769, 174, '{"english": "cake", "chinese": "蛋糕"}', 19, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6770, 174, '{"english": "jacket", "chinese": "夹克"}', 20, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6771, 174, '{"english": "shoes", "chinese": "鞋"}', 21, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6772, 174, '{"english": "horse", "chinese": "马"}', 22, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
