INSERT INTO "course_content" VALUES (6774, 174, '{"english": "Can you think of one more word group?", "chinese": "你能再想一组词吗？"}', 24, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6775, 174, '{"english": "Can you add more words to the groups?", "chinese": "你能在组里多加些词吗？"}', 25, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6776, 174, '{"english": "Mike''s happy days", "chinese": "迈克的快乐日子"}', 26, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6777, 174, '{"english": "Day 2 Farmers'' market", "chinese": "第 2 天 农贸市场"}', 27, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6778, 174, '{"english": "Mrs Booth and Bill want to go shopping.", "chinese": "布斯太太和比尔想去购物。"}', 28, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6779, 174, '{"english": "Help them finish their mind map.", "chinese": "帮助他们完成他们的思维导图。"}', 29, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6780, 174, '{"english": "shopping", "chinese": "购物"}', 30, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6781, 174, '{"english": "When?", "chinese": "什么时候？"}', 31, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6782, 174, '{"english": "morning", "chinese": "上午"}', 32, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6783, 174, '{"english": "With who?", "chinese": "和谁一起？"}', 33, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6784, 174, '{"english": "shopping list", "chinese": "购物清单"}', 34, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6785, 174, '{"english": "How much?", "chinese": "多少钱？"}', 35, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
INSERT INTO "course_content" VALUES (6786, 174, '{"english": "How can we get there?", "chinese": "我们怎么去那里？"}', 36, '2026-02-05 04:03:08', '2026-02-05 04:03:08');
