INSERT INTO "course_content" VALUES (6788, 174, '{"english": "farmers''market", "chinese": "农贸市场"}', 38, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6789, 174, '{"english": "Now make a new word map with your partner.", "chinese": "现在和你的搭档做一个新的单词地图。"}', 39, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6790, 174, '{"english": "Mike met new friends. Help him talk about them.", "chinese": "迈克结识了新朋友。帮他谈谈他们。"}', 40, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6791, 174, '{"english": "short", "chinese": "矮的"}', 41, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6792, 174, '{"english": "young", "chinese": "年轻的"}', 42, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6793, 174, '{"english": "a red bag", "chinese": "一个红色的包"}', 43, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6794, 174, '{"english": "white shoes", "chinese": "白色的鞋"}', 44, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6795, 174, '{"english": "tall", "chinese": "高的"}', 45, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
