INSERT INTO "course_content" VALUES (6798, 174, '{"english": "Bill is my new friend. He''s short and heavy.", "chinese": "比尔是我的新朋友。他又矮又重。"}', 48, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
