INSERT INTO "course_content" VALUES (6801, 174, '{"english": "Day 3 Life on the farm", "chinese": "第 3 天 农场生活"}', 51, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6802, 174, '{"english": "These are things people often do on the farm.", "chinese": "这些是人们在农场经常做的事情。"}', 52, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6803, 174, '{"english": "Circle the words in the puzzle.", "chinese": "圈出拼图中的单词。"}', 53, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6804, 174, '{"english": "Write down what he, she or they do every day.", "chinese": "写下他、她或他们每天做什么。"}', 54, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6805, 174, '{"english": "He goes fishing.", "chinese": "他去钓鱼。"}', 55, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6806, 174, '{"english": "She does the cleaning.", "chinese": "她打扫卫生。"}', 56, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6807, 174, '{"english": "He plays music.", "chinese": "他演奏音乐。"}', 57, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6808, 174, '{"english": "They have some juice.", "chinese": "他们喝一些果汁。"}', 58, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6809, 174, '{"english": "These people are having fun on the farm.", "chinese": "这些人在农场玩得很开心。"}', 59, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6810, 174, '{"english": "Write down three sentences about what they are doing.", "chinese": "写下关于他们正在做什么的三句话。"}', 60, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
INSERT INTO "course_content" VALUES (6811, 174, '{"english": "Bill is playing ping-pong.", "chinese": "比尔正在打乒乓球。"}', 61, '2026-02-05 04:03:09', '2026-02-05 04:03:09');
