INSERT INTO "course_content" VALUES (6813, 175, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6814, 175, '{"english": "My small cat", "chinese": "我的小猫"}', 3, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6815, 175, '{"english": "My small cat, my small cat,  My small cat is smaller than yours.", "chinese": "我的小猫，我的小猫， 我的小猫比你的小。"}', 4, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6816, 175, '{"english": "He''s smaller and shorter and younger than yours.", "chinese": "它比你的猫更小、更矮、更年轻。"}', 5, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6817, 175, '{"english": "My small cat.", "chinese": "我的小猫。"}', 6, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6818, 175, '{"english": "My big dog, my big dog,  My big dog is bigger than yours.", "chinese": "我的大狗，我的大狗， 我的大狗比你的大。"}', 7, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6819, 175, '{"english": "He''s bigger and longer and stronger than yours.  My big dog.", "chinese": "他比你的狗更大、更高、更强壮。 我的大狗。"}', 8, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6820, 175, '{"english": "Unit 2", "chinese": "第 2 单元"}', 9, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6821, 175, '{"english": "Last weekend", "chinese": "上周末"}', 10, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6822, 175, '{"english": "Last weekend I went to the zoo.", "chinese": "上周末我去了动物园。"}', 11, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6823, 175, '{"english": "What did you do last weekend?", "chinese": "你上周末做了什么？"}', 12, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6824, 175, '{"english": "I saw a film and played ping-pong.  What did you do last weekend?", "chinese": "我看了一场电影，并且打乒乓球了。 你上周末做了什么？"}', 13, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6825, 175, '{"english": "Last night I watched TV.  What did you do last night?", "chinese": "我昨晚看了电视。 你昨晚做了什么？"}', 14, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6826, 175, '{"english": "I stayed at home and read a book.", "chinese": "我待在家里看书。"}', 15, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6827, 175, '{"english": "What did you do last night?", "chinese": "你昨晚做了什么？"}', 16, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
