INSERT INTO "course_content" VALUES (6830, 175, '{"english": "Where did you go on your holiday, holiday, holiday?", "chinese": "你假期去哪里了？"}', 19, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6831, 175, '{"english": "Did you swim? Did you shop?  What did you do?", "chinese": "你去游泳了吗？你去购物了吗？ 你做了什么？"}', 20, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6832, 175, '{"english": "I went swimming in the sea, in the sea, in the sea.", "chinese": "我去海里游泳了。"}', 21, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
INSERT INTO "course_content" VALUES (6833, 175, '{"english": "I went shopping near the sea.", "chinese": "我在海边购物了。"}', 22, '2026-02-05 04:03:11', '2026-02-05 04:03:11');
