INSERT INTO "course_content" VALUES (6927, 177, '{"english": "gym", "chinese": "体育馆"}', 36, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6928, 177, '{"english": "had", "chinese": "（have 的过去式）患病；得病"}', 37, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6929, 177, '{"english": "had a cold", "chinese": "感冒"}', 38, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
