INSERT INTO "course_content" VALUES (6936, 177, '{"english": "kilogram", "chinese": "千克；公斤"}', 45, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6937, 177, '{"english": "lamp", "chinese": "台灯"}', 46, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6938, 177, '{"english": "last", "chinese": "最近的；上一个"}', 47, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6939, 177, '{"english": "laughed", "chinese": "（laugh 的过去式）笑"}', 48, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6940, 177, '{"english": "licked", "chinese": "（lick 的过去式）舔"}', 49, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6941, 177, '{"english": "longer", "chinese": "（long 的比较级）更长的"}', 50, '2026-02-05 04:03:16', '2026-02-05 04:03:16');
INSERT INTO "course_content" VALUES (6942, 177, '{"english": "look up", "chinese": "（在词典中或通过电脑）查阅"}', 51, '2026-02-05 04:03:17', '2026-02-05 04:03:17');
