INSERT INTO "course_content" VALUES (6945, 177, '{"english": "magazine", "chinese": "杂志"}', 54, '2026-02-05 04:03:17', '2026-02-05 04:03:17');
INSERT INTO "course_content" VALUES (6946, 177, '{"english": "metre", "chinese": "米（美式英语：meter）"}', 55, '2026-02-05 04:03:17', '2026-02-05 04:03:17');
INSERT INTO "course_content" VALUES (6947, 178, '{"english": "Useful expressions", "chinese": "常用表达法"}', 1, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6948, 178, '{"english": "Unit 1", "chinese": "第 1 单元"}', 2, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6949, 178, '{"english": "That''s the tallest dinosaur in this hall.", "chinese": "那是这个厅里最高的恐龙。"}', 3, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6950, 178, '{"english": "It''s taller than both of us together.", "chinese": "它比我俩加起来还高。"}', 4, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6951, 178, '{"english": "How tall are you?", "chinese": "你有多高？"}', 5, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6952, 178, '{"english": "I''m 1.65 metres.", "chinese": "我身高 1.65 米。"}', 6, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6953, 178, '{"english": "What size are you shoes, Mike?", "chinese": "迈克，你穿多大号的鞋？"}', 7, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6954, 178, '{"english": "Your feet are bigger than mine.", "chinese": "你的脚比我的大。"}', 8, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6955, 178, '{"english": "My shoes are size 37.", "chinese": "我穿 37 号的鞋。"}', 9, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6956, 178, '{"english": "How heavy are you?", "chinese": "你体重多少？"}', 10, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6957, 178, '{"english": "I''m 48 kilograms.", "chinese": "我体重 48 公斤。"}', 11, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6958, 178, '{"english": "Unit 2", "chinese": "第 2 单元"}', 12, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6959, 178, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 13, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6960, 178, '{"english": "It was good, thank you.", "chinese": "很好，谢谢。"}', 14, '2026-02-05 04:03:18', '2026-02-05 04:03:18');
INSERT INTO "course_content" VALUES (6961, 179, '{"english": "Unit 3", "chinese": "第 3 单元"}', 1, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6962, 179, '{"english": "What happened?", "chinese": "怎么了？"}', 2, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6963, 179, '{"english": "Are you all right?", "chinese": "你还好吧？"}', 3, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6964, 179, '{"english": "I''m OK now.", "chinese": "我现在没事了。"}', 4, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6965, 179, '{"english": "Where did you go?", "chinese": "你去哪儿了？"}', 5, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6966, 179, '{"english": "It looks like a mule!", "chinese": "它看起来像头骡子！"}', 6, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6967, 179, '{"english": "Did you go to Turpan?", "chinese": "你们去吐鲁番了吗？"}', 7, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6968, 179, '{"english": "Yes, we did.", "chinese": "是的，去了。"}', 8, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6969, 179, '{"english": "How did you go there?", "chinese": "你们怎么去的？"}', 9, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6970, 179, '{"english": "We went there by plane.", "chinese": "我们坐飞机去的。"}', 10, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6971, 179, '{"english": "Sounds great!", "chinese": "听上去不错！"}', 11, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6972, 179, '{"english": "Unit 4", "chinese": "第 4 单元"}', 12, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6973, 179, '{"english": "There was no library in my old school.", "chinese": "我以前的学校里没有图书馆。"}', 13, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6974, 179, '{"english": "Tell us about your school, please.", "chinese": "请给我们讲讲您的学校吧。"}', 14, '2026-02-05 04:03:19', '2026-02-05 04:03:19');
INSERT INTO "course_content" VALUES (6975, 179, '{"english": "How do you know that?", "chinese": "你怎么知道的？"}', 15, '2026-02-05 04:03:20', '2026-02-05 04:03:20');
INSERT INTO "course_content" VALUES (6976, 180, '{"english": "Short plays", "chinese": "短剧"}', 1, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6977, 180, '{"english": "The three little pigs", "chinese": "三只小猪"}', 2, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6978, 180, '{"english": "Once upon a time, there were three little pigs, named Pete, Pat and Paul.", "chinese": "从前，有三只小猪，他们分别叫皮特、帕特和保罗。"}', 3, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6979, 180, '{"english": "They were brothers.", "chinese": "他们是兄弟。"}', 4, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6980, 180, '{"english": "One day, they left their mother''s house.", "chinese": "一天，他们离开了妈妈的家。"}', 5, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6981, 180, '{"english": "The winter was coming. They wanted to build a new house.", "chinese": "冬天要来了。他们想要造一栋新房子。"}', 6, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6982, 180, '{"english": "One day, Pete met a man. He had straw to sell.", "chinese": "一天，皮特遇到了一个人。他卖稻草。"}', 7, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6983, 180, '{"english": "Can I please buy your straw?", "chinese": "我能买你的稻草吗？"}', 8, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6984, 180, '{"english": "Sure. What for?", "chinese": "当然可以。你要做什么用？"}', 9, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6985, 180, '{"english": "I am going to build a house with it.", "chinese": "我要用它盖房子。"}', 10, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6986, 180, '{"english": "Straw is not strong.", "chinese": "稻草不够结实。"}', 11, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6987, 180, '{"english": "That''s OK. I need a house before winter.", "chinese": "没关系。冬天来临之前我需要一栋房子。"}', 12, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6988, 180, '{"english": "So Pete built his house of straw.", "chinese": "于是皮特用稻草建了他的房子。"}', 13, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6989, 180, '{"english": "The next day, Pat met a man. He sold sticks.", "chinese": "第二天，帕特遇到了一个人。他卖木棍。"}', 14, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6990, 180, '{"english": "Can I please buy your sticks?", "chinese": "我可以买你的木棍吗？"}', 15, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6991, 180, '{"english": "Sure. What for?", "chinese": "当然可以。你要做什么用？"}', 16, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6992, 180, '{"english": "I am going to build a house with them.", "chinese": "我要用它们建一栋房子。"}', 17, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6993, 180, '{"english": "Sticks are not strong.", "chinese": "树枝不够结实。"}', 18, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6994, 180, '{"english": "That''s OK. I need a house before winter.", "chinese": "没关系。冬天来临之前我需要一栋房子。"}', 19, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6995, 180, '{"english": "So Pat built his house of sticks.", "chinese": "于是帕特用木棍建造了他的房子。"}', 20, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6996, 180, '{"english": "Then Paul met a man. He sold bricks.", "chinese": "然后保罗遇到了一个人。他卖砖块。"}', 21, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6997, 180, '{"english": "Can I please buy your bricks?", "chinese": "我可以买你的砖块吗？"}', 22, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6998, 180, '{"english": "Sure. What for?", "chinese": "当然可以。你要做什么用？"}', 23, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (6999, 180, '{"english": "I am going to build a house with them.", "chinese": "我打算用它们建一栋房子。"}', 24, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7000, 180, '{"english": "Great! Bricks are very strong.", "chinese": "很好！砖块非常结实。"}', 25, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7001, 180, '{"english": "It is hard work to build a house of bricks.", "chinese": "用砖块建造房子是项艰苦的工作。"}', 26, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7002, 180, '{"english": "Bricks are very heavy.", "chinese": "砖块非常重。"}', 27, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7003, 180, '{"english": "Bricks are heavier than straw and sticks.", "chinese": "砖块比稻草和木棍重。"}', 28, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7004, 180, '{"english": "Brick houses are stronger than straw houses and stick houses.", "chinese": "砖块房比稻草房和木棍房都要结实。"}', 29, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7005, 180, '{"english": "The man sold Paul the bricks.", "chinese": "那人把砖块卖给了保罗。"}', 30, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7006, 180, '{"english": "Paul built his house of bricks.", "chinese": "保罗用砖块建造了他的房子。"}', 31, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7007, 180, '{"english": "Pat built his house of sticks. Pete built his house of straw.", "chinese": "帕特用木棍建造了他的房子。皮特用稻草建造了他的房子。"}', 32, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7008, 180, '{"english": "Then one day, a hungry wolf came out of the woods.", "chinese": "然后有一天，一只饿狼从树林里跑出来。"}', 33, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7009, 180, '{"english": "Little Red-Cap picked some flowers for her grandmother.", "chinese": "小红帽为她的外婆采了些花。"}', 34, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7010, 180, '{"english": "The wolf ran to the grandmother''s house. He knocked at the door.", "chinese": "狼向外婆的房子跑去。他敲了敲门。"}', 35, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7011, 180, '{"english": "Who is there?", "chinese": "是谁？"}', 36, '2026-02-05 04:03:21', '2026-02-05 04:03:21');
INSERT INTO "course_content" VALUES (7012, 180, '{"english": "Little Red-Cap. It''s me, Grandmother.", "chinese": "小红帽。是我，外婆。"}', 37, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7013, 180, '{"english": "I have some cake for you. Open the door, please.", "chinese": "我给您带了一些蛋糕。请开门。"}', 38, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7014, 180, '{"english": "I''m in bed. Come in.", "chinese": "我躺在床上。进来吧。"}', 39, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7015, 180, '{"english": "The wolf went into the house.", "chinese": "狼进了屋。"}', 40, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7016, 180, '{"english": "Good morning, Grandmother.", "chinese": "早上好，外婆。"}', 41, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7017, 180, '{"english": "What a strange voice you have, Little Red-Cap.", "chinese": "小红帽，你的声音好奇怪。"}', 42, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7018, 180, '{"english": "I have a cold. My throat is sore.", "chinese": "我感冒了。我的喉咙痛。"}', 43, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
INSERT INTO "course_content" VALUES (7019, 180, '{"english": "I''m sorry.", "chinese": "我很抱歉。"}', 44, '2026-02-05 04:03:22', '2026-02-05 04:03:22');
