INSERT INTO "course_content" VALUES (9009, 498, '{"english": "I can use \"where\" to ask questions.", "chinese": "我会用“where”来问问题。"}', 63, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
INSERT INTO "course_content" VALUES (9010, 498, '{"english": "I can use \"in\", \"on\", \"under\" and \"behind\".", "chinese": "我会用“in”“on”“under”和“behind”。"}', 64, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
