INSERT INTO "course_content" VALUES (9012, 499, '{"english": "Project 1 My puppy", "chinese": "课题1 我的玩偶"}', 1, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
INSERT INTO "course_content" VALUES (9013, 499, '{"english": "Anna has a puppy.", "chinese": "安娜有一个玩偶。"}', 2, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
