INSERT INTO "course_content" VALUES (9015, 499, '{"english": "Where''s my puppy?", "chinese": "我的玩偶在哪里？"}', 4, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
INSERT INTO "course_content" VALUES (9016, 499, '{"english": "It is under the desk.", "chinese": "它在书桌下面。"}', 5, '2026-02-05 04:25:19', '2026-02-05 04:25:19');
