INSERT INTO "course_content" VALUES (9195, 502, '{"english": "Yes, they''re apples.", "chinese": "是的，是苹果。"}', 16, '2026-02-05 04:25:25', '2026-02-05 04:25:25');
INSERT INTO "course_content" VALUES (9196, 502, '{"english": "Are those apples too?", "chinese": "那也是苹果吗？"}', 17, '2026-02-05 04:25:25', '2026-02-05 04:25:25');
