INSERT INTO "course_content" VALUES (10734, 525, '{"english": "Unit 6", "chinese": "第六单元"}', 15, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10735, 525, '{"english": "Look at Su Yang''s gloves, Helen.", "chinese": "快看苏洋的手套，海伦。"}', 16, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10736, 525, '{"english": "They''re so big.", "chinese": "它们这么大。"}', 17, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10737, 525, '{"english": "Whose gloves are these, Su Yang?", "chinese": "这些是谁的手套，苏洋？"}', 18, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10738, 525, '{"english": "They''re my father''s.", "chinese": "它们是我父亲的。"}', 19, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10739, 525, '{"english": "Whose dress is this, Helen?", "chinese": "这是谁的连衣裙，海伦？"}', 20, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10740, 525, '{"english": "It''s my cousin''s.", "chinese": "它是我堂妹的。"}', 21, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10741, 525, '{"english": "It''s so beautiful.", "chinese": "它真漂亮。"}', 22, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10742, 525, '{"english": "Thank you.", "chinese": "谢谢你。"}', 23, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
