INSERT INTO "course_content" VALUES (10747, 525, '{"english": "Tip: Note the \"''s\".", "chinese": "小贴士：注意''s的用法。"}', 28, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10748, 525, '{"english": "See page 59.", "chinese": "详见课本59页。"}', 29, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
