INSERT INTO "course_content" VALUES (10750, 525, '{"english": "Guess and say", "chinese": "猜一猜并说一说"}', 31, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10751, 525, '{"english": "Whose sweater is this?", "chinese": "这是谁的毛衣？"}', 32, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10752, 525, '{"english": "Guess!", "chinese": "快猜猜！"}', 33, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10753, 525, '{"english": "Is it Dan''s?", "chinese": "是丹的吗？"}', 34, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10754, 525, '{"english": "No. You''re wrong.", "chinese": "不是。你猜错了。"}', 35, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10755, 525, '{"english": "Is it Joe''s?", "chinese": "是乔的吗？"}', 36, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10756, 525, '{"english": "Yes. You''re right.", "chinese": "是的。你猜对了。"}', 37, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10757, 525, '{"english": "Unit 6", "chinese": "第六单元"}', 38, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
