INSERT INTO "course_content" VALUES (10759, 525, '{"english": "What''s this?", "chinese": "这是什么？"}', 40, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10760, 525, '{"english": "Look!", "chinese": "快看！"}', 41, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10761, 525, '{"english": "It can move.", "chinese": "它会动。"}', 42, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10762, 525, '{"english": "Is this a ball, Sam?", "chinese": "萨姆，这是一个球吗？"}', 43, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10763, 525, '{"english": "I think so.", "chinese": "我想是。"}', 44, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10764, 525, '{"english": "Let''s play.", "chinese": "我们来玩一玩吧。"}', 45, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10765, 525, '{"english": "Ouch!", "chinese": "哎哟！"}', 46, '2026-02-05 04:26:15', '2026-02-05 04:26:15');
INSERT INTO "course_content" VALUES (10766, 525, '{"english": "What''s the matter?", "chinese": "怎么了？"}', 47, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10767, 525, '{"english": "My hand hurts.", "chinese": "我的手疼。"}', 48, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10768, 525, '{"english": "Hi! Nice to meet you.", "chinese": "你好！很高兴认识你们。"}', 49, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10769, 525, '{"english": "Hi! Nice to meet you too.", "chinese": "你好！我们也很高兴认识你。"}', 50, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
