INSERT INTO "course_content" VALUES (10772, 525, '{"english": "Before eating fish,  Let''s listen to some English.", "chinese": "在吃鱼之前， 我们来听一些英语吧。"}', 53, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
