INSERT INTO "course_content" VALUES (10776, 525, '{"english": "music", "chinese": "音乐"}', 57, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10777, 525, '{"english": "pig", "chinese": "猪"}', 58, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10778, 525, '{"english": "Rhyme time", "chinese": "唱歌谣时间"}', 59, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10779, 525, '{"english": "Whose cake is this?", "chinese": "这是谁的蛋糕？"}', 60, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10780, 525, '{"english": "Oh, Chris!", "chinese": "噢，克里斯！"}', 61, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10781, 525, '{"english": "Oh, Chris!", "chinese": "噢，克里斯！"}', 62, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10782, 525, '{"english": "Whose cake is this?", "chinese": "这是谁的蛋糕？"}', 63, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10783, 525, '{"english": "It''s my cake.", "chinese": "是我的蛋糕。"}', 64, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10784, 525, '{"english": "Let''s eat it by the lake.", "chinese": "咱们到湖边吃蛋糕吧。"}', 65, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10785, 525, '{"english": "Unit 6", "chinese": "第六单元"}', 66, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
