INSERT INTO "course_content" VALUES (10787, 525, '{"english": "Read and write", "chinese": "读一读并写一写"}', 68, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10788, 525, '{"english": "Whose coat is this?", "chinese": "这是谁的外套？"}', 69, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10789, 525, '{"english": "It''s Yang Ling''s.", "chinese": "它是杨凌的。"}', 70, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10790, 525, '{"english": "Whose dress is this?", "chinese": "这是谁的连衣裙？"}', 71, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10791, 525, '{"english": "It''s Helen''s.", "chinese": "它是海伦的。"}', 72, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10792, 525, '{"english": "Whose sweaters are these?", "chinese": "这些是谁的毛衣？"}', 73, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10793, 525, '{"english": "They''re Liu Tao''s.", "chinese": "它们是刘涛的。"}', 74, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10794, 525, '{"english": "Whose shirts are these?", "chinese": "这些是谁的衬衫？"}', 75, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10795, 525, '{"english": "They''re my father''s.", "chinese": "它们是我父亲的。"}', 76, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10796, 525, '{"english": "Whose trousers are these?", "chinese": "这些是谁的裤子？"}', 77, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10797, 525, '{"english": "They''re Su Yang''s.", "chinese": "它们是苏洋的。"}', 78, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10798, 525, '{"english": "Ticking time", "chinese": "打勾时间"}', 79, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10799, 525, '{"english": "I can say and write the names of some clothes.", "chinese": "我会说，并且会写一些衣服的名称。"}', 80, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10800, 525, '{"english": "I can use \"whose\" to ask questions.", "chinese": "我会用“whose”来提问。"}', 81, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10801, 525, '{"english": "I know the sound of the letter \"i\".", "chinese": "我知道字母“i”的发音。"}', 82, '2026-02-05 04:26:16', '2026-02-05 04:26:16');
INSERT INTO "course_content" VALUES (10802, 526, '{"english": "Unit 7  What''s the matter?", "chinese": "第七单元 怎么了？"}', 1, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10803, 526, '{"english": "Story time", "chinese": "讲故事时间"}', 2, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10804, 526, '{"english": "Come and have a pie, Taotao.", "chinese": "快过来吃馅饼，涛涛。"}', 3, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10805, 526, '{"english": "Thanks, Dad, but I''m not hungry.", "chinese": "谢谢爸爸，但是我不饿。"}', 4, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10806, 526, '{"english": "I''m thirsty.", "chinese": "我渴了。"}', 5, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10807, 526, '{"english": "Can I have some water, Mum?", "chinese": "我可以喝些水吗，妈妈？"}', 6, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10808, 526, '{"english": "Here you are.", "chinese": "给你。"}', 7, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10809, 526, '{"english": "Thank you, Mum.", "chinese": "谢谢你，妈妈。"}', 8, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10810, 526, '{"english": "happy", "chinese": "快乐的，高兴的"}', 9, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10811, 526, '{"english": "hungry", "chinese": "饥饿的"}', 10, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10812, 526, '{"english": "ill", "chinese": "生病的"}', 11, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10813, 526, '{"english": "Unit 7", "chinese": "第七单元"}', 12, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10814, 526, '{"english": "What''s the matter, Taotao?", "chinese": "怎么了，涛涛？"}', 13, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10815, 526, '{"english": "Are you ill?", "chinese": "你生病了吗？"}', 14, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10816, 526, '{"english": "No, but I''m tired.", "chinese": "没有，但是我很累。"}', 15, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10817, 526, '{"english": "I want to go to bed.", "chinese": "我想去睡觉。"}', 16, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10818, 526, '{"english": "Good night, dear.", "chinese": "晚安，亲爱的。"}', 17, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10819, 526, '{"english": "Good night, Mum and Dad.", "chinese": "爸爸妈妈，晚安。"}', 18, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10820, 526, '{"english": "sad", "chinese": "难过的"}', 19, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10821, 526, '{"english": "thirsty", "chinese": "渴的，口渴的"}', 20, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10822, 526, '{"english": "tired", "chinese": "累的，疲劳的"}', 21, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10823, 526, '{"english": "Fun time", "chinese": "娱乐时间"}', 22, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10824, 526, '{"english": "Say and act", "chinese": "说一说并演一演"}', 23, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10825, 526, '{"english": "What''s the matter?", "chinese": "怎么了？"}', 24, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10826, 526, '{"english": "Guess.", "chinese": "你猜猜。"}', 25, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10827, 526, '{"english": "Are you thirsty?", "chinese": "你渴了吗？"}', 26, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10828, 526, '{"english": "Yes, I''m thirsty.", "chinese": "是的，我很渴。"}', 27, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10829, 526, '{"english": "Here''s some water.", "chinese": "这里有些水。"}', 28, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10830, 526, '{"english": "Thank you.", "chinese": "谢谢你。"}', 29, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10831, 526, '{"english": "Tip: Say this in a different way.", "chinese": "小贴士：用不同的方式说。"}', 30, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10832, 526, '{"english": "See page 59.", "chinese": "详见课本59页。"}', 31, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10833, 526, '{"english": "Unit 7", "chinese": "第七单元"}', 32, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10834, 526, '{"english": "Cartoon time", "chinese": "卡通时间"}', 33, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10835, 526, '{"english": "What''s the matter, Bobby?", "chinese": "怎么了，波比？"}', 34, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10836, 526, '{"english": "Are you ill?", "chinese": "你生病了吗？"}', 35, '2026-02-05 04:26:17', '2026-02-05 04:26:17');
INSERT INTO "course_content" VALUES (10837, 526, '{"english": "No, I''m not.", "chinese": "不，我没生病。"}', 36, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10838, 526, '{"english": "Are you cold?", "chinese": "你冷吗？"}', 37, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10839, 526, '{"english": "No.", "chinese": "不冷。"}', 38, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10840, 526, '{"english": "Hello, Mrs Mouse.", "chinese": "你好，老鼠夫人。"}', 39, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10841, 526, '{"english": "This is Mrs Fox speaking.", "chinese": "我是狐狸夫人。"}', 40, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10842, 526, '{"english": "Are you all right, Bobby?", "chinese": "你没事吧，波比？"}', 41, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10843, 526, '{"english": "I''m hungry, Mum.", "chinese": "我饿了，妈妈。"}', 42, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10844, 526, '{"english": "Have a cake.", "chinese": "吃块蛋糕吧。"}', 43, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10845, 526, '{"english": "Thank you, Mum.", "chinese": "谢谢你，妈妈。"}', 44, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10846, 526, '{"english": "Ha! Ha!", "chinese": "哈！哈！"}', 45, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10847, 526, '{"english": "He''s happy now.", "chinese": "他现在很高兴。"}', 46, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
