INSERT INTO "course_content" VALUES (10850, 526, '{"english": "Go home, Joe, And show Rose your nose!", "chinese": "快回家，乔， 给罗斯看看你的鼻子！"}', 49, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10851, 526, '{"english": "close", "chinese": "关闭"}', 50, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10852, 526, '{"english": "home", "chinese": "家"}', 51, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
