INSERT INTO "course_content" VALUES (10856, 526, '{"english": "Rhyme time", "chinese": "唱歌谣时间"}', 55, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10857, 526, '{"english": "Are you ill?", "chinese": "你生病了吗？"}', 56, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10858, 526, '{"english": "My baby Bill Is sitting still.", "chinese": "我的宝宝比尔 坐着一动也不动。"}', 57, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10859, 526, '{"english": "If you''re ill, Take this pill.", "chinese": "如果你生病了， 就把这颗药丸吃了吧。"}', 58, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10860, 526, '{"english": "Unit 7", "chinese": "第七单元"}', 59, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
