INSERT INTO "course_content" VALUES (10862, 526, '{"english": "Look and say", "chinese": "看一看并说一说"}', 61, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10863, 526, '{"english": "What''s the matter, Mike?", "chinese": "怎么了，迈克？"}', 62, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10864, 526, '{"english": "I''m ...", "chinese": "我……"}', 63, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10865, 526, '{"english": "Here''s a fan.", "chinese": "这里有一把扇子。"}', 64, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10866, 526, '{"english": "Thank you, Dad.", "chinese": "谢谢你，爸爸。"}', 65, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10867, 526, '{"english": "Have some water, Wang Bing.", "chinese": "喝些水吧，王冰。"}', 66, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10868, 526, '{"english": "I''m not ..., but I''m ...", "chinese": "我不……但是我……"}', 67, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10869, 526, '{"english": "Here''s a hot dog.", "chinese": "这里有一根热狗。"}', 68, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10870, 526, '{"english": "Thank you.", "chinese": "谢谢你。"}', 69, '2026-02-05 04:26:18', '2026-02-05 04:26:18');
INSERT INTO "course_content" VALUES (10871, 526, '{"english": "Ticking time", "chinese": "打勾时间"}', 70, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10872, 526, '{"english": "I can talk about feelings.", "chinese": "我会谈论情绪。"}', 71, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10873, 526, '{"english": "I can use \"What''s the matter?\"", "chinese": "我会用“What''s the matter?”这个句型。"}', 72, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10874, 526, '{"english": "I know the sound of the letter \"o\".", "chinese": "我知道字母“o”的发音。"}', 73, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10875, 527, '{"english": "Unit 8  How are you?", "chinese": "第八单元 你好吗？"}', 1, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10876, 527, '{"english": "Story time", "chinese": "讲故事时间"}', 2, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10877, 527, '{"english": "Hello, this is Yang Ling speaking.", "chinese": "你好，我是杨凌。"}', 3, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10878, 527, '{"english": "May I speak to Miss Li?", "chinese": "我可以和李老师通电话吗？"}', 4, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10879, 527, '{"english": "Hello, Yang Ling.", "chinese": "你好，杨凌。"}', 5, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10880, 527, '{"english": "This is Miss Li.", "chinese": "我是李老师。"}', 6, '2026-02-05 04:26:19', '2026-02-05 04:26:19');
INSERT INTO "course_content" VALUES (10881, 527, '{"english": "Hello, Miss Li.", "chinese": "你好，李老师。"}', 7, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10882, 527, '{"english": "I can''t come to school today.", "chinese": "我今天不能来学校了。"}', 8, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10883, 527, '{"english": "What''s the matter?", "chinese": "怎么了？"}', 9, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10884, 527, '{"english": "I have a cold and a fever.", "chinese": "我感冒发烧了。"}', 10, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10885, 527, '{"english": "I''m sorry to hear that.", "chinese": "听到这事我很难过。"}', 11, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10886, 527, '{"english": "Take care, Yang Ling.", "chinese": "保重，杨凌。"}', 12, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10887, 527, '{"english": "Thank you, Miss Li.", "chinese": "谢谢你，李老师。"}', 13, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10888, 527, '{"english": "Unit 8", "chinese": "第八单元"}', 14, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10889, 527, '{"english": "Hello, this is Miss Li speaking.", "chinese": "你好，我是李老师。"}', 15, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10890, 527, '{"english": "Hello, Miss Li.", "chinese": "你好，李老师。"}', 16, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10891, 527, '{"english": "This is Yang Ling.", "chinese": "我是杨凌。"}', 17, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10892, 527, '{"english": "How are you now?", "chinese": "你现在怎么样了？"}', 18, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10893, 527, '{"english": "I''m fine, thank you.", "chinese": "我很好，谢谢。"}', 19, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10894, 527, '{"english": "Great.", "chinese": "太好了。"}', 20, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10895, 527, '{"english": "Can you come to school tomorrow?", "chinese": "你明天能来学校吗？"}', 21, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10896, 527, '{"english": "Yes, I can.", "chinese": "是的，我能。"}', 22, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10897, 527, '{"english": "See you tomorrow, Yang Ling.", "chinese": "明天见，杨凌。"}', 23, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
