INSERT INTO "course_content" VALUES (10905, 527, '{"english": "Hello, this is ... speaking. May I speak to ...?", "chinese": "你好，我是……。我可以和……通电话吗？"}', 31, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
