INSERT INTO "course_content" VALUES (10907, 527, '{"english": "How are you?", "chinese": "你好吗？"}', 33, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10908, 527, '{"english": "I''m fine, thank you. /", "chinese": "我很好，谢谢。/"}', 34, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10909, 527, '{"english": "Not so good.", "chinese": "不太好。"}', 35, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10910, 527, '{"english": "I have a cough.", "chinese": "我有点咳嗽。"}', 36, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
