INSERT INTO "course_content" VALUES (10914, 527, '{"english": "See page 59.", "chinese": "详见课本59页。"}', 40, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10915, 527, '{"english": "Hello, this is Sam speaking.", "chinese": "你好，我是萨姆。"}', 41, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10916, 527, '{"english": "Sunday 14 May", "chinese": "5月14日星期日"}', 42, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10917, 527, '{"english": "Hello, Sam.", "chinese": "你好，萨姆。"}', 43, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10918, 527, '{"english": "This is Tina.", "chinese": "我是蒂娜。"}', 44, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10919, 527, '{"english": "Hi, Tina.", "chinese": "你好，蒂娜。"}', 45, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10920, 527, '{"english": "Is Bobby there?", "chinese": "波比在那吗？"}', 46, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10921, 527, '{"english": "No. He''s at school.", "chinese": "不在。他在学校。"}', 47, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10922, 527, '{"english": "It''s Sunday today.", "chinese": "今天是星期日。"}', 48, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10923, 527, '{"english": "We don''t have any lessons on Sunday.", "chinese": "我们星期日没有课。"}', 49, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10924, 527, '{"english": "This is Bobby.", "chinese": "我是波比。"}', 50, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10925, 527, '{"english": "Ha! Ha!", "chinese": "哈！哈！"}', 51, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
INSERT INTO "course_content" VALUES (10926, 527, '{"english": "Sound time", "chinese": "学发音时间"}', 52, '2026-02-05 04:26:20', '2026-02-05 04:26:20');
