INSERT INTO "course_content" VALUES (10928, 528, '{"english": "Project 2  A party", "chinese": "课题 2 一次聚会"}', 1, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10929, 528, '{"english": "You are going to have a party.", "chinese": "你打算举办一次聚会。"}', 2, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10930, 528, '{"english": "Call your friends and ask them to come to the party.", "chinese": "给你的朋友们打电话，并请他们来参加这次聚会吧。"}', 3, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10931, 528, '{"english": "Hello, may I speak to ...?", "chinese": "你好，我可以和……通电话吗？"}', 4, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10932, 528, '{"english": "Hello, ...", "chinese": "你好，……"}', 5, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10933, 528, '{"english": "Can you come to my party this Sunday?", "chinese": "这个星期日你能来参加我的聚会吗？"}', 6, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10934, 528, '{"english": "I''d love to.", "chinese": "我很乐意。"}', 7, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10935, 528, '{"english": "Can ... come to my party too?", "chinese": "……也能来参加我的聚会吗？"}', 8, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10936, 528, '{"english": "No, he / she can''t.", "chinese": "不，他/她不能。"}', 9, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10937, 528, '{"english": "What''s the matter with him / her?", "chinese": "他/她怎么了？"}', 10, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10938, 528, '{"english": "He''s / She''s ill. He / She has ...", "chinese": "他/她生病了。他/她……"}', 11, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10939, 528, '{"english": "I''m sorry to hear that.", "chinese": "听到这事我很难过。"}', 12, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10940, 528, '{"english": "Choose your clothes for the party.", "chinese": "你为这次聚会挑选衣服。"}', 13, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10941, 528, '{"english": "Colour and cut out the clothes on page 69.", "chinese": "把69页上面的那些衣服剪下来并涂上颜色吧。"}', 14, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
INSERT INTO "course_content" VALUES (10942, 528, '{"english": "Whose clothes are these?", "chinese": "这些是谁的衣服？"}', 15, '2026-02-05 04:26:21', '2026-02-05 04:26:21');
