INSERT INTO "course_content" VALUES (11118, 531, '{"english": "Unit 1 Goldilocks and the three bears", "chinese": "第一单元  金发女孩和三只熊"}', 1, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11119, 531, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11120, 531, '{"english": "Goldilocks is in the forest.", "chinese": "金发女孩在森林里。"}', 3, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11121, 531, '{"english": "There is a house.", "chinese": "森林里有一座房子。"}', 4, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11122, 531, '{"english": "What a beautiful house!", "chinese": "多么漂亮的房子啊！"}', 5, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11123, 531, '{"english": "Goldilocks is in the house.", "chinese": "金发女孩在房子里。"}', 6, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11124, 531, '{"english": "She is hungry and thirsty.", "chinese": "她又饿又渴。"}', 7, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11125, 531, '{"english": "There is some soup on the table.", "chinese": "桌子上有一些汤。"}', 8, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11126, 531, '{"english": "This soup is too cold.", "chinese": "这个汤太冷了。"}', 9, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11127, 531, '{"english": "This soup is too hot.", "chinese": "这个汤太热了。"}', 10, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11128, 531, '{"english": "This soup is just right.", "chinese": "这个汤正好。"}', 11, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11129, 531, '{"english": "afraid", "chinese": "害怕的"}', 12, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11130, 531, '{"english": "hard", "chinese": "坚硬的"}', 13, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11131, 531, '{"english": "soft", "chinese": "柔软的"}', 14, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11132, 531, '{"english": "Tip Read more English stories.", "chinese": "小贴士 多读一些英语故事。"}', 15, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11133, 531, '{"english": "See page 90.", "chinese": "看90页。"}', 16, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11134, 531, '{"english": "Goldilocks is tired now.", "chinese": "金发女孩现在很累。"}', 17, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11135, 531, '{"english": "There are three beds in the room.", "chinese": "房间里有三张床。"}', 18, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11136, 531, '{"english": "This bed is too hard.", "chinese": "这张床太硬了。"}', 19, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11137, 531, '{"english": "This bed is too soft.", "chinese": "这张床太软了。"}', 20, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11138, 531, '{"english": "This bed is just right.", "chinese": "这张床正好。"}', 21, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11139, 531, '{"english": "Goldilocks is afraid.", "chinese": "金发女孩很害怕。"}', 22, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11140, 531, '{"english": "There are three bears in front of her!", "chinese": "在她的前面有三只熊！"}', 23, '2026-02-05 04:26:29', '2026-02-05 04:26:29');
INSERT INTO "course_content" VALUES (11141, 531, '{"english": "Who are you?", "chinese": "你是谁？"}', 24, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11142, 531, '{"english": "Help!", "chinese": "救命啊！"}', 25, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11143, 531, '{"english": "Help!", "chinese": "救命啊！"}', 26, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11144, 531, '{"english": "beside", "chinese": "在……旁边"}', 27, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11145, 531, '{"english": "between", "chinese": "在……中间"}', 28, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11146, 531, '{"english": "in front of", "chinese": "在……前面"}', 29, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11147, 531, '{"english": "Look and order", "chinese": "看一看，排一排"}', 30, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11148, 531, '{"english": "Think and say", "chinese": "想一想，说一说"}', 31, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11149, 531, '{"english": "There''s ... in the forest.", "chinese": "森林里有……"}', 32, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11150, 531, '{"english": "There''s ... on the table.", "chinese": "桌子上有……"}', 33, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11151, 531, '{"english": "There are ... in the room.", "chinese": "房间里有……"}', 34, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11152, 531, '{"english": "There are ... in front of me.", "chinese": "在我的前面有……"}', 35, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11153, 531, '{"english": "Grammar time", "chinese": "语法时间"}', 36, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11154, 531, '{"english": "There is a house in the forest.  There is some soup on the table.  There are three beds in the room.  There are three bears in front of her.", "chinese": "森林里有一所房子。 桌子上有一些汤。 房间里有三张床。 她面前有三只熊。"}', 37, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11155, 531, '{"english": "there''s  =  there is", "chinese": "有"}', 38, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11156, 531, '{"english": "This soup is too hot. This soup is too cold.  This bed is too hard. This bed is too soft.", "chinese": "这汤太热了。 这汤太冷了。 这张床太硬了。 这张床太软了。"}', 39, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11157, 531, '{"english": "Do you remember these words?", "chinese": "你记得这些单词吗？"}', 40, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11158, 531, '{"english": "happy", "chinese": "开心的；高兴的"}', 41, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11159, 531, '{"english": "hungry", "chinese": "饥饿的"}', 42, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11160, 531, '{"english": "thirsty", "chinese": "口渴的"}', 43, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11161, 531, '{"english": "tired", "chinese": "疲惫的"}', 44, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11162, 531, '{"english": "Fun time", "chinese": "娱乐时间"}', 45, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11163, 531, '{"english": "Draw and say", "chinese": "画一画，说一说"}', 46, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11164, 531, '{"english": "There''s a book on the chair.", "chinese": "椅子上有一本书。"}', 47, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11165, 531, '{"english": "There''s a glass of milk on the table ...", "chinese": "桌子上有一瓶牛奶……"}', 48, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11166, 531, '{"english": "Sound time", "chinese": "发音时间"}', 49, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11167, 531, '{"english": "c", "chinese": ""}', 50, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11168, 531, '{"english": "My uncle has a cold,", "chinese": "我的叔叔感冒了，"}', 51, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11169, 531, '{"english": "And my cousin too!", "chinese": "我的堂弟也感冒了！"}', 52, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11170, 531, '{"english": "The doctor comes and says,", "chinese": "医生来了说，"}', 53, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11171, 531, '{"english": "Put on your coats, you two!", "chinese": "“你们俩穿上你们的外套！”"}', 54, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11172, 531, '{"english": "cake", "chinese": "蛋糕"}', 55, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11173, 531, '{"english": "coat", "chinese": "外套"}', 56, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11174, 531, '{"english": "come", "chinese": "来"}', 57, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11175, 531, '{"english": "cup", "chinese": "杯子"}', 58, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11176, 531, '{"english": "doctor", "chinese": "医生"}', 59, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11177, 531, '{"english": "Culture time", "chinese": "文化时间"}', 60, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11178, 531, '{"english": "Coffee is popular in Western countries.", "chinese": "咖啡在西方国家很流行。"}', 61, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11179, 531, '{"english": "Tea is popular in China.", "chinese": "茶在中国很流行。"}', 62, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11180, 531, '{"english": "Cartoon time", "chinese": "卡通时间"}', 63, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11181, 531, '{"english": "Bobby is hungry.", "chinese": "鲍比饿了。"}', 64, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11182, 531, '{"english": "I''m hungry, Tina.", "chinese": "我饿了，蒂娜。"}', 65, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11183, 531, '{"english": "You can have some cakes.", "chinese": "你可以吃些蛋糕。"}', 66, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11184, 531, '{"english": "There are some in the kitchen.", "chinese": "厨房里有一些。"}', 67, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11185, 531, '{"english": "Bobby is in the kitchen.", "chinese": "鲍比在厨房里。"}', 68, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11186, 531, '{"english": "Where are the cakes, Tina?", "chinese": "蛋糕在哪里，蒂娜？"}', 69, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11187, 531, '{"english": "They''re in the fridge.", "chinese": "它们在冰箱里。"}', 70, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11188, 531, '{"english": "Bobby cannot see any cakes in the fridge.", "chinese": "鲍比没有看到冰箱里的蛋糕。"}', 71, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11189, 531, '{"english": "There aren''t any cakes here.", "chinese": "这里没有蛋糕。"}', 72, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11190, 531, '{"english": "Really?", "chinese": "真的吗？"}', 73, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11191, 531, '{"english": "Then, Bobby and Tina find their cousin.", "chinese": "然后，鲍比和蒂娜找到它们的堂弟。"}', 74, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11192, 531, '{"english": "Here are the cakes.", "chinese": "蛋糕在这里。"}', 75, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11193, 531, '{"english": "Checkout time", "chinese": "检查时间"}', 76, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11194, 531, '{"english": "Look and say", "chinese": "看一看，说一说"}', 77, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11195, 531, '{"english": "I''m in the living room.", "chinese": "我在客厅。"}', 78, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11196, 531, '{"english": "There''s a table.", "chinese": "客厅里有一张桌子。"}', 79, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11197, 531, '{"english": "There ... some books ... the table.", "chinese": "桌子……有一些书。"}', 80, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11198, 531, '{"english": "There ... some toy cars ... the table.", "chinese": "桌子……有一些玩具车。"}', 81, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11199, 531, '{"english": "There ... a chair ... the table.", "chinese": "桌子……有一把椅子。"}', 82, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11200, 531, '{"english": "There ... three umbrellas ... the window.", "chinese": "窗户……有三把伞。"}', 83, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11201, 531, '{"english": "Oh, There ... a bear ... the chair!", "chinese": "噢，椅子……有一只熊！"}', 84, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11202, 531, '{"english": "Look and write", "chinese": "看一看，写一写"}', 85, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11203, 531, '{"english": "There are five apples on the table.", "chinese": "桌子上有五个苹果。"}', 86, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11204, 531, '{"english": "There is coffee in the glass.", "chinese": "杯子里有咖啡。"}', 87, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11205, 531, '{"english": "There is a bird in the tree.", "chinese": "树上有一只鸟。"}', 88, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11206, 531, '{"english": "There are some candies in the box.", "chinese": "盒子里有一些糖。"}', 89, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11207, 531, '{"english": "Ticking time", "chinese": "评价时间"}', 90, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11208, 531, '{"english": "I can understand \"Goldilocks and the three bears\".", "chinese": "我能理解“Goldilocks和the three bears”的故事。"}', 91, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11209, 531, '{"english": "I can use \"There is/are\" to talk about things in a place.", "chinese": "我可以用“There is/are”谈论某处的物品。"}', 92, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11210, 531, '{"english": "I know the sound of the letter \"c\".", "chinese": "我知道字母“c”的发音。"}', 93, '2026-02-05 04:26:30', '2026-02-05 04:26:30');
INSERT INTO "course_content" VALUES (11211, 532, '{"english": "Unit 2 A new student", "chinese": "第二单元   一位新学生"}', 1, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11212, 532, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11213, 532, '{"english": "Hi, Yang Ling.", "chinese": "嗨，杨玲。"}', 3, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11214, 532, '{"english": "This is Nancy Black.", "chinese": "这是南茜·布莱克。"}', 4, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11215, 532, '{"english": "She''s a new student.", "chinese": "她是一位新学生。"}', 5, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11216, 532, '{"english": "Can you show her around?", "chinese": "你可以带她参观一下吗？"}', 6, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11217, 532, '{"english": "Yes, Miss Li.", "chinese": "好的，李老师。"}', 7, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11218, 532, '{"english": "These are the classrooms.", "chinese": "这些是教室。"}', 8, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11219, 532, '{"english": "How many classrooms are there in our school?", "chinese": "在我们学校有多少教室？"}', 9, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11220, 532, '{"english": "There are 24 classrooms.", "chinese": "有24间教室。"}', 10, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11221, 532, '{"english": "Our classroom is on the second floor.", "chinese": "我们的教室在二楼。"}', 11, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11222, 532, '{"english": "art room", "chinese": "美术室"}', 12, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11223, 532, '{"english": "classroom", "chinese": "教室"}', 13, '2026-02-05 04:26:31', '2026-02-05 04:26:31');
INSERT INTO "course_content" VALUES (11224, 532, '{"english": "computer room", "chinese": "电脑室"}', 14, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11225, 532, '{"english": "Are there any computer rooms?", "chinese": "有电脑室吗？"}', 15, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11226, 532, '{"english": "Yes, There are.", "chinese": "有。"}', 16, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11227, 532, '{"english": "There are two computer rooms.", "chinese": "有两个电脑室。"}', 17, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11228, 532, '{"english": "There''s a library too.", "chinese": "还有一个图书馆。"}', 18, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11229, 532, '{"english": "They''re on the third floor.", "chinese": "它们在三楼。"}', 19, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11230, 532, '{"english": "Is there a music room?", "chinese": "有音乐室吗？"}', 20, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11231, 532, '{"english": "Yes, There is.", "chinese": "有。"}', 21, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11232, 532, '{"english": "It''s on the first floor.", "chinese": "在一楼。"}', 22, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11233, 532, '{"english": "The table tennis room is on the first floor too.", "chinese": "乒乓球室也在一楼。"}', 23, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11234, 532, '{"english": "Let''s go and have a look.", "chinese": "让我们去看看吧。"}', 24, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11235, 532, '{"english": "library", "chinese": "图书馆"}', 25, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11236, 532, '{"english": "music room", "chinese": "音乐室"}', 26, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11237, 532, '{"english": "playground", "chinese": "操场"}', 27, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11238, 532, '{"english": "Write and say", "chinese": "写一写，说一说"}', 28, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11239, 532, '{"english": "Where are these rooms?", "chinese": "这些房间在哪里？"}', 29, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11240, 532, '{"english": "library", "chinese": "图书馆"}', 30, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11241, 532, '{"english": "Nancy''s classroom", "chinese": "南茜的教室"}', 31, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11242, 532, '{"english": "computer room", "chinese": "电脑室"}', 32, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11243, 532, '{"english": "table tennis room", "chinese": "乒乓球室"}', 33, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11244, 532, '{"english": "music room", "chinese": "音乐室"}', 34, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11245, 532, '{"english": "3F", "chinese": "三楼"}', 35, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11246, 532, '{"english": "2F", "chinese": "二楼"}', 36, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11247, 532, '{"english": "1F", "chinese": "一楼"}', 37, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11248, 532, '{"english": "There are two computer rooms in the school.", "chinese": "学校里有两间电脑室。"}', 38, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11249, 532, '{"english": "They''re on the third floor.", "chinese": "它们在三楼。"}', 39, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11250, 532, '{"english": "Grammar time", "chinese": "语法时间"}', 40, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11251, 532, '{"english": "Is there a music room? Is there a library? Are there any computer rooms? Are there any art rooms?", "chinese": "有音乐室吗？ 有图书馆吗？ 有电脑室吗？ 有美术室吗？"}', 41, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11252, 532, '{"english": "Yes, there is./Yes, there are.  No, there isn''t./No, there aren''t.", "chinese": "是的，有。 不，没有。"}', 42, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11253, 532, '{"english": "isn''t = is not", "chinese": "不是"}', 43, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11254, 532, '{"english": "aren''t = are not", "chinese": "不是"}', 44, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11255, 532, '{"english": "How many classrooms are there in our school?", "chinese": "我们学校有多少间教室？"}', 45, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11256, 532, '{"english": "There are 24 classrooms.", "chinese": "有24间教室。"}', 46, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11257, 532, '{"english": "It''s on the first floor. It''s on the second floor. It''s on the third floor. They''re on the first floor. They''re on the second floor. They''re on the third floor.", "chinese": "它在一楼。 它在二楼。 它在三楼。 它们在一楼。 它们在二楼。 它们在三楼。"}', 47, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11258, 532, '{"english": "It''s = It is", "chinese": "它是"}', 48, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11259, 532, '{"english": "They''re = They are", "chinese": "它们是"}', 49, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11260, 532, '{"english": "one→first", "chinese": "一→第一"}', 50, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11261, 532, '{"english": "two→second", "chinese": "二→第二"}', 51, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11262, 532, '{"english": "three→third", "chinese": "三→第三"}', 52, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11263, 532, '{"english": "Fun time", "chinese": "娱乐时间"}', 53, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11264, 532, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 54, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11265, 532, '{"english": "This is Nancy''s classroom in her new school.", "chinese": "这是南茜新学校的教室。"}', 55, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11266, 532, '{"english": "How many desks and chairs are there in the classroom?", "chinese": "教室里有多少桌子和椅子？"}', 56, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11267, 532, '{"english": "Is there a computer?", "chinese": "有一台电脑吗？"}', 57, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11268, 532, '{"english": "Are there any pictures?", "chinese": "有一些图片吗？"}', 58, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11269, 532, '{"english": "Sound time", "chinese": "发音时间"}', 59, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11270, 532, '{"english": "c", "chinese": ""}', 60, '2026-02-05 04:26:32', '2026-02-05 04:26:32');
INSERT INTO "course_content" VALUES (11271, 532, '{"english": "Alice and I sing and dance,", "chinese": "我和爱丽丝唱歌跳舞，"}', 61, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11272, 532, '{"english": "And drink some nice juice!", "chinese": "喝了一些美味的果汁！"}', 62, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11273, 532, '{"english": "Then we go to the cinema,", "chinese": "然后我们去了电影院，"}', 63, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11274, 532, '{"english": "And have a nice ice cream!", "chinese": "吃了一个美味的冰淇淋！"}', 64, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11275, 532, '{"english": "cinema", "chinese": "电影院"}', 65, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11276, 532, '{"english": "dance", "chinese": "跳舞"}', 66, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11277, 532, '{"english": "ice cream", "chinese": "冰淇淋"}', 67, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11278, 532, '{"english": "juice", "chinese": "果汁"}', 68, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11279, 532, '{"english": "nice", "chinese": "美味的"}', 69, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11280, 532, '{"english": "Culture time", "chinese": "文化时间"}', 70, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11281, 532, '{"english": "Tip Look, read and think.", "chinese": "小贴士 看一看，读一读，想一想。"}', 71, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11282, 532, '{"english": "See page 90.", "chinese": "看90页。"}', 72, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11283, 532, '{"english": "In the UK, this is the ground floor.", "chinese": "在英国，这是一楼。"}', 73, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11284, 532, '{"english": "In the US, this is the first floor.", "chinese": "在美国，这是第一层。"}', 74, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11285, 532, '{"english": "Cartoon time", "chinese": "卡通时间"}', 75, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11286, 532, '{"english": "Bobby and Sam are in the playground.", "chinese": "鲍比和山姆在操场上。"}', 76, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11287, 532, '{"english": "Look!", "chinese": "看！"}', 77, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11288, 532, '{"english": "There''s a swing.", "chinese": "有一个秋千。"}', 78, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11289, 532, '{"english": "Let''s go and play!", "chinese": "咱们一起去玩玩吧！"}', 79, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11290, 532, '{"english": "Sam is on the swing.", "chinese": "山姆坐在秋千上。"}', 80, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11291, 532, '{"english": "Push me, Bobby!", "chinese": "推我，鲍比！"}', 81, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11292, 532, '{"english": "You''re so heavy, Sam!", "chinese": "你太重了，山姆！"}', 82, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11293, 532, '{"english": "Now Bobby is on the swing.", "chinese": "现在鲍比坐在秋千上。"}', 83, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11294, 532, '{"english": "Go!", "chinese": "一！"}', 84, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11295, 532, '{"english": "Go!", "chinese": "二！"}', 85, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11296, 532, '{"english": "Go!", "chinese": "三！"}', 86, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11297, 532, '{"english": "Stop, Sam!", "chinese": "停下来，山姆！"}', 87, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11298, 532, '{"english": "It''s too high!", "chinese": "太高了！"}', 88, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11299, 532, '{"english": "Sam is happy, but Bobby is not.", "chinese": "山姆很开心，但是鲍比不开心。"}', 89, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11300, 532, '{"english": "He is afraid.", "chinese": "他很害怕。"}', 90, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11301, 532, '{"english": "It''s great fun!", "chinese": "太有趣了！"}', 91, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11302, 532, '{"english": "Let''s play again!", "chinese": "让我们再玩一次吧！"}', 92, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11303, 532, '{"english": "Oh no!", "chinese": "噢，不！"}', 93, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11304, 532, '{"english": "It''s time for dinner.", "chinese": "晚餐的时间到了。"}', 94, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11305, 532, '{"english": "Let''s go home now.", "chinese": "现在咱们回家吧。"}', 95, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11306, 532, '{"english": "Checkout time", "chinese": "检查时间"}', 96, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11307, 532, '{"english": "Think and write", "chinese": "想一想，写一写"}', 97, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11308, 532, '{"english": "My school", "chinese": "我的学校"}', 98, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11309, 532, '{"english": "There are ______ classrooms in my school.", "chinese": "在我的学校有______个教室。"}', 99, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11310, 532, '{"english": "There is a ______. It is on the ______ floor.", "chinese": "有一个______。它在______楼。"}', 100, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11311, 532, '{"english": "There is a ______. It is on the ______ floor.", "chinese": "有一个______。它在______楼。"}', 101, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11312, 532, '{"english": "There is a ______. It is on the ______ floor.", "chinese": "有一个______。它在______楼。"}', 102, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11313, 532, '{"english": "There are ______. They are on the ______ floor.", "chinese": "有______。它们在______楼。"}', 103, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11314, 532, '{"english": "There is not a ______ in my school.", "chinese": "在我的学校没有一个______。"}', 104, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11315, 532, '{"english": "There are not any ______ in my school.", "chinese": "在我的学校没有一些______。"}', 105, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11316, 532, '{"english": "Listen and number", "chinese": "听一听，标一标"}', 106, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11317, 532, '{"english": "Ticking time", "chinese": "评价时间"}', 107, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11318, 532, '{"english": "I can talk about my school.", "chinese": "我可以谈论我的学校。"}', 108, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11319, 532, '{"english": "I can use \"Is/Are there ... ?\" to ask questions.", "chinese": "我可以用“Is/Are there……？”问问题。"}', 109, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11320, 532, '{"english": "I can use \"first\", \"second\" and \"third\".", "chinese": "我可以用“first”“second”和“third”。"}', 110, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11321, 532, '{"english": "I know the sound of the letter \"c\".", "chinese": "我知道字母“c”的发音。"}', 111, '2026-02-05 04:26:33', '2026-02-05 04:26:33');
INSERT INTO "course_content" VALUES (11322, 533, '{"english": "Unit 3 Our animal friends", "chinese": "第三单元   我们的动物朋友"}', 1, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11323, 533, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11324, 533, '{"english": "I have two animal friends.", "chinese": "我有两个动物朋友。"}', 3, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11325, 533, '{"english": "One is red and the other is black.", "chinese": "一个是红色的，另一个是黑色的。"}', 4, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11326, 533, '{"english": "They have big eyes and big bodies.", "chinese": "它们有大眼睛，身体很大。"}', 5, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11327, 533, '{"english": "They have no legs or arms, but they have big tails.", "chinese": "它们没有腿和胳膊，但它们有大尾巴。"}', 6, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11328, 533, '{"english": "They can swim.", "chinese": "它们可以游泳。"}', 7, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11329, 533, '{"english": "I have an animal friend.", "chinese": "我有一个动物朋友。"}', 8, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11330, 533, '{"english": "It is white.", "chinese": "它是白色的。"}', 9, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11331, 533, '{"english": "It has four legs and a short tail.", "chinese": "它有四条腿和一条短尾巴。"}', 10, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11332, 533, '{"english": "It has big ears.", "chinese": "它有大耳朵。"}', 11, '2026-02-05 04:26:34', '2026-02-05 04:26:34');
INSERT INTO "course_content" VALUES (11333, 533, '{"english": "It can run and jump.", "chinese": "它可以跑和跳。"}', 12, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11334, 533, '{"english": "an arm", "chinese": "手臂"}', 13, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11335, 533, '{"english": "a body", "chinese": "身体"}', 14, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11336, 533, '{"english": "a foot", "chinese": "脚"}', 15, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11337, 533, '{"english": "Tip How many body parts can you name?", "chinese": "小贴士 你能说出多少身体部位？"}', 16, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11338, 533, '{"english": "See page 90.", "chinese": "看90页。"}', 17, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11339, 533, '{"english": "My animal friend is white.", "chinese": "我的动物朋友是白色的。"}', 18, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11340, 533, '{"english": "It has red eyes and long ears.", "chinese": "它有红眼睛和长耳朵。"}', 19, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11341, 533, '{"english": "It has four legs and a short tail.", "chinese": "它有四条腿和一条短尾巴。"}', 20, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11342, 533, '{"english": "It can run.", "chinese": "它可以跑。"}', 21, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11343, 533, '{"english": "My animal friend is yellow and green.", "chinese": "我的动物朋友是黄色和绿色的。"}', 22, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11344, 533, '{"english": "It has two legs and two wings.", "chinese": "它有两条腿和两个翅膀。"}', 23, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11345, 533, '{"english": "It has a big mouth and a long tail.", "chinese": "它有一个大嘴巴和一个长尾。"}', 24, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11346, 533, '{"english": "It can talk and fly.", "chinese": "它可以说话，还可以飞。"}', 25, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11347, 533, '{"english": "a leg", "chinese": "腿"}', 26, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11348, 533, '{"english": "a tail", "chinese": "尾巴"}', 27, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11349, 533, '{"english": "a wing", "chinese": "翅膀"}', 28, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11350, 533, '{"english": "Match and say", "chinese": "连一连，说一说"}', 29, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11351, 533, '{"english": "What animal friends do they have?", "chinese": "他们有什么动物？"}', 30, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11352, 533, '{"english": "Nancy has two fish.", "chinese": "南茜有两条鱼。"}', 31, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11353, 533, '{"english": "You", "chinese": "你"}', 32, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11354, 533, '{"english": "Think and write", "chinese": "想一想，写一写"}', 33, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11355, 533, '{"english": "Nancy''s fish have big eyes, bodies and tails.", "chinese": "南希的鱼有大眼睛，大身子和大尾巴。"}', 34, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11356, 533, '{"english": "Mike''s dog has big ears and a short tail.", "chinese": "迈克的狗有大耳朵和一条短尾巴。"}', 35, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11357, 533, '{"english": "Liu Tao''s rabbit has long ears and a short tail.", "chinese": "刘涛的兔子有长耳朵和一条短尾巴。"}', 36, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11358, 533, '{"english": "Su Hai''s parrot has a big mouth, a long tail, two legs and two wings.", "chinese": "苏海的鹦鹉有一个大嘴巴，一条长尾巴，两条腿和两个翅膀。"}', 37, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11359, 533, '{"english": "Grammar time", "chinese": "语法时间"}', 38, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11360, 533, '{"english": "I/We/You/They have two fish. I/We/You/They have a rabbit. I/We/You/They have a parrot. He/She/It has a dog.  He/She/It has a bird.  He/She/It has two legs.", "chinese": "我/我们/你（们）/他们有两条鱼。 我/我们/你（们）/他们有一只兔子。 我/我们/你（们）/他们有一只鹦鹉。 他/她/它有一只狗。 他/她/它有一只鸟。 他/她/它有两条腿。"}', 39, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11361, 533, '{"english": "have→has", "chinese": "有"}', 40, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11362, 533, '{"english": "Do you/they have an animal friend? Does he/she have an animal friend?", "chinese": "你/他们有动物朋友吗？ 他/她有动物朋友吗？"}', 41, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11363, 533, '{"english": "Yes, I/we/they do.  No, I/we/they don''t.", "chinese": "是的，我/我们/他们有。 不，我/我们/他们没有。"}', 42, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11364, 533, '{"english": "Yes, he/she does.  No, he/she doesn''t.", "chinese": "是的，他/她有。 不，他/她没有。"}', 43, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11365, 533, '{"english": "don''t = do not", "chinese": "不"}', 44, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11366, 533, '{"english": "doesn''t = does not", "chinese": "不"}', 45, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11367, 533, '{"english": "Fun time", "chinese": "娱乐时间"}', 46, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11368, 533, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 47, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11369, 533, '{"english": "Do you have an animal friend, Peter?", "chinese": "你有一个动物朋友吗，彼得？"}', 48, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11370, 533, '{"english": "Yes, I do.", "chinese": "是的，我有。"}', 49, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11371, 533, '{"english": "Does it have ... ?", "chinese": "它有……吗？"}', 50, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11372, 533, '{"english": "Yes, It does.", "chinese": "是的，它有。"}', 51, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11373, 533, '{"english": "No, It doesn''t.", "chinese": "不，它没有。"}', 52, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11374, 533, '{"english": "It has ...", "chinese": "它有……"}', 53, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11375, 533, '{"english": "What can it do?", "chinese": "它可以做什么？"}', 54, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11376, 533, '{"english": "It can ...", "chinese": "它可以……"}', 55, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11377, 533, '{"english": "Is it a ... ?", "chinese": "它是一只……吗？"}', 56, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11378, 533, '{"english": "Animal friend", "chinese": "动物朋友"}', 57, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11379, 533, '{"english": "It has ...", "chinese": "它有……"}', 58, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11380, 533, '{"english": "It can ...", "chinese": "它可以……"}', 59, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11381, 533, '{"english": "Peter", "chinese": "彼得"}', 60, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11382, 533, '{"english": "parrot", "chinese": "鹦鹉"}', 61, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11383, 533, '{"english": "long tail, big mouth, two wings", "chinese": "长尾巴，大嘴巴，两个翅膀"}', 62, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11384, 533, '{"english": "fly, talk", "chinese": "飞，说话"}', 63, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11385, 533, '{"english": "Sound time", "chinese": "发音时间"}', 64, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11386, 533, '{"english": "u", "chinese": ""}', 65, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11387, 533, '{"english": "Rubber duck likes the rain,", "chinese": "橡皮鸭喜欢雨，"}', 66, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11388, 533, '{"english": "But he doesn''t like sunny weather.", "chinese": "但它不喜欢阳光明媚的天气。"}', 67, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11389, 533, '{"english": "So when the summer sun comes out,", "chinese": "所以夏天当太阳出来的时候，"}', 68, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11390, 533, '{"english": "He carries an umbrella!", "chinese": "它带着一把伞！"}', 69, '2026-02-05 04:26:35', '2026-02-05 04:26:35');
INSERT INTO "course_content" VALUES (11391, 533, '{"english": "bus", "chinese": "公共汽车"}', 70, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11392, 533, '{"english": "duck", "chinese": "鸭子"}', 71, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11393, 533, '{"english": "summer", "chinese": "夏天"}', 72, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11394, 533, '{"english": "sun", "chinese": "太阳"}', 73, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11395, 533, '{"english": "umbrella", "chinese": "雨伞"}', 74, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11396, 533, '{"english": "Culture time", "chinese": "文化时间"}', 75, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11397, 533, '{"english": "You can see pandas in China.", "chinese": "在中国你可以看到熊猫。"}', 76, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11398, 533, '{"english": "You can see bald eagles in the US.", "chinese": "在美国你可以看到秃鹰。"}', 77, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11399, 533, '{"english": "You can see polar bears in Canada.", "chinese": "在加拿大你可以看到北极熊。"}', 78, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11400, 533, '{"english": "You can see kangaroos in Australia.", "chinese": "在澳大利亚你可以看到袋鼠。"}', 79, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11401, 533, '{"english": "Cartoon time", "chinese": "卡通时间"}', 80, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11402, 533, '{"english": "Look, Sam!", "chinese": "看，山姆！"}', 81, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11403, 533, '{"english": "We have a new friend.", "chinese": "我们有一位新朋友。"}', 82, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11404, 533, '{"english": "Hello, I''m Sam.", "chinese": "你好，我是山姆。"}', 83, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11405, 533, '{"english": "Nice to meet you.", "chinese": "很高兴认识你。"}', 84, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11406, 533, '{"english": "Don''t shout, Sam!", "chinese": "不要叫，山姆！"}', 85, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11407, 533, '{"english": "It''s afraid.", "chinese": "它很害怕。"}', 86, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11408, 533, '{"english": "Oh, It can run!", "chinese": "噢，它可以跑！"}', 87, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11409, 533, '{"english": "It has ten legs.", "chinese": "它有十条腿。"}', 88, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11410, 533, '{"english": "No.", "chinese": "不。"}', 89, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11411, 533, '{"english": "It has eight legs.", "chinese": "它有八条腿。"}', 90, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11412, 533, '{"english": "Those two are not legs.", "chinese": "这两个不是腿。"}', 91, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11413, 533, '{"english": "They''re arms.", "chinese": "它们是手臂。"}', 92, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11414, 533, '{"english": "It has big arms!", "chinese": "它的手臂很大！"}', 93, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11415, 533, '{"english": "It has a big body too.", "chinese": "它的身体也很大。"}', 94, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11416, 533, '{"english": "Its body is hard.", "chinese": "它的身体很硬。"}', 95, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11417, 533, '{"english": "Give It a cake.", "chinese": "给它一个蛋糕。"}', 96, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11418, 533, '{"english": "Ouch!", "chinese": "哎哟！"}', 97, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11419, 533, '{"english": "Ha! Ha!", "chinese": "哈！哈！"}', 98, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11420, 533, '{"english": "It likes your fingers!", "chinese": "它喜欢你的手指！"}', 99, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11421, 533, '{"english": "Checkout time", "chinese": "检查时间"}', 100, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11422, 533, '{"english": "Look and say", "chinese": "看一看，说一说"}', 101, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11423, 533, '{"english": "There''s/There are ... on the farm.", "chinese": "农场里有……。"}', 102, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11424, 533, '{"english": "It has/They have ...", "chinese": "它有/它们有……"}', 103, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11425, 533, '{"english": "You", "chinese": "你"}', 104, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11426, 533, '{"english": "Draw and write", "chinese": "画一画，写一写"}', 105, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11427, 533, '{"english": "Draw an animal and write about it.", "chinese": "画一个动物，然后写一写。"}', 106, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11428, 533, '{"english": "This is my animal friend.", "chinese": "这是我的动物朋友。"}', 107, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11429, 533, '{"english": "It is ______.", "chinese": "它是______。"}', 108, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11430, 533, '{"english": "It has ______.", "chinese": "它有______。"}', 109, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11431, 533, '{"english": "It can ______.", "chinese": "它可以______。"}', 110, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11432, 533, '{"english": "Ticking time", "chinese": "评价时间"}', 111, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11433, 533, '{"english": "I can talk about animals.", "chinese": "我可以谈论动物。"}', 112, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11434, 533, '{"english": "I can use \"have\" and \"has\".", "chinese": "我可以用“have”和“has”。"}', 113, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11435, 533, '{"english": "I can use \"do\" and \"does\" to ask \"Yes/No\" questions.", "chinese": "我可以用“do”和“does”问“Yes/No”的问题。"}', 114, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11436, 533, '{"english": "I know the sound of the letter \"u\".", "chinese": "我知道字母“u”的发音。"}', 115, '2026-02-05 04:26:36', '2026-02-05 04:26:36');
INSERT INTO "course_content" VALUES (11437, 534, '{"english": "Unit 4 Hobbies", "chinese": "第四单元  业余爱好"}', 1, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11438, 534, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11439, 534, '{"english": "Tip Use the dictionary.", "chinese": "小贴士 使用词典。"}', 3, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11440, 534, '{"english": "See page 90.", "chinese": "看90页。"}', 4, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11441, 534, '{"english": "I like playing basketball and football.", "chinese": "我喜欢打篮球，踢足球。"}', 5, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11442, 534, '{"english": "I can play basketball well, but I am not good at football.", "chinese": "我篮球打得很好，但是我不擅长足球。"}', 6, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11443, 534, '{"english": "I like drawing too.", "chinese": "我也喜欢画画。"}', 7, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11444, 534, '{"english": "I usually draw in the park with my brother Tim.", "chinese": "我通常和我的弟弟蒂姆在公园里画画。"}', 8, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11445, 534, '{"english": "This is my friend Liu Tao.", "chinese": "这是我的朋友刘涛。"}', 9, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11446, 534, '{"english": "He likes playing football too.", "chinese": "他也喜欢踢足球。"}', 10, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11447, 534, '{"english": "He is good at it.", "chinese": "他很擅长踢足球。"}', 11, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11448, 534, '{"english": "He also likes playing table tennis.", "chinese": "他也喜欢打乒乓球。"}', 12, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11449, 534, '{"english": "dance", "chinese": "跳舞"}', 13, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11450, 534, '{"english": "draw", "chinese": "画画"}', 14, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11451, 534, '{"english": "play the piano", "chinese": "弹钢琴"}', 15, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11452, 534, '{"english": "This is Yang Ling.", "chinese": "这是杨玲。"}', 16, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11453, 534, '{"english": "She is my friend too.", "chinese": "她也是我的朋友。"}', 17, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11454, 534, '{"english": "She likes reading stories.", "chinese": "她喜欢读故事。"}', 18, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11455, 534, '{"english": "She has a lot of books.", "chinese": "她有很多书。"}', 19, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11456, 534, '{"english": "She also likes playing the piano.", "chinese": "她也喜欢弹钢琴。"}', 20, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11457, 534, '{"english": "Here are Su Hai and Su Yang.", "chinese": "这是苏海和苏洋。"}', 21, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11458, 534, '{"english": "They are twins.", "chinese": "她们是双胞胎。"}', 22, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11459, 534, '{"english": "Su Hai likes dancing.", "chinese": "苏海喜欢跳舞。"}', 23, '2026-02-05 04:26:37', '2026-02-05 04:26:37');
INSERT INTO "course_content" VALUES (11460, 534, '{"english": "Su Yang likes watching films.", "chinese": "苏洋喜欢看电影。"}', 24, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11461, 534, '{"english": "They both like swimming.", "chinese": "她们都喜欢游泳。"}', 25, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11462, 534, '{"english": "read", "chinese": "阅读"}', 26, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11463, 534, '{"english": "sing", "chinese": "唱歌"}', 27, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11464, 534, '{"english": "watch films", "chinese": "看电影"}', 28, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11465, 534, '{"english": "Think and write", "chinese": "想一想，写一写"}', 29, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11466, 534, '{"english": "Mike likes playing basketball, football and drawing.", "chinese": "迈克喜欢打篮球，踢足球和画画。"}', 30, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11467, 534, '{"english": "Tim likes drawing.", "chinese": "蒂姆喜欢画画。"}', 31, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11468, 534, '{"english": "Liu Tao likes playing football.", "chinese": "刘涛喜欢踢足球。"}', 32, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11469, 534, '{"english": "Yang Ling likes reading stories.", "chinese": "杨玲喜欢读故事。"}', 33, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11470, 534, '{"english": "Su Hai likes dancing and swimming.", "chinese": "苏海喜欢跳舞和游泳。"}', 34, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11471, 534, '{"english": "Su Yang likes swimming.", "chinese": "苏洋喜欢游泳。"}', 35, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11472, 534, '{"english": "Grammar time", "chinese": "语法时间"}', 36, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11473, 534, '{"english": "What do you/they like doing? What does he/she like doing?", "chinese": "你（们）/他们喜欢做什么？ 他/她喜欢做什么？"}', 37, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11474, 534, '{"english": "I/You/We/They like playing basketball.  I/You/We/They like watching films.  I/You/We/They like drawing.  I/You/We/They like swimming.  He/She likes playing football.  He/She likes reading stories.", "chinese": "我/你（们）/我们/他们喜欢打篮球。 我/你（们）/我们/他们喜欢看电影。 我/你（们）/我们/他们喜欢画画。 我/你（们）/我们/他们喜欢游泳。 他/她喜欢踢足球。 他/她喜欢读故事。"}', 38, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11475, 534, '{"english": "like→likes", "chinese": "喜欢"}', 39, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11476, 534, '{"english": "dance→dancing", "chinese": "跳舞"}', 40, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11477, 534, '{"english": "read→reading", "chinese": "阅读"}', 41, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11478, 534, '{"english": "draw→drawing", "chinese": "画画"}', 42, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11479, 534, '{"english": "sing→singing", "chinese": "唱歌"}', 43, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11480, 534, '{"english": "play→playing", "chinese": "玩；踢（球类）"}', 44, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11481, 534, '{"english": "swim→swimming", "chinese": "游泳"}', 45, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11482, 534, '{"english": "Fun time", "chinese": "娱乐时间"}', 46, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11483, 534, '{"english": "Do a survey", "chinese": "做调查"}', 47, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11484, 534, '{"english": "Mary", "chinese": "玛丽"}', 48, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11485, 534, '{"english": "What do you like doing, Mary?", "chinese": "你喜欢做什么，玛丽？"}', 49, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11486, 534, '{"english": "I like drawing.", "chinese": "我喜欢画画。"}', 50, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11487, 534, '{"english": "In our group, ... student(s) like(s) ...", "chinese": "在我们组，……学生喜欢……."}', 51, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11488, 534, '{"english": "Sound time", "chinese": "发音时间"}', 52, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11489, 534, '{"english": "y", "chinese": ""}', 53, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11490, 534, '{"english": "Do you like wearing yellow?", "chinese": "你喜欢穿黄色吗？"}', 54, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11491, 534, '{"english": "Yellow?", "chinese": "黄色？"}', 55, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11492, 534, '{"english": "Yellow?", "chinese": "黄色？"}', 56, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11493, 534, '{"english": "yes!", "chinese": "是的！"}', 57, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11494, 534, '{"english": "I have yellow shoes, a yellow hat,", "chinese": "我有黄色的鞋子，一个黄色的帽子，"}', 58, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11495, 534, '{"english": "And a yellow dress!", "chinese": "和一条黄色的裙子！"}', 59, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11496, 534, '{"english": "year", "chinese": "年"}', 60, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11497, 534, '{"english": "yellow", "chinese": "黄色的"}', 61, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11498, 534, '{"english": "yes", "chinese": "是的"}', 62, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11499, 534, '{"english": "you", "chinese": "你"}', 63, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11500, 534, '{"english": "young", "chinese": "年轻的"}', 64, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11501, 534, '{"english": "Song time", "chinese": "歌曲时间"}', 65, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11502, 534, '{"english": "We all like climbing", "chinese": "我们都喜欢爬山"}', 66, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11503, 534, '{"english": "We all like cli- mbing ve- ry much.", "chinese": "歌词大意：我们都非常喜欢爬山。"}', 67, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11504, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 68, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11505, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 69, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11506, 534, '{"english": "We all like cli- mbing ve- ry much.", "chinese": "我们都非常喜欢爬山。"}', 70, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11507, 534, '{"english": "Let''s go and climb to- day.", "chinese": "今天我们去爬山吧。"}', 71, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11508, 534, '{"english": "We all like dan- cing  ve- ry much.", "chinese": "我们都非常喜欢跳舞。"}', 72, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11509, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 73, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11510, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 74, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11511, 534, '{"english": "We all like dan- cing ve- ry much.", "chinese": "我们都非常喜欢跳舞。"}', 75, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11512, 534, '{"english": "Let''s go and dance to-  day.", "chinese": "今天我们去跳舞吧。"}', 76, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11513, 534, '{"english": "We all like swim-ming ve- ry much.", "chinese": "我们都非常喜欢游泳。"}', 77, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11514, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 78, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11515, 534, '{"english": "Yes, we do.", "chinese": "是的，我们喜欢。"}', 79, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11516, 534, '{"english": "We all like swim-ming ve-  ry much.", "chinese": "我们都非常喜欢游泳。"}', 80, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11517, 534, '{"english": "Let''s go and swim to-  day.", "chinese": "今天我们去游泳吧。"}', 81, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11518, 534, '{"english": "Cartoon time", "chinese": "卡通时间"}', 82, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11519, 534, '{"english": "Sam and Billy talk about their hobbies.", "chinese": "山姆和比利谈论他们的业余爱好。"}', 83, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11520, 534, '{"english": "What do you like doing in winter, Sam?", "chinese": "冬天你喜欢做什么，山姆？"}', 84, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11521, 534, '{"english": "I like skating.", "chinese": "我喜欢滑冰。"}', 85, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11522, 534, '{"english": "I can skate very well.", "chinese": "我能滑得很好。"}', 86, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11523, 534, '{"english": "I can skate very well too.", "chinese": "我滑冰也滑得很好。"}', 87, '2026-02-05 04:26:38', '2026-02-05 04:26:38');
INSERT INTO "course_content" VALUES (11524, 534, '{"english": "Really?", "chinese": "真的吗？"}', 88, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11525, 534, '{"english": "Sam has an idea.", "chinese": "山姆有一个主意。"}', 89, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11526, 534, '{"english": "Let''s go skating this afternoon.", "chinese": "今天下午咱们一起去滑冰吧。"}', 90, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11527, 534, '{"english": "That''s a great idea!", "chinese": "好主意！"}', 91, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11528, 534, '{"english": "Sam and Billy skate on the ice.", "chinese": "山姆和比利在冰上滑冰。"}', 92, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11529, 534, '{"english": "You''re really good at skating, Billy.", "chinese": "你真的很擅长滑冰，比利。"}', 93, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11530, 534, '{"english": "Yes.", "chinese": "是的。"}', 94, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11531, 534, '{"english": "I like skating.", "chinese": "我喜欢滑冰。"}', 95, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11532, 534, '{"english": "There is a hole in the ice.", "chinese": "冰上有个洞。"}', 96, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11533, 534, '{"english": "It is behind Billy.", "chinese": "在比利的后面。"}', 97, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11534, 534, '{"english": "Look out, Billy!", "chinese": "当心，比利！"}', 98, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11535, 534, '{"english": "Help!", "chinese": "救命啊！"}', 99, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11536, 534, '{"english": "Billy is cold and wet.", "chinese": "比利又冷又湿。"}', 100, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11537, 534, '{"english": "I don''t like skating now.", "chinese": "现在我不喜欢滑冰。"}', 101, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11538, 534, '{"english": "Checkout time", "chinese": "检查时间"}', 102, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11539, 534, '{"english": "Listen and judge", "chinese": "听录音，并判断"}', 103, '2026-02-05 04:26:39', '2026-02-05 04:26:39');
INSERT INTO "course_content" VALUES (11540, 534, '{"english": "Look and say", "chinese": "看一看，说一说"}', 104, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11541, 534, '{"english": "I like ...", "chinese": "我喜欢……"}', 105, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11542, 534, '{"english": "I like ... and ...", "chinese": "我喜欢……和……"}', 106, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11543, 534, '{"english": "I like ...", "chinese": "我喜欢……"}', 107, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11544, 534, '{"english": "I like ... and ...", "chinese": "我喜欢……和……"}', 108, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11545, 534, '{"english": "Think and write", "chinese": "想一想，写一写"}', 109, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11546, 534, '{"english": "Write about your and your friends'' hobbies.", "chinese": "写一写你和你朋友的爱好。"}', 110, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11547, 534, '{"english": "My hobbies", "chinese": "我的业余爱好"}', 111, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11548, 534, '{"english": "I like ______.", "chinese": "我喜欢______。"}', 112, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11549, 534, '{"english": "I like ______ too.", "chinese": "我也喜欢______。"}', 113, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11550, 534, '{"english": "My friends'' hobbies", "chinese": "我朋友的业余爱好"}', 114, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11551, 534, '{"english": "______ likes ______.", "chinese": "______喜欢______。"}', 115, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11552, 534, '{"english": "______ likes ______ and ______.", "chinese": "______喜欢______和______。"}', 116, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11553, 534, '{"english": "______ and ______ like ______.", "chinese": "______和______喜欢______."}', 117, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11554, 534, '{"english": "Ticking time", "chinese": "评价时间"}', 118, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11555, 534, '{"english": "I can talk about hobbies.", "chinese": "我可以谈论业余爱好。"}', 119, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11556, 534, '{"english": "I can use \"like doing ...\".", "chinese": "我可以用“like doing……”。"}', 120, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11557, 534, '{"english": "I know the sound of the letter \"y\".", "chinese": "我知道字母“y”的发音。"}', 121, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11558, 535, '{"english": "Project 1 An animal school", "chinese": "实践活动一  一所动物学校"}', 1, '2026-02-05 04:26:40', '2026-02-05 04:26:40');
INSERT INTO "course_content" VALUES (11559, 535, '{"english": "Design an animal school in groups.", "chinese": "分组设计一所动物学校。"}', 2, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11560, 535, '{"english": "How many rooms are there in your animal school?", "chinese": "在你的动物学校有多少房间？"}', 3, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11561, 535, '{"english": "What rooms are they?", "chinese": "它们是什么房间？"}', 4, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11562, 535, '{"english": "Where are they?", "chinese": "它们在哪里？"}', 5, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11563, 535, '{"english": "Tick and write.", "chinese": "标一标并写一写。"}', 6, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11564, 535, '{"english": "classroom", "chinese": "教室"}', 7, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11565, 535, '{"english": "4", "chinese": "四"}', 8, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11566, 535, '{"english": "2F", "chinese": "二楼"}', 9, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11567, 535, '{"english": "music room", "chinese": "音乐室"}', 10, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11568, 535, '{"english": "art room", "chinese": "美术室"}', 11, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11569, 535, '{"english": "computer room", "chinese": "电脑室"}', 12, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11570, 535, '{"english": "table tennis room", "chinese": "乒乓球室"}', 13, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11571, 535, '{"english": "library", "chinese": "图书馆"}', 14, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11572, 535, '{"english": "Draw a room for your animal school on page 99.", "chinese": "在99页给你的动物学校画一个房间。"}', 15, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11573, 535, '{"english": "Put your rooms in the animal school.", "chinese": "把你的房间放在动物学校里面。"}', 16, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11574, 535, '{"english": "ANIMAL SCHOOL", "chinese": "动物学校"}', 17, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11575, 535, '{"english": "Draw some animal teachers and students on page 99.", "chinese": "在99页画一些动物老师和学生。"}', 18, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11576, 535, '{"english": "Tell your classmates about your animal school.", "chinese": "告诉你的同学你的动物学校。"}', 19, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11577, 535, '{"english": "This is our animal school.", "chinese": "这是我们的动物学校。"}', 20, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11578, 535, '{"english": "There''s/There are ... in the school.", "chinese": "在学校有……。"}', 21, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11579, 535, '{"english": "It''s/They''re on ... floor.", "chinese": "她/她们在……楼。"}', 22, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11580, 535, '{"english": "This is the ... room.", "chinese": "这是……房间。"}', 23, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11581, 535, '{"english": "There''s/There are ... in it.", "chinese": "里面有……。"}', 24, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11582, 535, '{"english": "Tell your classmates about the teachers and students.", "chinese": "告诉你的同学你的老师和学生。"}', 25, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11583, 535, '{"english": "There are ... teachers and ... students in the animal school.", "chinese": "在动物学校有……老师和……学生。"}', 26, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11584, 535, '{"english": "This is Rabbit.", "chinese": "这是兔子。"}', 27, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11585, 535, '{"english": "She''s a student.", "chinese": "她是一名学生。"}', 28, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11586, 535, '{"english": "She has red eyes and long ears.", "chinese": "她有红眼睛和长耳朵。"}', 29, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11587, 535, '{"english": "She likes running and jumping.", "chinese": "她喜欢跑和跳。"}', 30, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11588, 535, '{"english": "She likes reading too.", "chinese": "她也喜欢阅读。"}', 31, '2026-02-05 04:26:41', '2026-02-05 04:26:41');
INSERT INTO "course_content" VALUES (11589, 536, '{"english": "Unit 5 What do they do?", "chinese": "第五单元  他们是做什么工作的？"}', 1, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11590, 536, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11591, 536, '{"english": "What does your father do, Mike?", "chinese": "你爸爸是做什么工作的，迈克？"}', 3, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11592, 536, '{"english": "My father is a teacher.", "chinese": "我爸爸是一名老师。"}', 4, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11593, 536, '{"english": "He teaches English.", "chinese": "他教英语。"}', 5, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11594, 536, '{"english": "He has a lot of students.", "chinese": "他有很多学生。"}', 6, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11595, 536, '{"english": "That''s nice.", "chinese": "那很好啊。"}', 7, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11596, 536, '{"english": "What about your mother?", "chinese": "你妈妈呢？"}', 8, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11597, 536, '{"english": "Is she an English teacher too?", "chinese": "她也是一名英语老师吗？"}', 9, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11598, 536, '{"english": "No, she isn''t.", "chinese": "不，她不是的。"}', 10, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11599, 536, '{"english": "She''s a writer.", "chinese": "她是一个作家。"}', 11, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11600, 536, '{"english": "She writes stories.", "chinese": "她写故事。"}', 12, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11601, 536, '{"english": "She works at home.", "chinese": "她在家里工作。"}', 13, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11602, 536, '{"english": "a cook", "chinese": "厨师"}', 14, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11603, 536, '{"english": "a doctor", "chinese": "医生"}', 15, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11604, 536, '{"english": "a driver", "chinese": "司机"}', 16, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11605, 536, '{"english": "a farmer", "chinese": "农民"}', 17, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11606, 536, '{"english": "Tip Pay attention to teaches and helps.", "chinese": "小贴士 注意“teaches”和“helps”。"}', 18, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11607, 536, '{"english": "See page 91.", "chinese": "看91页。"}', 19, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11608, 536, '{"english": "What does your father do, Su Hai?", "chinese": "你爸爸是做什么工作的，苏海？"}', 20, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11609, 536, '{"english": "My father is a doctor.", "chinese": "我爸爸是一名医生。"}', 21, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11610, 536, '{"english": "He helps sick people.", "chinese": "他帮助生病的人。"}', 22, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11611, 536, '{"english": "That''s great!", "chinese": "太棒了！"}', 23, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11612, 536, '{"english": "What does your mother do?", "chinese": "你妈妈是做什么工作的？"}', 24, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11613, 536, '{"english": "My mother is a factory worker.", "chinese": "我妈妈是一名工厂工人。"}', 25, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11614, 536, '{"english": "She makes sweets.", "chinese": "她做糖果。"}', 26, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11615, 536, '{"english": "Oh, really?", "chinese": "噢，真的吗？"}', 27, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11616, 536, '{"english": "I like sweets!", "chinese": "我喜欢糖果！"}', 28, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11617, 536, '{"english": "I eat a lot of sweets.", "chinese": "我吃很多糖。"}', 29, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11618, 536, '{"english": "a nurse", "chinese": "护士"}', 30, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11619, 536, '{"english": "a policeman", "chinese": "警察"}', 31, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11620, 536, '{"english": "a teacher", "chinese": "老师"}', 32, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11621, 536, '{"english": "a worker", "chinese": "工人"}', 33, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11622, 536, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 34, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
INSERT INTO "course_content" VALUES (11623, 536, '{"english": "What does Mike''s father do?", "chinese": "迈克的爸爸是做什么工作的？"}', 35, '2026-02-05 04:26:42', '2026-02-05 04:26:42');
