INSERT INTO "course_content" VALUES (11736, 537, '{"english": "Can he speak Chinese?", "chinese": "他会说中文吗？"}', 16, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11737, 537, '{"english": "Yes, he can.", "chinese": "是的，他会。"}', 17, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11738, 537, '{"english": "Does he have Chinese lessons at school?", "chinese": "他在学校上中文课吗？"}', 18, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11739, 537, '{"english": "No, he doesn''t.", "chinese": "不，他不上。"}', 19, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11740, 537, '{"english": "He studies Chinese after school.", "chinese": "他放学后学中文。"}', 20, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11741, 537, '{"english": "What subjects does he like?", "chinese": "他喜欢的科目是什么？"}', 21, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11742, 537, '{"english": "He likes Maths and PE.", "chinese": "他喜欢数学和体育。"}', 22, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11743, 537, '{"english": "Does he like playing football?", "chinese": "他喜欢踢足球吗？"}', 23, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11744, 537, '{"english": "Yes, he does.", "chinese": "是的。"}', 24, '2026-02-05 04:26:45', '2026-02-05 04:26:45');
INSERT INTO "course_content" VALUES (11745, 537, '{"english": "He likes swimming too.", "chinese": "他也喜欢游泳。"}', 25, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11746, 537, '{"english": "Tip What do PRC, UK and US stand for?", "chinese": "小贴士 PRC、UK和US分别表示什么？"}', 26, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11747, 537, '{"english": "See page 91.", "chinese": "看91页。"}', 27, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11748, 537, '{"english": "PRC", "chinese": "中国"}', 28, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11749, 537, '{"english": "UK", "chinese": "英国"}', 29, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11750, 537, '{"english": "US", "chinese": "美国"}', 30, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11751, 537, '{"english": "Think and write", "chinese": "想一想，写一写"}', 31, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11752, 537, '{"english": "Where does he live?", "chinese": "他住在哪里？"}', 32, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11753, 537, '{"english": "How old is he?", "chinese": "他多大了？"}', 33, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11754, 537, '{"english": "What does he like doing?", "chinese": "他喜欢做什么？"}', 34, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11755, 537, '{"english": "What subjects does he like?", "chinese": "他喜欢什么科目？"}', 35, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11756, 537, '{"english": "What does he do after school?", "chinese": "放学后他做什么？"}', 36, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11757, 537, '{"english": "Peter", "chinese": "彼得"}', 37, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11758, 537, '{"english": "Think and say", "chinese": "想一想，说一说"}', 38, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11759, 537, '{"english": "Peter is ... e-friend.", "chinese": "彼得是……网友。"}', 39, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11760, 537, '{"english": "He lives in ...", "chinese": "他住在……"}', 40, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11761, 537, '{"english": "He''s ... years old.", "chinese": "他……岁了。"}', 41, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11762, 537, '{"english": "He ... speak Chinese.", "chinese": "他……说中文。"}', 42, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11763, 537, '{"english": "He ... Maths and PE.", "chinese": "他……数学和体育。"}', 43, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11764, 537, '{"english": "He ... Chinese lessons at school.", "chinese": "在学校他……中文课？"}', 44, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11765, 537, '{"english": "He studies Chinese ...", "chinese": "他……学中文。"}', 45, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11766, 537, '{"english": "He likes playing ...", "chinese": "他喜欢……"}', 46, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11767, 537, '{"english": "Grammar time", "chinese": "语法时间"}', 47, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11768, 537, '{"english": "Do you have an e-friend? Do they like swimming? Does he have Chinese lessons? Does she like singing?", "chinese": "你有网友吗？ 他们喜欢游泳吗？ 他上语文课吗？ 她喜欢唱歌吗？"}', 48, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11769, 537, '{"english": "Yes, I/they do.  Yes, he/she/does.", "chinese": "是的，我/他们有/喜欢。 是的，他/她/有/喜欢。"}', 49, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11770, 537, '{"english": "No, I/they don''t.  No, he/she doesn''t.", "chinese": "不，我/他们没有/不喜欢。 不，他/她没有/不喜欢。"}', 50, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11771, 537, '{"english": "What subjects do you/they like? What subjects does he/she like?", "chinese": "你（们）/他们喜欢什么科目？ 他/她喜欢什么科目？"}', 51, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11772, 537, '{"english": "I/They like English.  I/They like Chinese.  He/She likes Maths and PE.  He/She likes Music and Art.", "chinese": "我/他们喜欢英语。 我/他们喜欢语文。 他/她喜欢数学和体育。 他/她喜欢音乐和美术。"}', 52, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11773, 537, '{"english": "live→lives", "chinese": "居住"}', 53, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11774, 537, '{"english": "study→studies", "chinese": "学习"}', 54, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
