INSERT INTO "course_content" VALUES (11776, 537, '{"english": "Ask and guess", "chinese": "问一问，猜一猜"}', 56, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11777, 537, '{"english": "TOM", "chinese": "汤姆"}', 57, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11778, 537, '{"english": "Is it a girl?", "chinese": "它是一个女孩吗？"}', 58, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11779, 537, '{"english": "No.", "chinese": "不是。"}', 59, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11780, 537, '{"english": "Does he like playing football?", "chinese": "他喜欢踢足球吗？"}', 60, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11781, 537, '{"english": "Yes, he does.", "chinese": "是的。"}', 61, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11782, 537, '{"english": "Does he swim well?", "chinese": "他游泳游得好吗？"}', 62, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11783, 537, '{"english": "No, he doesn''t.", "chinese": "不好。"}', 63, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11784, 537, '{"english": "TOM", "chinese": "汤姆"}', 64, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11785, 537, '{"english": "It''s Tom.", "chinese": "是汤姆。"}', 65, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11786, 537, '{"english": "You''re right.", "chinese": "你说对了。"}', 66, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11787, 537, '{"english": "Sound time", "chinese": "发音时间"}', 67, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11788, 537, '{"english": "w", "chinese": ""}', 68, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11789, 537, '{"english": "In winter, water turns to ice,", "chinese": "冬天，水变成冰，"}', 69, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11790, 537, '{"english": "And sometimes it snows.", "chinese": "有时还下雪。"}', 70, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11791, 537, '{"english": "So when the winter weather comes,", "chinese": "所以，当冬天来临的时候，"}', 71, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11792, 537, '{"english": "We always wear warm clothes!", "chinese": "我们总是穿暖和的衣服！"}', 72, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11793, 537, '{"english": "watch", "chinese": "观看"}', 73, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11794, 537, '{"english": "water", "chinese": "水"}', 74, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11795, 537, '{"english": "week", "chinese": "周，星期"}', 75, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11796, 537, '{"english": "winter", "chinese": "冬天"}', 76, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11797, 537, '{"english": "woman", "chinese": "女人"}', 77, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11798, 537, '{"english": "Culture time", "chinese": "文化时间"}', 78, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11799, 537, '{"english": "We write Chinese addresses like this.", "chinese": "我们像这样写中文地址。"}', 79, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11800, 537, '{"english": "We write English addresses like this.", "chinese": "我们像这样写英文地址。"}', 80, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11801, 537, '{"english": "Cartoon time", "chinese": "卡通时间"}', 81, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11802, 537, '{"english": "Bobby and Sam eat fish at a snack bar.", "chinese": "鲍比和山姆在小吃店吃鱼。"}', 82, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11803, 537, '{"english": "Let''s go fishing tomorrow.", "chinese": "明天我们一起去钓鱼吧。"}', 83, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11804, 537, '{"english": "OK, but I''m not good at fishing.", "chinese": "好啊，但是我不擅长钓鱼。"}', 84, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11805, 537, '{"english": "Don''t worry, Bobby.", "chinese": "不要担心，鲍比。"}', 85, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11806, 537, '{"english": "I can teach you.", "chinese": "我可以教你。"}', 86, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11807, 537, '{"english": "Bobby and Sam sit by the river.", "chinese": "鲍比和山姆坐在河边。"}', 87, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11808, 537, '{"english": "What do fish eat, Sam?", "chinese": "鱼吃什么，山姆？"}', 88, '2026-02-05 04:26:46', '2026-02-05 04:26:46');
INSERT INTO "course_content" VALUES (11809, 537, '{"english": "They eat apples.", "chinese": "它们吃苹果。"}', 89, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11810, 537, '{"english": "Do they eat oranges too?", "chinese": "它们也吃橘子吗？"}', 90, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11811, 537, '{"english": "Yes, they do.", "chinese": "是的。"}', 91, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11812, 537, '{"english": "Now, Sam has many fish, but Bobby does not have any.", "chinese": "现在，山姆有很多鱼，但是鲍比什么也没有。"}', 92, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11813, 537, '{"english": "You''re really good at fishing, Sam.", "chinese": "你真的很擅长钓鱼，山姆。"}', 93, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11814, 537, '{"english": "Yes!", "chinese": "是的！"}', 94, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11815, 537, '{"english": "Look!", "chinese": "看！"}', 95, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11816, 537, '{"english": "I don''t have any fish.", "chinese": "我没有鱼。"}', 96, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11817, 537, '{"english": "Bobby waits and waits.", "chinese": "鲍比等啊等。"}', 97, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11818, 537, '{"english": "I don''t eat oranges!", "chinese": "我不吃橘子！"}', 98, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11819, 537, '{"english": "Checkout time", "chinese": "检查时间"}', 99, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11820, 537, '{"english": "Listen and tick", "chinese": "听一听，标一标"}', 100, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11821, 537, '{"english": "What does Wang Fang''s father do?", "chinese": "王芳的爸爸是做什么工作的？"}', 101, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11822, 537, '{"english": "What subjects does Wang Fang like?", "chinese": "王芳喜欢什么科目？"}', 102, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11823, 537, '{"english": "What does Wang Fang like doing after school?", "chinese": "放学后王芳喜欢做什么？"}', 103, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11824, 537, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 104, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11825, 537, '{"english": "Who''s your friend?", "chinese": "谁是你的朋友？"}', 105, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11826, 537, '{"english": "...  is my friend.", "chinese": "……是我的朋友。"}', 106, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11827, 537, '{"english": "How old is he/she?", "chinese": "他/她多大了？"}', 107, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11828, 537, '{"english": "He''s/She''s ...", "chinese": "他/她……"}', 108, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11829, 537, '{"english": "What subjects does he/she like?", "chinese": "他/她喜欢什么科目？"}', 109, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11830, 537, '{"english": "He/She likes ...", "chinese": "他/她喜欢……"}', 110, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11831, 537, '{"english": "What does he/she like doing after school?", "chinese": "放学后他/她喜欢做什么？"}', 111, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11832, 537, '{"english": "He/She likes ...", "chinese": "他/她喜欢……"}', 112, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11833, 537, '{"english": "Write and say", "chinese": "写一写，说一说"}', 113, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11834, 537, '{"english": "What do you know about your e-friends ?", "chinese": "你知道你的网友什么？"}', 114, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11835, 537, '{"english": "Complete the chart and then talk about them.", "chinese": "完成表格，然后谈论一下他们。"}', 115, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11836, 537, '{"english": "English", "chinese": "英语"}', 116, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11837, 537, '{"english": "11", "chinese": "十一"}', 117, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11838, 537, '{"english": "swimming", "chinese": "游泳"}', 118, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11839, 537, '{"english": "Linda", "chinese": "琳达"}', 119, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11840, 537, '{"english": "Canada", "chinese": "加拿大"}', 120, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11841, 537, '{"english": "My e-friends", "chinese": "我的网友"}', 121, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
INSERT INTO "course_content" VALUES (11842, 537, '{"english": "Linda is my e-friend.", "chinese": "琳达是我的网友。"}', 122, '2026-02-05 04:26:47', '2026-02-05 04:26:47');
