INSERT INTO "course_content" VALUES (11950, 538, '{"english": "always", "chinese": "总是，一直"}', 99, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11951, 538, '{"english": "usually", "chinese": "通常"}', 100, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11952, 538, '{"english": "often", "chinese": "经常"}', 101, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11953, 538, '{"english": "sometimes", "chinese": "有时"}', 102, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11954, 538, '{"english": "At weekends, Mary often visits her grandparents.", "chinese": "周末玛丽经常拜访她的祖父母。"}', 103, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11955, 538, '{"english": "She sometimes goes to the park with her parents.", "chinese": "她有时和她的父母去公园。"}', 104, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11956, 538, '{"english": "Think and write", "chinese": "想一想，写一写"}', 105, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11957, 538, '{"english": "What do you and your friends do at weekends?", "chinese": "你和你的朋友在周末做什么？"}', 106, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11958, 538, '{"english": "I usually ______ at weekends.", "chinese": "周末我通常______。"}', 107, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11959, 538, '{"english": "I often ______.", "chinese": "我经常______。"}', 108, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11960, 538, '{"english": "I sometimes ______.", "chinese": "我有时______。"}', 109, '2026-02-05 04:26:50', '2026-02-05 04:26:50');
INSERT INTO "course_content" VALUES (11961, 538, '{"english": "My friend ______ always ______.", "chinese": "我的朋友______总是______。"}', 110, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11962, 538, '{"english": "He/She usually ______.", "chinese": "他/她通常______。"}', 111, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11963, 538, '{"english": "He/She sometimes ______.", "chinese": "他/她有时______。"}', 112, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11964, 538, '{"english": "Ticking time", "chinese": "评价时间"}', 113, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11965, 538, '{"english": "I can talk about weekend activities.", "chinese": "我可以谈论周末的活动。"}', 114, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11966, 538, '{"english": "I can use \"always\", \"usually\", \"often\" and \"sometimes\".", "chinese": "我可以用“always”“usually”“often”和“sometimes”。"}', 115, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11967, 538, '{"english": "I know the sound of the letter \"s\".", "chinese": "我知道字母“s”的发音。"}', 116, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11968, 539, '{"english": "Unit 8 At Christmas", "chinese": "第八单元 在圣诞节"}', 1, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11969, 539, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11970, 539, '{"english": "Tip Learn more about Western holidays.", "chinese": "小贴士 了解更多的西方节日。"}', 3, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11971, 539, '{"english": "See page 91.", "chinese": "看91页。"}', 4, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11972, 539, '{"english": "We always have a lot of fun at Christmas.", "chinese": "在圣诞节我们总是有很多乐趣。"}', 5, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11973, 539, '{"english": "First, we buy presents for our family and friends.", "chinese": "首先，我们给我们的家人和朋友买礼物。"}', 6, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11974, 539, '{"english": "We also buy a Christmas tree.", "chinese": "我们也买了一棵圣诞树。"}', 7, '2026-02-05 04:26:51', '2026-02-05 04:26:51');
INSERT INTO "course_content" VALUES (11975, 539, '{"english": "We sometimes go to see Father Christmas.", "chinese": "我们有时去看圣诞老人。"}', 8, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11976, 539, '{"english": "Next, we put some pretty things on the Christmas tree.", "chinese": "接下来，我们把一些漂亮的东西挂在圣诞树上。"}', 9, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11977, 539, '{"english": "We also put our presents under the tree.", "chinese": "我们也把我们的礼物放在树下。"}', 10, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11978, 539, '{"english": "It looks great!", "chinese": "看起来太棒了！"}', 11, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11979, 539, '{"english": "a card", "chinese": "卡片"}', 12, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11980, 539, '{"english": "a Christmas tree", "chinese": "圣诞树"}', 13, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11981, 539, '{"english": "Father Christmas", "chinese": "圣诞老人"}', 14, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11982, 539, '{"english": "Then, Christmas Eve comes.", "chinese": "然后，平安夜来了。"}', 15, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11983, 539, '{"english": "We put a stocking on our beds and wait for presents.", "chinese": "我们把袜子放在床上，等待礼物。"}', 16, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11984, 539, '{"english": "Finally, it is Christmas Day!", "chinese": "最后，圣诞节到了！"}', 17, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11985, 539, '{"english": "We wake up early and open our presents.", "chinese": "我们起得很早，打开礼物。"}', 18, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11986, 539, '{"english": "We have a big lunch.", "chinese": "我们吃一顿丰盛的午餐。"}', 19, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11987, 539, '{"english": "We eat a turkey and Christmas pudding.", "chinese": "我们吃火鸡和圣诞布丁。"}', 20, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11988, 539, '{"english": "We all have a good time!", "chinese": "我们过得很愉快！"}', 21, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11989, 539, '{"english": "a present", "chinese": "礼物"}', 22, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11990, 539, '{"english": "a stocking", "chinese": "长筒袜"}', 23, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11991, 539, '{"english": "a turkey", "chinese": "火鸡；火鸡肉"}', 24, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11992, 539, '{"english": "Read and match", "chinese": "读一读，连一连"}', 25, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11993, 539, '{"english": "People buy presents.", "chinese": "人们买礼物。"}', 26, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11994, 539, '{"english": "People put pretty things on the Christmas tree.", "chinese": "人们把漂亮的东西挂在圣诞树上。"}', 27, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11995, 539, '{"english": "Children put a stocking on the beds.", "chinese": "孩子们把袜子放在床上。"}', 28, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11996, 539, '{"english": "They open presents.", "chinese": "他们打开礼物。"}', 29, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11997, 539, '{"english": "People have a big lunch on Christmas Day.", "chinese": "在圣诞节那天人们吃一顿丰盛的午餐。"}', 30, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11998, 539, '{"english": "People go to see Father Christmas.", "chinese": "人们去看圣诞老人。"}', 31, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (11999, 539, '{"english": "Grammar time", "chinese": "语法时间"}', 32, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12000, 539, '{"english": "First, we buy presents.  Next, we put pretty things on the Christmas tree.  Then, Christmas Eve comes.  Finally, it is Christmas Day.", "chinese": "首先，我们买礼物。 接着，我们在圣诞树上挂上漂亮的东西。 然后，平安夜来临。 最后，圣诞节到了。"}', 33, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12001, 539, '{"english": "First", "chinese": "首先"}', 34, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12002, 539, '{"english": "Next", "chinese": "接下来"}', 35, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12003, 539, '{"english": "Then", "chinese": "然后"}', 36, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12004, 539, '{"english": "Finally", "chinese": "最后"}', 37, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12005, 539, '{"english": "Read and write", "chinese": "读一读，写一写"}', 38, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12006, 539, '{"english": "First, we go shopping and see Father Christmas.", "chinese": "首先，我们去购物，看圣诞老人。"}', 39, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12007, 539, '{"english": "Next, we put some pretty things on the Christmas tree.", "chinese": "接下来，我们把一些漂亮的东西挂在圣诞树上。"}', 40, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12008, 539, '{"english": "What do you do at Christmas?", "chinese": "在圣诞节你做什么？"}', 41, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12009, 539, '{"english": "Then, we wait for presents.", "chinese": "然后，我们等礼物。"}', 42, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12010, 539, '{"english": "Finally, we have a big lunch with our family.", "chinese": "最后，我们和家人吃一顿丰盛的午餐。"}', 43, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12011, 539, '{"english": "Fun time", "chinese": "娱乐时间"}', 44, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12012, 539, '{"english": "Make and say", "chinese": "做一做，说一说"}', 45, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12013, 539, '{"english": "First, fold a card.", "chinese": "首先，折叠卡片。"}', 46, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12014, 539, '{"english": "Next, draw a picture.", "chinese": "接下来，画一幅图。"}', 47, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12015, 539, '{"english": "Then, write your message.", "chinese": "然后，写下你的祝福。"}', 48, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12016, 539, '{"english": "Finally, write your name.", "chinese": "最后，写下你的名字。"}', 49, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12017, 539, '{"english": "Happy New Year!", "chinese": "新年快乐！"}', 50, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12018, 539, '{"english": "Here''s a New Year card for you.", "chinese": "这里有一张新年贺卡送给你。"}', 51, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12019, 539, '{"english": "Thank you!", "chinese": "谢谢你！"}', 52, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12020, 539, '{"english": "Sound time", "chinese": "发音时间"}', 53, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12021, 539, '{"english": "j", "chinese": ""}', 54, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12022, 539, '{"english": "Don''t jump up, little dog!", "chinese": "不要跳起来，小狗！"}', 55, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12023, 539, '{"english": "You''ll get juice on my jacket.", "chinese": "你会把果汁弄到我的夹克上。"}', 56, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12024, 539, '{"english": "Don''t jump up, little cat!", "chinese": "不要跳起来，小猫！"}', 57, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12025, 539, '{"english": "You''ll get yourself wet.", "chinese": "你会把自己弄湿。"}', 58, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12026, 539, '{"english": "jacket", "chinese": "夹克"}', 59, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12027, 539, '{"english": "juice", "chinese": "果汁"}', 60, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12028, 539, '{"english": "jump", "chinese": "跳"}', 61, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12029, 539, '{"english": "subject", "chinese": "科目"}', 62, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12030, 539, '{"english": "Song time", "chinese": "歌曲时间"}', 63, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12031, 539, '{"english": "We wish you a Merry Christmas", "chinese": "我们祝你圣诞快乐"}', 64, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12032, 539, '{"english": "We wish you a Mer- ry Christ- mas.", "chinese": "歌词大意：我们祝你圣诞快乐。"}', 65, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12033, 539, '{"english": "We wish you a Mer-ry Christ- mas.", "chinese": "我们祝你圣诞快乐。"}', 66, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12034, 539, '{"english": "We wish you a Mer-ry Christ-mas and a Hap- py New Year.", "chinese": "我们祝你圣诞快乐，并且新年快乐。"}', 67, '2026-02-05 04:26:52', '2026-02-05 04:26:52');
INSERT INTO "course_content" VALUES (12035, 540, '{"english": "Project 2 Our friends", "chinese": "实践活动二  我们的朋友"}', 1, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12036, 540, '{"english": "What do you know about your friends?", "chinese": "你知道你的朋友什么？"}', 2, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12037, 540, '{"english": "Ask and answer the questions about your classmates'' friends.", "chinese": "问一问并回答有关你同学的朋友的问题。"}', 3, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12038, 540, '{"english": "What''s your friend''s name?", "chinese": "你朋友的名字是什么？"}', 4, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12039, 540, '{"english": "His/Her name is ...", "chinese": "他的/她的名字是……"}', 5, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12040, 540, '{"english": "How old is he/she?", "chinese": "他/她多大了？"}', 6, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12041, 540, '{"english": "He''s/She''s ...", "chinese": "他/她……"}', 7, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12042, 540, '{"english": "What do his/her parents do?", "chinese": "他/她父母是做什么工作的？"}', 8, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12043, 540, '{"english": "His/Her father is ...", "chinese": "他的/她的爸爸是……"}', 9, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12044, 540, '{"english": "His/Her mother is ...", "chinese": "他的/她的妈妈是……"}', 10, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12045, 540, '{"english": "What subjects does he/she like?", "chinese": "他/她喜欢什么科目？"}', 11, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12046, 540, '{"english": "He/She likes ...", "chinese": "他/她喜欢……"}', 12, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12047, 540, '{"english": "He''s/She''s good at ...", "chinese": "他/她擅长……"}', 13, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12048, 540, '{"english": "What does he/she like doing after school?", "chinese": "放学后他/她喜欢做什么？"}', 14, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12049, 540, '{"english": "He/She likes ...", "chinese": "他/她喜欢……"}', 15, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12050, 540, '{"english": "What does he/she do at weekends?", "chinese": "在周末他/她做什么？"}', 16, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12051, 540, '{"english": "He/She often ...", "chinese": "他/她经常……"}', 17, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12052, 540, '{"english": "He/She sometimes ...", "chinese": "他/她有时……"}', 18, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12053, 540, '{"english": "What does he/she do on New Year''s Day?", "chinese": "在春节那天他/她做什么？"}', 19, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12054, 540, '{"english": "He/She usually ...", "chinese": "他/她通常……"}', 20, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
INSERT INTO "course_content" VALUES (12055, 540, '{"english": "Name", "chinese": "名字"}', 21, '2026-02-05 04:26:53', '2026-02-05 04:26:53');
