INSERT INTO "course_content" VALUES (12273, 543, '{"english": "Unit 1 Cinderella", "chinese": "第一单元  灰姑娘"}', 1, '2026-02-05 04:27:00', '2026-02-05 04:27:00');
INSERT INTO "course_content" VALUES (12274, 543, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12275, 543, '{"english": "There is a party at the prince''s house, but Cinderella cannot go.", "chinese": "王子家里有一场晚会，但是灰姑娘不能去。"}', 3, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12276, 543, '{"english": "Cinderella, come and help me!", "chinese": "灰姑娘，过来帮我吧！"}', 4, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12277, 543, '{"english": "Cinderella, where are my gloves?", "chinese": "灰姑娘，我的手套在哪儿？"}', 5, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12278, 543, '{"english": "A fairy comes.", "chinese": "一个仙女来了。"}', 6, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12279, 543, '{"english": "Why are you so sad, dear?", "chinese": "为什么你会如此伤心，亲爱的？"}', 7, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12280, 543, '{"english": "Because I can''t go to the party.", "chinese": "因为我不能去晚会。"}', 8, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12281, 543, '{"english": "Why?", "chinese": "为什么？"}', 9, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12282, 543, '{"english": "Because I don''t have any nice clothes or shoes.", "chinese": "因为我没有任何漂亮的衣服和鞋子。"}', 10, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12283, 543, '{"english": "Let me help you.", "chinese": "让我来帮你吧。"}', 11, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12284, 543, '{"english": "put on", "chinese": "穿上"}', 12, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12285, 543, '{"english": "take off", "chinese": "脱下"}', 13, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12286, 543, '{"english": "Unit 1", "chinese": "第一单元"}', 14, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12287, 543, '{"english": "Cinderella puts on the new clothes and shoes.", "chinese": "灰姑娘穿上了新衣服和新鞋子。"}', 15, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12288, 543, '{"english": "Come back before 12 o''clock.", "chinese": "在12点以前要回来。"}', 16, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12289, 543, '{"english": "Cinderella has a good time at the party.", "chinese": "灰姑娘在晚会上过得很开心。"}', 17, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12290, 543, '{"english": "Sorry, I have to go now.", "chinese": "对不起，我现在必须得走了。"}', 18, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12291, 543, '{"english": "Hey, your shoe!", "chinese": "嘿，你的鞋！"}', 19, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12292, 543, '{"english": "The prince visits every house.", "chinese": "王子拜访了每一户人家。"}', 20, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12293, 543, '{"english": "Many girls try on the shoe, but it does not fit.", "chinese": "许多姑娘都试穿那只鞋子，但是都不合脚。"}', 21, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12294, 543, '{"english": "Finally, Cinderella tries it on.", "chinese": "最后，灰姑娘试穿了。"}', 22, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12295, 543, '{"english": "It fits!", "chinese": "它很合适！"}', 23, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12296, 543, '{"english": "Read and match", "chinese": "读一读并连一连"}', 24, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12297, 543, '{"english": "Cinderella has a good time at the party.", "chinese": "灰姑娘在晚会上过得很开心。"}', 25, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12298, 543, '{"english": "Cinderella goes home at 12 o''clock.", "chinese": "灰姑娘在12点回家。"}', 26, '2026-02-05 04:27:01', '2026-02-05 04:27:01');
INSERT INTO "course_content" VALUES (12299, 543, '{"english": "Many girls try on the shoe.", "chinese": "许多姑娘都试穿那只鞋子。"}', 27, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12300, 543, '{"english": "Cinderella tries on the shoe.", "chinese": "灰姑娘试穿那只鞋子。"}', 28, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12301, 543, '{"english": "Ask and answer", "chinese": "问一问并答一答"}', 29, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12302, 543, '{"english": "Where''s the party?", "chinese": "晚会在哪儿？"}', 30, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12303, 543, '{"english": "Who can''t go to the party?", "chinese": "谁不能去晚会？"}', 31, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12304, 543, '{"english": "Why?", "chinese": "为什么？"}', 32, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12305, 543, '{"english": "Who helps Cinderella?", "chinese": "谁帮助灰姑娘？"}', 33, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12306, 543, '{"english": "When does Cinderella have to come back?", "chinese": "灰姑娘必须在什么时候回家？"}', 34, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12307, 543, '{"english": "Whose shoe do the girls try on?", "chinese": "姑娘们试穿的是谁的鞋子？"}', 35, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12308, 543, '{"english": "Unit 1", "chinese": "第一单元"}', 36, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12309, 543, '{"english": "Grammar time", "chinese": "语法时间"}', 37, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12310, 543, '{"english": "Why are you so sad? Why can''t you go to the party?", "chinese": "你为什么这么难过？ 你为什么不能去参加聚会？"}', 38, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12311, 543, '{"english": "Because I can''t go to the party. Because I don''t have any nice clothes or shoes.", "chinese": "因为我不能去参加聚会。 因为我没有漂亮的衣服和鞋子。"}', 39, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12312, 543, '{"english": "can''t = cannot", "chinese": "不能"}', 40, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12313, 543, '{"english": "don''t = do not", "chinese": "不要"}', 41, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12314, 543, '{"english": "come→comes", "chinese": "来"}', 42, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12315, 543, '{"english": "put→puts", "chinese": "放，安置"}', 43, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
