INSERT INTO "course_content" VALUES (12328, 543, '{"english": "Why can''t I go to the party?", "chinese": "为什么我不能去晚会呢？"}', 56, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12329, 543, '{"english": "Because ...", "chinese": "因为……"}', 57, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12330, 543, '{"english": "You''re sad, dear.", "chinese": "你很伤心，亲爱的。"}', 58, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12331, 543, '{"english": "Why?", "chinese": "为什么？"}', 59, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12332, 543, '{"english": "Because ...", "chinese": "因为……"}', 60, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12333, 543, '{"english": "Why can''t you go to the party?", "chinese": "你为什么不能去晚会？"}', 61, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12334, 543, '{"english": "Because ...", "chinese": "因为……"}', 62, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12335, 543, '{"english": "I have to go now.", "chinese": "我现在必须得走了。"}', 63, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12336, 543, '{"english": "Why?", "chinese": "为什么？"}', 64, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12337, 543, '{"english": "Because ...", "chinese": "因为……"}', 65, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12338, 543, '{"english": "Oh, my foot hurts!", "chinese": "噢，我的脚好痛！"}', 66, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12339, 543, '{"english": "Why?", "chinese": "为什么？"}', 67, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
INSERT INTO "course_content" VALUES (12340, 543, '{"english": "Because ...", "chinese": "因为……"}', 68, '2026-02-05 04:27:02', '2026-02-05 04:27:02');
