INSERT INTO "course_content" VALUES (12343, 543, '{"english": "dr", "chinese": "dr"}', 71, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12344, 543, '{"english": "Andrew is having a drink.", "chinese": "安德鲁在喝一杯饮料。"}', 72, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12345, 543, '{"english": "It''s cold and blue.", "chinese": "那是凉的且是蓝色的。"}', 73, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12346, 543, '{"english": "Andrea is drawing a dress", "chinese": "安德莉亚在画一条裙子"}', 74, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12347, 543, '{"english": "For her friend Sue.", "chinese": "给她的朋友苏。"}', 75, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
