INSERT INTO "course_content" VALUES (12350, 543, '{"english": "drink", "chinese": "饮料"}', 78, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12351, 543, '{"english": "driver", "chinese": "司机"}', 79, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
