INSERT INTO "course_content" VALUES (12353, 543, '{"english": "I like reading fairy tales.", "chinese": "我喜欢读童话故事。"}', 81, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12354, 543, '{"english": "I like reading stories about the Monkey King and Nezha.", "chinese": "我喜欢读关于猴王和哪吒的故事。"}', 82, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12355, 543, '{"english": "Cartoon time", "chinese": "卡通时间"}', 83, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12356, 543, '{"english": "Bobby and Sam are in the forest.", "chinese": "波比和山姆在森林里。"}', 84, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12357, 543, '{"english": "Do you have any snacks, Sam?", "chinese": "你有零食吗，山姆？"}', 85, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12358, 543, '{"english": "I''m very hungry.", "chinese": "我非常饿。"}', 86, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12359, 543, '{"english": "No, I don''t.", "chinese": "我没有。"}', 87, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12360, 543, '{"english": "Bobby finds some mushrooms under a tree.", "chinese": "波比在一棵树下找到了一些蘑菇。"}', 88, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12361, 543, '{"english": "Hurry up, Bobby.", "chinese": "快点，波比。"}', 89, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12362, 543, '{"english": "It''s late.", "chinese": "我们要晚了。"}', 90, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12363, 543, '{"english": "Look!", "chinese": "看！"}', 91, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12364, 543, '{"english": "There are some mushrooms.", "chinese": "有一些蘑菇。"}', 92, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12365, 543, '{"english": "We can eat them.", "chinese": "我们可以吃它们。"}', 93, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12366, 543, '{"english": "Unit 1", "chinese": "第一单元"}', 94, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12367, 543, '{"english": "Bobby picks a big red mushroom.", "chinese": "波比摘了一个大的红蘑菇。"}', 95, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12368, 543, '{"english": "Would you like one?", "chinese": "你想要一个吗？"}', 96, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12369, 543, '{"english": "No, Bobby!", "chinese": "不，波比!"}', 97, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12370, 543, '{"english": "We can''t eat them.", "chinese": "我们不能吃它们。"}', 98, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12371, 543, '{"english": "Bobby does not understand.", "chinese": "波比不明白。"}', 99, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12372, 543, '{"english": "Why?", "chinese": "为什么？"}', 100, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12373, 543, '{"english": "They look so nice.", "chinese": "它们看起来很漂亮。"}', 101, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12374, 543, '{"english": "Because these mushrooms are bad for us!", "chinese": "因为这些蘑菇对我们有害。"}', 102, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12375, 543, '{"english": "Oh, what a pity!", "chinese": "噢，多遗憾啊！"}', 103, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12376, 543, '{"english": "Checkout time", "chinese": "检测时间"}', 104, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12377, 543, '{"english": "Look and write", "chinese": "看一看并写一写"}', 105, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12378, 543, '{"english": "Why is Yang Ling not at school today?", "chinese": "为什么杨玲今天没在学校？"}', 106, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12379, 543, '{"english": "Because______.", "chinese": "因为__________。"}', 107, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12380, 543, '{"english": "Why is Liu Tao so happy?", "chinese": "为什么刘涛如此高兴？"}', 108, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12381, 543, '{"english": "Because______.", "chinese": "因为__________。"}', 109, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12382, 543, '{"english": "Why does Nancy take off her coat?", "chinese": "为什么南希脱掉她的外套？"}', 110, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12383, 543, '{"english": "Because______.", "chinese": "因为__________。"}', 111, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12384, 543, '{"english": "Why does Mike put on his jacket?", "chinese": "为什么迈克穿上他的夹克衫？"}', 112, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12385, 543, '{"english": "Because______.", "chinese": "因为__________。"}', 113, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12386, 543, '{"english": "Unit 1", "chinese": "第一单元"}', 114, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12387, 543, '{"english": "Think and write", "chinese": "想一想并写一写"}', 115, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12388, 543, '{"english": "There is a party at the prince''s house.", "chinese": "王子家里有一场晚会。"}', 116, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12389, 543, '{"english": "All the girls can go, but Cinderella cannot.", "chinese": "所有的女孩都可以去，但是灰姑娘不能去。"}', 117, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12390, 543, '{"english": "She does not have any nice clothes or shoes.", "chinese": "她没有漂亮的衣服和鞋子。"}', 118, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12391, 543, '{"english": "The fairy helps Cinderella.", "chinese": "仙女帮助了灰姑娘。"}', 119, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12392, 543, '{"english": "Cinderella has beautiful clothes and shoes.", "chinese": "灰姑娘有了漂亮的衣服和鞋子。"}', 120, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12393, 543, '{"english": "She can go to the party now.", "chinese": "她现在可以去晚会了。"}', 121, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12394, 543, '{"english": "Cinderella has a good time at the party.", "chinese": "灰姑娘在晚会上过得很开心。"}', 122, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12395, 543, '{"english": "The prince likes her very much.", "chinese": "王子非常喜欢她。"}', 123, '2026-02-05 04:27:03', '2026-02-05 04:27:03');
INSERT INTO "course_content" VALUES (12396, 543, '{"english": "Cinderella goes home at 12 o''clock.", "chinese": "灰姑娘在12点回家。"}', 124, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12397, 543, '{"english": "She leaves a shoe behind.", "chinese": "她掉了一只鞋。"}', 125, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12398, 543, '{"english": "It fits well.", "chinese": "它很合适。"}', 126, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12399, 543, '{"english": "The prince visits every house.", "chinese": "王子拜访了每一户人家。"}', 127, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12400, 543, '{"english": "Many girls try on the shoe, but it does not fit.", "chinese": "许多姑娘都试穿那只鞋子，但是都不合脚。"}', 128, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12401, 543, '{"english": "Finally, Cinderella tries it on.", "chinese": "最后，灰姑娘试穿了。"}', 129, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12402, 543, '{"english": "Ticking time", "chinese": "打勾时间"}', 130, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12403, 543, '{"english": "I can understand \"Cinderella\".", "chinese": "我能理解“灰姑娘”。"}', 131, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12404, 543, '{"english": "I can use \"why\" and \"because\" to ask and answer questions.", "chinese": "我能用“why”和“because”来询问和回答问题。"}', 132, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12405, 543, '{"english": "I know the sound of \"dr\".", "chinese": "我知道“dr”的发音。"}', 133, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12406, 544, '{"english": "Unit 2 How do you come to school?", "chinese": "第二单元  你是怎样来学校的？"}', 1, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12407, 544, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
INSERT INTO "course_content" VALUES (12408, 544, '{"english": "Do you like your new home, Su Hai?", "chinese": "你喜欢你的新家吗，苏海？"}', 3, '2026-02-05 04:27:04', '2026-02-05 04:27:04');
