INSERT INTO "course_content" VALUES (12452, 544, '{"english": "Where do you live? Where do they live? Where does he live? Where does she live?", "chinese": "你住在哪里？ 他们住在哪里？ 他住在哪里？ 她住在哪里？"}', 47, '2026-02-05 04:27:05', '2026-02-05 04:27:05');
