INSERT INTO "course_content" VALUES (12455, 544, '{"english": "I come to school by bus. We come to school by taxi. They come to school by car. He comes to school by metro. She comes to school on foot.", "chinese": "我是坐公共汽车来学校的。 我们是坐出租车来学校的。 他们是坐车来学校的。 他是坐地铁来学校的。 她是步行来学校的。"}', 50, '2026-02-05 04:27:06', '2026-02-05 04:27:06');
