INSERT INTO "course_content" VALUES (12491, 544, '{"english": "Bobby has a new bike.", "chinese": "波比有一辆新自行车。"}', 86, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12492, 544, '{"english": "He likes riding it in the park.", "chinese": "他喜欢在公园里骑自行车。"}', 87, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12493, 544, '{"english": "This bike is cool!", "chinese": "这辆自行车真酷!"}', 88, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12494, 544, '{"english": "I can fly now!", "chinese": "我现在能飞了!"}', 89, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12495, 544, '{"english": "Bobby wants to show his bike to Sam.", "chinese": "波比想向山姆展示他的自行车。"}', 90, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12496, 544, '{"english": "Dad, can I go to school by bike?", "chinese": "爸爸，我能骑自行车去学校吗？"}', 91, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12497, 544, '{"english": "No, you can''t.", "chinese": "不，你不能。"}', 92, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12498, 544, '{"english": "Why?", "chinese": "为什么？"}', 93, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
INSERT INTO "course_content" VALUES (12499, 544, '{"english": "Because you''re too young.", "chinese": "因为你太小了。"}', 94, '2026-02-05 04:27:07', '2026-02-05 04:27:07');
