INSERT INTO "course_content" VALUES (12501, 544, '{"english": "Bobby is not happy.", "chinese": "波比很不开心。"}', 96, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12502, 544, '{"english": "How does Sam go to School?", "chinese": "山姆是怎样去上学的？"}', 97, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12503, 544, '{"english": "He goes to school by bike.", "chinese": "他骑自行车去上学的。"}', 98, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12504, 544, '{"english": "Bobby''s dad does not think so.", "chinese": "波比的爸爸并不这么认为。"}', 99, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12505, 544, '{"english": "Really?", "chinese": "真的吗？"}', 100, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12506, 544, '{"english": "Yes, but he always sits in the basket.", "chinese": "是的，但是他总是坐在篮子里。"}', 101, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12507, 544, '{"english": "Checkout time", "chinese": "检测时间"}', 102, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
