INSERT INTO "course_content" VALUES (12510, 544, '{"english": "We sometimes visit her ...", "chinese": "我们有时候拜访她……"}', 105, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12511, 544, '{"english": "Su Hai and Su Yang live near City Library.", "chinese": "苏海和苏阳住在城市图书馆附近。"}', 106, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12512, 544, '{"english": "They always go there ...", "chinese": "她们总是……去那儿。"}', 107, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12513, 544, '{"english": "You", "chinese": "你"}', 108, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12514, 544, '{"english": "Mr Green lives near the park.", "chinese": "格林先生住在公园附近。"}', 109, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12515, 544, '{"english": "He can get there ...", "chinese": "他可以……去那儿。"}', 110, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12516, 544, '{"english": "My uncle works on a big ship.", "chinese": "我的叔叔在一艘大轮船上工作。"}', 111, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12517, 544, '{"english": "He goes to many cities ...", "chinese": "他去许多城市……"}', 112, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12518, 544, '{"english": "Unit 2", "chinese": "第二单元"}', 113, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12519, 544, '{"english": "Think and write", "chinese": "想一想并写一写"}', 114, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12520, 544, '{"english": "Where do you live?", "chinese": "你住在哪里？"}', 115, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12521, 544, '{"english": "How do you go to school?", "chinese": "你是怎样去上学的？"}', 116, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12522, 544, '{"english": "How do your parents go to work?", "chinese": "你的父母是怎样去上班的？"}', 117, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12523, 544, '{"english": "What about your friend?", "chinese": "你的朋友呢？"}', 118, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12524, 544, '{"english": "I live ______.", "chinese": "我住在______。"}', 119, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12525, 544, '{"english": "It is near ______.", "chinese": "它在______附近。"}', 120, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12526, 544, '{"english": "I go to school ______.", "chinese": "我______去学校。"}', 121, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12527, 544, '{"english": "My father goes to work ______.", "chinese": "我的爸爸______去上班。"}', 122, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12528, 544, '{"english": "My mother goes to work ______.", "chinese": "我的妈妈______去上班。"}', 123, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12529, 544, '{"english": "My friend ______ lives ______.", "chinese": "我的朋友______住在______。"}', 124, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12530, 544, '{"english": "It is near ______.", "chinese": "它在______附近。"}', 125, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12531, 544, '{"english": "He/She goes to school ______.", "chinese": "他/她______去上学。"}', 126, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12532, 544, '{"english": "His/Her father ______.", "chinese": "他的/她的爸爸______。"}', 127, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12533, 544, '{"english": "His/Her mother ______.", "chinese": "他的/她的妈妈______。"}', 128, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12534, 544, '{"english": "Ticking time", "chinese": "打勾时间"}', 129, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12535, 544, '{"english": "I can talk about public transport.", "chinese": "我能谈论公共交通工具。"}', 130, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12536, 544, '{"english": "I can talk about where I live.", "chinese": "我能谈论我住的地方。"}', 131, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12537, 544, '{"english": "I know the sound of \"tr\".", "chinese": "我知道“tr”的发音。"}', 132, '2026-02-05 04:27:08', '2026-02-05 04:27:08');
INSERT INTO "course_content" VALUES (12538, 545, '{"english": "Unit 3 Asking the way", "chinese": "第三单元  问路"}', 1, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12539, 545, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12540, 545, '{"english": "Yang Ling wants to visit Su Hai''s new home.", "chinese": "杨玲想去拜访苏海的新家。"}', 3, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12541, 545, '{"english": "CITY LIBRARY STATION", "chinese": "城市图书馆站"}', 4, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12542, 545, '{"english": "BOOKSHOP", "chinese": "书店"}', 5, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12543, 545, '{"english": "PARK STATION", "chinese": "公园站"}', 6, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12544, 545, '{"english": "MOON STREET", "chinese": "月亮街"}', 7, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12545, 545, '{"english": "How do I get to your home, Su Hai?", "chinese": "我怎样才能到达你家，苏海？"}', 8, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12546, 545, '{"english": "You can take the metro.", "chinese": "你可以搭乘地铁。"}', 9, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12547, 545, '{"english": "You can get on the metro at Park Station and get off at City Library Station.", "chinese": "你可以在公园站上地铁，在城市图书馆站下地铁。"}', 10, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12548, 545, '{"english": "Then, walk to Moon Street.", "chinese": "然后，步行去月亮街。"}', 11, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12549, 545, '{"english": "There''s a bookshop on the street.", "chinese": "街上有一个书店。"}', 12, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12550, 545, '{"english": "My home is next to it.", "chinese": "我家就在它旁边。"}', 13, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12551, 545, '{"english": "All right.", "chinese": "好的。"}', 14, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12552, 545, '{"english": "CINEMA", "chinese": "电影院"}', 15, '2026-02-05 04:27:09', '2026-02-05 04:27:09');
INSERT INTO "course_content" VALUES (12553, 545, '{"english": "SPORTS SHOP", "chinese": "体育用品商店"}', 16, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12554, 545, '{"english": "ZOO", "chinese": "动物园"}', 17, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12555, 545, '{"english": "a cinema", "chinese": "一个电影院"}', 18, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12556, 545, '{"english": "a hospital", "chinese": "一家医院"}', 19, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12557, 545, '{"english": "a shop", "chinese": "一个商店"}', 20, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12558, 545, '{"english": "a zoo", "chinese": "一个动物园"}', 21, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12559, 545, '{"english": "Unit 3", "chinese": "第三单元"}', 22, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12560, 545, '{"english": "Yang Ling comes out from City Library Station.", "chinese": "杨玲从城市图书馆站出来。"}', 23, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12561, 545, '{"english": "She is on Sun Street.", "chinese": "她在太阳街。"}', 24, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12562, 545, '{"english": "She cannot find the bookshop.", "chinese": "她找不到那个书店。"}', 25, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12563, 545, '{"english": "She asks a policeman for help.", "chinese": "她向一个警察寻求帮助。"}', 26, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12564, 545, '{"english": "MOON STREET", "chinese": "月亮街"}', 27, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12565, 545, '{"english": "BOOKSHOP", "chinese": "书店"}', 28, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12566, 545, '{"english": "Excuse me, how do I get to the bookshop on Moon Street?", "chinese": "劳驾，我怎样才能到达月亮街的书店呢？"}', 29, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12567, 545, '{"english": "Go along this street.", "chinese": "沿着这条街走。"}', 30, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12568, 545, '{"english": "Turn right at the traffic lights.", "chinese": "在交通灯那儿右转。"}', 31, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12569, 545, '{"english": "Then, go along Moon Street.", "chinese": "然后，沿着月亮街走。"}', 32, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12570, 545, '{"english": "You can see the bookshop on your right.", "chinese": "你能看到书店就在你的右侧。"}', 33, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12571, 545, '{"english": "Thank you.", "chinese": "谢谢你。"}', 34, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12572, 545, '{"english": "get on", "chinese": "上车"}', 35, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12573, 545, '{"english": "get off", "chinese": "下车"}', 36, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12574, 545, '{"english": "turn right", "chinese": "向右转"}', 37, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12575, 545, '{"english": "turn left", "chinese": "向左转"}', 38, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12576, 545, '{"english": "Read and match", "chinese": "读一读并连一连"}', 39, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12577, 545, '{"english": "Yang Ling gets off the metro.", "chinese": "杨玲下地铁。"}', 40, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12578, 545, '{"english": "Yang Ling walks along Sun Street.", "chinese": "杨玲沿着太阳街走。"}', 41, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12579, 545, '{"english": "Yang Ling gets on the metro.", "chinese": "杨玲上地铁。"}', 42, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12580, 545, '{"english": "Yang Ling turns right at the traffic lights.", "chinese": "杨玲在交通灯那儿右转。"}', 43, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12581, 545, '{"english": "Yang Ling asks a policeman for help.", "chinese": "杨玲向一个警察求助。"}', 44, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
