INSERT INTO "course_content" VALUES (12584, 545, '{"english": "Park Station", "chinese": "公园站"}', 47, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12585, 545, '{"english": "Yang Ling''s home", "chinese": "杨玲的家"}', 48, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12586, 545, '{"english": "City Library Station", "chinese": "城市图书馆站"}', 49, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12587, 545, '{"english": "Bookshop", "chinese": "书店"}', 50, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12588, 545, '{"english": "Su Hai''s home", "chinese": "苏海的家"}', 51, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12589, 545, '{"english": "Moon Street", "chinese": "月亮街"}', 52, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12590, 545, '{"english": "Sun Street", "chinese": "太阳街"}', 53, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12591, 545, '{"english": "First, Yang Ling gets on the metro at Park Station.", "chinese": "首先，杨玲在公园站上地铁。"}', 54, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12592, 545, '{"english": "Next, ...", "chinese": "接下来，……"}', 55, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12593, 545, '{"english": "Then, she''s on Sun Street.", "chinese": "然后，她在太阳街。"}', 56, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12594, 545, '{"english": "She walks along ...", "chinese": "她沿着……走。"}', 57, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12595, 545, '{"english": "You", "chinese": "你"}', 58, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12596, 545, '{"english": "Unit 3", "chinese": "第三单元"}', 59, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
