INSERT INTO "course_content" VALUES (12598, 545, '{"english": "How do I get to the cinema? How do I get to the bookshop? How do I get to the hospital? How do I get to the zoo? How do I get to the library?", "chinese": "去电影院怎么走？ 去书店怎么走？ 去医院怎么走？ 去动物园怎么走？ 去图书馆怎么走？"}', 61, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12599, 545, '{"english": "Go along this street.", "chinese": "沿着这条街道直走。"}', 62, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12600, 545, '{"english": "Turn left at the traffic lights. Turn right at the traffic lights.", "chinese": "在红绿灯路口左转。 在红绿灯路口右转。"}', 63, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12601, 545, '{"english": "Get on the metro at Park Station. Get off the bus at City Library Station.", "chinese": "在公园站上地铁。 在市图书馆下车。"}', 64, '2026-02-05 04:27:10', '2026-02-05 04:27:10');
INSERT INTO "course_content" VALUES (12602, 545, '{"english": "You can see the bookshop on your right/left.", "chinese": "你可以在你的右手边/左手边看到图书馆。"}', 65, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12603, 545, '{"english": "Tip: These expressions are very useful.", "chinese": "小贴士：这些表达方式很有用。"}', 66, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12604, 545, '{"english": "See page 90.", "chinese": "见第90页。"}', 67, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12605, 545, '{"english": "Fun time", "chinese": "娱乐时间"}', 68, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12606, 545, '{"english": "Ask and answer", "chinese": "问与答"}', 69, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12607, 545, '{"english": "You are here.", "chinese": "你在这儿。"}', 70, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
