INSERT INTO "course_content" VALUES (12609, 545, '{"english": "Mango Street", "chinese": "芒果街"}', 72, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12610, 545, '{"english": "Apple Street", "chinese": "苹果街"}', 73, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
