INSERT INTO "course_content" VALUES (12612, 545, '{"english": "How do I get to the supermarket?", "chinese": "我怎样才能到达超市？"}', 75, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12613, 545, '{"english": "Go along ... Street.", "chinese": "沿着……街走。"}', 76, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12614, 545, '{"english": "Turn ... at the ... traffic lights.", "chinese": "在……交通灯那儿向……转。"}', 77, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12615, 545, '{"english": "Then, ...", "chinese": "然后，……"}', 78, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12616, 545, '{"english": "The supermarket is on your ...", "chinese": "超市就在你的……"}', 79, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12617, 545, '{"english": "unit 3", "chinese": "第三单元"}', 80, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12618, 545, '{"english": "Sound time", "chinese": "发音时间"}', 81, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12619, 545, '{"english": "sh", "chinese": "sh"}', 82, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12620, 545, '{"english": "Sharon is in the shoe shop.", "chinese": "莎伦在鞋店里。"}', 83, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12621, 545, '{"english": "She likes shiny shoes,", "chinese": "她喜欢闪闪发光的鞋子，"}', 84, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12622, 545, '{"english": "But there are so many.", "chinese": "但是这儿的鞋子太多了。"}', 85, '2026-02-05 04:27:11', '2026-02-05 04:27:11');
INSERT INTO "course_content" VALUES (12623, 545, '{"english": "She doesn''t know which to chooes!", "chinese": "她不知道该选哪一双!"}', 86, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12624, 545, '{"english": "sheep", "chinese": "绵羊"}', 87, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12625, 545, '{"english": "ship", "chinese": "船"}', 88, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12626, 545, '{"english": "shoe", "chinese": "鞋"}', 89, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12627, 545, '{"english": "shop", "chinese": "商店"}', 90, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12628, 545, '{"english": "Culture time", "chinese": "文化时间"}', 91, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12629, 545, '{"english": "In the UK, we ask \"Where''s the toilet?\"", "chinese": "在英国，我们说“Where''s the toilet?”。"}', 92, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12630, 545, '{"english": "In the US, we ask \"Where''s the restroom?\"", "chinese": "在美国，我们说“Where''s the restroom?”。"}', 93, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12631, 545, '{"english": "Cartoon time", "chinese": "卡通时间"}', 94, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12632, 545, '{"english": "Bobby and Tina want to see a new film.", "chinese": "波比和缇娜想去看一场新电影。"}', 95, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12633, 545, '{"english": "They want to go to City Cinema.", "chinese": "他们想去城市电影院。"}', 96, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12634, 545, '{"english": "How do we get to City Cinema?", "chinese": "我们怎样才能到达城市电影院？"}', 97, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12635, 545, '{"english": "We can go by bus.", "chinese": "我们可以坐公交车去。"}', 98, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12636, 545, '{"english": "They wait for the bus at the bus stop.", "chinese": "他们在公交站台等车。"}', 99, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12637, 545, '{"english": "A bus comes.", "chinese": "一辆公交车来了。"}', 100, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12638, 545, '{"english": "We can''t get on the bus, Tina!", "chinese": "我们上不去了，缇娜!"}', 101, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12639, 545, '{"english": "The bus is full!", "chinese": "这辆车满了!"}', 102, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12640, 545, '{"english": "OK.", "chinese": "好吧。"}', 103, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12641, 545, '{"english": "Let''s go to the cinema by taxi.", "chinese": "我们坐出租车去电影院吧。"}', 104, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12642, 545, '{"english": "Unit 3", "chinese": "第三单元"}', 105, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12643, 545, '{"english": "They get in a taxi.", "chinese": "他们上了一辆出租车。"}', 106, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12644, 545, '{"english": "There are too many cars in the street, Tina!", "chinese": "街上有太多汽车了，缇娜！"}', 107, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12645, 545, '{"english": "OK.", "chinese": "好吧。"}', 108, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12646, 545, '{"english": "Let''s take the metro.", "chinese": "我们坐地铁去吧。"}', 109, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12647, 545, '{"english": "They get to the cinema by metro, but the film is over.", "chinese": "他们乘地铁到达了电影院，但是电影已经结束了。"}', 110, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12648, 545, '{"english": "We''re too late, Bobby!", "chinese": "我们太晚了，波比！"}', 111, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12649, 545, '{"english": "Checkout time", "chinese": "检测时间"}', 112, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12650, 545, '{"english": "Point and say", "chinese": "指一指并说一说"}', 113, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12651, 545, '{"english": "How do you get to these places from your school?", "chinese": "你是怎样从你的学校到达这些地方的？"}', 114, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12652, 545, '{"english": "cinema", "chinese": "电影院"}', 115, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12653, 545, '{"english": "hospital", "chinese": "医院"}', 116, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12654, 545, '{"english": "library", "chinese": "图书馆"}', 117, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12655, 545, '{"english": "zoo", "chinese": "动物园"}', 118, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12656, 545, '{"english": "park", "chinese": "公园"}', 119, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12657, 545, '{"english": "your school", "chinese": "你的学校"}', 120, '2026-02-05 04:27:12', '2026-02-05 04:27:12');
INSERT INTO "course_content" VALUES (12658, 545, '{"english": "Brown Street", "chinese": "布朗街"}', 121, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12659, 545, '{"english": "Green Street", "chinese": "格林街"}', 122, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12660, 545, '{"english": "White Street", "chinese": "怀特街"}', 123, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12661, 545, '{"english": "Black Street", "chinese": "布莱克街"}', 124, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12662, 545, '{"english": "Excuse me, how do I get to ...?", "chinese": "劳驾，我怎样才能到达……？"}', 125, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12663, 545, '{"english": "Walk along ...", "chinese": "沿着……走，"}', 126, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12664, 545, '{"english": "Then, turn ... at ...", "chinese": "然后，在……向……转。"}', 127, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12665, 545, '{"english": "The ... is on your ...", "chinese": "……就在你的……。"}', 128, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12666, 545, '{"english": "Unit 3", "chinese": "第三单元"}', 129, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12667, 545, '{"english": "Draw and write", "chinese": "画一画并写一写"}', 130, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12668, 545, '{"english": "Where do you live?", "chinese": "你住在哪儿？"}', 131, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12669, 545, '{"english": "How do you get to your school?", "chinese": "你是怎样到达你的学校的？"}', 132, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12670, 545, '{"english": "I live on ______ Street.", "chinese": "我住在______街。"}', 133, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12671, 545, '{"english": "It is near ______.", "chinese": "它在______附近。"}', 134, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12672, 545, '{"english": "I come to school ______.", "chinese": "我______来学校。"}', 135, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12673, 545, '{"english": "First, I ______.", "chinese": "首先，我______。"}', 136, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12674, 545, '{"english": "Then, I ______.", "chinese": "然后，我______。"}', 137, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12675, 545, '{"english": "my home", "chinese": "我的家"}', 138, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12676, 545, '{"english": "my school", "chinese": "我的学校"}', 139, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12677, 545, '{"english": "Ticking time", "chinese": "打勾时间"}', 140, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12678, 545, '{"english": "I can name some places in the city.", "chinese": "我能说出城市中一些地方的名称。"}', 141, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12679, 545, '{"english": "I can ask and tell the way.", "chinese": "我能问路并指路。"}', 142, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12680, 545, '{"english": "I know the sound of \"sh\".", "chinese": "我知道“sh”的发音。"}', 143, '2026-02-05 04:27:13', '2026-02-05 04:27:13');
INSERT INTO "course_content" VALUES (12681, 546, '{"english": "Unit 4 Seeing the doctor", "chinese": "第四单元  看医生"}', 1, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12682, 546, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12683, 546, '{"english": "Su Hai is ill.", "chinese": "苏海生病了。"}', 3, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12684, 546, '{"english": "She goes to see the doctor.", "chinese": "她去看医生。"}', 4, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12685, 546, '{"english": "What''s wrong with you?", "chinese": "你怎么了？"}', 5, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12686, 546, '{"english": "I have a headache.", "chinese": "我头痛。"}', 6, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12687, 546, '{"english": "I feel cold.", "chinese": "我感觉很冷。"}', 7, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12688, 546, '{"english": "Let me check.", "chinese": "让我来检查一下。"}', 8, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12689, 546, '{"english": "You have a fever.", "chinese": "你发烧了。"}', 9, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12690, 546, '{"english": "What should I do, Doctor?", "chinese": "我应该做什么，医生？"}', 10, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12691, 546, '{"english": "You should have a rest at home.", "chinese": "你应该在家休息。"}', 11, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12692, 546, '{"english": "You should take some medicine and drink some warm water.", "chinese": "你应该吃一些药并喝一些温水。"}', 12, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12693, 546, '{"english": "Thank you, Doctor.", "chinese": "谢谢你，医生。"}', 13, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12694, 546, '{"english": "brush one''s teeth", "chinese": "刷牙"}', 14, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12695, 546, '{"english": "drink water", "chinese": "喝水"}', 15, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12696, 546, '{"english": "eat sweets", "chinese": "吃糖"}', 16, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12697, 546, '{"english": "Unit 4", "chinese": "第四单元"}', 17, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12698, 546, '{"english": "Mike has a toothache.", "chinese": "迈克牙疼。"}', 18, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12699, 546, '{"english": "He goes to see the dentist.", "chinese": "他去看牙医。"}', 19, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12700, 546, '{"english": "What''s wrong with you?", "chinese": "你怎么了？"}', 20, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12701, 546, '{"english": "I have a toothache.", "chinese": "我牙疼。"}', 21, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12702, 546, '{"english": "I can''t eat anything!", "chinese": "我什么也吃不了!"}', 22, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12703, 546, '{"english": "Do you eat a lot of sweets?", "chinese": "你吃很多糖果吗？"}', 23, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12704, 546, '{"english": "Yes, I do.", "chinese": "是的。"}', 24, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12705, 546, '{"english": "You shouldn''t eat too many sweets.", "chinese": "你不应该吃太多糖果。"}', 25, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12706, 546, '{"english": "You should brush your teeth in the morning and before bedtime.", "chinese": "你应该在早上和就寝时间之前刷牙。"}', 26, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12707, 546, '{"english": "OK.", "chinese": "好的。"}', 27, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12708, 546, '{"english": "Thanks.", "chinese": "谢谢。"}', 28, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12709, 546, '{"english": "Tip: Can you make more phrases?", "chinese": "小贴士：你能组成更多的词组吗？"}', 29, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12710, 546, '{"english": "See page 90.", "chinese": "见第90页。"}', 30, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12711, 546, '{"english": "have a rest", "chinese": "休息"}', 31, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12712, 546, '{"english": "take medicine", "chinese": "吃药"}', 32, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12713, 546, '{"english": "Ask and answer", "chinese": "问与答"}', 33, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12714, 546, '{"english": "What''s wrong with Su Hai?", "chinese": "苏海怎么了？"}', 34, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12715, 546, '{"english": "What should she do?", "chinese": "她应该做什么？"}', 35, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12716, 546, '{"english": "What''s wrong with Mike?", "chinese": "迈克怎么了？"}', 36, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12717, 546, '{"english": "Why does he have a toothache?", "chinese": "他为什么会牙疼？"}', 37, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12718, 546, '{"english": "What should he do?", "chinese": "他应该做什么？"}', 38, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12719, 546, '{"english": "Think and write", "chinese": "想一想并写一写"}', 39, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12720, 546, '{"english": "I have a headache and a fever.", "chinese": "我头痛并发烧。"}', 40, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12721, 546, '{"english": "I should have a rest at home.", "chinese": "我应该在家休息。"}', 41, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12722, 546, '{"english": "I should take some medicine and drink some warm water too.", "chinese": "我也应该吃一些药并喝一些温水。"}', 42, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12723, 546, '{"english": "I have a toothache.", "chinese": "我牙疼。"}', 43, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12724, 546, '{"english": "I cannot eat anything.", "chinese": "我什么也吃不了。"}', 44, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12725, 546, '{"english": "I should not eat too many sweets.", "chinese": "我不应该吃太多糖果。"}', 45, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12726, 546, '{"english": "I should brush my teeth in the morning and before bedtime.", "chinese": "我应该在早上和就寝时间之前刷牙。"}', 46, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12727, 546, '{"english": "Unit 4", "chinese": "第四单元"}', 47, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12728, 546, '{"english": "Grammar time", "chinese": "语法时间"}', 48, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12729, 546, '{"english": "What''s wrong with you? What''s wrong with him? What''s wrong with her? What''s wrong with them?", "chinese": "你怎么了？ 他怎么了？ 她怎么了？ 他们怎么了？"}', 49, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12730, 546, '{"english": "I have a fever. They have a headache. He has a cold. She has a toothache.", "chinese": "我发烧了。 他们头痛。 他感冒了。 她牙疼。"}', 50, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12731, 546, '{"english": "What should I do? What should he do? What should she do? What should they do?", "chinese": "我应该怎么做？ 他应该怎么做？ 她应该怎么做？ 他们应该怎么做？"}', 51, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12732, 546, '{"english": "You/He/She/They should have a rest. You/He/She/They should take some medicine. You/He/She/They should drink warm water.", "chinese": "你/他/她/他们应该好好休息。 你/他/她/他们应该吃些药。 你/他/她/他们应该喝些温开水。"}', 52, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12733, 546, '{"english": "You shouldn''t eat too many sweets.", "chinese": "你不应该吃太多甜食。"}', 53, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12734, 546, '{"english": "shouldn''t = should not", "chinese": "不应该"}', 54, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12735, 546, '{"english": "tooth→teeth", "chinese": "牙齿"}', 55, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12736, 546, '{"english": "Fun time", "chinese": "娱乐时间"}', 56, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12737, 546, '{"english": "Do a role-play", "chinese": "角色扮演"}', 57, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12738, 546, '{"english": "Cough", "chinese": "咳嗽"}', 58, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12739, 546, '{"english": "eat ice cream", "chinese": "吃冰淇淋"}', 59, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12740, 546, '{"english": "drink warm water", "chinese": "喝温水"}', 60, '2026-02-05 04:27:14', '2026-02-05 04:27:14');
INSERT INTO "course_content" VALUES (12741, 546, '{"english": "take some medicine", "chinese": "吃一些药"}', 61, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12742, 546, '{"english": "Toothache", "chinese": "牙疼"}', 62, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12743, 546, '{"english": "eat sweets", "chinese": "吃糖"}', 63, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12744, 546, '{"english": "eat before bedtime", "chinese": "在就寝时间前吃东西"}', 64, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12745, 546, '{"english": "brush teeth before bedtime", "chinese": "在就寝时间前刷牙"}', 65, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12746, 546, '{"english": "Cold", "chinese": "感冒"}', 66, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12747, 546, '{"english": "watch TV", "chinese": "看电视"}', 67, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12748, 546, '{"english": "drink warm water", "chinese": "喝温水"}', 68, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12749, 546, '{"english": "have a rest", "chinese": "休息"}', 69, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12750, 546, '{"english": "Headache", "chinese": "头痛"}', 70, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12751, 546, '{"english": "watch TV", "chinese": "看电视"}', 71, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12752, 546, '{"english": "have a rest", "chinese": "休息"}', 72, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12753, 546, '{"english": "take some medicine", "chinese": "吃一些药"}', 73, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12754, 546, '{"english": "What''s wrong with you?", "chinese": "你怎么了？"}', 74, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12755, 546, '{"english": "I have a ...", "chinese": "我患了……"}', 75, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12756, 546, '{"english": "What should I do, Doctor?", "chinese": "我应该做什么，医生？"}', 76, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12757, 546, '{"english": "You should ...", "chinese": "你应该……"}', 77, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12758, 546, '{"english": "You shouldn''t ...", "chinese": "你不应该……"}', 78, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12759, 546, '{"english": "Unit 4", "chinese": "第四单元"}', 79, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12760, 546, '{"english": "Sound time", "chinese": "发音时间"}', 80, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12761, 546, '{"english": "ch", "chinese": "ch"}', 81, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12762, 546, '{"english": "Charlie is sitting on a bench,", "chinese": "查理坐在一个长凳上，"}', 82, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12763, 546, '{"english": "Eating chicken for his lunch.", "chinese": "他正吃着鸡肉来作为他的午餐。"}', 83, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12764, 546, '{"english": "He likes Chinese food very much.", "chinese": "他非常喜欢中国食物。"}', 84, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12765, 546, '{"english": "He''s going to China in March!", "chinese": "他打算在三月去中国!"}', 85, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12766, 546, '{"english": "chair", "chinese": "椅子"}', 86, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12767, 546, '{"english": "chicken", "chinese": "鸡肉"}', 87, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12768, 546, '{"english": "lunch", "chinese": "午餐"}', 88, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12769, 546, '{"english": "much", "chinese": "非常"}', 89, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12770, 546, '{"english": "teach", "chinese": "教"}', 90, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12771, 546, '{"english": "Culture time", "chinese": "文化时间"}', 91, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12772, 546, '{"english": "You have a fever.", "chinese": "你发烧了。"}', 92, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12773, 546, '{"english": "Your temperature is 102℉.", "chinese": "你的体温是华氏102度。"}', 93, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12774, 546, '{"english": "102?", "chinese": "102？"}', 94, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12775, 546, '{"english": "It''s 39℃.", "chinese": "就是39摄氏度。"}', 95, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12776, 546, '{"english": "Cartoon time", "chinese": "卡通时间"}', 96, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12777, 546, '{"english": "Bobby helps in the hospital.", "chinese": "波比在医院里帮忙。"}', 97, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12778, 546, '{"english": "Monkey, Rabbit and Elephant come to see him.", "chinese": "猴子，兔子和大象来看他。"}', 98, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12779, 546, '{"english": "What''s wrong with you?", "chinese": "你们怎么了？"}', 99, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12780, 546, '{"english": "My arm hurts.", "chinese": "我的胳膊疼。"}', 100, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12781, 546, '{"english": "My ear hurts.", "chinese": "我的耳朵疼。"}', 101, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12782, 546, '{"english": "My nose hurts.", "chinese": "我的鼻子疼。"}', 102, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12783, 546, '{"english": "Bobby is very happy to help them.", "chinese": "波比很愿意帮助他们。"}', 103, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12784, 546, '{"english": "OK.", "chinese": "好吧。"}', 104, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12785, 546, '{"english": "How do you feel now?", "chinese": "你们现在感觉怎么样？"}', 105, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12786, 546, '{"english": "I can''t write now!", "chinese": "我现在写不了字！"}', 106, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12787, 546, '{"english": "I can''t hear well now!", "chinese": "我现在听不清了!"}', 107, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12788, 546, '{"english": "I can''t eat or drink now!", "chinese": "我现在不能吃也不能喝！"}', 108, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12789, 546, '{"english": "You should have a rest today.", "chinese": "你们今天都需要休息。"}', 109, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12790, 546, '{"english": "Unit 4", "chinese": "第四单元"}', 110, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12791, 546, '{"english": "Then, Giraffe comes to the hospital.", "chinese": "接着，长颈鹿来到医院。"}', 111, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12792, 546, '{"english": "Can you help me, Bobby?", "chinese": "你能帮我吗，波比？"}', 112, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12793, 546, '{"english": "Sure.", "chinese": "当然。"}', 113, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12794, 546, '{"english": "What''s wrong with you?", "chinese": "你怎么了？"}', 114, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12795, 546, '{"english": "Giraffe points at his long neck.", "chinese": "长颈鹿指了指他的长脖子。"}', 115, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12796, 546, '{"english": "My neck hurts.", "chinese": "我的脖子疼。"}', 116, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12797, 546, '{"english": "Oh no!", "chinese": "噢不！"}', 117, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12798, 546, '{"english": "Checkout time", "chinese": "检测时间"}', 118, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12799, 546, '{"english": "Think and write", "chinese": "想一想并写一写"}', 119, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12800, 546, '{"english": "What should they do?", "chinese": "他们应该做什么？"}', 120, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12801, 546, '{"english": "What shouldn''t they do?", "chinese": "他们不应该做什么？"}', 121, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12802, 546, '{"english": "He feels hot.", "chinese": "他感觉很热。"}', 122, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12803, 546, '{"english": "He should take off his jacket.", "chinese": "他应该脱下他的夹克衫。"}', 123, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12804, 546, '{"english": "She feels cold.", "chinese": "她感觉很冷。"}', 124, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12805, 546, '{"english": "She should put on her coat.", "chinese": "她应该穿上她的外套。"}', 125, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12806, 546, '{"english": "She likes eating sweets.", "chinese": "她喜欢吃糖。"}', 126, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12807, 546, '{"english": "She sometimes has a toothache.", "chinese": "她有时候牙疼。"}', 127, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12808, 546, '{"english": "She should brush her teeth in the morning and before bedtime.", "chinese": "她应该在早上和就寝时间之前刷牙。"}', 128, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12809, 546, '{"english": "She should not eat too many sweets.", "chinese": "她不应该吃太多糖果。"}', 129, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12810, 546, '{"english": "She has a headache.", "chinese": "她头痛。"}', 130, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12811, 546, '{"english": "She feels tired.", "chinese": "她觉得很累。"}', 131, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12812, 546, '{"english": "She should not watch TV.", "chinese": "她不应该看电视。"}', 132, '2026-02-05 04:27:15', '2026-02-05 04:27:15');
INSERT INTO "course_content" VALUES (12813, 546, '{"english": "She should have a rest.", "chinese": "她应该休息。"}', 133, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12814, 546, '{"english": "They are in the library.", "chinese": "他们在图书馆里。"}', 134, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12815, 546, '{"english": "They should not talk.", "chinese": "他们不应该交谈。"}', 135, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12816, 546, '{"english": "They should not eat or drink either.", "chinese": "他们不应该吃东西和喝东西。"}', 136, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12817, 546, '{"english": "Unit 4", "chinese": "第四单元"}', 137, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12818, 546, '{"english": "Listen and choose", "chinese": "听一听并选一选"}', 138, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12819, 546, '{"english": "What is wrong with Tim?", "chinese": "提姆怎么了？"}', 139, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12820, 546, '{"english": "How does he feel?", "chinese": "他感觉怎么样？"}', 140, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12821, 546, '{"english": "What should he do?", "chinese": "他应该做什么？"}', 141, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12822, 546, '{"english": "Ticking time", "chinese": "打勾时间"}', 142, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12823, 546, '{"english": "I can talk about illnesses.", "chinese": "我能谈论疾病。"}', 143, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12824, 546, '{"english": "I can use\"should\" and \"should not\" to give advice.", "chinese": "我能用“should”和“should not”提建议。"}', 144, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12825, 546, '{"english": "I know the sound of \"ch\".", "chinese": "我知道“ch”的发音。"}', 145, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12826, 547, '{"english": "Project 1 Around our city", "chinese": "课题1  我们的城市周围"}', 1, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12827, 547, '{"english": "Work in groups.", "chinese": "小组练习。"}', 2, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12828, 547, '{"english": "Draw a map of your city on page 99.", "chinese": "在第99页上画一张你所在城市的地图。"}', 3, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12829, 547, '{"english": "Mark your homes and school on the map.", "chinese": "在地图上标记出你的家和学校。"}', 4, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12830, 547, '{"english": "Where do you live?", "chinese": "你住在哪儿？"}', 5, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12831, 547, '{"english": "I live in ... Town/on ... Street.", "chinese": "我住在……小镇/……街。"}', 6, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12832, 547, '{"english": "Where''s our school?", "chinese": "我们的学校在哪儿？"}', 7, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12833, 547, '{"english": "It''s on ... Street.", "chinese": "它在……街。"}', 8, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12834, 547, '{"english": "Mark these places on the map.", "chinese": "在地图上标记出这些地方。"}', 9, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12835, 547, '{"english": "museum", "chinese": "博物馆"}', 10, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12836, 547, '{"english": "restaurant", "chinese": "餐馆"}', 11, '2026-02-05 04:27:16', '2026-02-05 04:27:16');
INSERT INTO "course_content" VALUES (12837, 547, '{"english": "post office", "chinese": "邮局"}', 12, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12838, 547, '{"english": "bookshop", "chinese": "书店"}', 13, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12839, 547, '{"english": "cinema", "chinese": "电影院"}', 14, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12840, 547, '{"english": "hospital", "chinese": "医院"}', 15, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12841, 547, '{"english": "supermarket", "chinese": "超市"}', 16, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12842, 547, '{"english": "bank", "chinese": "银行"}', 17, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12843, 547, '{"english": "Where''s the museum?", "chinese": "博物馆在哪儿？"}', 18, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12844, 547, '{"english": "It''s on ... Street.", "chinese": "它在……街。"}', 19, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12845, 547, '{"english": "Where''s the hospital?", "chinese": "医院在哪儿？"}', 20, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12846, 547, '{"english": "It''s on ... Street.", "chinese": "它在……街。"}', 21, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12847, 547, '{"english": "How do you get to school?", "chinese": "你是怎样到达学校的？"}', 22, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12848, 547, '{"english": "Show and tell your class.", "chinese": "向全班展示一下。"}', 23, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12849, 547, '{"english": "I come to school ...", "chinese": "我……来学校。"}', 24, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12850, 547, '{"english": "First, I ...", "chinese": "首先，我……"}', 25, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12851, 547, '{"english": "Next, I ...", "chinese": "接下来，我……"}', 26, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12852, 547, '{"english": "Then, I ...", "chinese": "然后，我……"}', 27, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12853, 547, '{"english": "I live in ... Town/on ... Street.", "chinese": "我住在……小镇/……街。"}', 28, '2026-02-05 04:27:17', '2026-02-05 04:27:17');
INSERT INTO "course_content" VALUES (12854, 547, '{"english": "How do you get to the places in B?", "chinese": "你是怎样到达B部分中的那些地方的？"}', 29, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12855, 547, '{"english": "Show and tell your class.", "chinese": "向全班展示一下。"}', 30, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12856, 547, '{"english": "I take ... to go to the ...", "chinese": "我乘……去……"}', 31, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12857, 547, '{"english": "I get on ... and get off ...", "chinese": "我在……上车，在……下车。"}', 32, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12858, 547, '{"english": "Then, I ...", "chinese": "然后，我……"}', 33, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12859, 548, '{"english": "Unit 5 Helping our parents", "chinese": "第五单元  帮助我们的父母"}', 1, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12860, 548, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12861, 548, '{"english": "It is Saturday morning.", "chinese": "现在是周六早上。"}', 3, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12862, 548, '{"english": "My father is cleaning the car.", "chinese": "我爸爸在洗车。"}', 4, '2026-02-05 04:27:18', '2026-02-05 04:27:18');
INSERT INTO "course_content" VALUES (12863, 548, '{"english": "I am helping him.", "chinese": "我在帮他。"}', 5, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12864, 548, '{"english": "My mother is cooking breakfast in the kitchen.", "chinese": "我妈妈在厨房里做早餐。"}', 6, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12865, 548, '{"english": "Helen is in the living room.", "chinese": "海伦在客厅里。"}', 7, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12866, 548, '{"english": "She is sweeping the floor.", "chinese": "她在扫地。"}', 8, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12867, 548, '{"english": "Where is Tim?", "chinese": "提姆在哪儿？"}', 9, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12868, 548, '{"english": "What is he doing now?", "chinese": "他正在做什么？"}', 10, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12869, 548, '{"english": "Tim is in his bedroom.", "chinese": "提姆在他的房间里。"}', 11, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12870, 548, '{"english": "He is sleeping.", "chinese": "他正在睡觉。"}', 12, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12871, 548, '{"english": "Ben the dog is sleeping too.", "chinese": "小狗本也在睡觉。"}', 13, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12872, 548, '{"english": "clean the car", "chinese": "洗车"}', 14, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12873, 548, '{"english": "clean the table", "chinese": "擦桌子"}', 15, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12874, 548, '{"english": "make the bed", "chinese": "整理床铺"}', 16, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12875, 548, '{"english": "Unit 5", "chinese": "第五单元"}', 17, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12876, 548, '{"english": "In the afternoon, my cousin Jim comes.", "chinese": "在下午，我的表弟吉姆来了。"}', 18, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12877, 548, '{"english": "What are we doing now?", "chinese": "我们现在在做什么？"}', 19, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12878, 548, '{"english": "My mother is busy.", "chinese": "我妈妈很忙。"}', 20, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12879, 548, '{"english": "She is cooking dinner.", "chinese": "她正在做晚餐。"}', 21, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12880, 548, '{"english": "Helen and I are helping her.", "chinese": "我和海伦正在帮她。"}', 22, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12881, 548, '{"english": "Helen is washing the dishes.", "chinese": "海伦在洗碗。"}', 23, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12882, 548, '{"english": "I am cleaning the table.", "chinese": "我在擦桌子。"}', 24, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12883, 548, '{"english": "What are Tim and Jim doing?", "chinese": "提姆和吉姆在做什么？"}', 25, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12884, 548, '{"english": "They are eating fruit in the living room.", "chinese": "他们在客厅里吃水果。"}', 26, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12885, 548, '{"english": "We''re watching TV too!", "chinese": "我们也在看电视！"}', 27, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12886, 548, '{"english": "Woof!", "chinese": "汪！"}', 28, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12887, 548, '{"english": "sweep the floor", "chinese": "扫地"}', 29, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12888, 548, '{"english": "wash clothes", "chinese": "洗衣服"}', 30, '2026-02-05 04:27:19', '2026-02-05 04:27:19');
INSERT INTO "course_content" VALUES (12889, 548, '{"english": "wash the dishes", "chinese": "洗碗"}', 31, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12890, 548, '{"english": "Match and say", "chinese": "连一连并说一说"}', 32, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12891, 548, '{"english": "Are Mike and Helen helping their parents?", "chinese": "迈克和海伦在帮助他们的父母吗？"}', 33, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12892, 548, '{"english": "What are they doing?", "chinese": "他们在做什么？"}', 34, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12893, 548, '{"english": "Mike is helping his parents.", "chinese": "迈克在帮他的父母。"}', 35, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12894, 548, '{"english": "He''s ...", "chinese": "他在……"}', 36, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12895, 548, '{"english": "You", "chinese": "你"}', 37, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12896, 548, '{"english": "Think and write", "chinese": "想一想并写一写"}', 38, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12897, 548, '{"english": "What are they doing in the morning and in the afternoon?", "chinese": "他们在早上和下午都在做什么？"}', 39, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12898, 548, '{"english": "In the morning", "chinese": "在早上"}', 40, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12899, 548, '{"english": "In the afternoon", "chinese": "在下午"}', 41, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12900, 548, '{"english": "cleaning the car", "chinese": "洗车"}', 42, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12901, 548, '{"english": "Unit 5", "chinese": "第五单元"}', 43, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12902, 548, '{"english": "Grammar time", "chinese": "语法时间"}', 44, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12903, 548, '{"english": "What are you doing? What are they doing? What is he doing? What is she doing?", "chinese": "你（们）在做什么？ 他们在做什么？ 他在做什么？ 她在做什么？"}', 45, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12904, 548, '{"english": "I am sweeping the floor. We are watching TV. They are eating fruit. He is sleeping. She is washing the dishes.", "chinese": "我在扫地。 我们在看电视。 他们在吃水果。 他在睡觉。 她在洗碗。"}', 46, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12905, 548, '{"english": "Tip: Pay attention to these words.", "chinese": "小贴士：注意这些单词的形式。"}', 47, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12906, 548, '{"english": "See page 91.", "chinese": "见第91页。"}', 48, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12907, 548, '{"english": "do→doing", "chinese": "做"}', 49, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12908, 548, '{"english": "clean→cleaning", "chinese": "打扫"}', 50, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12909, 548, '{"english": "cook→cooking", "chinese": "烹调"}', 51, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12910, 548, '{"english": "eat→eating", "chinese": "吃"}', 52, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12911, 548, '{"english": "help→helping", "chinese": "帮助"}', 53, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12912, 548, '{"english": "wash→washing", "chinese": "洗"}', 54, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12913, 548, '{"english": "watch→watching", "chinese": "看"}', 55, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12914, 548, '{"english": "Fun time", "chinese": "娱乐时间"}', 56, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12915, 548, '{"english": "Ask and answer", "chinese": "问与答"}', 57, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12916, 548, '{"english": "START", "chinese": "开始"}', 58, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12917, 548, '{"english": "FINISH", "chinese": "结束"}', 59, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12918, 548, '{"english": "What''s he/she doing?", "chinese": "他/她在做什么？"}', 60, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12919, 548, '{"english": "What are they doing?", "chinese": "他们在做什么？"}', 61, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12920, 548, '{"english": "He''s/She''s/They''re ...", "chinese": "他在/她在/他们在……"}', 62, '2026-02-05 04:27:20', '2026-02-05 04:27:20');
INSERT INTO "course_content" VALUES (12921, 548, '{"english": "Unit 5", "chinese": "第五单元"}', 63, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12922, 548, '{"english": "Sound time", "chinese": "发音时间"}', 64, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12923, 548, '{"english": "ing", "chinese": "ing"}', 65, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12924, 548, '{"english": "In the morning, I like to sing", "chinese": "在早上，我喜欢唱歌"}', 66, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12925, 548, '{"english": "And watch the flowers growing.", "chinese": "以及看着花儿生长。"}', 67, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12926, 548, '{"english": "In the evening, I like to sit.", "chinese": "在晚上，我喜欢静坐。"}', 68, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12927, 548, '{"english": "And listen to the wind blowing.", "chinese": "并听着风吹的声音。"}', 69, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12928, 548, '{"english": "bring", "chinese": "带来"}', 70, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12929, 548, '{"english": "morning", "chinese": "早上"}', 71, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12930, 548, '{"english": "sing", "chinese": "唱歌"}', 72, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12931, 548, '{"english": "spring", "chinese": "春天"}', 73, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12932, 548, '{"english": "Song time", "chinese": "歌曲时间"}', 74, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12933, 548, '{"english": "Polly, put the kettle on", "chinese": "波利，把壶放到炉子上"}', 75, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12934, 548, '{"english": "Polly, put the kettle on.", "chinese": "歌词大意： 波利，把壶放到炉子上。"}', 76, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12935, 548, '{"english": "Polly, put the kettle on.", "chinese": "波利，把壶放到炉子上。"}', 77, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12936, 548, '{"english": "Polly, put the kettle on.", "chinese": "波利，把壶放到炉子上。"}', 78, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12937, 548, '{"english": "We''ll all have tea.", "chinese": "我们都要喝茶。"}', 79, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12938, 548, '{"english": "Susie, take it off again.", "chinese": "苏茜，把壶拿下来吧。"}', 80, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12939, 548, '{"english": "Susie, take it off again.", "chinese": "苏茜，把壶拿下来吧。"}', 81, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12940, 548, '{"english": "Susie, take it off again.", "chinese": "苏茜，把壶拿下来吧。"}', 82, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12941, 548, '{"english": "They''ve all gone away.", "chinese": "他们都走了。"}', 83, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12942, 548, '{"english": "Cartoon time", "chinese": "卡通时间"}', 84, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12943, 548, '{"english": "Bobby grows grapes in his garden.", "chinese": "波比在他的花园里种葡萄。"}', 85, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12944, 548, '{"english": "My grapes are big and sweet.", "chinese": "我的葡萄又大又甜。"}', 86, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12945, 548, '{"english": "There are some pests on the grapes.", "chinese": "葡萄上有一些害虫。"}', 87, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12946, 548, '{"english": "What are you doing here?", "chinese": "你们在这儿干什么？"}', 88, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12947, 548, '{"english": "We''re eating your grapes.", "chinese": "我们在吃你的葡萄。"}', 89, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12948, 548, '{"english": "They''re so sweet!", "chinese": "它们真甜!"}', 90, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12949, 548, '{"english": "Unit 5", "chinese": "第五单元"}', 91, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12950, 548, '{"english": "Then, some ladybirds come.", "chinese": "然后，一些瓢虫来了。"}', 92, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12951, 548, '{"english": "We can help you!", "chinese": "我们可以帮助你。"}', 93, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12952, 548, '{"english": "Thank you!", "chinese": "谢谢你们！"}', 94, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12953, 548, '{"english": "The pests go away, but the ladybirds do not.", "chinese": "害虫离开了，但是瓢虫没走。"}', 95, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12954, 548, '{"english": "What are you doing?", "chinese": "你们在做什么？"}', 96, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12955, 548, '{"english": "We''re eating the leaves.", "chinese": "我们在吃叶子。"}', 97, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12956, 548, '{"english": "(To be continued)", "chinese": "（未完待续）"}', 98, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12957, 548, '{"english": "Checkout time", "chinese": "检测时间"}', 99, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12958, 548, '{"english": "Look and write", "chinese": "看一看并写一写"}', 100, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12959, 548, '{"english": "What are the children doing?", "chinese": "孩子们在做什么？"}', 101, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12960, 548, '{"english": "Liu Tao is making the bed.", "chinese": "刘涛在整理床铺。"}', 102, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12961, 548, '{"english": "Su Hai is washing the dishes.", "chinese": "苏海在洗碗。"}', 103, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12962, 548, '{"english": "Nancy is sweeping the floor.", "chinese": "南希在扫地。"}', 104, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12963, 548, '{"english": "Yang Ling is doing her homework.", "chinese": "杨玲在做家庭作业。"}', 105, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12964, 548, '{"english": "Wang Bing is cleaning the table.", "chinese": "王冰在擦桌子。"}', 106, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12965, 548, '{"english": "Mike is washing clothes.", "chinese": "迈克在洗衣服。"}', 107, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12966, 548, '{"english": "Unit 5", "chinese": "第五单元"}', 108, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12967, 548, '{"english": "Listen, number and say", "chinese": "听一听，标一标并说一说"}', 109, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12968, 548, '{"english": "Helen is in ...", "chinese": "海伦在……"}', 110, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12969, 548, '{"english": "She''s ...", "chinese": "她在……"}', 111, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12970, 548, '{"english": "You", "chinese": "你"}', 112, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12971, 548, '{"english": "Ticking time", "chinese": "打勾时间"}', 113, '2026-02-05 04:27:21', '2026-02-05 04:27:21');
INSERT INTO "course_content" VALUES (12972, 548, '{"english": "I can name some housework.", "chinese": "我能说出一些家务活的名称。"}', 114, '2026-02-05 04:27:22', '2026-02-05 04:27:22');
INSERT INTO "course_content" VALUES (12973, 548, '{"english": "I can use \"am/is/are doing\".", "chinese": "我能使用“am/is/are doing”。"}', 115, '2026-02-05 04:27:22', '2026-02-05 04:27:22');
INSERT INTO "course_content" VALUES (12974, 548, '{"english": "I know the sound of \"ing\".", "chinese": "我知道“ing”的发音。"}', 116, '2026-02-05 04:27:22', '2026-02-05 04:27:22');
INSERT INTO "course_content" VALUES (12975, 549, '{"english": "Unit 6 In the kitchen", "chinese": "第六单元   在厨房"}', 1, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12976, 549, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12977, 549, '{"english": "It is six o''clock in the evening.", "chinese": "现在是晚上6点钟。"}', 3, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12978, 549, '{"english": "Liu Tao comes home from a football game.", "chinese": "刘涛在踢完一场足球比赛以后回到家。"}', 4, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12979, 549, '{"english": "His parents are cooking dinner in the kitchen.", "chinese": "他的父母正在厨房里做晚餐。"}', 5, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12980, 549, '{"english": "That smells nice, Mum.", "chinese": "闻起来真香，妈妈。"}', 6, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12981, 549, '{"english": "Are you cooking meat?", "chinese": "你在做肉吗？"}', 7, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12982, 549, '{"english": "No, I''m not.", "chinese": "不，不是。"}', 8, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12983, 549, '{"english": "I''m washing some vegetables.", "chinese": "我在洗一些蔬菜。"}', 9, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12984, 549, '{"english": "I want to cook some tomato soup.", "chinese": "我想做些西红柿汤。"}', 10, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12985, 549, '{"english": "I''m cooking meat with potatoes, Taotao.", "chinese": "我在做土豆炒肉，涛涛。"}', 11, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12986, 549, '{"english": "Great!", "chinese": "太棒了！"}', 12, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12987, 549, '{"english": "I can''t wait, Dad!", "chinese": "我等不及了，爸爸！"}', 13, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12988, 549, '{"english": "bread", "chinese": "面包"}', 14, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12989, 549, '{"english": "meat", "chinese": "（猪、牛、羊等的）肉"}', 15, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12990, 549, '{"english": "potatoes", "chinese": "马铃薯，土豆"}', 16, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12991, 549, '{"english": "Unit 6", "chinese": "第六单元"}', 17, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12992, 549, '{"english": "Liu Tao is looking for some juice in the fridge.", "chinese": "刘涛在冰箱里找一些果汁。"}', 18, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12993, 549, '{"english": "Mum, is there any apple juice in the fridge?", "chinese": "妈妈，冰箱里还有苹果汁吗？"}', 19, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12994, 549, '{"english": "No, but there''s some orange juice.", "chinese": "没有了，但是还有一些橙汁。"}', 20, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12995, 549, '{"english": "OK, thank you.", "chinese": "好的，谢谢你。"}', 21, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12996, 549, '{"english": "Dinner is ready.", "chinese": "晚餐准备好了。"}', 22, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12997, 549, '{"english": "Liu Tao is eating the meat.", "chinese": "刘涛在吃肉。"}', 23, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12998, 549, '{"english": "How''s the meat, Taotao?", "chinese": "肉的味道怎么样，涛涛？"}', 24, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (12999, 549, '{"english": "It''s yummy, Dad.", "chinese": "太美味了，爸爸。"}', 25, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13000, 549, '{"english": "I love it!", "chinese": "我喜欢!"}', 26, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13001, 549, '{"english": "You''re a great cook!", "chinese": "你真是个很棒的厨师!"}', 27, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13002, 549, '{"english": "How''s my soup, Taotao?", "chinese": "我的汤怎么样，涛涛？"}', 28, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13003, 549, '{"english": "It''s nice, Mum.", "chinese": "汤很不错，妈妈。"}', 29, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13004, 549, '{"english": "I love it too!", "chinese": "我也喜欢!"}', 30, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13005, 549, '{"english": "soup", "chinese": "汤"}', 31, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13006, 549, '{"english": "tomatoes", "chinese": "西红柿，番茄"}', 32, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13007, 549, '{"english": "vegetables", "chinese": "蔬菜"}', 33, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13008, 549, '{"english": "Ask and answer", "chinese": "问与答"}', 34, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13009, 549, '{"english": "Who''s cooking meat?", "chinese": "谁在炒肉？"}', 35, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13010, 549, '{"english": "Who''s washing vegetables?", "chinese": "谁在洗蔬菜？"}', 36, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13011, 549, '{"english": "What''s Liu Tao looking for in the fridge?", "chinese": "刘涛在冰箱里找什么？"}', 37, '2026-02-05 04:27:23', '2026-02-05 04:27:23');
INSERT INTO "course_content" VALUES (13012, 549, '{"english": "Does Liu Tao like the meat?", "chinese": "刘涛喜欢肉吗？"}', 38, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13013, 549, '{"english": "Read and write", "chinese": "读一读并写一写"}', 39, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13014, 549, '{"english": "It is six o''clock in the evening.", "chinese": "现在是晚上6点钟。"}', 40, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13015, 549, '{"english": "My parents are cooking dinner in the kitchen.", "chinese": "我的父母在厨房里做晚餐。"}', 41, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13016, 549, '{"english": "My father is cooking meat with potatoes.", "chinese": "我爸爸在做土豆炒肉。"}', 42, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13017, 549, '{"english": "My mother is washing some vegetables.", "chinese": "我妈妈在洗一些蔬菜。"}', 43, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13018, 549, '{"english": "She wants to cook some tomato soup.", "chinese": "她想做一些西红柿汤。"}', 44, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13019, 549, '{"english": "I love the meat very much.", "chinese": "我非常喜欢肉。"}', 45, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13020, 549, '{"english": "It is yummy.", "chinese": "它很美味。"}', 46, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13021, 549, '{"english": "I love the soup too.", "chinese": "我也喜欢汤。"}', 47, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13022, 549, '{"english": "It is nice.", "chinese": "它很不错。"}', 48, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13023, 549, '{"english": "Unit 6", "chinese": "第六单元"}', 49, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13024, 549, '{"english": "Grammar time", "chinese": "语法时间"}', 50, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13025, 549, '{"english": "Are you cooking meat with potatoes? Are they cooking dinner? Is he looking for juice? Is she looking for tomatoes?", "chinese": "你在做土豆炒肉吗？ 他们在做晚餐吗？ 他在找果汁吗？ 她在找西红柿吗？"}', 51, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13026, 549, '{"english": "Yes, I am. Yes, they are. Yes, he is. Yes, she is.", "chinese": "是的，我在做土豆炒肉。 是的，他们在做饭。 是的，他在找果汁。 是的，她在找西红柿。"}', 52, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13027, 549, '{"english": "No, I''m not. No, they aren''t. No, he isn''t. No, she isn''t.", "chinese": "不，我没在做土豆炒肉。 不，他们没在做饭。 不，他没在找果汁。 不，她没在找西红柿。"}', 53, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13028, 549, '{"english": "There is some bread in the fridge. There is some meat in the fridge. There is some juice in the fridge. There is some milk in the fridge. There are three potatoes in the fridge. There are five tomatoes in the fridge.", "chinese": "冰箱里有面包。 冰箱里有肉。 冰箱里有果汁。 冰箱里有牛奶。 冰箱里有三个土豆。 冰箱里有五个西红柿。"}', 54, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13029, 549, '{"english": "potato→potatoes", "chinese": "马铃薯，土豆"}', 55, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13030, 549, '{"english": "tomato→tomatoes", "chinese": "西红柿，番茄"}', 56, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13031, 549, '{"english": "Fun time", "chinese": "娱乐时间"}', 57, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13032, 549, '{"english": "Tip: Play this game with your friends.", "chinese": "小贴士：和你的朋友们一起玩这个游戏。"}', 58, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13033, 549, '{"english": "See page 91.", "chinese": "见第91页。"}', 59, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13034, 549, '{"english": "Act and guess", "chinese": "演一演并猜一猜"}', 60, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13035, 549, '{"english": "What''s he doing?", "chinese": "他在做什么？"}', 61, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13036, 549, '{"english": "Is he drinking water?", "chinese": "他在喝水吗？"}', 62, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13037, 549, '{"english": "Yes, he is.", "chinese": "是的，他在喝水。"}', 63, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13038, 549, '{"english": "Look.", "chinese": "看。"}', 64, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13039, 549, '{"english": "What''s he doing?", "chinese": "他在做什么？"}', 65, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13040, 549, '{"english": "Is he cooking?", "chinese": "他在做饭吗？"}', 66, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13041, 549, '{"english": "No, he isn''t.", "chinese": "不，他没有。"}', 67, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13042, 549, '{"english": "He''s washing the dishes.", "chinese": "他在洗碗。"}', 68, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13043, 549, '{"english": "You win!", "chinese": "你赢了！"}', 69, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13044, 549, '{"english": "Yeah!", "chinese": "耶！"}', 70, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13045, 549, '{"english": "Unit 6", "chinese": "第六单元"}', 71, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13046, 549, '{"english": "Sound time", "chinese": "发音时间"}', 72, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13047, 549, '{"english": "qu", "chinese": "qu"}', 73, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13048, 549, '{"english": "Quick!", "chinese": "快！"}', 74, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13049, 549, '{"english": "The queen is coming", "chinese": "女王来了"}', 75, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13050, 549, '{"english": "Through our little town.", "chinese": "要穿过我们的小镇。"}', 76, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13051, 549, '{"english": "Quick!", "chinese": "快！"}', 77, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13052, 549, '{"english": "The queen is coming", "chinese": "女王来了"}', 78, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13053, 549, '{"english": "Wearing her golden crown.", "chinese": "戴着她金色的王冠。"}', 79, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13054, 549, '{"english": "queen", "chinese": "女王"}', 80, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13055, 549, '{"english": "quick", "chinese": "快的"}', 81, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13056, 549, '{"english": "quiet", "chinese": "安静的"}', 82, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13057, 549, '{"english": "quite", "chinese": "相当，很"}', 83, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13058, 549, '{"english": "Culture time", "chinese": "文化时间"}', 84, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13059, 549, '{"english": "Chinese food is famous all over the world.", "chinese": "中餐世界闻名。"}', 85, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13060, 549, '{"english": "I love Chinese food.", "chinese": "我很喜欢吃中餐。"}', 86, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13061, 549, '{"english": "Cartoon time", "chinese": "卡通时间"}', 87, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13062, 549, '{"english": "There are a lot of pests and ladybirds in Bobby''s garden now.", "chinese": "波比的花园里现在有很多的害虫和瓢虫。"}', 88, '2026-02-05 04:27:24', '2026-02-05 04:27:24');
INSERT INTO "course_content" VALUES (13063, 549, '{"english": "Sam comes to help Bobby.", "chinese": "山姆过来帮波比。"}', 89, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13064, 549, '{"english": "Look, Bobby.", "chinese": "看，波比。"}', 90, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13065, 549, '{"english": "Here are some ladybirds.", "chinese": "这儿有一些瓢虫。"}', 91, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13066, 549, '{"english": "They can help you.", "chinese": "它们可以帮助你。"}', 92, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13067, 549, '{"english": "Bobby sees two ladybirds on Sam''s hand.", "chinese": "波比看到两只瓢虫在山姆的手上。"}', 93, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13068, 549, '{"english": "He is very angry.", "chinese": "他非常生气。"}', 94, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13069, 549, '{"english": "They eat the leaves!", "chinese": "它们吃叶子！"}', 95, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13070, 549, '{"english": "They can''t help me.", "chinese": "它们帮不了我。"}', 96, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13071, 549, '{"english": "No, they don''t.", "chinese": "不，它们不会的。"}', 97, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13072, 549, '{"english": "Look.", "chinese": "看。"}', 98, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13073, 549, '{"english": "They have seven spots.", "chinese": "它们有七个点。"}', 99, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13074, 549, '{"english": "Unit 6", "chinese": "第六单元"}', 100, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13075, 549, '{"english": "Sam catches a ladybird from the grapes.", "chinese": "山姆从葡萄上抓获了一只瓢虫。"}', 101, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13076, 549, '{"english": "How many spots does this ladybird have?", "chinese": "这只瓢虫身上有几个点？"}', 102, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13077, 549, '{"english": "It has ten spots.", "chinese": "它有十个点。"}', 103, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13078, 549, '{"english": "Right.", "chinese": "没错。"}', 104, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13079, 549, '{"english": "These ladybirds eat the leaves.", "chinese": "这些瓢虫就是吃叶子的。"}', 105, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13080, 549, '{"english": "Sam''s ladybirds drive the bad ladybirds and the pests away.", "chinese": "山姆的瓢虫把坏瓢虫和害虫都赶走了。"}', 106, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13081, 549, '{"english": "Thank you, my friends.", "chinese": "谢谢你们，我的朋友们。"}', 107, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13082, 549, '{"english": "Checkout time", "chinese": "检测时间"}', 108, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13083, 549, '{"english": "Ask and answer", "chinese": "问与答"}', 109, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13084, 549, '{"english": "The children are helping in the kitchen.", "chinese": "孩子们正在厨房里帮忙。"}', 110, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13085, 549, '{"english": "Ask and answer the questions.", "chinese": "询问并回答问题。"}', 111, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13086, 549, '{"english": "Is ...?", "chinese": "……在……吗？"}', 112, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13087, 549, '{"english": "Yes, he/she is.", "chinese": "是的，他/她在。"}', 113, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13088, 549, '{"english": "No, he/she isn''t.", "chinese": "不，他/她没有。"}', 114, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13089, 549, '{"english": "Are ...?", "chinese": "……在……吗？"}', 115, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13090, 549, '{"english": "Yes, they are.", "chinese": "是的，他们在。"}', 116, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13091, 549, '{"english": "No, they aren''t.", "chinese": "不，他们没有。"}', 117, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13092, 549, '{"english": "Unit 6", "chinese": "第六单元"}', 118, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13093, 549, '{"english": "Look and write", "chinese": "看一看并写一写"}', 119, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13094, 549, '{"english": "There is two pieces of meat in the fridge.", "chinese": "冰箱里有两块肉。"}', 120, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13095, 549, '{"english": "There is one fish in the fridge.", "chinese": "冰箱里有一条鱼。"}', 121, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13096, 549, '{"english": "There are four bananas in the fridge.", "chinese": "冰箱里有四根香蕉。"}', 122, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13097, 549, '{"english": "There are five oranges in the fridge.", "chinese": "冰箱里有五个橙子。"}', 123, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13098, 549, '{"english": "There is a loaf of bread in the fridge.", "chinese": "冰箱里有一条面包。"}', 124, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13099, 549, '{"english": "There are four apples in the fridge.", "chinese": "冰箱里有四个苹果。"}', 125, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13100, 549, '{"english": "There are twelve eggs in the fridge.", "chinese": "冰箱里有12个鸡蛋。"}', 126, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13101, 549, '{"english": "There are two boxes of milk in the fridge.", "chinese": "冰箱里有两盒牛奶。"}', 127, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13102, 549, '{"english": "There are three bottles of orange juice in the fridge.", "chinese": "冰箱里有三瓶橙汁。"}', 128, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13103, 549, '{"english": "Ticking time", "chinese": "打勾时间"}', 129, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13104, 549, '{"english": "I can name some food.", "chinese": "我能说出一些食物的名称。"}', 130, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13105, 549, '{"english": "I can ask and answer \"Yes/No\" questions about actions.", "chinese": "我能询问并回答关于行为的“Yes或No”问句的问题。"}', 131, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13106, 549, '{"english": "I know the sound of \"qu\".", "chinese": "我知道“qu”的发音。"}', 132, '2026-02-05 04:27:25', '2026-02-05 04:27:25');
INSERT INTO "course_content" VALUES (13107, 550, '{"english": "Unit 7 Chinese festivals", "chinese": "第七单元   中国节日"}', 1, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13108, 550, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13109, 550, '{"english": "The Spring Festival is in January or February.", "chinese": "春节在一月或二月。"}', 3, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13110, 550, '{"english": "People also call it Chinese New Year.", "chinese": "人们也称它为中国农历新年。"}', 4, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13111, 550, '{"english": "At this festival, people get together with their families.", "chinese": "在这天，人们和他们的家人团聚。"}', 5, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13112, 550, '{"english": "Some people eat jiaozi.", "chinese": "有些人会吃饺子。"}', 6, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13113, 550, '{"english": "The Dragon Boat Festival is in May or June.", "chinese": "端午节在五月或六月。"}', 7, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13114, 550, '{"english": "There are dragon boat races in some places.", "chinese": "在一些地区会有龙舟赛。"}', 8, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13115, 550, '{"english": "People eat rice dumplings at this festival.", "chinese": "人们在这个节日吃粽子。"}', 9, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13116, 550, '{"english": "Double Ninth Festival (Chongyang Festival)", "chinese": "重阳节"}', 10, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13117, 550, '{"english": "Dragon Boat Festival", "chinese": "端午节"}', 11, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13118, 550, '{"english": "Mid-Autumn Festival", "chinese": "中秋节"}', 12, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13119, 550, '{"english": "Spring Festival", "chinese": "春节"}', 13, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13120, 550, '{"english": "Unit 7", "chinese": "第七单元"}', 14, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13121, 550, '{"english": "The Mid-Autumn Festival is in September or October.", "chinese": "中秋节在九月或十月。"}', 15, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13122, 550, '{"english": "People look at the moon at night with their families.", "chinese": "人们在晚上和他们的家人一起赏月。"}', 16, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13123, 550, '{"english": "They eat moon cakes and fruit.", "chinese": "他们吃月饼和水果。"}', 17, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13124, 550, '{"english": "The Double Ninth Festival (Chongyang Festival) is in October or November.", "chinese": "重阳节在十月或十一月。"}', 18, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13125, 550, '{"english": "It is a festival for old people.", "chinese": "这是一个老年人的节日。"}', 19, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13126, 550, '{"english": "People visit their parents and grandparents.", "chinese": "人们看望他们的父母和祖父母。"}', 20, '2026-02-05 04:27:26', '2026-02-05 04:27:26');
INSERT INTO "course_content" VALUES (13127, 550, '{"english": "They also climb mountains and eat rice cakes at this festival.", "chinese": "他们还会在这天爬山、吃重阳糕。"}', 21, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13128, 550, '{"english": "a rice cake", "chinese": "一个重阳糕"}', 22, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13129, 550, '{"english": "jiaozi", "chinese": "饺子"}', 23, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13130, 550, '{"english": "moon cakes", "chinese": "月饼"}', 24, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13131, 550, '{"english": "rice dumplings", "chinese": "粽子"}', 25, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13132, 550, '{"english": "Look and match", "chinese": "看一看并连一连"}', 26, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13133, 550, '{"english": "Spring Festival", "chinese": "春节"}', 27, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13134, 550, '{"english": "Dragon Boat Festival", "chinese": "端午节"}', 28, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13135, 550, '{"english": "Double Ninth Festival", "chinese": "重阳节"}', 29, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13136, 550, '{"english": "Chongyang Festival", "chinese": "重阳节"}', 30, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13137, 550, '{"english": "Mid-Autumn Festival", "chinese": "中秋节"}', 31, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13138, 550, '{"english": "Read and write", "chinese": "读一读并写一写"}', 32, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13139, 550, '{"english": "The Spring Festival is in January or February.", "chinese": "春节在一月或二月。"}', 33, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13140, 550, '{"english": "The Dragon Boat Festival is in May or June.", "chinese": "端午节在五月或六月。"}', 34, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13141, 550, '{"english": "The Mid-Autumn Festival is in September or October.", "chinese": "中秋节在九月或十月。"}', 35, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13142, 550, '{"english": "The Double Ninth Festival (Chongyang Festival) is in October or November.", "chinese": "重阳节在十月或十一月。"}', 36, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13143, 550, '{"english": "Unit 7", "chinese": "第七单元"}', 37, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13144, 550, '{"english": "Grammar time", "chinese": "语法时间"}', 38, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13145, 550, '{"english": "The Spring Festival is in January or February. The Dragon Boat Festival is in May or June. The Mid-Autumn Festival is in September or October. The Double Ninth Festival (Chongyang Festival) is in October or November.", "chinese": "春节在一月或二月。 端午节在五月或六月。 中秋节在九月或十月。 重阳节在十月或十一月。"}', 39, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13146, 550, '{"english": "January→Jan.", "chinese": "一月"}', 40, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13147, 550, '{"english": "February→Feb.", "chinese": "二月"}', 41, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13148, 550, '{"english": "March→Mar.", "chinese": "三月"}', 42, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13149, 550, '{"english": "April→Apr.", "chinese": "四月"}', 43, '2026-02-05 04:27:27', '2026-02-05 04:27:27');
INSERT INTO "course_content" VALUES (13150, 550, '{"english": "May→May", "chinese": "五月"}', 44, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13151, 550, '{"english": "June→Jun.", "chinese": "六月"}', 45, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13152, 550, '{"english": "July→Jul.", "chinese": "七月"}', 46, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13153, 550, '{"english": "August→Aug.", "chinese": "八月"}', 47, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13154, 550, '{"english": "September→Sept.", "chinese": "九月"}', 48, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13155, 550, '{"english": "October→Oct.", "chinese": "十月"}', 49, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13156, 550, '{"english": "November→Nov.", "chinese": "十一月"}', 50, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13157, 550, '{"english": "December→Dec.", "chinese": "十二月"}', 51, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13158, 550, '{"english": "Do you remember these words?", "chinese": "你记得这些单词吗？"}', 52, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13159, 550, '{"english": "spring", "chinese": "春天"}', 53, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13160, 550, '{"english": "summer", "chinese": "夏天"}', 54, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13161, 550, '{"english": "autumn", "chinese": "秋天"}', 55, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13162, 550, '{"english": "winter", "chinese": "冬天"}', 56, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
INSERT INTO "course_content" VALUES (13163, 550, '{"english": "Fun time", "chinese": "娱乐时间"}', 57, '2026-02-05 04:27:28', '2026-02-05 04:27:28');
