INSERT INTO "course_content" VALUES (13201, 550, '{"english": "It is Mother''s Day today.", "chinese": "今天是母亲节。"}', 95, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13202, 550, '{"english": "Do you know Mother''s Day, Bobby?", "chinese": "你知道母亲节吗，波比？"}', 96, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13203, 550, '{"english": "No, I don''t.", "chinese": "不，我不知道。"}', 97, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13204, 550, '{"english": "What is it?", "chinese": "那是什么？"}', 98, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13205, 550, '{"english": "It''s a day for mothers.", "chinese": "这是所有母亲的一个节日。"}', 99, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13206, 550, '{"english": "It''s on the second Sunday of May.", "chinese": "它在五月的第二个星期天。"}', 100, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13207, 550, '{"english": "Bobby likes all festivals.", "chinese": "波比喜欢所有的节日。"}', 101, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13208, 550, '{"english": "What do people do on Mother''s Day?", "chinese": "人们在母亲节那天做什么？"}', 102, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
