INSERT INTO "course_content" VALUES (13216, 550, '{"english": "Happy Mother''s Day, Mum!", "chinese": "母亲节快乐，妈妈!"}', 110, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
INSERT INTO "course_content" VALUES (13217, 550, '{"english": "We love you!", "chinese": "我们爱你!"}', 111, '2026-02-05 04:27:29', '2026-02-05 04:27:29');
