INSERT INTO "course_content" VALUES (13268, 551, '{"english": "When''s your birthday, Su Hai?", "chinese": "你的生日是什么时候，苏海？"}', 3, '2026-02-05 04:27:31', '2026-02-05 04:27:31');
INSERT INTO "course_content" VALUES (13269, 551, '{"english": "It''s on the eleventh of May.", "chinese": "是5月11号。"}', 4, '2026-02-05 04:27:31', '2026-02-05 04:27:31');
INSERT INTO "course_content" VALUES (13270, 551, '{"english": "It''s also Su Yang''s birthday.", "chinese": "同样也是苏阳的生日。"}', 5, '2026-02-05 04:27:31', '2026-02-05 04:27:31');
INSERT INTO "course_content" VALUES (13271, 551, '{"english": "What do you do on your birthday?", "chinese": "你们生日都会做些什么？"}', 6, '2026-02-05 04:27:31', '2026-02-05 04:27:31');
INSERT INTO "course_content" VALUES (13272, 551, '{"english": "We usually have a big dinner with our parents and grandparents.", "chinese": "我们通常和我们的父母以及祖父母吃一顿丰盛的晚餐。"}', 7, '2026-02-05 04:27:31', '2026-02-05 04:27:31');
