INSERT INTO "course_content" VALUES (13274, 551, '{"english": "After that, we play with Kitty the cat.", "chinese": "在那之后，我们和小猫基蒂玩。"}', 9, '2026-02-05 04:27:32', '2026-02-05 04:27:32');
INSERT INTO "course_content" VALUES (13275, 551, '{"english": "We have a great time.", "chinese": "我们玩得很开心。"}', 10, '2026-02-05 04:27:32', '2026-02-05 04:27:32');
INSERT INTO "course_content" VALUES (13276, 551, '{"english": "a birthday cake", "chinese": "一个生日蛋糕"}', 11, '2026-02-05 04:27:32', '2026-02-05 04:27:32');
