INSERT INTO "course_content" VALUES (13594, 555, '{"english": "Unit 1 The king''s new clothes", "chinese": "第一单元  国王的新衣"}', 1, '2026-02-05 04:27:44', '2026-02-05 04:27:44');
INSERT INTO "course_content" VALUES (13595, 555, '{"english": "Tip", "chinese": "小贴士"}', 2, '2026-02-05 04:27:44', '2026-02-05 04:27:44');
INSERT INTO "course_content" VALUES (13596, 555, '{"english": "Recite the text.", "chinese": "背诵课文。"}', 3, '2026-02-05 04:27:44', '2026-02-05 04:27:44');
INSERT INTO "course_content" VALUES (13597, 555, '{"english": "See page 90.", "chinese": "见90页。"}', 4, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13598, 555, '{"english": "Story time", "chinese": "故事时间"}', 5, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13599, 555, '{"english": "Long long ago, there was a king.", "chinese": "很久以前，有一位国王。"}', 6, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13600, 555, '{"english": "He liked new clothes.", "chinese": "他很喜欢新衣服。"}', 7, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13601, 555, '{"english": "One day, two men visited the king.", "chinese": "一天，有两个男人去拜见国王。"}', 8, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13602, 555, '{"english": "\"My king, we can make new clothes for you.\"", "chinese": "并说道，“我的国王，我们可以为您做新衣服。”"}', 9, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13603, 555, '{"english": "The king was happy.", "chinese": "国王很高兴。"}', 10, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13604, 555, '{"english": "The two men showed the king his new clothes.", "chinese": "两个男人向国王展示了新衣服。"}', 11, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13605, 555, '{"english": "\"My king, please try on these magic clothes.", "chinese": "“我的国王，请试穿一下这些神奇的衣服。"}', 12, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13606, 555, '{"english": "Clever people can see them.", "chinese": "聪明的人才能看见它们。"}', 13, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13607, 555, '{"english": "Foolish people can''t see them.\"", "chinese": "愚蠢的人是看不到的。”"}', 14, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13608, 555, '{"english": "clever", "chinese": "聪明的"}', 15, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13609, 555, '{"english": "foolish", "chinese": "愚蠢的"}', 16, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13610, 555, '{"english": "laugh", "chinese": "笑，大笑"}', 17, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13611, 555, '{"english": "The king walked through the city in his new clothes.", "chinese": "国王穿着他的新衣服在街头漫步。"}', 18, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13612, 555, '{"english": "There were a lot of people in the street.", "chinese": "街上有很多人。"}', 19, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13613, 555, '{"english": "They looked at the king and shouted, \"What beautiful clothes!\"", "chinese": "他们看着国王，大声喊着，“多漂亮的衣服啊！”"}', 20, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13614, 555, '{"english": "A little boy pointed at the king and laughed,", "chinese": "一个小男孩指着国王笑，"}', 21, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13615, 555, '{"english": "\"Ha! Ha! The king isn''t wearing any clothes!\"", "chinese": "“哈哈！国王没穿衣服！”"}', 22, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13616, 555, '{"english": "point at", "chinese": "指向"}', 23, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13617, 555, '{"english": "shout", "chinese": "呼喊，喊叫"}', 24, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13618, 555, '{"english": "Unit 1", "chinese": "第一单元"}', 25, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13619, 555, '{"english": "True or false", "chinese": "判断对错"}', 26, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13620, 555, '{"english": "The king liked new clothes.", "chinese": "国王喜欢新衣服。"}', 27, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13621, 555, '{"english": "Two men showed the king some magic clothes.", "chinese": "两个男人向国王展示了一些神奇的衣服。"}', 28, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13622, 555, '{"english": "The king was foolish.", "chinese": "国王很愚蠢。"}', 29, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13623, 555, '{"english": "People could see the king''s new clothes.", "chinese": "人们可以看见国王的新衣。"}', 30, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13624, 555, '{"english": "The boy was foolish because he could not see the king''s new clothes.", "chinese": "小男孩很愚蠢，因为他看不到国王的新衣。"}', 31, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13625, 555, '{"english": "Read and write", "chinese": "读一读并写一写"}', 32, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13626, 555, '{"english": "The king liked new clothes.", "chinese": "国王喜欢新衣服。"}', 33, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13627, 555, '{"english": "Two men wanted to make new clothes for the king.", "chinese": "两个男人想为国王做新衣服。"}', 34, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13628, 555, '{"english": "The king was happy.", "chinese": "国王很高兴。"}', 35, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13629, 555, '{"english": "The men showed the king his new clothes, but the king could not see them.", "chinese": "他们向国王展示了新衣服，但是国王不能看见它们。"}', 36, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13630, 555, '{"english": "The king walked through the city in his new clothes.", "chinese": "国王穿着他的新衣服在街头漫步。"}', 37, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13631, 555, '{"english": "A little boy laughed at him.", "chinese": "一个小男孩笑他。"}', 38, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13632, 555, '{"english": "Grammar time", "chinese": "语法时间"}', 39, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13633, 555, '{"english": "Long long ago, there was a king.", "chinese": "很久很久以前，有一个国王。"}', 40, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13634, 555, '{"english": "There were a lot of people in the street.", "chinese": "街上有很多人。"}', 41, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13635, 555, '{"english": "One day, two men visited the king.", "chinese": "一天，两个人来拜访国王。"}', 42, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13636, 555, '{"english": "The king was happy. The king liked new clothes.", "chinese": "国王很高兴。 国王很喜欢新衣裳。"}', 43, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13637, 555, '{"english": "They looked at the king and shouted. A little boy pointed at the king and laughed.", "chinese": "他们看着国王，大喊着。 一个小男孩指着国王，笑了起来。"}', 44, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13638, 555, '{"english": "laugh", "chinese": "笑，大笑"}', 45, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13639, 555, '{"english": "laughed", "chinese": "笑，大笑"}', 46, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13640, 555, '{"english": "like", "chinese": "喜欢"}', 47, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13641, 555, '{"english": "liked", "chinese": "喜欢"}', 48, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13642, 555, '{"english": "live", "chinese": "居住；生活"}', 49, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13643, 555, '{"english": "lived", "chinese": "居住；生活"}', 50, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13644, 555, '{"english": "look", "chinese": "看"}', 51, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13645, 555, '{"english": "looked", "chinese": "看"}', 52, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13646, 555, '{"english": "point", "chinese": "指"}', 53, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13647, 555, '{"english": "pointed", "chinese": "指"}', 54, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13648, 555, '{"english": "shout", "chinese": "喊叫"}', 55, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13649, 555, '{"english": "shouted", "chinese": "喊叫"}', 56, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13650, 555, '{"english": "show", "chinese": "展示"}', 57, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
