INSERT INTO "course_content" VALUES (13660, 555, '{"english": "Unit 1", "chinese": "第一单元"}', 67, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13661, 555, '{"english": "Fun time", "chinese": "娱乐时间"}', 68, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13662, 555, '{"english": "Say and act", "chinese": "说一说并表演"}', 69, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13663, 555, '{"english": "I like new clothes.", "chinese": "我喜欢新衣服。"}', 70, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13664, 555, '{"english": "Who can make ... for me?", "chinese": "谁能帮我做……？"}', 71, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13665, 555, '{"english": "My king, we can make new clothes for you.", "chinese": "我的国王，我们可以为您做新衣服。"}', 72, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13666, 555, '{"english": "Clever people ...", "chinese": "聪明的人……"}', 73, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13667, 555, '{"english": "Foolish people ...", "chinese": "愚蠢的人……"}', 74, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13668, 555, '{"english": "Make the clothes for me.", "chinese": "给我做衣服。"}', 75, '2026-02-05 04:27:45', '2026-02-05 04:27:45');
INSERT INTO "course_content" VALUES (13669, 555, '{"english": "My king, please.", "chinese": "我的国王，请。"}', 76, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13670, 555, '{"english": "Do they fit?", "chinese": "它们合适吗？"}', 77, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13671, 555, '{"english": "Oh yes.", "chinese": "噢，是的。"}', 78, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13672, 555, '{"english": "They fit well.", "chinese": "很合适。"}', 79, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13673, 555, '{"english": "Look at the king''s new clothes.", "chinese": "看国王的新衣服。"}', 80, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13674, 555, '{"english": "They''re ...", "chinese": "它们……"}', 81, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13675, 555, '{"english": "Ha! Ha! The king isn''t ...", "chinese": "哈哈!国王没有……"}', 82, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13676, 555, '{"english": "Sound time", "chinese": "发音时间"}', 83, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13677, 555, '{"english": "ar", "chinese": ""}', 84, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13678, 555, '{"english": "This afternoon, I got a card  From my good friend Mark.", "chinese": "今天下午，我得到了一张卡片是我的好朋友马克给我的。"}', 85, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13679, 555, '{"english": "It said, \"Come to my party  At half past four in the park!\"", "chinese": "上面说道，“来我的派对四点半在公园！”"}', 86, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13680, 555, '{"english": "arm", "chinese": "手臂"}', 87, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13681, 555, '{"english": "card", "chinese": "卡片"}', 88, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13682, 555, '{"english": "hard", "chinese": "困难的"}', 89, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13683, 555, '{"english": "park", "chinese": "公园"}', 90, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13684, 555, '{"english": "party", "chinese": "派对，晚会"}', 91, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13685, 555, '{"english": "Culture time", "chinese": "文化时间"}', 92, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13686, 555, '{"english": "This is an American cowboy.", "chinese": "这是一位美国牛仔。"}', 93, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13687, 555, '{"english": "He''s wearing jeans.", "chinese": "他穿着牛仔裤。"}', 94, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13688, 555, '{"english": "This is a Scottish man.", "chinese": "这是一位苏格兰人。"}', 95, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13689, 555, '{"english": "He''s wearing a kilt.", "chinese": "他穿着苏格兰式短裙。"}', 96, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13690, 555, '{"english": "Unit 1", "chinese": "第一单元"}', 97, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13691, 555, '{"english": "Cartoon time", "chinese": "卡通时间"}', 98, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13692, 555, '{"english": "Miss Fox and her students are playing a game.", "chinese": "狐狸小姐和她的学生们在玩游戏。"}', 99, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13693, 555, '{"english": "They are telling a story.", "chinese": "它们正在讲故事。"}', 100, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13694, 555, '{"english": "Each student says one sentence.", "chinese": "每一个学生说一句话。"}', 101, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13695, 555, '{"english": "Miss Fox starts.", "chinese": "狐狸小姐先开始。"}', 102, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13696, 555, '{"english": "Long long ago, there was a mountain.", "chinese": "很久以前，有一座山。"}', 103, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13697, 555, '{"english": "Sam is quick.", "chinese": "山姆反应很快。"}', 104, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13698, 555, '{"english": "There was a house on the mountian.", "chinese": "山上有座房子。"}', 105, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13699, 555, '{"english": "Great, Sam!", "chinese": "做得好，山姆！"}', 106, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13700, 555, '{"english": "Willy says the next sentence.", "chinese": "威利讲下一句。"}', 107, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13701, 555, '{"english": "An old man and a little boy lived in the house.", "chinese": "一位老人和一个小男孩住在房子里。"}', 108, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13702, 555, '{"english": "Wonderful, Willy!", "chinese": "太棒了，威利！"}', 109, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13703, 555, '{"english": "Billy says a sentence too.", "chinese": "比利也说一个句子。"}', 110, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13704, 555, '{"english": "The old man told the boy a story.", "chinese": "老人给男孩讲了一个故事。"}', 111, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13705, 555, '{"english": "Good!", "chinese": "很好！"}', 112, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13706, 555, '{"english": "It is Bobby''s turn.", "chinese": "该波比了。"}', 113, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13707, 555, '{"english": "He is thinking hard.", "chinese": "他很努力地思考。"}', 114, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13708, 555, '{"english": "Bobby, what''s next?", "chinese": "波比，接下来呢？"}', 115, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13709, 555, '{"english": "Long long ago, there was ... a mountain.", "chinese": "很久以前，有…… 一座山。"}', 116, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13710, 555, '{"english": "Ha! Ha! We have to start the story again.", "chinese": "哈哈！我们又从头开始了。"}', 117, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13711, 555, '{"english": "Unit 1", "chinese": "第一单元"}', 118, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13712, 555, '{"english": "Checkout time", "chinese": "检查时间"}', 119, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13713, 555, '{"english": "Read and write", "chinese": "读一读并写一写"}', 120, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13714, 555, '{"english": "was", "chinese": "是"}', 121, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13715, 555, '{"english": "were", "chinese": "是"}', 122, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13716, 555, '{"english": "laughed", "chinese": "笑"}', 123, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13717, 555, '{"english": "lived", "chinese": "居住；生活"}', 124, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13718, 555, '{"english": "said", "chinese": "说"}', 125, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13719, 555, '{"english": "visited", "chinese": "拜访"}', 126, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13720, 555, '{"english": "worked", "chinese": "工作"}', 127, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13721, 555, '{"english": "Long long ago, there was an old man.", "chinese": "很久很久以前，有一个老人。"}', 128, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13722, 555, '{"english": "His name was Yu Gong.", "chinese": "有一个叫愚公的老人。"}', 129, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13723, 555, '{"english": "He lived behind two mountains.", "chinese": "他家住在两座山的后面。"}', 130, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13724, 555, '{"english": "Yu Gong said to his family, \"We have to move the two mountains away.\"", "chinese": "愚公对他的家人说道：“我们必须把两座山移走。”"}', 131, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13725, 555, '{"english": "Yu Gong and his family worked very hard.", "chinese": "愚公和他的家人辛勤劳作。"}', 132, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13726, 555, '{"english": "They were tired but happy.", "chinese": "虽然他们很累，但是却十分高兴。"}', 133, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13727, 555, '{"english": "Yu Gong''s friend visited him.", "chinese": "愚公的朋友拜访了他。"}', 134, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13728, 555, '{"english": "He laughed at Yu Gong and his family.", "chinese": "并嘲笑愚公和他的家人。"}', 135, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13729, 555, '{"english": "Yu Gong said, \"I have children and grandchildren.", "chinese": "愚公说道：“我有儿子和孙子。"}', 136, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13730, 555, '{"english": "My grandchildren have their children.", "chinese": "我的孙子有儿子。"}', 137, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13731, 555, '{"english": "One day, we can move the mountains away.\"", "chinese": "终有一天，我们能把山移走。”"}', 138, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13732, 555, '{"english": "Circle and say", "chinese": "圈一圈并说一说"}', 139, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13733, 555, '{"english": "The children are telling stories.", "chinese": "孩子们正在说故事。"}', 140, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13734, 555, '{"english": "Circle the correct words.", "chinese": "圈出正确的单词。"}', 141, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13735, 555, '{"english": "Then tell your own story.", "chinese": "并说说你自己的故事。"}', 142, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13736, 555, '{"english": "Long long ago, there (was/were) two men ...", "chinese": "很久以前，有两个男人……"}', 143, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13737, 555, '{"english": "Long long ago, there (was/were) a house in the forest ...", "chinese": "很久以前，在森林里有一座房子……"}', 144, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13738, 555, '{"english": "Long long ago, there (was/were) a child ...", "chinese": "很久以前，有一个孩子……"}', 145, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13739, 555, '{"english": "Long long ago, there (was/were) some animals ...", "chinese": "很久以前，有一些动物……"}', 146, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13740, 555, '{"english": "You", "chinese": "你"}', 147, '2026-02-05 04:27:46', '2026-02-05 04:27:46');
INSERT INTO "course_content" VALUES (13741, 555, '{"english": "Long long ago ...", "chinese": "很久以前……"}', 148, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13742, 555, '{"english": "Ticking time", "chinese": "评价时间"}', 149, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13743, 555, '{"english": "I can understand the story \"The king''s new clothes\".", "chinese": "我能理解“国王的新衣”这个故事。"}', 150, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13744, 555, '{"english": "I can use \"was\", \"were\", \"looked\", etc.", "chinese": "我会用“was”“were”“looked”等单词。"}', 151, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13745, 555, '{"english": "I know the sound of \"ar\".", "chinese": "我知道“ar”的发音。"}', 152, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13746, 555, '{"english": "Unit 1", "chinese": "第一单元"}', 153, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13747, 556, '{"english": "Unit 2 What a day!", "chinese": "第二单元  多糟糕的一天！"}', 1, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13748, 556, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13749, 556, '{"english": "Sunday, 20th September", "chinese": "9月20日，星期天"}', 3, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13750, 556, '{"english": "It was sunny in the morning.", "chinese": "早上天气晴朗。"}', 4, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13751, 556, '{"english": "Su Hai, Mike, Liu Tao and I went to the park by bike.", "chinese": "我和苏海，迈克，刘涛骑单车去公园玩。"}', 5, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13752, 556, '{"english": "There was a parrot show in the park.", "chinese": "公园里有一个鹦鹉表演。"}', 6, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13753, 556, '{"english": "We saw some interesting parrots.", "chinese": "我们看到了一些有趣的鹦鹉。"}', 7, '2026-02-05 04:27:47', '2026-02-05 04:27:47');
INSERT INTO "course_content" VALUES (13754, 556, '{"english": "Then, the weather became windy and cloudy.", "chinese": "然后，天气开始变得多云并刮风了。"}', 8, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13755, 556, '{"english": "We flew kites high in the sky.", "chinese": "我们把风筝在天空中放得很高。"}', 9, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13756, 556, '{"english": "cloudy", "chinese": "多云的"}', 10, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13757, 556, '{"english": "rainy", "chinese": "下雨的"}', 11, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13758, 556, '{"english": "It was time for lunch.", "chinese": "到吃午餐的时间了。"}', 12, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13759, 556, '{"english": "We brought some jiaozi, some bread and honey and some drinks.", "chinese": "我们带了一些饺子，面包和蜂蜜，还有一些饮料。"}', 13, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13760, 556, '{"english": "We saw some ants on the bread and honey.", "chinese": "我们看到面包和蜂蜜上有一些蚂蚁。"}', 14, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13761, 556, '{"english": "There were some bees too.", "chinese": "还有一些蜜蜂。"}', 15, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13762, 556, '{"english": "We could not eat our lunch!", "chinese": "我们不能吃我们的午餐了！"}', 16, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13763, 556, '{"english": "In the afternoon, there were black clouds in the sky.", "chinese": "下午，天空中出现了几朵黑云。"}', 17, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13764, 556, '{"english": "It rained.", "chinese": "下雨了。"}', 18, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13765, 556, '{"english": "We were hungry and wet.", "chinese": "我们不仅饿而且全身都湿透了。"}', 19, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13766, 556, '{"english": "What a day!", "chinese": "多糟糕的一天！"}', 20, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13767, 556, '{"english": "sunny", "chinese": "晴朗的"}', 21, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13768, 556, '{"english": "windy", "chinese": "刮风的"}', 22, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13769, 556, '{"english": "Unit 2", "chinese": "第二单元"}', 23, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13770, 556, '{"english": "Read and order", "chinese": "读一读并排序"}', 24, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13771, 556, '{"english": "They saw some interesting parrots in the park.", "chinese": "他们在公园看到一些有趣的鹦鹉。"}', 25, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13772, 556, '{"english": "They were hungry and wet.", "chinese": "他们不仅饿而且全身都湿透了。"}', 26, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13773, 556, '{"english": "The children went to the park by bike.", "chinese": "孩子们骑单车去公园玩。"}', 27, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13774, 556, '{"english": "They flew kites in the park.", "chinese": "他们在公园放风筝。"}', 28, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13775, 556, '{"english": "They saw ants and bees on their lunch.", "chinese": "他们看到蚂蚁和蜜蜂在他们的午餐里。"}', 29, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13776, 556, '{"english": "The weather became windy and cloudy.", "chinese": "天气开始变得多云并刮风了。"}', 30, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13777, 556, '{"english": "It rained.", "chinese": "下雨了。"}', 31, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13778, 556, '{"english": "True or false", "chinese": "判断对错"}', 32, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13779, 556, '{"english": "It rained all day on 20th September.", "chinese": "9月20号下了一整天的雨。"}', 33, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13780, 556, '{"english": "The children saw a parrot show.", "chinese": "孩子们看到一个鹦鹉表演。"}', 34, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13781, 556, '{"english": "They flew kites in the park.", "chinese": "他们在公园放风筝。"}', 35, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13782, 556, '{"english": "They brought lunch to the park.", "chinese": "他们把午餐带到公园去了。"}', 36, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13783, 556, '{"english": "They were hungry because they did not have lunch.", "chinese": "他们很饿因为他们没有吃午餐。"}', 37, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13784, 556, '{"english": "Grammar time", "chinese": "语法时间"}', 38, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13785, 556, '{"english": "It was sunny. It was cloudy. It was windy. It was rainy.", "chinese": "天气晴朗。 天气多云。 刮风了。 下雨了。"}', 39, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13786, 556, '{"english": "We saw many interesting parrots. We flew kites.", "chinese": "我们看到了许多有趣的鹦鹉。 我们放了风筝。"}', 40, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13787, 556, '{"english": "I brought some drinks. He brought some bread and honey. She brought some jiaozi.", "chinese": "我带了饮料。 他带了面包和蜂蜜。 她带了饺子。"}', 41, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
