INSERT INTO "course_content" VALUES (13803, 556, '{"english": "Note the past forms of these verbs.", "chinese": "注意这些动词的过去式形式。"}', 57, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13804, 556, '{"english": "See page 90.", "chinese": "见第90页。"}', 58, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13805, 556, '{"english": "Unit 2", "chinese": "第二单元"}', 59, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13806, 556, '{"english": "Fun time", "chinese": "娱乐时间"}', 60, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13807, 556, '{"english": "Play a game", "chinese": "玩游戏"}', 61, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13808, 556, '{"english": "Pick three cards.", "chinese": "选三张卡片。"}', 62, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
