INSERT INTO "course_content" VALUES (13810, 556, '{"english": "It was sunny.", "chinese": "天气晴朗。"}', 64, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13811, 556, '{"english": "I played basketball in the playground.", "chinese": "我在操场上打篮球。"}', 65, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13812, 556, '{"english": "Well done.", "chinese": "做得好。"}', 66, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13813, 556, '{"english": "Sound time", "chinese": "发音时间"}', 67, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13814, 556, '{"english": "ear", "chinese": ""}', 68, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13815, 556, '{"english": "The New Year is nearly here.", "chinese": "新年到了。"}', 69, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13816, 556, '{"english": "Let''s cheer together, my dear!", "chinese": "让我们一起庆祝，亲爱的！"}', 70, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13817, 556, '{"english": "dear", "chinese": "亲爱的"}', 71, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13818, 556, '{"english": "hear", "chinese": "听见"}', 72, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13819, 556, '{"english": "near", "chinese": "接近"}', 73, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13820, 556, '{"english": "year", "chinese": "年"}', 74, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13821, 556, '{"english": "Song time", "chinese": "唱歌时间"}', 75, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13822, 556, '{"english": "Rain, rain, go away", "chinese": "小雨，小雨，请走开"}', 76, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13823, 556, '{"english": "Rain, rain, go away.", "chinese": "歌词大意：小雨，小雨，请走开。"}', 77, '2026-02-05 04:27:48', '2026-02-05 04:27:48');
INSERT INTO "course_content" VALUES (13824, 556, '{"english": "Come again another day.", "chinese": "改天再来吧。"}', 78, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13825, 556, '{"english": "Little Johnny wants to play.", "chinese": "小约翰尼想要去玩儿。"}', 79, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13826, 556, '{"english": "Rain, rain, go away.", "chinese": "小雨，小雨，请走开。"}', 80, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13827, 556, '{"english": "Rain, rain, go away.", "chinese": "小雨，小雨，请走开。"}', 81, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13828, 556, '{"english": "Come again another day.", "chinese": "改天再来吧。"}', 82, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13829, 556, '{"english": "Little Johnny wants to play.", "chinese": "小约翰尼想要去玩儿。"}', 83, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13830, 556, '{"english": "Rain, rain, go away.", "chinese": "小雨，小雨，请走开。"}', 84, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13831, 556, '{"english": "Unit 2", "chinese": "第二单元"}', 85, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13832, 556, '{"english": "Cartoon time", "chinese": "卡通时间"}', 86, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13833, 556, '{"english": "Sam meets Bobby in the park.", "chinese": "山姆在公园遇见波比。"}', 87, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13834, 556, '{"english": "Hi, Bobby.", "chinese": "你好，波比。"}', 88, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13835, 556, '{"english": "Hi, Sam.", "chinese": "你好，山姆。"}', 89, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13836, 556, '{"english": "You look sad.", "chinese": "你看起来很伤心。"}', 90, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13837, 556, '{"english": "What''s the matter?", "chinese": "你怎么了？"}', 91, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13838, 556, '{"english": "I lost my new kite.", "chinese": "我丢失了我的新风筝。"}', 92, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13839, 556, '{"english": "Sam wants to know why.", "chinese": "山姆想知道为什么。"}', 93, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13840, 556, '{"english": "What happened, Bobby?", "chinese": "出什么事了，波比？"}', 94, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13841, 556, '{"english": "This morning, Tina and I flew my new kite in the park, but it wasn''t windy in the park.", "chinese": "今天早上，我和缇娜在公园一起放我的新风筝，但是公园里没有风。"}', 95, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13842, 556, '{"english": "What happened then?", "chinese": "然后发生什么了？"}', 96, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13843, 556, '{"english": "We climbed up the hill.", "chinese": "我们爬上小山。"}', 97, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13844, 556, '{"english": "It was windy there.", "chinese": "那里有风。"}', 98, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13845, 556, '{"english": "What happened then?", "chinese": "接下来又发生什么了呢？"}', 99, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13846, 556, '{"english": "The kite flew high, but it flew too high and we couldn''t hold onto it.", "chinese": "风筝飞得很高，但是因为它飞得太高，我们不能抓紧它。"}', 100, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13847, 556, '{"english": "It flew away.", "chinese": "它飞走了。"}', 101, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13848, 556, '{"english": "Sam laughs.", "chinese": "山姆笑了。"}', 102, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13849, 556, '{"english": "Is this your kite?", "chinese": "这是你的风筝吗？"}', 103, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13850, 556, '{"english": "Yes!", "chinese": "是的！"}', 104, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13851, 556, '{"english": "Why do you have it?", "chinese": "它为什么会在你的手上？"}', 105, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13852, 556, '{"english": "I found it near the hill!", "chinese": "我在小山附近发现了它！"}', 106, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13853, 556, '{"english": "Unit 2", "chinese": "第二单元"}', 107, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13854, 556, '{"english": "Checkout time", "chinese": "检查时间"}', 108, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13855, 556, '{"english": "Listen and choose", "chinese": "听一听并选一选"}', 109, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13856, 556, '{"english": "It was cloudy on Monday morning.", "chinese": "星期一早上天气多云。"}', 110, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13857, 556, '{"english": "I got up at seven thirty.", "chinese": "我七点半起床。"}', 111, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13858, 556, '{"english": "I went to school by bike.", "chinese": "我骑自行车去上学。"}', 112, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13859, 556, '{"english": "I could not find my English book.", "chinese": "我找不到我的英语书了。"}', 113, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13860, 556, '{"english": "Think and write", "chinese": "想一想并写一写"}', 114, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13861, 556, '{"english": "What did you do with your family or friends last Sunday?", "chinese": "上周星期天，你和你的家人或朋友都做了些什么呢？"}', 115, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13862, 556, '{"english": "Write about it in your diary.", "chinese": "把它写进你的日记里吧。"}', 116, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13863, 556, '{"english": "went swimming", "chinese": "去游泳了"}', 117, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13864, 556, '{"english": "watched a film", "chinese": "看了一场电影"}', 118, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13865, 556, '{"english": "had a picnic", "chinese": "去野餐了"}', 119, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13866, 556, '{"english": "did the housework", "chinese": "做了家务"}', 120, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13867, 556, '{"english": "Sunday, ______", "chinese": "星期天，________"}', 121, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13868, 556, '{"english": "Today, I ______", "chinese": "今天，我__________"}', 122, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13869, 556, '{"english": "Ticking time", "chinese": "评价时间"}', 123, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13870, 556, '{"english": "I can talk and write about the things I did.", "chinese": "我能说，也能写出我做过的事情。"}', 124, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13871, 556, '{"english": "I can use \"brought\", \"could\", \"flew\", etc.", "chinese": "我会用“brought”“could”“flew”等单词。"}', 125, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13872, 556, '{"english": "I know the sound of \"ear\".", "chinese": "我知道“ear”的发音。"}', 126, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13873, 556, '{"english": "Unit 2", "chinese": "第二单元"}', 127, '2026-02-05 04:27:49', '2026-02-05 04:27:49');
INSERT INTO "course_content" VALUES (13874, 557, '{"english": "Unit 3 Holiday fun", "chinese": "第三单元 假日娱乐"}', 1, '2026-02-05 04:27:50', '2026-02-05 04:27:50');
INSERT INTO "course_content" VALUES (13875, 557, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13876, 557, '{"english": "The students came back to school after the National Day holiday.", "chinese": "国庆节假日过后，同学们都返回学校。"}', 3, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13877, 557, '{"english": "Hello, Liu Tao!", "chinese": "你好，刘涛！"}', 4, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13878, 557, '{"english": "Where did you go for the holiday?", "chinese": "你去哪里度假了？"}', 5, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13879, 557, '{"english": "I called you, but you weren''t at home.", "chinese": "我给你打过电话，但是你不在家。"}', 6, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13880, 557, '{"english": "I went to Shanghai and visited my aunt.", "chinese": "我去上海拜访我的姑姑了。"}', 7, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13881, 557, '{"english": "What did you do there?", "chinese": "你在那儿干什么？"}', 8, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13882, 557, '{"english": "We went to the Bund and visited the Shanghai Museum.", "chinese": "我们去了外滩，参观了上海博物馆。"}', 9, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13883, 557, '{"english": "I saw many interesting things.", "chinese": "我看到了很多有趣的东西。"}', 10, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13884, 557, '{"english": "How was your holiday, Mike?", "chinese": "你的假期怎么样呢，迈克？"}', 11, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13885, 557, '{"english": "Bund", "chinese": "外滩"}', 12, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13886, 557, '{"english": "Great Wall", "chinese": "长城"}', 13, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13887, 557, '{"english": "Palace Museum", "chinese": "故宫博物院"}', 14, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13888, 557, '{"english": "It was great fun.", "chinese": "很棒。"}', 15, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13889, 557, '{"english": "Our family went to a farm near Star Lake.", "chinese": "我们一家人去了星湖附近的一个农场。"}', 16, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13890, 557, '{"english": "We picked some oranges and went fishing.", "chinese": "我们摘了一些橘子，还去抓鱼了。"}', 17, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13891, 557, '{"english": "Did you catch any fish?", "chinese": "你抓到鱼了吗？"}', 18, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13892, 557, '{"english": "Yes, I did.", "chinese": "是的，抓到了。"}', 19, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13893, 557, '{"english": "I caught a big fish!", "chinese": "我抓到了一条大鱼！"}', 20, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13894, 557, '{"english": "That''s great.", "chinese": "那太棒了。"}', 21, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13895, 557, '{"english": "Why did you call me?", "chinese": "你为什么给我打电话呢？"}', 22, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13896, 557, '{"english": "Because I wanted to give you the fish.", "chinese": "因为我想给你我抓到的鱼。"}', 23, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13897, 557, '{"english": "Where''s the fish now?", "chinese": "那现在鱼在哪儿？"}', 24, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13898, 557, '{"english": "I ate it!", "chinese": "我吃了！"}', 25, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13899, 557, '{"english": "Shanghai Museum", "chinese": "上海博物馆"}', 26, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13900, 557, '{"english": "Summer Palace", "chinese": "颐和园"}', 27, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13901, 557, '{"english": "Tian''anmen Square", "chinese": "天安门广场"}', 28, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13902, 557, '{"english": "Unit 3", "chinese": "第三单元"}', 29, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13903, 557, '{"english": "Think and write", "chinese": "想一想并写一写"}', 30, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13904, 557, '{"english": "What did Liu Tao and Mike do for the National Day holiday?", "chinese": "刘涛和迈克在国庆节假期里都做了什么呢？"}', 31, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13905, 557, '{"english": "Liu Tao went to Shanghai.", "chinese": "刘涛去了上海。"}', 32, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13906, 557, '{"english": "He went to the Bund and the Shanghai Museum.", "chinese": "他去了外滩和上海博物馆。"}', 33, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13907, 557, '{"english": "He saw many interesting things.", "chinese": "他看见了很多有趣的东西。"}', 34, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13908, 557, '{"english": "Mike went to a farm.", "chinese": "迈克去了一个农场。"}', 35, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13909, 557, '{"english": "He picked some oranges.", "chinese": "他摘了一些橘子。"}', 36, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13910, 557, '{"english": "He went fishing too.", "chinese": "他还去抓鱼了。"}', 37, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13911, 557, '{"english": "He caught a big fish.", "chinese": "他抓了一条大鱼。"}', 38, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13912, 557, '{"english": "Ask and answer", "chinese": "提问并回答"}', 39, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13913, 557, '{"english": "Where does Liu Tao''s aunt live?", "chinese": "刘涛的姑姑住在哪里？"}', 40, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13914, 557, '{"english": "Where did Liu Tao go in Shanghai?", "chinese": "刘涛在上海去了哪些地方？"}', 41, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13915, 557, '{"english": "Where did Mike go for the holiday?", "chinese": "迈克去哪里度假了？"}', 42, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13916, 557, '{"english": "Did Mike catch a big fish?", "chinese": "迈克抓了一条大鱼吗？"}', 43, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13917, 557, '{"english": "Why did Mike call Liu Tao?", "chinese": "为什么迈克会给刘涛打电话？"}', 44, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13918, 557, '{"english": "Grammar time", "chinese": "语法时间"}', 45, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13919, 557, '{"english": "What did you do for the holiday? Where did he go for the holiday?", "chinese": "你在假期做了什么？ 他在假期去了哪里？"}', 46, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13920, 557, '{"english": "I visited the Shanghai Museum. He went to a farm.", "chinese": "我去参观了上海博物馆。 他去了农场。"}', 47, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13921, 557, '{"english": "How was your holiday?", "chinese": "你假期过得怎么样？"}', 48, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13922, 557, '{"english": "It was great fun.", "chinese": "非常开心。"}', 49, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13923, 557, '{"english": "Why did you call me?", "chinese": "你为什么打电话给我？"}', 50, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13924, 557, '{"english": "Because I wanted to give you the fish.", "chinese": "因为我想把鱼给你。"}', 51, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13925, 557, '{"english": "Did you go fishing? Did he go fishing?", "chinese": "你去钓鱼了吗？ 他去钓鱼了吗？"}', 52, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13926, 557, '{"english": "Yes, I did. No, he didn''t.", "chinese": "是的，我去钓鱼了。 不，他没去钓鱼。"}', 53, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13927, 557, '{"english": "catch", "chinese": "抓"}', 54, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13928, 557, '{"english": "caught", "chinese": "抓"}', 55, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13929, 557, '{"english": "do", "chinese": "做"}', 56, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13930, 557, '{"english": "did", "chinese": "做"}', 57, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13931, 557, '{"english": "eat", "chinese": "吃"}', 58, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13932, 557, '{"english": "ate", "chinese": "吃"}', 59, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13933, 557, '{"english": "get", "chinese": "得到"}', 60, '2026-02-05 04:27:51', '2026-02-05 04:27:51');
INSERT INTO "course_content" VALUES (13934, 557, '{"english": "got", "chinese": "得到"}', 61, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13935, 557, '{"english": "didn''t = did not", "chinese": "没有"}', 62, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13936, 557, '{"english": "Unit 3", "chinese": "第三单元"}', 63, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13937, 557, '{"english": "Fun time", "chinese": "娱乐时间"}', 64, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13938, 557, '{"english": "Tip", "chinese": "小贴士"}', 65, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13939, 557, '{"english": "Talk about your travel experiences.", "chinese": "谈谈你的旅游经历。"}', 66, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13940, 557, '{"english": "See page 90.", "chinese": "见第90页。"}', 67, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13941, 557, '{"english": "Ask and answer", "chinese": "提问并回答"}', 68, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13942, 557, '{"english": "How was your National Day holiday?", "chinese": "你的国庆节假期怎么样？"}', 69, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13943, 557, '{"english": "It was ...", "chinese": "它……"}', 70, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13944, 557, '{"english": "Where did you go?", "chinese": "你去哪里了？"}', 71, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13945, 557, '{"english": "I went ...", "chinese": "我去……"}', 72, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13946, 557, '{"english": "What did you do?", "chinese": "你做什么了？"}', 73, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13947, 557, '{"english": "I ...", "chinese": "我……"}', 74, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13948, 557, '{"english": "Did you ...?", "chinese": "你……了吗？"}', 75, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13949, 557, '{"english": "Yes, I did.", "chinese": "是的，我做了。"}', 76, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13950, 557, '{"english": "No, I didn''t.", "chinese": "不，我没有。"}', 77, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13951, 557, '{"english": "I ...", "chinese": "我……"}', 78, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13952, 557, '{"english": "Sound time", "chinese": "发音时间"}', 79, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13953, 557, '{"english": "Intonation", "chinese": "语调"}', 80, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13954, 557, '{"english": "Hey!", "chinese": "嘿！"}', 81, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13955, 557, '{"english": "Please pick an orange for me.", "chinese": "请为我摘一个橘子。"}', 82, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13956, 557, '{"english": "I want an orange from the tree.", "chinese": "我想要那棵树上的一个橘子。"}', 83, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13957, 557, '{"english": "Hey!", "chinese": "嘿！"}', 84, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13958, 557, '{"english": "Please catch a fish for me.", "chinese": "请为我抓一条鱼。"}', 85, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13959, 557, '{"english": "I want a fish from the sea.", "chinese": "我想要大海里的一条鱼。"}', 86, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13960, 557, '{"english": "Culture time", "chinese": "文化时间"}', 87, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13961, 557, '{"english": "There are usually three terms in a school year in the UK.", "chinese": "在英国，一个学年通常有三个学期。"}', 88, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13962, 557, '{"english": "They are the autumn term, the spring term and the summer term.", "chinese": "它们分别是秋季学期、春季学期和夏季学期。"}', 89, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13963, 557, '{"english": "Unit 3", "chinese": "第三单元"}', 90, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13964, 557, '{"english": "Cartoon time", "chinese": "卡通时间"}', 91, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13965, 557, '{"english": "It is time for dinner.", "chinese": "到吃晚餐的时间了。"}', 92, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13966, 557, '{"english": "Bobby comes home late.", "chinese": "波比回家晚了。"}', 93, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13967, 557, '{"english": "Where did you go, Bobby?", "chinese": "你去哪儿了，波比？"}', 94, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13968, 557, '{"english": "I was in the park.", "chinese": "我在公园。"}', 95, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13969, 557, '{"english": "We had fashion show there.", "chinese": "我们在那里有一个时装表演。"}', 96, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13970, 557, '{"english": "Tina loves beautiful clothes.", "chinese": "缇娜喜欢漂亮的衣服。"}', 97, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13971, 557, '{"english": "She is excited about the show.", "chinese": "对于这个表演，她十分激动。"}', 98, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13972, 557, '{"english": "Wow, I love fashion shows.", "chinese": "哇，我喜欢时装表演。"}', 99, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13973, 557, '{"english": "What did you wear, Bobby?", "chinese": "你穿的什么，波比？"}', 100, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13974, 557, '{"english": "I wore a paper T-shirt and paper shorts.", "chinese": "我穿了一件纸制T恤和纸制短裤。"}', 101, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13975, 557, '{"english": "Ha! Ha!", "chinese": "哈哈！"}', 102, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13976, 557, '{"english": "That''s cool.", "chinese": "太酷了。"}', 103, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13977, 557, '{"english": "What great fun!", "chinese": "多好玩啊！"}', 104, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13978, 557, '{"english": "Tina asks Bobby about Sam.", "chinese": "缇娜问波比山姆穿的是什么。"}', 105, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13979, 557, '{"english": "Did Sam wear paper clothes too?", "chinese": "山姆也穿了纸制衣服吗？"}', 106, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13980, 557, '{"english": "No.", "chinese": "不，"}', 107, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13981, 557, '{"english": "He wore a lot of bottles.", "chinese": "他穿着很多瓶子。"}', 108, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13982, 557, '{"english": "Wow, that''s interesting!", "chinese": "哇，好有趣！"}', 109, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13983, 557, '{"english": "Tina asks about the show.", "chinese": "缇娜问那场表演的情况。"}', 110, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13984, 557, '{"english": "Did the show go well?", "chinese": "表演进行得顺利吗？"}', 111, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13985, 557, '{"english": "It was wonderful at first, but then there was heavy rain.", "chinese": "一开始很棒，但是后来下了场大雨。"}', 112, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13986, 557, '{"english": "Oh, that''s too bad!", "chinese": "噢，那太糟糕了！"}', 113, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13987, 557, '{"english": "Unit 3", "chinese": "第三单元"}', 114, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13988, 557, '{"english": "Checkout time", "chinese": "检查时间"}', 115, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13989, 557, '{"english": "Write and say", "chinese": "写一写并说一说"}', 116, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13990, 557, '{"english": "What did they do for the holiday?", "chinese": "他们在假期里都做了些什么？"}', 117, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13991, 557, '{"english": "Mike and Liu Tao went to the Car Museum.", "chinese": "迈克和刘涛去了汽车博物馆。"}', 118, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13992, 557, '{"english": "They saw many cool cars.", "chinese": "他们看见了很多很酷的汽车。"}', 119, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13993, 557, '{"english": "Yang Ling and Helen went to the theater.", "chinese": "杨玲和海伦去了电影院。"}', 120, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13994, 557, '{"english": "They watched a new film.", "chinese": "她们看了一部新电影。"}', 121, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13995, 557, '{"english": "Yang Ling visited Su Hai and Su Yang.", "chinese": "杨玲拜访苏海和苏阳。"}', 122, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13996, 557, '{"english": "Miss Li had a birthday party.", "chinese": "李老师举办了生日派对。"}', 123, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13997, 557, '{"english": "She invited many friends.", "chinese": "她邀请了很多朋友。"}', 124, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13998, 557, '{"english": "Tim visited his cousin Jim.", "chinese": "提姆拜访了他的表弟吉姆。"}', 125, '2026-02-05 04:27:52', '2026-02-05 04:27:52');
INSERT INTO "course_content" VALUES (13999, 557, '{"english": "They played together.", "chinese": "他们在一起玩。"}', 126, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14000, 557, '{"english": "Mr Green was at home.", "chinese": "格林先生呆在家。"}', 127, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14001, 557, '{"english": "He washed his car.", "chinese": "他清洗了他的车。"}', 128, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14002, 557, '{"english": "HAPPY BIRTHDAY", "chinese": "生日快乐"}', 129, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14003, 557, '{"english": "Think and write", "chinese": "想一想并写一写"}', 130, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14004, 557, '{"english": "Write about your National Day holiday.", "chinese": "写一写你的国庆节假期"}', 131, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14005, 557, '{"english": "My holiday", "chinese": "我的假期"}', 132, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14006, 557, '{"english": "I went _____ for the holiday.", "chinese": "我去_______度假了。"}', 133, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14007, 557, '{"english": "I saw ____.", "chinese": "我看见_______。"}', 134, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14008, 557, '{"english": "I ____.", "chinese": "我______。"}', 135, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14009, 557, '{"english": "It was great fun.", "chinese": "太好玩了。"}', 136, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14010, 557, '{"english": "Ticking time", "chinese": "评价时间"}', 137, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14011, 557, '{"english": "I can talk and write about the things I did for the holidays.", "chinese": "我能说，也能写出我在假期里做的事。"}', 138, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14012, 557, '{"english": "I can ask and answer questions with \"did\" and \"was\".", "chinese": "我会用“did”和“was”提问并回答。"}', 139, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14013, 557, '{"english": "I know how to use falling intonation.", "chinese": "我知道如何使用降调。"}', 140, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14014, 557, '{"english": "Unit 3", "chinese": "第三单元"}', 141, '2026-02-05 04:27:53', '2026-02-05 04:27:53');
INSERT INTO "course_content" VALUES (14015, 558, '{"english": "Unit 4 Then and now", "chinese": "第四单元  过去和现在"}', 1, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14016, 558, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14017, 558, '{"english": "Six years ago, Mike could read and draw, but he could not write.", "chinese": "六年前，迈克会读会画，但是他不会写。"}', 3, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14018, 558, '{"english": "Now he can do many things.", "chinese": "现在他会做许多事情。"}', 4, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14019, 558, '{"english": "Twenty years ago, Mr Brown wrote letters to his friends.", "chinese": "二十年前，布朗先生给他的朋友们写信。"}', 5, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14020, 558, '{"english": "He used the telephone at home and in the office to call people.", "chinese": "他用家里或办公室的电话给别人打电话。"}', 6, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14021, 558, '{"english": "Now he has a mobile phone and he can call people anywhere.", "chinese": "现在他有手机了，他可以在任何地点给别人电话。"}', 7, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14022, 558, '{"english": "He also writes emails.", "chinese": "他还能写邮件。"}', 8, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14023, 558, '{"english": "an e-book", "chinese": "一本电子书"}', 9, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14024, 558, '{"english": "a mobile phone", "chinese": "一部手机"}', 10, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14025, 558, '{"english": "a newspaper", "chinese": "一份报纸"}', 11, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14026, 558, '{"english": "Thirty years ago, Mike''s grandpa listened to the radio and read newspapers for news.", "chinese": "三十年前，迈克的爷爷通过听音机和看报来了解新闻。"}', 12, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14027, 558, '{"english": "Now he can read and watch news on the Internet.", "chinese": "现在他能在网上看新闻了。"}', 13, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14028, 558, '{"english": "He reads e-books too.", "chinese": "他也能读电子书。"}', 14, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14029, 558, '{"english": "Twenty years ago, Mrs Brown made friends at school.", "chinese": "二十年前，布朗太太只能在学校交朋友。"}', 15, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14030, 558, '{"english": "She bought things from shops.", "chinese": "她只能从商店里买东西。"}', 16, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14031, 558, '{"english": "Now she has e-friends from all over the world.", "chinese": "现在她已经有了世界各地的网友。"}', 17, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14032, 558, '{"english": "She does shopping on the Internet too.", "chinese": "她还可以在网上买东西。"}', 18, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14033, 558, '{"english": "a radio", "chinese": "一台收音机"}', 19, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14034, 558, '{"english": "a telephone", "chinese": "一个电话"}', 20, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14035, 558, '{"english": "a TV", "chinese": "一台电视"}', 21, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14036, 558, '{"english": "Unit 4", "chinese": "第四单元"}', 22, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14037, 558, '{"english": "Write and say", "chinese": "写一写并说一说"}', 23, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14038, 558, '{"english": "Mike", "chinese": "迈克"}', 24, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14039, 558, '{"english": "Then", "chinese": "过去"}', 25, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14040, 558, '{"english": "couldn''t write", "chinese": "不会写"}', 26, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14041, 558, '{"english": "Now", "chinese": "现在"}', 27, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14042, 558, '{"english": "can do many things", "chinese": "会做许多事情"}', 28, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14043, 558, '{"english": "Mr Brown", "chinese": "布朗先生"}', 29, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14044, 558, '{"english": "Then", "chinese": "过去"}', 30, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14045, 558, '{"english": "wrote letters to friends", "chinese": "给朋友写信"}', 31, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14046, 558, '{"english": "used the telephone at home and in the office", "chinese": "用家里或办公室的电话"}', 32, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14047, 558, '{"english": "Now", "chinese": "现在"}', 33, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14048, 558, '{"english": "writes emails", "chinese": "写邮件"}', 34, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14049, 558, '{"english": "has a mobile phone", "chinese": "有一部手机"}', 35, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14050, 558, '{"english": "Grandpa", "chinese": "爷爷"}', 36, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14051, 558, '{"english": "Then", "chinese": "过去"}', 37, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14052, 558, '{"english": "listened to the radio", "chinese": "听收音机"}', 38, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14053, 558, '{"english": "read newspapers", "chinese": "看报"}', 39, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14054, 558, '{"english": "Now", "chinese": "现在"}', 40, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14055, 558, '{"english": "reads and watches news on the Internet", "chinese": "在网上看新闻"}', 41, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14056, 558, '{"english": "reads e-books", "chinese": "看电子书"}', 42, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14057, 558, '{"english": "Mrs Brown", "chinese": "布朗太太"}', 43, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14058, 558, '{"english": "Then", "chinese": "过去"}', 44, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14059, 558, '{"english": "made friends at school", "chinese": "在学校交朋友"}', 45, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14060, 558, '{"english": "bought things from shops", "chinese": "从商店里买东西"}', 46, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14061, 558, '{"english": "Now", "chinese": "现在"}', 47, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14062, 558, '{"english": "has e-friends from all over the world", "chinese": "有世界各地的网友"}', 48, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14063, 558, '{"english": "does shopping on the Internet", "chinese": "在网上购物"}', 49, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14064, 558, '{"english": "Six years ago, Mike couldn''t ...", "chinese": "六年前，迈克不会……"}', 50, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14065, 558, '{"english": "Now Mike can ...", "chinese": "现在迈克会……"}', 51, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14066, 558, '{"english": "Grammar time", "chinese": "语法时间"}', 52, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14067, 558, '{"english": "Six years ago, I couldn''t write. Twenty years ago, he wrote letters. Twenty years ago, she bought things from shops. Thirty years ago, they listened to the radio for news.", "chinese": "六年前，我还不会写字。 二十年前，他写了一封信。 二十年前，她在店里买东西。 三十年前，他们在收音机里听新闻。"}', 53, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14068, 558, '{"english": "couldn''t = could not", "chinese": "不能，不会"}', 54, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
INSERT INTO "course_content" VALUES (14069, 558, '{"english": "Do you remember these words?", "chinese": "你还记得这些单词吗？"}', 55, '2026-02-05 04:27:54', '2026-02-05 04:27:54');
