INSERT INTO "course_content" VALUES (14094, 558, '{"english": "Unit 4", "chinese": "第四单元"}', 80, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14095, 558, '{"english": "Fun time", "chinese": "娱乐时间"}', 81, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14096, 558, '{"english": "Make and say", "chinese": "做一做并说一说"}', 82, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14097, 558, '{"english": "Stick two photos.", "chinese": "粘贴两张照片。"}', 83, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14098, 558, '{"english": "____ year(s) ago", "chinese": "____年前"}', 84, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14099, 558, '{"english": "Now", "chinese": "现在"}', 85, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14100, 558, '{"english": "Point and say.", "chinese": "指一指并说一说。"}', 86, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14101, 558, '{"english": "... year(s) ago,", "chinese": "……年前，"}', 87, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14102, 558, '{"english": "I was ...", "chinese": "我是……"}', 88, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14103, 558, '{"english": "I could ...", "chinese": "我会……"}', 89, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14104, 558, '{"english": "I couldn''t ...", "chinese": "我不会……"}', 90, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14105, 558, '{"english": "I didn''t ...", "chinese": "我没有……"}', 91, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14106, 558, '{"english": "Now I''m ...", "chinese": "现在我是……"}', 92, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14107, 558, '{"english": "I can ...", "chinese": "我会……"}', 93, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14108, 558, '{"english": "I ...", "chinese": "我……"}', 94, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14109, 558, '{"english": "Sound time", "chinese": "发音时间"}', 95, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14110, 558, '{"english": "er", "chinese": ""}', 96, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14111, 558, '{"english": "My mother is a teacher.", "chinese": "我的妈妈是个老师。"}', 97, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14112, 558, '{"english": "She works hard every day.", "chinese": "她每天都工作得很努力。"}', 98, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14113, 558, '{"english": "My cousin is a worker.", "chinese": "我的表弟是个工人。"}', 99, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14114, 558, '{"english": "Now he''s on holiday.", "chinese": "现在他在度假。"}', 100, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14115, 558, '{"english": "mother", "chinese": "妈妈"}', 101, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14116, 558, '{"english": "sister", "chinese": "姐；妹"}', 102, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14117, 558, '{"english": "summer", "chinese": "夏天"}', 103, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14118, 558, '{"english": "teacher", "chinese": "老师"}', 104, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14119, 558, '{"english": "winter", "chinese": "冬天"}', 105, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14120, 558, '{"english": "Culture time", "chinese": "文化时间"}', 106, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14121, 558, '{"english": "The Chinese invented the compass.", "chinese": "中国人发明了指南针。"}', 107, '2026-02-05 04:27:55', '2026-02-05 04:27:55');
INSERT INTO "course_content" VALUES (14122, 558, '{"english": "The British invented the train.", "chinese": "英国人发明了火车。"}', 108, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14123, 558, '{"english": "Unit 4", "chinese": "第四单元"}', 109, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14124, 558, '{"english": "Cartoon time", "chinese": "卡通时间"}', 110, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14125, 558, '{"english": "It is an English lesson.", "chinese": "这是一节英语课。"}', 111, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14126, 558, '{"english": "Bobby is looking out of the window.", "chinese": "波比正望着窗外。"}', 112, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14127, 558, '{"english": "Bobby, please listen to me.", "chinese": "波比，请听我说。"}', 113, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14128, 558, '{"english": "Yes, Miss Fox.", "chinese": "好的，狐狸小姐。"}', 114, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14129, 558, '{"english": "The lesson goes on, but Bobby is still looking out of the window.", "chinese": "课堂继续，但是波比却仍然望着窗外。"}', 115, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14130, 558, '{"english": "Bobby, what day is today?", "chinese": "波比，今天是星期几？"}', 116, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14131, 558, '{"english": "It''s Wednesday, Miss Fox.", "chinese": "今天是星期三，狐狸小姐。"}', 117, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14132, 558, '{"english": "OK.", "chinese": "好的。"}', 118, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14133, 558, '{"english": "Can you spell it, Bobby?", "chinese": "你能拼写出来吗，波比？"}', 119, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14134, 558, '{"english": "W-e-d-n-e-s-d-a-y.", "chinese": "W-e-d-n-e-s-d-a-y."}', 120, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14135, 558, '{"english": "Now Bobby and Sam are talking.", "chinese": "此时波比和山姆正在交谈。"}', 121, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14136, 558, '{"english": "Miss Fox gets angry.", "chinese": "狐狸小姐生气了。"}', 122, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14137, 558, '{"english": "Sam, make a sentence with \"egg\".", "chinese": "山姆，用“鸡蛋”造一个句子。"}', 123, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14138, 558, '{"english": "I ate a cake yesterday.", "chinese": "我昨天吃了一个蛋糕。"}', 124, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14139, 558, '{"english": "Where''s the \"egg\"?", "chinese": "“鸡蛋”在哪儿？"}', 125, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14140, 558, '{"english": "Oh, the egg, the egg ...", "chinese": "噢，鸡蛋，鸡蛋……"}', 126, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14141, 558, '{"english": "Miss Fox waits for the answer.", "chinese": "狐狸小姐等着答案。"}', 127, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14142, 558, '{"english": "Miss Fox, the egg was in the cake.", "chinese": "狐狸小姐，鸡蛋在蛋糕里。"}', 128, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14143, 558, '{"english": "Unit 4", "chinese": "第四单元"}', 129, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14144, 558, '{"english": "Checkout time", "chinese": "检查时间"}', 130, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14145, 558, '{"english": "Tip", "chinese": "小贴士"}', 131, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14146, 558, '{"english": "Review the simple past tense.", "chinese": "复习一般过去时。"}', 132, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14147, 558, '{"english": "See page 90.", "chinese": "见第90页。"}', 133, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14148, 558, '{"english": "Look and write", "chinese": "看一看并写一写"}', 134, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14149, 558, '{"english": "What could they do?", "chinese": "他们会做什么？"}', 135, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14150, 558, '{"english": "What couldn''t they do?", "chinese": "他们不会做什么？"}', 136, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14151, 558, '{"english": "1 year old", "chinese": "1岁"}', 137, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14152, 558, '{"english": "Tim was one year old.", "chinese": "提姆1岁时。"}', 138, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14153, 558, '{"english": "He could not walk.", "chinese": "他不会走。"}', 139, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14154, 558, '{"english": "3 years old", "chinese": "3岁"}', 140, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14155, 558, '{"english": "Helen was three years old.", "chinese": "海伦3岁时。"}', 141, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14156, 558, '{"english": "She could not write.", "chinese": "她不会写字。"}', 142, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14157, 558, '{"english": "16 years old", "chinese": "16岁"}', 143, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14158, 558, '{"english": "Mr Brown was 16 years old.", "chinese": "布朗先生16岁时。"}', 144, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14159, 558, '{"english": "He could read.", "chinese": "他会读书。"}', 145, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14160, 558, '{"english": "15 years old", "chinese": "15岁"}', 146, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14161, 558, '{"english": "Mrs Brown was 15 years old.", "chinese": "布朗太太15岁时。"}', 147, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14162, 558, '{"english": "She could cook.", "chinese": "她会做饭。"}', 148, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14163, 558, '{"english": "6 years old", "chinese": "6岁"}', 149, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14164, 558, '{"english": "Mike was six years old.", "chinese": "迈克6岁时。"}', 150, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14165, 558, '{"english": "He could not ride.", "chinese": "他不会骑车。"}', 151, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14166, 558, '{"english": "Think and write", "chinese": "想一想并写一写"}', 152, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14167, 558, '{"english": "Stick a photo of yourself and then write about it.", "chinese": "粘贴一张你自己的照片然后关于这张照片写一写。"}', 153, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14168, 558, '{"english": "This was me ____ year(s) ago.", "chinese": "这是……年前的我。"}', 154, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14169, 558, '{"english": "I was ____.", "chinese": "我是_____。"}', 155, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14170, 558, '{"english": "I could ____.", "chinese": "我会_____。"}', 156, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14171, 558, '{"english": "I could not ____.", "chinese": "我不会_____。"}', 157, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14172, 558, '{"english": "Ticking time", "chinese": "评价时间"}', 158, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14173, 558, '{"english": "I can compare the past with the present.", "chinese": "我会比较过去与现在。"}', 159, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14174, 558, '{"english": "I can use \"... year(s) ago\".", "chinese": "我会用“... year(s) ago”这个句型。"}', 160, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14175, 558, '{"english": "I know the sound of \"er\".", "chinese": "我知道“er”的发音。"}', 161, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
INSERT INTO "course_content" VALUES (14176, 558, '{"english": "Unit 4", "chinese": "第四单元"}', 162, '2026-02-05 04:27:57', '2026-02-05 04:27:57');
