INSERT INTO "course_content" VALUES (14201, 560, '{"english": "Mike, Helen and Tim are at a shopping centre.", "chinese": "迈克，海伦和提姆在一个购物中心。"}', 3, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14202, 560, '{"english": "Be careful, Tim!", "chinese": "小心点，提姆！"}', 4, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14203, 560, '{"english": "Can you see the sign?", "chinese": "你看到那个标志了吗？"}', 5, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14204, 560, '{"english": "What does it mean?", "chinese": "它是什么意思？"}', 6, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14205, 560, '{"english": "It means the floor is wet.", "chinese": "它表示地板是湿的。"}', 7, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14206, 560, '{"english": "Then, they see a juice shop.", "chinese": "然后，他们看见了一个果汁店。"}', 8, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14207, 560, '{"english": "Do you want some juice?", "chinese": "你想要一些果汁吗？"}', 9, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14208, 560, '{"english": "Yes, please.", "chinese": "好的。"}', 10, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14209, 560, '{"english": "Here''s a sign.", "chinese": "这里有一个标志。"}', 11, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14210, 560, '{"english": "What does it mean, Mike?", "chinese": "它是什么意思，迈克？"}', 12, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14211, 560, '{"english": "It means you can''t litter here.", "chinese": "这表示你不能在这儿乱丢垃圾。"}', 13, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14212, 560, '{"english": "SALE", "chinese": "出售"}', 14, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14213, 560, '{"english": "No eating or drinking.", "chinese": "请勿饮食。"}', 15, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
