INSERT INTO "course_content" VALUES (14216, 560, '{"english": "There is a bookshop.", "chinese": "这里有一个书店。"}', 18, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14217, 560, '{"english": "Helen wants to go in.", "chinese": "海伦想进去。"}', 19, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14218, 560, '{"english": "You can''t take your juice into the shop, Helen.", "chinese": "你不能把果汁拿进书店，海伦。"}', 20, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14219, 560, '{"english": "Can you see that sign?", "chinese": "你看到那个标志了吗？"}', 21, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14220, 560, '{"english": "It means you can''t eat or drink there.", "chinese": "那表示你不能在那儿饮食。"}', 22, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
INSERT INTO "course_content" VALUES (14221, 560, '{"english": "I''m sorry.", "chinese": "对不起。"}', 23, '2026-02-05 04:28:00', '2026-02-05 04:28:00');
