INSERT INTO "course_content" VALUES (14287, 560, '{"english": "Bobby and Sam are on an outing in the forest.", "chinese": "波比和山姆外出去森林。"}', 89, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14288, 560, '{"english": "It is time for lunch.", "chinese": "到午餐时间了。"}', 90, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14289, 560, '{"english": "Bobby feels tired and hungry.", "chinese": "波比觉得又累又饿。"}', 91, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14290, 560, '{"english": "What are you doing, Bobby?", "chinese": "你在干什么，波比？"}', 92, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14291, 560, '{"english": "I''m looking for my bananas.", "chinese": "我在找我的香蕉。"}', 93, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14292, 560, '{"english": "I brought some for lunch.", "chinese": "我带了一些做午餐。"}', 94, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14293, 560, '{"english": "Bobby gives Sam a banana.", "chinese": "波比给山姆一个香蕉。"}', 95, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14294, 560, '{"english": "Do you want one, Sam?", "chinese": "你想要一个吗，山姆？"}', 96, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14295, 560, '{"english": "It''s sweet.", "chinese": "很甜的。"}', 97, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14296, 560, '{"english": "Thanks, Bobby.", "chinese": "谢谢，波比。"}', 98, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14297, 560, '{"english": "Bobby and Sam walk on.", "chinese": "波比和山姆继续走着。"}', 99, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14298, 560, '{"english": "They find a sign on a tree.", "chinese": "它们发现树上有一个标志。"}', 100, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14299, 560, '{"english": "Look, Bobby.", "chinese": "看，波比。"}', 101, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14300, 560, '{"english": "There''s a sign.", "chinese": "那里有一个标志。"}', 102, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14301, 560, '{"english": "What does it mean?", "chinese": "那是什么意思？"}', 103, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14302, 560, '{"english": "It means we can''t eat bananas here.", "chinese": "它表示我们不能在这里吃香蕉。"}', 104, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14303, 560, '{"english": "Why?", "chinese": "为什么？"}', 105, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14304, 560, '{"english": "Then, they see a lot of monkeys around them.", "chinese": "然后，它们看到周围有好多猴子。"}', 106, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14305, 560, '{"english": "They are looking at Bobby''s bananas.", "chinese": "它们在盯着波比的香蕉。"}', 107, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14306, 560, '{"english": "I know why we shouldn''t eat bananas here!", "chinese": "我知道为什么我们不能在这儿吃香蕉了！"}', 108, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14307, 560, '{"english": "Unit 5", "chinese": "第五单元"}', 109, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14308, 560, '{"english": "Checkout time", "chinese": "检查时间"}', 110, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14309, 560, '{"english": "Draw and say", "chinese": "画一画并说一说"}', 111, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14310, 560, '{"english": "Design signs for some public places.", "chinese": "为一些公共场所设计标志。"}', 112, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14311, 560, '{"english": "Then ask and answer the questions.", "chinese": "然后提问并回答。"}', 113, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14312, 560, '{"english": "What does this sign mean?", "chinese": "这个标志是什么意思？"}', 114, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14313, 560, '{"english": "It means ...", "chinese": "它表示……"}', 115, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14314, 560, '{"english": "Where can we put it?", "chinese": "我们可以把它放在哪里？"}', 116, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14315, 560, '{"english": "We can put it at/in ...", "chinese": "我们可以把它放在……"}', 117, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14316, 560, '{"english": "Listen and choose", "chinese": "听一听并选一选"}', 118, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14317, 560, '{"english": "Ticking time", "chinese": "评价时间"}', 119, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14318, 560, '{"english": "I know some public signs.", "chinese": "我知道一些公共标志。"}', 120, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14319, 560, '{"english": "I can use \"mean\" to ask and answer questions about signs.", "chinese": "我会就标志用“mean”提问并回答。"}', 121, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14320, 560, '{"english": "I know the sound of \"ir\".", "chinese": "我知道“ir”的发音。"}', 122, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14321, 560, '{"english": "Unit 5", "chinese": "第五单元"}', 123, '2026-02-05 04:28:02', '2026-02-05 04:28:02');
INSERT INTO "course_content" VALUES (14322, 561, '{"english": "Unit 6 Keep our city clean", "chinese": "第六单元 保持城市整洁"}', 1, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14323, 561, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14324, 561, '{"english": "Look at these old pictures of our city.", "chinese": "看这些我们城市的图片。"}', 3, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14325, 561, '{"english": "Was our city clean?", "chinese": "我们的城市干净吗？"}', 4, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14326, 561, '{"english": "No, it wasn''t.", "chinese": "不，不干净。"}', 5, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14327, 561, '{"english": "What made our city dirty?", "chinese": "是什么让我们的城市变得这么脏？"}', 6, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14328, 561, '{"english": "Smoke from cars made the air dirty.", "chinese": "汽车的烟雾使空气变脏。"}', 7, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14329, 561, '{"english": "Black smoke from factories made the air dirty too.", "chinese": "工厂的黑烟也会使空气变脏。"}', 8, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14330, 561, '{"english": "Rubbish made the streets messy and dirty.", "chinese": "垃圾使街道变得脏乱。"}', 9, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14331, 561, '{"english": "The river was dirty.", "chinese": "河流是脏的。"}', 10, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14332, 561, '{"english": "There was rubbish in the water and the fish were dead.", "chinese": "河里有垃圾，鱼儿们都死了。"}', 11, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14333, 561, '{"english": "clean", "chinese": "干净的"}', 12, '2026-02-05 04:28:03', '2026-02-05 04:28:03');
INSERT INTO "course_content" VALUES (14334, 561, '{"english": "dirty", "chinese": "脏的"}', 13, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14335, 561, '{"english": "bins", "chinese": "垃圾桶"}', 14, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14336, 561, '{"english": "Our city is clean now.", "chinese": "我们的城市现在很干净。"}', 15, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14337, 561, '{"english": "What can we do to keep it clean?", "chinese": "我们能做些什么来保持城市的整洁呢？"}', 16, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14338, 561, '{"english": "We can take the bus and the metro to school.", "chinese": "我们可以坐公交车和搭地铁去学校。"}', 17, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14339, 561, '{"english": "We can walk to school too.", "chinese": "我们也可以步行去学校。"}', 18, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14340, 561, '{"english": "We can put rubbish in the bin.", "chinese": "我们可以把垃圾扔进垃圾桶。"}', 19, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14341, 561, '{"english": "We can plant more trees.", "chinese": "我们可以种更多的树。"}', 20, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14342, 561, '{"english": "They help keep the air clean.", "chinese": "它们能使空气保持清新。"}', 21, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14343, 561, '{"english": "Your ideas are great.", "chinese": "你们的主意很棒。"}', 22, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14344, 561, '{"english": "Well done, class!", "chinese": "做得好，同学们！"}', 23, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14345, 561, '{"english": "a factory", "chinese": "一个工厂"}', 24, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14346, 561, '{"english": "rubbish", "chinese": "垃圾"}', 25, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14347, 561, '{"english": "smoke", "chinese": "烟雾"}', 26, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14348, 561, '{"english": "Unit 6", "chinese": "第六单元"}', 27, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14349, 561, '{"english": "Ask and answer", "chinese": "提问并回答"}', 28, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14350, 561, '{"english": "Was the city clean?", "chinese": "城市干净吗？"}', 29, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14351, 561, '{"english": "What made the air dirty?", "chinese": "什么使空气变脏？"}', 30, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14352, 561, '{"english": "What made the streets messy and dirty?", "chinese": "什么使街道脏乱？"}', 31, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14353, 561, '{"english": "Was the river dirty?", "chinese": "河流脏吗？"}', 32, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14354, 561, '{"english": "Think and write", "chinese": "想一想并写一写"}', 33, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14355, 561, '{"english": "What can we do to keep our city clean?", "chinese": "为了使我们的城市保持整洁，我们能做什么呢？"}', 34, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14356, 561, '{"english": "We can take the bus and the metro to school.", "chinese": "我们可以坐公交车和搭地铁去学校。"}', 35, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14357, 561, '{"english": "We can also walk to school.", "chinese": "我们也可以步行去学校。"}', 36, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14358, 561, '{"english": "We can put rubbish in the bin.", "chinese": "我们可以把垃圾扔进垃圾桶。"}', 37, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14359, 561, '{"english": "We can plant more trees.", "chinese": "我们可以种更多的树。"}', 38, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14360, 561, '{"english": "Grammar time", "chinese": "语法时间"}', 39, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14361, 561, '{"english": "What made the air dirty? What made the streets messy and dirty?", "chinese": "是什么让空气变得浑浊？ 是什么让街道变得又乱又脏？"}', 40, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14362, 561, '{"english": "Smoke made the air dirty. Rubbish made the streets messy and dirty.", "chinese": "吸烟使空气变得浑浊。 垃圾让街道变得又乱又脏。"}', 41, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14363, 561, '{"english": "What can we do to keep our city clean?", "chinese": "为保持城市干净我们可以做什么？"}', 42, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14364, 561, '{"english": "We can take the bus and the metro to school. We can walk to school. We can put rubblish in the bin. We can plant more trees.", "chinese": "我们可以搭乘公共汽车和地铁去学校。 我们可以步行去学校。 我们可以把垃圾扔进垃圾桶里。 我们可以种植更多的树木。"}', 43, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14365, 561, '{"english": "Unit 6", "chinese": "第六单元"}', 44, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14366, 561, '{"english": "Fun time", "chinese": "娱乐时间"}', 45, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14367, 561, '{"english": "Tip", "chinese": "小贴士"}', 46, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14368, 561, '{"english": "Give a speech on this topic.", "chinese": "就这个话题作一个演讲。"}', 47, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14369, 561, '{"english": "See page 91.", "chinese": "见第91页。"}', 48, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14370, 561, '{"english": "Make and write", "chinese": "做一做并写一写"}', 49, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14371, 561, '{"english": "What can we do to keep our school clean?", "chinese": "为了使我们的学校保持整洁，我们能做什么呢？"}', 50, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14372, 561, '{"english": "We can put rubbish in the bin.", "chinese": "我们可以把垃圾扔进垃圾桶。"}', 51, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14373, 561, '{"english": "We can sweep the floor.", "chinese": "我们可以打扫地面。"}', 52, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14374, 561, '{"english": "We can clean the desks and chairs.", "chinese": "我们可以清洁桌子和椅子。"}', 53, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14375, 561, '{"english": "We can _____.", "chinese": "我们可以_____."}', 54, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14376, 561, '{"english": "Sound time", "chinese": "发音时间"}', 55, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14377, 561, '{"english": "Intonation", "chinese": "语调"}', 56, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14378, 561, '{"english": "Do you throw rubbish on the floor?", "chinese": "你把垃圾扔在地上吗？"}', 57, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14379, 561, '{"english": "No, I don''t!", "chinese": "不，我没有！"}', 58, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14380, 561, '{"english": "I put my rubbish in the bin.", "chinese": "我把我的垃圾扔进垃圾桶。"}', 59, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14381, 561, '{"english": "Can we keep our city clean?", "chinese": "我们能保持城市整洁吗？"}', 60, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14382, 561, '{"english": "Yes, we can!", "chinese": "是的，我们能！"}', 61, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14383, 561, '{"english": "We can put our rubbish in the bin.", "chinese": "我们可以把我们的垃圾扔进垃圾桶。"}', 62, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14384, 561, '{"english": "Song time", "chinese": "唱歌时间"}', 63, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14385, 561, '{"english": "Two little blackbirds", "chinese": "两只小黑鸟"}', 64, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14386, 561, '{"english": "Two little blackbirds sitting on the hill, one named Jack and one named Jill.", "chinese": "歌词大意：两只小黑鸟坐在小山上，一个叫杰克，一个叫吉尔。"}', 65, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14387, 561, '{"english": "Fly away, Jack.", "chinese": "杰克飞走了。"}', 66, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14388, 561, '{"english": "Fly away, Jill.", "chinese": "吉尔飞走了。"}', 67, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14389, 561, '{"english": "Come back, Jack and come back, Jill.", "chinese": "杰克快回来，吉尔快回来。"}', 68, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14390, 561, '{"english": "Two little blackbirds sitting on the hill, one named Jack and one named Jill.", "chinese": "两只小黑鸟坐在小山上，一个叫杰克，一个叫吉尔。"}', 69, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14391, 561, '{"english": "Unit 6", "chinese": "第六单元"}', 70, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14392, 561, '{"english": "Cartoon time", "chinese": "卡通时间"}', 71, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14393, 561, '{"english": "Bobby and Tina are walking home after school.", "chinese": "放学后，波比和缇娜步行回家。"}', 72, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14394, 561, '{"english": "I like living in the city.", "chinese": "我喜欢住在城市里。"}', 73, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14395, 561, '{"english": "There are many museums, shops and cinemas.", "chinese": "这里有许多博物馆，商店和电影院。"}', 74, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14396, 561, '{"english": "I like living in the city too.", "chinese": "我也喜欢住在城市里。"}', 75, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14397, 561, '{"english": "It''s clean and beautiful.", "chinese": "它很干净，而且漂亮。"}', 76, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14398, 561, '{"english": "Bobby throws a banana skin on the ground.", "chinese": "波比把香蕉皮扔在马路上。"}', 77, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14399, 561, '{"english": "I like eating bananas.", "chinese": "我喜欢吃香蕉。"}', 78, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14400, 561, '{"english": "Bobby, you shouldn''t do that!", "chinese": "波比，你不应该那样做！"}', 79, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14401, 561, '{"english": "Pick it up.", "chinese": "把它捡起来。"}', 80, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14402, 561, '{"english": "It makes the street messy.", "chinese": "这使街道变得脏乱。"}', 81, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14403, 561, '{"english": "But it is too late.", "chinese": "但是太晚了。"}', 82, '2026-02-05 04:28:04', '2026-02-05 04:28:04');
INSERT INTO "course_content" VALUES (14404, 561, '{"english": "Billy slips on the banana skin and falls.", "chinese": "比利踩在香蕉皮上滑倒了。"}', 83, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14405, 561, '{"english": "Ouch!", "chinese": "哎呦！"}', 84, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14406, 561, '{"english": "Billy goes to hospital.", "chinese": "比利去医院。"}', 85, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14407, 561, '{"english": "I''m sorry, Billy.", "chinese": "对不起，比利。"}', 86, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14408, 561, '{"english": "Bobby, you should put your rubbish in the bin.", "chinese": "波比，你应该把垃圾扔进垃圾桶。"}', 87, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14409, 561, '{"english": "Unit 6", "chinese": "第六单元"}', 88, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14410, 561, '{"english": "Checkout time", "chinese": "检查时间"}', 89, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14411, 561, '{"english": "Look and wirte", "chinese": "看一看并写一写"}', 90, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14412, 561, '{"english": "The bedroom is messy.", "chinese": "房间乱七八糟的。"}', 91, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14413, 561, '{"english": "The clothes make the bed messy.", "chinese": "衣服使床上变乱。"}', 92, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14414, 561, '{"english": "The toys make the floor messy.", "chinese": "玩具使地板变乱。"}', 93, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14415, 561, '{"english": "Rubbish makes the park messy and dirty.", "chinese": "垃圾使公园又乱又脏。"}', 94, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14416, 561, '{"english": "To keep the park clean, we can put our rubbish in the bin.", "chinese": "为了使公园保持整洁，我们可以将垃圾扔进垃圾桶。"}', 95, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14417, 561, '{"english": "The classroom is messy and dirty.", "chinese": "教室又乱又脏。"}', 96, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14418, 561, '{"english": "To keep it clean, we can sweep the floor.", "chinese": "为了使教室保持整洁，我们可以打扫地面。"}', 97, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14419, 561, '{"english": "We can clean the desks and chairs.", "chinese": "我们可以清洁桌子和椅子。"}', 98, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14420, 561, '{"english": "Smoke makes the air dirty.", "chinese": "烟雾使空气变脏。"}', 99, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14421, 561, '{"english": "To keep the air clean, we can move some factories away from the city.", "chinese": "为了使空气保持清新，我们可以将一些工厂从城市搬走。"}', 100, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14422, 561, '{"english": "Look and say", "chinese": "看一看并说一说"}', 101, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14423, 561, '{"english": "What makes the room dirty and messy?", "chinese": "什么使房间又脏又乱？"}', 102, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14424, 561, '{"english": "...make(s) the ... dirty/messy.", "chinese": "……使……又脏又乱。"}', 103, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14425, 561, '{"english": "To keep the ... clean, we can...", "chinese": "为了使……保持干净，我们可以……"}', 104, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14426, 561, '{"english": "You", "chinese": "你"}', 105, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14427, 561, '{"english": "Ticking time", "chinese": "评价时间"}', 106, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14428, 561, '{"english": "I know how to keep our city clean.", "chinese": "我知道怎样保持城市整洁。"}', 107, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14429, 561, '{"english": "I can use \"make\", \"keep\" and \"can\".", "chinese": "我会用“make”“keep”和“can”。"}', 108, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14430, 561, '{"english": "I know how to use rising and falling intonation.", "chinese": "我知道怎样用升调和降调。"}', 109, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14431, 561, '{"english": "Unit 6", "chinese": "第六单元"}', 110, '2026-02-05 04:28:05', '2026-02-05 04:28:05');
INSERT INTO "course_content" VALUES (14432, 562, '{"english": "Unit 7 Protect the Earth", "chinese": "第七单元 保护地球"}', 1, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14433, 562, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14434, 562, '{"english": "Save water", "chinese": "节约用水"}', 3, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14435, 562, '{"english": "Water is useful.", "chinese": "水是有用的。"}', 4, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14436, 562, '{"english": "We drink water and use water to clean things every day.", "chinese": "我们每天都要喝水，用水清洁物品。"}', 5, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14437, 562, '{"english": "In many places, there is not much water.", "chinese": "在很多地方并没有很多水。"}', 6, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14438, 562, '{"english": "We should not waste water.", "chinese": "我们不能浪费水。"}', 7, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14439, 562, '{"english": "We should reuse and save it.", "chinese": "我们应该重复利用水并且节约用水。"}', 8, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14440, 562, '{"english": "Save energy", "chinese": "节约能源"}', 9, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14441, 562, '{"english": "Most of our energy comes from coal and oil.", "chinese": "我们的大部分能源是来自煤炭和石油。"}', 10, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14442, 562, '{"english": "There is not much coal or oil on Earth.", "chinese": "地球上没有太多的煤炭和石油。"}', 11, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14443, 562, '{"english": "We should save energy.", "chinese": "我们应该节约能源。"}', 12, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14444, 562, '{"english": "We should not drive so much because cars use a lot of energy.", "chinese": "我们不应该如此频繁地驾车，因为汽车需要消耗许多能源。"}', 13, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14445, 562, '{"english": "coal", "chinese": "煤炭"}', 14, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14446, 562, '{"english": "Earth", "chinese": "地球"}', 15, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14447, 562, '{"english": "oil", "chinese": "石油"}', 16, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14448, 562, '{"english": "Save trees", "chinese": "节约树木"}', 17, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14449, 562, '{"english": "Wood comes from trees.", "chinese": "木材来源于树。"}', 18, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14450, 562, '{"english": "We use wood to make tables, chairs and many other things.", "chinese": "我们用木材制作桌子，椅子还有许多其他的东西。"}', 19, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14451, 562, '{"english": "We should not cut down too many trees because trees help keep the air clean.", "chinese": "我们不应该砍伐太多的树，因为树木有助于保持空气清新。"}', 20, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14452, 562, '{"english": "Don’t use too much plastic", "chinese": "不要使用过多的塑料制品"}', 21, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14453, 562, '{"english": "We use plastic to make bags and bottles, but too much plastic is bad for the Earth.", "chinese": "我们用塑料制作袋子和瓶子，但是过多的塑料会对地球造成损害。"}', 22, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14454, 562, '{"english": "We should not use too many plastic bags or bottles.", "chinese": "我们不应该使用过多的塑料袋或塑料瓶。"}', 23, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14455, 562, '{"english": "We should use paper bags and glass bottles.", "chinese": "我们应该用纸制袋和玻璃瓶。"}', 24, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14456, 562, '{"english": "paper", "chinese": "纸"}', 25, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14457, 562, '{"english": "plastic", "chinese": "塑料；塑料制品"}', 26, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14458, 562, '{"english": "wood", "chinese": "木材"}', 27, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14459, 562, '{"english": "Unit 7", "chinese": "第七单元"}', 28, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14460, 562, '{"english": "True or false", "chinese": "判断对错"}', 29, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14461, 562, '{"english": "There is not much water in many places.", "chinese": "在许多地方没有很多水。"}', 30, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14462, 562, '{"english": "Cars do not use much energy.", "chinese": "汽车不用太多能源。"}', 31, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14463, 562, '{"english": "We should not cut down trees.", "chinese": "我们不应该砍伐树木。"}', 32, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14464, 562, '{"english": "Trees help keep the air clean.", "chinese": "树木使空气保持清新。"}', 33, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14465, 562, '{"english": "We should not use plastic bags because they are not useful.", "chinese": "我们不应该用塑料袋因为它们没什么作用。"}', 34, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14466, 562, '{"english": "Think and write", "chinese": "想一想并写一写"}', 35, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14467, 562, '{"english": "How to protect the Earth", "chinese": "怎样保护地球"}', 36, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14468, 562, '{"english": "We should save water and reuse water.", "chinese": "我们应该节约水并重复利用水。"}', 37, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14469, 562, '{"english": "We should not waste water.", "chinese": "我们不应该浪费水。"}', 38, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14470, 562, '{"english": "We should save energy.", "chinese": "我们应该节约能源。"}', 39, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14471, 562, '{"english": "We should not drive so much.", "chinese": "我们不应该如此频繁地驾车。"}', 40, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14472, 562, '{"english": "We should save trees.", "chinese": "我们应该节约树木。"}', 41, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14473, 562, '{"english": "We should not cut down too many trees.", "chinese": "我们不应该过多砍伐树木。"}', 42, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14474, 562, '{"english": "We should not use too many plastic bags or bottles.", "chinese": "我们不应该使用过多的塑料袋或塑料瓶。"}', 43, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14475, 562, '{"english": "We should use paper bags and glass bottles.", "chinese": "我们应该使用纸制袋和玻璃瓶。"}', 44, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14476, 562, '{"english": "Grammar time", "chinese": "语法时间"}', 45, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14477, 562, '{"english": "We use water to clean things. We use plastic to make bags and bottles. We use wood to make tables, chairs and other things.", "chinese": "我们用水来清洁。 我们用塑料制造袋子和瓶子。 我们用木头制造桌子、椅子及其他物品。"}', 46, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14478, 562, '{"english": "Let''s review these.", "chinese": "让我们复习这些。"}', 47, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14479, 562, '{"english": "We should use paper bags and glass bottles. We should save trees.", "chinese": "我们应该使用纸袋子和玻璃瓶。 我们应该保护树木。"}', 48, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14480, 562, '{"english": "We should not drive so much. We should not use too many plastic bags or bottles. We should not cut down many trees. We should not waste water.", "chinese": "我们不应该频繁开车。 我们不应该使用太多塑料袋和塑料瓶。 我们不应该砍伐许多树木。 我们不应该浪费水。"}', 49, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14481, 562, '{"english": "Unit 7", "chinese": "第七单元"}', 50, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14482, 562, '{"english": "Fun time", "chinese": "娱乐时间"}', 51, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14483, 562, '{"english": "Make and say", "chinese": "做一做并说一说"}', 52, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14484, 562, '{"english": "Collect some paper, plastic bags and plastic bottles.", "chinese": "收集一些纸，塑料袋和塑料瓶。"}', 53, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14485, 562, '{"english": "How can we reuse these things?", "chinese": "我们该怎样重新利用这些东西？"}', 54, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14486, 562, '{"english": "I can reuse paper to make a box.", "chinese": "我可以再利用纸做一个盒子。"}', 55, '2026-02-05 04:28:06', '2026-02-05 04:28:06');
INSERT INTO "course_content" VALUES (14487, 562, '{"english": "I an reuse a plastic bottle to make a toy.", "chinese": "我可以再利用一个塑料瓶做一个玩具。"}', 56, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14488, 562, '{"english": "Sound time", "chinese": "发音时间"}', 57, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14489, 562, '{"english": "oo", "chinese": ""}', 58, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14490, 562, '{"english": "Every day I go to school.", "chinese": "我每天去上学。"}', 59, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14491, 562, '{"english": "I think it''s really cool!", "chinese": "我认为那真的很酷！"}', 60, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14492, 562, '{"english": "We have fun in the classroom", "chinese": "我们都在教室里娱乐玩耍！"}', 61, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14493, 562, '{"english": "Every morning and afternoon!", "chinese": "每天早上和下午"}', 62, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14494, 562, '{"english": "cool", "chinese": "酷的"}', 63, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14495, 562, '{"english": "food", "chinese": "食物"}', 64, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14496, 562, '{"english": "room", "chinese": "房间"}', 65, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14497, 562, '{"english": "school", "chinese": "学校"}', 66, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14498, 562, '{"english": "zoo", "chinese": "动物园"}', 67, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14499, 562, '{"english": "Culture time", "chinese": "文化时间"}', 68, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14500, 562, '{"english": "Earth Day is on 22nd April.", "chinese": "地球日是4月22日。"}', 69, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14501, 562, '{"english": "World Environment Day is on 5th June.", "chinese": "世界环境日是6月5日。"}', 70, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14502, 562, '{"english": "We should love and protect our Earth.", "chinese": "我们应该热爱和保护我们的地球。"}', 71, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14503, 562, '{"english": "PROTECT OUR EARTH", "chinese": "保护我们的地球"}', 72, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14504, 562, '{"english": "Unit 7", "chinese": "第七单元"}', 73, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14505, 562, '{"english": "Cartoon time", "chinese": "卡通时间"}', 74, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14506, 562, '{"english": "Tip", "chinese": "小贴士"}', 75, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14507, 562, '{"english": "Make a poster with your classmates.", "chinese": "和你的同学一起做一张海报。"}', 76, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14508, 562, '{"english": "See page 91.", "chinese": "见第91页。"}', 77, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14509, 562, '{"english": "Bobby and Sam are doing a project.", "chinese": "波比和山姆在做一个课题。"}', 78, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14510, 562, '{"english": "The Earth is our home.", "chinese": "地球是我们的家。"}', 79, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14511, 562, '{"english": "We should protect it.", "chinese": "我们应该保护它。"}', 80, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14512, 562, '{"english": "All students should know this.", "chinese": "所有的学生都应该知道这点。"}', 81, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14513, 562, '{"english": "Let''s make a poster and tell them about it.", "chinese": "让我们一起做一张海报然后告诉其他同学。"}', 82, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14514, 562, '{"english": "OK.", "chinese": "好的。"}', 83, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14515, 562, '{"english": "I can help you.", "chinese": "我能帮助你。"}', 84, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14516, 562, '{"english": "Sam starts drawing.", "chinese": "山姆开始画画。"}', 85, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14517, 562, '{"english": "Let me draw the Earth first.", "chinese": "让我先画地球。"}', 86, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14518, 562, '{"english": "It''s green, blue and brown.", "chinese": "它是绿色，蓝色和棕色的。"}', 87, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14519, 562, '{"english": "There are trees and flowers on it.", "chinese": "上面有树，还有花儿。"}', 88, '2026-02-05 04:28:07', '2026-02-05 04:28:07');
INSERT INTO "course_content" VALUES (14520, 562, '{"english": "That looks nice!", "chinese": "看起来真不错！"}', 89, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14521, 562, '{"english": "Protect the Earth", "chinese": "保护地球"}', 90, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14522, 562, '{"english": "Then, Bobby and Billy draw.", "chinese": "然后，波比和比利画画。"}', 91, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14523, 562, '{"english": "Let me draw some bananas on the trees.", "chinese": "让我在树上画一些香蕉。"}', 92, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14524, 562, '{"english": "Let me draw a rubbish bin.", "chinese": "让我画一个垃圾桶。"}', 93, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14525, 562, '{"english": "You shouldn''t litter, Bobby.", "chinese": "你不应该乱丢垃圾，波比。"}', 94, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14526, 562, '{"english": "The poster is ready.", "chinese": "海报准备好了。"}', 95, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14527, 562, '{"english": "They put it at the school gate.", "chinese": "它们把他放在学校门口。"}', 96, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14528, 562, '{"english": "What a nice poster!", "chinese": "多好看的海报啊！"}', 97, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14529, 562, '{"english": "We should protect the Earth and keep it clean.", "chinese": "我们应该保护地球，保持地球干净。"}', 98, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14530, 562, '{"english": "Protect the Earth", "chinese": "保护地球"}', 99, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14531, 562, '{"english": "Unit 7", "chinese": "第七单元"}', 100, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14532, 562, '{"english": "Checkout time", "chinese": "检查时间"}', 101, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14533, 562, '{"english": "Look and write", "chinese": "看一看并写一写"}', 102, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14534, 562, '{"english": "What should they not do?", "chinese": "他们不应该做什么？"}', 103, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14535, 562, '{"english": "He should not waste water.", "chinese": "他们不应该浪费水。"}', 104, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14536, 562, '{"english": "They should not litter in the park.", "chinese": "他们不应该在公园乱丢垃圾。"}', 105, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14537, 562, '{"english": "They should not cut down trees.", "chinese": "他们不应该砍伐树木。"}', 106, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14538, 562, '{"english": "They should not throw rubbish in the river.", "chinese": "他们不应该往河里扔垃圾。"}', 107, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14539, 562, '{"english": "They should not talk in the library.", "chinese": "他们不应该在图书馆里交谈。"}', 108, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14540, 562, '{"english": "They should not use plastic bags.", "chinese": "他们不应该使用塑料袋。"}', 109, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14541, 562, '{"english": "Think and write", "chinese": "想一想并写一写"}', 110, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14542, 562, '{"english": "To protect the Earth, what should we do?", "chinese": "为了保护地球，我们应该做什么？"}', 111, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14543, 562, '{"english": "What should we not do?", "chinese": "我们不应该做什么？"}', 112, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14544, 562, '{"english": "Protect the Earth", "chinese": "保护地球"}', 113, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14545, 562, '{"english": "To protect the Earth, we should ______ To protect the Earth, we should not ______", "chinese": "为了保护地球，我们应该______ 为了保护地球，我们不应该______"}', 114, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14546, 562, '{"english": "Ticking time", "chinese": "评价时间"}', 115, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14547, 562, '{"english": "I know how to protect the Earth.", "chinese": "我知道怎样保护地球。"}', 116, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14548, 562, '{"english": "I can use \"use ... to ...\".", "chinese": "我会用“use ... to ...”。"}', 117, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14549, 562, '{"english": "I know the sound of \"oo\".", "chinese": "我知道“oo”的发音。"}', 118, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14550, 562, '{"english": "Unit 7", "chinese": "第七单元"}', 119, '2026-02-05 04:28:08', '2026-02-05 04:28:08');
INSERT INTO "course_content" VALUES (14551, 563, '{"english": "Unit 8 Chinese New Year", "chinese": "第八单元  春节"}', 1, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14552, 563, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14553, 563, '{"english": "Tip", "chinese": "小贴士"}', 3, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14554, 563, '{"english": "How to write an English email?", "chinese": "如何写英文电子邮件？"}', 4, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14555, 563, '{"english": "See page 91.", "chinese": "见第91页。"}', 5, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14556, 563, '{"english": "Chinese New Year is coming.", "chinese": "春节到了。"}', 6, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14557, 563, '{"english": "Su Hai gets an email from her e-friend Anna in Hong Kong.", "chinese": "苏海收到了一封身在香港的网友安娜的邮件。"}', 7, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14558, 563, '{"english": "To: Su Hai", "chinese": "致：苏海"}', 8, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14559, 563, '{"english": "Subject: Chinese New Year", "chinese": "主题：春节"}', 9, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14560, 563, '{"english": "Dear Su Hai, How are you?", "chinese": "亲爱的苏海，你好吗？"}', 10, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14561, 563, '{"english": "It''s going to be Chinese New Year next week.", "chinese": "下周就是春节了。"}', 11, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14562, 563, '{"english": "I''m very excited!", "chinese": "我非常激动！"}', 12, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14563, 563, '{"english": "Tomorrow, my family and I are going to buy some new clothes and food.", "chinese": "明天，我和我的家人将去买一些新衣服和食物。"}', 13, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14564, 563, '{"english": "Then, in the evening, we''re going to make some cakes and tangyuan.", "chinese": "然后，我们准备晚上做一些蛋糕和汤圆。"}', 14, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14565, 563, '{"english": "firecrackers", "chinese": "鞭炮"}', 15, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14566, 563, '{"english": "fireworks", "chinese": "烟花，烟火"}', 16, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14567, 563, '{"english": "On Chinese New Year''s Eve, we''re going to have dinner with my grandparents, my aunt and uncle and my cousin.", "chinese": "在春节除夕夜，我们将会与我的爷爷奶奶，叔叔阿姨，还有我的表兄弟们一起共进晚餐。"}', 17, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14568, 563, '{"english": "Then, we''re going to buy some flowers.", "chinese": "然后，我们准备去买一些花卉。"}', 18, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14569, 563, '{"english": "On Chinese New Year''s Day, my parents are going to give me red packets.", "chinese": "在春节那天，我的父母将会给我红包。"}', 19, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14570, 563, '{"english": "Then, we''re going to watch a lion dance in the afternoon.", "chinese": "然后，我们会在下午去看舞龙狮。"}', 20, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14571, 563, '{"english": "On the second day of Chinese New Year, we''re going to watch fireworks in the evening.", "chinese": "在春节的第二天，我们准备晚上去看烟火。"}', 21, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14572, 563, '{"english": "What are you going to do at Chinese New Year?", "chinese": "你打算在春节做什么呢？"}', 22, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14573, 563, '{"english": "Love, Anna.", "chinese": "爱你，安娜。"}', 23, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14574, 563, '{"english": "a lion dance", "chinese": "舞龙狮"}', 24, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14575, 563, '{"english": "red packets", "chinese": "红包"}', 25, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14576, 563, '{"english": "Unit 8", "chinese": "第八单元  春节"}', 26, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14577, 563, '{"english": "Look and order", "chinese": "看一看并排序"}', 27, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14578, 563, '{"english": "What is Anna going to do at Chinese New Year?", "chinese": "安娜准备在春节做什么？"}', 28, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14579, 563, '{"english": "Think and write", "chinese": "想一想并写一写"}', 29, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14580, 563, '{"english": "Complete the notes.", "chinese": "完成摘要。"}', 30, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14581, 563, '{"english": "Before Chinese New Year", "chinese": "春节前"}', 31, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14582, 563, '{"english": "buy some new clothes and food", "chinese": "买一些新衣服和食物"}', 32, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14583, 563, '{"english": "make some cakes and tangyuan", "chinese": "做一些蛋糕和汤圆"}', 33, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14584, 563, '{"english": "On Chinese New Year''s Eve", "chinese": "在春节除夕夜"}', 34, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14585, 563, '{"english": "have dinner with family", "chinese": "与家人共进晚餐"}', 35, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14586, 563, '{"english": "buy some flowers", "chinese": "买一些花卉"}', 36, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14587, 563, '{"english": "On Chinese New Year''s Day", "chinese": "在春节当天"}', 37, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14588, 563, '{"english": "get red packets from parents", "chinese": "从父母那儿得到红包"}', 38, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14589, 563, '{"english": "watch a lion dance", "chinese": "看一场舞龙狮"}', 39, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14590, 563, '{"english": "On 2nd day of Chinese New Year", "chinese": "在春节第二天"}', 40, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14591, 563, '{"english": "watch fireworks", "chinese": "看烟火"}', 41, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14592, 563, '{"english": "Grammar time", "chinese": "语法时间"}', 42, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14593, 563, '{"english": "What are you going to do on Chinese New Year''s Eve? What are they going to buy at Chinese New Year? What is he going to eat at Chinese New Year? What is she going to watch on Chinese New Year''s Day?", "chinese": "你（们）打算在除夕做什么？ 他们打算在新年买什么？ 他打算在新年吃什么？ 她打算在新年看什么？"}', 43, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
INSERT INTO "course_content" VALUES (14594, 563, '{"english": "I''m going to buy some flowers. We''re going to have a big dinner. They''re going to make some cakes and tangyuan. He''s going to watch a lion dance. She''s going to watch fireworks.", "chinese": "我打算买一些花。 我们打算吃大餐。 他们打算做蛋糕和汤圆。 他打算看舞狮。 她打算看烟花。"}', 44, '2026-02-05 04:28:09', '2026-02-05 04:28:09');
