INSERT INTO "course_content" VALUES (14863, 567, '{"english": "Unit 1 The lion and the mouse", "chinese": "第一单元 狮子和老鼠"}', 1, '2026-02-05 04:28:18', '2026-02-05 04:28:18');
INSERT INTO "course_content" VALUES (14864, 567, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14865, 567, '{"english": "Tip,Make a study plan.", "chinese": "小贴士，制订学习计划。"}', 3, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14866, 567, '{"english": "See page 90.", "chinese": "见第90页。"}', 4, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14867, 567, '{"english": "There was a lion in the forest.", "chinese": "森林里有一头狮子。"}', 5, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14868, 567, '{"english": "He was very large and strong.", "chinese": "他既高大又强壮。"}', 6, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14869, 567, '{"english": "One day, a mouse walked by and woke the lion up.", "chinese": "有一天，有只老鼠走过，把狮子给吵醒了。"}', 7, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14870, 567, '{"english": "The lion was angry and wanted to eat the mouse.", "chinese": "狮子很生气，想要吃了那只老鼠。"}', 8, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14871, 567, '{"english": "\"Please don''t eat me.", "chinese": "“请你不要吃我。"}', 9, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14872, 567, '{"english": "I can help you some day,\" said the mouse quietly.", "chinese": "有朝一日我可以帮助你。”老鼠小声地说道。"}', 10, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14873, 567, '{"english": "\"You''re so small and weak!", "chinese": "“你这么小，又这么软弱！”"}', 11, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14874, 567, '{"english": "How can you help me?\"", "chinese": "你怎么能帮助我？"}', 12, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14875, 567, '{"english": "laughed the lion loudly.", "chinese": "狮子大声地笑道。"}', 13, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14876, 567, '{"english": "Then, he let the mouse go.", "chinese": "然后，他就把老鼠给放走了。"}', 14, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14877, 567, '{"english": "large", "chinese": "大的"}', 15, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14878, 567, '{"english": "sharp", "chinese": "锋利的，尖的"}', 16, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14879, 567, '{"english": "The next day, two men caught the lion with a large net.", "chinese": "第二天，有两个人用一张大网把狮子给逮住了。"}', 17, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14880, 567, '{"english": "The lion bit the net with his sharp teeth, but that did not help.", "chinese": "狮子用他那锋利的牙齿咬那张网，但是无济于事。"}', 18, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14881, 567, '{"english": "\"How can I get out?\"", "chinese": "“我怎样才能出去呢？”"}', 19, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14882, 567, '{"english": "Asked the lion sadly.", "chinese": "狮子伤心地问道。"}', 20, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14883, 567, '{"english": "Just then, the mouse saw the lion.", "chinese": "就在那时，老鼠看见了狮子。"}', 21, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14884, 567, '{"english": "\"I can help you,\" he said.", "chinese": "“我可以帮你，”他说。"}', 22, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14885, 567, '{"english": "Soon, the mouse made a big hole in the net with his teeth.", "chinese": "很快，老鼠用牙齿在那张网中咬了个大洞。"}', 23, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14886, 567, '{"english": "The lion got out.", "chinese": "狮子出去了。"}', 24, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14887, 567, '{"english": "\"Thank you!\" said the lion happily.", "chinese": "“谢谢你！”狮子高兴地说道。"}', 25, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14888, 567, '{"english": "From then on, the lion and the mouse became friends.", "chinese": "从那时起，狮子和老鼠变成了朋友。"}', 26, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14889, 567, '{"english": "strong", "chinese": "强大的，强壮的"}', 27, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14890, 567, '{"english": "weak", "chinese": "弱的，软弱的"}', 28, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14891, 567, '{"english": "Read and order", "chinese": "读一读并进行排序"}', 29, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14892, 567, '{"english": "The lion caught the mouse.", "chinese": "狮子抓住了老鼠。"}', 30, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14893, 567, '{"english": "The lion and the mouse became good friends.", "chinese": "狮子和老鼠变成了好朋友。"}', 31, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14894, 567, '{"english": "The lion could not get out from the net.", "chinese": "狮子无法从那张网里逃出去。"}', 32, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14895, 567, '{"english": "The mouse woke the lion up.", "chinese": "老鼠把狮子给吵醒了。"}', 33, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14896, 567, '{"english": "The lion let the mouse go.", "chinese": "狮子放走了老鼠。"}', 34, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14897, 567, '{"english": "The mouse helped the lion get out.", "chinese": "老鼠帮助狮子逃了出去。"}', 35, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14898, 567, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 36, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14899, 567, '{"english": "Who woke the lion up?", "chinese": "是谁吵醒了狮子？"}', 37, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14900, 567, '{"english": "Did the lion eat the mouse?", "chinese": "狮子吃掉老鼠了吗？"}', 38, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14901, 567, '{"english": "How did the men catch the lion?", "chinese": "那些人是怎样逮住狮子的？"}', 39, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14902, 567, '{"english": "How did the mouse help the lion?", "chinese": "老鼠是怎样帮助狮子的？"}', 40, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14903, 567, '{"english": "What did the lion and the mouse become?", "chinese": "狮子和老鼠变成了什么？"}', 41, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14904, 567, '{"english": "Grammar time", "chinese": "语法时间"}', 42, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14905, 567, '{"english": "The lion asked sadly / laughed loudly. The mouse said quietly / happily.", "chinese": "狮子伤心地问 / 大声地笑。 老鼠悄悄地 / 高兴地说。"}', 43, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14906, 567, '{"english": "He''s a happy boy.", "chinese": "他是个快乐的男孩。"}', 44, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14907, 567, '{"english": "He laughs happily.", "chinese": "他开心地笑着。"}', 45, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14908, 567, '{"english": "excited → excitedly", "chinese": "兴奋的 兴奋地"}', 46, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14909, 567, '{"english": "quiet → quietly", "chinese": "安静的 安静地"}', 47, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14910, 567, '{"english": "loud → loudly", "chinese": "大声的 大声地"}', 48, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14911, 567, '{"english": "sad → sadly", "chinese": "伤心的 伤心地"}', 49, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14912, 567, '{"english": "happy → happily", "chinese": "高兴的 高兴地"}', 50, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14913, 567, '{"english": "bite → bit", "chinese": "咬"}', 51, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14914, 567, '{"english": "let → let", "chinese": "让，允许"}', 52, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14915, 567, '{"english": "wake → woke", "chinese": "唤醒，醒来"}', 53, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14916, 567, '{"english": "Fun time", "chinese": "娱乐时间"}', 54, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14917, 567, '{"english": "Say and act", "chinese": "说一说，演一演"}', 55, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14918, 567, '{"english": "I''m ... and ...", "chinese": "我既……又……"}', 56, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14919, 567, '{"english": "Here comes the lion.", "chinese": "狮子来了。"}', 57, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14920, 567, '{"english": "Run!", "chinese": "快跑！"}', 58, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14921, 567, '{"english": "What are you doing here, Little Mouse?", "chinese": "你在这里干什么，小老鼠？"}', 59, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14922, 567, '{"english": "I''m going to ...!", "chinese": "我要……！"}', 60, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14923, 567, '{"english": "Please don''t ..., Lion.", "chinese": "请不要……，狮子。"}', 61, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14924, 567, '{"english": "I can ... some day.", "chinese": "有朝一日我可以……。"}', 62, '2026-02-05 04:28:19', '2026-02-05 04:28:19');
INSERT INTO "course_content" VALUES (14925, 567, '{"english": "Ha!", "chinese": "哈！"}', 63, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14926, 567, '{"english": "Ha!", "chinese": "哈！"}', 64, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14927, 567, '{"english": "You''re so ...", "chinese": "你这么……"}', 65, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14928, 567, '{"english": "How can you help me?", "chinese": "你怎么能帮我呢？"}', 66, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14929, 567, '{"english": "Help!", "chinese": "救命啊！"}', 67, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14930, 567, '{"english": "Help!", "chinese": "救命啊！"}', 68, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14931, 567, '{"english": "Please help me!", "chinese": "请救救我吧！"}', 69, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14932, 567, '{"english": "Don''t be ..., Lion.", "chinese": "不要……，狮子。"}', 70, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14933, 567, '{"english": "I can help you!", "chinese": "我可以帮你！"}', 71, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14934, 567, '{"english": "..., Little Mouse!", "chinese": "……，小老鼠！"}', 72, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14935, 567, '{"english": "Sound time", "chinese": "语音时间"}', 73, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14936, 567, '{"english": "Intonation", "chinese": "语调"}', 74, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14937, 567, '{"english": "Where are you going?", "chinese": "你要去哪儿？"}', 75, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14938, 567, '{"english": "To the sweet shop.", "chinese": "去糖果店。"}', 76, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14939, 567, '{"english": "What do you want to buy?", "chinese": "你想要买什么？"}', 77, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14940, 567, '{"english": "A lollipop.", "chinese": "棒棒糖。"}', 78, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14941, 567, '{"english": "Who is it for?", "chinese": "是买给谁的？"}', 79, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14942, 567, '{"english": "The boy over there.", "chinese": "那边那个男孩。"}', 80, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14943, 567, '{"english": "What will he say?", "chinese": "他将会说什么？"}', 81, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14944, 567, '{"english": "It doesn''t matter.", "chinese": "没关系。"}', 82, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14945, 567, '{"english": "Culture time", "chinese": "文化时间"}', 83, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14946, 567, '{"english": "I like the story \"The fox and the crow\".", "chinese": "我喜欢《狐狸与乌鸦》这个故事。"}', 84, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14947, 567, '{"english": "Do you like animal fables?", "chinese": "你喜欢动物寓言吗？"}', 85, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14948, 567, '{"english": "Yes, I do.", "chinese": "喜欢。"}', 86, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14949, 567, '{"english": "I like \"The monkeys and the moon.\"", "chinese": "我喜欢《猴子捞月》。"}', 87, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14950, 567, '{"english": "Cartoon time", "chinese": "卡通时间"}', 88, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14951, 567, '{"english": "Sam and Bobby are playing table tennis happily.", "chinese": "萨姆和波比正在高兴地打乒乓球。"}', 89, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14952, 567, '{"english": "You''re really good at table tennis, Sam.", "chinese": "你真的很擅长打乒乓球，萨姆。"}', 90, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14953, 567, '{"english": "Thanks.", "chinese": "谢谢。"}', 91, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14954, 567, '{"english": "Billy and Willy cheer for them loudly.", "chinese": "比利和维利在大声地给他们加油。"}', 92, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14955, 567, '{"english": "Sam is too excited and he hits the ball hard.", "chinese": "萨姆太兴奋了，于是他用力地击球。"}', 93, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14956, 567, '{"english": "Then, they cannot find the ball.", "chinese": "然后，他们就找不到那个球了。"}', 94, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14957, 567, '{"english": "Hooray!", "chinese": "万岁！"}', 95, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14958, 567, '{"english": "Finally, Sam and Bobby find a hole in the ground.", "chinese": "最后，萨姆和波比发现地上有个洞。"}', 96, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14959, 567, '{"english": "Is the ball in the hole?", "chinese": "球是在这个洞里面吗？"}', 97, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14960, 567, '{"english": "Yes!", "chinese": "是的！"}', 98, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14961, 567, '{"english": "I can see it.", "chinese": "我能看见它。"}', 99, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14962, 567, '{"english": "But it''s too deep.", "chinese": "但是洞太深了。"}', 100, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14963, 567, '{"english": "I can''t reach it.", "chinese": "我够不着。"}', 101, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14964, 567, '{"english": "Sam has an idea.", "chinese": "萨姆有个主意。"}', 102, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14965, 567, '{"english": "He brings some water quickly and pours it into the hole.", "chinese": "他很快带来一些水，然后把它倒进洞里。"}', 103, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14966, 567, '{"english": "Well done, Sam.", "chinese": "干得好，萨姆。"}', 104, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14967, 567, '{"english": "There are so many balls!", "chinese": "有这么多的球啊！"}', 105, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14968, 567, '{"english": "Checkout time", "chinese": "检测时间"}', 106, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14969, 567, '{"english": "Look and write", "chinese": "看一看，写一写"}', 107, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14970, 567, '{"english": "Look at the pictures and complete the sentences.", "chinese": "看图，完成句子。"}', 108, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14971, 567, '{"english": "The boy is running quickly.", "chinese": "这个男孩正在快速地跑着。"}', 109, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14972, 567, '{"english": "The girl is shouting excitedly.", "chinese": "这个女孩正在兴奋地叫喊着。"}', 110, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14973, 567, '{"english": "The children are talking happily.", "chinese": "孩子们正在高兴地聊着天。"}', 111, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14974, 567, '{"english": "The people are laughing loudly.", "chinese": "这些人正在大声地笑着。"}', 112, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14975, 567, '{"english": "The man is reading quietly.", "chinese": "这个男人正在安静地阅读。"}', 113, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14976, 567, '{"english": "The woman is crying sadly.", "chinese": "这位妇女正在伤心地哭泣。"}', 114, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14977, 567, '{"english": "Think and write", "chinese": "想一想，写一写"}', 115, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14978, 567, '{"english": "Su Hai is writing an email to her e-friend Anna.", "chinese": "苏海正在给她的网友安娜写电子邮件。"}', 116, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14979, 567, '{"english": "Help her complete it.", "chinese": "帮她完成一下吧。"}', 117, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14980, 567, '{"english": "To: Anna", "chinese": "致：安娜"}', 118, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14981, 567, '{"english": "Subject: My weekend", "chinese": "主题：我的周末"}', 119, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14982, 567, '{"english": "Dear Anna, Last Sunday, I went to a shopping centre with my mum and dad.", "chinese": "亲爱的安娜， 上周日，我和爸爸妈妈一起去了一个购物中心。"}', 120, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14983, 567, '{"english": "We saw a small boy on the floor.", "chinese": "我们看到地上有个小男孩。"}', 121, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14984, 567, '{"english": "He looked sad.", "chinese": "他看上去很伤心。"}', 122, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14985, 567, '{"english": "We went to him and helped him up.", "chinese": "我们走到他跟前，把他扶了起来。"}', 123, '2026-02-05 04:28:20', '2026-02-05 04:28:20');
INSERT INTO "course_content" VALUES (14986, 567, '{"english": "I asked him, \"Are you OK?\"", "chinese": "我问他，“你还好吗？”"}', 124, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14987, 567, '{"english": "He said, \" I can''t find my mum.\"", "chinese": "他说，“我找不到我妈妈。”"}', 125, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14988, 567, '{"english": "Dad took him to an office in the shopping centre.", "chinese": "爸爸把他带到了购物中心的一间办公室。"}', 126, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14989, 567, '{"english": "I gave him a sweet.", "chinese": "我给了他一颗糖果。"}', 127, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14990, 567, '{"english": "The small boy became happy.", "chinese": "小男孩变得很高兴。"}', 128, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14991, 567, '{"english": "I was happy too.", "chinese": "我也很高兴。"}', 129, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14992, 567, '{"english": "I like helping people.", "chinese": "我喜欢帮助人。"}', 130, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14993, 567, '{"english": "What about you?", "chinese": "你呢？"}', 131, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14994, 567, '{"english": "Talk soon.", "chinese": "回头聊。"}', 132, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14995, 567, '{"english": "Su Hai", "chinese": "苏海"}', 133, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14996, 567, '{"english": "Ticking time", "chinese": "打勾时间"}', 134, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14997, 567, '{"english": "I can understand \"The lion and the mouse\".", "chinese": "我能理解“狮子和老鼠”这个故事。"}', 135, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14998, 567, '{"english": "I can use \"loudly\", \"sadly\", etc.", "chinese": "我能使用“loudly”，“sadly”，等等。"}', 136, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (14999, 567, '{"english": "I know the intonation of \"Wh-questions\".", "chinese": "我知道“特殊疑问句”的语调。"}', 137, '2026-02-05 04:28:21', '2026-02-05 04:28:21');
INSERT INTO "course_content" VALUES (15000, 568, '{"english": "Unit 2 Good habits", "chinese": "第二单元 良好的习惯"}', 1, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15001, 568, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15002, 568, '{"english": "Tip Try to form good learning habits.", "chinese": "小贴士养成良好的学习习惯。"}', 3, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15003, 568, '{"english": "See page 90.", "chinese": "见第90页。"}', 4, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15004, 568, '{"english": "Wang Bing is a good boy.", "chinese": "王冰是个好男孩。"}', 5, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15005, 568, '{"english": "He has many good habits.", "chinese": "他有许多好习惯。"}', 6, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15006, 568, '{"english": "He gets up early in the morning and never goes to bed late.", "chinese": "他早上起得很早，他从来不晚睡。"}', 7, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15007, 568, '{"english": "He brushes his teeth in the morning and before bedtime.", "chinese": "他早上和睡前都会刷牙。"}', 8, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15008, 568, '{"english": "At home, Wang Bing always puts his things in order.", "chinese": "在家里，王冰总是把他的东西整理得井井有条。"}', 9, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15009, 568, '{"english": "He usually finishes his homework before dinner.", "chinese": "他通常都会在晚饭前先完成家庭作业。"}', 10, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15010, 568, '{"english": "messy", "chinese": "凌乱的，散乱的"}', 11, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15011, 568, '{"english": "tidy", "chinese": "干净的，整齐的"}', 12, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15012, 568, '{"english": "Liu Tao is a good boy too.", "chinese": "刘涛也是个好男孩。"}', 13, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15013, 568, '{"english": "He listens to his teachers at school.", "chinese": "他在学校听老师的话。"}', 14, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15014, 568, '{"english": "He also does well at home.", "chinese": "他在家也做得很好。"}', 15, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15015, 568, '{"english": "He keeps his room clean and tidy.", "chinese": "他把房间保持得干净而又整洁。"}', 16, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15016, 568, '{"english": "He also helps his parents.", "chinese": "他也会给父母帮忙。"}', 17, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15017, 568, '{"english": "But Liu Tao has some bad habits.", "chinese": "但是刘涛还有一些坏习惯。"}', 18, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15018, 568, '{"english": "He often does his homework late at night and does not go to bed early.", "chinese": "他经常深更半夜做家庭作业，不早点上床睡觉。"}', 19, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15019, 568, '{"english": "He sometimes feels sleepy in the morning.", "chinese": "他上午有时会感觉很困。"}', 20, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15020, 568, '{"english": "Wang Bing and Liu Tao are friends.", "chinese": "王冰和刘涛是朋友。"}', 21, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15021, 568, '{"english": "Wang Bing knows Liu Tao well.", "chinese": "王冰很了解刘涛。"}', 22, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15022, 568, '{"english": "Did you go to bed late last night, Liu Tao?", "chinese": "你昨晚很晚睡觉吗，刘涛？"}', 23, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15023, 568, '{"english": "Yes, but I''m not sleepy.", "chinese": "是的，但是我不困。"}', 24, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15024, 568, '{"english": "I can walk fast.", "chinese": "我能走得快。"}', 25, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15025, 568, '{"english": "Ouch!", "chinese": "哎哟！"}', 26, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15026, 568, '{"english": "You shouldn''t go to bed late, Liu Tao.", "chinese": "你不应该晚睡的，刘涛。"}', 27, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15027, 568, '{"english": "early", "chinese": "早；早的"}', 28, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15028, 568, '{"english": "late", "chinese": "迟，晚"}', 29, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15029, 568, '{"english": "Match and say", "chinese": "连一连，说一说"}', 30, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15030, 568, '{"english": "What habits do Wang Bing and Liu Tao have?", "chinese": "王冰和刘涛有些什么习惯呢？"}', 31, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15031, 568, '{"english": "does his homework late at night", "chinese": "深更半夜做家庭作业"}', 32, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15032, 568, '{"english": "gets up early", "chinese": "早起"}', 33, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15033, 568, '{"english": "goes to bed late", "chinese": "晚睡"}', 34, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15034, 568, '{"english": "helps his parents", "chinese": "给父母帮忙"}', 35, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15035, 568, '{"english": "finishes his homework early", "chinese": "提早完成家庭作业"}', 36, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15036, 568, '{"english": "puts his things in order", "chinese": "把东西整理得井井有条"}', 37, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15037, 568, '{"english": "Wang Bing has some good habits.", "chinese": "王冰有一些好习惯。"}', 38, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15038, 568, '{"english": "He gets up early.", "chinese": "他起得很早。"}', 39, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15039, 568, '{"english": "You", "chinese": "你"}', 40, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15040, 568, '{"english": "Think and write", "chinese": "想一想，写一写"}', 41, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15041, 568, '{"english": "Good habits", "chinese": "好习惯"}', 42, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15042, 568, '{"english": "Get up early in the morning.", "chinese": "早上早起。"}', 43, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15043, 568, '{"english": "Do not go to school late.", "chinese": "上学不迟到。"}', 44, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15044, 568, '{"english": "Listen to your teacher at school.", "chinese": "在学校听老师的话。"}', 45, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15045, 568, '{"english": "Finish your homework early.", "chinese": "提早完成家庭作业。"}', 46, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15046, 568, '{"english": "Help your parents at home.", "chinese": "在家帮父母的忙。"}', 47, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15047, 568, '{"english": "Keep your room clean and tidy.", "chinese": "使房间保持干净而又整洁。"}', 48, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15048, 568, '{"english": "Go to bed early at night.", "chinese": "晚上早点上床睡觉。"}', 49, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15049, 568, '{"english": "Grammar time", "chinese": "语法时间"}', 50, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15050, 568, '{"english": "I walk fast in the street. We / They do well at home. He gets up early in the morning. He goes to school early in the morning. She goes to bed late at night.", "chinese": "我在街上快步行走。 我们 / 他们在家表现很好。 他早上起得很早。 他一大早去上学。 她晚上睡得很晚。"}', 51, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15051, 568, '{"english": "He never goes to bed late.", "chinese": "他从不晚睡。"}', 52, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15052, 568, '{"english": "Let''s review these!", "chinese": "我们来复习一下这些吧！"}', 53, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15053, 568, '{"english": "I always have breakfast on time.", "chinese": "我总是准时吃早餐。"}', 54, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15054, 568, '{"english": "We usually finish our homework before dinner.", "chinese": "我们通常会在晚饭前先完成家庭作业。"}', 55, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15055, 568, '{"english": "They often do their homework in the evening.", "chinese": "他们经常在晚上做家庭作业。"}', 56, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15056, 568, '{"english": "He sometimes feels sleepy in the morning.", "chinese": "他上午有时会感觉很困。"}', 57, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15057, 568, '{"english": "Fun time", "chinese": "娱乐时间"}', 58, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15058, 568, '{"english": "Pick and say", "chinese": "选一选，说一说"}', 59, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15059, 568, '{"english": "Pick one!", "chinese": "快选一张吧！"}', 60, '2026-02-05 04:28:22', '2026-02-05 04:28:22');
INSERT INTO "course_content" VALUES (15060, 568, '{"english": "OK.", "chinese": "好的。"}', 61, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15061, 568, '{"english": "Do you go to bed early?", "chinese": "你很早就上床睡觉吗？"}', 62, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15062, 568, '{"english": "Yes, I do.", "chinese": "是的，我很早就上床睡觉。"}', 63, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15063, 568, '{"english": "That''s a good habit.", "chinese": "那是个好习惯。"}', 64, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15064, 568, '{"english": "Thank you!", "chinese": "谢谢你！"}', 65, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15065, 568, '{"english": "Sound time", "chinese": "语音时间"}', 66, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15066, 568, '{"english": "or", "chinese": ""}', 67, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15067, 568, '{"english": "Four short horses, Running through the grass.", "chinese": "四匹矮马，奔驰着穿过草地。"}', 68, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15068, 568, '{"english": "Four short horses, Running very fast!", "chinese": "四匹矮马，飞快地奔驰着！"}', 69, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15069, 568, '{"english": "for", "chinese": "为了"}', 70, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15070, 568, '{"english": "horse", "chinese": "马"}', 71, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15071, 568, '{"english": "short", "chinese": "矮的；短的"}', 72, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15072, 568, '{"english": "sport", "chinese": "运动"}', 73, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15073, 568, '{"english": "Song time", "chinese": "唱歌时间"}', 74, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15074, 568, '{"english": "This is the way", "chinese": "《就是这样》"}', 75, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15075, 568, '{"english": "This is the way we wash our face, wash our face, wash our face.", "chinese": "歌词大意：我们就是这样洗脸，洗脸，洗脸的。"}', 76, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15076, 568, '{"english": "This is the way we wash our face at seven o''clock in the morning.", "chinese": "我们早上七点钟就是这样洗脸的。"}', 77, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15077, 568, '{"english": "Cartoon time", "chinese": "卡通时间"}', 78, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15078, 568, '{"english": "Tina''s friends come to see her.", "chinese": "蒂娜的朋友来看她了。"}', 79, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15079, 568, '{"english": "Let me show you around our house.", "chinese": "让我带领你们参观一下我们家吧。"}', 80, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15080, 568, '{"english": "They go into the living room.", "chinese": "他们进入了客厅。"}', 81, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15081, 568, '{"english": "This is our living room.", "chinese": "这是我们的客厅。"}', 82, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15082, 568, '{"english": "It''s big and clean.", "chinese": "它又大又干净。"}', 83, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15083, 568, '{"english": "They go into Tina''s bedroom.", "chinese": "他们进入了蒂娜的卧室。"}', 84, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15084, 568, '{"english": "This is my bedroom.", "chinese": "这是我的卧室。"}', 85, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15085, 568, '{"english": "It''s small, but it''s nice.", "chinese": "它很小，但是很漂亮。"}', 86, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15086, 568, '{"english": "They are in Bobby''s bedroom.", "chinese": "他们在波比的卧室里。"}', 87, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15087, 568, '{"english": "They see a lot of books and toys on the floor.", "chinese": "他们看到地板上有许多书和玩具。"}', 88, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15088, 568, '{"english": "Whose bedroom is this?", "chinese": "这是谁的卧室？"}', 89, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15089, 568, '{"english": "It''s my brother''s.", "chinese": "是我弟弟的。"}', 90, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15090, 568, '{"english": "They cannot see Bobby.", "chinese": "他们看不到波比。"}', 91, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15091, 568, '{"english": "Bobby, where are you?", "chinese": "波比，你在哪儿？"}', 92, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15092, 568, '{"english": "I''m here, under the bed.", "chinese": "我在这儿，在床底下。"}', 93, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15093, 568, '{"english": "You should put your books and toys in order.", "chinese": "你应该把你的书和玩具整理得井井有条。"}', 94, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15094, 568, '{"english": "Checkout time", "chinese": "检测时间"}', 95, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15095, 568, '{"english": "Look and circle", "chinese": "看一看，圈一圈"}', 96, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15096, 568, '{"english": "Look at the pictures and circle the correct words.", "chinese": "看图，圈出正确的单词。"}', 97, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15097, 568, '{"english": "The children are running fast.", "chinese": "孩子们正在快速奔跑着。"}', 98, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15098, 568, '{"english": "The old man is walking slowly.", "chinese": "这位老人正在缓慢行走着。"}', 99, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15099, 568, '{"english": "The man is singing badly.", "chinese": "这个男人正唱得很难听。"}', 100, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15100, 568, '{"english": "The boy is doing well at school.", "chinese": "这个男孩在学校里成绩很好。"}', 101, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15101, 568, '{"english": "The woman gets up late.", "chinese": "这位妇女起得很晚。"}', 102, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15102, 568, '{"english": "I go to school early in the morning.", "chinese": "我早上很早上学。"}', 103, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15103, 568, '{"english": "Listen and choose", "chinese": "听一听，选一选"}', 104, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15104, 568, '{"english": "Su Hai and Su Yang get up at _____ in the morning.", "chinese": "苏海和苏阳在早上______起来。"}', 105, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15105, 568, '{"english": "six o''clock", "chinese": "六点钟"}', 106, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15106, 568, '{"english": "six thirty", "chinese": "六点半"}', 107, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15107, 568, '{"english": "seven o''clock", "chinese": "七点钟"}', 108, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15108, 568, '{"english": "They help their _____.", "chinese": "他们帮助他们的______。"}', 109, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15109, 568, '{"english": "grandparents", "chinese": "祖父母"}', 110, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15110, 568, '{"english": "parents", "chinese": "父母"}', 111, '2026-02-05 04:28:23', '2026-02-05 04:28:23');
INSERT INTO "course_content" VALUES (15111, 568, '{"english": "friends", "chinese": "朋友"}', 112, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15112, 568, '{"english": "They keep their______clean.", "chinese": "他们保持______干净。"}', 113, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15113, 568, '{"english": "rooms", "chinese": "房间"}', 114, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15114, 568, '{"english": "schoolbags", "chinese": "书包"}', 115, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15115, 568, '{"english": "desks", "chinese": "课桌"}', 116, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15116, 568, '{"english": "What is their bad habit?______.", "chinese": "他们的坏习惯是什么？"}', 117, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15117, 568, '{"english": "Ticking time", "chinese": "打勾时间"}', 118, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15118, 568, '{"english": "I know some good habits and bad habits.", "chinese": "我知道一些好习惯和坏习惯。"}', 119, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15119, 568, '{"english": "I can use \"early\", \"late\", etc.", "chinese": "我能使用“early”，“late”，等等。"}', 120, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15120, 568, '{"english": "I know the sound of \"or\".", "chinese": "我知道“or”的发音。"}', 121, '2026-02-05 04:28:24', '2026-02-05 04:28:24');
INSERT INTO "course_content" VALUES (15121, 569, '{"english": "Unit 3 A healthy diet", "chinese": "第三单元 健康饮食"}', 1, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15122, 569, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15123, 569, '{"english": "Mike likes eating sweets, cakes and ice cream.", "chinese": "迈克喜欢吃糖果、蛋糕和冰淇淋。"}', 3, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15124, 569, '{"english": "He does not like drinking water.", "chinese": "他不喜欢喝水。"}', 4, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15125, 569, '{"english": "He only drinks a little water every day.", "chinese": "他每天只喝一点点水。"}', 5, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15126, 569, '{"english": "Mike has some bread and milk for breakfast.", "chinese": "迈克早餐会吃一些面包，再喝一些牛奶。"}', 6, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15127, 569, '{"english": "For lunch and dinner, he has a lot of rice, some fish and some meat.", "chinese": "至于午餐和晚餐，他会吃许多米饭、一些鱼和一些肉。"}', 7, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15128, 569, '{"english": "He has a few eggs every week.", "chinese": "他每周都会吃几个鸡蛋。"}', 8, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15129, 569, '{"english": "Does Mike have a healthy diet?", "chinese": "迈克有一个健康的饮食习惯吗？"}', 9, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15130, 569, '{"english": "a lot of", "chinese": "许多"}', 10, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15131, 569, '{"english": "some", "chinese": "一些"}', 11, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15132, 569, '{"english": "Yang Ling often has a lot of noodles for breakfast.", "chinese": "杨琳早餐经常吃许多面条。"}', 12, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15133, 569, '{"english": "She sometimes eats an egg too.", "chinese": "她有时也会吃个鸡蛋。"}', 13, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15134, 569, '{"english": "For lunch and dinner, she eats some meat and some vegetables.", "chinese": "至于午餐和晚餐，她会吃一些肉和一些蔬菜。"}', 14, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15135, 569, '{"english": "She only eats a little rice.", "chinese": "她只吃一点点米饭。"}', 15, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15136, 569, '{"english": "Yang Ling likes sweet food too, but she eats a little at a time.", "chinese": "杨琳也喜欢甜食，但是她一次只吃一点点。"}', 16, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15137, 569, '{"english": "She eats some fruit every day.", "chinese": "她每天都吃一些水果。"}', 17, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15138, 569, '{"english": "Does Yang Ling have a healthy diet?", "chinese": "杨琳有一个健康的饮食习惯吗？"}', 18, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15139, 569, '{"english": "Do you have a healthy diet?", "chinese": "你有一个健康的饮食习惯吗？"}', 19, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15140, 569, '{"english": "Tip Use a few and a little correctly.", "chinese": "正确使用“a few”和“a little”。"}', 20, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15141, 569, '{"english": "See page 90.", "chinese": "见第90页。"}', 21, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15142, 569, '{"english": "a little", "chinese": "一点"}', 22, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15143, 569, '{"english": "a few", "chinese": "几个"}', 23, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15144, 569, '{"english": "True or false", "chinese": "对还是错"}', 24, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15145, 569, '{"english": "Mike does not eat any cakes.", "chinese": "迈克什么蛋糕都不吃。"}', 25, '2026-02-05 04:28:25', '2026-02-05 04:28:25');
INSERT INTO "course_content" VALUES (15146, 569, '{"english": "Mike does not drink a lot of water every day.", "chinese": "迈克每天没有喝许多的水。"}', 26, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15147, 569, '{"english": "Mike eats a lot of eggs every day.", "chinese": "迈克每天吃许多鸡蛋。"}', 27, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15148, 569, '{"english": "Yang Ling eats some meat every day.", "chinese": "杨琳每天吃一些肉。"}', 28, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15149, 569, '{"english": "Yang Ling eats a lot of rice.", "chinese": "杨琳吃许多的米饭。"}', 29, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15150, 569, '{"english": "Yang Ling does not eat a lot of sweets.", "chinese": "杨琳没有吃许多的糖果。"}', 30, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15151, 569, '{"english": "Read and write", "chinese": "读一读，写一写"}', 31, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15152, 569, '{"english": "I like eating.", "chinese": "我喜欢吃。"}', 32, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15153, 569, '{"english": "I have a lot of food every day.", "chinese": "我每天都吃许多食物。"}', 33, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15154, 569, '{"english": "In the morning, I have some bread and milk.", "chinese": "在早上，我吃一些面包，再喝一些牛奶。"}', 34, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15155, 569, '{"english": "In the afternoon and evening, I have a lot of rice, some fish and some meat.", "chinese": "在下午和晚上，我吃许多米饭，还吃一些鱼和一些肉。"}', 35, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15156, 569, '{"english": "I like eating sweets, cakes and ice cream.", "chinese": "我喜欢吃糖果、蛋糕和冰淇淋。"}', 36, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15157, 569, '{"english": "I like sweet food very much.", "chinese": "我非常喜欢甜食。"}', 37, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15158, 569, '{"english": "I like eating too.", "chinese": "我也喜欢吃。"}', 38, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15159, 569, '{"english": "In the morning, I have a lot of noodles.", "chinese": "在早上，我吃许多面条。"}', 39, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15160, 569, '{"english": "I sometimes have an egg too.", "chinese": "我有时还吃一个鸡蛋。"}', 40, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15161, 569, '{"english": "In the afternoon and evening, I have some meat and some vegetables.", "chinese": "在下午和晚上，我吃一些肉和一些蔬菜。"}', 41, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15162, 569, '{"english": "I only eat a little rice.", "chinese": "我只吃一点点米饭。"}', 42, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15163, 569, '{"english": "I also eat a little sweet food and some fruit every day.", "chinese": "我每天还吃一点甜食和一些水果。"}', 43, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15164, 569, '{"english": "Grammar time", "chinese": "语法时间"}', 44, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15165, 569, '{"english": "I eat a lot of noodles. We eat a lot of meat. They have some vegetables. You have some bread.", "chinese": "我吃很多面条。 我们吃很多肉。 他们吃蔬菜。 你（们）吃面包。"}', 45, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15166, 569, '{"english": "He eats a few eggs. She drinks a little water.", "chinese": "他吃几个鸡蛋。 她喝一点水。"}', 46, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15167, 569, '{"english": "We don''t add \"s\" or \"es\" to the following words.", "chinese": "我们不给如下的单词加上“s”或“es”。"}', 47, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15168, 569, '{"english": "bread", "chinese": "面包"}', 48, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15169, 569, '{"english": "juice", "chinese": "果汁"}', 49, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15170, 569, '{"english": "meat", "chinese": "肉"}', 50, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15171, 569, '{"english": "milk", "chinese": "牛奶"}', 51, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15172, 569, '{"english": "rice", "chinese": "米饭"}', 52, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15173, 569, '{"english": "water", "chinese": "水"}', 53, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15174, 569, '{"english": "Do you remember these words?", "chinese": "你记得这些单词吗？"}', 54, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15175, 569, '{"english": "We usually add \"es\" to them.", "chinese": "我们通常会给它们加上“es”哦。"}', 55, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15176, 569, '{"english": "mango", "chinese": "芒果"}', 56, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15177, 569, '{"english": "potato", "chinese": "土豆"}', 57, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15178, 569, '{"english": "tomato", "chinese": "西红柿"}', 58, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15179, 569, '{"english": "Fun time", "chinese": "娱乐时间"}', 59, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15180, 569, '{"english": "Do a survey", "chinese": "做调查"}', 60, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15181, 569, '{"english": "What do you have for breakfast?", "chinese": "你早餐吃什么？"}', 61, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15182, 569, '{"english": "I have some noodles.", "chinese": "我吃一些面条。"}', 62, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15183, 569, '{"english": "What about lunch and dinner?", "chinese": "午餐和晚餐呢？"}', 63, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15184, 569, '{"english": "For lunch and dinner, I have a lot of rice, some meat and some vegetables.", "chinese": "我午餐和晚餐会吃许多的米饭，还会吃一些肉和一些蔬菜。"}', 64, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15185, 569, '{"english": "Name", "chinese": "姓名"}', 65, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15186, 569, '{"english": "Breakfast", "chinese": "早餐"}', 66, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15187, 569, '{"english": "Lunch", "chinese": "午餐"}', 67, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15188, 569, '{"english": "Dinner", "chinese": "晚餐"}', 68, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15189, 569, '{"english": "Mary", "chinese": "玛丽"}', 69, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15190, 569, '{"english": "some noodles", "chinese": "一些面条"}', 70, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15191, 569, '{"english": "a lot of rice", "chinese": "许多米饭"}', 71, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15192, 569, '{"english": "some meat", "chinese": "一些肉"}', 72, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15193, 569, '{"english": "some vegetables", "chinese": "一些蔬菜"}', 73, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15194, 569, '{"english": "a lot of rice", "chinese": "许多米饭"}', 74, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15195, 569, '{"english": "some meat", "chinese": "一些肉"}', 75, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15196, 569, '{"english": "some vegetables", "chinese": "一些蔬菜"}', 76, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15197, 569, '{"english": "Mary has some noodles for breakfast.", "chinese": "玛丽早餐会吃一些面条。"}', 77, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15198, 569, '{"english": "She has a lot of rice, some meat and some vegetables for lunch and dinner.", "chinese": "她午餐和晚餐会吃许多的米饭，还会吃一些肉和一些蔬菜。"}', 78, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15199, 569, '{"english": "Sound time", "chinese": "语音时间"}', 79, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15200, 569, '{"english": "ou", "chinese": ""}', 80, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15201, 569, '{"english": "Mrs Li shouts, \"Get out!", "chinese": "李太太大喊道，“出去！"}', 81, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15202, 569, '{"english": "Get out!\"", "chinese": "出去！”"}', 82, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15203, 569, '{"english": "There''s a little mouse In her house.", "chinese": "在她家里有一只小老鼠。"}', 83, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15204, 569, '{"english": "about", "chinese": "关于"}', 84, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15205, 569, '{"english": "house", "chinese": "房子"}', 85, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15206, 569, '{"english": "mouth", "chinese": "嘴巴"}', 86, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15207, 569, '{"english": "out", "chinese": "外面的"}', 87, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15208, 569, '{"english": "shout", "chinese": "呼喊；喊叫"}', 88, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15209, 569, '{"english": "Culture time", "chinese": "文化时间"}', 89, '2026-02-05 04:28:26', '2026-02-05 04:28:26');
INSERT INTO "course_content" VALUES (15210, 569, '{"english": "Chinese people often have some porridge and steamed buns for breakfast.", "chinese": "中国人早餐经常会吃一些粥和馒头。"}', 90, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15211, 569, '{"english": "Western people often have cereal, bread, eggs and sausages for breakfast.", "chinese": "西方人早餐经常会吃麦片、面包、鸡蛋和香肠。"}', 91, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15212, 569, '{"english": "Cartoon time", "chinese": "卡通时间"}', 92, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15213, 569, '{"english": "There is not much food in the fridge.", "chinese": "冰箱里没有多少食物。"}', 93, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15214, 569, '{"english": "I have to go to the supermarket.", "chinese": "我得去趟超市。"}', 94, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15215, 569, '{"english": "Do you want to come with me, Sam?", "chinese": "你想跟我一起来吗，萨姆？"}', 95, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15216, 569, '{"english": "Yes, Mum.", "chinese": "想，妈妈。"}', 96, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15217, 569, '{"english": "Let''s go.", "chinese": "我们走吧。"}', 97, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15218, 569, '{"english": "Sam sees some drinks.", "chinese": "萨姆看到一些饮料。"}', 98, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15219, 569, '{"english": "Mum, can I have some cola?", "chinese": "妈妈，我可以喝一些可乐吗？"}', 99, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15220, 569, '{"english": "Yes, but take a small bottle.", "chinese": "可以，但是只拿一小瓶。"}', 100, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15221, 569, '{"english": "You shouldn''t drink too much cola.", "chinese": "你不应该喝太多可乐。"}', 101, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15222, 569, '{"english": "Sam wants some fish too.", "chinese": "萨姆还想要一些鱼。"}', 102, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15223, 569, '{"english": "I want this big fish, Mum.", "chinese": "我想要这条大鱼，妈妈。"}', 103, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15224, 569, '{"english": "OK.", "chinese": "好的。"}', 104, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15225, 569, '{"english": "Then, Sam sees some rice.", "chinese": "然后，萨姆看到一些大米。"}', 105, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15226, 569, '{"english": "Mum, do we need rice?", "chinese": "妈妈，我们需要大米吗？"}', 106, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15227, 569, '{"english": "Yes, we need a lot of  rice.", "chinese": "是的，我们需要许多大米。"}', 107, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15228, 569, '{"english": "Take the big bag.", "chinese": "拿那个大包的吧。"}', 108, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15229, 569, '{"english": "Now they are going home.", "chinese": "现在他们要回家了。"}', 109, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15230, 569, '{"english": "The fish is too heavy.", "chinese": "这条鱼太重了。"}', 110, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15231, 569, '{"english": "Can we have a rest, Mum?", "chinese": "我们可以休息一会儿吗，妈妈？"}', 111, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15232, 569, '{"english": "OK.", "chinese": "好的。"}', 112, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15233, 569, '{"english": "Oh no!", "chinese": "哦，不好！"}', 113, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15234, 569, '{"english": "Checkout time", "chinese": "检测时间"}', 114, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15235, 569, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 115, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15236, 569, '{"english": "Are there a lot of vegetables?", "chinese": "有许多蔬菜吗？"}', 116, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15237, 569, '{"english": "Yes, there are.", "chinese": "是的，有。"}', 117, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15238, 569, '{"english": "Is there any water?", "chinese": "有一些水吗？"}', 118, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15239, 569, '{"english": "No, there isn''t.", "chinese": "不，没有。"}', 119, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15240, 569, '{"english": "Look and write", "chinese": "看一看，写一写"}', 120, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15241, 569, '{"english": "a few", "chinese": "几个"}', 121, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15242, 569, '{"english": "a little", "chinese": "一点"}', 122, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15243, 569, '{"english": "a lot of", "chinese": "许多"}', 123, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15244, 569, '{"english": "some", "chinese": "一些"}', 124, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15245, 569, '{"english": "In a healthy diet, there is a lot of fruit and vegetables.", "chinese": "在健康的饮食中，有着许多的水果和蔬菜。"}', 125, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15246, 569, '{"english": "There is also a lot of  rice and bread.", "chinese": "还有许多的米饭和面包。"}', 126, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15247, 569, '{"english": "You can have some meat and fish in your meals.", "chinese": "你吃饭时可以吃一些肉和鱼。"}', 127, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15248, 569, '{"english": "You can also have a few eggs every week.", "chinese": "你每周还可以吃几个鸡蛋。"}', 128, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15249, 569, '{"english": "Milk is good for your body.", "chinese": "牛奶对你的身体有好处。"}', 129, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15250, 569, '{"english": "You can have some milk every day.", "chinese": "你每天可以喝一些牛奶。"}', 130, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15251, 569, '{"english": "Sweet food is nice, but it is not good for your teeth.", "chinese": "甜食很好吃，但是它对你的牙齿不好。"}', 131, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15252, 569, '{"english": "Eat only a little sweet food every day.", "chinese": "每天只能吃一点点甜食。"}', 132, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15253, 569, '{"english": "Ticking time", "chinese": "打勾时间"}', 133, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15254, 569, '{"english": "I know the food and drinks in a healthy diet.", "chinese": "我知道健康饮食中的食物和饮料。"}', 134, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15255, 569, '{"english": "I can use \"a lot of\", \"some\", etc.", "chinese": "我能使用“a lot of”，“some”等等。"}', 135, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15256, 569, '{"english": "I know the sound of \"ou\".", "chinese": "我知道“ou”的发音。"}', 136, '2026-02-05 04:28:27', '2026-02-05 04:28:27');
INSERT INTO "course_content" VALUES (15257, 570, '{"english": "Unit 4 Road safety", "chinese": "第四单元 道路安全"}', 1, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15258, 570, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15259, 570, '{"english": "Tip The pictures can help you understand the text.", "chinese": "小贴士图片能帮助你理解课文。"}', 3, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15260, 570, '{"english": "See page 90.", "chinese": "见第90页。"}', 4, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15261, 570, '{"english": "Road safety", "chinese": "道路安全"}', 5, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15262, 570, '{"english": "There are many busy roads in the city.", "chinese": "城市里有许多繁忙的道路。"}', 6, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15263, 570, '{"english": "How can you cross them safely?", "chinese": "你怎样才能安全地过马路呢？"}', 7, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15264, 570, '{"english": "First, you must look for a zebra crossing.", "chinese": "首先，你必须寻找斑马线。"}', 8, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15265, 570, '{"english": "Then, you must look at the traffic lights and wait for the green man.", "chinese": "然后，你必须看看红绿灯，并等待绿灯。"}', 9, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15266, 570, '{"english": "Can you see the red man?", "chinese": "你能看见红灯吗？"}', 10, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15267, 570, '{"english": "You mustn''t cross the road now.", "chinese": "你现在不准过马路。"}', 11, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15268, 570, '{"english": "Look!", "chinese": "瞧！"}', 12, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15269, 570, '{"english": "Here''s the green man.", "chinese": "这就是绿灯。"}', 13, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15270, 570, '{"english": "You can cross the road now.", "chinese": "你现在可以过马路了。"}', 14, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15271, 570, '{"english": "a pavement", "chinese": "人行道"}', 15, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15272, 570, '{"english": "a road", "chinese": "马路"}', 16, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15273, 570, '{"english": "a zebra crossing", "chinese": "斑马线"}', 17, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15274, 570, '{"english": "Sometimes, you cannot find a zebra crossing near you.", "chinese": "有时，你在附近找不到斑马线。"}', 18, '2026-02-05 04:28:28', '2026-02-05 04:28:28');
INSERT INTO "course_content" VALUES (15275, 570, '{"english": "To keep safe, you can wait on the pavement and look out for cars and bikes.", "chinese": "为了保证安全，你可以在人行道上等，要当心汽车和自行车。"}', 19, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15276, 570, '{"english": "You must first look left, then right and then left again.", "chinese": "你必须先向左边看看，然后向右边看看，然后再向左边看看。"}', 20, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15277, 570, '{"english": "You can also cross the road with other people.", "chinese": "你也可以和其他人一起过马路。"}', 21, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15278, 570, '{"english": "Then the drivers can see you easily.", "chinese": "那时司机就可以很容易看见你。"}', 22, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15279, 570, '{"english": "Some children run or play football on the road.", "chinese": "有些孩子会在马路上奔跑或踢足球。"}', 23, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15280, 570, '{"english": "This is not safe.", "chinese": "这是很不安全的。"}', 24, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15281, 570, '{"english": "You must not play on the road because there are many cars and bikes.", "chinese": "你不许在马路上玩耍，因为那里有许多的汽车和自行车。"}', 25, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15282, 570, '{"english": "Follow the rules and stay safe on the road!", "chinese": "马路上要遵守规则，保持安全！"}', 26, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15283, 570, '{"english": "green man", "chinese": "绿灯"}', 27, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15284, 570, '{"english": "red man", "chinese": "红灯"}', 28, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15285, 570, '{"english": "traffic lights", "chinese": "红绿灯"}', 29, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15286, 570, '{"english": "Think and write", "chinese": "想一想，写一写"}', 30, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15287, 570, '{"english": "Complete the notes below.", "chinese": "完成下列笔记。"}', 31, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15288, 570, '{"english": "To cross a busy road safely, we must first look for a zebra crossing and then look at the traffic lights.", "chinese": "为了安全地穿过一条繁忙的马路，我们必须先寻找斑马线，然后再看看红绿灯。"}', 32, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15289, 570, '{"english": "Sometimes, we can wait on the pavement.", "chinese": "有时，我们可以在人行道上等。"}', 33, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15290, 570, '{"english": "We must first look left, then right and then look left again before we cross the road.", "chinese": "在过马路之前，我们必须先向左边看看，然后向右边看看，然后再向左边看看。"}', 34, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15291, 570, '{"english": "We can also cross the road with other people.", "chinese": "我们也可以和其他人一起过马路。"}', 35, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15292, 570, '{"english": "We must not run or play football on the road.", "chinese": "我们不可以在马路上奔跑或踢足球。"}', 36, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15293, 570, '{"english": "Look and say", "chinese": "看一看，说一说"}', 37, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15294, 570, '{"english": "What must you do to cross the road safely?", "chinese": "为了安全地过马路，你们必须做些什么？"}', 38, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15295, 570, '{"english": "What must you not do on the road?", "chinese": "在马路上你们不准做什么？"}', 39, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15296, 570, '{"english": "We must ...", "chinese": "我们必须……"}', 40, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15297, 570, '{"english": "We mustn''t ...", "chinese": "我们不准……"}', 41, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15298, 570, '{"english": "Grammar time", "chinese": "语法时间"}', 42, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15299, 570, '{"english": "How can you cross the road safely? What must you not do on the road?", "chinese": "如何安全过马路？ 马路上不能做什么？"}', 43, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15300, 570, '{"english": "You must look for a zebra crossing. You must look at the traffic lights. You mustn''t play football on the road. You mustn''t run on the road.", "chinese": "一定要找斑马线。 一定要看红绿灯。 不能在马路上踢足球。 不能在马路上奔跑。"}', 44, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15301, 570, '{"english": "mustn''t = must not", "chinese": "禁止"}', 45, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15302, 570, '{"english": "Let''s review these！", "chinese": "我们来复习一下这些吧！"}', 46, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15303, 570, '{"english": "You can wait on the pavement. You can cross the road with other people. You can''t cross the road here. You cannot find a zebra crossing.", "chinese": "你可以在人行道上等。 你可以和其他人一起过马路。 你不能在这里过马路。 你找不到斑马线。"}', 47, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15304, 570, '{"english": "can''t = cannot", "chinese": "不能"}', 48, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15305, 570, '{"english": "Fun time", "chinese": "娱乐时间"}', 49, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15306, 570, '{"english": "Play a game", "chinese": "玩游戏"}', 50, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15307, 570, '{"english": "Red man, stop!", "chinese": "红灯，停！"}', 51, '2026-02-05 04:28:29', '2026-02-05 04:28:29');
INSERT INTO "course_content" VALUES (15308, 570, '{"english": "Green man, go!", "chinese": "绿灯，行！"}', 52, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15309, 570, '{"english": "What must you do on the road?", "chinese": "在马路上你必须做什么？"}', 53, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15310, 570, '{"english": "I must look out for cars.", "chinese": "我必须当心车辆。"}', 54, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15311, 570, '{"english": "Right!", "chinese": "答对了！"}', 55, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15312, 570, '{"english": "What must you do on the road?", "chinese": "在马路上你必须做什么？"}', 56, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15313, 570, '{"english": "I must run quickly on the road.", "chinese": "在马路上我必须快跑。"}', 57, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15314, 570, '{"english": "No, you mustn''t run quickly on the road!", "chinese": "不对，你在马路上不准快跑！"}', 58, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15315, 570, '{"english": "Sound time", "chinese": "语音时间"}', 59, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15316, 570, '{"english": "Stress", "chinese": "重读"}', 60, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15317, 570, '{"english": "Stop!", "chinese": "停！"}', 61, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15318, 570, '{"english": "There''s a red man.", "chinese": "有红灯。"}', 62, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15319, 570, '{"english": "We mustn''t walk now.", "chinese": "我们现在不准走。"}', 63, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15320, 570, '{"english": "We must wait for the green man.", "chinese": "我们必须等绿灯。"}', 64, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15321, 570, '{"english": "There he is!", "chinese": "绿灯来了！"}', 65, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15322, 570, '{"english": "Now we can walk, But don''t run!", "chinese": "现在我们可以走了，但是不要跑！"}', 66, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15323, 570, '{"english": "Culture time", "chinese": "文化时间"}', 67, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15324, 570, '{"english": "In the United Kingdom, people drive on the left side of the road.", "chinese": "在英国，人们靠马路左边行驶。"}', 68, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15325, 570, '{"english": "In the People''s Republic of China, except Hong Kong and Macau, people drive on the right side of the road.", "chinese": "在中国，除了香港和澳门之外，人们都是靠马路右边行驶。"}', 69, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15326, 570, '{"english": "Cartoon time", "chinese": "卡通时间"}', 70, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15327, 570, '{"english": "Bobby and Tina go to see their aunt.", "chinese": "波比和蒂娜去看望他们的阿姨。"}', 71, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15328, 570, '{"english": "Hello, Aunt Alice.", "chinese": "你好，爱丽丝阿姨。"}', 72, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15329, 570, '{"english": "This is Tina.", "chinese": "我是蒂娜。"}', 73, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15330, 570, '{"english": "How do we get to your house?", "chinese": "我们该怎样到你家？"}', 74, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15331, 570, '{"english": "You can take the bus, Tina.", "chinese": "你们可以乘公交车，蒂娜。"}', 75, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15332, 570, '{"english": "OK.", "chinese": "好的。"}', 76, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15333, 570, '{"english": "They get on the bus.", "chinese": "他们上了公交车。"}', 77, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15334, 570, '{"english": "Look!", "chinese": "瞧！"}', 78, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15335, 570, '{"english": "There are so many cars on the road.", "chinese": "马路上有这么多的车。"}', 79, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15336, 570, '{"english": "Yes.", "chinese": "是啊。"}', 80, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15337, 570, '{"english": "They''re going fast.", "chinese": "它们开得真快。"}', 81, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15338, 570, '{"english": "There is a red light.", "chinese": "有红灯。"}', 82, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15339, 570, '{"english": "The bus stops.", "chinese": "公交车停了下来。"}', 83, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15340, 570, '{"english": "Why does the bus stop here?", "chinese": "公交车为什么在这儿停下来？"}', 84, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15341, 570, '{"english": "Look at the red light.", "chinese": "看看那个红灯。"}', 85, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15342, 570, '{"english": "It means we must stop.", "chinese": "它表示我们必须停。"}', 86, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15343, 570, '{"english": "Oh, I see.", "chinese": "哦，我明白了。"}', 87, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15344, 570, '{"english": "The bus goes on, but soon it stops again.", "chinese": "公交车继续前行，但是很快它又停了下来。"}', 88, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15345, 570, '{"english": "There aren''t any traffic lights here.", "chinese": "这里没有任何的红绿灯。"}', 89, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15346, 570, '{"english": "Why is the bus stopping again?", "chinese": "公交车为什么又要停？"}', 90, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15347, 570, '{"english": "Look!", "chinese": "瞧！"}', 91, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15348, 570, '{"english": "Some elephants are crossing the road.", "chinese": "有些大象在过马路。"}', 92, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15349, 570, '{"english": "We must stop and wait.", "chinese": "我们必须停下来等一等。"}', 93, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15350, 570, '{"english": "Checkout time", "chinese": "检测时间"}', 94, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15351, 570, '{"english": "Read and circle", "chinese": "读一读，圈一圈"}', 95, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15352, 570, '{"english": "Can I watch TV?", "chinese": "我可以看电视吗？"}', 96, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15353, 570, '{"english": "No, you can''t.", "chinese": "不，你不可以。"}', 97, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15354, 570, '{"english": "It''s late.", "chinese": "很晚了。"}', 98, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15355, 570, '{"english": "You must go to bed now.", "chinese": "你现在必须上床睡觉。"}', 99, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15356, 570, '{"english": "What can you do?", "chinese": "你能做什么？"}', 100, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15357, 570, '{"english": "I can run fast.", "chinese": "我能跑得很快。"}', 101, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15358, 570, '{"english": "But you mustn''t run fast on the road.", "chinese": "但是在马路上你不准快跑。"}', 102, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15359, 570, '{"english": "I know.", "chinese": "我知道。"}', 103, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15360, 570, '{"english": "Must I go to see the doctor?", "chinese": "我必须去看医生吗？"}', 104, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15361, 570, '{"english": "Yes, you must.", "chinese": "是的，你必须。"}', 105, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15362, 570, '{"english": "You can''t go to school because you''re sick.", "chinese": "你不能去上学，因为你生病了。"}', 106, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15363, 570, '{"english": "Think and write", "chinese": "想一想，写一写"}', 107, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15364, 570, '{"english": "Complete the poster with \"must\" and \"must not\".", "chinese": "用“must”和“must not”完成这张海报。"}', 108, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15365, 570, '{"english": "Classroom rules", "chinese": "课堂规则"}', 109, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15366, 570, '{"english": "You must not run in the classroom.", "chinese": "你不准在教室里乱跑。"}', 110, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15367, 570, '{"english": "You must keep your desk clean and tidy.", "chinese": "你必须使书桌保持干净而又整齐。"}', 111, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15368, 570, '{"english": "You must not eat or drink.", "chinese": "你不准吃喝。"}', 112, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15369, 570, '{"english": "You must not play ball games.", "chinese": "你不准打球。"}', 113, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15370, 570, '{"english": "You must not talk loudly.", "chinese": "你不准大声说话。"}', 114, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15371, 570, '{"english": "You must keep the classroom clean.", "chinese": "你必须使教室保持干净。"}', 115, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15372, 570, '{"english": "You must listen to your teachers in class.", "chinese": "在课堂上你必须听老师讲课。"}', 116, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15373, 570, '{"english": "Ticking time", "chinese": "打勾时间"}', 117, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15374, 570, '{"english": "I know what I must and must not do on the road.", "chinese": "我知道我在马路上必须以及不准做什么。"}', 118, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15375, 570, '{"english": "I can use \"must\" and \"must not\".", "chinese": "我能使用“must”和“must not”。"}', 119, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15376, 570, '{"english": "I know that I need to read some words in a sentence more loudly.", "chinese": "我知道我需要大声点朗读句中的某些单词。"}', 120, '2026-02-05 04:28:30', '2026-02-05 04:28:30');
INSERT INTO "course_content" VALUES (15377, 571, '{"english": "Project 1 Being a good student", "chinese": "课题 1 做个好学生"}', 1, '2026-02-05 04:28:31', '2026-02-05 04:28:31');
INSERT INTO "course_content" VALUES (15378, 571, '{"english": "Read about Amy and John.", "chinese": "阅读有关艾米和约翰的信息。"}', 2, '2026-02-05 04:28:32', '2026-02-05 04:28:32');
INSERT INTO "course_content" VALUES (15379, 571, '{"english": "What habits do they have?", "chinese": "他们有什么习惯？"}', 3, '2026-02-05 04:28:32', '2026-02-05 04:28:32');
INSERT INTO "course_content" VALUES (15380, 571, '{"english": "Are they good habits or bad habits?", "chinese": "它们是好习惯还是坏习惯？"}', 4, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15381, 571, '{"english": "Amy gets up early and has breakfast every day.", "chinese": "艾米每天很早起床吃早餐。"}', 5, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15382, 571, '{"english": "She goes to school early.", "chinese": "她很早去上学。"}', 6, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15383, 571, '{"english": "She helps her classmates.", "chinese": "她帮同学的忙。"}', 7, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15384, 571, '{"english": "She finishes her homework before dinner.", "chinese": "她在晚饭前先完成家庭作业。"}', 8, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15385, 571, '{"english": "She always waits for the green man before she crosses the road.", "chinese": "在过马路之前，她总是先等绿灯。"}', 9, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15386, 571, '{"english": "She often eats too many sweets.", "chinese": "她经常吃太多糖果。"}', 10, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15387, 571, '{"english": "Amy''s good habits", "chinese": "艾米的好习惯"}', 11, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15388, 571, '{"english": "Amy''s bad habits", "chinese": "艾米的坏习惯"}', 12, '2026-02-05 04:28:33', '2026-02-05 04:28:33');
INSERT INTO "course_content" VALUES (15389, 571, '{"english": "John says \"good morning\" to his teachers, but he is sometimes late for school.", "chinese": "约翰会向他的老师们说“早上好”，但是他上学有时会迟到。"}', 13, '2026-02-05 04:28:34', '2026-02-05 04:28:34');
INSERT INTO "course_content" VALUES (15390, 571, '{"english": "He watches TV after school and does his homework in the evening.", "chinese": "他放学后会看电视，然后在晚上做家庭作业。"}', 14, '2026-02-05 04:28:34', '2026-02-05 04:28:34');
INSERT INTO "course_content" VALUES (15391, 571, '{"english": "He waits for the green man before he crosses the road, but he sometimes runs quickly on the road.", "chinese": "他在过马路之前会先等绿灯，但是他有时会在马路上快跑。"}', 15, '2026-02-05 04:28:35', '2026-02-05 04:28:35');
INSERT INTO "course_content" VALUES (15392, 571, '{"english": "He usually eats a lot of meat for lunch and dinner.", "chinese": "他午餐和晚餐通常会吃许多肉。"}', 16, '2026-02-05 04:28:35', '2026-02-05 04:28:35');
INSERT INTO "course_content" VALUES (15393, 571, '{"english": "John''s good habits", "chinese": "约翰的好习惯"}', 17, '2026-02-05 04:28:35', '2026-02-05 04:28:35');
INSERT INTO "course_content" VALUES (15394, 571, '{"english": "John''s bad habits", "chinese": "约翰的坏习惯"}', 18, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15395, 571, '{"english": "What makes a good student?", "chinese": "什么会造就一个好学生？"}', 19, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15396, 571, '{"english": "Talk about this in groups.", "chinese": "分组讨论一下这个吧。"}', 20, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15397, 571, '{"english": "A good student should go to school early.", "chinese": "一个好学生应该很早就去上学。"}', 21, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15398, 571, '{"english": "A good student must ...", "chinese": "一个好学生必须……"}', 22, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15399, 571, '{"english": "A good student mustn''t ...", "chinese": "一个好学生不准……"}', 23, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15400, 571, '{"english": "How can you be a good student?", "chinese": "你怎样才能成为一个好学生呢？"}', 24, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15401, 571, '{"english": "In groups, make a poster about this on page 99.", "chinese": "小组合作，在第99页上面制作一张有关这个的海报。"}', 25, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15402, 571, '{"english": "Then show and tell your class about the poster.", "chinese": "然后展示一下并给你们班讲讲那张海报。"}', 26, '2026-02-05 04:28:36', '2026-02-05 04:28:36');
INSERT INTO "course_content" VALUES (15403, 572, '{"english": "Unit 5 A party", "chinese": "第五单元 派对"}', 1, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15404, 572, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15405, 572, '{"english": "Tip, Be prepared.", "chinese": "小贴士，做好准备。"}', 3, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15406, 572, '{"english": "See page 91.", "chinese": "见第91页。"}', 4, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15407, 572, '{"english": "It is Children''s Day this Sunday.", "chinese": "本周日是儿童节。"}', 5, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15408, 572, '{"english": "The children are going to have a party at Mike''s house.", "chinese": "孩子们打算在迈克家里举办一个派对。"}', 6, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15409, 572, '{"english": "Su Hai is going to buy some snacks and drinks.", "chinese": "苏海打算买一些零食和饮料。"}', 7, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15410, 572, '{"english": "Wang Bing is going to bring some fruit from home.", "chinese": "王冰打算从家里带一些水果来。"}', 8, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15411, 572, '{"english": "Yang Ling is going to bring some toys and play with her friends at the party.", "chinese": "杨琳打算带一些玩具来，并打算在派对上和朋友们一起玩。"}', 9, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15412, 572, '{"english": "Look at Liu Tao.", "chinese": "看看刘涛。"}', 10, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15413, 572, '{"english": "What is he going to do for the party?", "chinese": "他打算为这次派对做什么呢？"}', 11, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15414, 572, '{"english": "balloons", "chinese": "气球"}', 12, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15415, 572, '{"english": "drinks", "chinese": "饮料"}', 13, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15416, 572, '{"english": "fruit", "chinese": "水果"}', 14, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15417, 572, '{"english": "It is Sunday morning.", "chinese": "现在是周日上午。"}', 15, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15418, 572, '{"english": "The children bring their things to Mike''s house.", "chinese": "孩子们带着他们的东西来到了迈克家里。"}', 16, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15419, 572, '{"english": "Hello!", "chinese": "你们好！"}', 17, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15420, 572, '{"english": "Where''s Liu Tao?", "chinese": "刘涛在哪儿？"}', 18, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15421, 572, '{"english": "We don''t know.", "chinese": "我们不知道。"}', 19, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15422, 572, '{"english": "Just then, a clown appears.", "chinese": "就在那时，有个小丑出现了。"}', 20, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15423, 572, '{"english": "Who are you?", "chinese": "你是谁？"}', 21, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15424, 572, '{"english": "I''m Liu Tao.", "chinese": "我是刘涛。"}', 22, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15425, 572, '{"english": "Here are some balloons for you.", "chinese": "给你们一些气球。"}', 23, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15426, 572, '{"english": "Thank you!", "chinese": "谢谢你！"}', 24, '2026-02-05 04:28:37', '2026-02-05 04:28:37');
INSERT INTO "course_content" VALUES (15427, 572, '{"english": "Now the party begins.", "chinese": "现在派对开始了。"}', 25, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15428, 572, '{"english": "Are we going to eat or play with the toys first?", "chinese": "我们是要先吃，还是要先玩玩具？"}', 26, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15429, 572, '{"english": "Let''s have some fun first!", "chinese": "我们先找点乐子吧！"}', 27, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15430, 572, '{"english": "Hooray!", "chinese": "好哇！"}', 28, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15431, 572, '{"english": "snacks", "chinese": "零食"}', 29, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15432, 572, '{"english": "toys", "chinese": "玩具"}', 30, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15433, 572, '{"english": "Match and say", "chinese": "连一连，说一说"}', 31, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15434, 572, '{"english": "What are the children going to bring to the party?", "chinese": "孩子们打算把什么带到派对上来？"}', 32, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15435, 572, '{"english": "Su Hai is going to bring some ... to the party.", "chinese": "苏海打算带一些……到派对上来。"}', 33, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15436, 572, '{"english": "You", "chinese": "你"}', 34, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15437, 572, '{"english": "True or false", "chinese": "对还是错"}', 35, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15438, 572, '{"english": "The party is on Children''s Day.", "chinese": "这次派对是在儿童节那天。"}', 36, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15439, 572, '{"english": "The party is at Su Hai''s home.", "chinese": "这次派对是在苏海的家里。"}', 37, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15440, 572, '{"english": "Wang Bing buys some fruit from the supermarket.", "chinese": "王冰从超市买了一些水果。"}', 38, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15441, 572, '{"english": "Liu Tao does not go to the party with his friends.", "chinese": "刘涛没有和朋友们一起去参加派对。"}', 39, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15442, 572, '{"english": "There are six children at the party.", "chinese": "在派对上有六个孩子。"}', 40, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15443, 572, '{"english": "The children want to have some food first.", "chinese": "孩子们想先吃些食物。"}', 41, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15444, 572, '{"english": "Grammar time", "chinese": "语法时间"}', 42, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15445, 572, '{"english": "What are you / we / they going to bring to the party? What is he / she going to do at the party?", "chinese": "你 / 我们 / 他们打算带什么去参加聚会？ 他 / 她打算在聚会上做什么？"}', 43, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15446, 572, '{"english": "I am going to bring some snakes to the party. We / They are going to bring some snakes to the party. He / she is going to play with some toys at the party.", "chinese": "我打算带一些零食去参加聚会。 我们 / 他们打算带一些零食去参加聚会。 他 / 她打算在聚会上玩玩具。"}', 44, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15447, 572, '{"english": "Are you / we / they going to bring some snacks to the party? Is he / she going to bring some snacks to the party?", "chinese": "你 / 我们 / 他们打算带零食去参加聚会吗？ 他 / 她打算带零食去参加聚会吗？"}', 45, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15448, 572, '{"english": "Yes, I am. Yes, we / they are. No, he / she isn''t.", "chinese": "是的，我打算打算带零食去参加聚会。 是的，我们 / 他们打算带零食去参加聚会。 不，他 / 她不打算带零食去参加聚会。"}', 46, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15449, 572, '{"english": "Fun time", "chinese": "娱乐时间"}', 47, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15450, 572, '{"english": "Say and make", "chinese": "说一说，做一做"}', 48, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15451, 572, '{"english": "When are we going to have the party?", "chinese": "我们打算什么时候举办派对？"}', 49, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15452, 572, '{"english": "We''re going to have the party on ...", "chinese": "我们打算在……举办派对"}', 50, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15453, 572, '{"english": "Where are we going to have the party?", "chinese": "我们打算在哪里举办派对？"}', 51, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15454, 572, '{"english": "We''re going to have the party at / in ...", "chinese": "我们打算在……举办派对"}', 52, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15455, 572, '{"english": "What are you going to bring to the party?", "chinese": "你打算把什么带到派对上来？"}', 53, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15456, 572, '{"english": "I''m going to bring ...", "chinese": "我打算带来……"}', 54, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15457, 572, '{"english": "Welcome to the party!", "chinese": "欢迎参加派对！"}', 55, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15458, 572, '{"english": "Invitation", "chinese": "请柬"}', 56, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15459, 572, '{"english": "Date: 15th April (Sunday)", "chinese": "日期：4月15日（星期日）"}', 57, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
