INSERT INTO "course_content" VALUES (15474, 572, '{"english": "When you go to a Western party, you should take a gift.", "chinese": "当你去参加西方的派对时，你应该带份礼物去。"}', 72, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15475, 572, '{"english": "Do not arrive too early.", "chinese": "别到得太早。"}', 73, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
