INSERT INTO "course_content" VALUES (15478, 572, '{"english": "Bobby''s class is going to have a party soon.", "chinese": "波比的班上马上要举办一次派对。"}', 76, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
