INSERT INTO "course_content" VALUES (15480, 572, '{"english": "I''m going to play the piano.", "chinese": "我打算弹钢琴。"}', 78, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15481, 572, '{"english": "What are you going to do at the party, Willy?", "chinese": "你打算在派对上做什么，维利？"}', 79, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15482, 572, '{"english": "I''m going to tell a story.", "chinese": "我打算讲故事。"}', 80, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15483, 572, '{"english": "What are we going to do at the party, Sam?", "chinese": "我们要在派对上做什么，萨姆？"}', 81, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15484, 572, '{"english": "Let''s put on a play.", "chinese": "我们表演一部戏剧吧。"}', 82, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15485, 572, '{"english": "What about The king''s new clothes?", "chinese": "《皇帝的新装》怎么样？"}', 83, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15486, 572, '{"english": "Sure!", "chinese": "当然好了！"}', 84, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15487, 572, '{"english": "I''m going to be the king.", "chinese": "我要当国王。"}', 85, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15488, 572, '{"english": "Now Bobby is the king.", "chinese": "现在，波比是国王。"}', 86, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15489, 572, '{"english": "He is wearing his \"new clothes\".", "chinese": "他正穿着“新衣服”。"}', 87, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
INSERT INTO "course_content" VALUES (15490, 572, '{"english": "Ha! Ha! Ha!", "chinese": "哈！哈！哈！"}', 88, '2026-02-05 04:28:38', '2026-02-05 04:28:38');
