INSERT INTO "course_content" VALUES (15500, 572, '{"english": "Lily: think of some party games", "chinese": "莉莉：想出一些派对游戏"}', 98, '2026-02-05 04:28:39', '2026-02-05 04:28:39');
INSERT INTO "course_content" VALUES (15501, 572, '{"english": "Where are you going to have the party?", "chinese": "你打算在哪儿举办派对？"}', 99, '2026-02-05 04:28:39', '2026-02-05 04:28:39');
INSERT INTO "course_content" VALUES (15502, 572, '{"english": "When''s the party going to begin?", "chinese": "派对将在什么时候开始？"}', 100, '2026-02-05 04:28:39', '2026-02-05 04:28:39');
