INSERT INTO "course_content" VALUES (15509, 572, '{"english": "I know about parties.", "chinese": "我知道有关派对的事情。"}', 107, '2026-02-05 04:28:39', '2026-02-05 04:28:39');
INSERT INTO "course_content" VALUES (15510, 572, '{"english": "I can use \"am / is / are going to\" to ask and answer questions.", "chinese": "我能使用“am / is / are going to”来提问并回答问题。"}', 108, '2026-02-05 04:28:39', '2026-02-05 04:28:39');
