INSERT INTO "course_content" VALUES (15566, 573, '{"english": "Make and say", "chinese": "做一做，说一说"}', 55, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15567, 573, '{"english": "About ______", "chinese": "关于______"}', 56, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
