INSERT INTO "course_content" VALUES (15572, 573, '{"english": "About the UK", "chinese": "关于英国的信息"}', 61, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15573, 573, '{"english": "Weather: rainy", "chinese": "天气：多雨的"}', 62, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15574, 573, '{"english": "Interesting sport: football", "chinese": "有趣的运动：足球"}', 63, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15575, 573, '{"english": "Interesting cities: London, Oxford", "chinese": "有趣的城市：伦敦，牛津"}', 64, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15576, 573, '{"english": "Interesting places: Big Ben, London Eye, Tower Bridge", "chinese": "有趣的景点：大本钟，伦敦眼，塔桥"}', 65, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15577, 573, '{"english": "Today, I''ll tell you about the UK.", "chinese": "今天，我要给你讲讲英国。"}', 66, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15578, 573, '{"english": "The weather is sometimes rainy in the UK, and the people there love football.", "chinese": "英国的天气有时会下雨，那里的人热爱足球。"}', 67, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15579, 573, '{"english": "There are some interesting cities in the country, for example, London and Oxford.", "chinese": "在这个国家中有一些有趣的城市，例如伦敦和牛津。"}', 68, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15580, 573, '{"english": "You''ll find interesting places like Big Ben, the London Eye and Tower Bridge.", "chinese": "你将会找到诸如大本钟、伦敦眼和塔桥之类的有趣景点。"}', 69, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15581, 573, '{"english": "Sound time", "chinese": "语音时间"}', 70, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15582, 573, '{"english": "air", "chinese": ""}', 71, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15583, 573, '{"english": "Look over there!", "chinese": "看看那边！"}', 72, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15584, 573, '{"english": "It''s Sydney in Australia.", "chinese": "它是澳大利亚的悉尼。"}', 73, '2026-02-05 04:28:41', '2026-02-05 04:28:41');
INSERT INTO "course_content" VALUES (15585, 573, '{"english": "The city has fresh air.", "chinese": "这座城市有着新鲜的空气。"}', 74, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15586, 573, '{"english": "Its view is fair.", "chinese": "它的风景很美。"}', 75, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15587, 573, '{"english": "air", "chinese": "空气"}', 76, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15588, 573, '{"english": "chair", "chinese": "椅子"}', 77, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15589, 573, '{"english": "fair", "chinese": "公平的；美丽的"}', 78, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15590, 573, '{"english": "hair", "chinese": "头发"}', 79, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15591, 573, '{"english": "Culture time", "chinese": "文化时间"}', 80, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15592, 573, '{"english": "Tip Find more information about these places.", "chinese": "小贴士查找更多有关这些地方的信息。"}', 81, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15593, 573, '{"english": "See page 91.", "chinese": "见第91页。"}', 82, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15594, 573, '{"english": "You''ll find the Great Wall in the PRC.", "chinese": "你将会在中国找到长城。"}', 83, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15595, 573, '{"english": "You''ll find Yellowstone National Park in the US.", "chinese": "你将会在美国找到黄石国家公园。"}', 84, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15596, 573, '{"english": "You''ll find Stonehenge in the UK.", "chinese": "你将会在英国找到巨石阵。"}', 85, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15597, 573, '{"english": "You''ll find the Great Barrier Reef in Australia.", "chinese": "你将会在澳大利亚找到大堡礁。"}', 86, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15598, 573, '{"english": "Cartoon time", "chinese": "卡通时间"}', 87, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15599, 573, '{"english": "Billy likes eating nice food.", "chinese": "比利喜欢吃美食。"}', 88, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15600, 573, '{"english": "Yummy!", "chinese": "真好吃！"}', 89, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15601, 573, '{"english": "I want to be a cook.", "chinese": "我想当一名厨师。"}', 90, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15602, 573, '{"english": "Billy wants to find out about cooking.", "chinese": "比利想找出有关烹饪的信息。"}', 91, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15603, 573, '{"english": "I''ll learn about cooking on the Internet.", "chinese": "我要在网上学习烹饪。"}', 92, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15604, 573, '{"english": "I''ll read newspapers too.", "chinese": "我还要看报纸。"}', 93, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15605, 573, '{"english": "Billy will cook dinner for Bobby and Sam.", "chinese": "比利要为波比和萨姆做晚饭。"}', 94, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15606, 573, '{"english": "What will you cook?", "chinese": "你要煮什么？"}', 95, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15607, 573, '{"english": "Will you cook fish for me?", "chinese": "你要给我煮鱼吗？"}', 96, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15608, 573, '{"english": "Just wait and see.", "chinese": "等着瞧就是了。"}', 97, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15609, 573, '{"english": "Billy is very busy in the kitchen.", "chinese": "比利在厨房非常忙碌。"}', 98, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15610, 573, '{"english": "He is cooking fish and making a potato salad.", "chinese": "他正在煮鱼，并且还在做土豆沙拉。"}', 99, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15611, 573, '{"english": "What do you think, Sam?", "chinese": "你觉得呢，萨姆？"}', 100, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15612, 573, '{"english": "Is he a good cook?", "chinese": "他是个好厨师吗？"}', 101, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15613, 573, '{"english": "Checkout time", "chinese": "检测时间"}', 102, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15614, 573, '{"english": "Read and write", "chinese": "读一读，写一写"}', 103, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15615, 573, '{"english": "Complete the passages with \"will\" and the correct words.", "chinese": "用“will”以及正确的单词完成这些短文。"}', 104, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15616, 573, '{"english": "buy", "chinese": "买"}', 105, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15617, 573, '{"english": "go", "chinese": "去"}', 106, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15618, 573, '{"english": "help", "chinese": "帮助"}', 107, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15619, 573, '{"english": "send", "chinese": "发送，寄"}', 108, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15620, 573, '{"english": "tell", "chinese": "告诉"}', 109, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15621, 573, '{"english": "visit", "chinese": "参观；拜访"}', 110, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15622, 573, '{"english": "Uncle Bob lives in Australia.", "chinese": "鲍勃叔叔住在澳大利亚。"}', 111, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15623, 573, '{"english": "My parents and I will visit him next month.", "chinese": "我和我父母下个月将会去拜访他。"}', 112, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15624, 573, '{"english": "Dad will send him an email tomorrow.", "chinese": "爸爸明天会给他发一封电子邮件。"}', 113, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15625, 573, '{"english": "He will tell Uncle Bob about our visit.", "chinese": "他将会告诉鲍勃叔叔有关我们要去拜访的事。"}', 114, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15626, 573, '{"english": "Mum will go shopping this Sunday.", "chinese": "这个周日妈妈将会去购物。"}', 115, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15627, 573, '{"english": "She will buy some presents for Uncle Bob.", "chinese": "她要给鲍勃叔叔买一些礼物。"}', 116, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15628, 573, '{"english": "I will help my parents do the housework this Saturday.", "chinese": "这个周六我要帮父母做家务。"}', 117, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15629, 573, '{"english": "After that, I will go to the library.", "chinese": "在那之后，我将会去图书馆。"}', 118, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15630, 573, '{"english": "I want to find out more about Australia!", "chinese": "我想找出更多有关澳大利亚的信息！"}', 119, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15631, 573, '{"english": "bring", "chinese": "带来"}', 120, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15632, 573, '{"english": "buy", "chinese": "买"}', 121, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15633, 573, '{"english": "go", "chinese": "去"}', 122, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15634, 573, '{"english": "have", "chinese": "有"}', 123, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15635, 573, '{"english": "make", "chinese": "做，制作"}', 124, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15636, 573, '{"english": "My friends and I will go to the park this Saturday.", "chinese": "这个周六我和朋友们将会去公园。"}', 125, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15637, 573, '{"english": "We will have a picnic there.", "chinese": "我们要在那里举行野餐。"}', 126, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15638, 573, '{"english": "I will buy some snacks from the supermarket.", "chinese": "我将会从超市买一些零食。"}', 127, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15639, 573, '{"english": "Ken will bring some fruit from home.", "chinese": "肯将会从家里带一些水果来。"}', 128, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15640, 573, '{"english": "Tracy will make some sandwiches for us.", "chinese": "特蕾西将会给我们做一些三明治。"}', 129, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15641, 573, '{"english": "She''s so nice!", "chinese": "她真好！"}', 130, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15642, 573, '{"english": "I can''t wait to have the picnic.", "chinese": "我等不及要举行这次野餐了。"}', 131, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15643, 573, '{"english": "Think and say", "chinese": "想一想，说一说"}', 132, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15644, 573, '{"english": "What will you do tomorrow?", "chinese": "你明天将会做什么？"}', 133, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15645, 573, '{"english": "Tell your classmates.", "chinese": "跟你的同学说一说吧。"}', 134, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15646, 573, '{"english": "I''ll do many things tomorrow.", "chinese": "我明天将会做许多事情。"}', 135, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15647, 573, '{"english": "First, I''ll go to the library.", "chinese": "首先，我将会去图书馆。"}', 136, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15648, 573, '{"english": "Then, I''ll ...", "chinese": "然后，我将会……"}', 137, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15649, 573, '{"english": "That''s good.", "chinese": "那很好。"}', 138, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15650, 573, '{"english": "I''ll also do many things tomorrow.", "chinese": "我明天也会做许多事情。"}', 139, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15651, 573, '{"english": "First, I''ll ...", "chinese": "首先，我将会……"}', 140, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15652, 573, '{"english": "Ticking time", "chinese": "打勾时间"}', 141, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15653, 573, '{"english": "I know some things about Australia.", "chinese": "我知道一些有关澳大利亚的事情。"}', 142, '2026-02-05 04:28:42', '2026-02-05 04:28:42');
INSERT INTO "course_content" VALUES (15654, 573, '{"english": "I can use \"will\" to talk about the future.", "chinese": "我能使用“will”来谈论将来。"}', 143, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15655, 573, '{"english": "I know the sound of \"air\".", "chinese": "我知道“air”的发音。"}', 144, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15656, 574, '{"english": "Unit 7 Summer holiday plans", "chinese": "第七单元 暑假计划"}', 1, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15657, 574, '{"english": "Story time", "chinese": "故事时间"}', 2, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15658, 574, '{"english": "The children are talking about their plans for the summer holiday.", "chinese": "孩子们正在谈论他们的暑假计划。"}', 3, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15659, 574, '{"english": "Where will you go for the holiday, Mike?", "chinese": "这次假期你将会去哪儿，迈克？"}', 4, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15660, 574, '{"english": "I''ll go back to London.", "chinese": "我将会回伦敦。"}', 5, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15661, 574, '{"english": "How long will you stay there?", "chinese": "你将会在那儿呆多久？"}', 6, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15662, 574, '{"english": "I''ll stay there for a month.", "chinese": "我将会在那儿呆一个月。"}', 7, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15663, 574, '{"english": "What about you?", "chinese": "你呢？"}', 8, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15664, 574, '{"english": "I''ll visit my aunt and uncle in Beijing.", "chinese": "我将会拜访我北京的叔叔阿姨。"}', 9, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15665, 574, '{"english": "That sounds great.", "chinese": "听起来不错。"}', 10, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15666, 574, '{"english": "Will you go to Beijing by plane?", "chinese": "你将会乘飞机去北京吗？"}', 11, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15667, 574, '{"english": "No, I won''t.", "chinese": "不，我不会。"}', 12, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15668, 574, '{"english": "I''ll go by train.", "chinese": "我将会乘火车去。"}', 13, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15669, 574, '{"english": "Beijing", "chinese": "北京"}', 14, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15670, 574, '{"english": "Hong Kong", "chinese": "香港"}', 15, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15671, 574, '{"english": "Where will you go for the summer holiday, Su Hai?", "chinese": "这次暑假你将会去哪儿，苏海？"}', 16, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15672, 574, '{"english": "I''ll go to Hong Kong with my family.", "chinese": "我将会和家人一起去香港。"}', 17, '2026-02-05 04:28:43', '2026-02-05 04:28:43');
INSERT INTO "course_content" VALUES (15673, 574, '{"english": "Will you go to Disneyland?", "chinese": "你会去迪士尼乐园吗？"}', 18, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15674, 574, '{"english": "Yes, I will.", "chinese": "是的，我会。"}', 19, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15675, 574, '{"english": "We''ll go to Ocean Park too.", "chinese": "我们还会去海洋公园。"}', 20, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15676, 574, '{"english": "What about you, Liu Tao?", "chinese": "你呢，刘涛？"}', 21, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15677, 574, '{"english": "I''ll go to Taipei with my parents.", "chinese": "我将会和父母一起去台北。"}', 22, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15678, 574, '{"english": "That''s wonderful.", "chinese": "太棒了。"}', 23, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15679, 574, '{"english": "I want to see the city too.", "chinese": "我也想去看看那座城市。"}', 24, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15680, 574, '{"english": "OK.", "chinese": "好的。"}', 25, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15681, 574, '{"english": "I''ll show you some photos after the holiday.", "chinese": "假期结束后我会给你看一些照片。"}', 26, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15682, 574, '{"english": "Thanks!", "chinese": "谢谢！"}', 27, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15683, 574, '{"english": "Tip Talk about your holiday plans.", "chinese": "小贴士说一说你的假日安排。"}', 28, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15684, 574, '{"english": "See page 91.", "chinese": "见第91页。"}', 29, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15685, 574, '{"english": "London", "chinese": "伦敦"}', 30, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15686, 574, '{"english": "Taipei", "chinese": "台北"}', 31, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15687, 574, '{"english": "Match and say", "chinese": "连一连，说一说"}', 32, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15688, 574, '{"english": "Where will the children go for the summer holiday?", "chinese": "暑假孩子们将会去哪儿？"}', 33, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15689, 574, '{"english": "Mike will go ...", "chinese": "迈克将会去……"}', 34, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15690, 574, '{"english": "You", "chinese": "你"}', 35, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15691, 574, '{"english": "Read and write", "chinese": "读一读，写一写"}', 36, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15692, 574, '{"english": "Mike is writing about everyone''s summer holiday plans.", "chinese": "迈克正在记述大家的暑假计划。"}', 37, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15693, 574, '{"english": "Complete his notes.", "chinese": "完成他的笔记。"}', 38, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15694, 574, '{"english": "Our summer holiday", "chinese": "我们的暑假"}', 39, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15695, 574, '{"english": "My friends and I will be busy in the summer holiday.", "chinese": "在这次暑假中我和我的朋友将会很忙。"}', 40, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15696, 574, '{"english": "My family and I will visit Grandma and Grandpa in London.", "chinese": "我和我的家人将会拜访伦敦的爷爷奶奶。"}', 41, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15697, 574, '{"english": "We will stay there for a month.", "chinese": "我们将会在那儿呆一个月。"}', 42, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15698, 574, '{"english": "Yang Ling''s aunt and uncle live in Beijing.", "chinese": "杨琳的叔叔阿姨住在北京。"}', 43, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15699, 574, '{"english": "She will visit them this summer.", "chinese": "今年夏天她将会去拜访他们。"}', 44, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15700, 574, '{"english": "She will go there by train.", "chinese": "她将会乘火车去那儿。"}', 45, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15701, 574, '{"english": "Su Hai and her family will visit Disneyland and Ocean Park in Hong Kong.", "chinese": "苏海和她的家人将会参观香港的迪士尼乐园和海洋公园。"}', 46, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15702, 574, '{"english": "Liu Tao will go to Taipei with his parents.", "chinese": "刘涛将会和他的父母一起去台北。"}', 47, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15703, 574, '{"english": "He will take some photos and show them after the holiday.", "chinese": "他将会拍一些照片，然后在假期结束后再将它们展示出来。"}', 48, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15704, 574, '{"english": "Grammar time", "chinese": "语法时间"}', 49, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15705, 574, '{"english": "Will you go to Beijing by plane? Will they go to Disneyland? Will he stay in London for a month? Will she visit her aunt and uncle?", "chinese": "你要坐飞机去北京吗？ 他们要去迪士尼乐园吗？ 他要在伦敦待上一个月吗？ 她要去看望舅舅和舅妈吗？"}', 50, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15706, 574, '{"english": "Yes, I will. Yes, they will. No, he won''t. No, she won''t.", "chinese": "是的，我要坐飞机去北京。 是的，他们要去迪士尼乐园。 不，他不会在伦敦待一个月。 不，她不去看望舅舅和舅妈。"}', 51, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15707, 574, '{"english": "won''t = will not", "chinese": "不会 = 不会"}', 52, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15708, 574, '{"english": "Where will you go for the summer holiday? When will we go? How long will he stay there? What will she do there?", "chinese": "暑假你要去哪里？ 我们要什么时候时候去？ 他要在那儿待多久？ 她要在那儿做什么？"}', 53, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15709, 574, '{"english": "I will go to Taipei. We will go in July. He will stay there for a month. She will visit Ocean Park.", "chinese": "我要去台北。 我们七月去。 他要在那儿待一个月。 她要去参观海洋公园。"}', 54, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15710, 574, '{"english": "Fun time", "chinese": "娱乐时间"}', 55, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15711, 574, '{"english": "Play a game", "chinese": "玩游戏"}', 56, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15712, 574, '{"english": "I''ll go to Beijing.", "chinese": "我将会去北京。"}', 57, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15713, 574, '{"english": "I''ll go to Hong Kong.", "chinese": "我将会去香港。"}', 58, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15714, 574, '{"english": "He''ll go to Beijing.", "chinese": "他将会去北京。"}', 59, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15715, 574, '{"english": "I''ll go to Taipei.", "chinese": "我将会去台北。"}', 60, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15716, 574, '{"english": "She''ll go to Hong Kong.", "chinese": "她将会去香港。"}', 61, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15717, 574, '{"english": "He''ll go to Beijing.", "chinese": "他将会去北京。"}', 62, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15718, 574, '{"english": "Well done!", "chinese": "干得好！"}', 63, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15719, 574, '{"english": "Sound time", "chinese": "语音时间"}', 64, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15720, 574, '{"english": "oy", "chinese": ""}', 65, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15721, 574, '{"english": "Look at the little boy Playing with his toy.", "chinese": "看看这个小男孩正在玩他的玩具。"}', 66, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15722, 574, '{"english": "He really is so happy.", "chinese": "他是真的很高兴。"}', 67, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15723, 574, '{"english": "He''s so full of joy!", "chinese": "他是如此充满快乐！"}', 68, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15724, 574, '{"english": "boy", "chinese": "男孩"}', 69, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15725, 574, '{"english": "joy", "chinese": "欢乐"}', 70, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15726, 574, '{"english": "toy", "chinese": "玩具"}', 71, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15727, 574, '{"english": "Culture time", "chinese": "文化时间"}', 72, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15728, 574, '{"english": "You''ll find Uluru in Australia.", "chinese": "你将会在澳大利亚找到乌卢鲁。"}', 73, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15729, 574, '{"english": "You''ll find the Grand Canyon in the US.", "chinese": "你将会在美国找到大峡谷。"}', 74, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15730, 574, '{"english": "You''ll find Niagara Falls in Canada.", "chinese": "你将会在加拿大找到尼亚加拉大瀑布。"}', 75, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15731, 574, '{"english": "Cartoon time", "chinese": "卡通时间"}', 76, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15732, 574, '{"english": "Bobby is reading a travel book.", "chinese": "波比正在阅读一本旅游手册。"}', 77, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15733, 574, '{"english": "I want to be a traveller and travel around the world.", "chinese": "我想当一名旅行家，还想环游世界。"}', 78, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15734, 574, '{"english": "Bobby is talking about his travel plans with Sam.", "chinese": "波比正在和萨姆一起谈论他的旅行计划。"}', 79, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15735, 574, '{"english": "I''ll visit many places.", "chinese": "我将会参观许多地方。"}', 80, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15736, 574, '{"english": "Will you go with me, Sam?", "chinese": "你会和我一起去吗，萨姆？"}', 81, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15737, 574, '{"english": "Yes, I will.", "chinese": "是的，我会。"}', 82, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15738, 574, '{"english": "What are your plans?", "chinese": "你有什么计划？"}', 83, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15739, 574, '{"english": "First, I''ll go to the UK.", "chinese": "首先，我将会去英国。"}', 84, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15740, 574, '{"english": "Next, I''ll go to the US.", "chinese": "接着，我将会去美国。"}', 85, '2026-02-05 04:28:44', '2026-02-05 04:28:44');
INSERT INTO "course_content" VALUES (15741, 574, '{"english": "Then, I''ll go to Australia.", "chinese": "然后，我将会去澳大利亚。"}', 86, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15742, 574, '{"english": "Sam is excited about Bobby''s plans.", "chinese": "萨姆对波比的计划感到很兴奋。"}', 87, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15743, 574, '{"english": "That sounds great!", "chinese": "听起来很不错！"}', 88, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15744, 574, '{"english": "I''ll go with you.", "chinese": "我要跟你一起去。"}', 89, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15745, 574, '{"english": "How will we get to the UK, Bobby?", "chinese": "我们将会怎样到达英国，波比？"}', 90, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15746, 574, '{"english": "Let''s take a taxi.", "chinese": "我们乘出租车吧。"}', 91, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15747, 574, '{"english": "Checkout time", "chinese": "检测时间"}', 92, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15748, 574, '{"english": "Think and write", "chinese": "想一想，写一写"}', 93, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15749, 574, '{"english": "What are your plans for the summer holiday?", "chinese": "你的暑假计划是什么？"}', 94, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15750, 574, '{"english": "My Summer holiday plans", "chinese": "我的暑假计划"}', 95, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15751, 574, '{"english": "This summer, I will go to ______.", "chinese": "今年夏天，我将会去______。"}', 96, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15752, 574, '{"english": "I will go there by ______.", "chinese": "我将会乘______去那儿。"}', 97, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15753, 574, '{"english": "I will go there in / on ______.", "chinese": "我将会在______去那儿。"}', 98, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15754, 574, '{"english": "I will stay there for ______.", "chinese": "我将会在那儿呆______。"}', 99, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15755, 574, '{"english": "I will do many things there.", "chinese": "我将会在那儿做许多事情。"}', 100, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15756, 574, '{"english": "I will ______.", "chinese": "我将会______。"}', 101, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15757, 574, '{"english": "I will have a wonderful summer holiday!", "chinese": "我将会拥有一个精彩的暑假！"}', 102, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15758, 574, '{"english": "Ask and answer", "chinese": "问一问，答一答"}', 103, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15759, 574, '{"english": "What will you do for the summer holiday?", "chinese": "暑假你将会做什么？"}', 104, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15760, 574, '{"english": "I''ll ...", "chinese": "我将会……"}', 105, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15761, 574, '{"english": "Will you ...?", "chinese": "你会……吗？"}', 106, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15762, 574, '{"english": "My friends and I have different plans for the summer holiday.", "chinese": "我和我的朋友有着不同的暑假计划。"}', 107, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15763, 574, '{"english": "I''ll / He''ll / She''ll ...", "chinese": "我将会 / 他将会 / 她将会……"}', 108, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15764, 574, '{"english": "Ticking time", "chinese": "打勾时间"}', 109, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15765, 574, '{"english": "I know about some great cities in the world.", "chinese": "我知道世界上的一些大城市。"}', 110, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15766, 574, '{"english": "I can ask and answer questions with \"will\".", "chinese": "我能用“will”提问并回答问题。"}', 111, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
INSERT INTO "course_content" VALUES (15767, 574, '{"english": "I know the sound of \"oy\".", "chinese": "我知道“oy”的发音。"}', 112, '2026-02-05 04:28:45', '2026-02-05 04:28:45');
