INSERT INTO "course_content" VALUES (15772, 575, '{"english": "Miss Li is asking the students about their dreams.", "chinese": "李老师正在询问学生们有关他们梦想的事情。"}', 5, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15773, 575, '{"english": "What do you want to be in the future, boys?", "chinese": "你们将来想当什么，男孩们？"}', 6, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15774, 575, '{"english": "I want to be a dentist.", "chinese": "我想当一名牙医。"}', 7, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15775, 575, '{"english": "Many children don''t care about their teeth, I want to help them.", "chinese": "很多孩子都不关心他们的牙齿，我想帮助他们。"}', 8, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15776, 575, '{"english": "I want to be an astronaut.", "chinese": "我想当一名宇航员。"}', 9, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15777, 575, '{"english": "I want to fly a spaceship to the Moon.", "chinese": "我想驾驶宇宙飞船去月球。"}', 10, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15778, 575, '{"english": "I want to be a football player.", "chinese": "我想当一名足球运动员。"}', 11, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15779, 575, '{"english": "I want to play in the World Cup some day.", "chinese": "将来有一天我想参加世界杯。"}', 12, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15780, 575, '{"english": "Thank you, boys.", "chinese": "谢谢你们，男孩们。"}', 13, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15781, 575, '{"english": "Your dreams are great!", "chinese": "你们的梦想真伟大！"}', 14, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
