INSERT INTO "course_content" VALUES (15783, 575, '{"english": "a dancer", "chinese": "一名舞蹈家"}', 16, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15784, 575, '{"english": "What do you want to be in the future, girls?", "chinese": "你们将来想当什么，女孩们？"}', 17, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15785, 575, '{"english": "I want to be a dancer.", "chinese": "我想当一名舞蹈家。"}', 18, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15786, 575, '{"english": "Dancing makes people healthy and beautiful.", "chinese": "跳舞可以使人健康而又美丽。"}', 19, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15787, 575, '{"english": "I want to be a writer.", "chinese": "我想当一名作家。"}', 20, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15788, 575, '{"english": "I want to write stories for children.", "chinese": "我想给孩子们写故事。"}', 21, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15789, 575, '{"english": "I want to be a pianist.", "chinese": "我想当一名钢琴演奏家。"}', 22, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
INSERT INTO "course_content" VALUES (15790, 575, '{"english": "Music makes people happy.", "chinese": "音乐可以使人快乐。"}', 23, '2026-02-05 04:28:46', '2026-02-05 04:28:46');
