INSERT INTO "course_content" VALUES (16304, 587, '{"english": "Do you like ...?", "chinese": "你喜欢⋯⋯？"}', 5, '2026-02-05 04:29:07', '2026-02-05 04:29:07');
INSERT INTO "course_content" VALUES (16305, 587, '{"english": "-Do you like oranges?  -Yes, I do.", "chinese": "—你喜欢橙吗？ —是的，我喜欢。"}', 6, '2026-02-05 04:29:07', '2026-02-05 04:29:07');
INSERT INTO "course_content" VALUES (16306, 587, '{"english": "-Do you like bananas?  -No, I don''t.", "chinese": "—你喜欢香蕉吗？ —不，我不喜欢。"}', 7, '2026-02-05 04:29:07', '2026-02-05 04:29:07');
