INSERT INTO "course_content" VALUES (16709, 598, '{"english": "Blue shirt, blue shirt,  I like my blue shirt.", "chinese": "蓝衬衫，蓝衬衫， 我喜欢我的蓝衬衫。"}', 9, '2026-02-05 04:29:29', '2026-02-05 04:29:29');
INSERT INTO "course_content" VALUES (16710, 598, '{"english": "Yellow skirt, yellow skirt,  I like my yellow skirt.", "chinese": "黄裙子，黄裙子， 我喜欢我的黄裙子。"}', 10, '2026-02-05 04:29:29', '2026-02-05 04:29:29');
INSERT INTO "course_content" VALUES (16711, 598, '{"english": "Green T-shirt, green T-shirt,  I like my green T-shirt.", "chinese": "绿 T 恤，绿 T 恤， 我喜欢我的绿 T 恤。"}', 11, '2026-02-05 04:29:29', '2026-02-05 04:29:29');
INSERT INTO "course_content" VALUES (16712, 598, '{"english": "Red dress, red dress,  I like my red dress.", "chinese": "红裙子，红裙子， 我喜欢我的红裙子。"}', 12, '2026-02-05 04:29:29', '2026-02-05 04:29:29');
