INSERT INTO "course_content" VALUES (16718, 598, '{"english": "C. Listen and chant again.  Blue shirt, blue shirt,  I like my blue shirt.", "chinese": "C. 听一听，再唱一遍。 蓝衬衫，蓝衬衫， 我喜欢我的蓝衬衫。"}', 18, '2026-02-05 04:29:29', '2026-02-05 04:29:29');
