INSERT INTO "course_content" VALUES (16724, 599, '{"english": "I''m hungry. I want ...", "chinese": "我饿了。我想要⋯⋯"}', 6, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16725, 599, '{"english": "I''m hungry. I want rice.", "chinese": "我饿了。我想要米饭。"}', 7, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16726, 599, '{"english": "I''m hungry. I want noodles.", "chinese": "我饿了。我想要面条。"}', 8, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16727, 599, '{"english": "I''m hungry. I want fish.", "chinese": "我饿了。我想要鱼肉。"}', 9, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16728, 599, '{"english": "I''m hungry. I want chicken.", "chinese": "我饿了。我想要鸡肉。"}', 10, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16729, 599, '{"english": "I''m hungry. I want vegetables.", "chinese": "我饿了。我想要蔬菜。"}', 11, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16730, 599, '{"english": "I''m hungry. I want eggs.", "chinese": "我饿了。我想要鸡蛋。"}', 12, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16731, 599, '{"english": "Do you want ... ?", "chinese": "你想要⋯⋯？"}', 13, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16732, 599, '{"english": "-Do you want juice?  -Yes, please.", "chinese": "—你想要果汁吗？ —好的，谢谢。"}', 14, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16733, 599, '{"english": "-Do you want water?  -No, thanks. I want juice.", "chinese": "—你想要水吗？ —不，谢谢。我想要果汁。"}', 15, '2026-02-05 04:29:30', '2026-02-05 04:29:30');
INSERT INTO "course_content" VALUES (16734, 600, '{"english": "On my desk,  I can see,", "chinese": "在我的书桌上， 我能看见，"}', 1, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16735, 600, '{"english": "A book for you, A book for me.", "chinese": "给你一本书，给我一本书。"}', 2, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16736, 600, '{"english": "Under my chair,  I can see,", "chinese": "在我的椅子下， 我能看见，"}', 3, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16737, 600, '{"english": "A schoolbag for you, A schoolbag for me.   In my classroom,  I can see,", "chinese": "给你一个书包，给我一个书包。  在我的教室里， 我能看见，"}', 4, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16738, 600, '{"english": "A blackboard for you, A blackboard for me!", "chinese": "给你一块黑板，给我一块黑板！"}', 5, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16739, 600, '{"english": "Where''s the green pencil, Green pencil, green pencil?", "chinese": "绿色铅笔在哪里？"}', 6, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16740, 600, '{"english": "Where''s the green pencil?  It''s under my desk.", "chinese": "绿色铅笔在哪里？ 它在我的书桌下面。"}', 7, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16741, 600, '{"english": "Where''s the red apple, Red apple, red apple?", "chinese": "红苹果在哪里？"}', 8, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16742, 600, '{"english": "Where''s the red apple?  It''s on my chair.", "chinese": "红苹果在哪里？ 它在我的椅子上。"}', 9, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16743, 600, '{"english": "This is the light,  near the bed.", "chinese": "这是灯， 靠近床。"}', 10, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16744, 600, '{"english": "This is the bed,  near the door.", "chinese": "这是床， 靠近门。"}', 11, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16745, 600, '{"english": "This is the door,  near the box.  What''s behind the box?", "chinese": "这是门， 靠近箱子。 箱子后面是什么？"}', 12, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16746, 600, '{"english": "Amy, Amy, where are you? In the schoolbag. Peekaboo.", "chinese": "艾米，艾米，你在哪里？在书包里面。躲猫猫。"}', 13, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16747, 600, '{"english": "Amy, Amy, where are you? On the schoolbag. Peekaboo.", "chinese": "艾米，艾米，你在哪里？在书包上面。躲猫猫。"}', 14, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16748, 600, '{"english": "Amy, Amy, where are you? Under the schoolbag. Peekaboo.", "chinese": "艾米，艾米，你在哪里？在书包下面。躲猫猫。"}', 15, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16749, 600, '{"english": "Amy, Amy,  where are you? Behind the schoolbag. Peekaboo.", "chinese": "艾米，艾米，你在哪里？在书包后面。躲猫猫。"}', 16, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16750, 600, '{"english": "We can play,  Night and day,", "chinese": "我们可以玩， 从早到晚，"}', 17, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16751, 600, '{"english": "With a doll, a bear or a train.", "chinese": "玩玩偶、熊或火车。"}', 18, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16752, 600, '{"english": "We can play,  Night and day,  With a car, a ball or a plane.", "chinese": "我们可以玩， 从早到晚， 玩小汽车、球或飞机。"}', 19, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16753, 600, '{"english": "Toy train, toy train,  Choo, choo, choo.", "chinese": "玩具火车，玩具火车， 啾，啾，啾。"}', 20, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16754, 600, '{"english": "Toy train, toy train,  GO, go, go.  Plane, plane,  Follow me.", "chinese": "玩具火车，玩具火车， 跑，跑，跑。 飞机，飞机， 跟我来。"}', 21, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16755, 600, '{"english": "Plane, plane, Come and see.   Toy train, toy train,  Choo, choo, choo.", "chinese": "飞机，飞机，过来看。  玩具火车，玩具火车， 啾，啾，啾。"}', 22, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16756, 600, '{"english": "Toy train, toy train,  Go, go, go.", "chinese": "玩具火车，玩具火车， 跑，跑，跑。"}', 23, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16757, 600, '{"english": "Ball, ball, Follow me. Ball, ball, Come and see.", "chinese": "球，球，跟我来。球，球，过来看。"}', 24, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16758, 600, '{"english": "Toy train, toy train,  Choo, choo, choo.", "chinese": "玩具火车，玩具火车， 啾，啾，啾。"}', 25, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16759, 600, '{"english": "Doll, doll, Follow me. Doll, doll, Come and see.   Toy train, toy train,  Go, go, go.", "chinese": "玩具火车，玩具火车， 跑，跑，跑。玩偶，玩偶，跟我来。玩偶，玩偶，过来看。"}', 26, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16760, 600, '{"english": "Toy train, toy train,  Choo, choo, choo.", "chinese": "玩具火车，玩具火车， 啾，啾，啾。"}', 27, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16761, 600, '{"english": "Toy train, toy train,  Go, go, go.", "chinese": "玩具火车，玩具火车， 跑，跑，跑。"}', 28, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16762, 600, '{"english": "Car, car, Follow me. Car, car, Come and see.", "chinese": "小汽车，小汽车，跟我来。小汽车，小汽车，过来看。"}', 29, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16763, 600, '{"english": "Toy train, toy train,  Choo, choo, choo.", "chinese": "玩具火车，玩具火车， 啾，啾，啾。"}', 30, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16764, 600, '{"english": "Toy train, toy train,  Go, go, go.", "chinese": "玩具火车，玩具火车， 跑，跑，跑。"}', 31, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16765, 600, '{"english": "Bear, bear, Follow me. Bear, bear, come and see.", "chinese": "熊，熊，跟我来。熊，熊，过来看看。"}', 32, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16766, 600, '{"english": "Do you like noodles, noodles, noodles?  No, no, I don''t.", "chinese": "你喜欢面条吗？ 不，不，我不喜欢。"}', 33, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16767, 600, '{"english": "Do you like chicken, chicken, chicken?  Yes, yes, I do.", "chinese": "你喜欢鸡肉吗？ 是，是，我喜欢。"}', 34, '2026-02-05 04:29:31', '2026-02-05 04:29:31');
INSERT INTO "course_content" VALUES (16768, 600, '{"english": "Do you like eggs, eggs, eggs?  No, no, I don''t.", "chinese": "你喜欢鸡蛋吗？ 不，不，我不喜欢。"}', 35, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16769, 600, '{"english": "Do you like vegetables, vegetables, vegetables?  Yes, yes, I do.", "chinese": "你喜欢蔬菜吗？ 是，是，我喜欢。"}', 36, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16770, 600, '{"english": "Do you like fish, fish, fish?  No, no, I don''t.", "chinese": "你喜欢鱼肉吗？ 不，不，我不喜欢。"}', 37, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16771, 600, '{"english": "Do you like rice, rice, rice?", "chinese": "你喜欢米饭吗？"}', 38, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16772, 600, '{"english": "Yes, yes, I do!  Rice is nice.", "chinese": "是，是，我喜欢！ 米饭很好吃。"}', 39, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16773, 600, '{"english": "Pat-a-cake, pat-a-cake, baker''s man!", "chinese": "做蛋糕，做蛋糕，面包师傅！"}', 40, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16774, 600, '{"english": "Bake us a cake as fast as you can.", "chinese": "给我做个蛋糕，以你最快的速度。"}', 41, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16775, 600, '{"english": "Pat it and prick it and mark it with ''B''.", "chinese": "拍一拍，卷一卷，刻上记号“B”。"}', 42, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16776, 600, '{"english": "Put it in the oven for baby and me,  For baby and me, for baby and me.", "chinese": "为我和宝宝，把它放到烤炉中， 为我和宝宝，为我和宝宝。"}', 43, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16777, 600, '{"english": "And there would be plenty for baby and me.", "chinese": "我和宝宝将会有很多蛋糕。"}', 44, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
INSERT INTO "course_content" VALUES (16778, 600, '{"english": "Pat-a-cake, pat-a-cake, baker''s man!", "chinese": "做蛋糕，做蛋糕，面包师傅！"}', 45, '2026-02-05 04:29:32', '2026-02-05 04:29:32');
