INSERT INTO "course_content" VALUES (17071, 610, '{"english": "Thank you. Thank you,Father Christmas.  Merry Christmas to you!", "chinese": "谢谢你。谢谢你，圣诞老人。 祝你圣诞快乐！"}', 28, '2026-02-05 04:29:47', '2026-02-05 04:29:47');
INSERT INTO "course_content" VALUES (17072, 610, '{"english": "Merry Christmas, boys and girls!", "chinese": "圣诞快乐，孩子们！"}', 29, '2026-02-05 04:29:47', '2026-02-05 04:29:47');
INSERT INTO "course_content" VALUES (17073, 610, '{"english": "Here''s a Christmas tree for you.  Thank you.", "chinese": "这是给你们的圣诞树。 谢谢你。"}', 30, '2026-02-05 04:29:47', '2026-02-05 04:29:47');
INSERT INTO "course_content" VALUES (17074, 611, '{"english": "Revision 2", "chinese": "复习 2"}', 1, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17075, 611, '{"english": "A. Look, listen and point.", "chinese": "A. 看一看，听一听，指一指。"}', 2, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17076, 611, '{"english": "START", "chinese": "开始"}', 3, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17077, 611, '{"english": "Where are you going?", "chinese": "你要去哪里？"}', 4, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17078, 611, '{"english": "-Where are you going?  -I''m going to the bookshop.", "chinese": "—你要去哪里？ —我要去书店。"}', 5, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17079, 611, '{"english": "-Where are you going?  -I''m going to the zoo.", "chinese": "—你要去哪里？ —我要去动物园。"}', 6, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17080, 611, '{"english": "-Where are you going?  -I''m going to school.", "chinese": "—你要去哪里？ —我要去学校。"}', 7, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17081, 611, '{"english": "-Where are you going?  -I''m going to the supermarket.", "chinese": "—你要去哪里？ —我要去超市。"}', 8, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17082, 611, '{"english": "-Where are you going?  -I''m going to the park.", "chinese": "—你要去哪里？ —我要去公园。"}', 9, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17083, 611, '{"english": "-Where are you going?  -I''m going to the hospital.", "chinese": "—你要去哪里？ —我要去医院。"}', 10, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17084, 611, '{"english": "B. Let''s say.", "chinese": "B. 让我们说一说。"}', 11, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17085, 611, '{"english": "C. Let''s play.", "chinese": "C. 让我们玩一玩。"}', 12, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17086, 611, '{"english": "There is/are ...", "chinese": "有⋯⋯"}', 13, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17087, 611, '{"english": "There are flowers in the grass.", "chinese": "草里有花。"}', 14, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17088, 611, '{"english": "There is a lake in the park.", "chinese": "公园里有一个湖。"}', 15, '2026-02-05 04:29:48', '2026-02-05 04:29:48');
INSERT INTO "course_content" VALUES (17089, 612, '{"english": "I''m so happy.", "chinese": "我好开心。"}', 1, '2026-02-05 04:29:50', '2026-02-05 04:29:50');
INSERT INTO "course_content" VALUES (17090, 612, '{"english": "Can you see?  Come and meet my family.", "chinese": "你能看见吗？ 来见见我的家人吧。"}', 2, '2026-02-05 04:29:50', '2026-02-05 04:29:50');
