INSERT INTO "course_content" VALUES (17652, 629, '{"english": "Andy''s friends come to play with him.", "chinese": "安迪的朋友们来和他一起玩。"}', 4, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17653, 629, '{"english": "1. -Mum, this is my new friend.", "chinese": "1. —妈妈，这是我的新朋友。"}', 5, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17654, 629, '{"english": "-Hello, what''s your name?  -My name is Sue.", "chinese": "—你好，你叫什么名字？ —我叫苏。"}', 6, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17655, 629, '{"english": "-How old are you?  -I''m nine years old.", "chinese": "—你多大了？ —我九岁了。"}', 7, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17656, 629, '{"english": "-Are you in Andy''s class?  -Yes.", "chinese": "—你在安迪的班级吗？ —是的。"}', 8, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17657, 629, '{"english": "-Mum, this is my new friend.  -Hello, what''s your name?", "chinese": "—妈妈，这是我的新朋友。 —你好，你叫什么名字？"}', 9, '2026-02-05 04:30:18', '2026-02-05 04:30:18');
INSERT INTO "course_content" VALUES (17658, 629, '{"english": "-My name is Sue.  -How old are you?", "chinese": "—我叫苏。 —你多大了？"}', 10, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17659, 629, '{"english": "-I''m nine years old.  -Are you in Andy''s class?  -Yes.", "chinese": "—我九岁了。 —你在安迪的班级吗？ —是的。"}', 11, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17660, 629, '{"english": "2. -Well, Sue. What do you want for lunch?", "chinese": "2. —苏。你午餐想吃什么？"}', 12, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17661, 629, '{"english": "-I really want cake.  -And what about you, Andy?", "chinese": "—我真的很想吃蛋糕。 —那你呢，安迪？"}', 13, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17662, 629, '{"english": "What do you want?  -I want fish and meat.", "chinese": "你想要什么？ —我想要鱼和肉。"}', 14, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17663, 629, '{"english": "I also want cake. -Well, Sue.", "chinese": "我还想要蛋糕。—苏。"}', 15, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17664, 629, '{"english": "What do you want for lunch?  -I really want cake.", "chinese": "你午餐想吃什么？ —我真的很想吃蛋糕。"}', 16, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
INSERT INTO "course_content" VALUES (17665, 629, '{"english": "-And what about you, Andy? What do you want?", "chinese": "—那你呢，安迪？你想要什么？"}', 17, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
