INSERT INTO "course_content" VALUES (17667, 629, '{"english": "3. -Come on, Andy. Come to help Yaoyao.  -Oh!", "chinese": "3. —来吧，安迪。快来帮瑶瑶。 —哦！"}', 19, '2026-02-05 04:30:19', '2026-02-05 04:30:19');
