INSERT INTO "course_content" VALUES (17997, 638, '{"english": "A. Look, listen and chant.", "chinese": "A. 看一看，听一听，唱一唱。"}', 2, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (17998, 638, '{"english": "Chinese", "chinese": "语文"}', 3, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (17999, 638, '{"english": "English", "chinese": "英语"}', 4, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18000, 638, '{"english": "science", "chinese": "科学"}', 5, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
