INSERT INTO "course_content" VALUES (18002, 638, '{"english": "music", "chinese": "音乐"}', 7, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18003, 638, '{"english": "maths", "chinese": "数学"}', 8, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18004, 638, '{"english": "art", "chinese": "美术"}', 9, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18005, 638, '{"english": "computer class", "chinese": "计算机课"}', 10, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18006, 638, '{"english": "I like Chinese class.  I like English, too.", "chinese": "我喜欢语文。 我也喜欢英语。"}', 11, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18007, 638, '{"english": "I don''t like maths and science.  What about you?   I like computer class.", "chinese": "我不喜欢数学和科学。 那你呢？  我喜欢计算机课。"}', 12, '2026-02-05 04:30:33', '2026-02-05 04:30:33');
INSERT INTO "course_content" VALUES (18008, 638, '{"english": "I like PE, too.  I really like art and music.", "chinese": "我也喜欢体育。 我真的很喜欢美术和音乐。"}', 13, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18009, 638, '{"english": "What about you? (music)  I like Chinese class.", "chinese": "那你呢？（音乐） 我喜欢语文。"}', 14, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18010, 638, '{"english": "I like English, too.  I don''t like maths and science.", "chinese": "我也喜欢英语。 我不喜欢数学和科学。"}', 15, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18011, 638, '{"english": "What about you?   I like computer class.  I like PE, too.", "chinese": "那你呢？  我喜欢计算机课。 我也喜欢体育。"}', 16, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18012, 638, '{"english": "I really like art and music.  What about you?", "chinese": "我真的很喜欢美术和音乐。 那你呢？"}', 17, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18013, 638, '{"english": "B. Ask and answer.", "chinese": "B. 问与答。"}', 18, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18014, 638, '{"english": "Bill, do you like computer class?", "chinese": "比尔，你喜欢计算机课吗？"}', 19, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18015, 638, '{"english": "Yes, I do.", "chinese": "是的，我喜欢。"}', 20, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18016, 638, '{"english": "Do you like art?", "chinese": "你喜欢美术课吗？"}', 21, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18017, 638, '{"english": "No, I don''t.", "chinese": "不，我不喜欢。"}', 22, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18018, 638, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 23, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18019, 638, '{"english": "My name''s Jake.  I make a cake.", "chinese": "我的名字叫杰克。 我做了一个蛋糕。"}', 24, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18020, 638, '{"english": "I put it on a plate  And eat it by the lake.", "chinese": "我把它放在盘子里 并在湖边吃了它。"}', 25, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18021, 638, '{"english": "What can you play?  I play the big drum.", "chinese": "你会玩什么？我打大鼓。"}', 26, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18022, 638, '{"english": "Boom-bi, boom-bi, boom-bi, boom. Boom-bi, boom, boom-bi, boom.", "chinese": "咚，咚，咚，打鼓。咚，打鼓，咚，打鼓。"}', 27, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
INSERT INTO "course_content" VALUES (18023, 638, '{"english": "Boom-bi, boom-bi, boom-bi, boom. Boom-bi, boom-bi, boom.", "chinese": "咚，咚，咚，打鼓。咚，咚，打鼓。"}', 28, '2026-02-05 04:30:34', '2026-02-05 04:30:34');
