INSERT INTO "course_content" VALUES (18042, 639, '{"english": "The art room is here and the classrooms, too.", "chinese": "美术室在这里，教室也在这里。"}', 19, '2026-02-05 04:30:35', '2026-02-05 04:30:35');
INSERT INTO "course_content" VALUES (18043, 639, '{"english": "This is the third floor.  The third floor of my school.", "chinese": "这是三楼。 我学校的三楼。"}', 20, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18044, 639, '{"english": "The music room is here and the teachers'' room,too.", "chinese": "音乐室在这里，老师办公室也在这里。"}', 21, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18045, 639, '{"english": "B. Look and say.", "chinese": "B. 看一看，说一说。"}', 22, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18046, 639, '{"english": "Where is Bill?", "chinese": "比尔在哪里？"}', 23, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18047, 639, '{"english": "He''s in the art room.", "chinese": "他在美术室。"}', 24, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18048, 639, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 25, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18049, 639, '{"english": "The music room is on the second floor.", "chinese": "音乐室在二楼。"}', 26, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
INSERT INTO "course_content" VALUES (18050, 639, '{"english": "Come and follow me.   -Thanks again.  -You''re welcome.", "chinese": "来跟我来。  —再次感谢。 —不客气。"}', 27, '2026-02-05 04:30:36', '2026-02-05 04:30:36');
