INSERT INTO "course_content" VALUES (18057, 640, '{"english": "sing songs", "chinese": "唱歌"}', 7, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18058, 640, '{"english": "read books", "chinese": "读书"}', 8, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18059, 640, '{"english": "I can dance. I can draw pictures, too.  And I can play chess.", "chinese": "我会跳舞。我也会画画。 我会下棋。"}', 9, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18060, 640, '{"english": "I want to play with you.   I can sing songs.", "chinese": "我想和你一起玩。  我会唱歌。"}', 10, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18061, 640, '{"english": "I can read books, too.  And I can play sports.", "chinese": "我也会读书。 我会做运动。"}', 11, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18062, 640, '{"english": "I want to play with you. Come on. Let''s play.", "chinese": "我想和你一起玩。来吧。我们来玩吧。"}', 12, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18063, 640, '{"english": "I want to play with you.  I can dance.", "chinese": "我想和你一起玩。 我会跳舞。"}', 13, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18064, 640, '{"english": "I can draw pictures, too.  And I can play chess.", "chinese": "我也会画画。 我会下棋。"}', 14, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18065, 640, '{"english": "I want to play with you.   I can sing songs.", "chinese": "我想和你一起玩。  我会唱歌。"}', 15, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18066, 640, '{"english": "I can read books, too.  And I can play sports.", "chinese": "我也会读书。 我会做运动。"}', 16, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18067, 640, '{"english": "I want to play with you. Come on.", "chinese": "我想和你一起玩。来吧。"}', 17, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18068, 640, '{"english": "Let''s play.  I want to play with you.", "chinese": "我们来玩吧。 我想和你一起玩。"}', 18, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18069, 640, '{"english": "B. Let''s role-play.", "chinese": "B. 让我们进行角色扮演。"}', 19, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18070, 640, '{"english": "Can you play chess?", "chinese": "你会下棋吗？"}', 20, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18071, 640, '{"english": "Yes, I can.", "chinese": "是的，我会。"}', 21, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18072, 640, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 22, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18073, 640, '{"english": "What are you going to do after school?", "chinese": "放学后你打算做什么？"}', 23, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18074, 640, '{"english": "We are going to play sports.  We are going to play chess.", "chinese": "我们要去运动。 我们要去下棋。"}', 24, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18075, 640, '{"english": "Yes, we are going to have some fun after school.", "chinese": "是的，放学后我们会玩得很开心。"}', 25, '2026-02-05 04:30:37', '2026-02-05 04:30:37');
INSERT INTO "course_content" VALUES (18076, 641, '{"english": "Revision 1", "chinese": "复习 1"}', 1, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18077, 641, '{"english": "Let''s Review", "chinese": "让我们来复习吧"}', 2, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18078, 641, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 3, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18079, 641, '{"english": "It''s Monday today. I am in my new classroom.", "chinese": "今天是星期一。我在我的新教室里。"}', 4, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18080, 641, '{"english": "The classroom is on the second floor.", "chinese": "教室在二楼。"}', 5, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18081, 641, '{"english": "On Tuesday, I am going to have math class.", "chinese": "星期二，我要上数学课。"}', 6, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18082, 641, '{"english": "Math is easy for me. So I''m going to have fun.", "chinese": "数学对我来说很简单。所以我会学得很开心。"}', 7, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18083, 641, '{"english": "On Wednesday, I am going to have science class.", "chinese": "星期三，我要上科学课。"}', 8, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18084, 641, '{"english": "I think science is difficult,but it''s interesting,too.", "chinese": "我认为科学很难，但它也很有趣。"}', 9, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18085, 641, '{"english": "Our school has a really great art room.", "chinese": "我们学校有一间很棒的美术室。"}', 10, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18086, 641, '{"english": "I am going to draw pictures there with my classmates on Thursday.", "chinese": "星期四我要和同学们一起去那里画画。"}', 11, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18087, 641, '{"english": "Those days are good. But my favourite day is Friday.", "chinese": "那些日子很好。但我最喜欢的一天是星期五。"}', 12, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18088, 641, '{"english": "I''m going to go to a singing club after school.", "chinese": "放学后我要去唱歌俱乐部。"}', 13, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18089, 641, '{"english": "I love singing and I love my new school too.", "chinese": "我喜欢唱歌，我也喜欢我的新学校。"}', 14, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18090, 641, '{"english": "B. Let''s play.", "chinese": "B. 让我们玩一玩。"}', 15, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18091, 641, '{"english": "Do you have an art room in your school?", "chinese": "你们学校有美术室吗？"}', 16, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18092, 641, '{"english": "Yes, we do.", "chinese": "是的，我们有。"}', 17, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
