INSERT INTO "course_content" VALUES (18115, 641, '{"english": "Dear friend,", "chinese": "亲爱的朋友："}', 40, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18116, 641, '{"english": "My name is Peter. I am 11 years old.", "chinese": "我叫彼得。我 11 岁了。"}', 41, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18117, 641, '{"english": "I am in grade 3 at Dongfang School.", "chinese": "我在东方学校读三年级。"}', 42, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18118, 641, '{"english": "My favourite subject is science.", "chinese": "我最喜欢的科目是科学。"}', 43, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18119, 641, '{"english": "We have a nice,big science room on the third floor.", "chinese": "我们在三楼有一间漂亮的大科学室。"}', 44, '2026-02-05 04:30:38', '2026-02-05 04:30:38');
INSERT INTO "course_content" VALUES (18120, 641, '{"english": "I like playing basketball. Today, I am going to play after school.", "chinese": "我喜欢打篮球。今天放学后我要去打篮球。"}', 45, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18121, 641, '{"english": "Do you like basketball, too?", "chinese": "你也喜欢篮球吗？"}', 46, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18122, 641, '{"english": "Yours,  Peter", "chinese": "你的朋友， 彼得"}', 47, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18123, 641, '{"english": "Now, write back to Peter.", "chinese": "现在，回信给彼得。"}', 48, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18124, 641, '{"english": "I hope we can be good friends.", "chinese": "我希望我们能成为好朋友。"}', 49, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
