INSERT INTO "course_content" VALUES (18127, 642, '{"english": "cousin", "chinese": "堂（或表）兄弟；堂（或表）姐妹"}', 3, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18128, 642, '{"english": "handsome uncle", "chinese": "英俊的叔叔"}', 4, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18129, 642, '{"english": "beautiful aunt", "chinese": "漂亮的阿姨"}', 5, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18130, 642, '{"english": "grandfather", "chinese": "（外）祖父"}', 6, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18131, 642, '{"english": "grandmother", "chinese": "（外）祖母"}', 7, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18132, 642, '{"english": "father", "chinese": "父亲"}', 8, '2026-02-05 04:30:39', '2026-02-05 04:30:39');
INSERT INTO "course_content" VALUES (18133, 642, '{"english": "mother", "chinese": "母亲"}', 9, '2026-02-05 04:30:40', '2026-02-05 04:30:40');
