INSERT INTO "course_content" VALUES (18230, 645, '{"english": "B. Let''s chant.", "chinese": "B. 让我们唱一唱。"}', 5, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18231, 645, '{"english": "Ake, ake, ake. Cake, cake, cake.  Ive, ive, ive.", "chinese": "Ake，ake，ake。蛋糕，蛋糕，蛋糕。 Ive，ive，ive。"}', 6, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18232, 645, '{"english": "Five, five, five.  Ose, ose, ose.", "chinese": "五，五，五。 Ose，ose，ose。"}', 7, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18233, 645, '{"english": "Nose, nose, nose.  Une, une, une. June, June, June.", "chinese": "鼻子，鼻子，鼻子。 Une，une，une。六月，六月，六月。"}', 8, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18234, 645, '{"english": "Now, make your own chants with a_e, i_e, o_e and u_e.", "chinese": "现在，用 a_e、i_e、o_e 和 u_e 创作自己的歌曲吧。"}', 9, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18235, 645, '{"english": "C. Listen and write.", "chinese": "C. 听一听，写一写。"}', 10, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18236, 645, '{"english": "snake", "chinese": "蛇"}', 11, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18237, 645, '{"english": "cage", "chinese": "笼子"}', 12, '2026-02-05 04:30:44', '2026-02-05 04:30:44');
INSERT INTO "course_content" VALUES (18238, 646, '{"english": "I like Chinese class.  I like English, too.", "chinese": "我喜欢语文课。 我也喜欢英语课。"}', 1, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18239, 646, '{"english": "I don''t like maths and science.  What about you?", "chinese": "我不喜欢数学和科学。 你呢？"}', 2, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18240, 646, '{"english": "I like computer class.  I like PE, too.", "chinese": "我喜欢计算机课。 我也喜欢体育课。"}', 3, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18241, 646, '{"english": "I really like art and music.  What about you?", "chinese": "我真的很喜欢美术和音乐。 你呢？"}', 4, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18242, 646, '{"english": "I''m a music man.  I come from far away,  And I can play.", "chinese": "我是一个音乐人。 我来自很远的地方， 我会弹奏乐器。"}', 5, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18243, 646, '{"english": "What can you play?  I play the piano.  Pia, pia, piano, piano, piano.", "chinese": "你会弹奏什么乐器？ 我会弹钢琴。 Pia, pia, 钢琴，钢琴，钢琴。"}', 6, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18244, 646, '{"english": "Pia, pia, piano, pia, piano.  I''m a music man.", "chinese": "Pia, pia, 钢琴，pia, 钢琴。 我是一个音乐人。"}', 7, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18245, 646, '{"english": "I come from far away,  And I can play.", "chinese": "我来自很远的地方， 我会弹奏乐器。"}', 8, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18246, 646, '{"english": "What can you play?  I play the big drum.", "chinese": "你会弹奏什么乐器？ 我会敲大鼓。"}', 9, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18247, 646, '{"english": "Boombi, boombi, boombi, boom.  Boombi, boom, boombi, boom.", "chinese": "砰，砰，砰，砰。 砰，砰，砰，砰。"}', 10, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18248, 646, '{"english": "Boombi, boombi, boombi, boom.  Boombi, boombi, boom.", "chinese": "砰，砰，砰，砰。 砰，砰，砰，砰。"}', 11, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18249, 646, '{"english": "This is the first floor,The first floor of my school.", "chinese": "这是一楼，我们学校的一楼。"}', 12, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18250, 646, '{"english": "The library is here,And the toilets, too.", "chinese": "图书馆在这里，厕所也在这里。"}', 13, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18251, 646, '{"english": "This is the second floor,The second floor of my school.", "chinese": "这是二楼，我们学校的二楼。"}', 14, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18252, 646, '{"english": "The art room is here,And the classrooms, too.", "chinese": "美术室在这里，教室也在这里。"}', 15, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18253, 646, '{"english": "This is the third floor,The third floor of my school.", "chinese": "这是三楼，我们学校的三楼。"}', 16, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18254, 646, '{"english": "The music room is here,And the teachers'' room,too.", "chinese": "音乐教室在这里，老师办公室也在这里。"}', 17, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18255, 646, '{"english": "-Hello,I''m new here. Can you help me find my classroom.", "chinese": "—你好，我是新来的。你能帮我找到教室吗？"}', 18, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18256, 646, '{"english": "-Sure I can, That''s no problem.", "chinese": "—当然可以。没问题。"}', 19, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18257, 646, '{"english": "Your new classroom is on the first floor,on the first floor,on the first floor.", "chinese": "你的新教室在一楼，在一楼，在一楼。"}', 20, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18258, 646, '{"english": "Your new classroom is on the first floor.", "chinese": "你的新教室在一楼。"}', 21, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18259, 646, '{"english": "Come and follow me. -Thank you. I have a music class now.", "chinese": "跟我来。—非常感谢。我现在上音乐课。"}', 22, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18260, 646, '{"english": "Can you tell me where the music classroom is?", "chinese": "你能告诉我音乐教室在哪里吗？"}', 23, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18261, 646, '{"english": "-Of course, I can.", "chinese": "—当然可以。"}', 24, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18262, 646, '{"english": "The music room is on the second floor,on the second floor,on the second floor.", "chinese": "音乐教室在二楼，在二楼，在二楼。"}', 25, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18263, 646, '{"english": "The music room is on the second floor.", "chinese": "音乐教室在二楼。"}', 26, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18264, 646, '{"english": "Come and follow me. -Thanks again. -You''re welcome.", "chinese": "跟我来。—再次感谢。—不客气。"}', 27, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18265, 646, '{"english": "I can dance.  I can draw pictures, too.  And I can play chess.", "chinese": "我会跳舞。 我也会画画。 我会下棋。"}', 28, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18266, 646, '{"english": "I want to play with you.   I can sing songs.", "chinese": "我想和你玩。  我会唱歌。"}', 29, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18267, 646, '{"english": "I can read books, too,  And I can play sports.", "chinese": "我也会阅读。 我会做运动。"}', 30, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18268, 646, '{"english": "I want to play with you.   Come on!", "chinese": "我想和你一起玩。  快来！"}', 31, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18269, 646, '{"english": "Let''s play!  I want to play with you.", "chinese": "我们来玩吧！ 我想和你一起玩。"}', 32, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18270, 646, '{"english": "What are you going to do after school?", "chinese": "你们放学后打算干什么？"}', 33, '2026-02-05 04:30:45', '2026-02-05 04:30:45');
INSERT INTO "course_content" VALUES (18271, 646, '{"english": "What are you going to do after school?", "chinese": "你们放学后打算干什么？"}', 34, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18272, 646, '{"english": "We are going to sing songs.  We are going to read books.", "chinese": "我们打算唱歌。 我们打算看书。"}', 35, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18273, 646, '{"english": "Yes, we''re going to have some fun after school.", "chinese": "是的，我们放学后有很多乐趣。"}', 36, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18274, 646, '{"english": "What are you going to do after school?", "chinese": "你们放学后打算干什么？"}', 37, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18275, 646, '{"english": "What are you going to do after school?", "chinese": "你们放学后打算干什么？"}', 38, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18276, 646, '{"english": "We are going to play sports.  We are going to play chess.", "chinese": "我们打算做运动。 我们打算下棋。"}', 39, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18277, 646, '{"english": "Yes, we''re going to have some fun after school.", "chinese": "是的，我们放学后有很多乐趣。"}', 40, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18278, 646, '{"english": "Who is she?  Who is he?", "chinese": "她是谁？ 他是谁？"}', 41, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18279, 646, '{"english": "She''s my mother,  He''s my father,  And they love me.", "chinese": "她是我的母亲， 他是我的父亲， 并且他们都爱我。"}', 42, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18280, 646, '{"english": "Who is she?  Who is he?", "chinese": "她是谁？ 他是谁？"}', 43, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18281, 646, '{"english": "She''s my aunt,  He''s my uncle,  And they love me.", "chinese": "她是我的阿姨， 他是我的叔叔， 并且他们都爱我。"}', 44, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18282, 646, '{"english": "Who are we?   Who are we?  We are together.  We are together.  We''re a family.", "chinese": "我们是谁？  我们是谁？ 我们在一起。 我们在一起。 我们是一家人。"}', 45, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18283, 646, '{"english": "How many people are there in your family?", "chinese": "你家里有多少人？"}', 46, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18284, 646, '{"english": "There''s my mum, dad and sister.  She''s small and pretty.", "chinese": "有我的妈妈，爸爸和妹妹。 她很小很漂亮。"}', 47, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18285, 646, '{"english": "There''s also my auntie and my uncle, too.", "chinese": "还有我的阿姨和叔叔。"}', 48, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18286, 646, '{"english": "He''s big, tall and handsome.  Yes, it''s really true.", "chinese": "他很高大很英俊。 是的，这真的是事实。"}', 49, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18287, 646, '{"english": "And last, there''s my grandma and, yes, my grandpa.", "chinese": "最后，有我的奶奶和爷爷。"}', 50, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18288, 646, '{"english": "My grandma has short hair,  And my grandpa''s hair''s mad!", "chinese": "我的奶奶留着短发， 我爷爷的头发一团糟！"}', 51, '2026-02-05 04:30:46', '2026-02-05 04:30:46');
INSERT INTO "course_content" VALUES (18289, 647, '{"english": "Stick your family photo here!", "chinese": "把你的全家福贴在这里！"}', 1, '2026-02-05 04:30:47', '2026-02-05 04:30:47');
INSERT INTO "course_content" VALUES (18290, 647, '{"english": "Stick a photo of your home here!", "chinese": "在这里贴一张你家的照片！"}', 2, '2026-02-05 04:30:47', '2026-02-05 04:30:47');
INSERT INTO "course_content" VALUES (18291, 647, '{"english": "He/She is (doing) ...", "chinese": "他/她正在（做）⋯⋯"}', 3, '2026-02-05 04:30:47', '2026-02-05 04:30:47');
INSERT INTO "course_content" VALUES (18292, 647, '{"english": "My ... is in the ...", "chinese": "我的⋯⋯在⋯⋯里面。"}', 4, '2026-02-05 04:30:47', '2026-02-05 04:30:47');
