INSERT INTO "course_content" VALUES (18472, 652, '{"english": "How do you go to the shops?", "chinese": "你怎么去商店？"}', 32, '2026-02-05 04:30:55', '2026-02-05 04:30:55');
INSERT INTO "course_content" VALUES (18473, 652, '{"english": "Oh, how do you go to the shops?", "chinese": "哦，你怎么去商店？"}', 33, '2026-02-05 04:30:55', '2026-02-05 04:30:55');
