INSERT INTO "course_content" VALUES (18479, 653, '{"english": "1. -Hi, Sally. Do you often play basketball?", "chinese": "1. —嗨，莎莉。你经常打篮球吗？"}', 4, '2026-02-05 04:30:56', '2026-02-05 04:30:56');
