INSERT INTO "course_content" VALUES (18481, 653, '{"english": "I''m good at jumping rope. -Hi, Sally.", "chinese": "我擅长跳绳。—嗨，莎莉。"}', 6, '2026-02-05 04:30:56', '2026-02-05 04:30:56');
INSERT INTO "course_content" VALUES (18482, 653, '{"english": "Do you often play basketball?  -No, I don''t like basketball.", "chinese": "你经常打篮球吗？ —不，我不喜欢篮球。"}', 7, '2026-02-05 04:30:56', '2026-02-05 04:30:56');
