INSERT INTO "course_content" VALUES (18489, 653, '{"english": "What do you do on the weekend?  -I like sports.", "chinese": "你周末做什么？ —我喜欢运动。"}', 14, '2026-02-05 04:30:56', '2026-02-05 04:30:56');
INSERT INTO "course_content" VALUES (18490, 653, '{"english": "So I often do sports on the weekend.", "chinese": "所以我经常在周末做运动。"}', 15, '2026-02-05 04:30:56', '2026-02-05 04:30:56');
