INSERT INTO "course_content" VALUES (18500, 653, '{"english": "I''m good at drawing.", "chinese": "我擅长画画。"}', 25, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18501, 653, '{"english": "-How do you go to the drawing club?", "chinese": "—你怎么去绘画俱乐部？"}', 26, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
