INSERT INTO "course_content" VALUES (18505, 653, '{"english": "-What''s your favourite sport?  -Football. -Hello, Tony.", "chinese": "—你最喜欢的运动是什么？ —足球。—你好，托尼。"}', 30, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
