INSERT INTO "course_content" VALUES (18510, 653, '{"english": "1. Do you like ...?", "chinese": "1. 你喜欢⋯⋯吗？"}', 35, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18511, 653, '{"english": "2. What do you do on the weekend?", "chinese": "2. 你周末做什么？"}', 36, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18512, 653, '{"english": "3. Are you good at ...?", "chinese": "3. 你擅长⋯⋯吗？"}', 37, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18513, 653, '{"english": "4. How do you go to ...?", "chinese": "4. 你怎么去⋯⋯？"}', 38, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18514, 653, '{"english": "C. Read and write.", "chinese": "C. 读一读，写一写。"}', 39, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18515, 653, '{"english": "Dear pen pal,", "chinese": "亲爱的笔友，"}', 40, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18516, 653, '{"english": "My name is Jack. I am from the USA.", "chinese": "我叫杰克。我来自美国。"}', 41, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18517, 653, '{"english": "I am nine years old.", "chinese": "我九岁了。"}', 42, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18518, 653, '{"english": "I like basketball, and I am good at it.", "chinese": "我喜欢篮球，而且我很擅长打篮球。"}', 43, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18519, 653, '{"english": "I often play basketball with my friends on the weekend.", "chinese": "周末我经常和朋友们一起打篮球。"}', 44, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18520, 653, '{"english": "It is fun. I also like ping-pong, but I can''t play it well.", "chinese": "这很有趣。我也喜欢打乒乓球，但我打得不好."}', 45, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18521, 653, '{"english": "I am going to China with my parents by plane next month.", "chinese": "下个月我要和父母乘飞机去中国了。"}', 46, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18522, 653, '{"english": "I am happy and excited.", "chinese": "我很高兴也很兴奋。"}', 47, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18523, 653, '{"english": "I want to make new friends there.", "chinese": "我想在那里交到新朋友。"}', 48, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18524, 653, '{"english": "I also want to learn to play ping-pong.", "chinese": "我也想学打乒乓球。"}', 49, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18525, 653, '{"english": "Can you play ping-pong? Are you good at it?", "chinese": "你会打乒乓球吗？你擅长吗？"}', 50, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18526, 653, '{"english": "Yours, Jack", "chinese": "你的（朋友）， 杰克"}', 51, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
INSERT INTO "course_content" VALUES (18527, 653, '{"english": "jump rope", "chinese": "跳绳"}', 52, '2026-02-05 04:30:57', '2026-02-05 04:30:57');
