INSERT INTO "course_content" VALUES (18574, 655, '{"english": "My leg hurts. I can''t walk.", "chinese": "我的腿受伤了。我不能走路了。"}', 13, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18575, 655, '{"english": "Are you OK?", "chinese": "你还好吗？"}', 14, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18576, 655, '{"english": "Call 120.", "chinese": "打 120。"}', 15, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18577, 655, '{"english": "Oh, I am having a bad day!", "chinese": "哦，真是糟糕的一天！"}', 16, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18578, 655, '{"english": "We are taking you to the hospital.", "chinese": "我们带你去医院。"}', 17, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18579, 655, '{"english": "Oh, dear! I am having a bad day!", "chinese": "哦，亲爱的！真是糟糕的一天！"}', 18, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18580, 655, '{"english": "You have a broken leg.", "chinese": "你的腿断了。"}', 19, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
INSERT INTO "course_content" VALUES (18581, 655, '{"english": "Please use the sidewalk next time.", "chinese": "下次请走人行道。"}', 20, '2026-02-05 04:31:00', '2026-02-05 04:31:00');
