INSERT INTO "course_content" VALUES (18598, 656, '{"english": "It''s an interesting job. Hello, I''m Alex.", "chinese": "它是个有趣的工作。你好，我是亚历克斯。"}', 16, '2026-02-05 04:31:01', '2026-02-05 04:31:01');
