INSERT INTO "course_content" VALUES (18604, 657, '{"english": "1. -Hi, Kate. Can I use your dictionary?", "chinese": "1.—嗨，凯特。我能用一下你的字典吗？"}', 4, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
INSERT INTO "course_content" VALUES (18605, 657, '{"english": "I''m reading a story, I don''t know this word.", "chinese": "我在读一个故事，我不知道这个词。"}', 5, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
INSERT INTO "course_content" VALUES (18606, 657, '{"english": "-Sure. Here you are.", "chinese": "—当然。给你。"}', 6, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
