INSERT INTO "course_content" VALUES (18608, 657, '{"english": "-What colour do you want?  -I want red.", "chinese": "—你想要什么颜色的？ —我想要红色的。"}', 8, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
INSERT INTO "course_content" VALUES (18609, 657, '{"english": "I''m drawing some flowers.  -Sorry, I don''t have a red one.", "chinese": "我正在画一些花。 —对不起，我没有红色的。"}', 9, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
INSERT INTO "course_content" VALUES (18610, 657, '{"english": "3. -Don''t run down the stairs, Amy.", "chinese": "3.—艾米，不要跑下楼梯。"}', 10, '2026-02-05 04:31:02', '2026-02-05 04:31:02');
