INSERT INTO "course_content" VALUES (18616, 657, '{"english": "This is Ann. She likes delicious food.", "chinese": "这是安。她喜欢吃美味的食物。"}', 16, '2026-02-05 04:31:03', '2026-02-05 04:31:03');
