INSERT INTO "course_content" VALUES (18964, 666, '{"english": "B. Ask and answer.", "chinese": "B. 问一问，答一答。"}', 8, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18965, 666, '{"english": "What do you do in your free time, Lily?", "chinese": "你在空闲时间做什么，莉莉？"}', 9, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18966, 666, '{"english": "I often go skating.", "chinese": "我经常去滑冰。"}', 10, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18967, 666, '{"english": "What do you do in your free time, Andy?", "chinese": "你在空闲时间做什么呢，安迪？"}', 11, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18968, 666, '{"english": "I often ...", "chinese": "我经常⋯⋯"}', 12, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18969, 666, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 13, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18970, 666, '{"english": "go skating", "chinese": "去滑冰"}', 14, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18971, 666, '{"english": "It is fun.", "chinese": "编织很有趣。"}', 15, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18972, 666, '{"english": "B. Let''s make.", "chinese": "B. 让我们做一做。"}', 16, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18973, 666, '{"english": "C. Let''s sing.   I go to bed once a day.", "chinese": "C. 让我们唱一唱。  我每天睡觉一次。"}', 17, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
INSERT INTO "course_content" VALUES (18974, 666, '{"english": "Can you help Lu Qi make an exercise plan?", "chinese": "你能帮陆奇制定一个锻炼计划吗？"}', 18, '2026-02-05 04:31:17', '2026-02-05 04:31:17');
