INSERT INTO "course_content" VALUES (18976, 667, '{"english": "A. Look, listen and repeat.", "chinese": "A. 看一看，听一听并跟读。"}', 2, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18977, 667, '{"english": "Welcome to China!", "chinese": "欢迎来到中国！"}', 3, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18978, 667, '{"english": "Canada", "chinese": "加拿大"}', 4, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18979, 667, '{"english": "Australia", "chinese": "澳大利亚"}', 5, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18980, 667, '{"english": "the UK", "chinese": "英国"}', 6, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18981, 667, '{"english": "the USA", "chinese": "美国"}', 7, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18982, 667, '{"english": "China", "chinese": "中国"}', 8, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18983, 667, '{"english": "B. Let''s role-play.", "chinese": "B. 角色扮演。"}', 9, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18984, 667, '{"english": "Where are you from?", "chinese": "你来自哪里？"}', 10, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18985, 667, '{"english": "I''m from the USA. You can visit Disneyland in my country.", "chinese": "我来自美国。你可以到我的国家参观迪斯尼乐园。"}', 11, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18986, 667, '{"english": "C. Listen and write.", "chinese": "C. 听一听，写一写。"}', 12, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18987, 667, '{"english": "I have some new friends. Peter is tall.", "chinese": "我有一些新朋友。彼得很高。"}', 13, '2026-02-05 04:31:18', '2026-02-05 04:31:18');
INSERT INTO "course_content" VALUES (18988, 667, '{"english": "He likes skateboarding. He is from the UK.", "chinese": "他喜欢玩滑板。他来自英国。"}', 14, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18989, 667, '{"english": "You can visit Big Ben in his country. Grace likes reading.", "chinese": "你可以去他的国家参观大本钟。格雷丝喜欢读书。"}', 15, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18990, 667, '{"english": "They sleep during the day,", "chinese": "它们在白天睡觉，"}', 16, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18991, 667, '{"english": "but at night they get up and eat leaves.", "chinese": "但是在晚上起来吃树叶。"}', 17, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18992, 667, '{"english": "B. Let''s make.", "chinese": "B. 让我们做一做。"}', 18, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18993, 667, '{"english": "C. Let''s sing.   Hello, my friend! Where are you from?", "chinese": "C. 让我们唱一唱。  你好，我的朋友！你来自哪里？"}', 19, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18994, 667, '{"english": "Oh, I am from the city of Beijing.", "chinese": "哦，我来自北京市。"}', 20, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18995, 667, '{"english": "What is Beijing famous for?", "chinese": "北京以什么闻名？"}', 21, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18996, 667, '{"english": "It''s famous for the Great Wall.   Hello, my friend!", "chinese": "它以长城而闻名。  你好，我的朋友！"}', 22, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18997, 667, '{"english": "Where are you from?", "chinese": "你来自哪里？"}', 23, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18998, 667, '{"english": "Oh, I am from the city of London.", "chinese": "哦，我来自伦敦市。"}', 24, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (18999, 668, '{"english": "Revision 2", "chinese": "复习 2"}', 1, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19000, 668, '{"english": "Let''s Review", "chinese": "复习一下"}', 2, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19001, 668, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 3, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19002, 668, '{"english": "1. My name is Lin Tao. I like doing jigsaw puzzles.", "chinese": "1. 我叫林涛。我喜欢玩拼图游戏。"}', 4, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19003, 668, '{"english": "I do jigsaw puzzles once a week.", "chinese": "我每周玩一次拼图游戏。"}', 5, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19004, 668, '{"english": "2. I''m Lanlan and I like playing the violin.", "chinese": "2. 我是兰兰，我喜欢拉小提琴。"}', 6, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19005, 668, '{"english": "I play it twice a week.", "chinese": "我一周拉两次小提琴。"}', 7, '2026-02-05 04:31:19', '2026-02-05 04:31:19');
INSERT INTO "course_content" VALUES (19006, 668, '{"english": "3. I''m Jiajia. I like dancing. I learn to dance everyday.", "chinese": "3. 我是佳佳。我喜欢跳舞。我每天都学跳舞。"}', 8, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19007, 668, '{"english": "4. My name is Lucas. I like skateboarding.", "chinese": "4. 我叫卢卡斯。我喜欢玩滑板。"}', 9, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19008, 668, '{"english": "I do it three times a week.", "chinese": "我一周玩三次滑板。"}', 10, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19009, 668, '{"english": "5.My name is Kevin. I like going for picnics.", "chinese": "5.我叫凯文。我喜欢去野餐。"}', 11, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19010, 668, '{"english": "I go with my family once a week.", "chinese": "我每周和家人一起去野餐一次。"}', 12, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19011, 668, '{"english": "6.I am Irene. I like doing housework with my mom. I do it every day.", "chinese": "6.我是艾琳。我喜欢和妈妈一起做家务。我每天都做家务。"}', 13, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19012, 668, '{"english": "B. Play and talk.", "chinese": "B. 玩一玩，说一说。"}', 14, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19013, 668, '{"english": "I''m Bill. I''m from China.", "chinese": "我是比尔。我来自中国。"}', 15, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19014, 668, '{"english": "You can visit the Great Wall in my country.", "chinese": "在我的国家里你可以参观长城。"}', 16, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19015, 668, '{"english": "C. Read and write.", "chinese": "C. 读一读，写一写。"}', 17, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19016, 668, '{"english": "Dear campers,  Thank you for joining our summer camp.", "chinese": "亲爱的露营者们， 感谢你们参加我们的夏令营。"}', 18, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19017, 668, '{"english": "We''re planning some activities for you.", "chinese": "我们正在为你们计划一些活动。"}', 19, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19018, 668, '{"english": "Please answer the following questions by email.", "chinese": "请通过电子邮件回答以下问题。"}', 20, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19019, 668, '{"english": "1. What are your hobbies?", "chinese": "1. 你的爱好是什么？"}', 21, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19020, 668, '{"english": "2. How often do you do them?", "chinese": "2. 你多久做一次（你的爱好）？"}', 22, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19021, 668, '{"english": "Please write down your names and where you are from.", "chinese": "请写下你的名字和你来自哪里。"}', 23, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19022, 668, '{"english": "Thank you! Ms James", "chinese": "谢谢！ 詹姆斯女士"}', 24, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19023, 668, '{"english": "Read some campers'' answers and help Ms James fill out the form.", "chinese": "阅读一些露营者们的答案，并帮助詹姆斯女士填写表格。"}', 25, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19024, 668, '{"english": "I am Dick from the USA.", "chinese": "我是来自美国的迪克。"}', 26, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19025, 668, '{"english": "I read books every day. I also like visiting museums.", "chinese": "我每天都看书。我也喜欢参观博物馆。"}', 27, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19026, 668, '{"english": "I go to the museums in my city once a week.", "chinese": "我每周去一次我所在城市的博物馆。"}', 28, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19027, 669, '{"english": "Excuse me. Can you please help me?", "chinese": "打扰一下。你能帮帮我吗？"}', 1, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19028, 669, '{"english": "How can I get to the bank?  Go straight. Turn right.", "chinese": "我怎么去银行？ 直走。右转。"}', 2, '2026-02-05 04:31:20', '2026-02-05 04:31:20');
INSERT INTO "course_content" VALUES (19029, 669, '{"english": "It''s on your left.  That''s how you get to the bank!", "chinese": "它就在你的左边。 你这样就可以到银行！"}', 3, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19030, 669, '{"english": "Excuse me. Can you please help me?", "chinese": "打扰一下。你能帮帮我吗？"}', 4, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19031, 669, '{"english": "How can I get to the grocery?  Go straight. Turn left.", "chinese": "我怎么去杂货店？ 直走。左转。"}', 5, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19032, 669, '{"english": "It''s on your right.  That''s how you get to the grocery!", "chinese": "它就在你的右边。 你这样就可以去杂货店！"}', 6, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19033, 669, '{"english": "Excuse me. Can you please help me?  How can I get to the post office?", "chinese": "打扰一下。你能帮帮我吗？ 去邮局怎么走？"}', 7, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19034, 669, '{"english": "I''m sorry.  I''m sorry.", "chinese": "我很抱歉。 我很抱歉。"}', 8, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19035, 669, '{"english": "I cannot help you.", "chinese": "我帮不了你。"}', 9, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19036, 669, '{"english": "I want to see a film.", "chinese": "我想看一部电影。"}', 10, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19037, 669, '{"english": "Do you want to see one, too?", "chinese": "你也想看一部吗？"}', 11, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19038, 669, '{"english": "The cinema is on King Street.  I want to go with you.", "chinese": "电影院在国王街。 我想和你一起去。"}', 12, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19039, 669, '{"english": "I want to buy some toys.  Do you want to buy some, too?", "chinese": "我想买一些玩具。 你也想买一些吗？"}', 13, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19040, 669, '{"english": "The toy shop is on King Street.", "chinese": "玩具店在国王街。"}', 14, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19041, 669, '{"english": "I want to go with you.   I want to row a boat.", "chinese": "我想和你一起去。  我想去划船。"}', 15, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19042, 669, '{"english": "Do you want to do that, too?", "chinese": "你也想划船吗？"}', 16, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19043, 669, '{"english": "The park is on King Street.", "chinese": "公园在国王街。"}', 17, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19044, 669, '{"english": "I want to visit the Great Wall,  I want some Beijing duck,  I want to take some photos,  So let''s go to Beijing.   I want to eat some seafood,  I want to swim in the sea,  I want to see the sunrise,  So let''s go to Sanya.", "chinese": "我想去游览长城， 我想吃北京烤鸭， 我想拍一些照片， 所以我们去北京吧。  我想吃海鲜， 我想在海里游泳， 我想看日出， 所以我们去三亚吧。"}', 18, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19045, 669, '{"english": "I like listening to music. And I like playing computer games.", "chinese": "我喜欢听音乐，我喜欢玩电脑游戏。"}', 19, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19046, 669, '{"english": "These are my favourite hobbies.  Are they your hobbies, too?", "chinese": "这些是我最喜欢的爱好。 它们也是你的爱好吗？"}', 20, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19047, 669, '{"english": "I like reading stories. And I like collecting stamps.", "chinese": "我喜欢读故事。我喜欢集邮。"}', 21, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19048, 669, '{"english": "These are my favourite hobbies.  Are they your hobbies, too?", "chinese": "这些是我最喜欢的爱好。 它们也是你的爱好吗？"}', 22, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19049, 669, '{"english": "I go to bed once a day.", "chinese": "我每天睡觉一次。"}', 23, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19050, 670, '{"english": "Unit 1", "chinese": "第 1 单元"}', 1, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19051, 670, '{"english": "across from", "chinese": "在对面"}', 2, '2026-02-05 04:31:21', '2026-02-05 04:31:21');
INSERT INTO "course_content" VALUES (19052, 670, '{"english": "next to", "chinese": "紧邻"}', 3, '2026-02-05 04:31:22', '2026-02-05 04:31:22');
