INSERT INTO "course_content" VALUES (19132, 672, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19133, 672, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 2, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19134, 672, '{"english": "-Look at these pictures, these are my new friends.", "chinese": "—看这些照片，这些是我的新朋友。"}', 3, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19135, 672, '{"english": "-Who is she?  -Her name is Helen. She likes reading.", "chinese": "—她是谁？ —她的名字叫海伦。她喜欢读书。"}', 4, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19136, 672, '{"english": "She is polite and quiet.  -Who is he?  -He is Peter.", "chinese": "她很有礼貌，很安静。 —他是谁？ —他是彼得。"}', 5, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19137, 672, '{"english": "He is very popular in our school. He likes playing basketball.", "chinese": "他在我们学校很受欢迎。他喜欢打篮球。"}', 6, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19138, 672, '{"english": "And he is active in class and in our sining club, too.", "chinese": "他在班上很活跃，在我们的唱歌俱乐部也很活跃。"}', 7, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19139, 672, '{"english": "-That girl looks very friendly.  -That''s Mary.", "chinese": "—那个女孩看起来很友好。 —那是玛丽。"}', 8, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19140, 672, '{"english": "Yes, she is always friendly and very helpful.", "chinese": "是的，她总是很友好，很乐于助人。"}', 9, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19141, 672, '{"english": "Her hobby is dancing.  -Wow, that dog is so cute!", "chinese": "她的爱好是跳舞。 —哇，那只狗真可爱！"}', 10, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19142, 672, '{"english": "-That''s Tom''s dog. Tom is clever and good at maths.", "chinese": "—那是汤姆的狗。汤姆很聪明，数学也很好。"}', 11, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19143, 672, '{"english": "But sometimes he is careless and he forgets to feed his dog.", "chinese": "但有时他很粗心，他忘记了去喂狗。"}', 12, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19144, 672, '{"english": "-Oh, the poor dog.", "chinese": "—哦，可怜的狗。"}', 13, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19145, 672, '{"english": "B. Think and say.", "chinese": "B. 想一想，说一说。"}', 14, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19146, 672, '{"english": "Let''s talk about our classmates.", "chinese": "让我们谈谈我们的同学。"}', 15, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19147, 672, '{"english": "Lily is cute.", "chinese": "莉莉很可爱。"}', 16, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19148, 672, '{"english": "And she''s friendly, too.", "chinese": "并且她也很友好。"}', 17, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19149, 672, '{"english": "name", "chinese": "姓名"}', 18, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19150, 672, '{"english": "Lily", "chinese": "莉莉"}', 19, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19151, 672, '{"english": "clever", "chinese": "聪明的"}', 20, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19152, 672, '{"english": "careless", "chinese": "粗心的"}', 21, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19153, 672, '{"english": "quiet", "chinese": "安静的"}', 22, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19154, 672, '{"english": "friendly", "chinese": "友好的"}', 23, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19155, 672, '{"english": "popular", "chinese": "受欢迎的"}', 24, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19156, 672, '{"english": "active", "chinese": "活跃的"}', 25, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19157, 672, '{"english": "polite", "chinese": "有礼貌的"}', 26, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19158, 672, '{"english": "cute", "chinese": "可爱的"}', 27, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19159, 672, '{"english": "helpful", "chinese": "乐于助人的"}', 28, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19160, 672, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 29, '2026-02-05 04:31:26', '2026-02-05 04:31:26');
INSERT INTO "course_content" VALUES (19161, 672, '{"english": "Peter", "chinese": "彼得"}', 30, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19162, 672, '{"english": "active", "chinese": "活跃的"}', 31, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19163, 672, '{"english": "tall", "chinese": "高的"}', 32, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19164, 672, '{"english": "big hands", "chinese": "大手"}', 33, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19165, 672, '{"english": "long arms", "chinese": "长胳膊"}', 34, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19166, 672, '{"english": "popular", "chinese": "受欢迎的"}', 35, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19167, 672, '{"english": "What''s your friend like?", "chinese": "你朋友是什么样的人？"}', 36, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19168, 672, '{"english": "He''s active and popular. He''s tall.", "chinese": "他很活跃并且很受欢迎。他个子很高。"}', 37, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19169, 672, '{"english": "He has long arms and big hands.", "chinese": "他有长长的胳膊和一双大手。"}', 38, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19170, 672, '{"english": "Is he Peter?", "chinese": "他是彼得吗？"}', 39, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19171, 672, '{"english": "Yes, he is.", "chinese": "是的。"}', 40, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19172, 672, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 41, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19173, 672, '{"english": "What is Peter like?", "chinese": "彼得是怎样的人？"}', 42, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19174, 672, '{"english": "careless", "chinese": "粗心的"}', 43, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19175, 672, '{"english": "polite", "chinese": "有礼貌的"}', 44, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19176, 672, '{"english": "quiet", "chinese": "安静的"}', 45, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19177, 672, '{"english": "cute", "chinese": "可爱的"}', 46, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19178, 672, '{"english": "friendly", "chinese": "友好的"}', 47, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19179, 672, '{"english": "helpful", "chinese": "乐于助人的"}', 48, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19180, 672, '{"english": "active", "chinese": "活跃的"}', 49, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19181, 672, '{"english": "popular", "chinese": "受欢迎的"}', 50, '2026-02-05 04:31:27', '2026-02-05 04:31:27');
INSERT INTO "course_content" VALUES (19182, 673, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19183, 673, '{"english": "A. Look, listen and number.", "chinese": "A. 看一看，听一听，并标上序号。"}', 2, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19184, 673, '{"english": "B. Describe and guess.", "chinese": "B. 描述并猜一猜。"}', 3, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19185, 673, '{"english": "These are pictures of my teachers.", "chinese": "这些是我老师的照片。"}', 4, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19186, 673, '{"english": "This is my English teacher. She is slim and pretty.", "chinese": "这是我的英语老师。她很苗条，很漂亮。"}', 5, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19187, 673, '{"english": "She has big eyes and long, curly hair.", "chinese": "她有一双大眼睛和一头长长的卷发。"}', 6, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19188, 673, '{"english": "She is a very good teacher. And she''s very helpful.", "chinese": "她是一位很好的老师。她还很乐于助人。"}', 7, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19189, 673, '{"english": "She is my favourite teacher.  Mr Wang is our PE teacher.", "chinese": "她是我最喜欢的老师。 王老师是我们的体育老师。"}', 8, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19190, 673, '{"english": "He is very young and I think he is very nice.", "chinese": "他很年轻，我认为他很好。"}', 9, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19191, 673, '{"english": "He can play basketball very well. We often play together.", "chinese": "他篮球打得很好。我们经常一起玩。"}', 10, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19192, 673, '{"english": "This is my maths teacher. He is young and tall.", "chinese": "这是我的数学老师。他又年轻又高。"}', 11, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19193, 673, '{"english": "He wears glasses. He''s quite clever. He always tells us many interesting things.", "chinese": "他戴着眼镜。他很聪明。他总是告诉我们许多有趣的事情。"}', 12, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19194, 673, '{"english": "This is my Chinese teacher. She has short, straight hair.", "chinese": "这是我的语文老师。她有一头短而直的头发。"}', 13, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19195, 673, '{"english": "She is short. She likes reading very much.", "chinese": "她很矮。她非常喜欢读书。"}', 14, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19196, 673, '{"english": "And she helps us a lot with our lessons.", "chinese": "她在功课上帮了我们很多。"}', 15, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19197, 673, '{"english": "She''s my favourite teacher. Who is she? Guess!", "chinese": "她是我最喜欢的老师。她是谁？猜猜看！"}', 16, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19198, 673, '{"english": "What''s she like?", "chinese": "她人怎么样？"}', 17, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19199, 673, '{"english": "She''s nice. She''s slim.", "chinese": "她人很好。她很苗条。"}', 18, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19200, 673, '{"english": "She has long curly hair. She''s young.", "chinese": "她有一头长长的卷发。她很年轻。"}', 19, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19201, 673, '{"english": "Is she our English teacher?", "chinese": "她是我们的英语老师吗？"}', 20, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19202, 673, '{"english": "Yes, she is. She''s Mrs Wu.", "chinese": "是的。她是吴老师。"}', 21, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19203, 673, '{"english": "C. Look and write.", "chinese": "C. 看一看，写一写。"}', 22, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19204, 673, '{"english": "He teaches music. He''s Mr Zhu, my music teacher.", "chinese": "他教音乐。他是朱老师，我的音乐老师。"}', 23, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19205, 673, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 24, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19206, 673, '{"english": "What does Mr Zhu teach?", "chinese": "朱老师教什么？"}', 25, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19207, 673, '{"english": "Draw your favourite teacher here.", "chinese": "在这里画上你最喜欢的老师。"}', 26, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19208, 673, '{"english": "Mr White", "chinese": "怀特老师"}', 27, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19209, 673, '{"english": "Mrs Smith", "chinese": "史密斯老师"}', 28, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19210, 673, '{"english": "English", "chinese": "英语"}', 29, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19211, 673, '{"english": "small eyes, short hair", "chinese": "小眼睛，短发"}', 30, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19212, 673, '{"english": "drawing animals", "chinese": "画动物"}', 31, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19213, 673, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 32, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19214, 673, '{"english": "Choose your favourite teacher from Part A. Then talk about him or her like this:", "chinese": "从 A 部分中选出你最喜欢的老师。然后像这样谈论他或她："}', 33, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19215, 673, '{"english": "Who''s your favourite teacher?", "chinese": "你最喜欢的老师是谁？"}', 34, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19216, 673, '{"english": "Mr White is my favourite teacher.", "chinese": "怀特老师是我最喜欢的老师。"}', 35, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19217, 673, '{"english": "What does he teach?", "chinese": "他教什么？"}', 36, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19218, 673, '{"english": "He teaches art.", "chinese": "他教美术。"}', 37, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19219, 673, '{"english": "What''s he like?", "chinese": "他长什么样？"}', 38, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19220, 673, '{"english": "He''s not very tall, but he''s handsome.", "chinese": "他个子不高，但很帅。"}', 39, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19221, 673, '{"english": "He has short brown hair. He wears glasses. Who''s your favourite teacher?", "chinese": "他有一头棕色短发。他戴眼镜。你最喜欢的老师是谁？"}', 40, '2026-02-05 04:31:28', '2026-02-05 04:31:28');
INSERT INTO "course_content" VALUES (19222, 673, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 41, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19223, 673, '{"english": "Who is your favourite teacher in your school?", "chinese": "你在你们学校最喜欢的老师是谁？"}', 42, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19224, 673, '{"english": "Write a letter to Tim and tell him something about your favourite teacher.", "chinese": "给蒂姆写封信，告诉他一些关于你最喜欢的老师的事情。"}', 43, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19225, 673, '{"english": "character", "chinese": "性格"}', 44, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19226, 673, '{"english": "kind, funny", "chinese": "善良的，有趣的"}', 45, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19227, 673, '{"english": "C. Let''s talk.", "chinese": "C. 让我们来说一说。"}', 46, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19228, 673, '{"english": "Who is Albert''s favourite teacher and why?", "chinese": "艾伯特最喜欢的老师是谁？为什么？"}', 47, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19229, 673, '{"english": "Who is your favourite teacher and why?", "chinese": "你最喜欢的老师是谁？为什么？"}', 48, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19230, 673, '{"english": "My Favourite Teacher", "chinese": "我最喜欢的老师"}', 49, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19231, 673, '{"english": "What''s his/her name?", "chinese": "他/她叫什么名字？"}', 50, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19232, 673, '{"english": "What does he/she look like?", "chinese": "他/她长什么样？"}', 51, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19233, 673, '{"english": "What''s he/she like?", "chinese": "他/她人怎么样？"}', 52, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19234, 673, '{"english": "What are his/her hobbies?", "chinese": "他/她有什么爱好？"}', 53, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19235, 673, '{"english": "What does he/she teach?", "chinese": "他/她教什么？"}', 54, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19236, 673, '{"english": "D. Write about your favourite teacher.", "chinese": "D. 写一写你最喜欢的老师。"}', 55, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
