INSERT INTO "course_content" VALUES (19238, 673, '{"english": "structures", "chinese": "结构"}', 57, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19239, 673, '{"english": "What does he/she teach?", "chinese": "他/她教什么？"}', 58, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
INSERT INTO "course_content" VALUES (19240, 673, '{"english": "He/She teaches ...", "chinese": "他/她教⋯⋯"}', 59, '2026-02-05 04:31:29', '2026-02-05 04:31:29');
