INSERT INTO "course_content" VALUES (19242, 673, '{"english": "wear glasses", "chinese": "戴眼镜"}', 61, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19243, 673, '{"english": "slim", "chinese": "苗条的"}', 62, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19244, 673, '{"english": "curly", "chinese": "卷曲的"}', 63, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19245, 673, '{"english": "straight", "chinese": "直的"}', 64, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19246, 673, '{"english": "nice", "chinese": "好的"}', 65, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19247, 673, '{"english": "young", "chinese": "年轻的"}', 66, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19248, 673, '{"english": "teach", "chinese": "教"}', 67, '2026-02-05 04:31:30', '2026-02-05 04:31:30');
INSERT INTO "course_content" VALUES (19249, 674, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19250, 674, '{"english": "A. Listen and number.", "chinese": "A. 听一听，标上序号。"}', 2, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19251, 674, '{"english": "I am Yaoyao. Tomorrow is Saturday.", "chinese": "我是瑶瑶。明天是星期六。"}', 3, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19252, 674, '{"english": "I''m going to the zoo with Binbin.", "chinese": "我要和彬彬一起去动物园。"}', 4, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19253, 674, '{"english": "Pandas are my favourite animals. They''re cute animals. They''re black and white.", "chinese": "熊猫是我最喜欢的动物。它们是可爱的动物。它们是黑白相间的。"}', 5, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19254, 674, '{"english": "They''re my favourite animals. I want to see them tomorrow.", "chinese": "它们是我最喜欢的动物。我想明天见他们。"}', 6, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19255, 674, '{"english": "Binbin likes elephant. They are so big and tall.", "chinese": "彬彬喜欢大象。它们又大又高。"}', 7, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19256, 674, '{"english": "Binbin wants to feed them.   I am Joy.", "chinese": "彬彬想喂它们。  我是乔伊。"}', 8, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19257, 674, '{"english": "I''m going to the farm with Andy and Linda tomorrow.", "chinese": "明天我要和安迪和琳达一起去农场。"}', 9, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19258, 674, '{"english": "We want to see some farm animals.", "chinese": "我们想看一些农场动物。"}', 10, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19259, 674, '{"english": "I want to see how people get the milk from the cow.", "chinese": "我想看看人们是如何从奶牛那里得到牛奶的。"}', 11, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19260, 674, '{"english": "And I want to ride a fast horse, too.", "chinese": "我也想骑一匹快的马。"}', 12, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19261, 674, '{"english": "Linda wants to see how people raise bees.", "chinese": "琳达想看看人们是如何养蜂的。"}', 13, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19262, 674, '{"english": "Andy wants to feed the big fat pigs and see the soft white sheep on the farm.", "chinese": "安迪想去喂农场里的大肥猪和柔软的、白色绵羊。"}', 14, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19263, 674, '{"english": "B. Let''s play.", "chinese": "B. 让我们来玩吧。"}', 15, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19264, 674, '{"english": "We''re going to the zoo.", "chinese": "我们要去动物园。"}', 16, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19265, 674, '{"english": "What animals do you want to see? Why?", "chinese": "你们想看什么动物？为什么？"}', 17, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19266, 674, '{"english": "I want to see pandas. They''re cute.", "chinese": "我想看熊猫。它们很可爱。"}', 18, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19267, 674, '{"english": "I want to see elephants. They''re big and tall.", "chinese": "我想看大象。它们又大又高。"}', 19, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19268, 674, '{"english": "I want to see their long noses.", "chinese": "我想看看它们的长鼻子。"}', 20, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19269, 674, '{"english": "I want to see tigers. They''re big.", "chinese": "我想看老虎。它们很大。"}', 21, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
INSERT INTO "course_content" VALUES (19270, 674, '{"english": "C. Let''s write.", "chinese": "C. 让我们来写一写。"}', 22, '2026-02-05 04:31:31', '2026-02-05 04:31:31');
