INSERT INTO "course_content" VALUES (19307, 675, '{"english": "Mary, Peter, Sally and Sam are classmates.", "chinese": "玛丽、彼得、萨利和萨姆是同学。"}', 4, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19308, 675, '{"english": "They go to school together every day. They''re at the bus station now.", "chinese": "他们每天一起上学。他们现在在公共汽车站。"}', 5, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19309, 675, '{"english": "Mary is tall and slim. She has straight hair.", "chinese": "玛丽又高又瘦。她有一头直发。"}', 6, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19310, 675, '{"english": "She is very helpful. She is helping an old lady.", "chinese": "她很乐于助人。她正在帮助一位老太太。"}', 7, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19311, 675, '{"english": "Peter has short hair. He is careless, but he is friendly.", "chinese": "彼得有一头短发。他很粗心，但很友好。"}', 8, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19312, 675, '{"english": "Sally is a cute girl. She is quiet and young.", "chinese": "莎莉是个可爱的女孩。她安静，很年轻。"}', 9, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19313, 675, '{"english": "She has curly hair and wears glasses. Sam is a big boy.", "chinese": "她留着卷发，戴着眼镜。萨姆是个大男孩。"}', 10, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19314, 675, '{"english": "He has big eyes. He is active and likes sports.", "chinese": "他有一双大眼睛。他很活跃，喜欢运动。"}', 11, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
INSERT INTO "course_content" VALUES (19315, 675, '{"english": "He is playing with a ball now.", "chinese": "他现在正在玩球。"}', 12, '2026-02-05 04:31:33', '2026-02-05 04:31:33');
