INSERT INTO "course_content" VALUES (19373, 676, '{"english": "Today we have some blue, pink and yellow exercise books.", "chinese": "今天我们有一些蓝色、粉色和黄色的练习本。"}', 4, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19374, 676, '{"english": "Only five yuan just for today. Do you want a new pencil sharpener?", "chinese": "今天只要五元钱。你想要一个新的卷笔刀吗？"}', 5, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19375, 676, '{"english": "We have some red pencil sharpeners. Only nine yuan for one.", "chinese": "我们有一些红色的卷笔刀。一个只要九元。"}', 6, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19376, 676, '{"english": "And do you want a new pencil box to put your pencil shapeners and pencils in?", "chinese": "你想要一个新的铅笔盒来装你的铅笔成型器和铅笔吗？"}', 7, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19377, 676, '{"english": "We have pencil boxes in different colours.", "chinese": "我们有不同颜色的铅笔盒。"}', 8, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19378, 676, '{"english": "And only twenty yuan for each one.", "chinese": "而且每个只要二十元。"}', 9, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19379, 676, '{"english": "Do you want new crayons or scissors?", "chinese": "你想要新蜡笔还是剪刀？"}', 10, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19380, 676, '{"english": "A box of crayons is only ten yuan.", "chinese": "一盒蜡笔只要十元。"}', 11, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19381, 676, '{"english": "A pair of scissors is only seven yuan. Come in and have a look!", "chinese": "一把剪刀只有七元。进来看看吧！"}', 12, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19382, 676, '{"english": "B. Let''s role-play.", "chinese": "B. 让我们角色扮演。"}', 13, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19383, 676, '{"english": "Xinxin Stationery shop", "chinese": "欣欣文具店"}', 14, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19384, 676, '{"english": "I want to buy a box of crayons.", "chinese": "我想买一盒蜡笔。"}', 15, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19385, 676, '{"english": "It''s 16 yuan.", "chinese": "16 元。"}', 16, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19386, 676, '{"english": "I want to buy an eraser.", "chinese": "我想买一块橡皮。"}', 17, '2026-02-05 04:31:35', '2026-02-05 04:31:35');
INSERT INTO "course_content" VALUES (19387, 676, '{"english": "It''s 2 yuan.", "chinese": "2 元。"}', 18, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19388, 676, '{"english": "Welcome to Xinxin. We have a nice green pencil box.", "chinese": "欢迎来到欣欣文具店。我们有一个漂亮的绿色铅笔盒。"}', 19, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19389, 676, '{"english": "It''s only 20 yuan.", "chinese": "只要 20 元。"}', 20, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19390, 676, '{"english": "We also have ...", "chinese": "我们还有⋯⋯"}', 21, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19391, 676, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 22, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19392, 676, '{"english": "Fill in the blanks according to Part A.", "chinese": "根据 A 部分内容进行填空。"}', 23, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19393, 676, '{"english": "3. Write down the total price.", "chinese": "3. 写下总价。"}', 24, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19394, 676, '{"english": "Total Price", "chinese": "总价"}', 25, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19395, 676, '{"english": "B. Ask and write.", "chinese": "B. 问一问，写一写。"}', 26, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19396, 676, '{"english": "How much is the sweater?", "chinese": "这件毛衣多少钱？"}', 27, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19397, 676, '{"english": "It''s 80 yuan.", "chinese": "80 元。"}', 28, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19398, 676, '{"english": "How much ...?", "chinese": "多少钱⋯⋯？"}', 29, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19399, 676, '{"english": "It''s ...", "chinese": "它⋯⋯"}', 30, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19400, 676, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 31, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19401, 676, '{"english": "Complete the sentences according to Part B.", "chinese": "根据 B 部分内容完成句子。"}', 32, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19402, 676, '{"english": "1. How much is the cap?", "chinese": "1. 这顶帽子多少钱？"}', 33, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19403, 676, '{"english": "It''s 40 yuan.", "chinese": "它是 40 元。"}', 34, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19404, 676, '{"english": "3. How much is the sweater?", "chinese": "3. 这件毛衣多少钱？"}', 35, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19405, 676, '{"english": "4. How much are the pants?", "chinese": "4. 这件短裤多少钱？"}', 36, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19406, 676, '{"english": "How much, oh, how much,  How much will these things all cost me?", "chinese": "多少钱，哦，多少钱， 全部这些东西要花我多少钱？"}', 37, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19407, 676, '{"english": "How much, oh, how much,  How much will these things all cost me?", "chinese": "多少钱，哦，多少钱， 全部这些东西要花我多少钱？"}', 38, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19408, 676, '{"english": "vocabulary", "chinese": "词汇"}', 39, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19409, 676, '{"english": "exercise book", "chinese": "练习本"}', 40, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19410, 676, '{"english": "pencil sharpener", "chinese": "卷笔刀"}', 41, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19411, 676, '{"english": "a pair of scissors", "chinese": "一把剪刀"}', 42, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19412, 676, '{"english": "pencil box", "chinese": "铅笔盒"}', 43, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19413, 676, '{"english": "a box of crayons", "chinese": "一盒蜡笔"}', 44, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19414, 676, '{"english": "please", "chinese": "拜托"}', 45, '2026-02-05 04:31:36', '2026-02-05 04:31:36');
INSERT INTO "course_content" VALUES (19415, 677, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19416, 677, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 2, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19417, 677, '{"english": "Hello, I am Lily. My family and I enjoy watching TV.", "chinese": "你好，我是莉莉。我和我的家人都喜欢看电视。"}', 3, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19418, 677, '{"english": "I like cartoons best. They are very funny.", "chinese": "我最喜欢卡通片。他们很有趣。"}', 4, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19419, 677, '{"english": "I watch cartoons three times a week. My grandfather''s favourite show is the news.", "chinese": "我每周看三次卡通片。我祖父最喜欢的节目是新闻。"}', 5, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19420, 677, '{"english": "He watches it every day in the morning.", "chinese": "他每天早上都看。"}', 6, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19421, 677, '{"english": "My grandmother is a music teacher, her favourite TV shows are music shows.", "chinese": "我的祖母是一位音乐老师，她最喜欢的电视节目是音乐节目。"}', 7, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19422, 677, '{"english": "She enjoys listening to beautiful songs.", "chinese": "她喜欢听优美的歌曲。"}', 8, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19423, 677, '{"english": "My dad likes sports, so he really likes watching sports shows.", "chinese": "我爸爸喜欢运动，所以他真的很喜欢看体育节目。"}', 9, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19424, 677, '{"english": "His favourtie sport is football. He watches sports in the evening.", "chinese": "他最喜欢的运动是足球。他晚上看体育比赛。"}', 10, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19425, 677, '{"english": "My mother likes nature shows best.", "chinese": "我妈妈最喜欢自然节目。"}', 11, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19426, 677, '{"english": "She can learn about animals all over the world.", "chinese": "她可以了解世界各地的动物。"}', 12, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19427, 677, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 13, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19428, 677, '{"english": "What are your favourite TV shows?", "chinese": "你最喜欢的电视节目是什么？"}', 14, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19429, 677, '{"english": "My favourite TV shows are music shows. They''re great.", "chinese": "我最喜欢的电视节目是音乐节目。它们很棒。"}', 15, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19430, 677, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 16, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19431, 677, '{"english": "I usually watch them on Tuesday evening.", "chinese": "我通常在星期二晚上看。"}', 17, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19432, 677, '{"english": "content", "chinese": "内容"}', 18, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19433, 677, '{"english": "their feelings", "chinese": "他们的感受"}', 19, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19434, 677, '{"english": "Jane", "chinese": "简"}', 20, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19435, 677, '{"english": "Mack", "chinese": "麦克"}', 21, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19436, 677, '{"english": "I watch children''s shows on Tuesday and Sunday.", "chinese": "我在星期二和星期天看儿童节目。"}', 22, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19437, 677, '{"english": "Well, children''s shows are on at 9:10 today.", "chinese": "今天 9 点 10 分有儿童节目。"}', 23, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19438, 677, '{"english": "We can watch them together.", "chinese": "我们可以一起看。"}', 24, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19439, 677, '{"english": "question", "chinese": "问题"}', 25, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19440, 677, '{"english": "Sandy''s favourite TV shows", "chinese": "桑迪最喜欢的电视节目"}', 26, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19441, 677, '{"english": "Joy''s favourite TV shows", "chinese": "乔伊最喜欢的电视节目"}', 27, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19442, 677, '{"english": "What?", "chinese": "什么？"}', 28, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19443, 677, '{"english": "When?", "chinese": "什么时候？"}', 29, '2026-02-05 04:31:37', '2026-02-05 04:31:37');
INSERT INTO "course_content" VALUES (19444, 677, '{"english": "C. Interview.", "chinese": "C. 采访。"}', 30, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19445, 677, '{"english": "Hi! I''m Yang Tao from Xinxin Primary School.", "chinese": "嗨！我是欣欣小学的杨涛。"}', 31, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19446, 677, '{"english": "May I ask you some questions?", "chinese": "我可以问你一些问题吗？"}', 32, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19447, 677, '{"english": "Sure.", "chinese": "当然。"}', 33, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19448, 677, '{"english": "What''s your name?", "chinese": "你叫什么名字？"}', 34, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19449, 677, '{"english": "I''m Linda.", "chinese": "我叫琳达。"}', 35, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19450, 678, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19451, 678, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 2, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19452, 678, '{"english": "-Hi, Lily. Are you free after school?", "chinese": "—嗨，莉莉。放学后你有空吗？"}', 3, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19453, 678, '{"english": "Can we play computer games together?  -Sorry, I can''t play with you today.", "chinese": "我们能一起玩电脑游戏吗？ —对不起，我今天不能和你一起玩。"}', 4, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19454, 678, '{"english": "My mother is busy with her work.", "chinese": "我妈妈正忙于她的工作。"}', 5, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19455, 678, '{"english": "I''m going to help her at home.", "chinese": "我打算在家里帮助她。"}', 6, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19456, 678, '{"english": "I''m going to wash clothes and sweep the floor.", "chinese": "我要洗衣服和扫地。"}', 7, '2026-02-05 04:31:38', '2026-02-05 04:31:38');
INSERT INTO "course_content" VALUES (19457, 678, '{"english": "-What about you, Bill? Can you play with me?  -No, I can''t.", "chinese": "—比尔，你呢？你能和我一起玩吗？ —不，我不能。"}', 8, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19458, 678, '{"english": "I''m going to tidy my desk and clean my room.", "chinese": "我要整理我的桌子，打扫我的房间。"}', 9, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19459, 678, '{"english": "Do you do chores at home, Andy?", "chinese": "安迪，你在家做家务吗？"}', 10, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19460, 678, '{"english": "-Yes. I help my parents take out the rubbish and make the bed.", "chinese": "—是的，我帮父母倒垃圾和整理床铺。"}', 11, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19461, 678, '{"english": "Can we play together this weekend?  -Sure, that''s great!", "chinese": "这个周末我们能一起玩吗？—当然，太好了！"}', 12, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19462, 678, '{"english": "B. Think and say.", "chinese": "B. 想一想，说一说。"}', 13, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19463, 678, '{"english": "Do you help your parents do chores at home?", "chinese": "你在家帮父母做家务吗？"}', 14, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19464, 678, '{"english": "OK. Bye.", "chinese": "好的。再见。"}', 15, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19465, 678, '{"english": "Bye.", "chinese": "再见。"}', 16, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19466, 678, '{"english": "3. Now read the dialogue and write.", "chinese": "3. 现在读对话并写一写。"}', 17, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19467, 678, '{"english": "What chores does Bill do at home?", "chinese": "比尔在家做什么家务？"}', 18, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19468, 678, '{"english": "Write B for Bill.", "chinese": "写 B 代表比尔。"}', 19, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19469, 678, '{"english": "What chores does Joy do at home?", "chinese": "乔伊在家做什么家务？"}', 20, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19470, 678, '{"english": "This is the way we clean the room,so early in the morning.", "chinese": "大清早我们就是这样打扫房间的。"}', 21, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19471, 678, '{"english": "Now I''m going to go camping with my classmates.", "chinese": "现在我要和同学们去野营了。"}', 22, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19472, 678, '{"english": "Thanks, Tom", "chinese": "谢谢你，汤姆"}', 23, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19473, 678, '{"english": "Dad,  Please help me do the chores for Mum.", "chinese": "爸爸， 请帮我为妈妈做些家务。"}', 24, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19474, 678, '{"english": "Please wash the clothes, take out the rubbish and sweep the floor.", "chinese": "请洗衣服、倒垃圾、扫地。"}', 25, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19475, 678, '{"english": "Also please water the plants, too.", "chinese": "也请给植物浇水。"}', 26, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19476, 678, '{"english": "I am going to walk the dog now.  Thanks!  Kathy", "chinese": "我现在要去遛狗了。 谢谢！ 凯西"}', 27, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19477, 678, '{"english": "What chores didn''t Tom and Kathy do?", "chinese": "汤姆和凯西没有做什么家务？"}', 28, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19478, 678, '{"english": "sweep the floor", "chinese": "扫地"}', 29, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19479, 678, '{"english": "take out the rubbish", "chinese": "倒垃圾"}', 30, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19480, 678, '{"english": "wash the clothes", "chinese": "洗衣服"}', 31, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19481, 678, '{"english": "clean the bedroom", "chinese": "打扫卧室"}', 32, '2026-02-05 04:31:39', '2026-02-05 04:31:39');
INSERT INTO "course_content" VALUES (19482, 679, '{"english": "Revision 2", "chinese": "复习 2"}', 1, '2026-02-05 04:31:40', '2026-02-05 04:31:40');
INSERT INTO "course_content" VALUES (19483, 679, '{"english": "Let''s Review", "chinese": "让我们复习一下"}', 2, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19484, 679, '{"english": "A. Listen and circle.", "chinese": "A. 听一听，圈一圈。"}', 3, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19485, 679, '{"english": "Dialogue 1. -What do you need for school?", "chinese": "对话 1.—你上学需要什么？"}', 4, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19486, 679, '{"english": "-I need an exercise book and a box of crayons.", "chinese": "—我需要一本练习本和一盒蜡笔。"}', 5, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19487, 679, '{"english": "-Do you need a pencil sharpener?", "chinese": "—你需要卷笔刀吗？"}', 6, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19488, 679, '{"english": "It''s only ten yuan.  -Sure. Let''s buy one.", "chinese": "只有十元。 —当然。我们买一个吧。"}', 7, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19489, 679, '{"english": "Dialogue 2. -I like that pair of purple trousers.", "chinese": "对话 2.—我喜欢那条紫色的裤子。"}', 8, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19490, 679, '{"english": "What do you think, Mum?  -It''s great! How much is it?", "chinese": "妈妈，你觉得怎么样？ —太好了！多少钱？"}', 9, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19491, 679, '{"english": "-I don''t know.  -Can I help you?  -Yes.", "chinese": "—我不知道。 —我能帮你吗？ —是的。"}', 10, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19492, 679, '{"english": "How much is that pair of purple trousers?", "chinese": "那条紫色的裤子多少钱？"}', 11, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19493, 679, '{"english": "-It''s eighty yuan.  -Do you like the green sweater?", "chinese": "—八十元。 —你喜欢这件绿色毛衣吗？"}', 12, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19494, 679, '{"english": "-Yes. I like the colour.", "chinese": "—是的。我喜欢这种颜色。"}', 13, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19495, 679, '{"english": "I also like the blue coat.  -OK. We''ll take them all.", "chinese": "我也喜欢这件蓝色的外套。 —好的。我们都要了。"}', 14, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19496, 679, '{"english": "B. Read and fill in the chart.", "chinese": "B. 读一读，并填写表格。"}', 15, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19497, 679, '{"english": "I''d like to make some TV shows for our school.", "chinese": "我想为我们学校做一些电视节目。"}', 16, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19498, 679, '{"english": "That''s a great idea!", "chinese": "这是一个很棒的想法！"}', 17, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19499, 679, '{"english": "I like game shows.", "chinese": "我喜欢游戏节目。"}', 18, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19500, 679, '{"english": "Let''s do a game show. They''re fun.", "chinese": "让我们做一档游戏节目吧。它们很有趣。"}', 19, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19501, 679, '{"english": "Let''s do a talk show, too.", "chinese": "让我们也做一档脱口秀吧。"}', 20, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19502, 679, '{"english": "I''d like to be the host of the talk show.", "chinese": "我想成为脱口秀的主持人。"}', 21, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19503, 679, '{"english": "Really? Let''s do a news show.", "chinese": "真的吗？让我们做一档新闻节目。"}', 22, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19504, 679, '{"english": "I want to be a news announcer. That is an exciting job.", "chinese": "我想做一名新闻播音员。这是一项令人兴奋的工作。"}', 23, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19505, 679, '{"english": "I''d like to put on a quiz show.", "chinese": "我想做一档智力竞赛节目，"}', 24, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19506, 679, '{"english": "It''s very exciting. I want to be on a quiz show.", "chinese": "这很令人兴奋。我想上智力竞赛节目。"}', 25, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19507, 679, '{"english": "Lily, what do you want to do?", "chinese": "莉莉，你想做什么？"}', 26, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19508, 679, '{"english": "Let''s do a nature show.", "chinese": "让我们做一档自然节目。"}', 27, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19509, 679, '{"english": "I really like to see animals.", "chinese": "我真的很喜欢看动物。"}', 28, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19510, 679, '{"english": "name", "chinese": "名字"}', 29, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19511, 679, '{"english": "Bill", "chinese": "比尔"}', 30, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19512, 679, '{"english": "Andy", "chinese": "安迪"}', 31, '2026-02-05 04:31:41', '2026-02-05 04:31:41');
INSERT INTO "course_content" VALUES (19513, 680, '{"english": "Make new friends,  But keep the old.", "chinese": "交新朋友， 但和老朋友保持联系。"}', 1, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19514, 680, '{"english": "Some are popular, and some are cute.  Make new friends,  But keep the old.", "chinese": "有些是受欢迎的，有些是可爱的。 交新朋友， 但和老朋友保持联系。"}', 2, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19515, 680, '{"english": "Some are clever, and some are helpful.  Make new friends,  But keep the old.", "chinese": "有些是聪明的，有些是乐于助人的。 交新朋友， 但和老朋友保持联系。"}', 3, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19516, 680, '{"english": "Some are polite, and some are friendly.  Make new friends,  But keep the old.", "chinese": "有些是礼貌的，有些是友好的。 交新朋友， 但和老朋友保持联系。"}', 4, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19517, 680, '{"english": "Some are quiet, and some are active.  Make new friends,  But keep the old.", "chinese": "有些是安静的，有些是活泼好动的。 交新朋友， 但和老朋友保持联系。"}', 5, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19518, 680, '{"english": "Some are popular, and some are cute.  Make new friends,  But keep the old.", "chinese": "有些是受欢迎的，有些是可爱的。 交新朋友， 但和老朋友保持联系。"}', 6, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19519, 680, '{"english": "Some are clever, and some are helpful.  Make new friends,  But keep the old.", "chinese": "有些是聪明的，有些是乐于助人的。 交新朋友， 但和老朋友保持联系。"}', 7, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19520, 680, '{"english": "Some are polite, and some are friendly.  Make new friends,  But keep the old.", "chinese": "有些是礼貌的，有些是友好的。 交新朋友， 但和老朋友保持联系。"}', 8, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19521, 680, '{"english": "Some are quiet, and some are active.", "chinese": "有些是安静的，有些是活泼好动的。"}', 9, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19522, 680, '{"english": "He''s my teacher. His hair is short,  And he wears cool glasses, too.", "chinese": "他是我的老师。他的头发很短， 他也戴着一副很酷的眼镜。"}', 10, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19523, 680, '{"english": "He teaches Chinese to us.  He teaches me and you.", "chinese": "他教我们语文。 他教我和你。"}', 11, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19524, 680, '{"english": "She''s my teacher. She is young,  And she has pretty, curly hair.", "chinese": "她是我的老师。她很年轻， 她有一头漂亮的卷发。"}', 12, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19525, 680, '{"english": "She teaches English to us.", "chinese": "她教我们英语。"}', 13, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19526, 680, '{"english": "She teaches us with care.   They''re my teachers.", "chinese": "她细心地教我们。  他们是我的老师。"}', 14, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19527, 680, '{"english": "They are kind,  And they''re very nice as well.", "chinese": "他们很善良， 并且他们也很好。"}', 15, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19528, 680, '{"english": "They teach us many things.", "chinese": "他们教我们很多东西。"}', 16, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19529, 680, '{"english": "They teach us very well. He''s my teacher.", "chinese": "他们教得很好。他是我的老师。"}', 17, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19530, 680, '{"english": "His hair is short, And he wears cool glasses, too.", "chinese": "他的头发好短，他也戴着一副很酷的眼镜。"}', 18, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19531, 680, '{"english": "He teaches Chinese to us. He teaches me and you.", "chinese": "他教我们语文。他教我和你。"}', 19, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19532, 680, '{"english": "She''s my teacher. She is young, And she has pretty, curly hair.", "chinese": "她是我的老师。她很年轻，她有一头漂亮的卷发。"}', 20, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19533, 680, '{"english": "She teaches English to us. She teacher us with care.", "chinese": "她教我们英语。她细心地教我们。"}', 21, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19534, 680, '{"english": "They''re my teachers. They are kind,  And they''re very nice as well.", "chinese": "他们是我的老师。他们很善良， 并且他们也很好。"}', 22, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19535, 680, '{"english": "They teach us many things.  They teach us very well.", "chinese": "他们教我们很多东西。 他们教得很好。"}', 23, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19536, 680, '{"english": "Ali Ba-ba, he has a little farm.", "chinese": "阿里巴巴，他有一个小农场。"}', 24, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19537, 680, '{"english": "On his farm he has some little lambs.", "chinese": "他的农场里有一些小羊羔。"}', 25, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19538, 680, '{"english": "''Baa, Baa,'' cry his little lambs,  On the farm of Ali Ba-ba.", "chinese": "“咩，咩，”他的小羊羔喊着， 在阿里巴巴的农场里。"}', 26, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19539, 680, '{"english": "Ali Ba-ba, he has a little farm.", "chinese": "阿里巴巴，他有一个小农场。"}', 27, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19540, 680, '{"english": "On his farm he has some little cows.", "chinese": "他的农场里有一些小牛。"}', 28, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
INSERT INTO "course_content" VALUES (19541, 680, '{"english": "''Moo, Moo,'' cry his little cows,  On the farm of Ali Ba-ba.", "chinese": "“哞，哞，”他的小牛叫着， 在阿里巴巴的农场里。"}', 29, '2026-02-05 04:31:42', '2026-02-05 04:31:42');
