INSERT INTO "course_content" VALUES (19553, 680, '{"english": "How much is that pencil in the window?", "chinese": "橱窗里的那支铅笔多少钱？"}', 41, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19554, 680, '{"english": "A dollar is all it will be.", "chinese": "一美元就够了。"}', 42, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19555, 680, '{"english": "A pencil is missing from my schoolbag.", "chinese": "我的书包里少了一根铅笔。"}', 43, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19556, 680, '{"english": "A pencil is all that I need.", "chinese": "我只需要一根铅笔。"}', 44, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19557, 680, '{"english": "How much, oh, how much,  How much will these things all cost me?", "chinese": "多少钱，哦，多少钱， 全部这些东西要花我多少钱？"}', 45, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19558, 680, '{"english": "How much, oh, how much,  How much will these things all cost me?", "chinese": "多少钱，哦，多少钱， 全部这些东西要花我多少钱？"}', 46, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19559, 680, '{"english": "How much is that eraser in the window?", "chinese": "橱窗里的橡皮多少钱？"}', 47, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
INSERT INTO "course_content" VALUES (19560, 680, '{"english": "Two dollars is all it will be.", "chinese": "两美元就够了。"}', 48, '2026-02-05 04:31:43', '2026-02-05 04:31:43');
