INSERT INTO "course_content" VALUES (19638, 683, '{"english": "Keeping Healthy", "chinese": "保持健康"}', 2, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19639, 683, '{"english": "Get ready.", "chinese": "准备一下。"}', 3, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19640, 683, '{"english": "What should/shouldn''t you do?", "chinese": "你应该做/不应该做什么？"}', 4, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19641, 683, '{"english": "eat too much candy", "chinese": "吃太多的糖果"}', 5, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19642, 683, '{"english": "eat too much meat", "chinese": "吃太多的肉"}', 6, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19643, 683, '{"english": "go to bed early", "chinese": "早点睡觉"}', 7, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19644, 683, '{"english": "exercise every day", "chinese": "每天锻炼"}', 8, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19645, 683, '{"english": "tired", "chinese": "疲倦的"}', 9, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19646, 683, '{"english": "drink milk every day", "chinese": "每天喝牛奶"}', 10, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19647, 683, '{"english": "drink too much juice", "chinese": "喝太多果汁"}', 11, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19648, 683, '{"english": "wash hands before eating", "chinese": "饭前洗手"}', 12, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19649, 683, '{"english": "eat with dirty hands", "chinese": "用脏手吃东西"}', 13, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19650, 683, '{"english": "Please do your homework, Bill.", "chinese": "请做你的家庭作业，比尔。"}', 14, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19651, 683, '{"english": "Sorry, Mum. I''m tired.", "chinese": "对不起，妈妈。我累了。"}', 15, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19652, 683, '{"english": "Your are always tired.", "chinese": "你总是很累。"}', 16, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19653, 683, '{"english": "You should exercise every day and go to bed early.", "chinese": "你应该每天锻炼并且早点睡觉。"}', 17, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19654, 683, '{"english": "It''s not good for our teeth.", "chinese": "这对我们的牙齿不好。"}', 18, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19655, 683, '{"english": "You should drink lots of water and some milk every day.", "chinese": "你应该每天喝大量的水和一些牛奶。"}', 19, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19656, 683, '{"english": "4. -It''s lunchtime, Miss Wu.", "chinese": "4. —午饭时间到了，吴老师。"}', 20, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19657, 683, '{"english": "Can we eat our lunch now?  -Sure.", "chinese": "我们现在能吃午饭了吗？ —当然。"}', 21, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19658, 683, '{"english": "But you shouldn''t eat with dirty hands.", "chinese": "但是你不应该用脏手吃饭。"}', 22, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19659, 683, '{"english": "Please wash your hands before eating.", "chinese": "请吃饭前洗手。"}', 23, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19660, 683, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 24, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19661, 683, '{"english": "Candy!", "chinese": "糖果！"}', 25, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19662, 683, '{"english": "We shouldn''t eat too much candy.", "chinese": "我们不应该吃太多糖果。"}', 26, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19663, 683, '{"english": "Fruit!", "chinese": "水果！"}', 27, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19664, 683, '{"english": "We should eat a lot of fruit.", "chinese": "我们应该吃很多水果。"}', 28, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19665, 683, '{"english": "C. Think and write.", "chinese": "C. 想一想，写一写。"}', 29, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19666, 683, '{"english": "I''ve got a headache.", "chinese": "我头痛。"}', 30, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19667, 683, '{"english": "I''ve got a toothache.", "chinese": "我牙痛。"}', 31, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19668, 683, '{"english": "I''m tired.", "chinese": "我累了。"}', 32, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19669, 683, '{"english": "C. Think and write.", "chinese": "C. 想一想，写一写。"}', 33, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19670, 683, '{"english": "What''s wrong?", "chinese": "你怎么了？"}', 34, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19671, 683, '{"english": "I am tired. What should I do?", "chinese": "我累了。我该怎么办？"}', 35, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19672, 683, '{"english": "Jack likes to eat a lot of meat, but he doesn''t like vegetables.", "chinese": "杰克喜欢吃很多肉，但他不喜欢蔬菜。"}', 36, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19673, 683, '{"english": "He doesn''t like sports either.", "chinese": "他也不喜欢运动。"}', 37, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19674, 683, '{"english": "Now he is a little fat.", "chinese": "现在他有点胖了。"}', 38, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19675, 683, '{"english": "Andy likes candy very much. He often eats ice cream.", "chinese": "安迪非常喜欢糖果。他经常吃冰激凌。"}', 39, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19676, 683, '{"english": "Now he has a bad toothache.", "chinese": "现在他牙痛得厉害。"}', 40, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19677, 683, '{"english": "He shouldn''t eat too much candy and ice cream.", "chinese": "他不应该吃太多糖果和冰激凌。"}', 41, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19678, 683, '{"english": "He should brush his teeth every morning and evening.", "chinese": "他应该每天早晚刷牙。"}', 42, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19679, 683, '{"english": "He should go to the dentist.", "chinese": "他应该去看牙医。"}', 43, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19680, 683, '{"english": "He shouldn''t watch too much TV.", "chinese": "他不应该看太多电视。"}', 44, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19681, 683, '{"english": "He should go to bed early every day.", "chinese": "他应该每天早睡。"}', 45, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19682, 683, '{"english": "He should go to bed before 9:30.", "chinese": "他应该在 9 点 30 分之前上床睡觉。"}', 46, '2026-02-05 04:31:48', '2026-02-05 04:31:48');
INSERT INTO "course_content" VALUES (19683, 683, '{"english": "He should eat more fruit and vegetables. He should exercise every day.", "chinese": "他应该多吃水果和蔬菜。他应该每天锻炼。"}', 47, '2026-02-05 04:31:49', '2026-02-05 04:31:49');
INSERT INTO "course_content" VALUES (19684, 683, '{"english": "He can play basketball, jump rope or walk.", "chinese": "他可以打篮球、跳绳或走路。"}', 48, '2026-02-05 04:31:49', '2026-02-05 04:31:49');
INSERT INTO "course_content" VALUES (19685, 683, '{"english": "D. Choose, think and write.", "chinese": "D. 选一选，想一想，写一写。"}', 49, '2026-02-05 04:31:49', '2026-02-05 04:31:49');
INSERT INTO "course_content" VALUES (19686, 683, '{"english": "What''s wrong?", "chinese": "你怎么了？"}', 50, '2026-02-05 04:31:49', '2026-02-05 04:31:49');
