INSERT INTO "course_content" VALUES (19780, 685, '{"english": "I want to send a short message to my mother.", "chinese": "我想给我妈妈发一条短信。"}', 33, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19781, 685, '{"english": "C. Think and write.", "chinese": "C. 想一想，写一写。"}', 34, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19782, 685, '{"english": "I want to send a short message to my mother on Mother''s Day.", "chinese": "我想在母亲节给我妈妈发一条短信。"}', 35, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19783, 685, '{"english": "Bill", "chinese": "比尔"}', 36, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19784, 685, '{"english": "special day", "chinese": "特殊日子"}', 37, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19785, 685, '{"english": "Teachers'' Day", "chinese": "教师节"}', 38, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19786, 685, '{"english": "things he/she would like to do", "chinese": "他/她想做的事情"}', 39, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19787, 685, '{"english": "buy some flowers  make a card  make a phone call", "chinese": "买些花 做张卡片 打电话"}', 40, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19788, 685, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 41, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19789, 685, '{"english": "What would you like to do on Spring Festival?", "chinese": "春节你想做什么？"}', 42, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19790, 685, '{"english": "D. Let''s write.", "chinese": "D. 让我们写一写。"}', 43, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19791, 685, '{"english": "Write what you''d like to do this weekend according to Part B.", "chinese": "根据 B 部分写下这个周末你想做什么。"}', 44, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19792, 685, '{"english": "I would like to buy some books on April 11th.", "chinese": "我想在 4 月 11 日买一些书。"}', 45, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19793, 685, '{"english": "I would like to bounce a ball at the fun sports day on April 12th.", "chinese": "我想在 4 月 12 日的趣味运动会上拍球。"}', 46, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19794, 685, '{"english": "What about you?", "chinese": "你呢？"}', 47, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19795, 685, '{"english": "Checkpoint", "chinese": "检查点"}', 48, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19796, 685, '{"english": "structures", "chinese": "结构"}', 49, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19797, 685, '{"english": "What would you like to do?", "chinese": "你想做什么？"}', 50, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19798, 685, '{"english": "I would like to ...", "chinese": "我想⋯⋯"}', 51, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19799, 685, '{"english": "vocabulary", "chinese": "词汇"}', 52, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19800, 685, '{"english": "send an email, write a letter, make a phone call,", "chinese": "发电子邮件，写信，打电话，"}', 53, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19801, 685, '{"english": "send a short message, mail a present,", "chinese": "发送短消息，邮寄礼物，"}', 54, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19802, 685, '{"english": "make a video call, say, make a card", "chinese": "打视频电话，说；讲，制作卡片"}', 55, '2026-02-05 04:31:53', '2026-02-05 04:31:53');
INSERT INTO "course_content" VALUES (19803, 686, '{"english": "Revision 1", "chinese": "复习 1"}', 1, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19804, 686, '{"english": "Let''s Review", "chinese": "让我们复习一下"}', 2, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19805, 686, '{"english": "A. Listen and number.", "chinese": "A. 听一听，标序号。"}', 3, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19806, 686, '{"english": "1. -It''s time for PE class.", "chinese": "1. —上体育课的时间到了。"}', 4, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19807, 686, '{"english": "-Can I stay in the classroom, Miss Wu?  -What''s wrong?", "chinese": "—我可以留在教室里吗，吴老师? —怎么了?"}', 5, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19808, 686, '{"english": "-I feel tired. I think I have a cold.", "chinese": "—我感到累。我想我感冒了。"}', 6, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19809, 686, '{"english": "-You should go to see a doctor.", "chinese": "—你应该去看医生。"}', 7, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19810, 686, '{"english": "2. -It''s 7 o''clock. Get up, Bill.", "chinese": "2. —7 点了。该起床了，比尔。"}', 8, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19811, 686, '{"english": "-Can I stay at home, Mum?  -What''s wrong?", "chinese": "—妈妈，我能呆在家里吗? —你怎么了?"}', 9, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19812, 686, '{"english": "-I have a headache.  -OK, I''ll phone your teacher.", "chinese": "—我头疼。 —好吧，我会打电话给你的老师。"}', 10, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19813, 686, '{"english": "You should stay in bed and have a good rest.", "chinese": "你应该躺在床上好好休息。"}', 11, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19814, 686, '{"english": "3. -What are you doing?", "chinese": "3. —你在干什么?"}', 12, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19815, 686, '{"english": "-I''m making a card for my father.", "chinese": "—我在给我爸爸做一张卡片。"}', 13, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19816, 686, '{"english": "This Sunday is Father''s Day.", "chinese": "本周日是父亲节。"}', 14, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19817, 686, '{"english": "What would you like to do for your father?", "chinese": "你想为你的爸爸做什么?"}', 15, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19818, 686, '{"english": "-My father is in America now.", "chinese": "—我爸爸现在在美国。"}', 16, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19819, 686, '{"english": "I would like to make a video call and say ''Happy Father''s Day'' to him.", "chinese": "我想给他打个视频电话，并且对他说“父亲节快乐。”"}', 17, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19820, 686, '{"english": "4. -New Year''s Day is coming.", "chinese": "4.—新年就要到了。"}', 18, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19821, 686, '{"english": "How are you going to celebrate it?", "chinese": "你打算怎么庆祝呢?"}', 19, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19822, 686, '{"english": "-Before New Year''s Day, I am going to have a party with my classmates.", "chinese": "—在元旦之前，我打算和我的同学举办一个聚会。"}', 20, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19823, 686, '{"english": "On New Year''s Day, I am going to see an ice lantern show with my family.", "chinese": "元旦那天，我打算和家人一起去看冰灯表演。"}', 21, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19824, 686, '{"english": "What about you?  -I''m going to visit my grandparents and have a big new year''s dinner with them.", "chinese": "你呢? —我要去看望我的祖父母，和他们吃一顿丰盛的年夜饭。"}', 22, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19825, 686, '{"english": "My grandmother is good at cooking.", "chinese": "我的奶奶擅长烹饪。"}', 23, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19826, 686, '{"english": "She cooks delicious food for us every year.", "chinese": "她每年都为我们做美味的食物。"}', 24, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19827, 686, '{"english": "B. Let''s play.", "chinese": "B. 让我们玩一玩。"}', 25, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19828, 686, '{"english": "National Day is coming.", "chinese": "国庆节即将到来。"}', 26, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19829, 686, '{"english": "How are you going to celebrate it, Binbin?", "chinese": "你打算怎么庆祝呢，彬彬？"}', 27, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19830, 686, '{"english": "I''m going to make some cards and give them to my friends.", "chinese": "我打算做一些卡片，送给我的朋友们。"}', 28, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19831, 686, '{"english": "What would you like to do on National Day?", "chinese": "国庆节你想做什么？"}', 29, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19832, 686, '{"english": "I would like to make video calls to my friends,", "chinese": "我想给我的朋友打视频电话，"}', 30, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19833, 686, '{"english": "wear my new clothes and have a party.", "chinese": "穿上我的新衣服，开个派对。"}', 31, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19834, 686, '{"english": "Wow, that sounds great.", "chinese": "哇，听起来不错。"}', 32, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19835, 686, '{"english": "C. Read and write.", "chinese": "C. 读一读，写一写。"}', 33, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19836, 686, '{"english": "How to Be Healthy", "chinese": "如何保持健康"}', 34, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19837, 686, '{"english": "There are some things you should and shouldn''t do to be healthy.", "chinese": "为了保持健康，有些事情你应该做，有些不应该做。"}', 35, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19838, 686, '{"english": "To be healthy, you should often eat fruit,vegetables,meat and fish.", "chinese": "为了健康，你应该经常吃水果、蔬菜、肉和鱼。"}', 36, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19839, 686, '{"english": "You shouldn''t eat too much candy or junk food.", "chinese": "你不应该吃太多糖果或垃圾食品。"}', 37, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19840, 686, '{"english": "You should drink at least eight glasses of water each day.", "chinese": "你应该每天至少喝八杯水。"}', 38, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19841, 686, '{"english": "You should sleep at least nine hours each night,too.", "chinese": "你应该每晚至少睡九个小时。"}', 39, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19842, 686, '{"english": "You shouldn''t go to bed too late.", "chinese": "你不应该睡得太晚。"}', 40, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19843, 686, '{"english": "To be healthy, it is also important to exercise every day.", "chinese": "为了保持健康，每天锻炼也很重要。"}', 41, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19844, 686, '{"english": "Do you walk, swim or run?", "chinese": "你走路、游泳还是跑步？"}', 42, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19845, 686, '{"english": "Do you play sports?", "chinese": "你做运动吗？"}', 43, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19846, 686, '{"english": "To be healthy, you should also take a shower often and you should brush your teeth every day.", "chinese": "为了保持健康，你还应该经常洗澡，每天刷牙。"}', 44, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19847, 686, '{"english": "You must wash your hands often.", "chinese": "你必须经常洗手。"}', 45, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19848, 686, '{"english": "You shouldn''t eat with dirty hands.", "chinese": "你不应该用脏手吃饭。"}', 46, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19849, 686, '{"english": "If you care for your health,you will enjoy your life.", "chinese": "如果你关心你的健康，你就会享受生活。"}', 47, '2026-02-05 04:31:54', '2026-02-05 04:31:54');
INSERT INTO "course_content" VALUES (19850, 686, '{"english": "To be healthy, what should you do?", "chinese": "为了保持健康，你应该做什么？"}', 48, '2026-02-05 04:31:55', '2026-02-05 04:31:55');
INSERT INTO "course_content" VALUES (19851, 686, '{"english": "What shouldn''t you do?", "chinese": "你不应该做什么？"}', 49, '2026-02-05 04:31:55', '2026-02-05 04:31:55');
INSERT INTO "course_content" VALUES (19852, 687, '{"english": "Unit 4", "chinese": "第 4 单元"}', 1, '2026-02-05 04:31:55', '2026-02-05 04:31:55');
INSERT INTO "course_content" VALUES (19853, 687, '{"english": "Last Weekend", "chinese": "上周末"}', 2, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19854, 687, '{"english": "Get ready.", "chinese": "准备一下。"}', 3, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19855, 687, '{"english": "What did you do last weekend?", "chinese": "上个周末你做了什么？"}', 4, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19856, 687, '{"english": "cleaned the window", "chinese": "（过去式）擦窗子"}', 5, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19857, 687, '{"english": "watched TV", "chinese": "（过去式）看电视"}', 6, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19858, 687, '{"english": "climbed a hill", "chinese": "（过去式）爬山"}', 7, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19859, 687, '{"english": "visited grandparents", "chinese": "（过去式）拜访祖父母"}', 8, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19860, 687, '{"english": "danced", "chinese": "（过去式）跳舞"}', 9, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19861, 687, '{"english": "jumped rope", "chinese": "（过去式）跳绳"}', 10, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19862, 687, '{"english": "listened to music", "chinese": "（过去式）听音乐"}', 11, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19863, 687, '{"english": "rowed a boat", "chinese": "（过去式）划船"}', 12, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19864, 687, '{"english": "played computer games", "chinese": "（过去式）玩电子游戏"}', 13, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19865, 687, '{"english": "stayed at home", "chinese": "（过去式）待在家里"}', 14, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19866, 687, '{"english": "played the piano", "chinese": "（过去式）弹钢琴"}', 15, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19867, 687, '{"english": "played chess", "chinese": "（过去式）下棋"}', 16, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19868, 687, '{"english": "What did you do last weekend?", "chinese": "上周末你做什么了？"}', 17, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19869, 687, '{"english": "I visited my grandparents.", "chinese": "我拜访了我的祖父母。"}', 18, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19870, 687, '{"english": "What did you do last weekend?  I climbed a hill.", "chinese": "上个周末你做些什么？ 我爬了一座山。"}', 19, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19871, 687, '{"english": "I played chess.  It was fun.  What about you?", "chinese": "我下了棋。 很有趣。 你呢？"}', 20, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19872, 687, '{"english": "What did you do last weekend?", "chinese": "上个周末你做些什么？"}', 21, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19873, 687, '{"english": "I cleaned the living room.", "chinese": "我打扫了客厅。"}', 22, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19874, 687, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 23, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19875, 687, '{"english": "On Sunday, I rowed a boat with my family.", "chinese": "星期天，我和家人划船。"}', 24, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19876, 687, '{"english": "name, day, activites", "chinese": "姓名，日期，活动"}', 25, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19877, 687, '{"english": "danced", "chinese": "（过去式）跳舞"}', 26, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
