INSERT INTO "course_content" VALUES (19879, 687, '{"english": "played the piano", "chinese": "（过去式）弹钢琴"}', 28, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19880, 687, '{"english": "cleaned his/her room", "chinese": "（过去式）打扫他/她的房间"}', 29, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19881, 687, '{"english": "climbed a hill", "chinese": "（过去式）爬山"}', 30, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
