INSERT INTO "course_content" VALUES (19883, 687, '{"english": "listened to music", "chinese": "（过去式）听音乐"}', 32, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19884, 687, '{"english": "jumped rope", "chinese": "（过去式）跳绳"}', 33, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19885, 687, '{"english": "C. Let''s write.", "chinese": "C. 让我们写一写。"}', 34, '2026-02-05 04:31:56', '2026-02-05 04:31:56');
INSERT INTO "course_content" VALUES (19886, 687, '{"english": "Fill in the blanks according to the survey.", "chinese": "根据调查结果填空。"}', 35, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19887, 687, '{"english": "How was Bob''s weekend?", "chinese": "鲍勃的周末过得怎么样？"}', 36, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19888, 687, '{"english": "What did Bob do last Saturday afternoon?", "chinese": "鲍勃上周六下午做了什么？"}', 37, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19889, 687, '{"english": "What did you do?", "chinese": "你做了什么？"}', 38, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19890, 687, '{"english": "I stayed at home, cleaned my room and watched TV.", "chinese": "我呆在家里，打扫房间，看电视。"}', 39, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19891, 687, '{"english": "D. Let''s write.", "chinese": "D. 让我们写一写。"}', 40, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19892, 687, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 41, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19893, 687, '{"english": "What did you do?", "chinese": "你做了什么？"}', 42, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19894, 687, '{"english": "Checkpoint", "chinese": "检查点"}', 43, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19895, 687, '{"english": "structures", "chinese": "结构"}', 44, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19896, 687, '{"english": "How was your weekend?", "chinese": "你周末过得怎么样？"}', 45, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19897, 687, '{"english": "What did you do last weekend?", "chinese": "上周末你做了什么？"}', 46, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19898, 687, '{"english": "vocabulary", "chinese": "词汇"}', 47, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19899, 687, '{"english": "cleaned the window, watched TV, climbed a hill,", "chinese": "（过去式）擦窗子，（过去式）看电视，（过去式）爬山，"}', 48, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19900, 687, '{"english": "visited grandparents, danced, jumped rope, listened to music,", "chinese": "（过去式）拜访祖父母，（过去式）跳舞，（过去式）跳绳，（过去式）听音乐，"}', 49, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19901, 687, '{"english": "rowed a boat, played computer games, stayed at home,", "chinese": "（过去式）划船，（过去式）玩电子游戏，（过去式）呆在家里，"}', 50, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19902, 687, '{"english": "played the piano, played chess. washed clothes, boring", "chinese": "（过去式）弹钢琴，（过去式）下棋，（过去式）洗衣服，（过去式）无聊的"}', 51, '2026-02-05 04:31:57', '2026-02-05 04:31:57');
INSERT INTO "course_content" VALUES (19903, 688, '{"english": "Unit 5", "chinese": "第 5 单元"}', 1, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19904, 688, '{"english": "Have a Great Trip", "chinese": "很棒的旅行"}', 2, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19905, 688, '{"english": "Get ready.", "chinese": "准备一下。"}', 3, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19906, 688, '{"english": "How was your vacation?", "chinese": "你的假期怎么样？"}', 4, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19907, 688, '{"english": "went to the beach", "chinese": "（过去式）去海边"}', 5, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19908, 688, '{"english": "drank cold drinks", "chinese": "（过去式）喝冷饮"}', 6, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19909, 688, '{"english": "swam in the sea", "chinese": "（过去式）在海里游泳"}', 7, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19910, 688, '{"english": "ate ice cream", "chinese": "（过去式）吃冰激凌"}', 8, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19911, 688, '{"english": "went to the Stone Forest", "chinese": "（过去式）去石林"}', 9, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19912, 688, '{"english": "bought some gifts", "chinese": "（过去式）买礼物"}', 10, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19913, 688, '{"english": "took photos", "chinese": "（过去式）拍照片"}', 11, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19914, 688, '{"english": "saw flowers", "chinese": "（过去式）赏花"}', 12, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19915, 688, '{"english": "Hello, Bill. How was your vacation?", "chinese": "你好，比尔。你的假期怎么样？"}', 13, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19916, 688, '{"english": "It was great. I went to the beach.", "chinese": "太棒了。我去了海滩。"}', 14, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19917, 688, '{"english": "What about you, Lily?", "chinese": "你呢，莉莉？"}', 15, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19918, 688, '{"english": "I went to Kunming with my uncle''s family.", "chinese": "我和叔叔一家去了昆明。"}', 16, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19919, 688, '{"english": "I felt very happy.", "chinese": "我觉得非常开心。"}', 17, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19920, 688, '{"english": "B. Chant and say.", "chinese": "B. 唱一唱，说一说。"}', 18, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19921, 688, '{"english": "I think you had a wonderful vacation.", "chinese": "我想你假期过得很愉快。"}', 19, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19922, 688, '{"english": "Do you have any pictures with you?", "chinese": "你有照片吗？"}', 20, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19923, 688, '{"english": "Where did you go?  What did you do?", "chinese": "你去哪儿了？ 你做了什么？"}', 21, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19924, 688, '{"english": "I went to the beach.  I swam in the sea.", "chinese": "我去了海滩。 我在海里游泳。"}', 22, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19925, 688, '{"english": "I slept really late.  I saw a nice tree.", "chinese": "我睡得很晚。 我看到一棵漂亮的树。"}', 23, '2026-02-05 04:31:58', '2026-02-05 04:31:58');
INSERT INTO "course_content" VALUES (19926, 689, '{"english": "Unit 6", "chinese": "第 6 单元"}', 1, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19927, 689, '{"english": "Growing Up", "chinese": "成长"}', 2, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19928, 689, '{"english": "Get ready.", "chinese": "准备一下。"}', 3, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19929, 689, '{"english": "Do you like their growing-up stories?", "chinese": "你喜欢他们的成长故事吗？"}', 4, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19930, 689, '{"english": "was born", "chinese": "出生"}', 5, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19931, 689, '{"english": "started to speak", "chinese": "开始说话"}', 6, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19932, 689, '{"english": "learned to walk", "chinese": "学走路"}', 7, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19933, 689, '{"english": "learned to ride a bike", "chinese": "学骑自行车"}', 8, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19934, 689, '{"english": "went to kindergarten", "chinese": "去幼儿园"}', 9, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19935, 689, '{"english": "It was easy.", "chinese": "它很容易。"}', 10, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19936, 689, '{"english": "-And you, Yaoyao?", "chinese": "—你呢，瑶瑶?"}', 11, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19937, 689, '{"english": "-I went to school when I was 6 years old. I really liked my first teacher, Miss Wu.", "chinese": "—我 6 岁时去上学。我真得很喜欢我的第一个老师，吴老师。"}', 12, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19938, 689, '{"english": "I bought an ice cream. It was delicious.", "chinese": "我买了一个冰激凌。它非常好吃。"}', 13, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19939, 689, '{"english": "What did you learn to do when you were five?", "chinese": "五岁的时候你学习做什么了？"}', 14, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19940, 689, '{"english": "When I was five, I learned to swim", "chinese": "当我五岁的时候，我学习游泳，"}', 15, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19941, 689, '{"english": "and started to study English.", "chinese": "开始学英语。"}', 16, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19942, 689, '{"english": "When did you go to kindergarten?", "chinese": "你什么时候去上幼儿园的？"}', 17, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19943, 689, '{"english": "Oh, I went to kindergarten when I was three.", "chinese": "哦，我三岁开始去上幼儿园的。"}', 18, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19944, 689, '{"english": "Me too.", "chinese": "我也是。"}', 19, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19945, 689, '{"english": "B. Do a survey and report.", "chinese": "B. 做一个调查并报告。"}', 20, '2026-02-05 04:31:59', '2026-02-05 04:31:59');
INSERT INTO "course_content" VALUES (19946, 689, '{"english": "When did you learn to swim, Joy?", "chinese": "乔伊，你什么时候学游泳的？"}', 21, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19947, 689, '{"english": "She is lovely and beautiful,but she is very small. We called her Doudou.", "chinese": "她很可爱，很漂亮，但她很小。我们叫她豆豆。"}', 22, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19948, 689, '{"english": "May 10th, 2006Doudou said ''mum'' today.", "chinese": "2006 年 5 月 1 日豆豆今天说“妈妈”。"}', 23, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19949, 689, '{"english": "It was her first word!", "chinese": "这是她的第一个字！"}', 24, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19950, 689, '{"english": "I was so excited. She said it many times.", "chinese": "我太激动了。她说了很多次。"}', 25, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19951, 689, '{"english": "Now her father is trying to teach her to say ''dad'',too.", "chinese": "现在她父亲也正试着教她说“爸爸”。"}', 26, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19952, 689, '{"english": "December 3rd, 2006", "chinese": "2006 年 12 月 3 日"}', 27, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19953, 689, '{"english": "Doudou walked for the first time today.", "chinese": "豆豆今天第一次走路。"}', 28, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19954, 689, '{"english": "She was very happy.", "chinese": "她非常高兴。"}', 29, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19955, 690, '{"english": "Revision 2", "chinese": "复习 2"}', 1, '2026-02-05 04:32:00', '2026-02-05 04:32:00');
INSERT INTO "course_content" VALUES (19956, 690, '{"english": "Let''s Review", "chinese": "让我们复习一下"}', 2, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19957, 690, '{"english": "A. Listen and number", "chinese": "A. 听一听，标序号。"}', 3, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19958, 690, '{"english": "1. Look, I''m riding a bike in this picture.", "chinese": "1. 看，这张照片里我在骑自行车。"}', 4, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19959, 690, '{"english": "I learned to ride a bike when I was 5.", "chinese": "我 5 岁的时候学骑自行车。"}', 5, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19960, 690, '{"english": "I also went to kindergarten when I was 5.", "chinese": "我 5 岁的时候也上了幼儿园。"}', 6, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19961, 690, '{"english": "I drew pictures,sang songs and danced in my kindergarten.", "chinese": "我在幼儿园画画、唱歌、跳舞。"}', 7, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19962, 690, '{"english": "I had a lot of fun.", "chinese": "我玩得很开心。"}', 8, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19963, 690, '{"english": "I really liked my kindergarten.", "chinese": "我非常喜欢我的幼儿园。"}', 9, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19964, 690, '{"english": "2. I was born on January 1st,2004.", "chinese": "2. 我出生于 2004 年 1 月 1 日。"}', 10, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19965, 690, '{"english": "So my parents call me ''Xinxin''.", "chinese": "所以我的父母叫我“新新”。"}', 11, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19966, 690, '{"english": "I learned to speak when I was 11 months old.", "chinese": "我在 11 个月大的时候学习说话。"}', 12, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19967, 690, '{"english": "The first word I said was ''mama''. My mother was very happy when I first called her ''mama''.", "chinese": "我说的第一个词是“妈妈”。我妈妈很高兴当我第一次叫她“妈妈”。"}', 13, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19968, 690, '{"english": "3. Last winter vacation,I went to Australia with my parents.", "chinese": "3. 去年寒假，我和父母去了澳大利亚。"}', 14, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19969, 690, '{"english": "It was summer there.", "chinese": "当时是夏天。"}', 15, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19970, 690, '{"english": "We went to the beach and swam in the sea. We also saw kangaroos and koalas at the zoo.", "chinese": "我们去了海滩，在海里游泳。我们还在动物园看到了袋鼠和考拉。"}', 16, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19971, 690, '{"english": "I bought some toy koalas for my friends. I really enjoyed my trip.", "chinese": "我给我的朋友们买了一些玩具考拉。我真得很享受这次旅行。"}', 17, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19972, 690, '{"english": "4. I visited my uncle last weekend. I stayed at his home for 2 days.", "chinese": "4. 我上周末去拜访了我叔叔。我在他家呆了两天。"}', 18, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19973, 690, '{"english": "I played with my cousins.", "chinese": "我和我的堂兄弟玩。"}', 19, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19974, 690, '{"english": "We climbed the hills,rode horses and fed the ducks.", "chinese": "我们爬山、骑马、喂鸭子。"}', 20, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19975, 690, '{"english": "I had a good time there.", "chinese": "我在那里过得很愉快。"}', 21, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19976, 690, '{"english": "B. Let''s play.", "chinese": "B. 让我们玩一玩。"}', 22, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19977, 690, '{"english": "Find out who went there with you.", "chinese": "找出谁和你一起去的那里。"}', 23, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19978, 690, '{"english": "Where did you go?", "chinese": "你去哪儿了？"}', 24, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19979, 690, '{"english": "When did you go there?", "chinese": "你什么时候去的？"}', 25, '2026-02-05 04:32:01', '2026-02-05 04:32:01');
INSERT INTO "course_content" VALUES (19980, 690, '{"english": "How did you go there?", "chinese": "你怎么去的？"}', 26, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19981, 690, '{"english": "What did you do there?", "chinese": "你在那里做了什么？"}', 27, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19982, 690, '{"english": "C. Read and write.", "chinese": "C. 读一读，写一写。"}', 28, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19983, 690, '{"english": "Our Wonderful Vacations", "chinese": "我们美好的假期"}', 29, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19984, 691, '{"english": "Hi, sweet heart. Are you OK?", "chinese": "嘿，甜心。你还好吗？"}', 1, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19985, 691, '{"english": "What''s wrong? Oh Mum.", "chinese": "怎么啦？哦，妈妈。"}', 2, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19986, 691, '{"english": "I''ve got a headache, a headache, a headache.  I''ve got a headache.", "chinese": "我头痛，头痛，头痛。 我头痛。"}', 3, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19987, 691, '{"english": "What should I do? You should have a rest and drink some warm water.", "chinese": "我该怎么办？你应该休息一下，喝些温水。"}', 4, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19988, 691, '{"english": "You shouldn''t watch TV.  No TV for you!", "chinese": "你不应该看电视。 不给你看电视！"}', 5, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19989, 691, '{"english": "Darling, you look like you don''t feel well.", "chinese": "亲爱的，你看起来好像不舒服。"}', 6, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19990, 691, '{"english": "What''s wrong? Oh, Mum. It hurts.", "chinese": "怎么啦？哦，妈妈。好疼啊。"}', 7, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19991, 691, '{"english": "I''ve got a stomachache, a stomachache, a stomachache.  I''ve got a stomachache.", "chinese": "我胃痛，胃痛，胃痛。 我胃痛。"}', 8, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19992, 691, '{"english": "What should I do? You should see a doctor and drink some warm water.", "chinese": "我该怎么办？你应该去看医生，喝些温水。"}', 9, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19993, 691, '{"english": "You shouldn''t eat ice cream.  No ice cream for you!", "chinese": "你不应该吃冰激凌， 不给你冰激凌！"}', 10, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19994, 691, '{"english": "It''s a day for children,", "chinese": "这是属于孩子们的一天，"}', 11, '2026-02-05 04:32:02', '2026-02-05 04:32:02');
INSERT INTO "course_content" VALUES (19995, 691, '{"english": "A day for you and me.  Children''s Day is fun.", "chinese": "属于你和我的一天。 儿童节很有趣。"}', 12, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (19996, 691, '{"english": "We can play games happily.   It''s a day for mothers.", "chinese": "我们可以开心地玩游戏。  这是属于母亲们的一天。"}', 13, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (19997, 691, '{"english": "They help us every day.  Mother''s Day is great.", "chinese": "她们每天都帮助我们。 母亲节是伟大的。"}', 14, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (19998, 691, '{"english": "We show our love in many ways.", "chinese": "我们用很多方式表达我们的爱。"}', 15, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (19999, 691, '{"english": "It''s a day for fathers.  They work hard for me and you.", "chinese": "这是属于父亲们的一天。 他们为我和你努力工作。"}', 16, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20000, 691, '{"english": "Father''s Day is cool.  We say thanks for all they do.", "chinese": "父亲节很酷。 我们感谢他们所做的一切。"}', 17, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20001, 691, '{"english": "Send me a letter,a long, long letter.", "chinese": "给我寄封信，一封长长、长长的信。"}', 18, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20002, 691, '{"english": "Send me an email, too. Send me short messages,every day.", "chinese": "也给我发封电子邮件。每天给我发短信。"}', 19, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20003, 691, '{"english": "I want to hear from you.", "chinese": "我想收到你的信息。"}', 20, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20004, 691, '{"english": "Give me a call,a long, long call.  Send me a present, too.", "chinese": "给我打个电话，一个很长、很长的电话。 也送我一份礼物。"}', 21, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20005, 691, '{"english": "Send me some cards,every day. I love to hear from you.", "chinese": "每天给我送一些卡片。我喜欢听到你的信息。"}', 22, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20006, 691, '{"english": "What did you do last weekend?", "chinese": "上周末你做了什么？"}', 23, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20007, 691, '{"english": "On Saturday and Sunday, I listened to music and played football.  That''s what I did those days.", "chinese": "星期六和星期天，我听音乐，踢足球。 这就是我周末做的事情。"}', 24, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20008, 691, '{"english": "What did you do last weekend?", "chinese": "上周末你做了什么？"}', 25, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
INSERT INTO "course_content" VALUES (20009, 691, '{"english": "On Saturday and Sunday, I danced with my friends and walked in the park.", "chinese": "星期六和星期天，我和朋友们跳舞，在公园里散步。"}', 26, '2026-02-05 04:32:03', '2026-02-05 04:32:03');
