INSERT INTO "course_content" VALUES (20094, 694, '{"english": "A. Listen and number.", "chinese": "A. 听一听，写编号。"}', 2, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20095, 694, '{"english": "1. -Where did you go on your summer vacation?", "chinese": "1. —你暑假去了哪里？"}', 3, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20096, 694, '{"english": "-I went to Guangzhou with my parents.", "chinese": "—我和父母一起去了广州。"}', 4, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20097, 694, '{"english": "-What did you do there?", "chinese": "—你在那里做了什么？"}', 5, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20098, 694, '{"english": "-We ate seafood, had morning tea and tasty soup.", "chinese": "—我们吃了海鲜，喝了早茶和美味的汤。"}', 6, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20099, 694, '{"english": "What about your, Bill?", "chinese": "比尔，你呢？"}', 7, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20100, 694, '{"english": "-I went to Lhasa with my aunt and uncle.", "chinese": "—我和叔叔阿姨去了拉萨。"}', 8, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20101, 694, '{"english": "-What did you do there?", "chinese": "—你在那里做了什么？"}', 9, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20102, 694, '{"english": "-We saw high mountains and visited the Potala Palace.", "chinese": "—我们看到了高山，参观了布达拉宫。"}', 10, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20103, 694, '{"english": "These are my photographs.", "chinese": "这些是我的照片。"}', 11, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20104, 694, '{"english": "2. -Did you go traveling in the vacation, Yaoyao?", "chinese": "2. —瑶瑶，你假期去旅行了吗？"}', 12, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20105, 694, '{"english": "-No, I didn''t. My cousin came to Beijing.", "chinese": "—不，我没有。我表哥来北京了。"}', 13, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20106, 694, '{"english": "I took him to the Summer Palace one day.", "chinese": "有一天我带他去了颐和园。"}', 14, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20107, 694, '{"english": "We went boating and took many photos by the lake.", "chinese": "我们在湖边划船，拍了很多照片。"}', 15, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20108, 694, '{"english": "3. -How was your summer vacation, Joy?  -It was great.", "chinese": "3. —乔伊，你的暑假过得怎么样？ —太棒了。"}', 16, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20109, 694, '{"english": "I went to Suzhou.  -What did you do there?", "chinese": "我去了苏州。 —你在那里做了什么？"}', 17, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20110, 694, '{"english": "-I visited some gardens there. They were all very beautiful.", "chinese": "—我参观了那里的一些花园。他们都很漂亮。"}', 18, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20111, 694, '{"english": "My mother bought a lovely red teacup there.", "chinese": "我妈妈在那里买了一个可爱的红色茶杯。"}', 19, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20112, 694, '{"english": "-Your pictures are beautiful. Look, this is my picture.", "chinese": "—你的照片很漂亮。看，这是我的照片。"}', 20, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20113, 694, '{"english": "I went to Xi''an to see the Terracotta Army.", "chinese": "我去西安看兵马俑。"}', 21, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20114, 694, '{"english": "It was amazing.", "chinese": "真是太棒了。"}', 22, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20115, 694, '{"english": "B. Let''s play.", "chinese": "B. 我们来一玩。"}', 23, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20116, 694, '{"english": "Where did you go on your summer vacation?", "chinese": "你暑假去了哪里？"}', 24, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20117, 694, '{"english": "Guess!", "chinese": "猜猜看！"}', 25, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20118, 694, '{"english": "What did you do there?", "chinese": "你在那里做了什么？"}', 26, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20119, 694, '{"english": "I saw the Terracotta Army.", "chinese": "我看到了兵马俑。"}', 27, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20120, 694, '{"english": "Is it Xi''an?", "chinese": "是西安吗？"}', 28, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20121, 694, '{"english": "You''re right.", "chinese": "你说得对。"}', 29, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
INSERT INTO "course_content" VALUES (20122, 694, '{"english": "C. Let''s write.", "chinese": "C. 我们来写一写。"}', 30, '2026-02-05 04:32:08', '2026-02-05 04:32:08');
