INSERT INTO "course_content" VALUES (20126, 694, '{"english": "Choose a city in China,", "chinese": "选择一个中国的城市，"}', 34, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20127, 694, '{"english": "and write some sentences about it.", "chinese": "写一些关于它的句子。"}', 35, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
