INSERT INTO "course_content" VALUES (20129, 694, '{"english": "What is it famous for?", "chinese": "它以什么闻名？"}', 37, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20130, 694, '{"english": "What can you do there?", "chinese": "你在那里能做什么？"}', 38, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20131, 694, '{"english": "D. Let''s write.", "chinese": "D. 我们来写一写。"}', 39, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20132, 694, '{"english": "Where do you want to go on your vacation?", "chinese": "你想去哪里度假？"}', 40, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20133, 694, '{"english": "Where is it? How do you want to go there?", "chinese": "它在哪里？你想怎么去？"}', 41, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
INSERT INTO "course_content" VALUES (20134, 694, '{"english": "What is it famous for?", "chinese": "它以什么闻名？"}', 42, '2026-02-05 04:32:09', '2026-02-05 04:32:09');
