INSERT INTO "course_content" VALUES (20160, 695, '{"english": "1. -Joy, what do you want to go this vacation?", "chinese": "1. —乔伊，这个假期你想去做什么？"}', 3, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20161, 695, '{"english": "-I want to go to Washington D.C.", "chinese": "—我想去华盛顿特区。"}', 4, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20162, 695, '{"english": "It''s in the east of the USA.", "chinese": "它在美国东部。"}', 5, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20163, 695, '{"english": "-What do you want to do there?", "chinese": "—你在那里做什么？"}', 6, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20164, 695, '{"english": "-I want to visit the White House. How about you, Andy?", "chinese": "—我想参观白宫。你呢，安迪？"}', 7, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20165, 695, '{"english": "-I want to go to Sydney. It''s in the southeast of Australia.", "chinese": "—我想去悉尼。它位于澳大利亚东南部。"}', 8, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20166, 695, '{"english": "I want to visit the Opera House and see kangaroos.", "chinese": "我想去歌剧院看袋鼠。"}', 9, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20167, 695, '{"english": "2. -Bill, where do you want to go this winter vacation?", "chinese": "2. —威尔，这个寒假你想去哪里？"}', 10, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20168, 695, '{"english": "-I want to go to London. It''s in the southeast of the UK.", "chinese": "—我想去伦敦。它位于英国东南部。"}', 11, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20169, 695, '{"english": "-What do you want to do there?", "chinese": "—你想在那里做什么？"}', 12, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20170, 695, '{"english": "-I want to visit the British Museum and see Big Ben.", "chinese": "—我想参观大英博物馆，看大本钟。"}', 13, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20171, 695, '{"english": "It''s a large clock. What about you?", "chinese": "这是一个大钟。你呢？"}', 14, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20172, 695, '{"english": "-I want to go to Canada.  -Wow, Canada is a big country.", "chinese": "—我想去加拿大。 —哇，加拿大是个大国。"}', 15, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20173, 695, '{"english": "What''s it famous for?  -It''s famous for maple leaves.", "chinese": "它以什么闻名？ —它以枫叶闻名。"}', 16, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20174, 695, '{"english": "I want to go to Toronto. It''s in the southeast of Canada.", "chinese": "我想去多伦多。它位于加拿大东南部。"}', 17, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20175, 695, '{"english": "I want to see the CN Tower.", "chinese": "我想看看加拿大国家电视塔。"}', 18, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20176, 695, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 19, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20177, 695, '{"english": "Hello. Lily.", "chinese": "你好。莉莉。"}', 20, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20178, 695, '{"english": "Where do you want to go this winter vacation?", "chinese": "这个寒假你想去哪里？"}', 21, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20179, 695, '{"english": "I want to go to Washington. It''s in the east of the USA.", "chinese": "我想去华盛顿。它在美国东部。"}', 22, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20180, 695, '{"english": "What do you want to do there?", "chinese": "你想在那里做什么？"}', 23, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20181, 695, '{"english": "I want to visit the museums there.", "chinese": "我想参观那里的博物馆。"}', 24, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
INSERT INTO "course_content" VALUES (20182, 695, '{"english": "C. Let''s write.", "chinese": "C. 我们来写一写。"}', 25, '2026-02-05 04:32:10', '2026-02-05 04:32:10');
