INSERT INTO "course_content" VALUES (20248, 696, '{"english": "What kind of animals are tigers?", "chinese": "老虎是什么动物？"}', 22, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
INSERT INTO "course_content" VALUES (20249, 696, '{"english": "They are mammals.", "chinese": "它们是哺乳动物。"}', 23, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
INSERT INTO "course_content" VALUES (20250, 696, '{"english": "What can they do?", "chinese": "它们会做什么？"}', 24, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
INSERT INTO "course_content" VALUES (20251, 696, '{"english": "They can run very fast.", "chinese": "它们能跑得很快。"}', 25, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
