INSERT INTO "course_content" VALUES (20265, 696, '{"english": "They can swim very fast. They have big mouths.", "chinese": "它们能游得很快。它们长着大嘴。"}', 39, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
INSERT INTO "course_content" VALUES (20266, 696, '{"english": "Elephants are mammals. They''re big and strong They each have a long nose,", "chinese": "大象是哺乳动物。它们又大又壮，每只大象都有一个长鼻子，"}', 40, '2026-02-05 04:32:13', '2026-02-05 04:32:13');
INSERT INTO "course_content" VALUES (20267, 696, '{"english": "two long teeth and two big ears.", "chinese": "两颗长牙齿和两个大耳朵。"}', 41, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
