INSERT INTO "course_content" VALUES (20274, 696, '{"english": "D. Let''s play.", "chinese": "D. 我们来玩一玩。"}', 48, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20275, 696, '{"english": "These animals are mammals.", "chinese": "这些动物是哺乳动物。"}', 49, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20276, 696, '{"english": "They each have two long ears and two red eyes.", "chinese": "它们都有两只长耳朵和两只红眼睛。"}', 50, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20277, 696, '{"english": "They can jump, and they eat grass. What animals are they?", "chinese": "它们会跳，它们吃草。它们是什么动物？"}', 51, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
