INSERT INTO "course_content" VALUES (20291, 696, '{"english": "shark", "chinese": "鲨鱼"}', 65, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20292, 696, '{"english": "whale", "chinese": "鲸鱼"}', 66, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20293, 696, '{"english": "kind", "chinese": "种类"}', 67, '2026-02-05 04:32:14', '2026-02-05 04:32:14');
INSERT INTO "course_content" VALUES (20294, 697, '{"english": "Revision 1", "chinese": "复习 1"}', 1, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20295, 697, '{"english": "Let''s Review", "chinese": "让我们复习吧"}', 2, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20296, 697, '{"english": "A. Listen and number.", "chinese": "A. 听一听，并编号。"}', 3, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20297, 697, '{"english": "1. It''s a high place.", "chinese": "1. 这是一个很高的地方。"}', 4, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20298, 697, '{"english": "It''s in the west of China.", "chinese": "它在中国的西部。"}', 5, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20299, 697, '{"english": "It''s very cold in winter.", "chinese": "冬天很冷。"}', 6, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20300, 697, '{"english": "There are many high mountains near the city.", "chinese": "城市附近有许多高山。"}', 7, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20301, 697, '{"english": "It''s famous for the Potala Palace.", "chinese": "它以布达拉宫而闻名。"}', 8, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20302, 697, '{"english": "2. This city is in the east of China, it is near Shanghai.", "chinese": "2. 这个城市在中国的东部，它靠近上海。"}', 9, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20303, 697, '{"english": "It''s famous for beautiful west lake, you can buy a silk skirt and Longjing tea for your parents.", "chinese": "它以美丽的西湖而闻名，你可以买一条丝绸裙子和龙井茶给你的父母。"}', 10, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20304, 697, '{"english": "3.This city is not in China, it is in the southeast of Canada.", "chinese": "3. 这个城市不在中国，它在加拿大的东南部。"}', 11, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20305, 697, '{"english": "People there speak English.", "chinese": "那里的人说英语。"}', 12, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20306, 697, '{"english": "This city is famous for maple leaves, you can visit the CN Tower there.", "chinese": "这个城市以枫叶闻名，你可以参观加拿大国家电视塔。"}', 13, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20307, 697, '{"english": "4. This city is famous for its beautiful beach.", "chinese": "4. 这个城市以它美丽的海滩而闻名。"}', 14, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20308, 697, '{"english": "You can swim in the sea and eat seafood on the beach.", "chinese": "你可以在海里游泳，在海滩上吃海鲜。"}', 15, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20309, 697, '{"english": "The Opera House is famous too.", "chinese": "歌剧院也很有名。"}', 16, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20310, 697, '{"english": "Do you like kangaroos and koalas?", "chinese": "你喜欢袋鼠和考拉吗?"}', 17, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20311, 697, '{"english": "you can see them in the zoo.", "chinese": "你可以在动物园里看到它们。"}', 18, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20312, 697, '{"english": "5. It is in the north of China, so it''s very cold in winter.", "chinese": "5. 它在中国的北方，所以冬天很冷。"}', 19, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20313, 697, '{"english": "If you like skiing, you can go there in winter, also you can see ice lantern there.", "chinese": "如果你喜欢滑雪，你可以在冬天去那里，还可以在那里看到冰灯。"}', 20, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20314, 697, '{"english": "But remember wear your thick coat, scarf and gloves.", "chinese": "但是记得穿上你的厚外套、围巾和手套。"}', 21, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20315, 697, '{"english": "B. Read and tick the right words.", "chinese": "B. 阅读并勾选正确的单词。"}', 22, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20316, 697, '{"english": "Yesterday my friend and I went to the zoo.", "chinese": "昨天我和朋友去了动物园。"}', 23, '2026-02-05 04:32:15', '2026-02-05 04:32:15');
INSERT INTO "course_content" VALUES (20317, 697, '{"english": "We saw many kinds of animals. First, I went to Mammal World.", "chinese": "我们看到许多种动物。首先，我去了哺乳动物世界。"}', 24, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20318, 697, '{"english": "I saw a (tiger, whale) there.", "chinese": "我在那儿看见一只（老虎、鲸鱼）。"}', 25, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20319, 697, '{"english": "It was big, and it had beautiful fur.", "chinese": "它很大，长着漂亮的皮毛。"}', 26, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20320, 697, '{"english": "Then I went to Bird Land. I saw a (parrot, penguin) there.", "chinese": "然后我去了鸟岛。我在那里看到一只（鹦鹉，企鹅）。"}', 27, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20321, 697, '{"english": "It''s from American. It can talk in English and Chinese.", "chinese": "它来自美国。它能用英语和中文交谈。"}', 28, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20322, 697, '{"english": "Then I saw the biggest mammal at the zoo.", "chinese": "然后我在动物园看到了最大的哺乳动物。"}', 29, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20323, 697, '{"english": "It was a (shark, whale) in Fish World.", "chinese": "那是鱼世界里的一只（鲨鱼，鲸鱼）。"}', 30, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20324, 697, '{"english": "The most beautiful animal at the zoo was a blue and yellow flying insect.", "chinese": "动物园里最漂亮的动物是一只蓝黄色的飞虫。"}', 31, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20325, 697, '{"english": "It was a (penguin, butterfly).", "chinese": "那是一只（企鹅，蝴蝶）。"}', 32, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20326, 697, '{"english": "My favourite animal was in Reptile World.", "chinese": "我最喜欢的动物是爬行动物世界里的。"}', 33, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20327, 697, '{"english": "It was a (snake, bee). It was long and cute.", "chinese": "那是（蛇，蜜蜂）。它又长又可爱。"}', 34, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20328, 697, '{"english": "I liked the trip very much. It was very interesting.", "chinese": "我非常喜欢这次旅行。非常有趣。"}', 35, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20329, 697, '{"english": "C. Guess and write.", "chinese": "C. 猜一猜，写一写。"}', 36, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20330, 697, '{"english": "What is it?", "chinese": "它是什么？"}', 37, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20331, 697, '{"english": "D. Think and talk.", "chinese": "D. 想一想，说一说。"}', 38, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20332, 697, '{"english": "What do you know about your favourite animal?", "chinese": "你对你最喜欢的动物了解多少？"}', 39, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20333, 697, '{"english": "What kind of animals are they?", "chinese": "它们是什么动物？"}', 40, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20334, 697, '{"english": "What do they like to eat?", "chinese": "它们喜欢吃什么？"}', 41, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20335, 697, '{"english": "Where do they live?", "chinese": "它们生活在哪里？"}', 42, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20336, 697, '{"english": "What can they do?", "chinese": "它们能做什么？"}', 43, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20337, 697, '{"english": "What do they look like?", "chinese": "它们长什么样子？"}', 44, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20338, 697, '{"english": "happy", "chinese": "开心的"}', 45, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20339, 697, '{"english": "My dog and I go out to play.", "chinese": "我和我的狗出去玩。"}', 46, '2026-02-05 04:32:16', '2026-02-05 04:32:16');
INSERT INTO "course_content" VALUES (20340, 698, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20341, 698, '{"english": "A. Listen and number.", "chinese": "A. 听一听，并编号。"}', 2, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20342, 698, '{"english": "1. I go to Lily''s house for lunch.", "chinese": "1. 我去莉莉家吃午饭。"}', 3, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20343, 698, '{"english": "My dog climbs on the table and eats Lily''s lunch, so I am angry.", "chinese": "我的狗爬到桌子上吃莉莉的午餐，所以我很生气。"}', 4, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20344, 698, '{"english": "2. I come home after school.", "chinese": "2. 我放学回家，"}', 5, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20345, 698, '{"english": "My dog is lying in his bed. He''s ill, and I''m worried.", "chinese": "我的狗躺在他的床上。他病了，我很担心。"}', 6, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20346, 698, '{"english": "3. Today, my dog and I go out to play in the park.", "chinese": "3.今天，我和我的狗去公园玩。"}', 7, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20347, 698, '{"english": "He is happy and I am happy, too.", "chinese": "他很高兴，我也很高兴。"}', 8, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20348, 698, '{"english": "4. My dog suddenly runs over to Yaoyao, so Yaoyao is scared.", "chinese": "4. 我的狗突然跑向瑶瑶，所以瑶瑶很害怕。"}', 9, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20349, 698, '{"english": "5. I can''t find my dog. It makes me cry.", "chinese": "5. 我找不到我的狗了，它让我哭了。"}', 10, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20350, 698, '{"english": "I look all round the house and in the street, but I have no luck.", "chinese": "我看了看房子周围和街上，但运气不佳。"}', 11, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20351, 698, '{"english": "I am very sad.", "chinese": "我很伤心。"}', 12, '2026-02-05 04:32:17', '2026-02-05 04:32:17');
INSERT INTO "course_content" VALUES (20352, 698, '{"english": "6. I am in my bedroom. I hear my dog.", "chinese": "6. 我在我的卧室里。我听到了我的狗。"}', 13, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20353, 698, '{"english": "He comes back home. I am very excited.", "chinese": "他回到了家。我很兴奋。"}', 14, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20354, 698, '{"english": "7. My dog has a running race.", "chinese": "7. 我的狗有一个跑步比赛，"}', 15, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20355, 698, '{"english": "He runs very fast and wins the race. I am proud.", "chinese": "他跑得很快，赢得了比赛。我很自豪。"}', 16, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20356, 698, '{"english": "B. Let''s talk.", "chinese": "B. 让我们交流一下。"}', 17, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20357, 698, '{"english": "I am going to sing for my class.", "chinese": "我要为我的班级唱歌。"}', 18, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20358, 698, '{"english": "I am proud.", "chinese": "我很自豪。"}', 19, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20359, 698, '{"english": "Today is my birthday.  I am ______.", "chinese": "今天是我的生日。 我______。"}', 20, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20360, 698, '{"english": "My best friend can''t come to my party.", "chinese": "我最好的朋友不能来参加我的聚会。"}', 21, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20361, 698, '{"english": "I am ______.", "chinese": "我______。"}', 22, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20362, 698, '{"english": "My grandma is ill.  I am ______.", "chinese": "我的奶奶病了。 我______。"}', 23, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20363, 698, '{"english": "The dog runs to Mum and me.  I am ______.", "chinese": "这只狗跑向我和妈妈。 我______。"}', 24, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20364, 698, '{"english": "My cousin takes away my model plane. I am ______.", "chinese": "我表弟拿走了我的飞机模型。我______。"}', 25, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20365, 698, '{"english": "C. Let''s write.", "chinese": "C. 我们来写一写吧。"}', 26, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20366, 698, '{"english": "Help me fill in the blanks.", "chinese": "帮我把下面的空格填写完整。"}', 27, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20367, 698, '{"english": "I am going to run. I am ______.", "chinese": "我要跑了。我______。"}', 28, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20368, 698, '{"english": "Bill buys me some meat. I am ______.", "chinese": "比尔给我买了些肉。我______。"}', 29, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20369, 698, '{"english": "I am ill. Bill is ______.", "chinese": "我病了。比尔______。"}', 30, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20370, 698, '{"english": "I am happy because ______.", "chinese": "我很高兴，因为______。"}', 31, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20371, 698, '{"english": "2. Why are you ______ today?", "chinese": "2. 你今天为什么______？"}', 32, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20372, 698, '{"english": "I am ______ because ______.", "chinese": "我是______因为______。"}', 33, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20373, 698, '{"english": "Why?", "chinese": "为什么？"}', 34, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20374, 698, '{"english": "C. Write about your day.", "chinese": "C. 写下你的一天。"}', 35, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20375, 698, '{"english": "My Week", "chinese": "我的一周"}', 36, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20376, 698, '{"english": "Sunday", "chinese": "星期日"}', 37, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20377, 698, '{"english": "Monday", "chinese": "星期一"}', 38, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20378, 698, '{"english": "Tuesday", "chinese": "星期二"}', 39, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20379, 698, '{"english": "Wednesday", "chinese": "星期三"}', 40, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20380, 698, '{"english": "Thursday", "chinese": "星期四"}', 41, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20381, 698, '{"english": "Friday", "chinese": "星期五"}', 42, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20382, 698, '{"english": "Saturday", "chinese": "星期六"}', 43, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20383, 698, '{"english": "D. Read and write.", "chinese": "D. 读一读，写一写。"}', 44, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20384, 698, '{"english": "I wrote about my week like this. What about you?", "chinese": "我这样写我的一周。你呢？"}', 45, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20385, 698, '{"english": "My Week", "chinese": "我的一周"}', 46, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20386, 698, '{"english": "Let me tell you about my week.", "chinese": "让我告诉你我的一周。"}', 47, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20387, 698, '{"english": "I was sad last Monday because I was ill.", "chinese": "上星期一我很难过，因为我病了。"}', 48, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20388, 698, '{"english": "Then on Tuesday I was happy because my friend Linda came to see me.", "chinese": "星期二我很高兴，因为我的朋友琳达来看我。"}', 49, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20389, 698, '{"english": "On Friday I won first place in a writing competition.", "chinese": "星期五我在一次写作比赛中获得了第一名，"}', 50, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20390, 698, '{"english": "I was very proud. My friends were all excited, too.", "chinese": "我很自豪。我的朋友们也都很兴奋。"}', 51, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20391, 698, '{"english": "Checkpoint", "chinese": "检查点"}', 52, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20392, 698, '{"english": "structures", "chinese": "结构"}', 53, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20393, 698, '{"english": "You look ... Why?", "chinese": "你看起来⋯⋯为什么？"}', 54, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20394, 698, '{"english": "I am/was ... because ...", "chinese": "我/曾经⋯⋯因为⋯⋯"}', 55, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20395, 698, '{"english": "vocabulary", "chinese": "词汇"}', 56, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20396, 698, '{"english": "scared", "chinese": "害怕的"}', 57, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20397, 698, '{"english": "worried", "chinese": "担心的"}', 58, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20398, 698, '{"english": "angry", "chinese": "愤怒的"}', 59, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20399, 698, '{"english": "proud", "chinese": "自豪的"}', 60, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20400, 698, '{"english": "sad", "chinese": "伤心的"}', 61, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20401, 698, '{"english": "excited", "chinese": "兴奋的"}', 62, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20402, 698, '{"english": "happy", "chinese": "幸福的"}', 63, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20403, 698, '{"english": "ill", "chinese": "生病的"}', 64, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20404, 698, '{"english": "win", "chinese": "赢"}', 65, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20405, 698, '{"english": "race", "chinese": "比赛"}', 66, '2026-02-05 04:32:18', '2026-02-05 04:32:18');
INSERT INTO "course_content" VALUES (20406, 698, '{"english": "find", "chinese": "找到"}', 67, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20407, 698, '{"english": "cry", "chinese": "哭泣"}', 68, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20408, 698, '{"english": "because", "chinese": "因为"}', 69, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20409, 698, '{"english": "test", "chinese": "测试"}', 70, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20410, 699, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20411, 699, '{"english": "A. Listen and number.", "chinese": "A. 听一听，并编号。"}', 2, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20412, 699, '{"english": "-Hi children, look at these famous people. They did great things. Do you know anything about them?  -This is Li Bai. He was Chinese. He was a poet. He wrote many famous poems. One of his famous poems is ''In the Quiet Night''. -This is Hans Christian Andersen.He was Danish.", "chinese": "—嗨，孩子们，看看这些名人，他们做了伟大的事情。你了解他们吗? —这是李白，他是中国人，他是一个诗人，他写了很多著名的诗。他的一首著名的诗是《静夜思》。—这是汉斯·克里斯蒂安·安徒生，丹麦人。"}', 3, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20413, 699, '{"english": "He was a writer and wrote many stories for children.", "chinese": "他是一位作家，写了许多儿童故事。"}', 4, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20414, 699, '{"english": "I like his story ''the Ugly Duckling''.", "chinese": "我喜欢他的故事《丑小鸭》。"}', 5, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20415, 699, '{"english": "-This is Xu Beihong. He was Chinese.", "chinese": "—这是徐悲鸿。他是中国人，"}', 6, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20416, 699, '{"english": "He was a painter and good at painting horses.", "chinese": "他是一个画家，擅长画马。"}', 7, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20417, 699, '{"english": "-This is Thomas Edison. He was American.", "chinese": "—这是托马斯·爱迪生，他是美国人，"}', 8, '2026-02-05 04:32:19', '2026-02-05 04:32:19');
INSERT INTO "course_content" VALUES (20418, 699, '{"english": "He was an adventure. He invented a lot of things.", "chinese": "他是一个冒险家。他发明了很多东西。"}', 9, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20419, 699, '{"english": "-Very good. Do you know anything about this man?  -No.", "chinese": "—很好，你们了解这个人吗? —不。"}', 10, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20420, 699, '{"english": "-This is Jean-Henri Fabre. He was French.", "chinese": "—这是让-亨利·法布尔，他是法国人，"}', 11, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20421, 699, '{"english": "He was a scientist and studied insects.", "chinese": "他是一名科学家，研究昆虫。"}', 12, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20422, 699, '{"english": "He is famous for his book named ''the Book of Insects''.", "chinese": "他以他的书《昆虫之书》而闻名。"}', 13, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20423, 699, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 14, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20424, 699, '{"english": "What do you know about Li Bai?", "chinese": "你对李白了解多少？"}', 15, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20425, 699, '{"english": "He was Chinese. He was a poet.", "chinese": "他是中国人。他是一位诗人。"}', 16, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20426, 699, '{"english": "He was good at writing poems.", "chinese": "他擅长写诗。"}', 17, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20427, 699, '{"english": "What do you know about Xu Beihong?", "chinese": "你对徐悲鸿了解多少？"}', 18, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20428, 699, '{"english": "He was Chinese, too. He was an artist.", "chinese": "他也是中国人。他是个艺术家，"}', 19, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20429, 699, '{"english": "He was good at painting horses.", "chinese": "他擅长画马。"}', 20, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20430, 699, '{"english": "Li Bai  poet (Chinese)  701 - 762", "chinese": "李白 诗人（中国人） 701 — 762"}', 21, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20431, 699, '{"english": "Xu Beihong  artist (Chinese)  1895 - 1953", "chinese": "徐悲鸿 艺术家（中国人） 1895 — 1953"}', 22, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20432, 699, '{"english": "C. Let''s write.", "chinese": "C. 我们来写一写。"}', 23, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20433, 699, '{"english": "Look at the above posters,", "chinese": "请看上面的海报，"}', 24, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20434, 699, '{"english": "and fill in the following blanks.", "chinese": "并填空。"}', 25, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20435, 699, '{"english": "This is Li Bai. He was ______.", "chinese": "我是李白。他是______。"}', 26, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20436, 699, '{"english": "He was a ______.  He was good at ______.", "chinese": "他是一个______。 他很擅长______。"}', 27, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20437, 699, '{"english": "This is Xu Beihong. He was ______.", "chinese": "我是徐悲鸿。他是______。"}', 28, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20438, 699, '{"english": "He was an ______.  He was good at ______.", "chinese": "他是一个______。 他很擅长______。"}', 29, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20439, 699, '{"english": "1. What was Marie''s full name?", "chinese": "1. 玛丽的全名是什么？"}', 30, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20440, 699, '{"english": "2. What did she like to do when she was a little girl?", "chinese": "2. 她小时候喜欢做什么？"}', 31, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20441, 699, '{"english": "3. What did she do when her sister played jokes behind her?", "chinese": "3. 当她姐姐在她背后开玩笑时，她做了什么？"}', 32, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20442, 699, '{"english": "4. What did she do when she grew up?", "chinese": "4. 她长大后做了什么？"}', 33, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20443, 699, '{"english": "5. What do you learn from the story?", "chinese": "5. 你从这个故事中学到了什么？"}', 34, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20444, 699, '{"english": "C. Let''s talk.", "chinese": "C. 我们说一说。"}', 35, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20445, 699, '{"english": "Who''s your favourite famous person?", "chinese": "你最喜欢的名人是谁？"}', 36, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20446, 699, '{"english": "It''s Hans Christian Andersen. He was a Danish writer.", "chinese": "是汉斯·克里斯蒂安·安徒生。他是一位丹麦作家。"}', 37, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20447, 699, '{"english": "Why is he famous?", "chinese": "他为什么出名？"}', 38, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20448, 699, '{"english": "Beethoven can write music, because he can''t do anything else!", "chinese": "贝多芬可以作曲，因为他别的什么都不会！"}', 39, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20449, 699, '{"english": "B. Match the people to their jobs and their stories.", "chinese": "B. 把人们和他们的工作和故事联系起来。"}', 40, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20450, 699, '{"english": "name", "chinese": "名字"}', 41, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20451, 699, '{"english": "J.K. Rowling", "chinese": "J.K. 罗琳"}', 42, '2026-02-05 04:32:20', '2026-02-05 04:32:20');
INSERT INTO "course_content" VALUES (20452, 700, '{"english": "Lesson 1", "chinese": "第 1 课"}', 1, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20453, 700, '{"english": "A. Listen and write.", "chinese": "A. 听一听，写一写。"}', 2, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20454, 700, '{"english": "-Hi, Bin Bin. What are you doing?", "chinese": "—你好,彬彬。你在干什么?"}', 3, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20455, 700, '{"english": "-I''m making a plan for my winter vacation. It starts this Monday.", "chinese": "—我正在为我的寒假制定一个计划。这个星期一开始。"}', 4, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20456, 700, '{"english": "I can''t wait.  -What are you going to do?", "chinese": "我等不及了。 —你要做什么?"}', 5, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20457, 700, '{"english": "-A lot of things.", "chinese": "—很多事情。"}', 6, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20458, 700, '{"english": "From January sixteenth to twenty-eighth, I''m going to skating classes.", "chinese": "从 1 月 16 日到 28 日，我要去上滑冰课。"}', 7, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20459, 700, '{"english": "On the twenty-second, we''re going to Harbin, so I need a practice skating.", "chinese": "22 号，我们要去哈尔滨，所以我需要练习滑冰。"}', 8, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20460, 700, '{"english": "I''m going to play in the snow there with my cousin.", "chinese": "我要和我的表弟在那里玩雪。"}', 9, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20461, 700, '{"english": "After we come back, I''m going to watch a football match.", "chinese": "我们回来后，我要去看一场足球比赛。"}', 10, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20462, 700, '{"english": "You know I''m a football fan.  -What else?", "chinese": "你知道我是个足球迷。 —有什么其他的吗?"}', 11, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20463, 700, '{"english": "-Spring Festival is coming in February. I''m going to help you do some chores.", "chinese": "—春节将在二月到来。我要帮你做些家务。"}', 12, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20464, 700, '{"english": "We''re also going to visit my grandparents.", "chinese": "我们也要去看望我的祖父母。"}', 13, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20465, 700, '{"english": "And I''m going to learn to make dumplings.  -Oh, you''ll have a great vacation.", "chinese": "我要学习包饺子。 —哦，你的假期会很愉快的。"}', 14, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20466, 700, '{"english": "B. Let''s talk.", "chinese": "B. 我们谈一谈。"}', 15, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20467, 700, '{"english": "What are you going to do in your winter vacation?", "chinese": "你寒假打算做什么？"}', 16, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20468, 700, '{"english": "I''m going to learn Chinese painting. I love painting.", "chinese": "我要学中国画。我喜欢绘画。"}', 17, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20469, 700, '{"english": "I''m going to train for a basketball match.", "chinese": "我要为一场篮球赛而训练。"}', 18, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20470, 700, '{"english": "I''m a sports fan.", "chinese": "我是个体育迷。"}', 19, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20471, 700, '{"english": "A Plan for My Winter Vacation", "chinese": "我的寒假计划"}', 20, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20472, 700, '{"english": "I don''t like cold weather. I''m afraid of getting a cold.", "chinese": "我不喜欢寒冷的天气。我害怕得感冒。"}', 21, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20473, 700, '{"english": "Oh, you''ll be fine.", "chinese": "哦，你不会生病的。"}', 22, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20474, 700, '{"english": "What are you going to do there?", "chinese": "你们要去那里做什么？"}', 23, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20475, 700, '{"english": "We''re going to see ice lanterns and play in the snow.", "chinese": "我们要去看冰灯，在雪地里玩耍。"}', 24, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20476, 700, '{"english": "My uncle''s family live there.", "chinese": "我的叔叔家在那里。"}', 25, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20477, 700, '{"english": "We want some figgy pudding.  Please bring it right here!", "chinese": "我们要一些无花果布丁。 请把它拿过来！"}', 26, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20478, 700, '{"english": "Glad tidings we bring To you and your kin, Glad tidings for Christmas And a Happy New Year!", "chinese": "请把它拿过来！我们带给您和您的亲人喜讯，"}', 27, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20479, 700, '{"english": "We won''t go until we get some.", "chinese": "在得到无花果布丁之前，我们不会去的。"}', 28, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20480, 700, '{"english": "We won''t go until we get some.", "chinese": "在得到无花果布丁之前，我们不会去的。"}', 29, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20481, 700, '{"english": "We won''t go until we get some.", "chinese": "在得到无花果布丁之前，我们不会去的。"}', 30, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20482, 700, '{"english": "So bring it out here!", "chinese": "所以请拿过来！"}', 31, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20483, 700, '{"english": "Glad tidings we bring To you and your kin, Glad tidings for Christmas And a Happy New Year!", "chinese": "我们带给您和您的亲人喜讯，我们祝你圣诞快乐。新年快乐。"}', 32, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20484, 700, '{"english": "We wish you a merry Christmas.", "chinese": "我们祝你圣诞快乐。"}', 33, '2026-02-05 04:32:21', '2026-02-05 04:32:21');
INSERT INTO "course_content" VALUES (20485, 700, '{"english": "2. Fill in the chart.", "chinese": "2. 填写表格。"}', 34, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20486, 701, '{"english": "Revision 2", "chinese": "复习 2"}', 1, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20487, 701, '{"english": "Let''s Review", "chinese": "让我们复习吧"}', 2, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20488, 701, '{"english": "A. Listen, write and tick.", "chinese": "A. 听一听，写一写，勾一勾。"}', 3, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20489, 701, '{"english": "-Hi Joy, you look so worried.", "chinese": "—嗨，乔伊，你看起来很担心。"}', 4, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20490, 701, '{"english": "-Yes, I''m worried because I can''t do my homework.", "chinese": "—是的，我很担心，因为我不能做作业了。"}', 5, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20491, 701, '{"english": "-Don''t worry, I''ll help you. But first let me tell you something exciting.", "chinese": "—别担心，我会帮你的。但首先让我告诉你一件激动人心的事。"}', 6, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20492, 701, '{"english": "I went to the cinema yesterday and Jackie Chan was there.", "chinese": "我昨天去看电影，成龙在那里。"}', 7, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20493, 701, '{"english": "I was really surprised.", "chinese": "我真的很惊讶。"}', 8, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20494, 701, '{"english": "I liked his movies, but I never met him before.", "chinese": "我喜欢他的电影，但我以前从未见过他。"}', 9, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20495, 701, '{"english": "-That''s great. I like his movies, too.", "chinese": "—太好了。我也喜欢他的电影。"}', 10, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20496, 701, '{"english": "-Do you want to be famous like Jackie Chan someday?  -Yes, I do.", "chinese": "—你想成为像成龙一样出名的人吗? —是的,我想。"}', 11, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20497, 701, '{"english": "B. Choose and talk.", "chinese": "B. 选择，并说一说。"}', 12, '2026-02-05 04:32:22', '2026-02-05 04:32:22');
INSERT INTO "course_content" VALUES (20498, 701, '{"english": "1. You are going to have a test tomorrow.", "chinese": "1. 你明天要考试。"}', 13, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20499, 701, '{"english": "2. Your team/class won a football game.", "chinese": "2. 你的队/班赢了一场足球赛。"}', 14, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20500, 701, '{"english": "3. Your best friends can''t come to your birthday party.", "chinese": "3. 你最好的朋友不能来参加你的生日聚会。"}', 15, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20501, 701, '{"english": "4. Your pet cat is ill today.", "chinese": "你的宠物猫今天病了。"}', 16, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20502, 701, '{"english": "You look worried.", "chinese": "你看起来很担心。"}', 17, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20503, 701, '{"english": "Yes, I am.", "chinese": "是的，我很担心。"}', 18, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20504, 701, '{"english": "I am worried because I''m going to have a maths test tomorrow.", "chinese": "因为我明天要参加数学考试。"}', 19, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20505, 701, '{"english": "Maths is always difficult for me.", "chinese": "数学对我来说总是很困难。"}', 20, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20506, 701, '{"english": "Don''t wory. You''ll be OK.", "chinese": "别担心。会顺利的。"}', 21, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20507, 701, '{"english": "Thank you. I''ll try.", "chinese": "非常感谢。我会尽力。"}', 22, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20508, 701, '{"english": "C. Think and write.", "chinese": "C. 想一想，写一写。"}', 23, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20509, 701, '{"english": "November 11 Rating:", "chinese": "11 月 11 日 评估："}', 24, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20510, 701, '{"english": "Dear Diary,  I had a bad day today.", "chinese": "亲爱的日记，我今天过得很糟，"}', 25, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20511, 701, '{"english": "My pet turtle is very sick today. I am worried.", "chinese": "我的宠物乌龟今天病得很重。我很担心。"}', 26, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20512, 701, '{"english": "This morning, I forgot my homework. Miss Wu was angry.", "chinese": "今天早上我忘了我的作业。吴老师很生气。"}', 27, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20513, 702, '{"english": "I went to the city of Beijing.", "chinese": "我去了北京。"}', 1, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20514, 702, '{"english": "I went to the city of Beijing.", "chinese": "我去了北京。"}', 2, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20515, 702, '{"english": "I went to the city of Beijing.", "chinese": "我去了北京。"}', 3, '2026-02-05 04:32:23', '2026-02-05 04:32:23');
INSERT INTO "course_content" VALUES (20516, 702, '{"english": "What''s Beijing famous for?   It''s famous for Tian anmen Square.", "chinese": "北京以什么闻名？  它以天安门广场闻名。"}', 4, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20517, 702, '{"english": "It''s famous for the Great Wall.  It''s famous for Beijing duck.", "chinese": "它以长城闻名。 它以烤鸭闻名。"}', 5, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20518, 702, '{"english": "That''s what it''s famous for.", "chinese": "这就是它闻名的地方"}', 6, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20519, 702, '{"english": "What do you know about London town?", "chinese": "你对伦敦城了解多少？"}', 7, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20520, 702, '{"english": "It''s famous for the Big Ben clock.", "chinese": "它以大本钟而闻名。"}', 8, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20521, 702, '{"english": "What do you know about Toronto?  It''s famous for the CN Tower.", "chinese": "你对多伦多了解多少？ 它以加拿大国家电视塔而闻名。"}', 9, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20522, 702, '{"english": "What do you know about Sydney Town?  It''s famous for the Opera House.", "chinese": "你对悉尼了解多少？ 它以歌剧院而闻名。"}', 10, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20523, 702, '{"english": "What do you know about Beijing city?  It''s famous for the Summer Palace.", "chinese": "你对北京了解多少？ 它以颐和园而闻名。"}', 11, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20524, 702, '{"english": "What kind of animal is a penguin?", "chinese": "企鹅是什么动物？"}', 12, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20525, 702, '{"english": "Is it a fish or a bird?  Is it a reptile or a mammal?", "chinese": "是鱼还是鸟？ 它是爬行动物还是哺乳动物？"}', 13, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20526, 702, '{"english": "A penguin is a bird. take my word.", "chinese": "听我说，企鹅是鸟。"}', 14, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20527, 702, '{"english": "What kind of animal is a blue whale?", "chinese": "蓝鲸是什么动物？"}', 15, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20528, 702, '{"english": "Is it a fish or a bird?  Is it a reptile or a mammal?", "chinese": "是鱼还是鸟？ 它是爬行动物还是哺乳动物？"}', 16, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20529, 702, '{"english": "A whale is a mammal, take my word.", "chinese": "听我说，鲸鱼是哺乳动物。"}', 17, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20530, 702, '{"english": "You look so happy.  You look excited.", "chinese": "你看起来很开心。你看起来很兴奋。"}', 18, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20531, 702, '{"english": "Why are you so proud on this fine day?", "chinese": "你为什么对这一天如此自豪？"}', 19, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20532, 702, '{"english": "Why are you happy?  Why are you so proud?", "chinese": "为什么你很高兴？ 你为什么这么骄傲？"}', 20, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20533, 702, '{"english": "Because I passed my test today.", "chinese": "因为我今天通过了我的测试。"}', 21, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20534, 702, '{"english": "You look so angry.  You look so worried.", "chinese": "你看起来很生气。 你看起来很担心。"}', 22, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20535, 702, '{"english": "Why are you so sad on this hot today?", "chinese": "在这炎热的日子你为什么这么伤心？"}', 23, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20536, 702, '{"english": "Why are you angry?  Why are you so sad?", "chinese": "你为什么生气？ 你为什么这么伤心？"}', 24, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20537, 702, '{"english": "Because it''s going to rain all day.", "chinese": "因为一整天都要下雨了。"}', 25, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20538, 702, '{"english": "He was a famous man.  Yes, he was.", "chinese": "他是个名人。 是的。"}', 26, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20539, 702, '{"english": "He was an American.  Yes, he was.  He was an inventor.", "chinese": "他是美国人。 是的。 他是发明家。"}', 27, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20540, 702, '{"english": "Yes, he was.  His name was Thomas Edison.", "chinese": "是的。 他叫托马斯·爱迪生。"}', 28, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20541, 702, '{"english": "He was a famous man.  Yes, he was.", "chinese": "他是个名人。 是的。"}', 29, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20542, 702, '{"english": "He was an Englishman.  Yes, he was.", "chinese": "他是个英国人。 是的。"}', 30, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20543, 702, '{"english": "He was a scientist.  Yes, he was.", "chinese": "他是个科学家。 是的。"}', 31, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20544, 702, '{"english": "His name was Sir Isaac Newton.", "chinese": "他叫艾萨克·牛顿。"}', 32, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20545, 702, '{"english": "He was a famous man.  Yes, he was.", "chinese": "他是个名人。 是的。"}', 33, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
INSERT INTO "course_content" VALUES (20546, 702, '{"english": "He was a Chinese man.  Yes, he was.", "chinese": "他是一个中国人。 是的。"}', 34, '2026-02-05 04:32:24', '2026-02-05 04:32:24');
