INSERT INTO "course_content" VALUES (20642, 705, '{"english": "Unit 1", "chinese": "第 1 单元"}', 1, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20643, 705, '{"english": "Visiting Canada", "chinese": "参观加拿大"}', 2, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20644, 705, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20645, 705, '{"english": "A. Listen and number.", "chinese": "A. 听一听，并编号。"}', 4, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20646, 705, '{"english": "It''s January.", "chinese": "一月了。"}', 5, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20647, 705, '{"english": "Bill is getting ready for a trip to Canada.", "chinese": "比尔准备去加拿大旅行。"}', 6, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20648, 705, '{"english": "-I''m leaving for Canada this Sunday,", "chinese": "—这个星期天我要去加拿大，"}', 7, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20649, 705, '{"english": "what clothes should I take with me?", "chinese": "我应该带什么衣服？"}', 8, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20650, 705, '{"english": "-You''d better phone Ted and ask him.   Bill dials the number.", "chinese": "—你最好给特德打电话问问他。  比尔拨了号码。"}', 9, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20651, 705, '{"english": "-Hello, this is Ted.  -Hello! Ted, this is Bill.", "chinese": "—你好，我是泰德。—你好，泰德，我是比尔。"}', 10, '2026-02-05 04:32:29', '2026-02-05 04:32:29');
INSERT INTO "course_content" VALUES (20652, 705, '{"english": "I''m calling to ask what clothes I should take to Canada.", "chinese": "我打电话是想问我该带什么衣服去加拿大。"}', 11, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20653, 705, '{"english": "What''s the weather like in Canada?", "chinese": "加拿大的天气怎么样？"}', 12, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20654, 705, '{"english": "What do you usually wear in winter?", "chinese": "你冬天通常穿什么？"}', 13, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20655, 705, '{"english": "-It''s January now and it''s very cold.", "chinese": "—现在是一月，天气很冷。"}', 14, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20656, 705, '{"english": "I usually wear a sweater or a jacket in my house.", "chinese": "我通常在家里穿毛衣或夹克。"}', 15, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20657, 705, '{"english": "But I wear a hat, a scarf, gloves, boots and a warm coat when I go out.", "chinese": "但我出门时戴着帽子、围巾、手套，穿靴子和暖和的外套。"}', 16, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20658, 705, '{"english": "-What else should I take with me?", "chinese": "—我还应该带什么？"}', 17, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20659, 705, '{"english": "-You are going to stay here for five months.", "chinese": "—你要在这里住五个月。"}', 18, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20660, 705, '{"english": "You need clothes for spring and summer, such as jackets, trousers, sweaters, shorts and T-shirts.", "chinese": "你需要穿春天和夏天的衣服，比如夹克、裤子、毛衣、短裤和T恤。"}', 19, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20661, 705, '{"english": "You can also borrow some of my clothes if you need.", "chinese": "如果你需要的话，你也可以找我借一些衣服。"}', 20, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20662, 705, '{"english": "-Thanks Ted. See you on Sunday.  -OK. I''ll meet you at Toronto airport.", "chinese": "—谢谢，泰德。周日见。 —好的。我在多伦多机场接你。"}', 21, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20663, 705, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 22, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20664, 705, '{"english": "1. Where is Bill going?", "chinese": "1. 比尔要去哪里？"}', 23, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20665, 705, '{"english": "2. When is he going there?", "chinese": "2. 他什么时候去那里？"}', 24, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20666, 705, '{"english": "3. What''s the weather like there?", "chinese": "3. 那里的天气怎么样？"}', 25, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20667, 705, '{"english": "4. What should Bill take with him?", "chinese": "4. 比尔应该随身携带什么？"}', 26, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20668, 705, '{"english": "Where is Bill going?", "chinese": "比尔要去哪里？"}', 27, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20669, 705, '{"english": "He''s going to Canada.", "chinese": "他要去加拿大。"}', 28, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20670, 705, '{"english": "Pretend you are going to one of these places.", "chinese": "假装你要去下列其中的一个地方。"}', 29, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20671, 705, '{"english": "What is the weather like there?", "chinese": "那里的天气怎么样？"}', 30, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20672, 705, '{"english": "What clothes should you take with you?", "chinese": "你应该带什么衣服？"}', 31, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20673, 705, '{"english": "winter", "chinese": "冬天"}', 32, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20674, 705, '{"english": "Paris, windy & snowy  2℃-9℃", "chinese": "巴黎，刮风 & 下雪 2℃-9℃"}', 33, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20675, 705, '{"english": "winter", "chinese": "冬天"}', 34, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20676, 705, '{"english": "Hangzhou, rainy  1℃-8℃", "chinese": "杭州，下雨 1℃-8℃"}', 35, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20677, 705, '{"english": "summer", "chinese": "夏天"}', 36, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20678, 705, '{"english": "Sydney, clear  20℃-28℃", "chinese": "悉尼，晴朗 20℃-28℃"}', 37, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20679, 705, '{"english": "C. Let''s read.", "chinese": "C. 让我们读一读。"}', 38, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20680, 705, '{"english": "Bill is going to Canada and is going to stay there for five months.", "chinese": "比尔将要去加拿大待五个月。"}', 39, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20681, 705, '{"english": "He is going to stay at Ted''s house.", "chinese": "他将住在泰德的家。"}', 40, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20682, 705, '{"english": "Ted lives with his parents and his sister Tina.", "chinese": "泰德和他的父母、妹妹蒂娜生活在一起。"}', 41, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20683, 705, '{"english": "Bill is also going to go to Ted''s school.", "chinese": "比尔也要去泰德的学校。"}', 42, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20684, 705, '{"english": "He is very excited.", "chinese": "他很兴奋。"}', 43, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20685, 705, '{"english": "Bill also feel quite sad. He will miss his teachers and friends.", "chinese": "比尔也觉得很难过。他会想念他的老师和朋友们。"}', 44, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20686, 705, '{"english": "He has a going away party at school.", "chinese": "在学校的欢送会上。"}', 45, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20687, 705, '{"english": "He says goodbye to everyone.", "chinese": "比尔向他的每一位朋友告别。"}', 46, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20688, 705, '{"english": "Bill''s friends say they will email him every week.", "chinese": "比尔的朋友们说他们将会每个星期都给他发邮件。"}', 47, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20689, 705, '{"english": "It is very cold and snowy in Canada in the winter.", "chinese": "加拿大的冬天是非常寒冷和多雪的。"}', 48, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20690, 705, '{"english": "Bill takes some sweaters, scarves and a warm coat.", "chinese": "比尔带了一些毛衣、围巾和一件暖和的外套。"}', 49, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20691, 705, '{"english": "He''s going to be in Canada in the spring and summer too,", "chinese": "他要在加拿大度过春天和夏天，"}', 50, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20692, 705, '{"english": "so he also takes T-shirts and shorts.", "chinese": "所以他也带了 T 恤衫和短裤。"}', 51, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20693, 705, '{"english": "Bill will miss his father and mother,", "chinese": "比尔会想念他的父亲和母亲，"}', 52, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20694, 705, '{"english": "so he takes a photo of his family.", "chinese": "所以他带了他的一张全家福。"}', 53, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20695, 705, '{"english": "Answer the questions. Write down your answers in your notebook.", "chinese": "回答问题。把你的答案写在笔记本上。"}', 54, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20696, 705, '{"english": "1. How long is Bill going to stay in Canada?", "chinese": "1. 比尔将在加拿大待多久？"}', 55, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20697, 705, '{"english": "2. How does Bill feel?", "chinese": "2. 比尔感觉如何？"}', 56, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20698, 705, '{"english": "3. How many people are there in Ted''s family?", "chinese": "3. 泰德家有多少人？"}', 57, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20699, 705, '{"english": "Who are they?", "chinese": "他们是谁？"}', 58, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20700, 705, '{"english": "4. What is the weather like in Canada in the winter?", "chinese": "4. 加拿大冬天的天气怎么样？"}', 59, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20701, 705, '{"english": "5.", "chinese": "5."}', 60, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20702, 705, '{"english": "What winter clothes is Bill going to take to Canada?", "chinese": "比尔打算带什么冬衣去加拿大？"}', 61, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20703, 705, '{"english": "D. Let''s write.", "chinese": "D. 让我们写一写。"}', 62, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20704, 705, '{"english": "Pretend you are going to Canada or another country.", "chinese": "假装你要去加拿大或其他国家。"}', 63, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20705, 705, '{"english": "What are you going to take with you?", "chinese": "你要带什么？"}', 64, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20706, 705, '{"english": "I am going to Toronto this weekend.", "chinese": "这个周末我要去多伦多。"}', 65, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20707, 705, '{"english": "I need to take some clothes for winter,spring and summer.", "chinese": "我需要带一些冬春夏的衣服。"}', 66, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20708, 705, '{"english": "I also want to take my favourite books,", "chinese": "我还想带上我最喜欢的书，"}', 67, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20709, 705, '{"english": "a photo of my family and ... Oh, so many things!", "chinese": "一张我家人的照片，还有⋯⋯哦，这么多东西！"}', 68, '2026-02-05 04:32:30', '2026-02-05 04:32:30');
INSERT INTO "course_content" VALUES (20710, 706, '{"english": "Unit 2", "chinese": "第 2 单元"}', 1, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20711, 706, '{"english": "All Around Me", "chinese": "我周围的事物"}', 2, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20712, 706, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20713, 706, '{"english": "A. Listen and number.", "chinese": "A. 听一听，标序号。"}', 4, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20714, 706, '{"english": "Ted is showing Bill around the city.", "chinese": "泰德正在带比尔参观这座城市。"}', 5, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20715, 706, '{"english": "-Ted, I want send a postcard to my parents.", "chinese": "—特德，我想给我父母寄张明信片。"}', 6, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20716, 706, '{"english": "Is there a post office near our house?", "chinese": "我们家附近有邮局吗？"}', 7, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20717, 706, '{"english": "-Yes, there is. I''ll take you there.", "chinese": "—是的，有。我带你去。"}', 8, '2026-02-05 04:32:31', '2026-02-05 04:32:31');
INSERT INTO "course_content" VALUES (20718, 706, '{"english": "I can show you some of the city, too.", "chinese": "我也可以带你看看这个城市。"}', 9, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20719, 706, '{"english": "Let''s go straight and turn right at the second crossroads.", "chinese": "我们直走，在第二个十字路口右转。"}', 10, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20720, 706, '{"english": "The post office is on the left.", "chinese": "邮局在左边。"}', 11, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20721, 706, '{"english": "-There it is, Ted.", "chinese": "—在那里，特德。"}', 12, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20722, 706, '{"english": "What''s that building next to the post office?", "chinese": "邮局旁边的那栋楼是什么？"}', 13, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20723, 706, '{"english": "Is it a bookshop?  -No, it''s a coffee shop.  -Look!", "chinese": "是书店吗？ —不，是咖啡馆。 —看！"}', 14, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20724, 706, '{"english": "Over there you can see a public library.", "chinese": "那边你可以看到一个公共图书馆。"}', 15, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20725, 706, '{"english": "It has many kinds of books.  -That''s cool.", "chinese": "它有很多种书。 —太酷了。"}', 16, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20726, 706, '{"english": "Look at that building over there.  -What is it?", "chinese": "看那边的那栋楼。 —是什么？"}', 17, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20727, 706, '{"english": "-It''s an art gallery.", "chinese": "—是一家美术馆。"}', 18, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20728, 706, '{"english": "You can see Uncle Bob''s paintings there.", "chinese": "你可以在那里看到鲍勃叔叔的画。"}', 19, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20729, 706, '{"english": "But now let''s go to Queen''s Park.", "chinese": "但是现在我们去皇后公园吧。"}', 20, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20730, 706, '{"english": "It''s really famous and there are many trees there.", "chinese": "它真的很有名，那里有很多树。"}', 21, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20731, 706, '{"english": "-Oh, look! There''s a Chinese restaurant. I miss Chinese food.", "chinese": "—哦，看！这有一家中国餐馆。我想念中国菜。"}', 22, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20732, 706, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 23, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20733, 706, '{"english": "Is there a library?", "chinese": "有图书馆吗？"}', 24, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20734, 706, '{"english": "Yes, there is.", "chinese": "是的，有。"}', 25, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20735, 706, '{"english": "How can I get there?", "chinese": "我怎么去那里？"}', 26, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20736, 706, '{"english": "It''s on Pear Street. Go straight.", "chinese": "在梨街。直走。"}', 27, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20737, 706, '{"english": "Turn left at the second crossroads. The library is on the right.", "chinese": "在第二个十字路口向左拐。图书馆在右边。"}', 28, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20738, 706, '{"english": "supermarket", "chinese": "超市"}', 29, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20739, 706, '{"english": "Pear Street", "chinese": "梨街"}', 30, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20740, 706, '{"english": "Apple Street", "chinese": "苹果街"}', 31, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20741, 706, '{"english": "school", "chinese": "学校"}', 32, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20742, 706, '{"english": "park", "chinese": "公园"}', 33, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20743, 706, '{"english": "grocery", "chinese": "杂货店"}', 34, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20744, 706, '{"english": "post office", "chinese": "邮局"}', 35, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20745, 706, '{"english": "Banana Street", "chinese": "香蕉街"}', 36, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20746, 706, '{"english": "sports centre", "chinese": "体育中心"}', 37, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20747, 706, '{"english": "Map 2: see on Page 63.", "chinese": "地图 2：见第 63 页。"}', 38, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20748, 706, '{"english": "WORD BOX", "chinese": "单词盒子"}', 39, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20749, 706, '{"english": "library  restaurant", "chinese": "图书馆 餐厅"}', 40, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20750, 706, '{"english": "C. Let''s read.", "chinese": "C. 让我们读一读。"}', 41, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20751, 706, '{"english": "Ted is telling Bill about Yonge Street.", "chinese": "泰德正在告诉比尔关于央街的事。"}', 42, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20752, 706, '{"english": "There are many beautiful buildings in downtown Toronto.", "chinese": "在多伦多市中心有许多美丽的建筑物。"}', 43, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20753, 706, '{"english": "Yonge Street is the longest street in Canada.", "chinese": "央街是加拿大最长的街道。"}', 44, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20754, 706, '{"english": "There are a lot of shops on this street.", "chinese": "在这条街道上有很多商店。"}', 45, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20755, 706, '{"english": "My favourite bookshop is there.", "chinese": "我最喜欢的书店就在那里。"}', 46, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20756, 706, '{"english": "Next to the bookshop is a cinema,", "chinese": "在书店旁边是一个电影院，"}', 47, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20757, 706, '{"english": "and there is a bank next to the cinema.", "chinese": "电影院旁边有一个银行。"}', 48, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20758, 706, '{"english": "Across from the cinema there is a library.", "chinese": "穿过电影院有一个图书馆。"}', 49, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20759, 706, '{"english": "There is a big lake in Toronto called Lake Ontario.", "chinese": "在多伦多有一个很大的湖泊，被称为安大略湖。"}', 50, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20760, 706, '{"english": "You can see the sports stadium near the lake.", "chinese": "在湖的附近你可以看到一个体育场。"}', 51, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20761, 706, '{"english": "The CN Tower is near the stadium.", "chinese": "加拿大国家电视塔在体育场附近。"}', 52, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20762, 706, '{"english": "There is a famous restaurant next to the stadium.", "chinese": "体育场旁边有一家很有名的餐厅。"}', 53, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20763, 706, '{"english": "If you get lost, you can go to the police station.", "chinese": "如果你迷路了，你可以去警察局。"}', 54, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20764, 706, '{"english": "It''s near the park, next to the subway station.", "chinese": "它离公园很近，在地铁站的旁边。"}', 55, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20765, 706, '{"english": "Write the names of the buildings in the blanks.", "chinese": "在空白处写下建筑物的名称。"}', 56, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20766, 706, '{"english": "bookshop", "chinese": "书店"}', 57, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20767, 706, '{"english": "Yonge Street", "chinese": "央街"}', 58, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20768, 706, '{"english": "park", "chinese": "公园"}', 59, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20769, 706, '{"english": "subway station", "chinese": "地铁站"}', 60, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20770, 706, '{"english": "Lake Ontario", "chinese": "安大略湖"}', 61, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20771, 706, '{"english": "sports stadium", "chinese": "体育场"}', 62, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20772, 706, '{"english": "D. Let''s write.", "chinese": "D. 我们写一写。"}', 63, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20773, 706, '{"english": "Draw a map of your neighbourhood and write about it.", "chinese": "画一张你的社区地图并写下来。"}', 64, '2026-02-05 04:32:32', '2026-02-05 04:32:32');
INSERT INTO "course_content" VALUES (20774, 707, '{"english": "Unit 3", "chinese": "第 3 单元"}', 1, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20775, 707, '{"english": "Daily Life", "chinese": "日常生活"}', 2, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20776, 707, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20777, 707, '{"english": "A. Listen and write the times.", "chinese": "A. 听录音，写时间。"}', 4, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20778, 707, '{"english": "Hello, I''m Bill.", "chinese": "哈喽，我是比尔。"}', 5, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20779, 707, '{"english": "I am a student in Willow Primary School.", "chinese": "我是威洛小学的学生。"}', 6, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20780, 707, '{"english": "I live in my friend Ted''s home.", "chinese": "我住在我的朋友泰德家。"}', 7, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20781, 707, '{"english": "Ted and I get up at same time and then we go to school together.", "chinese": "泰德和我同时起床，然后我们一起上学。"}', 8, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20782, 707, '{"english": "We usually get up at 7:00 in the morning.", "chinese": "我们通常早上七点起床。"}', 9, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20783, 707, '{"english": "We have breakfast at 7:30.", "chinese": "我们七点半吃早餐。"}', 10, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20784, 707, '{"english": "Then we catch the bus to school.", "chinese": "然后我们乘公共汽车去学校。"}', 11, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20785, 707, '{"english": "School starts at 9:00 and ends at 3:30 in the afternoon.", "chinese": "学校九点开始上课，下午三点半放学。"}', 12, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20786, 707, '{"english": "We have five classes a day.", "chinese": "我们每天有五节课。"}', 13, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20787, 707, '{"english": "After school we often play sports for an hour.", "chinese": "放学后，我们经常运动一个小时。"}', 14, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20788, 707, '{"english": "We usually get home at 5:00.", "chinese": "我们通常五点到家。"}', 15, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20789, 707, '{"english": "We have dinner at 6:30.", "chinese": "我们六点半吃晚饭。"}', 16, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20790, 707, '{"english": "After dinner we often go for a walk and then read books.", "chinese": "晚饭后我们经常出去散步，然后看书。"}', 17, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20791, 707, '{"english": "Sometimes I teach him Chinese. Chinese is difficult for Ted.", "chinese": "有时我教他中文。中文对泰德来说很难。"}', 18, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20792, 707, '{"english": "We usually go to bed at 9:45.", "chinese": "我们通常九点四十五分上床睡觉。"}', 19, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20793, 707, '{"english": "What''s your daily schedule?", "chinese": "你每天的日程安排是什么？"}', 20, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20794, 707, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 21, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20795, 707, '{"english": "First, talk about Bill''s life in Canada.", "chinese": "首先，谈谈比尔在加拿大的生活。"}', 22, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20796, 707, '{"english": "1. When does Bill get up?", "chinese": "1. 比尔什么时候起床？"}', 23, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20797, 707, '{"english": "2. How does Bill go to school?", "chinese": "2. 比尔如何去上学？"}', 24, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20798, 707, '{"english": "3. How many classes does Bill have at school?", "chinese": "3. 比尔在学校有几节课？"}', 25, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20799, 707, '{"english": "4. When does Bill come back home?", "chinese": "4. 比尔什么时候回家？"}', 26, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20800, 707, '{"english": "5. What does Bill do after dinner?", "chinese": "5. 比尔晚饭后做什么？"}', 27, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20801, 707, '{"english": "Now, talk with you partner about your lives and fill in the chart.", "chinese": "现在，与你的搭档谈谈你的生活并填写表格。"}', 28, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20802, 707, '{"english": "When do you .../who", "chinese": "你什么时候⋯⋯/谁"}', 29, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20803, 707, '{"english": "your name", "chinese": "你的名字"}', 30, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20804, 707, '{"english": "your partner''s name", "chinese": "你搭档的名字"}', 31, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20805, 707, '{"english": "get up", "chinese": "起床"}', 32, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20806, 707, '{"english": "have breakfast", "chinese": "吃早餐"}', 33, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20807, 707, '{"english": "go to school", "chinese": "去上学"}', 34, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20808, 707, '{"english": "go home", "chinese": "回家"}', 35, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20809, 707, '{"english": "go to bed", "chinese": "去睡觉"}', 36, '2026-02-05 04:32:34', '2026-02-05 04:32:34');
INSERT INTO "course_content" VALUES (20810, 707, '{"english": "C. Let''s read and match.", "chinese": "C. 让我们读一读，连一连。"}', 37, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20811, 707, '{"english": "Bill, what do you do on weekends in China?", "chinese": "比尔，在中国你周末一般做什么？"}', 38, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20812, 707, '{"english": "On Saturday mornings, I always go to my maths club.", "chinese": "星期六早上，我总是去数学俱乐部。"}', 39, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20813, 707, '{"english": "On Saturday afternoons,", "chinese": "星期六下午，"}', 40, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20814, 707, '{"english": "I often stay at home and do my homework.", "chinese": "我经常在家里做作业。"}', 41, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20815, 707, '{"english": "Sometimes I go shopping or go to the cinema with my mum.", "chinese": "有时候我和妈妈去购物或者看电影。"}', 42, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20816, 707, '{"english": "What about Sunday?", "chinese": "星期日呢？"}', 43, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20817, 707, '{"english": "On Sunday mornings, I always do my homework and then watch TV or play computer games.", "chinese": "星期日早上，我总是做我的家庭作业，然后看电视或玩电脑游戏。"}', 44, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20818, 707, '{"english": "Sometimes I help my mum do the dishes.", "chinese": "有时我帮助妈妈洗碗。"}', 45, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20819, 707, '{"english": "On Sunday afternoons, I always play sports.", "chinese": "星期日下午，我总是去运动。"}', 46, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20820, 707, '{"english": "I often play ping-pong or basketball. Sometimes I go swimming.", "chinese": "我经常打乒乓球或者篮球。我有时去游泳。"}', 47, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20821, 707, '{"english": "I never do homework on Sunday nights.", "chinese": "星期日晚上我从来不做作业。"}', 48, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20822, 707, '{"english": "Wow, you''re so busy on weekends!", "chinese": "哇，你周末真忙！"}', 49, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20823, 707, '{"english": "Yes, I never have enough time!", "chinese": "是的，我从来都没有充足的时间！"}', 50, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20824, 707, '{"english": "What do you do on weekends?", "chinese": "你在周末做什么呢？"}', 51, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20825, 707, '{"english": "I don''t have much homework to do on weekends,", "chinese": "我没有太多的家庭作业要做，"}', 52, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20826, 707, '{"english": "but I often do some volunteer work in my community.", "chinese": "但是周末我常常在我的社区做一些志愿者工作。"}', 53, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20827, 707, '{"english": "That''s great.", "chinese": "那真棒。"}', 54, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20828, 707, '{"english": "On Saturday mornings", "chinese": "在星期六上午"}', 55, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20829, 707, '{"english": "On Saturday afternoons", "chinese": "在星期六下午"}', 56, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20830, 707, '{"english": "On Sunday mornings", "chinese": "在星期天上午"}', 57, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20831, 707, '{"english": "On Sunday afternoons", "chinese": "在星期天下午"}', 58, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20832, 707, '{"english": "On Sunday nights", "chinese": "在星期天晚上"}', 59, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20833, 707, '{"english": "always", "chinese": "总是"}', 60, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20834, 707, '{"english": "often", "chinese": "经常"}', 61, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20835, 707, '{"english": "sometimes", "chinese": "有时"}', 62, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20836, 707, '{"english": "never", "chinese": "从不"}', 63, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20837, 707, '{"english": "D. Let''s write.", "chinese": "D. 让我们写一写。"}', 64, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20838, 707, '{"english": "What do you do on weekends?", "chinese": "你在周末做什么？"}', 65, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20839, 707, '{"english": "Write about your weekends using always, often, sometimes and never.", "chinese": "用 always、often、sometimes 和 never 来描述你的周末。"}', 66, '2026-02-05 04:32:35', '2026-02-05 04:32:35');
INSERT INTO "course_content" VALUES (20840, 708, '{"english": "Unit 4", "chinese": "第 4 单元"}', 1, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20841, 708, '{"english": "Free Time", "chinese": "空闲时间"}', 2, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20842, 708, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20843, 708, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 4, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20844, 708, '{"english": "Bill and Ted are talking about hobbies.", "chinese": "比尔和泰德正在谈论爱好。"}', 5, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20845, 708, '{"english": "-What do you usually do in your free time, Bill?", "chinese": "—比尔，你空闲时通常做什么？"}', 6, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20846, 708, '{"english": "-I like reading books. I have many story books.", "chinese": "—我喜欢读书。我有很多故事书。"}', 7, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20847, 708, '{"english": "I also like watching films.", "chinese": "我也喜欢看电影。"}', 8, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20848, 708, '{"english": "My favourite film is Harry Potter.", "chinese": "我最喜欢的电影是《哈利波特》。"}', 9, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20849, 708, '{"english": "What are your hobbies, Ted?  -I like listening to music.", "chinese": "你的爱好是什么，泰德？ —我喜欢听音乐。"}', 10, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20850, 708, '{"english": "I have many music CDs.", "chinese": "我有很多音乐 CD。"}', 11, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20851, 708, '{"english": "I also like making model planes.", "chinese": "我也喜欢做模型飞机。"}', 12, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20852, 708, '{"english": "Look at the plane on my desk.", "chinese": "看我桌上的飞机。"}', 13, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20853, 708, '{"english": "I made it last week.", "chinese": "这是我上周做的。"}', 14, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20854, 708, '{"english": "I am also good at drawing pictures.", "chinese": "我也擅长画画。"}', 15, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20855, 708, '{"english": "I like drawing pictures of elephants. They are cool.", "chinese": "我喜欢画大象。它们很酷。"}', 16, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20856, 708, '{"english": "Do you like drawing pictures? Are you good at drawing?", "chinese": "你喜欢画画吗？你擅长画画吗？"}', 17, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20857, 708, '{"english": "-Well, I like it. But I''m not good at it.", "chinese": "—嗯，我喜欢画画。但我不擅长。"}', 18, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20858, 708, '{"english": "I really like sports.", "chinese": "我真的很喜欢运动。"}', 19, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20859, 708, '{"english": "I often play basketball or ping-pong with my friends after school.", "chinese": "放学后我经常和朋友们打篮球或乒乓球。"}', 20, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20860, 708, '{"english": "I also like swimming. I am good at it.", "chinese": "我也喜欢游泳。我很擅长游泳。"}', 21, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20861, 708, '{"english": "Last summer vacation I went to the beach with my family.", "chinese": "去年暑假我和家人去了海滩。"}', 22, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20862, 708, '{"english": "It was great.  -How often do you go swimming?", "chinese": "太棒了。 —你多久去游一次泳？"}', 23, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20863, 708, '{"english": "-Not very often. But I often play chess.", "chinese": "—不经常。但我经常下棋。"}', 24, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20864, 708, '{"english": "I''m good at playing chess and I''m on a chess team.", "chinese": "我擅长下棋，我在一个象棋队里。"}', 25, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20865, 708, '{"english": "We often have games with other teams.", "chinese": "我们经常和其他队比赛。"}', 26, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20866, 708, '{"english": "Do you want to play chess now?  -Great!", "chinese": "你现在想下棋吗？ —太好了！"}', 27, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20867, 708, '{"english": "I go to a chess club, too. Let''s play.", "chinese": "我也去象棋俱乐部。我们来玩吧。"}', 28, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20868, 708, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 29, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20869, 708, '{"english": "What do Bill and Ted do in their free time?", "chinese": "比尔和泰德在空闲时间做什么？"}', 30, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20870, 708, '{"english": "They ...", "chinese": "他们⋯⋯"}', 31, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20871, 708, '{"english": "1. What do Bill and Ted do in their free time?", "chinese": "1. 比尔和泰德在空闲时间做什么？"}', 32, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20872, 708, '{"english": "2. What are Bill''s and Ted''s hobbies?", "chinese": "2. 比尔和泰德的爱好是什么？"}', 33, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20873, 708, '{"english": "3. What sports are Bill and Ted good at?", "chinese": "3. 比尔和泰德擅长什么运动？"}', 34, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20874, 708, '{"english": "1. What do you do in your free time?", "chinese": "1. 你在空闲时间做什么？"}', 35, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20875, 708, '{"english": "2. What are your hobbies?", "chinese": "2. 你的爱好是什么？"}', 36, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20876, 708, '{"english": "3. What sports are you good at?", "chinese": "3. 你擅长什么运动？"}', 37, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20877, 708, '{"english": "4. How often do you do them?", "chinese": "4. 你多久做一次？"}', 38, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20878, 708, '{"english": "C. Let''s read.", "chinese": "C. 让我们读一读。"}', 39, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20879, 708, '{"english": "In China, Bill went to many clubs.", "chinese": "在中国，比尔去了很多俱乐部。"}', 40, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20880, 708, '{"english": "He went to an English club to study English twice a week.", "chinese": "他一周去两次英语俱乐部来学习英语。"}', 41, '2026-02-05 04:32:36', '2026-02-05 04:32:36');
INSERT INTO "course_content" VALUES (20881, 708, '{"english": "He also went to a swimming club every weekend.", "chinese": "他每个周末也还去游泳俱乐部。"}', 42, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20882, 708, '{"english": "In China there were many other clubs,", "chinese": "在中国有许多其他的俱乐部，"}', 43, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20883, 708, '{"english": "such as art clubs, music clubs and volunteers'' clubs.", "chinese": "如美术俱乐部、音乐俱乐部和志愿者俱乐部。"}', 44, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20884, 708, '{"english": "Sometimes Bill went to these clubs, but not every week.", "chinese": "有时比尔去这些俱乐部，但不是每周都去。"}', 45, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20885, 708, '{"english": "In Canada, Bill goes to different clubs.", "chinese": "在加拿大，比尔去不同的俱乐部。"}', 46, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20886, 708, '{"english": "He goes to a  hockey club twice a week.", "chinese": "他一周去两次曲棍球俱乐部。"}', 47, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20887, 708, '{"english": "He can''t skate very well, but he likes playing hockey.", "chinese": "他滑冰滑得不是很好，但他喜欢打曲棍球。"}', 48, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20888, 708, '{"english": "He also goes to a volunteers'' club once a week.", "chinese": "他每周也还去一个志愿者俱乐部。"}', 49, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20889, 708, '{"english": "They help old people go shopping and do their housework.", "chinese": "他们帮助老年人购物和做家务。"}', 50, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20890, 708, '{"english": "Sometimes, they also help clean the city streets. Bill enjoys helping others.", "chinese": "有时，他们也帮助清洁城市街道。比尔喜欢帮助别人。"}', 51, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20891, 708, '{"english": "He meets many new people and makes many new friends.", "chinese": "他遇到了许多不认识的人，结交了许多新朋友。"}', 52, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20892, 708, '{"english": "Answer the questions. Write down your answers in your notebook.", "chinese": "回答问题。在你的笔记本上写下你的答案。"}', 53, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20893, 708, '{"english": "1. What clubs did Bill go to in China?", "chinese": "1. 比尔在中国参加了哪些俱乐部？"}', 54, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20894, 708, '{"english": "2. What clubs does Bill go to in Canada?", "chinese": "2. 比尔在加拿大参加哪些俱乐部？"}', 55, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20895, 708, '{"english": "3. What does Bill do in the volunteers'' club in Canada?", "chinese": "3. 比尔在加拿大的志愿者俱乐部做什么？"}', 56, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20896, 708, '{"english": "4. Why does Bill like the volunteers'' club?", "chinese": "4. 比尔为什么喜欢志愿者俱乐部？"}', 57, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20897, 708, '{"english": "D. Let''s write.", "chinese": "D. 让我们写一写。"}', 58, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20898, 708, '{"english": "Write about your free time.", "chinese": "写一写你的空闲时间。"}', 59, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20899, 708, '{"english": "The following questions may help you.", "chinese": "以下问题可能会对你有所帮助。"}', 60, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20900, 708, '{"english": "Do you go to any clubs after school?", "chinese": "放学后你去俱乐部吗？"}', 61, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20901, 708, '{"english": "What are they? How often do you go?", "chinese": "它们是什么？你多久去一次？"}', 62, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20902, 708, '{"english": "Do you like them? Why or why not?", "chinese": "你喜欢这些俱乐部吗？为什么喜欢或为什么不喜欢？"}', 63, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20903, 708, '{"english": "What clubs would you like to go to? Why?", "chinese": "你想去什么俱乐部？为什么？"}', 64, '2026-02-05 04:32:37', '2026-02-05 04:32:37');
INSERT INTO "course_content" VALUES (20904, 709, '{"english": "Unit 5", "chinese": "第 5 单元"}', 1, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20905, 709, '{"english": "Nature and Culture", "chinese": "自然与文化"}', 2, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20906, 709, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20907, 709, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 4, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20908, 709, '{"english": "Ted, Tina, Tony and Sherry are talking about their favourite seasons.", "chinese": "泰德、蒂娜、托尼和雪莉正在谈论他们最喜欢的季节。"}', 5, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20909, 709, '{"english": "-What a nice spring day! Do you like spring, Tina?", "chinese": "—多么美好的春日啊！蒂娜，你喜欢春天吗？"}', 6, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20910, 709, '{"english": "-Yes, I do. I like spring because we can do many outdoor activities.", "chinese": "—是的，我喜欢。我喜欢春天，因为我们可以做很多户外活动。"}', 7, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20911, 709, '{"english": "We can go roller skating and go for a picnic.", "chinese": "我们可以去滑旱冰，去野餐。"}', 8, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20912, 709, '{"english": "-Hi, Tony. Is spring your favourite season?  -No, I like summer best.", "chinese": "—嗨，托尼。春天是你最喜欢的季节吗？ —不，我最喜欢夏天。"}', 9, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20913, 709, '{"english": "Because we have lots of rain in summer.", "chinese": "因为夏天雨水很多。"}', 10, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20914, 709, '{"english": "Toronto is beautiful after the rain and I can go swimming in the lake.", "chinese": "雨后的多伦多很美，我可以去湖里游泳。"}', 11, '2026-02-05 04:32:38', '2026-02-05 04:32:38');
INSERT INTO "course_content" VALUES (20915, 709, '{"english": "I also like playing baseball in summer. Do you like summer, Ted?", "chinese": "我也喜欢在夏天打棒球。泰德，你喜欢夏天吗？"}', 12, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20916, 709, '{"english": "-Sorry, I don''t like summer. It''s too hot.", "chinese": "—抱歉，我不喜欢夏天。太热了。"}', 13, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20917, 709, '{"english": "My favourite season is winter. It snows a lot.", "chinese": "我最喜欢的季节是冬天。冬天经常下雪。"}', 14, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20918, 709, '{"english": "So we can make snowmen and go ice-skating.", "chinese": "所以我们可以堆雪人，去滑冰。"}', 15, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20919, 709, '{"english": "We always have a lot of fun.", "chinese": "我们总是玩得很开心。"}', 16, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20920, 709, '{"english": "What about you, Sherry?  -Well, I like autumn best.", "chinese": "你呢，雪莉？ —嗯，我最喜欢秋天。"}', 17, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20921, 709, '{"english": "It''s nice and cool. The trees are red and yellow.", "chinese": "天气凉爽宜人。树木是红色和黄色的。"}', 18, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20922, 709, '{"english": "I like to play basketball in autumn.", "chinese": "我喜欢在秋天打篮球。"}', 19, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20923, 709, '{"english": "We also have Halloween in autumn and Halloween is fun.", "chinese": "我们在秋天也有万圣节，万圣节很有趣。"}', 20, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20924, 709, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 21, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20925, 709, '{"english": "1. What is Ted''s/Tina''s/Tony''s/Sherry''s favourite season?", "chinese": "1. 泰德/蒂娜/托尼/雪莉最喜欢的季节是什么？"}', 22, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20926, 709, '{"english": "2. What''s the weather like in spring/summer/autumn/winter in Toronto?", "chinese": "2. 多伦多的春/夏/秋/冬天气怎么样？"}', 23, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20927, 709, '{"english": "3. What does Ted do in spring/summer/autumn/winter in Toronto?", "chinese": "3. 泰德在多伦多的春/夏/秋/冬做什么？"}', 24, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20928, 709, '{"english": "What''s Tony''s favourite season?", "chinese": "托尼最喜欢的季节是什么？"}', 25, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20929, 709, '{"english": "Summer.", "chinese": "夏天。"}', 26, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20930, 709, '{"english": "What''s the weather like in summer in Toronto?", "chinese": "多伦多夏天的天气怎么样？"}', 27, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20931, 709, '{"english": "It''s hot and rainy.", "chinese": "天气又热又下雨。"}', 28, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20932, 709, '{"english": "What does Tony do in summer in Toronto?", "chinese": "托尼在多伦多的夏天做什么？"}', 29, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20933, 709, '{"english": "He goes swimming and plays baseball.", "chinese": "他去游泳和打棒球。"}', 30, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20934, 709, '{"english": "C. Let''s read.", "chinese": "C. 让我们读一读。"}', 31, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20935, 709, '{"english": "Bill is telling his classmates in Canada about Beijing.", "chinese": "比尔正在给他在加拿大的同学讲有关北京的事。"}', 32, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20936, 709, '{"english": "Beijing has four different seasons.", "chinese": "北京有四个不同的季节。"}', 33, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20937, 709, '{"english": "It is very hot in summer, so I like to go swimming.", "chinese": "在夏天非常热，所以我喜欢去游泳。"}', 34, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20938, 709, '{"english": "I sometimes go to the countryside near Beijing, too.", "chinese": "我有时也去北京附近的农村。"}', 35, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20939, 709, '{"english": "Autumn is very nice. It''s cool, and the sky is blue.", "chinese": "秋天很漂亮。天气凉爽，天空蔚蓝。"}', 36, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20940, 709, '{"english": "I like to play sports with my friends.", "chinese": "我喜欢跟我的朋友们一起运动。"}', 37, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20941, 709, '{"english": "We have Mid-Autumn Festival in this season.", "chinese": "在这个季节我们有中秋节。"}', 38, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20942, 709, '{"english": "We can eat delicious mooncakes then. The autumn in Beijing is quite short.", "chinese": "我们可以吃美味的月饼。北京的秋天很短暂。"}', 39, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20943, 709, '{"english": "Winter is long and cold.", "chinese": "冬天既漫长又寒冷。"}', 40, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20944, 709, '{"english": "I like to make snowmen with my friends.", "chinese": "我喜欢和我的朋友们一起堆雪人。"}', 41, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20945, 709, '{"english": "I also eat a lot of spicy food, like hot pot.", "chinese": "我也吃很多辛辣的食物，比如火锅。"}', 42, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20946, 709, '{"english": "My favourite season is spring.", "chinese": "我最喜欢的季节是春天。"}', 43, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20947, 709, '{"english": "It''s warm, and there are many beautiful flowers to see.", "chinese": "天气很暖和，有许多美丽的花可看。"}', 44, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20948, 709, '{"english": "This season is a good time to fly kites.", "chinese": "这个季节是放风筝的好时机。"}', 45, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20949, 709, '{"english": "I really like to fly kites with my friends in spring.", "chinese": "我真的很喜欢在春天和朋友们一起放风筝。"}', 46, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20950, 709, '{"english": "Fill in the chart.", "chinese": "填表。"}', 47, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20951, 709, '{"english": "season", "chinese": "季节"}', 48, '2026-02-05 04:32:39', '2026-02-05 04:32:39');
INSERT INTO "course_content" VALUES (20952, 710, '{"english": "Unit 6", "chinese": "第 6 单元"}', 1, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20953, 710, '{"english": "Summer Vacation", "chinese": "暑假"}', 2, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20954, 710, '{"english": "Lesson 1", "chinese": "第 1 课"}', 3, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20955, 710, '{"english": "A. Listen and match.", "chinese": "A. 听一听，连一连。"}', 4, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20956, 710, '{"english": "Tina is talking about summer vacation plans with her friends.", "chinese": "蒂娜正在和她的朋友们讨论关于暑假的计划。"}', 5, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20957, 710, '{"english": "—The summer vacation is coming.", "chinese": "——暑假要来了。"}', 6, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20958, 710, '{"english": "I am going to London with Jenny for the summer vacation.", "chinese": "我打算和珍妮一起去伦敦过暑假。"}', 7, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20959, 710, '{"english": "Where are you going, Sherry?", "chinese": "你要去哪里，雪莉？"}', 8, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20960, 710, '{"english": "—I''m going to the USA by car with my family.", "chinese": "——我打算和家人一起开车去美国。"}', 9, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20961, 710, '{"english": "We are going to visit my grandparents there.", "chinese": "我们打算去那里看望我的祖父母。"}', 10, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20962, 710, '{"english": "We are also going to visit the Golden Gate Bridge.", "chinese": "我们还将参观金门桥。"}', 11, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20963, 710, '{"english": "I''m going to take many beautiful photos.  —Great!", "chinese": "我打算拍许多漂亮的照片。 ——太好了！"}', 12, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20964, 710, '{"english": "You can show them to us. What about you, Linda?", "chinese": "你可以给我们看看。你呢，琳达？"}', 13, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20965, 710, '{"english": "—Well, my family are going to Australia by plane.", "chinese": "——嗯，我们全家打算乘飞机去澳大利亚。"}', 14, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20966, 710, '{"english": "My uncle lives there, so we are going to stay with him.", "chinese": "我叔叔住在那里，所以我们要和他待在一起。"}', 15, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20967, 710, '{"english": "We are going to see kangaroos and koalas and we''re going to visit the famous Opera House, too.", "chinese": "我们要去看袋鼠和树袋熊，我们也要去参观著名的歌剧院。"}', 16, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20968, 710, '{"english": "B. Let''s talk.", "chinese": "B. 让我们说一说。"}', 17, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20969, 710, '{"english": "1. Where is Tina/Linda/Sherry going on her summer vacation?", "chinese": "1. 蒂娜/琳达/雪莉暑假将要去哪里？"}', 18, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20970, 710, '{"english": "2. How is Tina/Linda/Sherry going there?", "chinese": "2. 蒂娜/琳达/雪莉怎样去那里？"}', 19, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20971, 710, '{"english": "3. What is Tina/Linda/Sherry going to do there?", "chinese": "3. 蒂娜/琳达/雪莉将在那里做什么？"}', 20, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20972, 710, '{"english": "1. Where are you going on your summer vacation?", "chinese": "1. 你暑假将要去哪里？"}', 21, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20973, 710, '{"english": "2. How are you going there?", "chinese": "2. 你打算怎么去那里？"}', 22, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20974, 710, '{"english": "3. What are you going to do there?", "chinese": "3. 你打算在那里做什么？"}', 23, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20975, 710, '{"english": "C. Let''s read.", "chinese": "C. 让我们读一读。"}', 24, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20976, 710, '{"english": "The summer vacation is coming.", "chinese": "暑假就要来了。"}', 25, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20977, 710, '{"english": "Tina and Jenny are going to London with the school dancing club.", "chinese": "蒂娜、珍妮和学校的舞蹈俱乐部要去伦敦。"}', 26, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20978, 710, '{"english": "They are going there by plane on July 15.", "chinese": "他们于 7 月 15 日乘坐飞机去那里。"}', 27, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20979, 710, '{"english": "They are going to stay there for six days.", "chinese": "他们打算在那儿待六天。"}', 28, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20980, 710, '{"english": "They are also going to dance for some English children", "chinese": "他们也将为一些英国儿童表演舞蹈，"}', 29, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20981, 710, '{"english": "and learn some English dancing.", "chinese": "同时学习一些英国舞蹈。"}', 30, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20982, 710, '{"english": "They want to see Big Ben and visit the British Museum in London.", "chinese": "他们想去看伦敦的大本钟和英国博物馆。"}', 31, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20983, 710, '{"english": "They also want to visit the London Eye and Tower Bridge.", "chinese": "他们还想去参观伦敦眼和伦敦塔桥。"}', 32, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20984, 710, '{"english": "Sherry is going to the USA with her family.", "chinese": "雪莉要和她的家人一起去美国。"}', 33, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20985, 710, '{"english": "They are going there by car on August 2.", "chinese": "他们准备在 8 月 2 日乘小汽车去。"}', 34, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
INSERT INTO "course_content" VALUES (20986, 710, '{"english": "It was ...", "chinese": "它⋯⋯"}', 35, '2026-02-05 04:32:40', '2026-02-05 04:32:40');
